fn_agent_institutional_memory:
declare v_dept text; v_cat text; out text := ''; r record;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if p_agent_key is null then return ''; end if;

  select department into v_dept from org_agents where agent_key = p_agent_key;
  if p_agent_key like 'cat:%' then v_cat := replace(p_agent_key, 'cat:', ''); end if;

  for r in
    select m.kind, m.headline, m.detail, m.outcome, m.money_aed, m.category_slug, m.confidence
    from institutional_memory m
    where (m.visible_to is null
           or array_length(m.visible_to,1) is null
           or 'all' = any(m.visible_to)
           or v_dept = any(m.visible_to)
           or p_agent_key = any(m.visible_to))
      and (m.category_slug is null or m.category_slug = v_cat)
      and coalesce(m.confidence, 1) >= 0.6
    order by coalesce(m.occurred_at, m.created_at) desc, coalesce(m.confidence,0) desc
    limit greatest(coalesce(p_limit,6), 1)
  loop
    out := out || '## lesson (' || coalesce(r.kind,'note') || ')' || E'\n'
        || coalesce(r.headline,'') || E'\n'
        || left(coalesce(r.detail,''), 600)
        || case when r.outcome is not null then E'\n' || 'What changed as a result: ' || left(r.outcome, 300) else '' end
        || case when coalesce(r.money_aed,0) <> 0 then ' (AED ' || r.money_aed || ' at stake)' else '' end
        || E'\n\n';
  end loop;

  return out;
end;

fn_email_sendable:
declare v_e text; v_pat record; v_dom text;
begin
  v_e := lower(btrim(coalesce(p_email,'')));
  if v_e = '' then
    return jsonb_build_object('ok', false, 'reason', 'no address');
  end if;
  if v_e !~ '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+[.][A-Za-z]{2,}$' then
    return jsonb_build_object('ok', false, 'reason', 'not a valid address shape');
  end if;
  if exists (select 1 from email_suppressions s where lower(s.email) = v_e) then
    return jsonb_build_object('ok', false, 'reason', 'suppressed');
  end if;
  v_dom := split_part(v_e, '@', 2);
  if exists (select 1 from email_domain_mx m
              where m.domain = v_dom and m.has_mx = false
                and m.kind in ('nxdomain','no_records')) then
    return jsonb_build_object('ok', false, 'reason', 'domain does not accept mail');
  end if;
  for v_pat in select pattern, reason from email_block_pattern where active loop
    if v_e ~ v_pat.pattern then
      return jsonb_build_object('ok', false, 'reason', v_pat.reason);
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'reason', 'sendable');
end;

fn_protect_app_secret:
declare
  protected text[] := array['inbound_secret','deploy_secret','stripe_secret_key','service_role_key','resend_api_key'];
  k text := coalesce(old.key, new.key);
begin
  if tg_op = 'DELETE' then
    if old.key = any(protected) then
      raise exception 'app_secrets.% is load-bearing for edge-function authentication and cannot be deleted; rotate the value instead', old.key
        using errcode = 'raise_exception';
    end if;
    return old;
  end if;
  if new.key = any(protected) then
    if new.value is null or length(btrim(new.value)) < 24 then
      raise exception 'app_secrets.% must stay a non-empty secret of at least 24 characters (got %); an empty value would make every __secret guard pass',
        new.key, coalesce(length(btrim(new.value)), 0)
        using errcode = 'raise_exception';
    end if;
  end if;
  return new;
end

fn_kpi_scoreboard:
declare r record; v numeric; t numeric;
begin
  for r in
    select k.id, k.agent_key, a.department, k.kpi, k.metric, k.cadence,
           k.serves_goal, k.target_value, k.unit, k.measure_sql
    from employee_kpi k
    left join org_agents a on a.agent_key = k.agent_key
    where k.active
    order by a.department nulls last, k.agent_key, k.id
  loop
    v := null;
    begin
      if r.measure_sql is not null then execute r.measure_sql into v; end if;
    exception when others then v := null;
    end;

    t := null;
    begin
      t := r.target_value::numeric;
    exception when others then t := null;
    end;

    kpi_id := r.id; agent_key := r.agent_key; department := r.department;
    kpi := r.kpi; metric := r.metric; cadence := r.cadence;
    serves_goal := r.serves_goal; target := t; unit := r.unit; actual := v;

    if v is null or t is null then
      attainment := null;
    elsif t = 0 then
      -- A ZERO TARGET IS A TARGET (11 Aug 2026). "Zero defects" is the commonest shape a quality
      -- KPI takes - reveal invoices with no payment record, suppliers gone quiet, categories off
      -- the specification, notifications still unsent - and t = 0 short-circuited into
      -- attainment null, which the verdict below then reported as 'NO TARGET'. Four active,
      -- measured KPIs were being told they had no target when zero IS the target, and the four
      -- were exactly the ones about defects.
      attainment := case when v <= 0 then 100.0 else 0.0 end;
    elsif r.unit = 'percent_max' then
      attainment := round(least(100.0, 100.0 * t / nullif(v,0)), 1);
    else
      attainment := round(100.0 * v / t, 1);
    end if;

    verdict := case
      when v is null then 'NO DATA'
      when attainment is null then 'NO TARGET'
      when attainment >= 100 then 'MET'
      when attainment >= 90 then 'NEAR'
      else 'MISSED' end;

    return next;
  end loop;
end

fn_kpi_review:
declare r record; v_opened int:=0; v_missed int:=0; v_nodata int:=0; v_title text; v_task bigint;
begin
  for r in select * from fn_kpi_scoreboard() loop
    if r.verdict='NO DATA' then v_nodata:=v_nodata+1; continue; end if;
    if r.verdict<>'MISSED' then continue; end if;
    v_missed := v_missed+1;
    v_title := 'KPI missed: '||r.metric||' ('||r.agent_key||')';
    if exists (select 1 from org_tasks where title=v_title and status<>'done') then continue; end if;

    insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
    values (coalesce(r.department,'exec'), v_title,
      'Owner: '||r.agent_key||'. Target '||coalesce(r.target::text,'?')||' '||coalesce(r.unit,'')||
      ', actual '||coalesce(r.actual::text,'?')||' ('||coalesce(r.attainment::text,'?')||'% of target), cadence '||coalesce(r.cadence,'?')||
      '. Serves company goal: '||coalesce(r.serves_goal,'unassigned')||
      '. Diagnose the cause and either close the gap or propose a revised target with evidence.',
      'proposed','advisory', false, 'recommend')
    returning id into v_task;

    perform fn_outcome_open(
      p_actor           => r.agent_key,
      p_decision        => 'Close the gap on: '||r.metric,
      p_subject_type    => 'org_task',
      p_subject_id      => v_task::text,
      p_expected_kpi_id => r.kpi_id,
      p_rationale       => 'KPI missed at '||coalesce(r.attainment::text,'?')||'% of target. Opened automatically by the weekly KPI review.',
      p_direction       => case when r.unit='percent_max' then 'down' else 'up' end,
      p_measure_after   => case when r.cadence='weekly' then interval '14 days' else interval '35 days' end
    );

    v_opened := v_opened+1;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('kpi_review', now(), now(), 'ok',
          jsonb_build_object('missed',v_missed,'opened',v_opened,'no_data',v_nodata),
          'Weekly KPI review: '||v_missed||' missing target, '||v_opened||' task(s) + outcome record(s) opened, '||v_nodata||' with no data.');
  return jsonb_build_object('missed',v_missed,'opened',v_opened,'no_data',v_nodata);
end

fn_outcome_open:
declare v_sql text; v_base numeric; v_metric text; v_dept text; v_id bigint;
begin
  p_actor := coalesce(public.fn_org_agent_resolve(p_actor), p_actor);
  if p_expected_kpi_id is not null then
    select measure_sql, metric into v_sql, v_metric from employee_kpi where id = p_expected_kpi_id;
    begin
      if v_sql is not null then execute v_sql into v_base; end if;
    exception when others then v_base := null; end;
  end if;

  select a.department into v_dept from org_agents a where a.agent_key = p_actor;

  insert into outcome_record (actor, dept_key, subject_type, subject_id, decision, rationale,
                              evidence, expected_kpi_id, expected_metric, expected_direction,
                              baseline_value, measure_after, due_at)
  values (p_actor, v_dept, p_subject_type, p_subject_id, p_decision, p_rationale,
          coalesce(p_evidence,'[]'::jsonb), p_expected_kpi_id, v_metric,
          coalesce(p_direction,'up'), v_base, coalesce(p_measure_after, interval '14 days'),
          now() + coalesce(p_measure_after, interval '14 days'))
  returning id into v_id;
  return v_id;
end

fn_outcome_evaluate:
declare
  r record; v_now numeric; v_delta numeric; v_verdict text; v_lesson text;
  n_improved int := 0; n_worse int := 0; n_flat int := 0; n_unmeasurable int := 0;
  v_claimants int; v_others text; v_lead_id bigint; v_is_lead boolean; v_conf numeric;
begin
  -- How many due outcomes share each reading, and which one speaks for the group. Computed once,
  -- over the same set the loop below walks, so the grouping cannot drift mid-run.
  create temporary table _due_group on commit drop as
  select o.id,
         count(*)      over w as claimants,
         min(o.id)     over w as lead_id,
         string_agg(o.actor, ', ') over (partition by coalesce(k.measure_sql, 'id:'||o.id::text)) as actors
  from outcome_record o
  left join employee_kpi k on k.id = o.expected_kpi_id
  where o.verdict = 'pending' and o.due_at <= now()
  window w as (partition by coalesce(k.measure_sql, 'id:'||o.id::text));

  for r in
    select o.*, k.measure_sql, g.claimants, g.lead_id, g.actors
    from outcome_record o
    left join employee_kpi k on k.id = o.expected_kpi_id
    join _due_group g on g.id = o.id
    where o.verdict = 'pending' and o.due_at <= now()
  loop
    v_now := null;
    begin
      if r.measure_sql is not null then execute r.measure_sql into v_now; end if;
    exception when others then v_now := null; end;

    v_claimants := coalesce(r.claimants, 1);
    v_is_lead   := (r.id = r.lead_id);
    v_others    := r.actors;

    if v_now is null or r.baseline_value is null then
      v_verdict := 'unmeasurable'; v_delta := null; v_conf := 0.6;
      v_lesson := 'Could not be graded: no measurable KPI attached, or no reading in the window. A change nobody can measure cannot be proven to have helped.';
      n_unmeasurable := n_unmeasurable + 1;
    else
      v_delta := v_now - r.baseline_value;
      if r.expected_direction = 'down' then v_delta := -v_delta; end if;
      if v_delta > 0 then
        v_verdict := 'improved';
        n_improved := n_improved + 1;
        if v_claimants > 1 then
          v_conf := 0.4;
          v_lesson := coalesce(r.expected_metric,'metric')||' moved '||r.baseline_value||' to '||v_now
                    ||', but '||v_claimants||' decisions are claiming the same single reading ('||v_others
                    ||'). The metric moved; which decision moved it is NOT established. Not promoted.'
                    ||' To prove a lever here, give these decisions distinct measures or stagger them.';
        else
          v_conf := 0.9;
          v_lesson := r.decision||' -> '||coalesce(r.expected_metric,'metric')||' moved '||r.baseline_value||' to '||v_now||' as predicted. Promote to standard practice.';
        end if;
      elsif v_delta < 0 then
        v_verdict := 'worse';
        n_worse := n_worse + 1;
        if v_claimants > 1 then
          v_conf := 0.4;
          v_lesson := coalesce(r.expected_metric,'metric')||' moved the WRONG WAY, '||r.baseline_value||' to '||v_now
                    ||'. '||v_claimants||' decisions share this reading ('||v_others||'), so the cause is not isolated.'
                    ||' Investigate together before reversing any one of them.';
        else
          v_conf := 0.9;
          v_lesson := r.decision||' -> '||coalesce(r.expected_metric,'metric')||' moved the WRONG WAY, '||r.baseline_value||' to '||v_now||'. Reverse this change and do not repeat it.';
        end if;
      else
        v_verdict := 'no_change'; v_conf := 0.6;
        v_lesson := r.decision||' -> '||coalesce(r.expected_metric,'metric')||' unchanged at '||v_now||'. The action was not the lever. Look elsewhere before spending more here.';
        n_flat := n_flat + 1;
      end if;
    end if;

    update outcome_record
       set observed_value=v_now, observed_at=now(), delta=v_delta, verdict=v_verdict, lesson=v_lesson,
           -- a shared reading never promotes: it has not shown which decision was the lever
           promoted=(v_verdict='improved' and v_claimants = 1),
           rollback_reason=case when v_verdict='worse' then 'Graded worse than baseline on '||to_char(now(),'DD Mon YYYY') else null end,
           closed_at=now()
     where id = r.id;

    perform public.fn_emit('outcome.graded','outcome_record', r.id::text, coalesce(r.actor,'system'),
              jsonb_build_object('verdict', v_verdict, 'metric', r.expected_metric,
                                 'baseline', r.baseline_value, 'observed', v_now, 'delta', v_delta,
                                 'claimants', v_claimants));

    -- One lesson per reading. The co-claimants are named inside it rather than each minting their
    -- own copy, so retrieval sees one observation instead of N agreeing witnesses who are one witness.
    if v_is_lead then
      begin
        insert into institutional_memory (kind, subject_type, subject_id, headline, detail, outcome,
                                          learned_by, confidence, evidence_ref, occurred_at)
        values ('outcome', r.subject_type, r.subject_id,
                left(coalesce(r.expected_metric, r.decision), 120), v_lesson, v_verdict,
                case when v_claimants > 1 then left(v_others, 200) else r.actor end,
                v_conf, 'outcome_record#'||r.id, now());
      exception when others then null; end;
    end if;

    if v_verdict = 'worse' and v_is_lead then
      perform public.fn_emit('rollback.required','outcome_record', r.id::text, coalesce(r.actor,'system'),
                jsonb_build_object('decision', r.decision, 'lesson', v_lesson, 'claimants', v_claimants));
      begin
        insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
        select coalesce(r.dept_key,'exec'), 'ROLL BACK: '||left(r.decision,90),
               'Outcome record #'||r.id||' graded WORSE. '||v_lesson||' Reverse the change, confirm the metric recovers, then close.',
               'proposed','gated', false, 'incident_fix'
        where not exists (select 1 from org_tasks where title='ROLL BACK: '||left(r.decision,90) and status<>'done');
      exception when others then null; end;
    end if;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('outcome_evaluate', now(), now(), 'ok',
          jsonb_build_object('improved',n_improved,'worse',n_worse,'no_change',n_flat,'unmeasurable',n_unmeasurable),
          'Graded due outcomes: '||n_improved||' improved, '||n_worse||' worse (rollback opened), '||n_flat||' no change, '||n_unmeasurable||' unmeasurable.');

  return jsonb_build_object('improved',n_improved,'worse',n_worse,'no_change',n_flat,'unmeasurable',n_unmeasurable);
end

trg_undo_capture:
declare v_actor text;
begin
  v_actor := coalesce(
    nullif(current_setting('app.actor', true), ''),
    nullif(current_setting('request.jwt.claim.email', true), ''),
    session_user);

  if tg_op = 'DELETE' then
    insert into undo_log (table_name, row_id, op, before, actor)
    values (tg_table_name, (to_jsonb(old)->>(tg_argv[0])), 'DELETE', to_jsonb(old), v_actor);
    return old;
  else
    insert into undo_log (table_name, row_id, op, before, actor)
    values (tg_table_name, (to_jsonb(old)->>(tg_argv[0])), 'UPDATE', to_jsonb(old), v_actor);
    return new;
  end if;
exception when others then
  -- never let audit failure block the company's work
  if tg_op = 'DELETE' then return old; else return new; end if;
end

fn_undo:
declare r record; v_pk text; v_sql text;
begin
  select * into r from undo_log where id = p_undo_id;
  if not found then return jsonb_build_object('ok',false,'error','undo_log row not found'); end if;
  if r.reverted then return jsonb_build_object('ok',false,'error','already reverted'); end if;

  select column_name into v_pk from information_schema.columns
   where table_schema='public' and table_name=r.table_name order by ordinal_position limit 1;

  if r.op = 'DELETE' then
    execute format('insert into public.%I select * from jsonb_populate_record(null::public.%I, $1)',
                   r.table_name, r.table_name) using r.before;
  else
    execute format(
      'update public.%I t set (%s) = (select %s from jsonb_populate_record(null::public.%I, $1)) where t.%I::text = $2',
      r.table_name,
      (select string_agg(quote_ident(k), ', ') from jsonb_object_keys(r.before) k),
      (select string_agg(quote_ident(k), ', ') from jsonb_object_keys(r.before) k),
      r.table_name, v_pk)
    using r.before, r.row_id;
  end if;

  update undo_log set reverted = true where id = p_undo_id;

  begin
    insert into os_audit_log (actor, action, entity, entity_id, detail, ok)
    values (coalesce(r.actor,'system'),'undo', r.table_name, r.row_id,
            jsonb_build_object('undo_id',p_undo_id,'op',r.op,'reason',p_reason), true);
  exception when others then null; end;

  return jsonb_build_object('ok',true,'table',r.table_name,'row_id',r.row_id,'op',r.op);
exception when others then
  return jsonb_build_object('ok',false,'error',sqlerrm);
end

fn_audit_prune:
declare n_audit int; n_undo int;
begin
  delete from os_audit_log where action='agent_run' and at < now() - interval '180 days';
  get diagnostics n_audit = row_count;

  delete from undo_log where created_at < now() - interval '90 days';
  get diagnostics n_undo = row_count;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('audit_prune', now(), now(), 'ok',
          jsonb_build_object('audit_pruned',n_audit,'undo_pruned',n_undo),
          'Retention: '||n_audit||' agent-run audit rows and '||n_undo||' undo rows older than their window removed.');

  return jsonb_build_object('audit_pruned',n_audit,'undo_pruned',n_undo);
end

trg_ai_cost_attribute:
declare m record;
begin
  if new.dept_key is null or new.agent_key is null then
    -- 1. the hand-maintained override, unchanged and still first.
    select * into m from ai_cost_fn_map where fn = new.fn;
    if found then
      new.dept_key  := coalesce(new.dept_key,  m.dept_key);
      new.agent_key := coalesce(new.agent_key, m.agent_key);
    end if;

    -- 2. what the ROUTER would have used. fn_ai_route attributes an un-departmented call from
    --    this exact table; until now the log did not, so the ceiling and the ledger disagreed.
    if new.dept_key is null then
      select t.dept_key into new.dept_key
        from fn_task_class t
       where t.fn = new.fn and t.active and t.dept_key is not null
       limit 1;
    end if;

    -- 3. the employee's own department, when the call names one.
    if new.dept_key is null and new.agent_key is not null then
      select a.department into new.dept_key
        from org_agents a
       where a.agent_key = new.agent_key and a.department is not null
       limit 1;
    end if;

    -- 4. the executor that owns this edge function.
    if new.dept_key is null then
      select e.department into new.dept_key
        from org_action_executor e
       where e.target = new.fn and e.department is not null
       limit 1;
    end if;
  end if;

  -- CANONICAL ON THE WAY IN. Whatever source supplied it, an absorbed key is stored as the
  -- department that absorbed it, so the ten budget rows are the only vocabulary the ledger uses.
  if new.dept_key is not null then
    new.dept_key := coalesce(public.fn_dept_canonical(new.dept_key), new.dept_key);
  end if;

  return new;
-- The swallow is deliberate and pre-existing: attribution must never cost a cost-log row. A
-- rising unattributed share is caught by the invariant test rather than by an exception here.
exception when others then return new;
end

fn_ceo_questions:
declare qs text[] := array[]::text[]; n int := 0; q text;
  v_rev numeric; v_sup int; v_inq int; v_worst text; v_cost numeric; v_prev numeric;
begin
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at > now()-interval '30 days';
  select count(*) into v_sup from leads where claimed and approval_status='approved';
  select count(*) into v_inq from inquiries where created_at > now()-interval '30 days';
  select dept_key into v_worst from org_tasks where title like 'KPI missed:%' and status<>'done'
    group by dept_key order by count(*) desc limit 1;
  select coalesce(sum(cost_aed),0) into v_cost from ai_cost_log where occurred_at > now()-interval '7 days';
  select coalesce(sum(cost_aed),0) into v_prev from ai_cost_log where occurred_at between now()-interval '14 days' and now()-interval '7 days';

  if v_rev = 0 then
    qs := array_append(qs, 'Why are we not growing? Revenue is zero over 30 days with '||v_sup||' onboarded suppliers and '||v_inq||' inquiries. What is the single binding constraint, and what would remove it?');
  end if;
  if v_sup = 0 then
    qs := array_append(qs, 'We have 86 fully briefed category experts and no onboarded suppliers. Are we building capability ahead of demand, and is that still the right sequence?');
  end if;
  if v_worst is not null then
    qs := array_append(qs, 'Why is '||v_worst||' missing more targets than any other department this week? Is it capability, capacity, or a target that was never realistic?');
  end if;
  if v_prev > 0 and v_cost > v_prev * 1.25 then
    qs := array_append(qs, 'AI cost rose from '||round(v_prev,2)||' to '||round(v_cost,2)||' AED week on week. What drove it and did it buy anything?');
  end if;
  qs := array_append(qs, 'Which workflow wastes the most employee time, and what would automating it be worth?');
  qs := array_append(qs, 'Which department produced the highest return on its AI spend this month, and what are the others not copying?');
  qs := array_append(qs, 'What are we doing today only because we have always done it?');

  foreach q in array qs loop
    insert into org_tasks (dept_key,title,detail,status,tier,needs_founder,action_class)
    select 'exec','CEO question: '||left(q,80),
           q||E'\n\nAnswer with evidence from company data, not opinion. If the answer implies a change, open it as an initiative with a named metric and a baseline so it can be graded.',
           'proposed','advisory',false,'recommend'
    where not exists (select 1 from org_tasks where title='CEO question: '||left(q,80) and status<>'done');
    if found then n := n + 1; end if;
  end loop;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('ceo_questions',now(),now(),'ok',jsonb_build_object('asked',n),
          'CEO self-questioning: '||n||' strategic question(s) raised from live company data.');
  return jsonb_build_object('asked',n);
end

fn_cron_ran:
declare v boolean;
begin
  select exists (
    select 1 from cron.job j
    join cron.job_run_details d on d.jobid = j.jobid
    where j.jobname = p_jobname
      and d.start_time > now() - p_within
      and d.status = 'succeeded'
  ) into v;
  return coalesce(v,false);
exception when others then
  return true;  -- if the history is unreadable, do not raise a false alarm
end

fn_os_review:
declare r record; v_period text := to_char(now(),'IYYY-"W"IW');
  v_health text; v_find jsonb; v_act int; v_total int := 0; v_red int := 0; v_amber int := 0;
  v_missed int; v_stale int; v_overspend numeric; v_score numeric; v_dept text; v_dept_os text;
  v_emitted int := 0; v_prev text;
begin
  -- BOTH views, joined, and not one or the other. v_os_health projects only a SUBSET of
  -- v_os_scoreboard: it carries open_risks/review_pass_pct/needs_founder_pct/backlog_per_head but
  -- drops kpis, kpis_unmeasurable and departments. Swapping the source outright would have
  -- compiled, deployed, reported success and then failed at call time on r.kpis — the exact class
  -- of bug that only a fixture catches.
  for r in select h.*, s.kpis, s.kpis_unmeasurable, s.departments
             from v_os_health h join v_os_scoreboard s on s.os_key = h.os_key loop
    v_find := '[]'::jsonb; v_act := 0;

    v_missed    := coalesce(r.kpi_gaps, 0);
    v_stale     := coalesce(r.stale_tasks, 0);
    v_overspend := coalesce(r.budget_pct, 0);

    if r.employees = 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','no employees','detail','This operating system has no staff.'));
    end if;
    if r.kpis = 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','no KPIs','detail','This operating system cannot be held to account.'));
    end if;
    if r.kpis_unmeasurable > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','unmeasurable KPIs','detail',r.kpis_unmeasurable||' KPI(s) have no measure.'));
    end if;
    if v_missed > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','KPIs missing target','detail',v_missed||' unclosed KPI gap(s).'));
    end if;
    if v_stale > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','stale work','detail',v_stale||' task(s) open more than 14 days.'));
    end if;
    if coalesce(r.open_risks,0) > 0 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','open risks','detail',r.open_risks||' risk(s) owned inside this OS.'));
    end if;
    if v_overspend >= 95 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','budget halt','detail',v_overspend||'% of monthly AI budget spent.'));
    elsif v_overspend >= 70 then
      v_find := v_find || jsonb_build_array(jsonb_build_object('issue','budget degrade','detail',v_overspend||'% of monthly AI budget spent.'));
    end if;

    v_health := case
      when r.employees = 0 or r.kpis = 0 or v_overspend >= 95 then 'red'
      when jsonb_array_length(v_find) > 0 then 'amber'
      else 'green' end;

    -- The two verdicts are driven by the same inputs on purpose. A green OS scores at least 85 and
    -- a red one at most 60, so "green with a score of 40" is not a state this can produce — a text
    -- verdict and a number that can disagree is worse than either alone.
    v_score := greatest(0, 100
      - (case when r.employees = 0 then 40 else 0 end)
      - (case when r.kpis = 0 then 40 else 0 end)
      - least(20, coalesce(r.kpis_unmeasurable,0) * 4)
      - least(15, v_missed * 3)
      - least(15, v_stale * 2)
      - least(10, coalesce(r.open_risks,0) * 3)
      - (case when v_overspend >= 95 then 25 when v_overspend >= 70 then 10 else 0 end));

    select os.health_score::text into v_prev from operating_system os where os.os_key = r.os_key;

    update operating_system
       set health_score = v_score, last_health_at = now()
     where os_key = r.os_key;

    -- xos-12 / comp-07. Own OS -> a task, which is not a cross-OS call. Anything else -> the bus.
    select coalesce(a.department, null) into v_dept from org_agents a where a.agent_key = r.owner_agent;
    select od.os_key into v_dept_os from os_department od where od.dept_key = v_dept;

    if v_health <> 'green' then
      if v_dept is not null and v_dept_os is not distinct from r.os_key then
        insert into org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
        select v_dept,
               'OS review ['||v_health||']: '||r.name,
               'Owner: '||coalesce(r.owner_agent,'unassigned')||'. Week '||v_period||'. Findings: '||v_find::text
               ||'. Close each finding or bring evidence the standard is wrong.',
               'proposed','advisory', false, 'exec_review'
        where not exists (select 1 from org_tasks t2 where t2.title like 'OS review [%]: '||r.name and t2.status <> 'done');
        get diagnostics v_act = row_count;
      else
        -- The old code wrote this into 'exec' — a different OS — which is exactly what xos-12
        -- forbids. Emitting means leadership receives it through the bus it already subscribes to.
        perform public.fn_emit('os.health_changed', 'operating_system', r.os_key, 'fn_os_review',
                 jsonb_build_object('os_key', r.os_key, 'health', v_health, 'score', v_score,
                                    'period', v_period, 'findings', v_find,
                                    'reason', 'owner agent resolves to no department inside this OS'));
        v_emitted := v_emitted + 1;
      end if;
    end if;

    -- comp-07 / xos-13. os.health_changed was DECLARED by leadership and had never once fired.
    -- Emitted on a real transition only: emitting every week whether or not anything moved is how
    -- an event stream becomes noise nobody subscribes to.
    if v_prev is distinct from v_score::text then
      perform public.fn_emit('os.health_changed', 'operating_system', r.os_key, 'fn_os_review',
               jsonb_build_object('os_key', r.os_key, 'health', v_health, 'score', v_score,
                                  'previous_score', v_prev, 'period', v_period));
      v_emitted := v_emitted + 1;
    end if;

    insert into os_review (os_key, period, owner_agent, health, metrics, findings, actions)
    values (r.os_key, v_period, r.owner_agent, v_health,
            jsonb_build_object('departments',r.departments,'employees',r.employees,'open_tasks',r.open_tasks,
                               'kpis',r.kpis,'kpis_unmeasurable',r.kpis_unmeasurable,
                               'budget_pct',v_overspend,'kpi_gaps',v_missed,'stale_tasks',v_stale,
                               -- the four v_os_health columns that had no reader at all
                               'health_score',v_score,
                               'open_risks',coalesce(r.open_risks,0),
                               'review_pass_pct',r.review_pass_pct,
                               'needs_founder_pct',r.needs_founder_pct,
                               'backlog_per_head',r.backlog_per_head,
                               -- comp-16-capacity. resource_pool is `committed` against
                               -- `capacity`; there is no `used` column, and guessing one would
                               -- have deployed and failed at call time.
                               'capacity_pct',(select round(100.0*sum(rp.committed)/nullif(sum(rp.capacity),0),1)
                                                 from resource_pool rp where rp.os_key = r.os_key)),
            v_find, v_act)
    on conflict (os_key, period) do update
      set health=excluded.health, metrics=excluded.metrics, findings=excluded.findings,
          actions=excluded.actions, created_at=now();

    v_total := v_total + 1;
    if v_health='red' then v_red := v_red+1; elsif v_health='amber' then v_amber := v_amber+1; end if;
  end loop;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('os_review', now(), now(), case when v_red>0 then 'error' else 'ok' end,
          jsonb_build_object('reviewed',v_total,'red',v_red,'amber',v_amber,'green',v_total-v_red-v_amber,'emitted',v_emitted),
          'Operating system review, week '||v_period||': '||(v_total-v_red-v_amber)||' green, '||v_amber||' amber, '||v_red||' red.');

  return jsonb_build_object('reviewed',v_total,'red',v_red,'amber',v_amber,'green',v_total-v_red-v_amber,
                            'events_emitted',v_emitted);
end

fn_os_improve:
declare r record; n int := 0; q text; qs text[];
  v_failed int; v_slow int; v_cost numeric; v_manual int; v_dead int;
begin
  for r in select o.os_key, o.name, o.owner_agent,
                  coalesce((select department from org_agents a where a.agent_key=o.owner_agent),'exec') as dept
           from operating_system o where o.active
  loop
    qs := array[]::text[];

    select count(*) into v_failed from agent_runs ar
      join os_department od on od.os_key = r.os_key
      join org_agents a on a.department = od.dept_key and a.agent_key = ar.agent
     where ar.status='error' and ar.started_at > now()-interval '7 days';

    select count(*) into v_slow from org_tasks t join os_department od on od.dept_key=t.dept_key
     where od.os_key=r.os_key and t.status<>'done' and t.created_at < now()-interval '14 days';

    select coalesce(sum(c.cost_aed),0) into v_cost from ai_cost_log c
      join os_department od on od.dept_key = c.dept_key
     where od.os_key = r.os_key and c.occurred_at > now()-interval '7 days';

    select count(*) into v_manual from org_tasks t join os_department od on od.dept_key=t.dept_key
     where od.os_key=r.os_key and t.needs_founder;

    select count(*) into v_dead from workflow w where w.os_key=r.os_key and not w.active;

    if v_failed > 0 then qs := array_append(qs,'What failed? '||v_failed||' agent run(s) errored this week in '||r.name||'. Root cause each one.'); end if;
    if v_slow   > 0 then qs := array_append(qs,'What slowed us? '||v_slow||' task(s) have been open over 14 days in '||r.name||'. Why has none closed?'); end if;
    if v_cost   > 0 then qs := array_append(qs,'What cost too much? '||r.name||' spent '||round(v_cost,2)||' AED on AI this week. Which calls could a cheaper model have served?'); end if;
    if v_manual > 0 then qs := array_append(qs,'What can be automated? '||v_manual||' task(s) in '||r.name||' still need the founder. Which of those is a rule rather than a judgement?'); end if;
    if v_dead   > 0 then qs := array_append(qs,'What should be deleted? '||v_dead||' inactive workflow(s) remain in '||r.name||'. Retire or revive them.'); end if;

    foreach q in array qs loop
      insert into org_tasks (dept_key,title,detail,status,tier,needs_founder,action_class)
      select r.dept, left(r.name||' improvement: '||q, 120),
             q||E'\n\nOwner: '||coalesce(r.owner_agent,'unassigned')||'. Answer with evidence. If the answer implies a change, open it through fn_outcome_open so it is graded against a baseline.',
             'proposed','advisory',false,'recommend'
      where not exists (select 1 from org_tasks t where t.title = left(r.name||' improvement: '||q,120) and t.status<>'done');
      if found then
        n := n+1;
        perform public.fn_emit('improvement.proposed','operating_system', r.os_key,
                  coalesce(r.owner_agent,'system'), jsonb_build_object('question', q, 'os', r.name));
      end if;
    end loop;
  end loop;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('os_improve',now(),now(),'ok',jsonb_build_object('questions',n),
    'Continuous improvement: '||n||' question(s) raised across the ten operating systems.');
  return jsonb_build_object('questions',n);
end

fn_challenge:
declare
  h record; v_id bigint; v_stance text := 'support'; v_conf numeric := 0.5;
  v_reason text := ''; v_alts jsonb := '[]'::jsonb; v_evidence jsonb := '[]'::jsonb;
  v_rank int; v_principle text; v_weight int := 0;
  v_prior record; v_supply int; v_rev numeric;
begin
  for h in select * from challenge_heuristic where active and p_proposal ~* pattern order by rank_touched limit 3
  loop
    -- a rank-1 conflict is severe on its own; lower ranks accumulate
    v_weight := v_weight + case h.rank_touched when 1 then 3 when 2 then 2 else 1 end;
    if v_rank is null or h.rank_touched < v_rank then v_rank := h.rank_touched; v_principle := h.principle; end if;
    v_reason := v_reason || case when v_reason='' then '' else ' ' end || h.concern;
    if h.alternative is not null then v_alts := v_alts || jsonb_build_array(h.alternative); end if;
  end loop;

  for v_prior in
    select headline, detail, outcome from institutional_memory
     where outcome in ('worse','improved')
       and p_proposal ~* coalesce(substring(headline from '\w+'),'zzzz')
     order by created_at desc limit 3
  loop
    v_evidence := v_evidence || jsonb_build_array(jsonb_build_object(
      'type','prior_outcome','verdict',v_prior.outcome,'lesson',left(v_prior.detail,240)));
    if v_prior.outcome='worse' then v_weight := v_weight + 3; end if;
  end loop;

  select count(*) into v_supply from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev
    from transactions where revealed_at > now()-interval '30 days';
  v_evidence := v_evidence || jsonb_build_array(jsonb_build_object(
    'type','current_state','onboarded_suppliers',v_supply,'revenue_30d_aed',v_rev,
    'note', case when v_supply=0
      then 'The marketplace has no onboarded supply, so any demand-side or pricing change cannot be validated against real behaviour yet.'
      else 'Supply exists; effects are measurable.' end));

  if v_supply=0 and p_proposal ~* '(fee|price|commission|campaign|customer|demand)' then
    v_weight := v_weight + 1;
    v_reason := v_reason || ' There is also no onboarded supply to measure the effect against, so the change would be unfalsifiable at the moment it is made.';
  end if;

  if v_weight >= 3 then v_stance := 'recommend_against'; v_conf := least(0.95, 0.60 + v_weight*0.05);
  elsif v_weight >= 1 then v_stance := 'concern'; v_conf := 0.65;
  else v_stance := 'support'; v_conf := 0.6;
       v_reason := 'No conflict with the priority hierarchy, no contrary prior outcome on record, and current state does not argue against it.';
  end if;

  -- A REFUSAL WITH NO REASON IS NOT A CHALLENGE. v_weight can cross the recommend_against
  -- threshold from institutional_memory alone, and only the heuristic loop above writes v_reason —
  -- so a proposal with two prior attempts that ended worse and no matching heuristic was recorded
  -- as recommend_against with an empty reasoning. Write the basis that actually drove the weight.
  if v_reason = '' and v_stance <> 'support' then
    v_reason := 'No principle in the priority hierarchy is touched by this, but '
      ||(select count(*) from jsonb_array_elements(v_evidence) e
          where e->>'type'='prior_outcome' and e->>'verdict'='worse')
      ||' prior attempt(s) on record ended worse: '
      ||coalesce((select string_agg(left(e->>'lesson',200), ' | ')
                    from jsonb_array_elements(v_evidence) e
                   where e->>'type'='prior_outcome' and e->>'verdict'='worse'),
                 'the outcome was recorded without a lesson')||'.';
  end if;

  if v_alts='[]'::jsonb and v_stance<>'support' then
    v_alts := jsonb_build_array('Run it as a bounded test with a named metric and a captured baseline, so it can be graded and reversed.');
  end if;

  insert into challenge_record (proposal,proposed_by,challenged_by,stance,confidence,reasoning,
                                violates_rank,violates_principle,evidence,alternatives)
  values (p_proposal,p_proposed_by,p_challenger,v_stance,v_conf,v_reason,v_rank,v_principle,v_evidence,v_alts)
  returning id into v_id;

  return jsonb_build_object('id',v_id,'stance',v_stance,'confidence',v_conf,
    'conflicts_with', case when v_principle is null then null else 'Rank '||v_rank||' — '||v_principle end,
    'reasoning',v_reason,'evidence',v_evidence,'alternatives',v_alts);
end

fn_company_reflect:
declare a jsonb; n_concern int := 0; n_act int := 0;
  v_learned int; v_errors int; v_wrong int; v_dept text; v_improved text;
  v_stale int; v_missed int; v_comp int; v_worst text; v_bus text;
begin
  select count(*) into v_learned from institutional_memory where created_at > now()-interval '24 hours';
  select count(*) into v_errors  from agent_runs where status='error' and started_at > now()-interval '24 hours';
  select count(*) into v_wrong   from outcome_record where verdict='worse' and closed_at > now()-interval '24 hours';
  select dept_key into v_dept from org_tasks where status<>'done' group by dept_key order by count(*) desc limit 1;
  select string_agg(actor, ', ') into v_improved from (
    select distinct actor from outcome_record where verdict='improved' and closed_at > now()-interval '7 days' limit 3) x;
  select count(*) into v_stale from agent_knowledge where validation_status in ('stale','quarantined');
  select count(*) into v_missed from v_supply_gap where status='READY - not yet invited';
  select count(*) into v_comp from competitor;
  select name into v_worst from v_supply_gap where status like 'NO POOL%' limit 1;

  -- xos-15. The company asks itself whether its own nervous system is carrying traffic. A
  -- subscribed event type that has never fired is a promise the company is not keeping.
  select coalesce(string_agg(event_type || ' ' || state, ', ' order by event_type),
                  'every subscribed event type is carrying traffic')
    into v_bus from v_event_backbone where state <> 'LIVE';

  a := jsonb_build_object(
    'what_did_i_learn', v_learned||' lesson(s) entered institutional memory in the last 24 hours.',
    'what_mistakes_did_i_make', v_errors||' agent run(s) errored.',
    'which_decisions_were_wrong', v_wrong||' graded improvement(s) made things worse and were flagged for reversal.',
    'which_departments_are_struggling', coalesce('Heaviest open backlog: '||v_dept,'No department is carrying an unusual backlog.'),
    'which_employees_improved', coalesce('Improvements that worked came from: '||v_improved,'No graded improvement has closed successfully yet.'),
    'which_knowledge_became_outdated', v_stale||' knowledge item(s) are stale or quarantined.',
    'which_opportunities_did_i_miss', v_missed||' category/categories have a viable supplier pool and no invitations sent.',
    'which_competitor_became_stronger', v_comp||' competitor(s) tracked but 0 market signals captured, so this cannot be answered honestly yet.',
    'is_my_nervous_system_carrying_traffic', 'Event types subscribed but not live: '||v_bus,
    'how_can_i_be_better_tomorrow', coalesce('Close the supply gap starting with '||v_worst,'Close the open KPI gaps before taking on new work.'));

  if v_errors > 10 then n_concern := n_concern + 1; end if;
  if v_wrong  > 0  then n_concern := n_concern + 1; end if;
  if v_stale  > 50 then n_concern := n_concern + 1; end if;

  -- xos-12. This used to be `insert into org_tasks ... 'procurement'` — the Leadership OS writing
  -- a command straight into the Marketplace OS's queue. It emits now, and procurement's
  -- supply.gap subscription turns it into exactly the same one task, through the bus, with an
  -- audit trail the direct write never had. Deduped on the same 24h window so a nightly
  -- reflection cannot emit the same gap twice.
  if v_missed > 0 then
    if not exists (select 1 from company_event
                    where event_type='supply.gap' and occurred_at > now()-interval '20 hours') then
      perform public.fn_emit('supply.gap', 'category', 'ready_uninvited', 'ceo',
                jsonb_build_object('categories_ready', v_missed,
                                   'detail', v_missed||' category(ies) hold a viable supplier pool with '
                                          || 'no invitations sent. Queue them, or record why not.'));
      n_act := n_act + 1;
    end if;
  end if;

  insert into company_reflection (reflected_on,answers,concerns,actions)
  values (current_date,a,n_concern,n_act)
  on conflict (reflected_on) do update set answers=excluded.answers, concerns=excluded.concerns, actions=excluded.actions;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('company_reflect',now(),now(),'ok',jsonb_build_object('concerns',n_concern,'actions',n_act),
    'Nightly self-reflection: '||n_concern||' concern(s), '||n_act||' action(s) opened. Nobody asked for this.');
  return jsonb_build_object('concerns',n_concern,'actions',n_act,'answers',a);
end

fn_board_review:
declare adv record; ch jsonb; v_rec text; v_conf numeric; v_supply int; v_rev numeric;
  n_pro int:=0; n_cond int:=0; n_against int:=0; v_out jsonb := '[]'::jsonb;
begin
  ch := fn_challenge(p_subject,'board','board');
  select count(*) into v_supply from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at>now()-interval '30 days';

  for adv in select * from board_advisor where active order by advisor_key loop
    -- each advisor reasons through its own lens against the same facts
    if adv.advisor_key='risk' and (ch->>'stance')='recommend_against' then
      v_rec:='do_not_proceed'; v_conf:=0.85;
    elsif adv.advisor_key='economist' and v_rev=0 then
      v_rec:='proceed_with_conditions'; v_conf:=0.7;
    elsif adv.advisor_key in ('customer','supplier') and v_supply=0 then
      v_rec:='abstain'; v_conf:=0.5;
    elsif (ch->>'stance')='recommend_against' then
      v_rec:='do_not_proceed'; v_conf:=0.75;
    elsif (ch->>'stance')='concern' then
      v_rec:='proceed_with_conditions'; v_conf:=0.65;
    else
      v_rec:='proceed'; v_conf:=0.6;
    end if;

    insert into board_opinion (subject,subject_ref,advisor_key,recommendation,rationale,confidence)
    values (p_subject,p_subject_ref,adv.advisor_key,v_rec,
      adv.name||' ('||adv.lens||') asks: '||adv.asks||' — '||
      case v_rec
        when 'do_not_proceed' then 'On the evidence available this fails that test.'
        when 'proceed_with_conditions' then 'Proceed only with a named metric, a captured baseline and a reversal path.'
        when 'abstain' then 'There is no data on this side of the marketplace yet; an opinion would be invention.'
        else 'Nothing in this lens argues against it.' end, v_conf);

    if v_rec='proceed' then n_pro:=n_pro+1;
    elsif v_rec='proceed_with_conditions' then n_cond:=n_cond+1;
    elsif v_rec='do_not_proceed' then n_against:=n_against+1; end if;

    v_out := v_out || jsonb_build_array(jsonb_build_object('advisor',adv.name,'lens',adv.lens,'recommendation',v_rec,'confidence',v_conf));
  end loop;

  return jsonb_build_object('subject',p_subject,'proceed',n_pro,'with_conditions',n_cond,
    'against',n_against,'abstained',(select count(*) from board_advisor where active)-n_pro-n_cond-n_against,
    'board_verdict', case when n_against>0 then 'DO NOT PROCEED' when n_cond>0 then 'PROCEED WITH CONDITIONS' else 'PROCEED' end,
    'challenge_stance', ch->>'stance', 'opinions', v_out);
end

fn_company_indices:
declare
  d_auto numeric; d_know numeric; d_dec numeric; d_fin numeric; d_cust numeric;
  d_supp numeric; d_sec numeric; d_res numeric; d_inno numeric; d_strat numeric; v_mat numeric;
  e_vel numeric; e_backlog numeric; e_collab numeric; e_knowcreate numeric; e_autorate numeric; v_energy numeric;
  m_quality numeric; m_speed numeric; m_completion numeric; m_fraud numeric; m_conf numeric; v_mh numeric;
  v_kpis int; v_gaps int;
begin
  select coalesce(100 - round(100.0*count(*) filter (where needs_founder)/nullif(count(*),0),1),100)
    into d_auto from org_tasks where status<>'done';
  select coalesce(round(100.0*count(*) filter (where validation_status not in ('unvalidated','unreviewed'))/nullif(count(*),0),1),0)
    into d_know from agent_knowledge;
  select coalesce(round(100.0*count(*) filter (where verdict='improved')
           /nullif(count(*) filter (where verdict in ('improved','no_change','worse')),0),1),50)
    into d_dec from outcome_record;
  select case when coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) > 0 then 60 else 10 end
    into d_fin from transactions where revealed_at > now()-interval '90 days';
  select case when count(*) > 0 then 50 else 10 end into d_cust from customers;
  select least(100, round(100.0*(select count(*) from v_supply_gap where approved>=10)/86.0,1)) into d_supp;
  select coalesce(round(100.0*count(*) filter (where ok)/nullif(count(*),0),1),50)
    into d_sec from health_checks where check_kind='http' and created_at > now()-interval '7 days';
  select round(100.0*count(*) filter (where last_tested is not null)/nullif(count(*),0),1)
    into d_res from continuity_plan;
  select least(100,(select count(*) from evolution_proposal)*5) into d_inno;
  select count(*) into v_kpis from employee_kpi where active;
  select count(*) into v_gaps from org_tasks where title like 'KPI missed:%' and status<>'done';
  d_strat := greatest(0, round(100.0 - 100.0*v_gaps/nullif(v_kpis,0), 1));

  v_mat := round((d_auto+d_know+d_dec+d_fin+d_cust+d_supp+d_sec+d_res+d_inno+d_strat)/10.0,1);
  insert into company_index (measured_on,index_name,dimensions,score,band)
  values (current_date,'company_maturity',
    jsonb_build_object('automation',d_auto,'knowledge_quality',d_know,'decision_accuracy',d_dec,
      'financial_health',d_fin,'customer_trust',d_cust,'supplier_ecosystem',d_supp,'security',d_sec,
      'operational_resilience',d_res,'innovation',d_inno,'strategic_execution',d_strat), v_mat,
    case when v_mat>=80 then 'mature' when v_mat>=60 then 'developing' when v_mat>=40 then 'early' else 'nascent' end)
  on conflict (measured_on,index_name) do update set dimensions=excluded.dimensions, score=excluded.score, band=excluded.band;

  select count(*) into e_vel from decision_log where created_at > now()-interval '7 days';
  select coalesce(round(100.0 - 100.0*count(*) filter (where created_at < now()-interval '14 days')/nullif(count(*),0),1),100)
    into e_backlog from org_tasks where status<>'done';
  select coalesce(round(100.0*count(*) filter (where decision='approve')/nullif(count(*),0),1),50)
    into e_collab from review_chain where created_at > now()-interval '30 days';
  select least(100,count(*)) into e_knowcreate from agent_knowledge where updated_at > now()-interval '7 days';
  e_autorate := d_auto;
  v_energy := round((least(100,e_vel)+e_backlog+e_collab+e_knowcreate+e_autorate)/5.0,1);
  insert into company_index (measured_on,index_name,dimensions,score,band)
  values (current_date,'organizational_energy',
    jsonb_build_object('decision_velocity_7d',e_vel,'backlog_freshness',e_backlog,
      'collaboration_efficiency',e_collab,'knowledge_creation_7d',e_knowcreate,'automation_rate',e_autorate),
    v_energy, case when v_energy>=75 then 'high' when v_energy>=50 then 'steady' else 'slowing' end)
  on conflict (measured_on,index_name) do update set dimensions=excluded.dimensions, score=excluded.score, band=excluded.band;

  select coalesce(round(avg(reliability),1),0) into m_quality from supplier_score where reliability is not null;
  select coalesce(round(100.0*count(*) filter (where sent_at is not null and sent_at-created_at < interval '24 hours')
           /nullif(count(*),0),1),0) into m_speed from notifications where created_at > now()-interval '30 days';
  select coalesce(round(100.0*count(*) filter (where exists(select 1 from quotes q where q.inquiry_id=i.id))
           /nullif(count(*),0),1),0) into m_completion from inquiries i where i.created_at > now()-interval '30 days';
  select coalesce(100 - least(100,count(*)*5),100) into m_fraud from fraud_flags;
  select coalesce(round(avg(confidence)*100,1),50) into m_conf from decision_log where confidence is not null;
  v_mh := round((m_quality+m_speed+coalesce(m_completion,0)+m_fraud+m_conf)/5.0,1);
  insert into company_index (measured_on,index_name,dimensions,score,band)
  values (current_date,'marketplace_health',
    jsonb_build_object('supplier_quality',m_quality,'quote_speed',m_speed,'rfq_completion',m_completion,
      'fraud_clean',m_fraud,'ai_confidence',m_conf), v_mh,
    case when v_mh>=75 then 'healthy' when v_mh>=50 then 'fragile' else 'unhealthy' end)
  on conflict (measured_on,index_name) do update set dimensions=excluded.dimensions, score=excluded.score, band=excluded.band;

  insert into agent_runs (agent,started_at,finished_at,status,counts,note)
  values ('company_indices',now(),now(),'ok',
    jsonb_build_object('maturity',v_mat,'energy',v_energy,'marketplace_health',v_mh),
    'Company indices: maturity '||v_mat||', energy '||v_energy||', marketplace health '||v_mh||'.');
  return jsonb_build_object('maturity',v_mat,'energy',v_energy,'marketplace_health',v_mh);
end

fn_reallocate:
declare
  r record;
  n int := 0;
  v_pool numeric := 0;
  v_recipients int := 0;
  v_idle numeric := 0;
  v_slots int := 0;
  v_i int := 0;
  v_take numeric;
  v_left numeric;
begin
  -- policy: never move more than 20% of a department's budget in one cycle, never below 200 AED,
  -- only FROM departments under 30% utilisation, only TO departments over 85%.

  -- Recipients first. A release that cannot be granted is a cut.
  select count(*) into v_recipients
    from department_budget
   where round(100.0 * spent_aed / nullif(monthly_aed, 0), 1) > 85;

  if v_recipients = 0 then
    select coalesce(sum(round(monthly_aed * 0.2, 0)), 0) into v_idle
      from department_budget
     where monthly_aed > 200
       and coalesce(round(100.0 * spent_aed / nullif(monthly_aed, 0), 1), 0) < 30
       and monthly_aed * 0.2 >= 50;

    insert into agent_runs (agent, started_at, finished_at, status, counts, note)
    values ('reallocate', now(), now(), 'ok',
            jsonb_build_object('changes', 0, 'released_aed', 0, 'idle_aed_available', v_idle,
                               'recipients', 0),
            'Resource reallocation: no change. ' || v_idle || ' AED could be released from idle '
            || 'departments, but no department is over 85% utilisation, so there is nowhere to '
            || 'move it. Budgets left intact rather than cut.');
    return jsonb_build_object('changes', 0, 'released_aed', 0, 'idle_aed_available', v_idle,
                              'recipients', 0);
  end if;

  for r in
    select b.dept_key, b.monthly_aed, b.spent_aed,
           round(100.0 * b.spent_aed / nullif(b.monthly_aed, 0), 1) as util
      from department_budget b
     where b.monthly_aed > 200
  loop
    if r.util < 30 and r.monthly_aed * 0.2 >= 50 then
      v_pool := v_pool + round(r.monthly_aed * 0.2, 0);
      insert into allocation_change (resource, subject, from_value, to_value, reason, policy)
      values ('ai_budget_aed', r.dept_key, r.monthly_aed,
              r.monthly_aed - round(r.monthly_aed * 0.2, 0),
              r.dept_key || ' used only ' || coalesce(r.util, 0)
              || '% of its budget. Releasing 20% to the pool.',
              'release: utilisation under 30%, cap 20% per cycle, floor 200 AED');
      update department_budget
         set monthly_aed = monthly_aed - round(monthly_aed * 0.2, 0), updated_at = now()
       where dept_key = r.dept_key;
      n := n + 1;
    end if;
  end loop;

  -- A released department was under 30% and can rise by at most a quarter of that, so it can never
  -- re-enter the grant loop's >85% set. The two loops cannot overlap.
  v_left := v_pool;
  v_slots := least(v_recipients, 3);
  if v_pool > 0 then
    for r in
      select b.dept_key, b.monthly_aed,
             round(100.0 * b.spent_aed / nullif(b.monthly_aed, 0), 1) util
        from department_budget b
       where round(100.0 * b.spent_aed / nullif(b.monthly_aed, 0), 1) > 85
       order by util desc
       limit 3
    loop
      v_i := v_i + 1;
      -- the last recipient takes the remainder, so the pool is never left part-granted
      v_take := case when v_i = v_slots then v_left else round(v_pool / v_slots, 0) end;
      exit when v_take <= 0;
      insert into allocation_change (resource, subject, from_value, to_value, reason, policy)
      values ('ai_budget_aed', r.dept_key, r.monthly_aed, r.monthly_aed + v_take,
              r.dept_key || ' is at ' || r.util || '% utilisation. Receiving ' || v_take
              || ' AED of released budget.',
              'grant: utilisation over 85%, released pool split across at most 3 departments');
      update department_budget set monthly_aed = monthly_aed + v_take, updated_at = now()
       where dept_key = r.dept_key;
      v_left := v_left - v_take;
      n := n + 1;
    end loop;
  end if;

  insert into agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('reallocate', now(), now(), 'ok',
          jsonb_build_object('changes', n, 'released_aed', v_pool, 'granted_aed', v_pool - v_left,
                             'recipients', v_recipients),
          'Resource reallocation: ' || n || ' change(s), ' || (v_pool - v_left) || ' of ' || v_pool
          || ' AED released from idle departments and granted to ' || v_slots
          || ' saturated one(s). Every change is logged and reversible.');
  return jsonb_build_object('changes', n, 'released_aed', v_pool, 'granted_aed', v_pool - v_left,
                            'recipients', v_recipients);
end

fn_what_if:
declare v_sup int; v_rev numeric; v_cost numeric; v_conv numeric; v_pool int;
  v_impact jsonb; v_conf numeric; v_id bigint;
  v_d_rev numeric; v_d_leads numeric; v_d_profit numeric;
begin
  select count(*) into v_sup from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at>now()-interval '30 days';
  select coalesce(sum(cost_aed),0) into v_cost from ai_cost_log where occurred_at>now()-interval '30 days';
  select coalesce(sum(sendable),0) into v_pool from v_supply_gap;
  v_conv := 0.05;

  if p_question ~* 'reveal fee|reduce.*fee|lower.*fee' then
    v_impact := jsonb_build_object('revenue_per_reveal','down by the discount percentage',
      'reveal_volume','unknown - no reveals have occurred, so elasticity is unmeasured',
      'net_revenue','indeterminate',
      'honest_answer','This cannot be simulated. Zero reveals have happened, so there is no price-response curve to extrapolate from. Any number would be invented.');
    v_conf := 0.15;
    -- All three stay NULL on purpose. The branch's own text says the question cannot be simulated,
    -- and a projection of 0 would contradict it.
    v_d_rev := null; v_d_leads := null; v_d_profit := null;

  elsif p_question ~* 'model price|openrouter|ai cost.*double|llm cost' then
    v_impact := jsonb_build_object('current_monthly_ai_cost_aed',round(v_cost,2),'if_doubled_aed',round(v_cost*2,2),
      'share_of_total_budget', round(100.0*v_cost*2/nullif((select sum(monthly_aed) from department_budget),0),1)||'%',
      'mitigation','Model policy already routes by task class. Prompt-cache reads are '
        ||coalesce((select round(100.0*sum(cached_in_tokens)/nullif(sum(prompt_tokens),0),1)::text
                      from ai_cost_log where occurred_at > now() - interval '30 days'),'0')
        ||'% of prompt tokens over 30 days ('
        ||coalesce((select sum(cached_in_tokens)::text from ai_cost_log
                     where occurred_at > now() - interval '30 days'),'0')
        ||' read against '
        ||coalesce((select sum(cache_write_tokens)::text from ai_cost_log
                     where occurred_at > now() - interval '30 days'),'0')
        ||' written at a 1.25x premium), so caching pays only above roughly 22% and is measured here rather than assumed.');
    v_conf := 0.8;
    -- Doubling the AI bill moves cost, not sales: the extra spend lands on profit one-for-one and
    -- the top line is untouched, so revenue is NULL rather than 0 (unmodelled, not unchanged).
    v_d_rev := null; v_d_leads := null; v_d_profit := -round(v_cost,2);

  elsif p_question ~* 'invite|supplier.*onboard|scale.*supplier' then
    v_impact := jsonb_build_object('sendable_pool',v_pool,'expected_approved_at_5pct',round(v_pool*v_conv),
      'target',860,'shortfall',greatest(0,860-round(v_pool*v_conv)),
      'note','Assumes a 5% invite-to-approved conversion, which is an assumption not an observation - no invite has converted yet.');
    v_conf := 0.45;
    -- Supply-side leads are the only dimension this branch models, and it says out loud that the
    -- 5% is an assumption. Revenue would need a conversion rate nobody has observed.
    v_d_rev := null; v_d_leads := round(v_pool*v_conv); v_d_profit := null;

  elsif p_question ~* 'saudi|expand|new market' then
    v_impact := jsonb_build_object('home_market_readiness',(select count(*) from v_supply_gap where approved>=10)||' of 86 categories at target',
      'assessment','Expanding before the home market has any onboarded supply spreads a thin pool thinner and the category knowledge is UAE-specific.');
    v_conf := 0.7;
    v_d_rev := null; v_d_leads := null; v_d_profit := null;
  else
    v_impact := jsonb_build_object('assessment','No model exists for this question yet. Add a scenario to scenario_library so it can be simulated rather than guessed.');
    v_conf := 0.2;
    v_d_rev := null; v_d_leads := null; v_d_profit := null;
  end if;

  -- THE THREE DIMENSIONS THE FOUNDER ASKED FOR, ALWAYS NAMED. Branch-shaped keys like
  -- 'net_revenue' and 'if_doubled_aed' answer the question but cannot be read uniformly across
  -- simulations, so a reader had to know which branch ran before it knew what it was looking at.
  v_impact := v_impact || jsonb_build_object(
    'projected_revenue_delta_aed', v_d_rev,
    'projected_leads_delta',       v_d_leads,
    'projected_profit_delta_aed',  v_d_profit,
    'delta_note', 'A null delta means this scenario does not model that dimension. It does not mean the delta is zero.');

  insert into simulations (scenario, result)
  values (jsonb_build_object('question',p_question,'change',p_change,'confidence',v_conf),
          -- The confidence belongs in the projection the caller reads, not only beside the question
          -- it was asked. coalesce guards the branch that builds it by hand already.
          v_impact || jsonb_build_object('confidence', coalesce((v_impact->>'confidence')::numeric, v_conf)))
  returning id into v_id;

  -- THE SIMULATION LEAVES SOMETHING TO APPROVE. Only when it actually modelled the question:
  -- v_conf is the simulator's own score for the branch it took, and below 0.5 are exactly the
  -- branches whose text says they are guesses ("No model exists for this question yet",
  -- "an assumption not an observation"). Those produce a projection to read and no action to take.
  if v_conf >= 0.5 then
    insert into agent_actions(agent, kind, status, risk, title, recommendation, detail,
                              target_table, target_id, confidence, evidence)
    values ('strategy_director', 'simulation_apply', 'pending', 'medium',
            left('Act on the simulation: ' || p_question, 200),
            coalesce(v_impact->>'assessment',
                     'The simulation returned a projection; open it to see the modelled figures.')
              || ' Approving this accepts the modelled change; the projection and its basis are on '
              || 'simulation #' || v_id || '.',
            jsonb_build_object('simulation_id', v_id, 'question', p_question,
                               'change', p_change, 'projection', v_impact),
            'simulations', v_id::text, v_conf,
            -- The real basis, not the generic stamped one: this rests on the simulation and the
            -- figures it computed, which are the two things a reader would want to check.
            jsonb_build_object('basis', 'simulation #' || v_id || ' of "' || p_question || '"',
                               'simulation_id', v_id, 'confidence', v_conf, 'projection', v_impact));
  end if;

  return jsonb_build_object('id',v_id,'question',p_question,'projection',v_impact,'confidence',v_conf,
    'basis', jsonb_build_object('approved_suppliers',v_sup,'revenue_30d',v_rev,'ai_cost_30d',round(v_cost,2),'sendable_pool',v_pool));
end

fn_edge_health_scan:
declare
  r            record;
  v_beat       timestamptz;
  v_silent     numeric;
  v_verdict    text;
  v_note       text;
  v_open       boolean;
  v_title      text;
  v_platform   jsonb;
begin
  select coalesce(jsonb_agg(x), '[]'::jsonb) into v_platform
  from (
    select coalesce(headers->>'sb-error-code', 'status_' || coalesce(status_code::text,'null')) as code,
           count(*) as n
    from net._http_response
    where created > timezone('utc', now()) - interval '30 minutes'
      and (status_code is null or status_code < 200 or status_code >= 300)
    group by 1 order by 2 desc limit 10
  ) x;

  for r in select * from edge_expectation where active order by fn_key loop
    v_beat := null; v_note := null; v_open := false;
    begin
      execute r.heartbeat_sql into v_beat;
    exception when others then
      v_verdict := 'PROBE FAILED';
      v_note := 'heartbeat_sql could not be evaluated: ' || left(sqlerrm, 200);
    end;

    if v_note is null then
      v_silent := case when v_beat is null then null
                       else round(extract(epoch from (now() - v_beat)) / 60.0, 1) end;
      v_verdict := case
        when v_beat is null then 'STALE'
        when v_silent > r.max_silence_minutes then 'STALE'
        else 'ALIVE' end;
    else
      v_silent := null;
    end if;

    insert into edge_health_probe (fn_key, last_beat_at, silent_minutes, verdict, note)
    values (r.fn_key, v_beat, v_silent, v_verdict, v_note);

    if v_verdict <> 'ALIVE' then
      v_title := 'Silent failure: ' || r.fn_key || ' has produced no effect for ' ||
                 coalesce(v_silent::text || ' minutes', 'an unknown period') ||
                 ' (threshold ' || r.max_silence_minutes || ')';

      if not exists (
        select 1 from os_incidents
        where status = 'open' and detail->>'fn_key' = r.fn_key
      ) then
        insert into os_incidents (title, kind, severity, status, detail, opened_by)
        values (
          left(v_title, 300), 'silent_failure', r.severity, 'open',
          jsonb_build_object(
            'fn_key', r.fn_key,
            'cron_jobname', r.cron_jobname,
            'purpose', r.purpose,
            'blast_radius', r.blast_radius,
            'last_beat_at', v_beat,
            'silent_minutes', v_silent,
            'threshold_minutes', r.max_silence_minutes,
            'probe_note', v_note,
            'platform_errors_30m', v_platform,
            'detected_by', 'fn_edge_health_scan'),
          'edge_health_watchdog');
        v_open := true;

        insert into org_tasks (dept_key, title, detail, status, tier, action_class, needs_founder)
        values (
          coalesce(r.dept_key, 'technology'),
          left(v_title, 300),
          r.purpose || E'\n\nWhat breaks while this stays down: ' || r.blast_radius ||
          E'\n\nLast observed effect: ' || coalesce(v_beat::text, 'never') ||
          E'\nCron job: ' || coalesce(r.cron_jobname, 'unknown') ||
          E'\nSeverity: ' || r.severity ||
          E'\nPlatform error codes in the last 30 minutes: ' || v_platform::text ||
          E'\n\nNote: this was detected by watching the capability''s EFFECT, not its logs. ' ||
          'A function killed by the platform (546 WORKER_RESOURCE_LIMIT, OOM, timeout) never ' ||
          'reaches its own error handler, so agent_runs will look clean. Check ' ||
          'net._http_response and the edge function logs directly.',
          'proposed', 'supervised', 'investigate',
          -- a dark backup or a dark availability probe is founder-visible, not just a ticket
          (r.severity = 'high'));
      end if;
    else
      update os_incidents
         set status = 'resolved', resolved_at = now(), resolved_by = 'edge_health_watchdog',
             resolution = 'Capability resumed producing effects; last beat ' || coalesce(v_beat::text,'?')
       where status = 'open' and detail->>'fn_key' = r.fn_key;
      update org_tasks
         set status = 'done', updated_at = now(),
             result = coalesce(result,'{}'::jsonb) || jsonb_build_object('auto_closed','capability recovered','last_beat_at', v_beat)
       where status in ('proposed','assigned','in_progress')
         and action_class = 'investigate'
         and title like 'Silent failure: ' || r.fn_key || ' %';
    end if;

    fn_key := r.fn_key; verdict := v_verdict; silent_minutes := v_silent; opened_incident := v_open;
    return next;
  end loop;
end

trg_health_check_agent_threshold:
declare
  v_total   int;
  v_failed  int;
  v_rate    numeric;
  v_limit   numeric := coalesce(
    (select nullif(value,'')::numeric from app_secrets where key='agent_failure_rate_limit'), 0.10);
begin
  if new.check_kind is distinct from 'agent_runs' then
    return new;
  end if;

  select count(*),
         count(*) filter (where status not in ('ok','success','completed','skipped','warn'))
    into v_total, v_failed
  from agent_runs
  where started_at > now() - interval '1 hour';

  -- No runs at all in an hour is itself a failure: the company has gone quiet.
  if v_total = 0 then
    new.ok := false;
    new.detail := 'NO agent runs at all in the last hour - the company has gone silent, which is worse than a high failure rate.';
    return new;
  end if;

  v_rate := round(v_failed::numeric / v_total, 4);
  new.ok := (v_rate < v_limit);
  new.detail := v_failed || ' of ' || v_total || ' agent runs failed in the last hour ('
             || round(v_rate * 100, 2) || '%); threshold ' || round(v_limit * 100, 2) || '%'
             || case when new.ok then '' else ' - OVER THRESHOLD' end
             || '. [Recomputed by trg_health_check_agent_threshold; the raw producer sets ok=false on any single failure, which can never be true.]';
  return new;
end

fn_ai_spend_guard:
declare
  r             record;
  v_month_start date := date_trunc('month', now())::date;
  v_day_of      numeric := greatest(extract(day from now())::numeric, 1);
  v_days_in     numeric := extract(day from (date_trunc('month', now()) + interval '1 month - 1 day'))::numeric;
  v_today       numeric;
  v_baseline    numeric;
  v_spike       numeric := coalesce((select nullif(value,'')::numeric from app_secrets where key='ai_spend_spike_multiple'), 5.0);
  v_verdict     text;
  v_note        text;
  v_proj        numeric;
  v_blind_pct   numeric;
begin
  -- HOW MUCH OF THIS MONTH'S SPEND THE AUTOMATIC HALT CANNOT SEE. fn_ai_route enforces the ceiling
  -- by looking up department_budget for the call's dept_key; a call logged without one has no
  -- budget to be measured against and cannot be halted. Measured here rather than asserted, because
  -- the sentence this feeds used to be a hardcoded claim that went stale.
  select round(100.0 * count(*) filter (where dept_key is null) / nullif(count(*), 0), 1)
    into v_blind_pct
    from ai_cost_log where occurred_at >= v_month_start;
  v_blind_pct := coalesce(v_blind_pct, 0);

  -- ---- 1 & 3: per-department consumption and month-end projection ----
  for r in
    select b.dept_key, b.monthly_aed, b.degrade_at_pct, b.halt_at_pct,
           coalesce((select sum(l.cost_aed) from ai_cost_log l
                      where l.dept_key = any(public.fn_dept_scope(b.dept_key))
                        and l.occurred_at >= v_month_start), 0) as spent
    from department_budget b
    where b.monthly_aed > 0
  loop
    pct  := round(100 * r.spent / r.monthly_aed, 2);
    v_proj := round(r.spent / v_day_of * v_days_in, 2);

    if pct >= r.halt_at_pct then
      v_verdict := 'HALT';
      v_note := r.dept_key || ' has spent ' || round(r.spent,2) || ' of ' || r.monthly_aed
             || ' AED (' || pct || '%), at or past its halt threshold of ' || r.halt_at_pct || '%.';
    elsif pct >= r.degrade_at_pct then
      v_verdict := 'DEGRADE';
      v_note := r.dept_key || ' has spent ' || round(r.spent,2) || ' of ' || r.monthly_aed
             || ' AED (' || pct || '%), past its degrade threshold of ' || r.degrade_at_pct || '%.';
    elsif v_proj > r.monthly_aed then
      v_verdict := 'PROJECTED OVER';
      v_note := r.dept_key || ' is at ' || pct || '% on day ' || v_day_of || ', but the current run-rate projects '
             || v_proj || ' AED by month end against a ' || r.monthly_aed || ' AED budget.';
    else
      v_verdict := 'OK';
      v_note := r.dept_key || ': ' || round(r.spent,2) || '/' || r.monthly_aed || ' AED (' || pct
             || '%), projecting ' || v_proj || ' AED.';
    end if;

    insert into ai_spend_probe (scope, spent_aed, budget_aed, pct, projected_aed, verdict, note)
    values (r.dept_key, r.spent, r.monthly_aed, pct, v_proj, v_verdict, v_note);

    -- THE STORED COUNTER STOPS LYING. department_budget.spent_aed was 0.00 for every real
    -- department while AED 106 had been spent this month, because nothing ever wrote it. The
    -- enforcing paths (this function and fn_ai_route) always summed ai_cost_log live and were
    -- never affected; fn_budget_available read the column and therefore reported every budget
    -- as untouched, which is what fn_check_spend authorises business spend against.
    -- fn_budget_available now computes live too, so this write is for anything that READS the
    -- column - dashboards, reports, the founder's own eye - not for any decision.
    update department_budget
       set spent_aed = round(r.spent, 4), period_label = to_char(now(), 'YYYY-MM'), updated_at = now()
     where dept_key = r.dept_key
       and (spent_aed is distinct from round(r.spent, 4) or period_label is distinct from to_char(now(), 'YYYY-MM'));

    if v_verdict <> 'OK' then
      if not exists (select 1 from os_incidents
                      where status='open' and kind='ai_spend' and detail->>'scope' = r.dept_key) then
        insert into os_incidents (title, kind, severity, status, detail, opened_by)
        values (left('AI spend ' || v_verdict || ': ' || r.dept_key, 300), 'ai_spend',
                case when v_verdict='HALT' then 'high' else 'medium' end, 'open',
                jsonb_build_object('scope', r.dept_key, 'spent_aed', round(r.spent,2),
                  'budget_aed', r.monthly_aed, 'pct', pct, 'projected_aed', v_proj,
                  'verdict', v_verdict,
                  'halt_enforcement', 'The automatic halt IS enforced, by fn_ai_route inside ai_gateway: it compares month-to-date dept spend against department_budget.halt_at_pct and returns use_llm=false, which the gateway refuses as budget_halted. It can only act on calls that carry a dept_key; ' || v_blind_pct || '% of this month''s logged calls do not, and that share is outside the ceiling.'),
                'ai_spend_guard');
        insert into founder_alerts (level, event, detail, channel)
        values (case when v_verdict='HALT' then 'crit' else 'warn' end, 'ai_spend_' || lower(replace(v_verdict,' ','_')),
                v_note || ' The automatic halt is enforced by fn_ai_route in ai_gateway and stops non-gated work for a department at its halt_at_pct. It cannot see calls logged without a dept_key: ' || v_blind_pct || '% of this month''s calls, which remain outside the ceiling.', 'system');
      end if;
    else
      update os_incidents set status='resolved', resolved_at=now(), resolved_by='ai_spend_guard',
             resolution = 'Back within budget: ' || v_note
       where status='open' and kind='ai_spend' and detail->>'scope' = r.dept_key;
    end if;

    scope := r.dept_key; verdict := v_verdict; note := v_note;
    return next;
  end loop;

  -- ---- 2: company-wide daily run-rate spike ----
  select coalesce(sum(cost_aed),0) into v_today
    from ai_cost_log where occurred_at >= current_date;
  select coalesce(avg(d),0) into v_baseline from (
    select sum(cost_aed) d from ai_cost_log
    where occurred_at >= current_date - interval '7 days' and occurred_at < current_date
    group by date_trunc('day', occurred_at)
  ) x;

  if v_baseline > 0 and v_today > v_baseline * v_spike then
    v_verdict := 'SPIKE';
    v_note := 'Company AI spend today is ' || round(v_today,2) || ' AED against a trailing daily average of '
           || round(v_baseline,2) || ' AED - ' || round(v_today / v_baseline, 1)
           || 'x the baseline. Autonomy multiplies call volume; check what started.';
    if not exists (select 1 from os_incidents where status='open' and kind='ai_spend' and detail->>'scope'='company_daily') then
      insert into os_incidents (title, kind, severity, status, detail, opened_by)
      values (left('AI spend SPIKE: ' || round(v_today/v_baseline,1) || 'x the daily baseline', 300),
              'ai_spend', 'high', 'open',
              jsonb_build_object('scope','company_daily','today_aed',round(v_today,2),
                'baseline_aed',round(v_baseline,2),'multiple',round(v_today/v_baseline,1),
                'threshold_multiple', v_spike), 'ai_spend_guard');
      insert into founder_alerts (level, event, detail, channel)
      values ('crit','ai_spend_spike', v_note, 'system');
    end if;
  else
    v_verdict := 'OK';
    v_note := 'Company AI spend today ' || round(v_today,2) || ' AED against a ' || round(v_baseline,2) || ' AED trailing daily average.';
    update os_incidents set status='resolved', resolved_at=now(), resolved_by='ai_spend_guard',
           resolution = v_note
     where status='open' and kind='ai_spend' and detail->>'scope'='company_daily';
  end if;

  insert into ai_spend_probe (scope, spent_aed, budget_aed, pct, verdict, note)
  values ('company_daily', v_today, v_baseline, case when v_baseline>0 then round(100*v_today/v_baseline,2) else null end, v_verdict, v_note);

  scope := 'company_daily'; verdict := v_verdict;
  pct := case when v_baseline>0 then round(100*v_today/v_baseline,2) else null end;
  note := v_note;
  return next;
end

fn_model_cost_usd:
select round(
    ( (greatest(coalesce(p_in_tokens,0) - coalesce(p_cached_in_tokens,0), 0)::numeric / 1000000) * r.in_per_mtok_usd
    + (coalesce(p_cached_in_tokens,0)::numeric / 1000000) * coalesce(r.cache_read_per_mtok_usd, r.in_per_mtok_usd)
    + (coalesce(p_out_tokens,0)::numeric / 1000000) * r.out_per_mtok_usd
    )::numeric, 6)
from model_registry r where r.model_id = p_model;

fn_llm_cache_lookup:
declare r record; v_sim numeric;
begin
  -- 1. exact
  select * into r from llm_cache
   where cache_key = p_key and (expires_at is null or expires_at > now()) limit 1;
  if found then
    update llm_cache set hits = hits + 1, last_hit_at = now() where cache_key = r.cache_key;
    return jsonb_build_object('hit', true, 'kind', 'exact', 'response', r.response,
                              'model', r.model_used, 'similarity', 1.0);
  end if;

  -- 2. semantic. Deliberately scoped to the same task_class: a research answer must
  -- never be served to a classification prompt just because they read alike.
  if p_embedding is not null then
    select c.*, 1 - (c.embedding_gte <=> p_embedding) as sim into r
      from llm_cache c
     where c.embedding_gte is not null
       and (c.expires_at is null or c.expires_at > now())
       and (p_task_class is null or c.task_class is not distinct from p_task_class)
     order by c.embedding_gte <=> p_embedding
     limit 1;
    if found then
      v_sim := round((r.sim)::numeric, 4);
      if v_sim >= p_min_similarity then
        update llm_cache set hits = hits + 1, last_hit_at = now() where cache_key = r.cache_key;
        return jsonb_build_object('hit', true, 'kind', 'semantic', 'response', r.response,
                                  'model', r.model_used, 'similarity', v_sim);
      end if;
    end if;
  end if;

  return jsonb_build_object('hit', false);
end

fn_rate_limit:
declare r ai_rate_limit%rowtype;
begin
  insert into ai_rate_limit (bucket, window_start, count) values (p_bucket, now(), 0)
    on conflict (bucket) do nothing;
  select * into r from ai_rate_limit where bucket = p_bucket for update;
  if r.window_start < now() - make_interval(secs => p_window_seconds) then
    update ai_rate_limit set window_start = now(), count = 1 where bucket = p_bucket;
    return jsonb_build_object('allowed', true, 'count', 1, 'limit', p_limit);
  end if;
  if r.count >= p_limit then
    return jsonb_build_object('allowed', false, 'count', r.count, 'limit', p_limit,
      'retry_after_seconds', greatest(1, p_window_seconds - extract(epoch from (now() - r.window_start))::int));
  end if;
  update ai_rate_limit set count = count + 1 where bucket = p_bucket;
  return jsonb_build_object('allowed', true, 'count', r.count + 1, 'limit', p_limit);
end

fn_faq_answer:
declare r record; v_q tsquery; v_tpl record; v_sim numeric;
begin
  if p_text is null or length(btrim(p_text)) < 2 then
    return jsonb_build_object('answered', false, 'reason', 'input too short');
  end if;

  -- 1. Fixed intents. No retrieval, no model.
  select * into v_tpl from response_template
   where active and (
     (intent='greeting' and p_text ~* '^\s*(hi|hey|hello|salam|marhaba|good (morning|afternoon|evening))\W*$') or
     (intent='thanks'   and p_text ~* '^\s*(thanks|thank you|thx|shukran|much appreciated)\W*$')
   ) limit 1;
  if found then
    update response_template set used_count = used_count + 1 where key = v_tpl.key;
    return jsonb_build_object('answered', true, 'source', 'template', 'key', v_tpl.key,
                              'answer', v_tpl.body, 'confidence', 1.0);
  end if;

  -- 2. Keyword match. Cheap and precise when the wording lines up.
  v_q := websearch_to_tsquery('english', p_text);
  if v_q is not null then
    select f.question, f.answer,
           ts_rank(to_tsvector('english', coalesce(f.question,'')||' '||coalesce(f.answer,'')), v_q) as rank
      into r
      from company_faq f
     where f.public and f.status='approved'
       and to_tsvector('english', coalesce(f.question,'')||' '||coalesce(f.answer,'')) @@ v_q
     order by rank desc limit 1;
    if found and r.rank >= p_min_rank then
      return jsonb_build_object('answered', true, 'source', 'faq_keyword', 'question', r.question,
                                'answer', r.answer, 'confidence', round(r.rank::numeric, 4));
    end if;
  end if;

  -- 3. Semantic match. Catches the same question asked in different words.
  if p_embedding is not null then
    select f.question, f.answer, 1 - (f.embedding_gte <=> p_embedding) as sim into r
      from company_faq f
     where f.public and f.status='approved' and f.embedding_gte is not null
     order by f.embedding_gte <=> p_embedding limit 1;
    if found then
      v_sim := round((r.sim)::numeric, 4);
      if v_sim >= p_min_similarity then
        return jsonb_build_object('answered', true, 'source', 'faq_semantic', 'question', r.question,
                                  'answer', r.answer, 'confidence', v_sim);
      end if;
      return jsonb_build_object('answered', false, 'reason', 'no confident FAQ match',
                                'best_similarity', v_sim);
    end if;
  end if;

  return jsonb_build_object('answered', false, 'reason', 'no confident FAQ match');
end

fn_dept_can_plan:
declare
  v_stalled int; v_cap int := 5; v_last timestamptz;
begin
  -- Only ASSIGNED-but-never-run work counts as pile-up. Work in progress, work
  -- awaiting the founder, and work already attempted are not what the cap is for.
  select count(*) into v_stalled from org_tasks
   where dept_key = p_dept_key and status = 'assigned' and attempts = 0
     and created_at < now() - interval '48 hours';

  select max(created_at) into v_last from org_memory
   where scope = p_dept_key and kind = 'plan' and source = 'dept_plan';

  -- No department goes silent for more than a week, whatever its backlog. A
  -- department that cannot plan cannot improve, and that is the failure mode the
  -- autonomous-company design exists to prevent.
  if v_last is null or v_last < now() - interval '7 days' then
    return jsonb_build_object('can_plan', true, 'reason',
      'weekly floor: last self-plan ' || coalesce(v_last::text,'never') || ' - planning regardless of backlog',
      'stalled', v_stalled);
  end if;

  if v_stalled >= v_cap then
    return jsonb_build_object('can_plan', false, 'reason',
      v_stalled || ' tasks assigned over 48h ago and never attempted. Execution is behind planning; drain before adding.',
      'stalled', v_stalled);
  end if;

  return jsonb_build_object('can_plan', true, 'reason',
    v_stalled || ' stalled task(s), under the cap of ' || v_cap, 'stalled', v_stalled);
end

