fn_approval_raise_on_award:
declare v_org uuid; v_policy uuid; v_amount numeric;
begin
  select o.id into v_org from public.customer_organization o
   where o.owner_customer_id = new.customer_id limit 1;
  if v_org is null then
    select m.organization_id into v_org from public.customer_organization_member m
     where m.user_id = new.customer_id and coalesce(m.active, true) limit 1;
  end if;
  if v_org is null then return new; end if;          -- not an enterprise buyer: nothing to approve

  select coalesce(q.customer_price, q.quote_amount) into v_amount
    from public.quotes q
   where q.inquiry_id = new.id and q.supplier_id = new.hired_supplier_id
   order by q.created_at desc limit 1;

  v_policy := public.fn_approval_policy_match(v_org, 'inquiry', v_amount, new.category, new.emirate);
  if v_policy is null then return new; end if;       -- no policy covers this purchase

  if exists (select 1 from public.procurement_approval_request r
              where r.entity_type = 'inquiry' and r.entity_id = new.id::text
                and r.status in ('pending', 'approved')) then
    return new;                                      -- idempotent: one live chain per award
  end if;

  insert into public.procurement_approval_request (organization_id, entity_type, entity_id, policy_id)
  values (v_org, 'inquiry', new.id::text, v_policy);
  return new;
exception when others then
  raise warning 'fn_approval_raise_on_award skipped inquiry %: %', new.id, sqlerrm;
  return new;
end

fn_approval_decide:
declare r public.procurement_approval_request;
        v_steps jsonb; v_n int; v_step jsonb; v_role text; v_actor_role text;
        v_next int; v_status text;
begin
  if coalesce(p_decision, '') not in ('approved', 'rejected') then
    raise exception 'decision must be approved or rejected, got %', p_decision;
  end if;
  select * into r from public.procurement_approval_request where id = p_request for update;
  if not found then raise exception 'approval request % not found', p_request; end if;
  if r.status <> 'pending' then
    return jsonb_build_object('ok', false, 'error', 'already_' || r.status,
                              'request_id', r.id, 'status', r.status);
  end if;

  -- THE TRUST BOUNDARY IS HERE, NOT IN THE ENDPOINT. Every caller — the customer endpoint, the
  -- staff console, a psql session — routes through this routine, so the membership and role check
  -- lives in it once instead of in each caller.
  select m.role into v_actor_role
    from public.customer_organization_member m
   where m.organization_id = r.organization_id and m.user_id = p_actor and coalesce(m.active, true);
  if v_actor_role is null then
    if exists (select 1 from public.customer_organization o
                where o.id = r.organization_id and o.owner_customer_id = p_actor) then
      v_actor_role := 'owner';
    else
      raise exception 'actor % is not an active member of organization %', p_actor, r.organization_id;
    end if;
  end if;

  select p.steps into v_steps from public.procurement_approval_policy p where p.id = r.policy_id;
  v_steps := coalesce(v_steps, '[]'::jsonb);
  v_n := jsonb_array_length(v_steps);
  if v_n = 0 then raise exception 'approval request % has no policy steps', r.id; end if;
  if r.current_step < 1 or r.current_step > v_n then
    raise exception 'approval request % is at step % of %', r.id, r.current_step, v_n;
  end if;

  v_step := v_steps -> (r.current_step - 1);
  v_role := v_step->>'role';
  if v_role is not null and v_actor_role <> v_role and v_actor_role <> 'owner' then
    raise exception 'step % (%) is decided by %, not %',
      r.current_step, coalesce(v_step->>'label', v_step->>'key'), v_role, v_actor_role;
  end if;

  if p_decision = 'rejected' then      v_status := 'rejected'; v_next := r.current_step;
  elsif r.current_step >= v_n then     v_status := 'approved'; v_next := r.current_step;
  else                                 v_status := 'pending';  v_next := r.current_step + 1;
  end if;

  update public.procurement_approval_request
     set decisions = decisions || jsonb_build_array(jsonb_build_object(
           'step', r.current_step,
           'key', v_step->>'key',
           'label', coalesce(v_step->>'label', v_step->>'key', 'Step ' || r.current_step),
           'decision', p_decision,
           'by', p_actor,
           'by_role', v_actor_role,
           'at', now(),
           'note', p_note)),
         current_step = v_next,
         status = v_status
   where id = r.id;

  return jsonb_build_object('ok', true, 'request_id', r.id, 'status', v_status,
                            'decided_step', r.current_step, 'current_step', v_next,
                            'steps_total', v_n, 'decided_by', p_actor, 'decided_by_role', v_actor_role);
end

fn_customer_supplier_score:
declare
  v_sent int; v_quoted int; v_awarded int; v_reveals int; v_acked int; v_refunds int;
  v_avg_quote numeric; v_resp_hours numeric; v_last timestamptz;
  v_rating numeric; v_dims jsonb; v_reviews int;
  v_responsiveness numeric; v_award_rate numeric; v_delivery numeric;
  v_quality numeric; v_refund_free numeric;
  v_parts jsonb := '[]'::jsonb; v_sum numeric := 0; v_wt numeric := 0;
  v_global jsonb; v_supplier text;
  -- each component contributes only when the customer's history actually carries it, so a single
  -- review does not become the whole verdict and a missing dimension does not read as a zero
  v_method text := 'weighted mean over the components with data';
begin
  select l.company_name into v_supplier from leads l where l.id = p_supplier;
  if v_supplier is null then
    return jsonb_build_object('error', 'unknown_supplier', 'supplier_id', p_supplier);
  end if;

  select count(*) into v_sent
    from inquiry_matches m join inquiries i on i.id = m.inquiry_id
   where m.supplier_id = p_supplier and i.customer_id = p_customer;

  select count(*), round(avg(q.quote_amount), 0),
         round(avg(extract(epoch from (q.created_at - i.created_at)) / 3600.0)::numeric, 1),
         max(q.created_at)
    into v_quoted, v_avg_quote, v_resp_hours, v_last
    from quotes q join inquiries i on i.id = q.inquiry_id
   where q.supplier_id = p_supplier and i.customer_id = p_customer
     and coalesce(q.status, '') <> 'draft';

  select count(*) into v_awarded
    from inquiries i
   where i.customer_id = p_customer and i.hired_supplier_id = p_supplier;

  select count(*),
         count(*) filter (where t.supplier_ack_at is not null),
         count(*) filter (where coalesce(t.refund_status, '') = 'approved')
    into v_reveals, v_acked, v_refunds
    from transactions t
   where t.customer_id = p_customer and t.supplier_id = p_supplier;

  select count(*), round(avg(r.rating)::numeric, 2),
         jsonb_build_object(
           'communication', round(avg(r.r_communication)::numeric, 2),
           'quality', round(avg(r.r_quality)::numeric, 2),
           'punctuality', round(avg(r.r_punctuality)::numeric, 2),
           'documentation', round(avg(r.r_documentation)::numeric, 2),
           'after_sales', round(avg(r.r_after_sales)::numeric, 2),
           'compliance', round(avg(r.r_compliance)::numeric, 2))
    into v_reviews, v_rating, v_dims
    from reviews r
   where r.customer_id = p_customer and r.supplier_id = p_supplier;

  select jsonb_build_object('reliability', s.reliability, 'quality_rating', s.quality_rating,
                            'price_index', s.price_index, 'response_rate', s.response_rate,
                            'avg_response_hours', s.avg_response_hours,
                            'quotes_submitted', s.quotes_submitted, 'quotes_won', s.quotes_won,
                            'computed_at', s.computed_at)
    into v_global from supplier_score s where s.lead_id = p_supplier;

  -- Nothing shared: report the global figures and refuse to invent a relationship.
  if coalesce(v_sent, 0) = 0 and coalesce(v_quoted, 0) = 0 and coalesce(v_reveals, 0) = 0
     and coalesce(v_reviews, 0) = 0 then
    return jsonb_build_object(
      'customer_id', p_customer, 'supplier_id', p_supplier, 'supplier_name', v_supplier,
      'basis', 'no_shared_history', 'relationship_score', null,
      'empty_reason', format('You have not worked with %s yet. A relationship score is built from your own RFQs, quotes, orders and reviews with a supplier, so there is nothing to score until the first one.', v_supplier),
      'history', jsonb_build_object('rfqs_sent', 0, 'quotes_received', 0, 'orders', 0,
                                    'reveals', 0, 'reviews', 0),
      'delivery_pct', null, 'quality_pct', null, 'win_rate_pct', null,
      'avg_response_hours', null, 'avg_quote_aed', null, 'last_interaction_at', null,
      'your_rating', null, 'your_rating_dimensions', null,
      'components', '[]'::jsonb,
      'platform_wide', coalesce(v_global, 'null'::jsonb));
  end if;

  if v_sent > 0 then
    v_responsiveness := round(least(100, 100.0 * v_quoted / v_sent), 1);
    v_parts := v_parts || jsonb_build_object('name', 'responsiveness', 'value', v_responsiveness,
      'weight', 30, 'basis', format('%s of %s RFQs you sent came back with a quote', v_quoted, v_sent));
    v_sum := v_sum + v_responsiveness * 30; v_wt := v_wt + 30;
  end if;

  if v_quoted > 0 then
    v_award_rate := round(100.0 * v_awarded / v_quoted, 1);
    v_parts := v_parts || jsonb_build_object('name', 'award_rate', 'value', v_award_rate,
      'weight', 15, 'basis', format('you awarded %s of their %s quote(s)', v_awarded, v_quoted));
    v_sum := v_sum + v_award_rate * 15; v_wt := v_wt + 15;
  end if;

  if v_reveals > 0 then
    v_delivery      := round(100.0 * v_acked / v_reveals, 1);
    v_refund_free   := round(100.0 * (v_reveals - v_refunds) / v_reveals, 1);
    v_parts := v_parts || jsonb_build_object('name', 'delivery', 'value', v_delivery,
      'weight', 30, 'basis', format('%s of %s reveal(s) were acknowledged by the supplier', v_acked, v_reveals));
    v_parts := v_parts || jsonb_build_object('name', 'no_refund', 'value', v_refund_free,
      'weight', 10, 'basis', format('%s of %s reveal(s) ended in a refund', v_refunds, v_reveals));
    v_sum := v_sum + v_delivery * 30 + v_refund_free * 10; v_wt := v_wt + 40;
  end if;

  if v_reviews > 0 and v_rating is not null then
    v_quality := round(100.0 * v_rating / 5.0, 1);
    v_parts := v_parts || jsonb_build_object('name', 'your_rating', 'value', v_quality,
      'weight', 25, 'basis', format('your %s review(s) average %s out of 5', v_reviews, v_rating));
    v_sum := v_sum + v_quality * 25; v_wt := v_wt + 25;
  end if;

  return jsonb_build_object(
    'customer_id', p_customer, 'supplier_id', p_supplier, 'supplier_name', v_supplier,
    'basis', 'shared_history', 'empty_reason', null,
    'relationship_score', case when v_wt > 0 then round(v_sum / v_wt, 0)::int end,
    'score_method', v_method,
    'history', jsonb_build_object('rfqs_sent', v_sent, 'quotes_received', v_quoted,
                                  'orders', v_awarded, 'reveals', v_reveals, 'reviews', v_reviews),
    'delivery_pct', v_delivery,
    'quality_pct', v_quality,
    'win_rate_pct', v_award_rate,
    'avg_response_hours', v_resp_hours,
    'avg_quote_aed', v_avg_quote,
    'last_interaction_at', v_last,
    'your_rating', v_rating,
    'your_rating_dimensions', case when v_reviews > 0 then v_dims end,
    'components', v_parts,
    'platform_wide', coalesce(v_global, 'null'::jsonb));
end

fn_negotiation_guidance:
declare
  v_amount numeric; v_cat text; v_supplier bigint; v_supplier_name text; v_inquiry uuid;
  v_stats jsonb; v_policy jsonb; v_scope text; v_band text; v_rule jsonb;
  v_median numeric; v_n int; v_ask numeric; v_max_ask numeric; v_floor_pct numeric;
  v_target numeric; v_delta numeric; v_action text; v_msg text; v_msg_ar text; v_headline text;
begin
  select q.quote_amount, q.supplier_id, i.category, i.id
    into v_amount, v_supplier, v_cat, v_inquiry
    from quotes q join inquiries i on i.id = q.inquiry_id
   where q.id = p_quote and i.customer_id = p_customer;

  -- Ownership is the first gate, not a filter added later: a quote on someone else's RFQ is not a
  -- quote this caller may benchmark.
  if v_inquiry is null then
    return jsonb_build_object('error', 'not_your_quote', 'quote_id', p_quote);
  end if;

  select l.company_name into v_supplier_name from leads l where l.id = v_supplier;

  v_stats := fn_price_confidence(v_cat, v_amount);
  v_band  := coalesce(v_stats ->> 'band', 'insufficient_data');
  v_median := nullif(v_stats ->> 'median', '')::numeric;
  v_n      := coalesce(nullif(v_stats ->> 'n', '')::int, 0);

  -- Per-supplier override first, house policy second. Neither is invented here: if the table is
  -- empty the routine says so instead of falling back to a hard-coded percentage.
  select p.policy, p.scope into v_policy, v_scope from supplier_negotiation_policy p
   where p.supplier_id = v_supplier limit 1;
  if v_policy is null then
    select p.policy, p.scope into v_policy, v_scope from supplier_negotiation_policy p
     where p.scope = 'default' limit 1;
  end if;
  if v_policy is null then
    return jsonb_build_object(
      'quote_id', p_quote, 'inquiry_id', v_inquiry, 'category', v_cat,
      'quote_amount', v_amount, 'supplier_id', v_supplier, 'supplier_name', v_supplier_name,
      'market', v_stats, 'policy_scope', null,
      'recommended_action', 'no_policy', 'target_price', null, 'ask_discount_pct', null,
      'headline', 'No negotiation policy is configured yet.',
      'suggested_message', null, 'suggested_message_ar', null,
      'empty_reason', 'supplier_negotiation_policy holds no rule for this supplier and no default rule, so no target price is proposed.');
  end if;

  if v_n < coalesce((v_policy ->> 'min_sample')::int, 4) then v_band := 'insufficient_data'; end if;
  v_rule      := coalesce(v_policy -> 'bands' -> v_band, v_policy -> 'bands' -> 'insufficient_data');
  v_action    := coalesce(v_rule ->> 'action', 'no_benchmark_yet');
  v_ask       := coalesce((v_rule ->> 'ask_discount_pct')::numeric, 0);
  v_max_ask   := coalesce((v_rule ->> 'max_ask_discount_pct')::numeric, 0);
  v_floor_pct := coalesce((v_policy ->> 'never_target_below_pct_of_median')::numeric, 80);
  v_ask       := least(v_ask, v_max_ask);

  if v_band = 'insufficient_data' or v_median is null or v_ask <= 0 then
    -- No benchmark, or a band the policy says not to push on. Both get an honest message.
    v_target := null;
    v_delta  := case when v_median is not null and v_median > 0
                     then round(100 * (v_amount - v_median) / v_median, 1) end;
    v_headline := case
      when v_band = 'insufficient_data' then
        format('No market benchmark yet — only %s comparable quote(s) recorded in %s, and this house policy needs %s before it will quote a market price.',
               v_n, coalesce(v_cat, 'this category'), coalesce(v_policy ->> 'min_sample', '4'))
      when v_band = 'suspiciously_low' then
        format('This quote is well below the market median of AED %s. Confirm the scope before pushing the price.', v_median)
      else format('This quote sits inside the market range; the house policy does not push on it.') end;
    v_msg := case
      when v_band = 'suspiciously_low' then
        format('Hello%s,%s%sThank you for the quotation on %s. Before we proceed I would like to confirm the scope: could you set out exactly what is included, what is excluded, the delivery lead time and the warranty terms? Your price is materially below the other submissions we hold and I want to be sure we are comparing the same package.%s%sKind regards',
               case when v_supplier_name is null then '' else ' ' || v_supplier_name end,
               chr(10), chr(10), coalesce(v_cat, 'this package'), chr(10), chr(10))
      else
        format('Hello%s,%s%sThank you for the quotation on %s. Could you confirm the inclusions and exclusions, the delivery lead time, the payment terms and the warranty period in writing? Once I have those on the same basis from each supplier I will come back to you on price.%s%sKind regards',
               case when v_supplier_name is null then '' else ' ' || v_supplier_name end,
               chr(10), chr(10), coalesce(v_cat, 'this package'), chr(10), chr(10)) end;
    v_msg_ar := format('تحية طيبة،%s%sشكرًا لعرضكم بخصوص %s. نرجو تأكيد البنود المشمولة والمستثناة، ومدة التسليم، وشروط الدفع، وفترة الضمان كتابةً. وبمجرد استلام ذلك من جميع المورّدين على الأساس نفسه سنعود إليكم بشأن السعر.%s%sمع خالص التقدير',
                       chr(10), chr(10), coalesce(v_cat, 'هذا البند'), chr(10), chr(10));
  else
    v_target := greatest(round(v_amount * (1 - v_ask / 100), 0),
                         round(v_median * v_floor_pct / 100, 0));
    v_delta  := round(100 * (v_amount - v_median) / nullif(v_median, 0), 1);
    v_headline := format('AED %s is %s%s%% against a market median of AED %s over %s comparable quote(s). Policy says %s: target AED %s.',
                         v_amount, case when v_delta >= 0 then '+' else '' end, v_delta,
                         v_median, v_n, replace(v_action, '_', ' '), v_target);
    v_msg := format('Hello%s,%s%sThank you for the quotation on %s at AED %s. Based on comparable submissions we are holding for the same scope, our benchmark for this package is around AED %s. If you can meet AED %s on the same inclusions, lead time and warranty, we are ready to proceed with you.%s%sIf the price cannot move, tell me what would have to change in the scope to reach it and I will consider that instead.%s%sKind regards',
                    case when v_supplier_name is null then '' else ' ' || v_supplier_name end,
                    chr(10), chr(10), coalesce(v_cat, 'this package'), v_amount, v_median, v_target,
                    chr(10), chr(10), chr(10), chr(10));
    v_msg_ar := format('تحية طيبة،%s%sشكرًا لعرضكم بخصوص %s بمبلغ %s درهم. استنادًا إلى العروض المماثلة لدينا لنفس النطاق، فإن السعر المرجعي لهذا البند يقارب %s درهم. إذا أمكنكم الوصول إلى %s درهم بنفس البنود ومدة التسليم والضمان، فنحن مستعدون للمضي معكم.%s%sوإذا تعذّر تعديل السعر، فأخبرونا بما يلزم تغييره في النطاق للوصول إليه.%s%sمع خالص التقدير',
                       chr(10), chr(10), coalesce(v_cat, 'هذا البند'), v_amount, v_median, v_target,
                       chr(10), chr(10), chr(10), chr(10));
  end if;

  return jsonb_build_object(
    'quote_id', p_quote, 'inquiry_id', v_inquiry, 'category', v_cat,
    'quote_amount', v_amount, 'supplier_id', v_supplier, 'supplier_name', v_supplier_name,
    'market', v_stats,
    'market_median', v_median, 'market_sample_n', v_n,
    'delta_vs_median_pct', v_delta,
    'band', v_band,
    'policy_scope', v_scope,
    'recommended_action', v_action,
    'ask_discount_pct', case when v_target is null then null else v_ask end,
    'target_price', v_target,
    'headline', v_headline,
    'suggested_message', v_msg,
    'suggested_message_ar', v_msg_ar,
    'empty_reason', case when v_target is null
      then format('No target price is proposed: %s.', case when v_band = 'insufficient_data'
        then 'the category has fewer comparable quotes than this policy requires'
        else 'the house policy does not push on this band' end) end);
end

fn_customer_savings:
declare
  v_min_sample int;
  v_rows int;
  v_by_cat jsonb;
  v_spread numeric; v_bench numeric;
begin
  select coalesce((p.policy ->> 'min_sample')::int, 4) into v_min_sample
    from supplier_negotiation_policy p where p.scope = 'default';
  v_min_sample := coalesce(v_min_sample, 4);

  select count(*) into v_rows
    from quotes q join inquiries i on i.id = q.inquiry_id
   where i.customer_id = p_customer and coalesce(q.status, '') <> 'draft'
     and q.quote_amount is not null and q.quote_amount > 0;

  if v_rows = 0 then
    return jsonb_build_object(
      'customer_id', p_customer, 'as_of', now(), 'min_sample', v_min_sample,
      'by_category', '[]'::jsonb,
      'total_spread_saving_aed', null, 'total_benchmark_saving_aed', null,
      'quotes_considered', 0,
      'empty_reason', 'No quotes on your requests yet. Potential savings are measured from the quotes you actually hold — the spread between them, and each one against the market median for its category — so there is nothing to compute until suppliers respond.');
  end if;

  with live as (
    select q.id, q.inquiry_id, q.quote_amount, coalesce(i.category, 'uncategorised') category
      from quotes q join inquiries i on i.id = q.inquiry_id
     where i.customer_id = p_customer and coalesce(q.status, '') <> 'draft'
       and q.quote_amount is not null and q.quote_amount > 0
       and coalesce(i.status, '') not in ('completed', 'cancelled', 'closed')
  ), per_rfq as (
    select inquiry_id, category, count(*) n_quotes,
           max(quote_amount) - min(quote_amount) spread, min(quote_amount) cheapest
      from live group by inquiry_id, category
  ), bench as (
    select l.category, l.inquiry_id, min(l.quote_amount) cheapest, s.median, s.n
      from live l left join category_price_stats s on s.category = l.category
     group by l.category, l.inquiry_id, s.median, s.n
  )
  select jsonb_agg(x order by x ->> 'category'), sum((x ->> 'spread_saving_aed')::numeric),
         sum(coalesce((x ->> 'benchmark_saving_aed')::numeric, 0))
    into v_by_cat, v_spread, v_bench
    from (
      select jsonb_build_object(
               'category', p.category,
               'rfqs', count(distinct p.inquiry_id),
               'quotes', sum(p.n_quotes),
               'spread_saving_aed', round(sum(case when p.n_quotes >= 2 then p.spread else 0 end), 0),
               'market_median', max(b.median),
               'market_sample_n', max(b.n),
               'benchmark_saving_aed', case when max(b.n) >= v_min_sample
                 then round(greatest(0, sum(b.cheapest) - sum(b.median)), 0) end,
               'benchmark_basis', case when coalesce(max(b.n), 0) >= v_min_sample
                 then format('cheapest quote(s) held against a market median over %s comparable quote(s)', max(b.n))
                 else format('no market benchmark: only %s comparable quote(s) recorded in this category, and %s are needed',
                             coalesce(max(b.n), 0), v_min_sample) end
             ) x
        from per_rfq p join bench b on b.inquiry_id = p.inquiry_id and b.category = p.category
       group by p.category
    ) z;

  return jsonb_build_object(
    'customer_id', p_customer, 'as_of', now(), 'min_sample', v_min_sample,
    'by_category', coalesce(v_by_cat, '[]'::jsonb),
    'total_spread_saving_aed', v_spread,
    'total_benchmark_saving_aed', case when v_bench > 0 then v_bench end,
    'quotes_considered', v_rows,
    'empty_reason', case when coalesce(v_bench, 0) = 0
      then format('No market benchmark saving is shown: no category on your open requests yet has the %s comparable quotes this house policy requires before it will quote a market median.', v_min_sample) end);
end

fn_report_recommendation_approve:
declare v_rec jsonb; v_title text; v_id bigint; v_officer text;
begin
  if p_source = 'exec_reports' then
    select r.recommendations -> p_index, r.officer into v_rec, v_officer
      from public.exec_reports r where r.id = p_report_id;
  else
    select r.kpis -> p_index, 'board' into v_rec, v_officer
      from public.board_reports r where r.id = p_report_id;
  end if;
  if v_rec is null then
    return jsonb_build_object('ok', false, 'error', 'no recommendation at that index');
  end if;
  v_title := coalesce(v_rec ->> 'title', v_rec ->> 'recommendation', left(v_rec::text, 160));

  insert into public.agent_actions(agent, kind, status, risk, title, recommendation,
      target_table, target_id, decided_by, decided_at, detail)
    values (coalesce(v_officer, 'exec'), 'report_recommendation', 'approved',
      coalesce(v_rec ->> 'risk', 'medium'), v_title, v_rec::text,
      p_source, p_report_id::text, p_by, now(),
      jsonb_build_object('report_id', p_report_id, 'index', p_index, 'source', p_source, 'recommendation', v_rec))
    returning id into v_id;

  return jsonb_build_object('ok', true, 'action_id', v_id, 'title', v_title, 'report_id', p_report_id);
end

fn_approval_trace_audit:
declare v_unattributed int; v_gated int; v_msg text;
begin
  -- An action that reached a terminal state with no decider recorded. The authority model exists
  -- precisely so that somebody is accountable for each of these.
  select count(*) into v_unattributed from public.agent_actions
   where status in ('approved','done','auto_done','resolved')
     and coalesce(btrim(decided_by), '') = '';

  -- An action whose department requires approval for its class, that carries no approval at all.
  select count(*) into v_gated from public.agent_actions a
   where a.status in ('approved','done','auto_done','resolved')
     and coalesce(btrim(a.decided_by), '') = ''
     and exists (select 1 from public.org_authority o
                  where o.action_class = a.kind and coalesce(o.max_tier, '') = 'gated');

  if v_unattributed > 0 then
    v_msg := v_unattributed || ' action(s) reached a terminal state with no decider recorded'
          || case when v_gated > 0 then ', ' || v_gated || ' of them in a gated action class' else '' end || '.';
    insert into public.founder_alerts(level, event, detail, channel)
      values (case when v_gated > 0 then 'warn' else 'info' end,
              'Governance monitor — missing approvals', v_msg, 'os');
  end if;
  return jsonb_build_object('monitor', 'missing_approvals', 'unattributed', v_unattributed,
    'gated_without_approval', v_gated, 'ran_at', now());
end

fn_regulation_watch:
declare v_open int; v_stale int; v_sources int;
begin
  select count(*) into v_sources from public.compliance_sources;
  -- Regulatory items the compliance agent raised and nobody has closed.
  select count(*), count(*) filter (where a.created_at < now() - interval '14 days')
    into v_open, v_stale
    from public.agent_actions a
   where a.status in ('pending','needs_review','held_for_review')
     and (a.title ~* '(regulat|municipal|compliance|licen[cs]e|code update|law|decree)'
          or coalesce(a.recommendation,'') ~* '(regulat|municipal|code update|decree)');

  if v_stale > 0 then
    insert into public.founder_alerts(level, event, detail, channel)
      values ('warn', 'Governance monitor — regulatory changes',
              v_stale || ' regulatory item(s) have been open more than 14 days, of ' || v_open
              || ' open in total, against ' || v_sources || ' tracked compliance source(s).', 'os');
  end if;
  return jsonb_build_object('monitor', 'regulatory_changes', 'open', v_open, 'stale', v_stale,
    'sources', v_sources, 'ran_at', now());
end

