fn_kb_route_test_run:
declare t record; r jsonb;
        v_ran int := 0; v_pass int := 0; v_fail int := 0; v_reg int := 0; v_regs text[] := '{}';
begin
  for t in
    select x.test_id, x.input, x.expected_action, (x.last_result->>'action') prev_action
      from public.kb_operational_route_test x
     order by x.last_run_at nulls first, x.test_id
     limit greatest(coalesce(p_limit, 400), 1)
  loop
    begin
      r := public.fn_kb_route_decide(t.input);
    exception when others then
      r := jsonb_build_object('action', 'error', 'error', left(SQLERRM, 300));
    end;

    update public.kb_operational_route_test
       set last_result = r, last_run_at = now()
     where test_id = t.test_id;

    v_ran := v_ran + 1;
    if (r->>'action') = t.expected_action then
      v_pass := v_pass + 1;
    else
      v_fail := v_fail + 1;
      -- a REGRESSION is a case that used to pass and no longer does. The cases that were already
      -- failing on 2 Aug are failures, not regressions, and must not page anyone every hour.
      if t.prev_action is not distinct from t.expected_action then
        v_reg := v_reg + 1; v_regs := v_regs || t.test_id;
      end if;
    end if;
  end loop;

  if v_reg > 0 then
    insert into public.agent_actions(agent, kind, title, recommendation, detail, risk, status)
    values ('knowledge_eng', 'incident',
            format('%s operational route test(s) regressed', v_reg),
            'A route that used to resolve correctly no longer does. Check kb_operational_alias and kb_operational_route_map for the affected catalog numbers.',
            jsonb_build_object('test_ids', to_jsonb(v_regs), 'source', 'fn_kb_route_test_run'),
            'medium', 'pending');
  end if;

  return jsonb_build_object('ran', v_ran, 'passed', v_pass, 'failed', v_fail,
                            'regressions', v_reg, 'regressed', to_jsonb(v_regs), 'ran_at', now());
end

fn_kb_corpus_integrity:
declare v_staged bigint; v_ckpt bigint; v_deployed bigint; v_files bigint;
        v_cats bigint; v_cats_empty bigint; v_pkgs_unchecked bigint;
        v_fts bigint; v_problems text[] := '{}';
        v_staged_distinct bigint; v_deployed_distinct bigint; v_missing bigint;
begin
  select count(*) into v_staged   from kb_stage.records;
  select coalesce(sum(rows_seen),0), count(*) into v_ckpt, v_files from kb_stage.file_hashes;
  select count(*) into v_deployed from public.kb_chunks where source_kind = 'qd_kb_pack';
  select count(*) into v_fts      from public.kb_chunks where source_kind = 'qd_kb_pack' and fts is not null;
  select count(*) into v_cats     from kb_stage.categories;
  select count(*) into v_cats_empty from kb_stage.categories c
   where not exists (select 1 from kb_stage.records r where r.category_slug = c.category_slug);
  select count(*) into v_pkgs_unchecked from kb_stage.categories c
   where not exists (select 1 from kb_stage.file_hashes f where f.package_id = c.package_id);

  -- CONTENT, NOT ROWS. A duplicate staged record does not need a duplicate chunk to be retrievable.
  select count(distinct md5(coalesce(title,'')||'|'||coalesce(content,''))) into v_staged_distinct
    from kb_stage.records;
  select count(distinct md5(coalesce(title,'')||'|'||coalesce(content,''))) into v_deployed_distinct
    from public.kb_chunks where source_kind = 'qd_kb_pack';
  select count(*) into v_missing from (
    select md5(coalesce(title,'')||'|'||coalesce(content,'')) h from kb_stage.records
    except
    select md5(coalesce(title,'')||'|'||coalesce(content,'')) from public.kb_chunks where source_kind = 'qd_kb_pack'
  ) z;

  if v_staged <> v_ckpt then
    v_problems := v_problems || format('kb_stage.records is %s but the importer checkpointed %s rows across %s files', v_staged, v_ckpt, v_files);
  end if;
  if v_missing > 0 then
    v_problems := v_problems || format('THE CORPUS IS STAGED BUT NOT DEPLOYED: %s distinct staged record(s) have no chunk in kb_chunks (staged %s rows / %s distinct, deployed %s rows / %s distinct). Every customer path reads kb_chunks.',
                                       v_missing, v_staged, v_staged_distinct, v_deployed, v_deployed_distinct);
  end if;
  if v_fts < v_deployed then
    v_problems := v_problems || format('%s deployed chunks have no full-text vector, and full text is the fallback retrieval path', v_deployed - v_fts);
  end if;
  if v_cats_empty > 0 then
    v_problems := v_problems || format('%s of %s categories in the index have no records', v_cats_empty, v_cats);
  end if;
  if v_pkgs_unchecked > 0 then
    v_problems := v_problems || format('%s packages in the index have no file checkpoint', v_pkgs_unchecked);
  end if;

  if array_length(v_problems,1) is not null then
    insert into public.agent_actions(agent, kind, title, recommendation, detail, risk, status)
    values ('knowledge_eng', 'incident',
            'Knowledge corpus integrity check failed',
            'The staged corpus and the corpus customers can actually retrieve have diverged. Re-run scripts/sql/deploy_corpus_into_kb_chunks.sql after establishing which side moved.',
            jsonb_build_object('problems', to_jsonb(v_problems), 'source', 'fn_kb_corpus_integrity'),
            'high', 'pending');
  end if;

  return jsonb_build_object(
    'ok', array_length(v_problems,1) is null,
    'staged', v_staged,
    'staged_distinct', v_staged_distinct,
    'checkpointed', v_ckpt,
    'files', v_files,
    'deployed_to_kb_chunks', v_deployed,
    'deployed_distinct', v_deployed_distinct,
    'staged_records_with_no_chunk', v_missing,
    'duplicate_staged_records', v_staged - v_staged_distinct,
    'deployed_with_fts', v_fts,
    'categories', v_cats,
    'categories_without_records', v_cats_empty,
    'packages_without_checkpoint', v_pkgs_unchecked,
    'problems', to_jsonb(v_problems),
    'ran_at', now());
end

fn_ai_route:
declare
  v_class   text;
  v_src     text;
  v_pol     model_policy%rowtype;
  v_reg     model_registry%rowtype;
  v_fb      model_registry%rowtype;
  v_bud     department_budget%rowtype;
  v_pct     numeric := 0;
  v_model   text;
  v_why     text;
  v_min     numeric;
  v_tier    text;
  v_vis     boolean := 'vision' = any(coalesce(p_require_caps, '{}'::text[]));
  v_aud     boolean := 'audio'  = any(coalesce(p_require_caps, '{}'::text[]));
  v_tls     boolean := 'tools'  = any(coalesce(p_require_caps, '{}'::text[]));
  v_sub     model_registry%rowtype;
  v_want    int;
  v_idp     model_policy_by_identity%rowtype;
  v_generic boolean := false;
  v_rt      jsonb;
  v_prior   jsonb;
  v_conf    numeric;
  v_rtier   text;
  v_canon   text;
begin
  if p_task_class is not null and length(btrim(p_task_class)) > 0 then
    v_class := p_task_class; v_src := 'caller-supplied task_class';
  else
    select task_class into v_class from fn_task_class where fn = p_fn and active;
    if v_class is not null then
      v_src := 'classified from calling function "' || p_fn || '"';
    else
      v_class := 'general_drafting';
      v_generic := true;
      v_src := 'UNMAPPED function "' || coalesce(p_fn,'?') || '" - defaulted to general_drafting (medium). Add a fn_task_class row to route this properly.';
    end if;
  end if;

  -- THE PACK'S FOUR-ROLE TAXONOMY REACHES THE PATH IT WAS WRITTEN FOR (14 Aug 2026).
  --
  -- All 93 employees carry org_agents.routing_tier - director 36, operations_specialist 23,
  -- analyst_controller 21, reviewer_auditor 10 - and on the main employee path it was DEAD.
  -- fn_routing_tier_model below only fires when v_generic is true, i.e. when the calling function
  -- is unmapped; agent_brain IS mapped, to agent_reasoning, so every employee from a marketing
  -- copywriter to the CEO got the same blanket large tier.
  --
  -- Meanwhile model_policy carries routine_employee_reasoning at MEDIUM, and its own rationale
  -- says: "Pack: replaces the current blanket large-tier agent_reasoning. agent_reasoning is LIVE
  -- on anthropic/claude-sonnet-5 and agent_brain is ~93% of OpenRouter spend." It had ZERO callers.
  -- A policy written to replace something, that nothing points at, is a build order nobody wired.
  --
  -- This is a ROUTING decision taken from the role, not an override of task_class routing: the
  -- class is chosen by who is asking, then the policy for that class applies normally.
  --
  -- WHO STAYS ON LARGE, AND WHY. Only operations_specialist moves. reviewer_auditor stays large
  -- deliberately - all 24 Reviewer/Auditor rows in the pack name a large model, and a reviewer on
  -- the cheap model is a green check that means nothing. director and analyst_controller stay
  -- because their work is the consequential kind the large tier exists for.
  if v_class = 'agent_reasoning' and p_agent_key is not null then
    v_canon := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
    select a.routing_tier into v_rtier from org_agents a
     where a.agent_key = v_canon and a.active;
    if v_rtier = 'operations_specialist'
       and exists (select 1 from model_policy mp
                    where mp.task_class = 'routine_employee_reasoning' and mp.active) then
      v_class := 'routine_employee_reasoning';
      v_src := v_src || ' | routing_tier "operations_specialist" for "' || v_canon
                     || '" selected the routine employee class instead of the blanket large tier';
    end if;
  end if;

  select * into v_pol from model_policy where task_class = v_class and active;
  if not found then
    select * into v_pol from model_policy where task_class = 'general_drafting' and active;
    v_src := v_src || ' | no policy for "' || v_class || '", fell back to general_drafting';
    v_generic := true;
  end if;

  -- THE ROLE DEFAULT. model_policy_by_identity carries 120 rows — 96 target employees and 24
  -- current production agents — and had NO reader in the database at all. The pack states its own
  -- precedence on every row: note = 'Role default only; task_class routing overrides it.' So it
  -- applies only where the caller would otherwise get the generic general_drafting fallback:
  -- either the named class has no policy, or the calling function is unmapped in fn_task_class.
  --
  -- v_generic exists because the first version of this branch was UNREACHABLE. It hung off
  -- `if not found` on the model_policy lookup, and an unmapped function has already had v_class
  -- rewritten to 'general_drafting' by then — which IS found. Measured: fn_ai_route(...,'cfo')
  -- returned identity_policy null. Same shape as the unreachable block in
  -- fn_kb_route_activation_blocked found earlier today: a branch guarded by a condition that
  -- cannot occur.
  --
  -- 23 of the 24 current_agent keys resolve to a real org_agents row; 'cat:*' covers the
  -- category desks.
  if v_generic and p_agent_key is not null then
    select * into v_idp from model_policy_by_identity
     where scope = 'current_agent'
       and (identity_key = p_agent_key
            or (identity_key = 'cat:*' and p_agent_key like 'cat:%'))
     order by (identity_key = p_agent_key) desc
     limit 1;
    if found and v_idp.primary_model is not null then
      v_pol.model_primary  := v_idp.primary_model;
      v_pol.model_fallback := coalesce(v_idp.fallback_model, v_pol.model_fallback);
      v_pol.max_tokens     := coalesce(v_idp.max_output_tokens, v_pol.max_tokens);
      v_src := v_src || ' | role default for "' || p_agent_key || '" applied from model_policy_by_identity';
    end if;
  end if;

  -- ---- ROUTING TIER, added 11 Aug 2026 ---------------------------------------------------------
  -- The pack's four-role taxonomy carried onto the 93 real employees as org_agents.routing_tier.
  -- Fires LAST and only if the pack had nothing to say about this specific agent, so an explicit
  -- current_agent row always wins. Resolves tier -> registry tier -> cheapest active approved model
  -- AT CALL TIME: no model id is stored anywhere, so this follows the fleet instead of going stale.
  -- Measured direction against the general_drafting default (haiku, 1.00 USD/Mtok in):
  -- operations_specialist 4x cheaper, analyst/director unchanged, reviewer_auditor 2x dearer and
  -- deliberately so - all 24 Reviewer/Auditor rows in the pack name sonnet-5, and a reviewer on the
  -- cheap model is a green check that means nothing.
  if v_generic and p_agent_key is not null and v_idp.identity_key is null then
    v_rt := public.fn_routing_tier_model(p_agent_key);
    if v_rt is not null and (v_rt->>'model') is not null then
      v_pol.model_primary := v_rt->>'model';
      v_pol.tier          := v_rt->>'registry_tier';
      v_src := v_src || ' | routing_tier "' || (v_rt->>'routing_tier') || '" for "' || p_agent_key
                     || '" resolved to ' || (v_rt->>'model') || ' (' || (v_rt->>'registry_tier') || ' tier)';
    end if;
  end if;
  -- ----------------------------------------------------------------------------------------------

  if v_pol.tier = 'none' then
    return jsonb_build_object(
      'use_llm', false, 'task_class', v_class, 'tier', 'none',
      'why', 'REFUSED. ' || coalesce(v_pol.deterministic_alternative, 'This is deterministic - use code.')
             || ' [' || v_src || ']',
      'deterministic_alternative', v_pol.deterministic_alternative);
  end if;

  v_tier  := v_pol.tier;
  v_model := v_pol.model_primary;
  v_why   := coalesce(v_pol.rationale, 'policy for ' || v_class) || ' [' || v_src || ']';

  if p_escalate then
    v_model := coalesce(v_pol.model_fallback, v_model);
    v_why   := v_why || ' | ESCALATED one tier after an unsatisfactory cheaper attempt';
  end if;

  select (value #>> '{}')::numeric into v_min from decision_policy where key = 'confidence_min';
  -- THE PRIOR, 11 Aug 2026. Both arms below are original and NEITHER HAS EVER FIRED, because
  -- p_confidence is the confidence of THIS call and no caller can know that before the call.
  -- Measured the day this was written: 7 of 1,746 model calls in seven days carried a confidence at
  -- all. The only confidence that CAN exist beforehand is the agent's own recent record on this
  -- task class, so that is what a caller supplying nothing now routes on.
  --
  -- fn_ai_confidence_prior returns null unless there are at least 5 observations AND they vary.
  -- The variance guard is the important half: the two callers that emitted a confidence before
  -- tonight always emitted exactly 1.0000, and a model reporting the same number every time would
  -- otherwise downgrade itself to a cheaper tier on the strength of its own unvarying optimism.
  v_conf := p_confidence;
  if v_conf is null and p_agent_key is not null then
    v_prior := public.fn_ai_confidence_prior(p_agent_key, v_class);
    if v_prior is not null then v_conf := (v_prior->>'prior')::numeric; end if;
  end if;

  if v_conf is not null then
    if v_conf >= 0.95 and v_tier in ('large','xlarge') then
      select model_id into v_model from model_registry
       where active and approved and tier = 'medium' order by in_per_mtok_usd limit 1;
      v_why := v_why || ' | confidence ' || v_conf
               || case when v_prior is null then ''
                       else ' (' || p_agent_key || ' own median over ' || (v_prior->>'n')
                            || ' calls on ' || v_class || ', spread ' || (v_prior->>'spread') || ')' end
               || ' >= 0.95, downgraded to medium - no second opinion needed';
    elsif v_min is not null and v_conf < v_min and v_tier = 'small' then
      v_model := coalesce(v_pol.model_fallback, v_model);
      v_why := v_why || ' | confidence ' || v_conf
               || case when v_prior is null then ''
                       else ' (' || p_agent_key || ' own median over ' || (v_prior->>'n') || ' calls)' end
               || ' below floor ' || v_min || ', escalated a tier';
    end if;
  end if;

  -- A CALL WITH NO DEPARTMENT IS A CALL NO CEILING CAN STOP (13 Aug 2026). The halt below needs a
  -- dept_key to find a budget, and 59 of this month's calls arrived without one - inquiry_intake,
  -- drawing_boq, doc_extract, license_extract, supplier_onboard and eleven more, i.e. the demand
  -- path. fn_task_class already maps fn -> task_class for this same function's model choice; it now
  -- carries the owning department too, so an un-attributed call is attributed by what it IS rather
  -- than left outside every ceiling. An explicit p_dept_key from the caller still wins.
  -- CANONICAL BEFORE THE CEILING (14 Aug 2026). department_budget holds the ten canonical rows;
  -- a caller passing a merged-away key ('procurement', 'marketing', 'sales' ...) found NO budget
  -- row and skipped the ceiling entirely. fn_dept_canonical resolves the key the caller used to
  -- the department that actually owns it.
  if public.fn_dept_canonical(coalesce(p_dept_key, (select t.dept_key from fn_task_class t where t.fn = p_fn and t.active))) is not null then
    select * into v_bud from department_budget
     where dept_key = public.fn_dept_canonical(coalesce(p_dept_key, (select t.dept_key from fn_task_class t where t.fn = p_fn and t.active)));
    if found and v_bud.monthly_aed > 0 then
      v_pct := round(100 * coalesce(
        (select sum(cost_aed) from ai_cost_log
          where dept_key = any(public.fn_dept_scope(v_bud.dept_key))
            and occurred_at >= date_trunc('month', now())), 0)
        / v_bud.monthly_aed, 2);
      if v_pct >= v_bud.halt_at_pct then
        return jsonb_build_object(
          'use_llm', false, 'task_class', v_class, 'tier', v_tier, 'halted', true, 'budget_pct', v_pct,
          'why', 'HALTED. ' || v_bud.dept_key || ' is at ' || v_pct || '% of its monthly AI budget (halt at '
                 || v_bud.halt_at_pct || '%). Non-gated work stops until the budget resets or is raised.');
      elsif v_pct >= v_bud.degrade_at_pct then
        select model_id into v_model from model_registry
         where active and approved
           and tier = case v_tier when 'xlarge' then 'large' when 'large' then 'medium' else 'small' end
         order by in_per_mtok_usd limit 1;
        v_why := v_why || ' | department at ' || v_pct || '% of budget, degraded one tier';
      end if;
    end if;
  end if;

  select * into v_reg from model_registry where model_id = v_model and active;
  if not found then
    select * into v_reg from model_registry
     where active and approved and tier = (case v_tier when 'xlarge' then 'xlarge' else v_tier end)
     order by in_per_mtok_usd limit 1;
    v_why := v_why || ' | WARNING: policy model "' || v_model || '" is not in model_registry; substituted ' || coalesce(v_reg.model_id,'(none)');
    v_model := v_reg.model_id;
  end if;

  -- CAPABILITY. Price and tier chose the model above; if it cannot see, hear or call tools the
  -- provider will simply reject the payload. Substitute the nearest capable model, preferring the
  -- intended tier, then the closest tier ABOVE it, and only then below - a capability substitution
  -- must never quietly become a quality downgrade.
  v_want := fn_ai_route_tier_rank(v_tier);
  if (v_vis or v_aud or v_tls)
     and not ( (not v_vis or coalesce(v_reg.supports_vision,false))
           and (not v_aud or coalesce(v_reg.supports_audio, false))
           and (not v_tls or coalesce(v_reg.supports_tools, false)) ) then

    select * into v_sub from model_registry
     where active and approved
       and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools)
     order by (fn_ai_route_tier_rank(tier) < v_want),                 -- at-or-above the tier first
              abs(fn_ai_route_tier_rank(tier) - v_want),              -- then closest to it
              in_per_mtok_usd                                          -- then cheapest
     limit 1;

    if found then
      v_why := v_why || ' | CAPABILITY OVERRIDE: ' || v_model || ' cannot do ('
               || array_to_string(coalesce(p_require_caps,'{}'::text[]), '+') || '); substituted ' || v_sub.model_id
               || ' (' || v_sub.tier || ' tier, intended ' || v_tier || ')';
      v_reg := v_sub; v_model := v_sub.model_id;
    else
      return jsonb_build_object(
        'use_llm', false, 'task_class', v_class, 'tier', v_tier, 'caps', to_jsonb(p_require_caps),
        'why', 'REFUSED. No active approved model in model_registry supports ('
               || array_to_string(coalesce(p_require_caps,'{}'::text[]), '+')
               || '). Add one, or mark the capability on an existing model.');
    end if;
  end if;

  select * into v_fb from model_registry
   where model_id = v_pol.model_fallback and active
     and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools);
  if not found and (v_vis or v_aud or v_tls) then
    select * into v_fb from model_registry
     where active and approved and model_id <> v_model
       and (not v_vis or supports_vision) and (not v_aud or supports_audio) and (not v_tls or supports_tools)
     order by (fn_ai_route_tier_rank(tier) < v_want), abs(fn_ai_route_tier_rank(tier) - v_want), in_per_mtok_usd
     limit 1;
  end if;

  return jsonb_build_object(
    'use_llm', true,
    'task_class', v_class,
    'tier', v_tier,
    'model', v_model,
    'fallback', v_fb.model_id,
    'max_tokens', v_pol.max_tokens,
    'cache_ttl_min', coalesce(v_pol.cache_ttl_min, 0),
    'cache', coalesce(v_reg.supports_cache, false),
    'stream', coalesce(v_reg.supports_streaming, true),
    'caps', to_jsonb(coalesce(p_require_caps, '{}'::text[])),
    'in_per_mtok_usd', v_reg.in_per_mtok_usd,
    'out_per_mtok_usd', v_reg.out_per_mtok_usd,
    'cache_read_per_mtok_usd', v_reg.cache_read_per_mtok_usd,
    'budget_pct', v_pct,
    'identity_policy', case when v_idp.identity_key is null then null else jsonb_build_object(
        'identity_key', v_idp.identity_key, 'deterministic_first', v_idp.deterministic_first,
        'reasoning_effort', v_idp.reasoning_effort, 'authority_tier', v_idp.authority_tier) end,
    'routing_tier', v_rt,
    'confidence_prior', v_prior,
    'confidence_used', v_conf,
    'why', v_why);
end

fn_agent_action_resolve_addressee:
declare v_key text;
begin
  if new.agent is null or new.agent = '' then
    new.agent := 'brief';
    new.escalated := true;
    new.escalation_reason := coalesce(new.escalation_reason, 'written with no addressee at all');
    return new;
  end if;

  if exists (select 1 from public.org_agents o where o.agent_key = new.agent and o.active) then
    return new;
  end if;

  v_key := public.fn_org_agent_resolve(new.agent);

  if v_key is null then
    new.detail := coalesce(new.detail, '{}'::jsonb)
                  || jsonb_build_object('addressed_as', new.agent, 'addressee_unresolved', true);
    new.escalated := true;
    new.escalation_reason := coalesce(new.escalation_reason,
      'addressee "' || new.agent || '" is not an employee and no org_agent_alias maps it');
    new.agent := 'brief';
    return new;
  end if;

  new.detail := coalesce(new.detail, '{}'::jsonb) || jsonb_build_object('addressed_as', new.agent);
  new.agent := v_key;
  return new;
end

fn_quality_snapshot_resolve_agent:
declare v_key text;
begin
  if new.agent is null then return new; end if;
  if exists (select 1 from public.org_agents o where o.agent_key = new.agent and o.active) then
    return new;
  end if;
  v_key := public.fn_org_agent_resolve(new.agent);
  if v_key is not null then new.agent := v_key; end if;
  return new;
end

trg_agent_knowledge_metadata:
declare v_days int; begin
  v_days := case when coalesce(NEW.topic,'') ~* 'regulat|authorit|licen|complian|price|pricing|tax|vat|fee' then 90
                 when coalesce(NEW.topic,'') ~* 'market|supplier|commercial|brand|manufactur|competitor'    then 180
                 else 365 end;
  -- source_ref, confidence, owner_agent and supporting_evidence are deliberately NOT set here.
  -- They belong after trg_knowledge_provenance_stamp has had its chance to derive a real citation;
  -- setting them here is what stopped it running at all. See the header.
  if NEW.validation_status is null then NEW.validation_status := 'unvalidated'; end if;
  if NEW.review_due  is null then NEW.review_due  := (now() + (v_days     || ' days')::interval)::date; end if;
  if NEW.valid_until is null then NEW.valid_until := (now() + (v_days * 2 || ' days')::interval)::date; end if;
  return NEW;
end

fn_scenario_run:
declare
  s public.scenario_library%rowtype;
  v_named text[]; v_missing text[] := '{}'; v_unstaffed text[] := '{}'; v_unmanaged text[] := '{}';
  v_dept text; v_verdict text; v_result text; v_staff int;
begin
  select * into s from public.scenario_library where scenario_key = p_scenario_key;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'no scenario '||p_scenario_key);
  end if;

  v_named := coalesce(s.departments, '{}'::text[]);
  if array_length(v_named, 1) is null then
    -- A scenario that names nobody cannot be answered by anybody. That is a finding, not a pass.
    v_verdict := 'gap';
    v_result  := 'NOT RUNNABLE: the scenario names no department, so there is no owner to respond.';
  else
    foreach v_dept in array v_named loop
      if not exists (select 1 from public.org_departments d
                      where d.dept_key = v_dept and coalesce(d.active, true)) then
        v_missing := v_missing || v_dept;
      else
        select count(*) into v_staff from public.org_agents a
         where a.department = v_dept and coalesce(a.active, true);
        if coalesce(v_staff, 0) = 0 then v_unstaffed := v_unstaffed || v_dept; end if;
        -- org_departments names its manager in lead_agent; there is no manager_key on this table.
        if not exists (select 1 from public.org_departments d
                        where d.dept_key = v_dept
                          and nullif(btrim(coalesce(d.lead_agent, '')), '') is not null)
        then v_unmanaged := v_unmanaged || v_dept; end if;
      end if;
    end loop;

    if array_length(v_missing, 1) is not null or array_length(v_unstaffed, 1) is not null then
      v_verdict := 'gap';
    elsif array_length(v_unmanaged, 1) is not null then
      v_verdict := 'staffed_unmanaged';
    else
      -- WAS 'ready'. A one-word status is read faster than the paragraph that qualifies it, and
      -- 'READY' beside "OpenRouter becomes unavailable" reads as "we are ready for that outage".
      -- What was actually checked is that somebody is employed to answer it.
      v_verdict := 'staffed';
    end if;

    v_result := format(
      'ORG STAFFING %s. %s department(s) named: %s. Absent or inactive: %s. Active but unstaffed: %s. Staffed but unmanaged: %s. Checked against org_departments and org_agents at %s UTC. THIS IS A STAFFING CHECK, NOT A REHEARSAL: the failure was not simulated and nothing here says the organisation would survive it.',
      upper(v_verdict), array_length(v_named, 1), array_to_string(v_named, ', '),
      coalesce(nullif(array_to_string(v_missing, ', '), ''), 'none'),
      coalesce(nullif(array_to_string(v_unstaffed, ', '), ''), 'none'),
      coalesce(nullif(array_to_string(v_unmanaged, ', '), ''), 'none'),
      to_char(now() at time zone 'utc', 'YYYY-MM-DD HH24:MI'));
  end if;

  -- WRITES THE STAFFING COLUMNS ONLY. last_run belongs to a real rehearsal and this is not one.
  update public.scenario_library
     set last_staffing_check = now(), last_staffing_result = v_result
   where scenario_key = p_scenario_key;

  return jsonb_build_object('ok', true, 'scenario_key', p_scenario_key, 'verdict', v_verdict,
    'is_rehearsal', false,
    'departments', to_jsonb(v_named), 'missing', to_jsonb(v_missing),
    'unstaffed', to_jsonb(v_unstaffed), 'unmanaged', to_jsonb(v_unmanaged), 'result', v_result);
end

fn_scenario_run_all:
declare r record; v_out jsonb := '[]'::jsonb; v_one jsonb; v_v text;
        v_staffed int := 0; v_unmanaged int := 0; v_gap int := 0;
begin
  for r in select scenario_key from public.scenario_library order by scenario_key loop
    v_one := public.fn_scenario_run(r.scenario_key);
    v_v := v_one->>'verdict';
    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'scenario_key', r.scenario_key, 'verdict', v_v));
    -- THE RUNNER'S OWN VOCABULARY, not the one it used to speak. See the header.
    if v_v = 'staffed' then v_staffed := v_staffed + 1;
    elsif v_v = 'staffed_unmanaged' then v_unmanaged := v_unmanaged + 1;
    else v_gap := v_gap + 1; end if;
  end loop;

  insert into public.agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('scenario_staffing', now(), now(), case when v_gap > 0 then 'error' else 'ok' end,
          jsonb_build_object('checked', jsonb_array_length(v_out), 'staffed', v_staffed,
                             'staffed_unmanaged', v_unmanaged, 'gap', v_gap),
          'Staffing-checked '||jsonb_array_length(v_out)||' failure scenario(s): '||v_staffed
          ||' have an active, staffed department named for them, '||v_unmanaged
          ||' are staffed but have no lead_agent, '||v_gap||' name a department that is absent, '
          ||'inactive or unstaffed. THIS IS A STAFFING CHECK, NOT A REHEARSAL - nothing here says '
          ||'the organisation would survive any of these failures, only that somebody is employed '
          ||'to answer them.');

  return jsonb_build_object('ok', true, 'ran', jsonb_array_length(v_out),
    'staffed', v_staffed, 'staffed_unmanaged', v_unmanaged, 'gap', v_gap,
    'is_rehearsal', false, 'scenarios', v_out);
end

fn_agent_context_capped:
declare
  v_want   int := greatest(coalesce(p_max_chars, 9000), 500);
  v_raw    text;
  v_l2     int;
  v_head   text; v_tail text;
  v_room   int;
  v_note   text;
  v_stored text;
  c_head_max_age constant interval := interval '3 hours';
  v_reserve constant int := 4500;
  v_mark   constant text := E'\n# --- END STABLE CONTEXT ---\n';
  -- THE RESOLVED KEY. Everything below uses this, never the raw argument: the stored-prefix lookup
  -- keys on it too, or an alias would miss the cache it should hit and rebuild the head every call.
  v_key    text;
  v_live   boolean;
begin
  v_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);

  select a.active into v_live from public.org_agents a where a.agent_key = v_key;
  if v_live is null then
    return '[No such employee: ' || coalesce(p_agent_key,'(null)') || '. It resolves to nothing in '
        || 'org_agents or org_agent_alias, so there is no identity, no authority and no knowledge '
        || 'to assemble. Do not proceed as though there were.]' || v_mark;
  end if;
  if not v_live then
    return '[Employee ' || v_key || ' is INACTIVE — merged away or stood down. No context is '
        || 'assembled for an inactive employee, because a context is what lets one act. Address '
        || 'the surviving role instead.]' || v_mark;
  end if;

  if p_query is null or btrim(p_query) = '' then
    v_raw := public.fn_agent_context(v_key, v_want);
  else
    v_raw := public.fn_agent_context(v_key, v_want, p_query);

    -- Fail-open: no row, a stale row, or a different budget all fall through to the live head
    -- computed below, which is exactly the pre-14-Aug behaviour.
    if v_want = 24000 then
      select h.head into v_stored from agent_context_head h
       where h.agent_key = v_key and h.built_at > now() - c_head_max_age
         and h.head_chars = 19500;
    end if;
  end if;

  if v_raw is null then return null; end if;

  v_l2 := position('# LAYER 2b' in v_raw);

  -- No query-matched tail: the whole thing is standing context and is stable as it is.
  if v_l2 = 0 then
    if length(v_raw) <= v_want then return v_raw || v_mark; end if;
    return left(v_raw, v_want - 110) || v_mark ||
      E'\n[context truncated to the ' || v_want || ' characters requested; ' || length(v_raw) ||
      ' were available. No retrieved department layer was present, so this cut is positional.]';
  end if;

  v_head := substr(v_raw, 1, v_l2 - 1);   -- standing context: identity, expertise, company, live
  v_tail := substr(v_raw, v_l2);          -- LAYER 2b + 2c, retrieved for THIS question

  -- Everything fits: nothing is trimmed and the head is whole.
  if length(v_raw) <= v_want then return v_head || v_mark || v_tail; end if;

  v_room := v_want - v_reserve;           -- FIXED. Does not depend on this question's retrieval.

  if v_room < 600 then
    -- The budget cannot fit the standing context at all. Keep what answers the question.
    return E'[Standing context omitted in full: the ' || v_want || '-character budget does not fit '
      || 'it alongside the material retrieved for this question. Identity, expertise, company '
      || 'knowledge and live state are NOT below - do not assert anything about them.]' || v_mark
      || left(v_tail, greatest(v_want - 300, 400));
  end if;

  v_note := E'\n[Standing context trimmed to the first ' || v_room || ' characters of '
         || length(v_head) || '. What follows was retrieved for this specific question. If you '
         || 'need the omitted background, say so rather than guessing at it.]\n';

  -- head is left() to a CONSTANT length, so for a given agent and budget these bytes are identical
  -- on every call. Everything that varies - the note's digits, the retrieved layers - is after the
  -- marker.
  return coalesce(v_stored, left(v_head, v_room)) || v_mark || v_note ||
         case when length(v_tail) > v_reserve
              then left(v_tail, v_reserve - 120) ||
                   E'\n[retrieved material truncated at ' || v_reserve || ' characters]'
              else v_tail end;
end

zzz_fn_notifications_demo_guard:
declare v_on boolean;
begin
  select coalesce((d.value #>> '{}')::boolean, false) into v_on
    from public.decision_policy d where d.key = 'demo_rehearsal_active';
  if not coalesce(v_on, false) then return NEW; end if;

  -- RFC 2606 reserves .invalid as permanently undeliverable. Anything else, including NULL, is
  -- treated as possibly real and held. Failing closed is the whole point of this trigger.
  if coalesce(NEW.to_email, '') ~* '@example[.]invalid$' then return NEW; end if;

  NEW.status := 'held';
  -- Deliberately does NOT contain the marker pattern: fn_demo_marker_scan reads every text column,
  -- and a guard that stamps the pattern on its own rows can never let the teardown proof reach zero.
  NEW.last_error := 'HELD by zzz_notifications_demo_guard: decision_policy.demo_rehearsal_active is '
                 || 'true and the recipient is not a reserved .invalid address. Release with '
                 || 'fn_notifications_release_held() once the rehearsal is torn down.';
  return NEW;
exception when others then
  NEW.status := 'held';
  NEW.last_error := 'HELD by zzz_notifications_demo_guard (guard itself errored: ' || sqlerrm || ')';
  return NEW;
end

fn_external_authority:
declare
  v_cap  int := greatest(coalesce(p_max_chars, 2800), 400);
  v_q    text := nullif(btrim(coalesce(p_query, '')), '');
  v_out  text := '';
  v_part text;
begin
  -- Relevance is a plain ILIKE over the words of the question, not full-text: these are 118 rows,
  -- the index would never be used, and a tsquery that fails to parse would silently return nothing.
  -- When no question is supplied, or nothing matches, the most authoritative rows are emitted
  -- anyway — an employee that does not know a regulation exists cannot ask about it.

  select string_agg('- ['||coalesce(r.authority,'?')||'] '||r.title
                    ||case when coalesce(r.doc_ref,'') <> '' then ' ('||r.doc_ref||')' else '' end
                    ||case when r.effective_date is not null then ' — in force '||r.effective_date else '' end
                    ||case when coalesce(r.summary,'') <> '' then E'\n    '||left(regexp_replace(r.summary,'\s+',' ','g'), 260) else '' end,
                    E'\n' order by (v_q is not null and (r.title ilike '%'||v_q||'%' or coalesce(r.summary,'') ilike '%'||v_q||'%')) desc,
                                   r.effective_date desc nulls last, r.id)
    into v_part
    from (select * from public.regulations
           where status = 'active' and approved_at is not null
           order by (v_q is not null and (title ilike '%'||v_q||'%' or coalesce(summary,'') ilike '%'||v_q||'%')) desc,
                    effective_date desc nulls last limit 8) r;
  if v_part is not null then
    v_out := v_out || 'UAE REGULATIONS IN FORCE (authoritative — cite the authority and the doc ref when you rely on one):'||E'\n'||v_part||E'\n\n';
  end if;

  select string_agg('- '||s.code||' — '||s.title||case when coalesce(s.authority,'') <> '' then ' ('||s.authority||')' else '' end,
                    E'\n' order by s.code)
    into v_part
    from (select * from public.mdm_standards where coalesce(active,true) order by code limit 14) s;
  if v_part is not null then
    v_out := v_out || 'INDUSTRY STANDARDS THE COMPANY WORKS TO:'||E'\n'||v_part||E'\n\n';
  end if;

  select string_agg('- '||m.name||case when coalesce(m.country,'') <> '' then ' ('||m.country||')' else '' end, ', '
                    order by m.name)
    into v_part
    from (select * from public.mdm_manufacturers where coalesce(active,true) order by name limit 22) m;
  if v_part is not null then
    v_out := v_out || 'MANUFACTURERS ON THE MASTER LIST:'||E'\n'||v_part||E'\n\n';
  end if;

  select string_agg('- '||coalesce(c.authority,'?')||': '||coalesce(c.topic,'(topic unrecorded)')
                    ||case when c.last_checked_at is not null then ' — last checked '||c.last_checked_at::date else ' — NEVER CHECKED' end,
                    E'\n' order by c.last_checked_at desc nulls last, c.id)
    into v_part
    from (select * from public.compliance_sources where active
           order by last_checked_at desc nulls last limit 8) c;
  if v_part is not null then
    v_out := v_out || 'AUTHORITIES THIS COMPANY WATCHES FOR CHANGE:'||E'\n'||v_part||E'\n\n';
  end if;

  select string_agg('- '||coalesce(k.authority,'?')||' '||coalesce(k.code_name,'?')
                    ||' ['||coalesce(k.status,'?')||']', E'\n' order by k.priority nulls last, k.authority)
    into v_part
    from (select * from public.reg_catalog where coalesce(status,'') = 'indexed'
           order by priority nulls last limit 10) k;
  if v_part is not null then
    v_out := v_out || 'REGULATORY CODES ALREADY INDEXED IN THE KNOWLEDGE BASE:'||E'\n'||v_part||E'\n\n';
  end if;

  if v_out = '' then return null; end if;

  return E'\n# LAYER 4 (EXTERNAL) - AUTHORITATIVE SOURCES OUTSIDE THIS COMPANY'||E'\n'
      || 'Spec #7 L541. These are external and authoritative: where they conflict with anything else '
      || 'in this context, they win, and you say so. Do not paraphrase a requirement without naming '
      || 'its authority.'||E'\n\n'
      || left(v_out, v_cap - 300);
end

fn_dept_objective_measure:
declare r record; v numeric; n_ok int := 0; n_bad int := 0;
begin
  for r in select id, measure_sql from department_objective
            where coalesce(active,true) and coalesce(measure_sql,'') <> '' loop
    begin
      execute r.measure_sql into v;
      update department_objective set actual_value = v, measured_at = now() where id = r.id;
      n_ok := n_ok + 1;
    exception when others then
      update department_objective set actual_value = null, measured_at = null where id = r.id;
      n_bad := n_bad + 1;
    end;
  end loop;
  return query select n_ok, n_bad;
end

fn_goal_decompose:
declare
  r record;
  v_created int := 0;
  v_adopted int := 0;
  v_id bigint;
  v_unmeasurable int;
begin
  for r in
    select g.key, g.goal, g.target_value, g.unit, g.measure_sql, g.owner_dept, g.horizon
      from company_goals g
      join org_departments d on d.dept_key = g.owner_dept and d.active
     where g.active and coalesce(g.measure_sql,'') <> ''
  loop
    -- Adopt the existing objective for this (department, goal) pair if there is one.
    select id into v_id from department_objective
     where dept_key = r.owner_dept and goal_key = r.key and active
     order by sort, id limit 1;

    if v_id is not null then
      update department_objective
         set target_value = coalesce(target_value, r.target_value),
             unit         = coalesce(unit,         r.unit),
             measure_sql  = coalesce(measure_sql,  r.measure_sql),
             updated_at   = now()
       where id = v_id
         and (measure_sql is null or target_value is null or unit is null);
      if found then v_adopted := v_adopted + 1; end if;
    else
      insert into department_objective
        (dept_key, objective, horizon, goal_key, target_value, unit, measure_sql, status, active)
      values
        (r.owner_dept, r.goal, coalesce(r.horizon,'year_1'), r.key,
         r.target_value, r.unit, r.measure_sql, 'active', true);
      v_created := v_created + 1;
    end if;
  end loop;

  select count(*) into v_unmeasurable from company_goals where active and coalesce(measure_sql,'')='';

  return jsonb_build_object(
    'created', v_created,
    'adopted', v_adopted,
    'company_goals_without_a_measure', v_unmeasurable,
    'note', 'A goal with no measure_sql cannot be handed down. Those '||v_unmeasurable||
            ' goals are the same defect one level up.');
end

fn_employee_responsibilities_backfill:
declare r record; v_txt text; v_kpi text; v_obj text; v_n int := 0;
begin
  for r in select a.agent_key, a.role, a.title, a.seniority, a.department, a.manager_key
             from org_agents a
            where a.active and coalesce(btrim(a.responsibilities),'') = ''
  loop
    select string_agg('- '||k.kpi||' (target '||coalesce(k.target_value::text,'?')||' '
                      ||coalesce(k.unit,'')||', '||coalesce(k.cadence,'ongoing')||')', E'\n' order by k.kpi)
      into v_kpi from employee_kpi k where k.agent_key = r.agent_key and k.active;

    select string_agg('- '||d.objective, E'\n' order by d.sort, d.id)
      into v_obj from department_objective d where d.dept_key = r.department and d.active;

    v_txt := coalesce(r.role, r.title, r.agent_key)
      || case when r.seniority is not null then E'\n\nSeniority: '||r.seniority else '' end
      || case when r.manager_key is not null then '. Reports to: '||r.manager_key else '' end
      || case when v_kpi is not null then E'\n\nYou are measured on:\n'||v_kpi else '' end
      || case when v_obj is not null then E'\n\nYour department exists to:\n'||v_obj else '' end
      || E'\n\nYou own the operational decisions inside this scope. When the answer is not in your'
      || ' knowledge, retrieve it, consult the specialist who holds it, or raise a knowledge-gap'
      || ' task - never answer from a guess.';

    update org_agents set responsibilities = v_txt where agent_key = r.agent_key;
    v_n := v_n + 1;
  end loop;
  return jsonb_build_object('written', v_n,
    'note', 'Composed from role, title, seniority, manager, live employee_kpi rows and the department''s objectives. Blanks only; never overwrites.');
end

fn_spend_concentration_check:
declare
  v_report jsonb; v_total numeric; v_earning numeric := 0; v_pct numeric;
  v_revenue numeric; v_target numeric; v_task bigint; v_title text; v_owner text;
begin
  v_report := public.fn_cost_per_os(30);
  v_total  := (v_report->>'total_cost_aed')::numeric;

  -- The OSes that face a paying customer. marketplace runs the RFQ chain, commercial brings demand.
  select coalesce(sum((e->>'cost_aed')::numeric), 0) into v_earning
    from jsonb_array_elements(v_report->'by_os') e
   where e->>'os_key' in ('marketplace','commercial');

  v_pct := case when coalesce(v_total,0) > 0 then round(100.0 * v_earning / v_total, 2) else null end;

  select p.actual_value, g.target_value into v_revenue, v_target
    from company_goals g
    left join goal_period p on p.goal_key = g.key and p.actual_value is not null
   where g.key = 'revenue_annual'
   order by p.updated_at desc nulls last limit 1;

  -- Earning its way out of the question: no finding while revenue is at or above target.
  if coalesce(v_revenue, 0) >= coalesce(v_target, 1000000) then
    return jsonb_build_object('ok', true, 'fired', false, 'reason', 'revenue at or above target',
                              'earning_os_pct', v_pct, 'revenue', v_revenue);
  end if;

  if v_pct is null or v_pct >= 5.0 then
    return jsonb_build_object('ok', true, 'fired', false, 'reason', 'earning-side share at or above the 5% floor',
                              'earning_os_pct', v_pct, 'total_cost_aed', v_total);
  end if;

  v_title := 'AI spend is concentrated away from the OS that earns revenue';
  if exists (select 1 from org_tasks where title = v_title and status <> 'done') then
    return jsonb_build_object('ok', true, 'fired', false, 'reason', 'an open task already carries this finding',
                              'earning_os_pct', v_pct);
  end if;

  select agent_key into v_owner from org_agents
   where active and agent_key = 'ai_director' limit 1;

  insert into org_tasks (dept_key, assigned_agent, title, detail, status, tier, needs_founder, action_class)
  values ('ai_dept', v_owner, v_title,
    'Measured by fn_cost_per_os over 30 days. Of ' || round(coalesce(v_total,0),2) ||
    ' AED spent on model calls, the revenue-earning operating systems (marketplace, commercial) '
    || 'received ' || round(v_earning,4) || ' AED = ' || v_pct || '%, against a floor of 5%. '
    || 'Trailing revenue is ' || coalesce(v_revenue,0) || ' against a target of '
    || coalesce(v_target,1000000) || ' AED. '
    || 'This is not an assertion that the split is wrong - a company with no customers may rightly '
    || 'think about itself. It is the observation that the company had no way to see it. '
    || 'Decide deliberately: either shift capacity toward demand and quoting, or record why the '
    || 'internal work is the faster route to revenue. Do not close this without one or the other. '
    || 'Full breakdown: ' || (v_report->'by_os')::text,
    'proposed', 'advisory', false, 'recommend')
  returning id into v_task;

  return jsonb_build_object('ok', true, 'fired', true, 'task_id', v_task,
                            'earning_os_pct', v_pct, 'total_cost_aed', v_total,
                            'assigned_agent', v_owner);
end

fn_alert_severe:
-- Deliberately generous and deliberately explicit. Anything a routine plausibly means as
-- "somebody has to look at this now". info / warn / warning / action are NOT severe and stay out.
select lower(coalesce(p_level,'')) in ('critical','crit','error','high','fatal','sev1','urgent');

fn_workflow_actor_resolve:
declare v_ctx jsonb; v_owner text; v_live text; v_tid bigint;
begin
  if p_actor is null or btrim(p_actor) = '' then return null; end if;

  if lower(btrim(p_actor)) not in ('owner', 'director', 'dept_head', 'department head') then
    return public.fn_org_agent_resolve(p_actor);
  end if;

  select r.context into v_ctx from public.workflow_run r where r.id = p_run;
  if v_ctx is null then return null; end if;

  -- The owner is the assignee of the task this run was raised for. employee_task runs carry
  -- context.task_id; the guard on the cast is there because context is free-form jsonb and a
  -- non-numeric task_id would abort the whole planning statement rather than skip one step.
  if coalesce(v_ctx->>'task_id','') ~ '^[0-9]+$' then
    v_tid := (v_ctx->>'task_id')::bigint;
    select t.assigned_agent into v_owner from public.org_tasks t where t.id = v_tid;
  end if;
  if v_owner is null then v_owner := nullif(v_ctx->>'agent',''); end if;
  if v_owner is null then v_owner := public.fn_org_agent_resolve(nullif(v_ctx->>'dept_key','')); end if;

  select o.agent_key into v_live from public.org_agents o where o.agent_key = v_owner and o.active;
  if v_live is null then return null; end if;

  if lower(btrim(p_actor)) = 'owner' then return v_live; end if;

  -- 'Director' on employee_task step 10 is "department head review" - the owner's own manager,
  -- which org_agents.manager_key already models for 93 of 94 employees, acyclically.
  return (select m.agent_key
            from public.org_agents o
            join public.org_agents m on m.agent_key = o.manager_key and m.active
           where o.agent_key = v_live);
end

fn_workflow_step_release:
begin
  update public.workflow_step_run
     set status   = 'ready',
         attempts = coalesce(attempts,0) + 1,
         error    = jsonb_build_object('released_at', now(), 'reason', left(coalesce(p_reason,''), 500),
                                       'released_by', 'workflow_dispatch')
   where id = p_step_run_id and status = 'running' and finished_at is null;
  if not found then return 'not held'; end if;
  return 'released';
end

fn_boq_fixture_score:
declare f public.boq_fixture%rowtype; d jsonb := '[]'::jsonb;
  v_checked int := 0; v_matched int := 0;
  v_doors numeric; v_windows numeric; v_total numeric;
begin
  select * into f from public.boq_fixture where id = p_fixture_id;
  if not found then return jsonb_build_object('error','no such fixture'); end if;

  -- Largest matching line wins: a plan can list "D1 flush wooden doors" and a separate
  -- "door frames" line, and the schedule quantity is the one being checked.
  select max((l->>'qty')::numeric) into v_doors
    from jsonb_array_elements(coalesce(p_actual->'boq','[]'::jsonb)) l
   where (l->>'description') ~* '\ydoor' and (l->>'qty') ~ '^[0-9.]+$'
     and coalesce(l->>'unit','') ~* 'no|ea|pc';
  select max((l->>'qty')::numeric) into v_windows
    from jsonb_array_elements(coalesce(p_actual->'boq','[]'::jsonb)) l
   where (l->>'description') ~* '\ywindow' and (l->>'qty') ~ '^[0-9.]+$'
     and coalesce(l->>'unit','') ~* 'no|ea|pc';
  v_total := nullif(p_actual->>'total_area_sqm','')::numeric;

  if f.expect_doors is not null then
    v_checked := v_checked + 1;
    if v_doors = f.expect_doors then v_matched := v_matched + 1; end if;
    d := d || jsonb_build_array(jsonb_build_object('field','doors','expected',f.expect_doors,
           'actual',v_doors,'match', v_doors = f.expect_doors));
  end if;

  if f.expect_windows is not null then
    v_checked := v_checked + 1;
    if v_windows = f.expect_windows then v_matched := v_matched + 1; end if;
    d := d || jsonb_build_array(jsonb_build_object('field','windows','expected',f.expect_windows,
           'actual',v_windows,'match', v_windows = f.expect_windows));
  end if;

  -- The stated built-up area is preferred; where the drawing prints none, the room sum is the
  -- only figure it states and is what the pipeline's total is compared against.
  if coalesce(f.expect_total_sqm, f.expect_rooms_sqm) is not null then
    declare v_exp numeric := coalesce(f.expect_total_sqm, f.expect_rooms_sqm); v_hit boolean;
    begin
      v_hit := v_total is not null
               and abs(v_total - v_exp) <= v_exp * (f.tolerance_pct / 100.0);
      v_checked := v_checked + 1;
      if v_hit then v_matched := v_matched + 1; end if;
      d := d || jsonb_build_array(jsonb_build_object('field','total_area_sqm','expected',v_exp,
             'actual',v_total,'tolerance_pct',f.tolerance_pct,'match',v_hit));
    end;
  end if;

  return jsonb_build_object('checked', v_checked, 'matched', v_matched,
    'score_pct', case when v_checked > 0 then round(100.0*v_matched/v_checked, 2) else null end,
    'detail', d, 'boq_lines', jsonb_array_length(coalesce(p_actual->'boq','[]'::jsonb)));
end

fn_leads_retrade:
declare v_n int; v_left bigint; v_hi bigint; v_max bigint;
begin
  -- The window: the next p_limit ids at or above p_after, chosen WITHOUT calling the normaliser.
  select max(id) into v_hi from (
    select id from public.leads where id > coalesce(p_after,0)
     order by id limit greatest(coalesce(p_limit, 2000), 1)) w;
  select max(id) into v_max from public.leads;

  if v_hi is null then
    -- past the end: nothing left to walk
    return jsonb_build_object('renormalised', 0, 'next_after', null, 'done', true,
      'in_taxonomy_vocab', (select count(*) from public.leads
                             where invite_trades && (select array_agg(code) from public.taxonomy_trade)));
  end if;

  update public.leads l
     set invite_trades = public.fn_norm_trades(
           coalesce(l.company_name,'')||' '||coalesce(l.categories,'')||' '||
           coalesce(l.sector,'')||' '||coalesce(l.services,'')||' '||coalesce(l.products,''))
   where l.id > coalesce(p_after,0) and l.id <= v_hi
     and not (coalesce(l.company_name,'') ilike 'ZZ DEMO%' or coalesce(l.email,'') ilike '%@example.invalid')
     and l.invite_trades is distinct from public.fn_norm_trades(
           coalesce(l.company_name,'')||' '||coalesce(l.categories,'')||' '||
           coalesce(l.sector,'')||' '||coalesce(l.services,'')||' '||coalesce(l.products,''));
  get diagnostics v_n = row_count;

  -- Progress is an array overlap, never a second run of the normaliser. See the header.
  select count(*) into v_left from public.leads l
   where l.invite_trades is not null and array_length(l.invite_trades,1) > 0
     and not (l.invite_trades && (select array_agg(code) from public.taxonomy_trade));

  return jsonb_build_object(
    'renormalised', v_n,
    'next_after', v_hi,
    'done', v_hi >= coalesce(v_max, v_hi),
    'still_wrong_vocabulary', v_left,
    'in_taxonomy_vocab', (select count(*) from public.leads
                           where invite_trades && (select array_agg(code) from public.taxonomy_trade)));
end

fn_leads_derive_owner_email_verified:
begin
  -- Only when an address is newly attached or changed. A later edit of an unrelated column must
  -- not re-run this, and it must never REVOKE a verification an OTP sign-in has already granted.
  if NEW.claimed_by is null then return NEW; end if;
  if TG_OP = 'UPDATE' and NEW.claimed_by is not distinct from OLD.claimed_by then return NEW; end if;
  if coalesce(NEW.owner_email_verified, false) then return NEW; end if;

  if exists (
    select 1 from email_verifications
    where email = lower(NEW.claimed_by)
      and purpose = 'login'
      and used_at is not null
  ) then
    NEW.owner_email_verified := true;
  end if;
  return NEW;
end

fn_agent_actions_fill_alternatives:
declare
  -- WAS `d record`. A record that is never assigned raises 55000 on the first field reference;
  -- these three are null when the lookup is skipped, and null is answerable.
  v_alts     jsonb;
  v_decision text;
  v_amt      text;
begin
  -- Nothing to do once every field the caller could supply is already there.
  if NEW.alternatives is not null and NEW.assumptions is not null
     and NEW.expected_impact is not null and NEW.cost is not null then
    return NEW;
  end if;

  if NEW.decision_log_id is not null then
    select l.alternatives, l.decision into v_alts, v_decision
      from public.decision_log l where l.id = NEW.decision_log_id;
  end if;

  if NEW.alternatives is null
     and v_alts is not null
     and v_alts::text not in ('null', '[]', '{}') then
    NEW.alternatives := v_alts;
  end if;

  if NEW.assumptions is null then
    NEW.assumptions := jsonb_build_array(
      'The action context recorded in detail is accurate as supplied by ' || coalesce(NEW.agent, 'the agent') || '.',
      'fn_should_escalate and fn_authorize were evaluated on that context'
        || case when v_decision is not null then ' and returned ' || v_decision || '.' else '.' end);
  end if;

  if NEW.expected_impact is null then
    NEW.expected_impact := case
      when coalesce(NEW.status, '') in ('needs_review', 'held_for_review')
        then 'Held: nothing changes until a human decides. Until then the condition this action reports remains as it is.'
      else 'Proceeds as recommended: ' || left(coalesce(NEW.recommendation, NEW.title, 'the recommended action'), 220) end;
  end if;

  if NEW.cost is null then
    begin
      v_amt := nullif(to_jsonb(NEW.detail) ->> 'amount_aed', '');
      if v_amt is null then v_amt := nullif(to_jsonb(NEW.detail) ->> 'amount', ''); end if;
    exception when others then v_amt := null; end;
    NEW.cost := case when v_amt is not null
      then 'AED ' || v_amt || ' — the amount carried in this action''s own context.'
      else 'No spend is recorded in this action''s context; the cost is the reviewer''s time.' end;
  end if;

  return NEW;
end

