fn_founder_apply_setting:
declare r record; v_old text; v_new text; v_num numeric; v_bool boolean; v_refusal text;
begin
  select * into r from public.fn_founder_settings() s where s.setting_key = p_key;

  if not found then
    v_refusal := 'I cannot change "' || coalesce(p_key,'(nothing)') || '" from a message. '
              || 'The settings I can change this way are: '
              || (select string_agg(s.setting_key, ', ' order by s.setting_key) from public.fn_founder_settings() s)
              || '. Money, refunds and the three go-live switches are deliberately not on that list.';
    insert into public.founder_directive(actor, channel, inbound, setting_key, applied, refusal)
    values (p_actor, p_channel, left(coalesce(p_inbound,''), 2000), p_key, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  v_old := r.current_value;

  -- TYPE AND BOUNDS. A mistyped number must not become an incident before anyone reads the reply.
  if r.kind in ('int','number') then
    begin v_num := p_value::numeric; exception when others then
      v_refusal := '"' || p_value || '" is not a number, and ' || p_key || ' takes one.'; end;
    if v_refusal is null and r.kind = 'int' and v_num <> trunc(v_num) then
      v_refusal := p_key || ' takes a whole number; "' || p_value || '" is not one.';
    end if;
    if v_refusal is null and r.min_val is not null and v_num < r.min_val then
      v_refusal := p_key || ' has a floor of ' || r.min_val || ' on this channel, and you asked for ' || v_num || '.';
    end if;
    if v_refusal is null and r.max_val is not null and v_num > r.max_val then
      v_refusal := p_key || ' has a ceiling of ' || r.max_val || ' on this channel, and you asked for ' || v_num
                || '. Change it in the OS if you really mean that.';
    end if;
    v_new := case when r.kind = 'int' then trunc(v_num)::bigint::text else v_num::text end;
  elsif r.kind = 'bool' then
    v_bool := case lower(btrim(p_value))
                when 'true' then true when 'on' then true when 'yes' then true when 'enable' then true when 'enabled' then true when '1' then true
                when 'false' then false when 'off' then false when 'no' then false when 'disable' then false when 'disabled' then false when '0' then false
                else null end;
    if v_bool is null then v_refusal := '"' || p_value || '" is not on or off, and ' || p_key || ' is a switch.';
    else v_new := case when v_bool then 'true' else 'false' end; end if;
  else
    v_new := p_value;
  end if;

  if v_refusal is not null then
    insert into public.founder_directive(actor, channel, inbound, setting_key, old_value, applied, refusal)
    values (p_actor, p_channel, left(coalesce(p_inbound,''), 2000), p_key, v_old, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal, 'key', p_key, 'old', v_old);
  end if;

  if v_old is not distinct from v_new then
    insert into public.founder_directive(actor, channel, inbound, setting_key, old_value, new_value, applied, refusal)
    values (p_actor, p_channel, left(coalesce(p_inbound,''), 2000), p_key, v_old, v_new, false, 'already at that value');
    return jsonb_build_object('ok', true, 'unchanged', true, 'key', p_key, 'old', v_old, 'new', v_new,
      'message', p_key || ' is already ' || v_new || '. Nothing to change.');
  end if;

  if r.store = 'app_secrets' then
    update public.app_secrets set value = v_new, updated_at = now() where key = p_key;
  else
    update public.decision_policy set value = to_jsonb(v_new), updated_at = now() where key = p_key;
    -- decision_policy holds real jsonb types, not strings: keep numbers as numbers.
    if r.kind in ('int','number') then
      update public.decision_policy set value = to_jsonb(v_new::numeric) where key = p_key;
    elsif r.kind = 'bool' then
      update public.decision_policy set value = to_jsonb(v_new::boolean) where key = p_key;
    end if;
  end if;

  insert into public.founder_directive(actor, channel, inbound, setting_key, old_value, new_value, applied)
  values (p_actor, p_channel, left(coalesce(p_inbound,''), 2000), p_key, v_old, v_new, true);

  insert into public.agent_runs(agent, status, counts, note, started_at, finished_at)
  values ('founder_directive', 'ok',
          jsonb_build_object('key', p_key, 'old', v_old, 'new', v_new, 'channel', p_channel),
          'The founder changed ' || p_key || ' from ' || coalesce(v_old,'(unset)') || ' to ' || v_new
          || ' by ' || p_channel || '. Instruction: ' || left(coalesce(p_inbound,''), 200), now(), now());

  return jsonb_build_object('ok', true, 'key', p_key, 'old', v_old, 'new', v_new,
    'message', 'Done — ' || p_key || ' changed from ' || coalesce(v_old,'(unset)') || ' to ' || v_new || '. ' || r.description);
end

fn_supplier_apply_change:
declare v_lead bigint; v_num numeric; v_q record; v_n int; v_refusal text; v_old numeric; v_list text;
        v_company text;
begin
  -- SCOPE FIRST, AND FROM THE PHONE. Nothing downstream takes a supplier id from the caller.
  v_lead := public.fn_wa_lead_id(p_phone);
  if v_lead is null then
    insert into public.channel_directive(actor_type, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, 'no supplier account matches this number');
    return jsonb_build_object('ok', false, 'refusal',
      'This number is not linked to a supplier account, so there is nothing of yours I can change. Sign in at https://quotesdone.com/suppliers.');
  end if;
  select company_name into v_company from public.leads where id = v_lead;

  if not exists (select 1 from public.fn_supplier_changeable() c where c.field = p_field) then
    v_refusal := 'I cannot change "' || coalesce(p_field,'(nothing)') || '" from a message. What I can change this way: '
              || (select string_agg(c.field, ', ' order by c.field) from public.fn_supplier_changeable() c)
              || '. Everything else — your licence, your company details, and generating a new quotation — is in the portal.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  begin v_num := p_value::numeric; exception when others then v_num := null; end;
  if v_num is null or v_num <= 0 then
    v_refusal := '"' || coalesce(p_value,'') || '" is not an amount I can put on a quotation.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  -- WHICH QUOTATION. Editable means: theirs, still open, nobody has paid to reveal them, not
  -- committed, not already accepted. Each of those is a different reason and each gets said.
  select count(*) into v_n
    from public.quotes q
    join public.inquiries i on i.id = q.inquiry_id
   where q.supplier_id = v_lead
     and (p_quote_id is null or q.id = p_quote_id)
     and q.committed_at is null
     and coalesce(q.status,'') not in ('accepted','withdrawn','expired')
     and coalesce(i.status,'') not in ('concluded','closed','cancelled','awarded')
     and not exists (select 1 from public.transactions t
                      where t.inquiry_id = q.inquiry_id and t.supplier_id = q.supplier_id
                        and t.revealed_at is not null);

  if v_n = 0 then
    -- Say WHY there is nothing to change rather than "no quotation found", which is true of a
    -- supplier who has never quoted and of one whose customer paid an hour ago.
    select string_agg(distinct r, '; ') into v_refusal from (
      select case
               when q.committed_at is not null then 'one is committed and cannot be re-priced'
               when coalesce(q.status,'') = 'accepted' then 'one has already been accepted'
               when exists (select 1 from public.transactions t where t.inquiry_id = q.inquiry_id
                             and t.supplier_id = q.supplier_id and t.revealed_at is not null)
                 then 'the customer has already paid to reveal you on one, so the price they paid to see stands'
               else 'the request is closed on one' end as r
        from public.quotes q where q.supplier_id = v_lead
         and (p_quote_id is null or q.id = p_quote_id)) z;
    v_refusal := coalesce('I cannot change a price right now: ' || v_refusal || '.',
                          'You have no open quotation for me to re-price. You can send a new one from the portal.');
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  if v_n > 1 then
    select string_agg(i.category || ' in ' || coalesce(i.emirate,'the UAE') || ' (currently AED ' || q.quote_amount || ')', '; ' order by q.created_at desc)
      into v_list
      from public.quotes q join public.inquiries i on i.id = q.inquiry_id
     where q.supplier_id = v_lead and q.committed_at is null
       and coalesce(q.status,'') not in ('accepted','withdrawn','expired');
    v_refusal := 'You have ' || v_n || ' open quotations, so I will not guess which one you mean: ' || v_list
              || '. Tell me which, or change it in the portal.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal, 'open_quotes', v_n);
  end if;

  select q.* into v_q
    from public.quotes q join public.inquiries i on i.id = q.inquiry_id
   where q.supplier_id = v_lead
     and (p_quote_id is null or q.id = p_quote_id)
     and q.committed_at is null
     and coalesce(q.status,'') not in ('accepted','withdrawn','expired')
     and coalesce(i.status,'') not in ('concluded','closed','cancelled','awarded')
     and not exists (select 1 from public.transactions t
                      where t.inquiry_id = q.inquiry_id and t.supplier_id = q.supplier_id
                        and t.revealed_at is not null);
  v_old := v_q.quote_amount;

  -- THE FAT-FINGER BOUND. A supplier may price their own work at whatever they like — that is
  -- their commercial decision and not ours. But this arrives as a sentence typed on a phone, where
  -- a missing or extra zero is one keystroke, and a quotation is a number a customer will compare
  -- against others and pay to unlock. Beyond half up or half down, the portal asks for it twice.
  if v_old is not null and v_old > 0 and (v_num > v_old * 1.5 or v_num < v_old * 0.5) then
    v_refusal := 'That would move the price from AED ' || v_old || ' to AED ' || v_num
              || ', which is more than half up or down. I have not changed it — if you do mean that, please set it in the portal so you can see the whole quotation while you do.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, target_id, old_value, new_value, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, v_q.id::text, v_old::text, v_num::text, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal, 'old', v_old, 'asked', v_num);
  end if;

  if v_old is not distinct from v_num then
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, target_id, old_value, new_value, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, v_q.id::text, v_old::text, v_num::text, false, 'already at that value');
    return jsonb_build_object('ok', true, 'unchanged', true, 'old', v_old, 'new', v_num,
      'message', 'Your quotation is already AED ' || v_num || '. Nothing to change.');
  end if;

  update public.quotes set quote_amount = v_num where id = v_q.id;

  insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, target_id, old_value, new_value, applied)
  values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, v_q.id::text, v_old::text, v_num::text, true);

  insert into public.agent_runs(agent, status, counts, note, started_at, finished_at)
  values ('supplier_directive', 'ok',
          jsonb_build_object('lead_id', v_lead, 'quote_id', v_q.id, 'old', v_old, 'new', v_num, 'channel', p_channel),
          coalesce(v_company,'lead ' || v_lead) || ' changed a quotation from AED ' || coalesce(v_old::text,'(unset)')
          || ' to AED ' || v_num || ' by ' || p_channel || '. Instruction: ' || left(coalesce(p_inbound,''),200),
          now(), now());

  return jsonb_build_object('ok', true, 'quote_id', v_q.id, 'old', v_old, 'new', v_num,
    'message', 'Done — your quotation is now AED ' || v_num || ' (it was AED ' || coalesce(v_old::text,'unset') || '). The customer sees the new price from now on.');
end

fn_scenario_rehearse:
declare
  s public.scenario_library%rowtype;
  v_facts jsonb := '[]'::jsonb;
  v_missing text[] := '{}';
  v_verdict text;
  v_answer text;
  v_burn numeric; v_calls int; v_spend30 numeric;
  v_committed numeric; v_top_dept text; v_top_aed numeric; v_runway text;
  v_meta_spend numeric; v_meta_results int; v_contribution text;
  v_plan public.continuity_plan%rowtype;
  v_owner text; v_gated boolean; v_gated_names text; v_incidents int;
  v_dup_blocked boolean; v_fraud_rows int;
begin
  select * into s from public.scenario_library where scenario_key = p_scenario_key;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'no scenario ' || p_scenario_key);
  end if;

  if p_scenario_key = 'openrouter_outage' then
    select round(sum(cost_aed), 2), count(*) into v_spend30, v_calls
      from public.ai_cost_log where occurred_at > now() - interval '30 days';
    v_burn := round(coalesce(v_spend30, 0) / 30.0, 2);
    select * into v_plan from public.continuity_plan where service = 'OpenRouter';
    v_facts := v_facts
      || jsonb_build_array(jsonb_build_object('fact', 'burn rate per day (AED)', 'produced', v_burn is not null, 'value', v_burn))
      || jsonb_build_array(jsonb_build_object('fact', '30-day AI spend (AED)', 'produced', v_spend30 is not null, 'value', v_spend30))
      || jsonb_build_array(jsonb_build_object('fact', 'documented fallback', 'produced', coalesce(btrim(v_plan.fallback),'') <> '', 'value', v_plan.fallback))
      || jsonb_build_array(jsonb_build_object('fact', 'task classes that survive without a model',
           'produced', true,
           'value', (select count(*) from public.model_policy
                      where coalesce(active,true)
                        and (coalesce(deterministic_alternative,'') <> '' or tier = 'none'))))
      || jsonb_build_array(jsonb_build_object('fact', 'remaining provider balance', 'produced', false,
           'value', 'not a database fact — held by the provider and not mirrored here'));
    v_answer := 'AI spend over 30 days is AED ' || coalesce(v_spend30::text,'?') || ' across '
      || coalesce(v_calls::text,'?') || ' call(s), a burn of AED ' || coalesce(v_burn::text,'?')
      || '/day. ' || (select count(*) from public.model_policy
                       where coalesce(active,true) and (coalesce(deterministic_alternative,'') <> '' or tier='none'))
      || ' of ' || (select count(*) from public.model_policy where coalesce(active,true))
      || ' active task class(es) still run with no model at all. The two failure modes are distinct: '
      || 'provider unreachable (retry/fallback applies) versus shared balance exhausted (no retry helps). '
      || 'The remaining balance is not mirrored in this database, so it is named as unavailable rather than guessed.';

  elsif p_scenario_key = 'supabase_outage' then
    select * into v_plan from public.continuity_plan where service = 'Supabase';
    v_facts := v_facts
      || jsonb_build_array(jsonb_build_object('fact', 'which project is answering', 'produced', true,
           'value', current_setting('cluster_name', true)))
      || jsonb_build_array(jsonb_build_object('fact', 'documented RTO (minutes)', 'produced', v_plan.rto_minutes is not null, 'value', v_plan.rto_minutes))
      || jsonb_build_array(jsonb_build_object('fact', 'documented degraded mode', 'produced', coalesce(btrim(v_plan.degraded_mode),'') <> '', 'value', v_plan.degraded_mode))
      || jsonb_build_array(jsonb_build_object('fact', 'surfaces that answer without this database', 'produced', false,
           'value', 'none — every edge function, cron job and console read goes through it. A rehearsal executed INSIDE the database cannot observe its own outage.'));
    v_answer := 'This rehearsal runs inside the database it is asked about, so it can state the '
      || 'documented position and not the live one: RTO ' || coalesce(v_plan.rto_minutes::text,'?')
      || ' minutes, degraded mode "' || coalesce(v_plan.degraded_mode,'(none recorded)')
      || '". Both projects are separate Supabase instances, so a regional failure affects them '
      || 'independently — but nothing here can answer WHICH is down while it is down. That is a real '
      || 'gap in the plan, not a rehearsal failure, and it is recorded as such.';

  elsif p_scenario_key = 'cash_flow_reduction' then
    select sum(monthly_aed) into v_committed from public.department_budget;
    select dept_key, monthly_aed into v_top_dept, v_top_aed
      from public.department_budget order by monthly_aed desc nulls last limit 1;
    select round(sum(cost_aed), 2) into v_spend30
      from public.ai_cost_log where occurred_at > now() - interval '30 days';
    v_runway := 'not computable — no cash balance is recorded anywhere in this database, so a runway '
             || 'in days would be a division by a number nobody has measured';
    v_facts := v_facts
      || jsonb_build_array(jsonb_build_object('fact', 'committed monthly spend (AED)', 'produced', v_committed is not null, 'value', v_committed))
      || jsonb_build_array(jsonb_build_object('fact', 'largest single cost', 'produced', v_top_dept is not null,
           'value', v_top_dept || ' at AED ' || coalesce(v_top_aed::text,'?') || '/month'))
      || jsonb_build_array(jsonb_build_object('fact', 'recognised revenue (AED, 30d)', 'produced', true,
           'value', (select coalesce(sum(coalesce(reveal_fee, app_fee, 0)), 0) from public.transactions
                      where revealed_at > now() - interval '30 days')))
      || jsonb_build_array(jsonb_build_object('fact', 'runway in days', 'produced', false, 'value', v_runway));
    v_answer := 'Committed monthly spend is AED ' || coalesce(v_committed::text,'?') || ' across '
      || (select count(*) from public.department_budget) || ' department budget(s); the largest single '
      || 'cost is ' || coalesce(v_top_dept,'?') || ' at AED ' || coalesce(v_top_aed::text,'?')
      || '/month. AI spend over 30 days was AED ' || coalesce(v_spend30::text,'0')
      || '. Recognised revenue over the same window is AED '
      || (select coalesce(sum(coalesce(reveal_fee, app_fee, 0)), 0) from public.transactions
           where revealed_at > now() - interval '30 days')
      || ', so every cost is funded rather than earned and no projection is made on a revenue line '
      || 'that has never produced. Runway: ' || v_runway || '.';

  elsif p_scenario_key = 'campaign_failure' then
    select meta_spend_30d, meta_results_30d into v_meta_spend, v_meta_results from public.marketing_kpis limit 1;
    v_contribution := case
      when coalesce(v_meta_results, 0) = 0 and coalesce(v_meta_spend, 0) = 0
        then 'AED 0 spent and 0 results — the channel is contributing nothing, so there is nothing to lose'
      when coalesce(v_meta_results, 0) = 0
        then 'AED ' || v_meta_spend || ' spent for 0 results — measured contribution is zero'
      else 'AED ' || coalesce(v_meta_spend,0) || ' spent for ' || v_meta_results || ' result(s)' end;
    v_facts := v_facts
      || jsonb_build_array(jsonb_build_object('fact', 'measured campaign spend (30d)', 'produced', v_meta_spend is not null, 'value', v_meta_spend))
      || jsonb_build_array(jsonb_build_object('fact', 'measured campaign results (30d)', 'produced', v_meta_results is not null, 'value', v_meta_results))
      || jsonb_build_array(jsonb_build_object('fact', 'measured contribution', 'produced', true, 'value', v_contribution))
      || jsonb_build_array(jsonb_build_object('fact', 'customers attributable to the channel', 'produced', true,
           'value', (select count(*) from public.customers)));
    v_answer := 'Measured contribution first: ' || v_contribution || '. Only then the projection — '
      || 'and a channel whose measured contribution is zero cannot be reported as a risk of losing '
      || 'something. Total customers on the book: ' || (select count(*) from public.customers) || '.';

  elsif p_scenario_key = 'security_incident' then
    select lead_agent into v_owner from public.org_departments where dept_key = 'it' and coalesce(active,true);
    -- THE QUESTION THE SCENARIO ACTUALLY ASKS. It says the founder is notified "via the gated
    -- security_incident_executive path"; that string is prose and is implemented by NO routine.
    -- What matters is whether an ACTIVE executor exists that reaches a human on the security or
    -- escalation path — escalate_founder and security_review both do, both notifies_human.
    -- Matching the literal name reported a defect that does not exist.
    select count(*) > 0,
           string_agg(action_class, ', ' order by action_class)
      into v_gated, v_gated_names
      from public.org_action_executor
     where active and notifies_human
       and action_class ~* '(security|incident|escalate_founder|breach)';
    select count(*) into v_incidents from public.founder_alerts
     where created_at > now() - interval '90 days' and (coalesce(event,'') ~* 'security|incident|breach');
    v_facts := v_facts
      || jsonb_build_array(jsonb_build_object('fact', 'named response owner', 'produced', coalesce(btrim(v_owner),'') <> '', 'value', v_owner))
      || jsonb_build_array(jsonb_build_object('fact', 'gated executive notification path exists', 'produced', v_gated, 'value', v_gated_names))
      || jsonb_build_array(jsonb_build_object('fact', 'security alerts raised in 90d', 'produced', true, 'value', v_incidents))
      || jsonb_build_array(jsonb_build_object('fact', 'security scan is scheduled and active', 'produced', true,
           'value', (select count(*) from cron.job where active and command ~* 'security_scan')));
    v_answer := 'Response owner: ' || coalesce(v_owner, '(none named on the IT department)')
      || '. Gated executive path(s) that reach a human: ' || coalesce(v_gated_names, '(none)')
      || '. ' || v_incidents || ' security alert(s) reached the founder in 90 days, and '
      || (select count(*) from cron.job where active and command ~* 'security_scan')
      || ' active security scan job(s) are scheduled.';

  elsif p_scenario_key = 'duplicate_payment' then
    select count(*) into v_fraud_rows from public.fraud_flags;
    select exists (select 1 from pg_constraint c join pg_class t on t.oid = c.conrelid
                    where t.relname = 'reveal_invoices' and c.contype in ('p','u'))
      into v_dup_blocked;
    v_facts := v_facts
      || jsonb_build_array(jsonb_build_object('fact', 'a uniqueness constraint blocks a second invoice', 'produced', v_dup_blocked, 'value', v_dup_blocked))
      || jsonb_build_array(jsonb_build_object('fact', 'fraud flags on file', 'produced', true, 'value', v_fraud_rows))
      || jsonb_build_array(jsonb_build_object('fact', 'money invariants run on a schedule', 'produced', true,
           'value', (select count(*) from cron.job where active and command ~* 'money_tests')))
      || jsonb_build_array(jsonb_build_object('fact', 'refund path is single-entry', 'produced', true,
           'value', (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace
                      where n.nspname='public' and p.proname ~* 'refund')));
    v_answer := 'A uniqueness constraint on reveal_invoices blocks a second invoice for the same '
      || 'transaction: ' || v_dup_blocked::text || '. ' || v_fraud_rows || ' fraud flag(s) on file; '
      || (select count(*) from cron.job where active and command ~* 'money_tests')
      || ' scheduled money-invariant job(s).';

  else
    return jsonb_build_object('ok', true, 'scenario_key', p_scenario_key, 'rehearsed', false,
      'reason', 'no rehearsal is defined for this scenario; last_run deliberately left untouched');
  end if;

  select coalesce(array_agg(e->>'fact'), '{}') into v_missing
    from jsonb_array_elements(v_facts) e where (e->>'produced')::boolean is not true;

  v_verdict := case when array_length(v_missing, 1) is null then 'answered' else 'incomplete' end;

  update public.scenario_library
     set last_run = now(),
         last_result = upper(v_verdict) || ' — ' || v_answer
           || case when array_length(v_missing, 1) is null then ''
                   else ' FACTS THAT COULD NOT BE PRODUCED: ' || array_to_string(v_missing, '; ') || '.' end
           || ' (Rehearsed ' || to_char(now() at time zone 'utc', 'YYYY-MM-DD HH24:MI')
           || ' UTC by fn_scenario_rehearse, computing the answer from live rows.)'
   where scenario_key = p_scenario_key;

  return jsonb_build_object('ok', true, 'scenario_key', p_scenario_key, 'rehearsed', true,
    'verdict', v_verdict, 'facts', v_facts, 'missing', to_jsonb(v_missing), 'answer', v_answer);
end

fn_scenario_rehearse_all:
declare k text; v jsonb; n_ans int := 0; n_inc int := 0; n_skip int := 0; out_j jsonb := '[]'::jsonb;
begin
  for k in select scenario_key from public.scenario_library order by scenario_key loop
    v := public.fn_scenario_rehearse(k);
    if coalesce((v->>'rehearsed')::boolean, false) then
      if v->>'verdict' = 'answered' then n_ans := n_ans + 1; else n_inc := n_inc + 1; end if;
      out_j := out_j || jsonb_build_array(jsonb_build_object('scenario_key', k, 'verdict', v->>'verdict'));
    else
      n_skip := n_skip + 1;
    end if;
  end loop;

  insert into public.agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('scenario_rehearsal', now(), now(), case when n_inc > 0 then 'error' else 'ok' end,
          jsonb_build_object('answered', n_ans, 'incomplete', n_inc, 'no_rehearsal_defined', n_skip),
          'Rehearsed ' || (n_ans + n_inc) || ' failure scenario(s) by posing each one and computing '
          || 'the required answer from live rows: ' || n_ans || ' produced every fact the scenario '
          || 'asks for, ' || n_inc || ' could not and name what is missing. ' || n_skip
          || ' scenario(s) have no rehearsal defined and were left untouched — last_run is not set '
          || 'for a scenario nobody exercised.');

  return jsonb_build_object('answered', n_ans, 'incomplete', n_inc,
    'no_rehearsal_defined', n_skip, 'scenarios', out_j);
end

trg_invite_cap_allocation:
declare v_old numeric; v_new numeric;
begin
  if new.key <> 'invite_daily_cap' then return new; end if;

  -- A non-numeric or absent value is not a reallocation; nothing is recorded rather than guessed.
  begin
    v_old := nullif(btrim(coalesce(old.value, '')), '')::numeric;
    v_new := nullif(btrim(coalesce(new.value, '')), '')::numeric;
  exception when others then
    return new;
  end;
  if v_old is null or v_new is null then return new; end if;

  -- A move to the same number moved nothing. s23-reallocation-policy-cited counts a no-op as a
  -- finding, correctly, so one is never written.
  if v_old is not distinct from v_new then return new; end if;

  insert into public.allocation_change (resource, subject, from_value, to_value, reason, policy)
  values ('supplier_onboarding_capacity', 'invite_daily_cap', v_old, v_new,
          case when v_new > v_old
               then 'Daily supplier-invite capacity raised from ' || v_old || ' to ' || v_new
                    || '. Deliverability is inside tolerance, so more onboarding capacity is released.'
               else 'Daily supplier-invite capacity reduced from ' || v_old || ' to ' || v_new
                    || '. Bounce rate is above tolerance, so onboarding capacity is withdrawn to '
                    || 'protect the sending domain.' end,
          'invite ramp: capacity follows the measured 7-day bounce rate against invite_max_bounce_rate, '
          || 'warming at most 2x per day, floored at the base cap and ceilinged by the volume stage');
  return new;
end

fn_agent_context_head_refresh:
declare
  r record; v_head text; v_md5 text; v_prev text;
  n_seen int := 0; n_changed int := 0; n_failed int := 0;
begin
  -- Only employees that have actually reasoned recently. Refreshing all 93 would spend a minute of
  -- CPU an hour building prefixes nothing reads; an employee that starts working is picked up on
  -- the next tick and serves live context until then, which is what it gets today anyway.
  for r in
    select distinct c.agent_key
      from ai_cost_log c
     where c.fn = 'agent_brain' and c.agent_key is not null
       and c.occurred_at > now() - interval '14 days'
  loop
    begin
      v_head := left(public.fn_agent_context(r.agent_key, 24000), 19500);
      if v_head is null or length(v_head) < 500 then n_failed := n_failed + 1; continue; end if;
      n_seen := n_seen + 1;
      v_md5  := md5(v_head);
      -- Read the prior hash BEFORE the upsert: asking afterwards always says "unchanged", because
      -- the upsert has already written the value being compared against.
      select h.head_md5 into v_prev from agent_context_head h where h.agent_key = r.agent_key;
      if v_prev is distinct from v_md5 then n_changed := n_changed + 1; end if;
      insert into agent_context_head (agent_key, head, head_md5, head_chars)
      values (r.agent_key, v_head, v_md5, length(v_head))
      on conflict (agent_key) do update
        set head       = excluded.head,
            head_md5   = excluded.head_md5,
            head_chars = excluded.head_chars,
            built_at   = now(),
            changed_at = case when agent_context_head.head_md5 = excluded.head_md5
                              then agent_context_head.changed_at else now() end;
    exception when others then
      -- One employee whose context cannot be built must not stop the other thirteen.
      n_failed := n_failed + 1;
    end;
  end loop;
  return jsonb_build_object('refreshed', n_seen, 'changed', n_changed, 'failed', n_failed);
end

fn_knowledge_rollback:
declare
  v_deleted int := 0;
  v_restored int := 0;
  r record;
begin
  if not exists (select 1 from knowledge_ingestion_run where run_id = p_run) then
    raise exception 'unknown ingestion run %', p_run;
  end if;

  for r in select * from knowledge_ingestion_undo where run_id = p_run and table_name = 'ops_knowledge' loop
    if r.existed then
      -- put the stored row back exactly as it was
      delete from ops_knowledge where record_id = r.key;
      insert into ops_knowledge select * from jsonb_populate_record(null::ops_knowledge, r.prev_row);
      v_restored := v_restored + 1;
    else
      delete from ops_knowledge where record_id = r.key;
      v_deleted := v_deleted + 1;
    end if;
  end loop;

  for r in select * from knowledge_ingestion_undo where run_id = p_run and table_name = 'agent_training_case' loop
    if r.existed then
      delete from agent_training_case where case_id = r.key;
      insert into agent_training_case select * from jsonb_populate_record(null::agent_training_case, r.prev_row);
      v_restored := v_restored + 1;
    else
      delete from agent_training_case where case_id = r.key;
      v_deleted := v_deleted + 1;
    end if;
  end loop;

  update knowledge_ingestion_run set status = 'rolled_back' where run_id = p_run;
  delete from knowledge_ingestion_undo where run_id = p_run;
  return jsonb_build_object('run_id', p_run, 'deleted', v_deleted, 'restored', v_restored);
end

fn_record_context_retrieval:
declare v_id bigint;
begin
  insert into agent_context_retrieval
    (agent_key, task_class, category_key, knowledge_ids, knowledge_count, budget_chars, chars_returned)
  values (p_agent_key, p_task_class, p_category, coalesce(p_ids,'{}'),
          coalesce(array_length(p_ids,1),0), p_budget, p_chars)
  returning id into v_id;

  if coalesce(array_length(p_ids, 1), 0) > 0 then
    insert into kb_usage_log (agent, query, category)
    values (p_agent_key,
            'context assembly: ' || coalesce(array_length(p_ids,1), 0) || ' knowledge record(s) — '
              || left(array_to_string(p_ids[1:5], ', '), 400),
            coalesce(p_category, p_task_class, 'context_assembly'));
