  return v_id;
end

fn_category_checklist:
declare
  v_decide   jsonb;
  v_num      integer;
  v_cat_key  text;
  v_route    record;
  v_curated  jsonb;
  v_bank     jsonb;
  v_policy   jsonb;
  v_resolved text;
begin
  -- 1. curated fields for the customer-facing slug, if the company has any
  select fields into v_curated from category_specs where category = p_category limit 1;

  -- 2a. a system category slug the company assigned resolves deterministically; only
  --     customer prose goes to the language resolver.
  select catalog_num into v_num from category_route_map where category = p_category;
  if v_num is not null then v_resolved := 'category_route_map'; end if;

  -- 2b. resolve to a catalogue route using the existing resolver, not a new matcher
  if v_num is null then
  v_decide := fn_kb_route_decide(coalesce(nullif(btrim(concat_ws(' ', p_label, p_category, p_text)), ''), p_category));
  v_num := nullif(v_decide->>'catalog_num', '')::integer;
  v_resolved := 'route_decider';
  end if;
  if v_num is null then
    -- the decider asked for clarification; take its top candidate only when it is unambiguous
    if coalesce(jsonb_array_length(v_decide->'candidates'), 0) = 1 then
      v_num := (v_decide->'candidates'->0->>'catalog_num')::integer;
      v_resolved := 'single_candidate';
    end if;
  end if;
  if v_num is null then
    select catalog_num into v_num from kb_operational_route
     where expected_catalog_slug = p_category or route_key = p_category limit 1;
    if v_num is not null then v_resolved := 'exact_slug'; end if;
  end if;

  if v_num is null then
    return jsonb_build_object(
      'category', p_category, 'route_resolved', false,
      'resolution', 'unresolved',
      'clarification', v_decide->>'clarification',
      'candidates', coalesce(v_decide->'candidates', '[]'::jsonb),
      'curated_fields', coalesce(v_curated, '[]'::jsonb),
      'packaged_questions', '[]'::jsonb, 'mandatory_fields', '[]'::jsonb,
      'never_infer', '[]'::jsonb, 'knowledge_ids', '[]'::jsonb);
  end if;

  select * into v_route from kb_operational_route where catalog_num = v_num;
  select category_key into v_cat_key from org_category_identity where catalog_num = v_num;

  -- 3. the packaged question bank for that route (field / question / mandatory / why)
  select structured_data->'questions' into v_bank
    from ops_knowledge
   where category_key = v_cat_key and runtime_eligible and supersession_state = 'current'
     and source_path like '%02_FIELD_AND_QUESTION_BANK_V2.yaml'
   limit 1;

  -- 4. the V3 minimum-sufficient policy: what must be answered, and what may never be guessed
  select structured_data into v_policy
    from ops_knowledge
   where category_key = v_cat_key and runtime_eligible and supersession_state = 'current'
     and source_path like '%02_MINIMUM_SUFFICIENT_QUESTION_POLICY_V3.yaml'
   limit 1;

  return jsonb_build_object(
    'category', p_category,
    'route_resolved', true,
    'resolution', v_resolved,
    'catalog_num', v_num,
    'route_key', v_route.route_key,
    'route_name', v_route.catalog_name,
    'category_key', v_cat_key,
    'coverage_status', v_route.coverage_status,
    'regulatory_coverage_status', v_route.regulatory_coverage_status,
    'curated_fields', coalesce(v_curated, '[]'::jsonb),
    'packaged_questions', coalesce(v_bank, '[]'::jsonb),
    'mandatory_fields', coalesce(v_policy->'mandatory_fields', '[]'::jsonb),
    'route_specific_fields', coalesce(v_policy->'route_specific_fields', '[]'::jsonb),
    'ask_order', coalesce(v_policy->'ask_order', '[]'::jsonb),
    'stop_rule', v_policy->>'stop_rule',
    'never_infer', coalesce(v_policy->'never_infer', '[]'::jsonb),
    'knowledge_ids', coalesce((
      select jsonb_agg(record_id) from ops_knowledge
       where category_key = v_cat_key and runtime_eligible and supersession_state = 'current'), '[]'::jsonb));
end

fn_category_quote_ready:
declare
  v_chk     jsonb;
  v_missing text[] := '{}';
  f         text;
begin
  v_chk := fn_category_checklist(p_category, p_label, null);
  if not (v_chk->>'route_resolved')::boolean then
    return jsonb_build_object('ready', false, 'reason', 'route_unresolved',
                              'clarification', v_chk->>'clarification',
                              'missing', '[]'::jsonb, 'checklist', v_chk);
  end if;
  for f in select jsonb_array_elements_text(v_chk->'mandatory_fields') loop
    if coalesce(p_spec, '{}'::jsonb) ->> f is null
       or btrim(coalesce(p_spec ->> f, '')) = '' then
      v_missing := v_missing || f;
    end if;
  end loop;
  return jsonb_build_object(
    'ready', coalesce(array_length(v_missing, 1), 0) = 0,
    'reason', case when coalesce(array_length(v_missing,1),0) = 0 then 'complete' else 'missing_mandatory_fields' end,
    'missing', to_jsonb(v_missing),
    'route_key', v_chk->>'route_key',
    'category_key', v_chk->>'category_key',
    'stop_rule', v_chk->>'stop_rule',
    'never_infer', v_chk->'never_infer',
    'knowledge_ids', v_chk->'knowledge_ids');
end

fn_assign_training:
declare v_roles text[]; v_dept text; v_rows jsonb;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if p_purpose not in ('practice','retest','drift_check') then
    raise exception 'purpose must be practice, retest or drift_check';
  end if;
  select array_agg(packaged_role_id) into v_roles from org_role_identity where agent_key = p_agent_key;
  select packaged_department into v_dept from org_role_identity where agent_key = p_agent_key limit 1;
  if v_roles is null then
    return jsonb_build_object('assigned', 0, 'reason', 'agent has no role identity');
  end if;

  with pool as (
    select c.case_id, c.case_family, c.competency, c.scope_key
      from agent_training_case c
     -- The parentheses matter: AND binds tighter than OR, so without them the competency
     -- filter applied only to the department branch and every role case slipped past it.
     where ((c.scope_type = 'role' and c.scope_key = any(v_roles))
         or (c.scope_type = 'department' and c.scope_key = v_dept))
       and (p_competency is null or c.competency = p_competency)
  ), unseen as (
    select p.* from pool p
     where not exists (select 1 from agent_training_attempt a
                        where a.agent_key = p_agent_key and a.case_id = p.case_id)
     order by md5(p.case_id || p_agent_key || p_purpose)     -- stable per (agent,purpose), not an ordered list
     limit greatest(coalesce(p_n, 5), 1)
  ), ins as (
    insert into agent_training_attempt (agent_key, case_id, purpose, competency)
    select p_agent_key, case_id, p_purpose, competency from unseen
    on conflict (agent_key, case_id, purpose) do nothing
    returning id, case_id
  )
  select jsonb_agg(jsonb_build_object('attempt_id', i.id, 'case_id', i.case_id,
                                      'payload', c.payload))
    into v_rows
    from ins i join agent_training_case c on c.case_id = i.case_id;

  return jsonb_build_object('assigned', coalesce(jsonb_array_length(v_rows), 0),
                            'purpose', p_purpose, 'cases', coalesce(v_rows, '[]'::jsonb));
end

fn_knowledge_freshness_sweep:
declare v_stale int; v_fresh int;
begin
  update ops_knowledge set source_freshness = 'stale'
   where review_after is not null and review_after < current_date
     and source_freshness <> 'stale';
  get diagnostics v_stale = row_count;
  update ops_knowledge set source_freshness = 'stable'
   where source_freshness = 'stale'
     and (review_after is null or review_after >= current_date);
  get diagnostics v_fresh = row_count;
  return jsonb_build_object('marked_stale', v_stale, 'restored', v_fresh, 'swept_at', now());
end

fn_open_remediation:
insert into agent_remediation (agent_key, failure_class, competency, detail, status)
values (p_agent_key, p_failure_class, p_competency, coalesce(p_detail,'{}'::jsonb), 'open')
returning id;

fn_propose_lesson:
declare
  v_id bigint;
  v_obs int := coalesce(jsonb_array_length(p_evidence->'observations'), 0);
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if p_agent_key is null or not exists (select 1 from org_agents where agent_key = p_agent_key) then
    raise exception 'unknown agent %', p_agent_key;
  end if;
  if coalesce(btrim(p_statement), '') = '' then
    raise exception 'a lesson needs a statement';
  end if;
  -- Two independent observations minimum. One outcome is an anecdote; the loop is allowed
  -- to record it as evidence but not to call it a lesson.
  if v_obs < 2 then
    return jsonb_build_object('accepted', false, 'reason', 'insufficient_evidence',
      'detail', format('a proposed lesson needs at least 2 observations; %s supplied', v_obs));
  end if;

  insert into agent_knowledge
    (agent_key, topic, content, priority, layer, source_ref, owner_agent, version,
     confidence, validation_status, review_due, valid_until, supporting_evidence)
  values (p_agent_key, p_topic, p_statement, 5, 'experience', 'learning_loop', p_agent_key, 1,
          least(coalesce(p_confidence, 0.5), 0.9), 'proposed',
          current_date + 30, p_valid_until, p_evidence::text)
  returning id into v_id;

  return jsonb_build_object('accepted', true, 'lesson_id', v_id, 'validation_status', 'proposed',
    'note', 'not retrievable until validated by someone other than its author');
end

fn_remediation_step:
declare r agent_remediation;
begin
  select * into r from agent_remediation where id = p_id for update;
  if r.id is null then raise exception 'unknown remediation %', p_id; end if;

  update agent_remediation
     set attempts = attempts + 1,
         cost_aed = cost_aed + coalesce(p_cost_aed, 0),
         baseline_score = coalesce(baseline_score, p_score),
         latest_score = p_score,
         status = case
           when p_score >= 0.8 and coalesce(baseline_score, p_score) <= p_score then 'passed'
           when attempts + 1 >= max_attempts or cost_aed + coalesce(p_cost_aed,0) >= max_cost_aed then 'escalated'
           else 'retesting' end,
         blocks_autonomy = not (p_score >= 0.8 and coalesce(baseline_score, p_score) <= p_score),
         closed_at = case when p_score >= 0.8 then now() else null end
   where id = p_id
   returning * into r;

  return jsonb_build_object('id', r.id, 'status', r.status, 'attempts', r.attempts,
                            'baseline', r.baseline_score, 'latest', r.latest_score,
                            'blocks_autonomy', r.blocks_autonomy, 'cost_aed', r.cost_aed);
end

fn_supersede_lesson:
begin
  update agent_knowledge set validation_status = 'superseded', supersedes_id = null,
         supporting_evidence = coalesce(supporting_evidence,'') || E'\n[superseded by ' || p_new || '] ' || coalesce(p_reason,''),
         updated_at = now()
   where id = p_old;
  update agent_knowledge set supersedes_id = p_old, updated_at = now() where id = p_new;
  return jsonb_build_object('ok', found, 'old', p_old, 'new', p_new);
end

fn_validate_lesson:
declare v agent_knowledge; v_mgr text;
begin
  p_validator := coalesce(public.fn_org_agent_resolve(p_validator), p_validator);
  select * into v from agent_knowledge where id = p_lesson_id;
  if v.id is null then raise exception 'unknown lesson %', p_lesson_id; end if;
  if v.validation_status <> 'proposed' then
    return jsonb_build_object('ok', false, 'reason', 'not_proposed', 'status', v.validation_status);
  end if;
  if p_validator = v.agent_key then
    return jsonb_build_object('ok', false, 'reason', 'self_validation_refused',
      'detail', 'the agent that proposed a lesson cannot be the one that validates it');
  end if;
  if p_verdict not in ('validated','rejected') then
    raise exception 'verdict must be validated or rejected, got %', p_verdict;
  end if;

  select manager_key into v_mgr from org_agents where agent_key = v.agent_key;
  update agent_knowledge
     set validation_status = p_verdict,
         updated_at = now(),
         supporting_evidence = coalesce(supporting_evidence, '') ||
           format(E'\n[%s by %s%s] %s', p_verdict, p_validator,
                  case when p_validator = v_mgr then ' (line manager)' else '' end,
                  coalesce(p_reason, ''))
   where id = p_lesson_id;
  return jsonb_build_object('ok', true, 'lesson_id', p_lesson_id, 'status', p_verdict,
                            'validator', p_validator, 'was_line_manager', p_validator = v_mgr);
end

fn_artifact_review_valid:
declare
  v_author   text;
  v_reviewer text;
begin
  -- Resolve BOTH sides before comparing. coalesce keeps an unrecognised identity as itself rather
  -- than turning it into null: null = null is null, and a guard that evaluates to null lets the
  -- row through.
  v_author   := coalesce(public.fn_org_agent_resolve(new.author_agent),   new.author_agent);
  v_reviewer := coalesce(public.fn_org_agent_resolve(new.reviewer_agent), new.reviewer_agent);

  if new.verdict = 'pass' then
    -- A PASS WITH NO REVIEWER IS WORSE THAN A SELF-REVIEW, and the previous guard permitted it:
    -- a null reviewer_agent is never equal to author_agent, so the comparison answered "not a
    -- self-review" and the row went in with nobody having looked at the artifact.
    if new.reviewer_agent is null or btrim(new.reviewer_agent) = '' then
      raise exception 'artifact % % cannot be marked pass with no reviewer recorded',
        new.subject_type, new.subject_id
        using errcode = 'check_violation';
    end if;

    if new.author_agent is not null and v_author = v_reviewer then
      raise exception
        'artifact_review refuses a self-review: author "%" and reviewer "%" are the same employee (%). %',
        new.author_agent, new.reviewer_agent, v_author,
        'Route the artifact to the QA path (ai_quality_reviewer) or to fn_pick_reviewer(dept, author).'
        using errcode = 'check_violation';
    end if;
  end if;

  -- Store both sides canonical, so every later count over this table measures employees and not
  -- spelling. Same discipline as trg_review_chain_no_self_review.
  new.author_agent   := case when new.author_agent   is null then null else v_author   end;
  new.reviewer_agent := case when new.reviewer_agent is null then null else v_reviewer end;
  return new;
end

fn_artifact_publish_blocked:
declare r artifact_review;
begin
  if p_sha256 is null or btrim(p_sha256) = '' then
    return jsonb_build_object('blocked', true, 'reason', 'no_artifact_digest',
      'detail', 'publishing needs the digest of the bytes that will be published');
  end if;
  select * into r from artifact_review
   where subject_type = p_subject_type and subject_id = p_subject_id
     and artifact_sha256 = p_sha256
   order by created_at desc limit 1;

  if r.id is null then
    return jsonb_build_object('blocked', true, 'reason', 'no_review_for_these_bytes',
      'detail', 'the artifact was never reviewed, or it changed after the review');
  end if;
  if r.verdict <> 'pass' then
    return jsonb_build_object('blocked', true, 'reason', 'review_failed',
      'failures', to_jsonb(r.failures), 'review_id', r.id);
  end if;
  return jsonb_build_object('blocked', false, 'review_id', r.id, 'reviewer', r.reviewer_agent,
                            'reviewed_at', r.created_at);
end

fn_category_readiness_recompute:
declare v jsonb;
begin
  update org_category_identity c
     set readiness = case
       when not exists (select 1 from ops_knowledge k where k.category_key = c.category_key
                          and k.runtime_eligible and k.supersession_state = 'current') then 'blocked'
       when (select (fn_category_checklist(r.expected_catalog_slug, r.catalog_name, null)->>'route_resolved')::boolean
               from kb_operational_route r where r.catalog_num = c.catalog_num) then 'decision_trace_connected'
       else 'knowledge_imported' end,
         updated_at = now();
  select jsonb_object_agg(readiness, n) into v
    from (select readiness, count(*) n from org_category_identity group by 1) s;
  return jsonb_build_object('counts', v);
end

trg_org_role_no_cycle:
declare v_cur text; v_depth int := 0;
begin
  if new.manager_role_id is null then return new; end if;
  v_cur := new.manager_role_id;
  while v_cur is not null and v_depth < 64 loop
    if v_cur = new.role_id then
      raise exception 'reporting cycle: % -> % would close a loop', new.role_id, new.manager_role_id;
    end if;
    select r.manager_role_id into v_cur from public.org_role r where r.role_id = v_cur;
    v_depth := v_depth + 1;
  end loop;
  if v_depth >= 64 then
    raise exception 'reporting chain deeper than 64 above %; refusing', new.role_id;
  end if;
  return new;
end

fn_org_role_agent:
with r as (select * from public.org_role where role_id = public.fn_org_role_resolve(p_any))
select coalesce(
  (select runtime_agent_key from r where runtime_mode <> 'knowledge_overlay'),
  (select m.runtime_agent_key from r join public.org_role m on m.role_id = r.manager_role_id),
  (select runtime_agent_key from r)
);

fn_role_manager_chain:
with recursive up as (
  select 0 as step, r.role_id, r.display_name, r.primary_department_id as department, r.manager_role_id
    from public.org_role r where r.role_id = public.fn_org_role_resolve(p_role)
  union all
  select u.step + 1, m.role_id, m.display_name, m.primary_department_id, m.manager_role_id
    from up u join public.org_role m on m.role_id = u.manager_role_id
   where u.step < 32
)
select step, role_id, display_name, department from up order by step;

fn_dept_scope:
select array(select p_dept
             union
             select d.dept_key from public.org_departments d where d.merged_into = p_dept);

fn_pick_reviewer:
declare v_head text; v_ok boolean; v_delegate text; v_basis text;
        v_head_tier text; v_head_score numeric; v_score numeric; v_up text;
begin
  -- THE AUTHOR ARRIVES UNDER WHATEVER NAME THE CALLER HAD (14 Aug 2026).
  -- Every comparison below is a raw string test - p_author = v_head, and three
  -- "a.agent_key is distinct from p_author" filters. All ten department heads carry aliases, so
  -- an author passed as 'finance_ai', 'marketplace_director' or 'CEO AI' was not equal to 'cfo',
  -- 'procurement' or 'ceo', the guard did not fire, and this function returned the author as its
  -- own reviewer. Measured on production before this line: 10 of 10 departments.
  -- Resolving once here fixes every comparison at the same time, because they all read p_author.
  p_author := coalesce(public.fn_org_agent_resolve(p_author), p_author);

  select lead_agent into v_head from org_departments where dept_key = p_dept_key;

  if v_head is null then
    return jsonb_build_object('reviewer', null, 'available', false,
      'basis', 'no lead_agent recorded for department ' || p_dept_key);
  end if;

  -- THE AUTHOR IS THE HEAD. Measured 14 Aug 2026: 285 of 1,882 review_chain rows had
  -- author_agent = reviewer_agent and 182 of those were approvals, because this function was only
  -- ever told the department and answered with its head. When the head wrote the work, review
  -- climbs: first to an independent reviewer inside the same department, then to the head's own
  -- manager. It never returns the author.
  if p_author is not null and p_author = v_head then
    select a.agent_key into v_delegate
      from org_agents a
      join org_role r on r.runtime_agent_key = a.agent_key and r.status = 'active'
     where a.department = p_dept_key and a.agent_key <> p_author
       and r.runtime_mode = 'independent_reviewer'
       and a.active and a.available and (a.unavailable_until is null or a.unavailable_until < current_date)
     order by a.agent_key limit 1;

    if v_delegate is not null then
      return jsonb_build_object('reviewer', v_delegate, 'available', true, 'delegated_from', v_head,
        'basis', 'the department head authored this work; review routed to the department''s '
                 || 'independent reviewer, which never approves its own output');
    end if;

    select m.agent_key into v_up
      from org_agents o join org_agents m on m.agent_key = o.manager_key and m.active
     where o.agent_key = v_head
       and m.available and (m.unavailable_until is null or m.unavailable_until < current_date);

    if v_up is not null and v_up <> p_author then
      return jsonb_build_object('reviewer', v_up, 'available', true, 'delegated_from', v_head,
        'basis', 'the department head authored this work and the department has no independent '
                 || 'reviewer available; review escalated one level up the reporting chain');
    end if;

    return jsonb_build_object('reviewer', null, 'available', false, 'delegated_from', v_head,
      'basis', 'the department head authored this work and no independent reviewer or manager is '
               || 'available - escalate rather than approve it');
  end if;

  select (a.active and a.available and (a.unavailable_until is null or a.unavailable_until < current_date))
    into v_ok from org_agents a where a.agent_key = v_head;

  select p.tier, p.score into v_head_tier, v_head_score
    from agent_reputation p where p.agent_key = v_head;

  if coalesce(v_ok, false) then
    if coalesce(v_head_tier, '') = 'probation' then
      select a.agent_key, p.score into v_delegate, v_score
        from org_agents a
        join agent_reputation p on p.agent_key = a.agent_key
       where a.department = p_dept_key and a.agent_key <> v_head
         and a.agent_key is distinct from p_author
         and a.active and a.available and (a.unavailable_until is null or a.unavailable_until < current_date)
         and p.tier <> 'probation' and p.score > coalesce(v_head_score, 0)
       order by p.score desc, a.agent_key
       limit 1;

      if v_delegate is not null then
        return jsonb_build_object('reviewer', v_delegate, 'available', true, 'delegated_from', v_head,
          'basis', 'department head ' || v_head || ' is on the probation reputation tier ('
                   || coalesce(v_head_score::text, '?') || '); review routed to the highest-scoring '
                   || 'available employee in ' || p_dept_key || ' (' || coalesce(v_score::text, '?') || ')');
      end if;
    end if;

    return jsonb_build_object('reviewer', v_head, 'available', true, 'delegated_from', null,
      'basis', 'department head (reputation ' || coalesce(v_head_score::text, 'unscored')
               || ', tier ' || coalesce(v_head_tier, 'unscored') || ')');
  end if;

  select d.delegate_to, d.basis into v_delegate, v_basis
  from delegation_rule d
  join org_agents a on a.agent_key = d.delegate_to
  where d.active and d.dept_key = p_dept_key and d.when_agent = v_head
    and a.agent_key is distinct from p_author
    and a.active and a.available and (a.unavailable_until is null or a.unavailable_until < current_date)
  order by d.rank limit 1;

  if v_delegate is null then
    select a.agent_key,
           'highest-scoring available employee in ' || p_dept_key
             || ' (reputation ' || coalesce(p.score::text, 'unscored') || ')'
      into v_delegate, v_basis
    from org_agents a
    left join agent_reputation p on p.agent_key = a.agent_key
    where a.department = p_dept_key and a.agent_key <> v_head
      and a.agent_key is distinct from p_author
      and a.active and a.available and (a.unavailable_until is null or a.unavailable_until < current_date)
      and coalesce(p.tier, 'standard') <> 'probation'
    order by p.score desc nulls last, fn_seniority_rank(a.seniority), a.agent_key
    limit 1;
  end if;

  if v_delegate is null then
    return jsonb_build_object('reviewer', null, 'available', false, 'delegated_from', v_head,
      'basis', 'department head unavailable and no delegate available - escalate');
  end if;

  return jsonb_build_object('reviewer', v_delegate, 'available', true,
    'delegated_from', v_head, 'basis', coalesce(v_basis, 'delegation'));
end;

fn_specialist_invoke:
declare v_mgr text; v_spec text; v_mode text; v_dept text; v_id bigint;
begin
  v_mgr  := public.fn_org_role_resolve(p_manager);
  v_spec := public.fn_org_role_resolve(p_specialist);
  if v_mgr is null then
    return jsonb_build_object('ok', false, 'error', 'unknown invoking role: '||p_manager);
  end if;
  if v_spec is null then
    return jsonb_build_object('ok', false, 'error', 'unknown specialist role: '||p_specialist);
  end if;

  select runtime_mode, primary_department_id into v_mode, v_dept from public.org_role where role_id = v_spec;

  -- A standing manager or an event-driven operator is not a tool: work goes to it by handoff, so
  -- that one accountable owner exists rather than two agents holding the same subject.
  if v_mode not in ('on_demand_specialist','knowledge_overlay','independent_reviewer') then
    return jsonb_build_object('ok', false, 'error',
      v_spec||' is a '||v_mode||'; invoke it by handoff (fn_role_handoff), not as a tool',
      'use', 'fn_role_handoff');
  end if;

  insert into public.review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                                   stage, decision, reason, confidence, delegation_basis)
  values (p_subject_type, p_subject_id, v_dept,
          public.fn_org_role_agent(v_mgr), public.fn_org_role_agent(v_spec),
          'specialist_invocation', 'owned',
          coalesce(p_reason, 'specialist consulted as a tool'), null,
          v_mgr||' invoked '||v_spec||' as a tool and retains ownership of the subject')
  returning id into v_id;

  return jsonb_build_object('ok', true, 'invocation_id', v_id,
    'manager_role', v_mgr, 'specialist_role', v_spec, 'specialist_mode', v_mode,
    'accountable_owner', v_mgr,
    'customer_visible', false,
    'note', 'the invoking manager remains the accountable owner and keeps the conversation');
end

fn_role_handoff:
declare v_from text; v_to text; v_dept text; v_allowed boolean; v_id bigint;
begin
  v_from := public.fn_org_role_resolve(p_from);
  v_to   := public.fn_org_role_resolve(p_to);
  if v_from is null or v_to is null then
    return jsonb_build_object('ok', false, 'error', 'unknown role in handoff',
                              'from', p_from, 'to', p_to);
  end if;
  if v_from = v_to then
    return jsonb_build_object('ok', false, 'error', 'a role cannot hand off to itself');
  end if;

  select primary_department_id into v_dept from public.org_role where role_id = v_to;

  -- The declared handoff graph. An undeclared handoff is allowed but recorded as such, because a
  -- refusal here would silently drop work; what must never happen is an unrecorded one.
  select v_to = any(r.handoff_targets) or v_to = any(r.escalation_targets)
    into v_allowed from public.org_role r where r.role_id = v_from;

  insert into public.review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                                   stage, decision, reason, delegated_from, delegation_basis)
  values (p_subject_type, p_subject_id, v_dept,
          public.fn_org_role_agent(v_from), public.fn_org_role_agent(v_to),
          'handoff', 'owned', coalesce(p_reason, 'ownership transferred'),
          public.fn_org_role_agent(v_from),
          case when coalesce(v_allowed,false)
               then 'declared handoff target of '||v_from
               else 'UNDECLARED handoff from '||v_from||' to '||v_to||'; recorded for the '
                    ||'organisation designer to reconcile' end)
  returning id into v_id;

  return jsonb_build_object('ok', true, 'handoff_id', v_id,
    'from_role', v_from, 'to_role', v_to, 'accountable_owner', v_to,
    'declared', coalesce(v_allowed, false),
    'to_agent', public.fn_org_role_agent(v_to), 'payload', p_payload);
end

fn_category_specialist_scorecard:
declare
  v_since timestamptz := now() - make_interval(days => greatest(coalesce(p_days,30),1));
  v_routed int; v_routed_ok int; v_inq int; v_quotable int; v_completeness_rows int;
  v_disp int; v_responded int; v_quotes int; v_valid int;
  v_overlays int; v_with_knowledge int;
begin
  select count(*) into v_overlays from org_role where status='active' and runtime_mode='knowledge_overlay';
  select count(distinct k.category_key) into v_with_knowledge
    from ops_knowledge k where k.category_key is not null and k.runtime_eligible;

  select count(*), count(*) filter (where coalesce(category,'') <> ''),
         count(*) filter (where coalesce(rfq_ready,false)),
         count(*) filter (where completeness is not null)
    into v_routed, v_routed_ok, v_quotable, v_completeness_rows
    from inquiries where created_at >= v_since;
  v_inq := v_routed;

  -- Dispatch is inquiry_matches.sent_at: a match that was never sent is a coverage fact, not a
  -- specialist outcome, so it is excluded from the denominator rather than counted as unanswered.
  select count(*) into v_disp from inquiry_matches where sent_at >= v_since;
  select count(distinct m.id) into v_responded
    from inquiry_matches m
    join quotes q on q.inquiry_id = m.inquiry_id and q.supplier_id = m.supplier_id
   where m.sent_at >= v_since;

  select count(*) into v_quotes from quotes where created_at >= v_since;
  select count(*) into v_valid from quotes
   where created_at >= v_since and coalesce(status,'') not in ('draft','invalid','withdrawn');

  return jsonb_build_object(
    'window_days', p_days,
    'overlays_active', v_overlays,
    'categories_with_runtime_knowledge', v_with_knowledge,
    'routing_accuracy', case when v_routed = 0 then null
                             else round(100.0 * v_routed_ok / v_routed, 1) end,
    'routing_accuracy_basis', case when v_routed = 0
      then 'no inquiry created in the window: not measurable, and deliberately not reported as 100'
      else v_routed_ok||' of '||v_routed||' inquiries carry a resolved category' end,
    'inquiry_quoteability', case when v_inq = 0 then null
                                 else round(100.0 * v_quotable / v_inq, 1) end,
    'inquiry_quoteability_basis', case when v_inq = 0
      then 'no inquiry in the window' else v_quotable||' of '||v_inq||' marked rfq_ready' end,
    'mandatory_field_completeness', null,
    'mandatory_field_completeness_basis',
      'not measurable: inquiries.completeness is jsonb and holds '||v_completeness_rows
      ||' non-null value(s) in this window. The column exists and no path writes it, so any number '
      ||'reported here would describe the schema rather than the inquiries',
    'supplier_response_rate', case when v_disp = 0 then null
                                   else round(100.0 * v_responded / v_disp, 1) end,
    'supplier_response_rate_basis', case when v_disp = 0
      then 'nothing dispatched in the window; with one confirmed supplier company-wide this is '
           ||'expected and is a coverage fact, not a specialist failure'
      else v_responded||' of '||v_disp||' dispatches answered' end,
    'valid_quotations', case when v_quotes = 0 then null
                             else round(100.0 * v_valid / v_quotes, 1) end,
    'valid_quotations_basis', case when v_quotes = 0
      then 'no quotation in the window' else v_valid||' of '||v_quotes end,
    'measured_at', now());
end

fn_retrieval_probe:
declare v_ctx jsonb; v_gap jsonb;
begin
  v_ctx := public.fn_agent_context_v3(p_agent_key, null, p_task_text, p_category_key, 24000);
  v_gap := public.fn_knowledge_gap(v_ctx);
  return jsonb_build_object(
    'agent_key',        p_agent_key,
    'role_ids',         v_ctx->'identity'->'packaged_role_ids',
    'knowledge_count',  v_ctx->'knowledge_count',
    'role_records',     coalesce(jsonb_array_length(v_ctx->'role_knowledge'),0),
    'dept_records',     coalesce(jsonb_array_length(v_ctx->'department_knowledge'),0),
    'category_records', coalesce(jsonb_array_length(v_ctx->'category_knowledge'),0),
    'rules_records',    coalesce(jsonb_array_length(v_ctx->'deterministic_rules'),0),
    'gap',              v_gap);
end

fn_retrieval_leak_check:
declare v_ctx jsonb; v_mine text[]; v_leak int;
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  select coalesce(array_agg(packaged_role_id),'{}') into v_mine
    from org_role_identity where agent_key = p_agent_key;
  v_ctx := public.fn_agent_context_v3(p_agent_key, null, p_task_text, null, 24000);
  select count(*) into v_leak
    from jsonb_array_elements(coalesce(v_ctx->'role_knowledge','[]'::jsonb)) e
    join ops_knowledge k on k.record_id = e->>'record_id'
   where k.role_key is not null and not (k.role_key = any(v_mine));
  return jsonb_build_object('agent_key', p_agent_key, 'own_roles', to_jsonb(v_mine),
                            'foreign_role_records', v_leak,
                            'clean', v_leak = 0);
end

fn_task_tsquery:
declare v_words text[]; v_q tsquery;
begin
  if p_text is null or btrim(p_text) = '' then return null; end if;

  -- Lexemes the text actually contains, after stemming and stop-word removal. Using to_tsvector
  -- rather than a hand-rolled split means the stop-word list is Postgres's own and the stems match
  -- the ones in the stored tsv, which is the whole point.
  select array_agg(distinct lexeme) into v_words
    from unnest(to_tsvector('english', left(p_text, 4000))) t(lexeme, positions, weights)
   where length(lexeme) > 2;

  if v_words is null or array_length(v_words, 1) = 0 then return null; end if;

  -- Cap the term count. A 60-word task ORed in full ranks almost the whole corpus as a weak match
  -- and the budget window then keeps whatever sorts first, which is the failure we are leaving.
  if array_length(v_words, 1) > 24 then v_words := v_words[1:24]; end if;

  v_q := to_tsquery('english', array_to_string(v_words, ' | '));
  return v_q;
exception when others then
  -- A malformed lexeme must degrade to "no query" (and therefore to labelled fallback), never to
  -- an exception that takes the agent's whole context down with it.
  return null;
end

trg_review_chain_no_self_review:
declare v_a text; v_r text;
begin
  if new.author_agent is null or new.reviewer_agent is null then return new; end if;

  v_a := coalesce(public.fn_org_agent_resolve(new.author_agent), new.author_agent);
  v_r := coalesce(public.fn_org_agent_resolve(new.reviewer_agent), new.reviewer_agent);

  if v_a = v_r then
    raise exception
      'review_chain refuses a self-review: author "%" and reviewer "%" are the same employee (%). %',
      new.author_agent, new.reviewer_agent, v_a,
      'Call fn_pick_reviewer(dept, author) and use what it returns; if it returns no reviewer, escalate.'
      using errcode = 'check_violation';
  end if;

  -- Store both sides canonical, so every count over this table measures employees and not spelling.
  new.author_agent   := v_a;
  new.reviewer_agent := v_r;
  return new;
end

fn_agent_action_trace_ins:
begin
  if new.decided_at is not null then
    perform public.fn_agent_action_trace_row(new);
  end if;
  return new;
end

fn_handoff_contract_guard:
declare
  v_check_owner boolean := false;
  v_owner       record;
  v_missing     text;
begin
  new.updated_at := now();

  -- (a) THE OWNER CANNOT BE LOST. NOT NULL stops the null; this stops the blank, the stranger,
  --     the deactivated replacement, and the owner who does not belong to the sending department.
  if coalesce(btrim(new.accountable_owner), '') = '' then
    raise exception 'handoff %: accountable_owner cannot be blank', coalesce(new.id, 0);
  end if;
  if tg_op = 'INSERT' then
    v_check_owner := true;
  elsif new.accountable_owner is distinct from old.accountable_owner then
    v_check_owner := true;
  end if;
  if v_check_owner then
    select agent_key, department, active into v_owner
      from org_agents where agent_key = new.accountable_owner;
    if not found then
      raise exception 'handoff %: accountable_owner % is not on the roster',
        coalesce(new.id, 0), new.accountable_owner;
    end if;
    if not v_owner.active then
      raise exception 'handoff %: accountable_owner % is not an active employee',
        coalesce(new.id, 0), new.accountable_owner;
    end if;
    if v_owner.department is distinct from new.from_dept then
      raise exception 'handoff %: accountable_owner % belongs to %, not the originating department %',
        coalesce(new.id, 0), new.accountable_owner, coalesce(v_owner.department, '(none)'), new.from_dept;
    end if;
  end if;

  -- (b) THE LIFECYCLE. open -> accepted|rejected; accepted -> returned|closed;
  --     rejected|returned -> open (the sender corrected it). closed is terminal.
  if tg_op = 'UPDATE' and new.status is distinct from old.status then
    if old.status = 'closed' then
      raise exception 'handoff %: closed is terminal, cannot move to %', new.id, new.status;
    end if;
    if not ((old.status = 'open'     and new.status in ('accepted','rejected'))
         or (old.status = 'accepted' and new.status in ('returned','closed'))
         or (old.status in ('rejected','returned') and new.status = 'open')) then
      raise exception 'handoff %: illegal transition % -> %', new.id, old.status, new.status;
    end if;
  end if;

  -- (c) CLOSURE NEEDS PROOF, PER CRITERION. This is CMP-HO-05 made unavoidable: a closure with a
  --     criterion nobody evidenced is refused, and the message names which criterion.
  if new.status = 'closed' then
    if new.closed_by is null or new.closed_at is null then
      raise exception 'handoff %: a closure must record who closed it and when', new.id;
    end if;
    select string_agg(c, '; ') into v_missing
      from unnest(new.closure_criteria) c
     where not exists (
       select 1 from jsonb_array_elements(coalesce(new.closure_evidence, '[]'::jsonb)) e
        where btrim(coalesce(e->>'criterion', '')) = btrim(c)
          and coalesce(btrim(e->>'evidence'), '') <> '');
    if v_missing is not null then
      raise exception 'handoff %: cannot close, no recorded proof for closure criteria: %',
        new.id, v_missing;
    end if;
  end if;

  return new;
end

fn_handoff_criteria:
select coalesce(array_agg(btrim(x)) filter (where btrim(x) <> ''), '{}'::text[])
  from jsonb_array_elements_text(
         case when jsonb_typeof(p) = 'array' then p else '[]'::jsonb end) x;

fn_handoff_notify:
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if coalesce(btrim(p_agent_key), '') = ''
     or not exists (select 1 from org_agents where agent_key = p_agent_key) then
    return false;
  end if;
  insert into agent_memory (agent_key, kind, content, source, importance)
  values (p_agent_key, 'learned', left(p_content, 2000), p_source, 4);
  return true;
end

fn_handoff_open:
declare
  v_from     text := btrim(coalesce(p->>'from_dept', ''));
  v_owner    text := btrim(coalesce(p->>'accountable_owner', ''));
  v_to       text := btrim(coalesce(p->>'to_dept', ''));
  v_role     text := btrim(coalesce(p->>'to_role', ''));
  v_purpose  text := btrim(coalesce(p->>'purpose', ''));
  v_act      text := btrim(coalesce(p->>'requested_action', ''));
  v_escal    text := btrim(coalesce(p->>'escalation_conditions', ''));
  v_evidence jsonb := case when jsonb_typeof(p->'evidence') = 'array' then p->'evidence' else '[]'::jsonb end;
  v_accept   text[] := public.fn_handoff_criteria(p->'acceptance_criteria');
  v_closure  text[] := public.fn_handoff_criteria(p->'closure_criteria');
  v_deadline timestamptz;
  v_missing  text[] := '{}';
  v_gaps     text[] := '{}';
  v_idem     text;
  v_recv     text;
  v_ownrec   record;
  v_action   bigint;
  v_id       bigint;
  v_dupe     bigint;
begin
  begin v_deadline := (p->>'deadline')::timestamptz; exception when others then v_deadline := null; end;

  if v_from    = '' then v_missing := v_missing || 'from_dept'::text;             end if;
  if v_owner   = '' then v_missing := v_missing || 'accountable_owner'::text;     end if;
  if v_to      = '' then v_missing := v_missing || 'to_dept'::text;               end if;
  if v_role    = '' then v_missing := v_missing || 'to_role'::text;               end if;
  if length(v_purpose) < 10 then v_missing := v_missing || 'purpose'::text;       end if;
  if length(v_act) < 10 then v_missing := v_missing || 'requested_action'::text;  end if;
  if v_escal   = '' then v_missing := v_missing || 'escalation_conditions'::text; end if;
  if v_deadline is null then v_missing := v_missing || 'deadline'::text;          end if;
  if cardinality(v_closure) = 0 then v_missing := v_missing || 'closure_criteria'::text; end if;
  if array_length(v_missing, 1) is not null then
    return jsonb_build_object('ok', false, 'reason', 'the handoff contract is not complete enough to open',
                              'missing', to_jsonb(v_missing));
  end if;
  if v_deadline <= now() then
    return jsonb_build_object('ok', false, 'reason', 'deadline is already in the past', 'deadline', v_deadline);
  end if;

  if not exists (select 1 from org_departments where dept_key = v_from) then
    return jsonb_build_object('ok', false, 'reason', 'unknown originating department', 'from_dept', v_from);
  end if;
  if not exists (select 1 from org_departments where dept_key = v_to) then
    return jsonb_build_object('ok', false, 'reason', 'unknown receiving department', 'to_dept', v_to);
  end if;
  select agent_key, department, active into v_ownrec from org_agents where agent_key = v_owner;
  if not found or not v_ownrec.active then
    return jsonb_build_object('ok', false, 'reason', 'accountable owner is not an active employee',
                              'accountable_owner', v_owner);
  end if;
  if v_ownrec.department is distinct from v_from then
    return jsonb_build_object('ok', false, 'reason', 'accountable owner does not belong to the originating department',
                              'accountable_owner', v_owner, 'owner_department', v_ownrec.department, 'from_dept', v_from);
  end if;

  -- REPLAY / DUPLICATE STATE. Same sender, same receiver, same ask = the same handoff.
  v_idem := coalesce(nullif(btrim(p->>'idempotency_key'), ''),
                     md5(v_from||'>'||v_to||'|'||lower(v_role)||'|'||lower(v_purpose)||'|'||lower(v_act)));
  select id into v_dupe from handoff_contract
   where idempotency_key = v_idem and status in ('open','accepted','returned') limit 1;
  if v_dupe is not null then
    return jsonb_build_object('ok', true, 'duplicate', true, 'id', v_dupe,
      'note', 'an identical handoff is already live; returning it rather than opening a second');
  end if;

  -- WHO ACTUALLY RECEIVES IT. The named role first, then a role that contains the name, then the
  -- department lead. A handoff addressed to a department with nobody in it is refused, not queued.
  select a.agent_key into v_recv
    from org_agents a
    left join org_departments d on d.dept_key = a.department
   where a.department = v_to and a.active
   order by (lower(a.role) = lower(v_role)) desc,
            (position(lower(v_role) in lower(coalesce(a.role,''))) > 0) desc,
            coalesce(a.available, true) desc,
            (a.agent_key = d.lead_agent) desc,
            a.agent_key
   limit 1;
  if v_recv is null then
    return jsonb_build_object('ok', false, 'reason', 'receiving department has no active employee to accept it',
                              'to_dept', v_to);
  end if;

  -- The transport row: this is what fn_agent_handoff_inbox already reads. Unchanged shape.
  insert into agent_actions (agent, kind, status, risk, title, recommendation, detail, target_table)
  values (v_recv, 'handoff', 'needs_review', 'medium',
          'Handoff — '||left(v_purpose, 160), left(v_act, 500),
          jsonb_build_object(
            'from', v_owner, 'from_name', v_owner, 'from_dept', v_from,
            'to_dept', v_to, 'to_role', v_role, 'deadline', v_deadline,
            'acceptance_criteria', to_jsonb(v_accept), 'closure_criteria', to_jsonb(v_closure),
            'escalation_conditions', v_escal, 'requested_at', now(), 'contract', true),
          'handoff_contract')
  returning id into v_action;

  insert into handoff_contract (action_id, idempotency_key, from_dept, accountable_owner, to_dept,
                                to_role, purpose, evidence, requested_action, deadline,
                                acceptance_criteria, closure_criteria, escalation_conditions)
  values (v_action, v_idem, v_from, v_owner, v_to, v_role, v_purpose, v_evidence, v_act, v_deadline,
          v_accept, v_closure, v_escal)
  returning id into v_id;

  update agent_actions set target_id = v_id::text where id = v_action;

  if jsonb_array_length(v_evidence) = 0 then v_gaps := v_gaps || 'evidence'::text; end if;
  if cardinality(v_accept) = 0 then v_gaps := v_gaps || 'acceptance_criteria'::text; end if;

  return jsonb_build_object('ok', true, 'id', v_id, 'action_id', v_action,
    'receiving_agent', v_recv, 'idempotency_key', v_idem,
    'complete', array_length(v_gaps, 1) is null,
    'rejectable_on_arrival', array_length(v_gaps, 1) is not null,
    'missing_for_acceptance', to_jsonb(v_gaps));
end

fn_handoff_respond:
declare
  c        handoff_contract%rowtype;
  v_dec    text := lower(btrim(coalesce(p_decision, '')));
  v_reason text := btrim(coalesce(p_reason, ''));
  v_gaps   text[] := '{}';
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  if v_dec not in ('accept','reject','return') then
    return jsonb_build_object('ok', false, 'reason', 'decision must be accept, reject or return');
  end if;
  select * into c from handoff_contract where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no handoff contract with that id');
  end if;
  if not exists (select 1 from org_agents
                  where agent_key = p_agent_key and active and department = c.to_dept) then
    return jsonb_build_object('ok', false, 'reason', 'only an active employee of the receiving department may answer',
                              'to_dept', c.to_dept);
  end if;

  if jsonb_array_length(c.evidence) = 0 then v_gaps := v_gaps || 'evidence'::text; end if;
  if cardinality(c.acceptance_criteria) = 0 then v_gaps := v_gaps || 'acceptance_criteria'::text; end if;

  if v_dec = 'accept' then
    if c.status <> 'open' then
      return jsonb_build_object('ok', false, 'reason', 'only an open handoff can be accepted', 'status', c.status);
    end if;
    -- REJECTABLE ON ARRIVAL: an incomplete handoff cannot be silently taken on.
    if array_length(v_gaps, 1) is not null then
      return jsonb_build_object('ok', false, 'reason', 'handoff is incomplete and cannot be accepted',
        'missing', to_jsonb(v_gaps), 'next', 'reject it with a reason, or ask the sender to amend it');
    end if;
    update handoff_contract
       set status = 'accepted', return_status = 'accepted',
           accepted_by = p_agent_key, accepted_at = now(), return_reason = nullif(v_reason, '')
     where id = p_id;
    perform public.fn_handoff_notify(c.accountable_owner,
      'Handoff #'||p_id||' ("'||c.purpose||'") was ACCEPTED by '||p_agent_key||' ('||c.to_dept||'). '
      ||'Due '||to_char(c.deadline, 'YYYY-MM-DD HH24:MI')||'. Closure criteria: '
      ||array_to_string(c.closure_criteria, ' | '),
      'handoff_contract:'||p_id);
    return jsonb_build_object('ok', true, 'id', p_id, 'status', 'accepted',
      'accepted_by', p_agent_key, 'deadline', c.deadline,
      'acceptance_criteria', to_jsonb(c.acceptance_criteria),
      'closure_criteria', to_jsonb(c.closure_criteria));
  end if;

  if v_reason = '' then
    return jsonb_build_object('ok', false, 'reason', 'a '||v_dec||' must state why');
  end if;

  if v_dec = 'reject' then
    if c.status <> 'open' then
      return jsonb_build_object('ok', false, 'reason', 'only an open handoff can be rejected', 'status', c.status);
    end if;
    update handoff_contract
       set status = 'rejected',
           return_status = case when array_length(v_gaps, 1) is not null
                                then 'rejected_incomplete' else 'rejected' end,
           return_reason = v_reason
     where id = p_id;
    -- The transport row leaves the receiver's inbox; the sender is told, in their own memory.
    update agent_actions
       set status = 'done', decided_at = now(), decided_by = p_agent_key,
           detail = coalesce(detail, '{}'::jsonb)
                    || jsonb_build_object('outcome', 'rejected', 'reason', left(v_reason, 1000),
                                          'missing', to_jsonb(v_gaps), 'rejected_at', now())
     where id = c.action_id;
    perform public.fn_handoff_notify(c.accountable_owner,
      'Handoff #'||p_id||' ("'||c.purpose||'") was REJECTED by '||p_agent_key||' ('||c.to_dept||'): '
      ||v_reason||case when array_length(v_gaps, 1) is not null
                       then '. Missing: '||array_to_string(v_gaps, ', ')||'. Amend and resubmit with fn_handoff_amend.'
                       else '' end,
      'handoff_contract:'||p_id);
    return jsonb_build_object('ok', true, 'id', p_id, 'status', 'rejected',
      'return_status', case when array_length(v_gaps, 1) is not null then 'rejected_incomplete' else 'rejected' end,
      'missing', to_jsonb(v_gaps), 'sender_notified', c.accountable_owner);
  end if;

  -- return: the receiver took it on, then found it cannot be finished as handed over.
  if c.status <> 'accepted' then
    return jsonb_build_object('ok', false, 'reason', 'only an accepted handoff can be returned for correction',
                              'status', c.status);
  end if;
  update handoff_contract
     set status = 'returned', return_status = 'returned_for_correction',
         return_reason = v_reason, returns_count = returns_count + 1
   where id = p_id;
  perform public.fn_handoff_notify(c.accountable_owner,
    'Handoff #'||p_id||' ("'||c.purpose||'") was RETURNED FOR CORRECTION by '||p_agent_key||': '||v_reason
    ||' Correct it with fn_handoff_amend; it goes back to '||c.to_dept||' as open.',
    'handoff_contract:'||p_id);
  return jsonb_build_object('ok', true, 'id', p_id, 'status', 'returned',
    'return_status', 'returned_for_correction', 'returns_count', c.returns_count + 1,
    'sender_notified', c.accountable_owner);
end

fn_handoff_amend:
declare
  c          handoff_contract%rowtype;
  v_evidence jsonb;
  v_accept   text[];
  v_deadline timestamptz;
  v_owner    text;
  v_gaps     text[] := '{}';
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  select * into c from handoff_contract where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no handoff contract with that id');
  end if;
  if c.status = 'closed' then
    return jsonb_build_object('ok', false, 'reason', 'a closed handoff cannot be amended');
  end if;
  if not exists (select 1 from org_agents
                  where agent_key = p_agent_key and active and department = c.from_dept) then
    return jsonb_build_object('ok', false, 'reason', 'only an active employee of the originating department may amend',
                              'from_dept', c.from_dept);
  end if;

  v_evidence := case when jsonb_typeof(p_patch->'evidence') = 'array' then p_patch->'evidence' else c.evidence end;
  v_accept   := case when jsonb_typeof(p_patch->'acceptance_criteria') = 'array'
                     then public.fn_handoff_criteria(p_patch->'acceptance_criteria') else c.acceptance_criteria end;
  v_owner    := coalesce(nullif(btrim(p_patch->>'accountable_owner'), ''), p_agent_key);
  begin v_deadline := coalesce((p_patch->>'deadline')::timestamptz, c.deadline);
  exception when others then v_deadline := c.deadline; end;

  update handoff_contract
     set evidence = v_evidence,
         acceptance_criteria = v_accept,
         deadline = v_deadline,
         accountable_owner = v_owner,          -- guard refuses a blank, a stranger or an ex-employee
         status = case when c.status in ('rejected','returned') then 'open' else c.status end,
         return_status = case when c.status in ('rejected','returned') then null else c.return_status end,
         return_reason = case when c.status in ('rejected','returned') then null else c.return_reason end
   where id = p_id;

  -- Back into the receiver's inbox if the rejection had taken it out.
  update agent_actions
     set status = 'needs_review', decided_at = null, decided_by = null,
         detail = coalesce(detail, '{}'::jsonb) || jsonb_build_object('amended_at', now(), 'amended_by', p_agent_key)
   where id = c.action_id and c.status in ('rejected','returned');

  if jsonb_array_length(v_evidence) = 0 then v_gaps := v_gaps || 'evidence'::text; end if;
  if cardinality(v_accept) = 0 then v_gaps := v_gaps || 'acceptance_criteria'::text; end if;

  return jsonb_build_object('ok', true, 'id', p_id,
    'status', case when c.status in ('rejected','returned') then 'open' else c.status end,
    'accountable_owner', v_owner, 'owner_changed', v_owner is distinct from c.accountable_owner,
    'complete', array_length(v_gaps, 1) is null, 'missing_for_acceptance', to_jsonb(v_gaps));
end

fn_handoff_close:
declare
  c         handoff_contract%rowtype;
  v_ev      jsonb := case when jsonb_typeof(p_closure_evidence) = 'array' then p_closure_evidence else '[]'::jsonb end;
  v_missing text[];
begin
  p_agent_key := coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key);
  select * into c from handoff_contract where id = p_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no handoff contract with that id');
  end if;
  if c.status <> 'accepted' then
    return jsonb_build_object('ok', false, 'reason', 'only an accepted handoff can be closed', 'status', c.status);
  end if;
  if not exists (select 1 from org_agents
                  where agent_key = p_agent_key and active and department = c.to_dept) then
    return jsonb_build_object('ok', false, 'reason', 'only an active employee of the receiving department may close it',
                              'to_dept', c.to_dept);
  end if;

  select coalesce(array_agg(x), '{}'::text[]) into v_missing
    from unnest(c.closure_criteria) x
   where not exists (
     select 1 from jsonb_array_elements(v_ev) e
      where btrim(coalesce(e->>'criterion', '')) = btrim(x)
        and coalesce(btrim(e->>'evidence'), '') <> '');
  if array_length(v_missing, 1) is not null then
    return jsonb_build_object('ok', false, 'reason', 'closure criteria without recorded proof',
      'unproven', to_jsonb(v_missing), 'declared', to_jsonb(c.closure_criteria));
  end if;

  update handoff_contract
     set status = 'closed', return_status = 'closed', closure_evidence = v_ev,
         closed_by = p_agent_key, closed_at = now()
   where id = p_id;

  update agent_actions
     set status = 'done', decided_at = now(), decided_by = p_agent_key,
         detail = coalesce(detail, '{}'::jsonb)
                  || jsonb_build_object('outcome', 'closed', 'closure_evidence', v_ev, 'closed_at', now())
   where id = c.action_id;

  perform public.fn_handoff_notify(c.accountable_owner,
    'Handoff #'||p_id||' ("'||c.purpose||'") was CLOSED by '||p_agent_key||' ('||c.to_dept||'). '
    ||'Proof recorded for '||cardinality(c.closure_criteria)||' closure criteria: '||v_ev::text,
    'handoff_contract:'||p_id);

  return jsonb_build_object('ok', true, 'id', p_id, 'status', 'closed', 'closed_by', p_agent_key,
    'criteria_proven', cardinality(c.closure_criteria), 'closure_evidence', v_ev);
end

fn_record_llm_attempt:
declare
  v_req      uuid    := coalesce(nullif(p->>'request_id','')::uuid, gen_random_uuid());
  v_model    text    := nullif(p->>'model_route','');
  v_ok       boolean := coalesce((p->>'ok')::boolean, false);
  v_no       integer;
  v_cls      jsonb;
  v_key      text;
  v_trips    boolean;
  v_first    boolean;
  v_thresh   integer;
  v_cool     integer;
  v_conseq   integer;
  v_state    text := 'closed';
  v_id       uuid;
  v_in       integer := nullif(p->>'prompt_tokens','')::integer;
  v_out      integer := nullif(p->>'output_tokens','')::integer;
  v_cached   integer := coalesce(nullif(p->>'cached_in_tokens','')::integer, 0);
  v_cost     numeric := nullif(p->>'cost_aed','')::numeric;
begin
  if v_model is null then
    raise exception 'fn_record_llm_attempt requires model_route: the route is what the breaker keys on';
  end if;

  if not v_ok then
    v_cls := fn_classify_llm_failure(p->>'err_excerpt',
                                     nullif(p->>'http_status','')::integer,
                                     p->>'finish_reason', v_model,
                                     nullif(p->>'latency_ms','')::integer);
    v_key := v_cls->>'class_key';
  end if;

  -- attempt_no is assigned HERE, never accepted from the caller. A caller cannot claim to be
  -- attempt 1 twice, and cannot renumber an earlier attempt out of the way.
  select coalesce(max(attempt_no), 0) + 1 into v_no from llm_attempt where request_id = v_req;

  insert into llm_route_health (model_id) values (v_model) on conflict (model_id) do nothing;
  select failure_threshold, cooldown_seconds into v_thresh, v_cool
    from llm_route_health where model_id = v_model;

  if v_ok then
    update llm_route_health
       set consecutive_failures = 0, open_until = null, opened_reason = null, opened_class = null,
           last_ok_at = now(), total_attempts = total_attempts + 1, total_ok = total_ok + 1,
           updated_at = now()
     where model_id = v_model;
  else
    select trips_breaker, opens_on_first into v_trips, v_first
      from llm_failure_class where class_key = v_key;
    update llm_route_health
       set consecutive_failures = case when coalesce(v_trips,false)
                                       then consecutive_failures + 1 else consecutive_failures end,
           last_failure_at = now(), total_attempts = total_attempts + 1, updated_at = now()
     where model_id = v_model
     returning consecutive_failures into v_conseq;

    if coalesce(v_trips,false) and (coalesce(v_first,false) or v_conseq >= v_thresh) then
      update llm_route_health
         set open_until = now() + make_interval(secs => v_cool),
             opened_reason = case when coalesce(v_first,false)
                             then 'opened on first occurrence of ' || v_key
                             else v_conseq || ' consecutive failures, threshold ' || v_thresh end,
             opened_class = v_key
       where model_id = v_model;
      v_state := 'opened_by_this';
    end if;
  end if;

  -- DERIVE THE MONEY HERE, from the same pricing source ai_cost_log uses, rather than trusting a
  -- caller to convert. A caller that computes its own AED is a second pricing implementation, and
  -- two of those drift. An explicit cost_aed in the payload still wins, so a provider that reports
  -- its own charge can be recorded verbatim.
  --
  -- Deliberately only when tokens are present: a failed attempt that produced no usage block has
  -- no measurable cost, and inventing 0 there would make "this retry was free" indistinguishable
  -- from "nobody recorded what this retry cost".
  if v_cost is null and (v_in is not null or v_out is not null) then
    begin
      v_cost := public.fn_model_cost_usd(v_model, coalesce(v_in,0), coalesce(v_out,0), v_cached)
                * public.fn_usd_to_aed();
    exception when others then v_cost := null;   -- pricing is reporting, never a gate
    end;
  end if;

  insert into llm_attempt (request_id, attempt_no, fn, agent_key, task_class, model_route, tier,
                           ok, class_key, http_status, finish_reason, err_excerpt,
                           evidence_truncated, latency_ms, prompt_tokens, output_tokens, cost_aed,
                           breaker_state)
  values (v_req, v_no, p->>'fn', p->>'agent_key', p->>'task_class', v_model, p->>'tier',
          v_ok, v_key, nullif(p->>'http_status','')::integer, p->>'finish_reason',
          left(coalesce(p->>'err_excerpt',''), 4000),
          coalesce((v_cls->>'evidence_truncated')::boolean, false),
          nullif(p->>'latency_ms','')::integer, v_in, v_out, v_cost,
          v_state)
  returning attempt_id into v_id;

  return jsonb_build_object(
    'attempt_id', v_id, 'request_id', v_req, 'attempt_no', v_no,
    'class_key', v_key, 'breaker', v_state,
    'cost_aed', v_cost,
    'retry_allowed', case when v_ok then false
                          when v_state = 'opened_by_this' then false   -- fail closed, do not retry into a wall
                          else fn_llm_retry_allowed(v_key, v_no) end,
    'retry_backoff_ms', coalesce((v_cls->>'retry_backoff_ms')::integer, 0),
    'evidence_truncated', coalesce((v_cls->>'evidence_truncated')::boolean, false));
end

fn_trace_edit_is_blocked:
declare v_before numeric; v_after numeric;
begin
  select confidence into v_before from decision_trace where id = p_id;
  begin
    -- The edit that must be refused on a sealed trace.
    update decision_trace set confidence = coalesce(v_before, 0) + 0.01 where id = p_id;
  exception when others then
    return true;                       -- refused, which is the correct behaviour
  end;
  select confidence into v_after from decision_trace where id = p_id;
  -- Not refused. Put it back so the probe leaves nothing behind, then report the defect honestly.
  update decision_trace set confidence = v_before where id = p_id;
  return v_after is not distinct from v_before;
end

fn_record_tool_call:
declare v_id uuid;
begin
  insert into agent_tool_call (correlation_id, agent_key, role_id, tool_id, args, status,
                               result_hash, result_rows, result_bytes, error, attempt, latency_ms)
  values (p_correlation, p_agent_key, p_role_id, p_tool_id, coalesce(p_args,'{}'::jsonb), p_status,
          p_result_hash, p_result_rows, p_result_bytes, left(p_error, 500),
          coalesce(p_attempt,1), p_latency_ms)
  returning id into v_id;
  return v_id;
end

fn_revenue_trajectory:
declare
  g record;
  v_actual numeric;
  v_err text;
  v_days int;
  v_gap numeric;
begin
  select key, goal, metric, target_value, unit, deadline, measure_sql, no_measure_reason
    into g from public.company_goals where key = 'revenue_annual' and active;

  if not found then
    return jsonb_build_object('measured', false,
      'reason', 'company_goals has no active row with key = revenue_annual');
  end if;

  if coalesce(g.measure_sql,'') = '' then
    v_err := coalesce(g.no_measure_reason, 'no measure_sql recorded for this goal');
  else
    begin
      execute g.measure_sql into v_actual;
    exception when others then
      v_actual := null;
      v_err := 'measure_sql failed: ' || sqlerrm;
    end;
  end if;

  v_days := case when g.deadline is null then null else (g.deadline - current_date) end;
  v_gap  := case when v_actual is null then null else g.target_value - v_actual end;

  return jsonb_build_object(
    'objective',        g.goal,
    'metric',           g.metric,
    'target_value',     g.target_value,
    'unit',             g.unit,
    'deadline',         g.deadline,
    'days_remaining',   v_days,
    'measured',         v_actual is not null,
    'actual_value',     v_actual,
    'not_measured_reason', case when v_actual is null then coalesce(v_err,'unknown') end,
    'gap_to_target',    v_gap,
    -- Run rate, not a score. Null propagates: no actual or no deadline means no run rate, never a
    -- comfortable number standing in for one.
    'required_per_month', case
        when v_gap is null or v_days is null or v_days <= 0 then null
        else round(v_gap / (v_days / 30.44), 2) end,
    'required_per_day',   case
        when v_gap is null or v_days is null or v_days <= 0 then null
        else round(v_gap / v_days, 2) end,
    'deadline_passed',  case when v_days is null then null else v_days <= 0 end,
    'source', 'company_goals.measure_sql executed live; deadline from company_goals.deadline');
end

fn_unsafe_escalation_route:
declare c record; v_dept text; v_auth jsonb; v_esc jsonb; v_auto text;
begin
  p_actor := coalesce(public.fn_org_agent_resolve(p_actor), p_actor);
  select * into c from public.unsafe_class where class_key = p_class_key;
  if c.class_key is null then
    return jsonb_build_object('error', 'unknown unsafe class: ' || coalesce(p_class_key,'(null)'));
  end if;

  select a.department into v_dept from public.org_agents a where a.agent_key = p_actor and a.active;
  v_dept := coalesce(v_dept, 'exec');

  -- No action_class means no department delegation exists for this class: it is founder-level by
  -- construction, and saying so is more honest than resolving a tier for a class nobody mapped.
  if c.authority_action_class is not null then
    v_auth := public.fn_ops_authority_check(v_dept, c.authority_action_class, null,
                                            case when c.severity = 'critical' then 'critical' else null end);
  end if;

  -- SECOND, INDEPENDENT SIGNAL. fn_autonomy_class holds the hard rails written as a per-kind
  -- disposition rather than a per-department tier: anything matching money, deletion or supplier
  -- approval returns 'founder' regardless of what any department was delegated. It is consulted,
  -- not replaced — where the two disagree the more restrictive one wins, which is why 'founder'
  -- forces approval even if the department tier came back permissive.
  v_auto := public.fn_autonomy_class(c.authority_action_class, null, null);

  v_esc := public.fn_should_escalate(jsonb_build_object(
             'actor', p_actor,
             'kind', 'unsafe_block',
             'category', c.class_key,
             'text', c.title || '. ' || c.mechanism));

  return jsonb_build_object(
    'class_key', c.class_key,
    'requires_human_authority', c.requires_human_authority,
    'department', v_dept,
    'action_class', c.authority_action_class,
    'effective_tier', coalesce(v_auth->>'effective_tier', 'gated'),
    'requires_approval', coalesce((v_auth->>'requires_approval')::boolean, true) or v_auto = 'founder',
    'autonomy_class', v_auto,
    'founder_only', v_auto = 'founder',
    'authority_reason', coalesce(v_auth->>'reason', 'no action_class mapped for this class: treated as gated')
                        || case when v_auto = 'founder'
                                then '; fn_autonomy_class returns founder for this action class, which overrides any department tier'
                                else '' end,
    'route_to', v_esc->>'route_to',
    'route_basis', v_esc->>'route_basis',
    'hard_gate', v_auth->'hard_gate');
end

fn_unsafe_block:
declare c record; v_route jsonb; v_id bigint; v_disp text;
begin
  select * into c from public.unsafe_class where class_key = p_class_key;
  if c.class_key is null then
    raise exception 'fn_unsafe_block: unknown unsafe class %. Register it in unsafe_class first — an unnamed refusal is not auditable.', p_class_key
      using errcode = 'foreign_key_violation';
  end if;

  v_route := public.fn_unsafe_escalation_route(p_class_key, p_actor);
  v_disp  := case when c.requires_human_authority then 'escalated' else 'blocked' end;

  insert into public.unsafe_block
    (class_key, actor, subject_table, subject_ref, action_attempted, disposition,
     escalation_route, detail, correlation_id)
  values (p_class_key, p_actor, p_subject_table, p_subject_ref, p_action, v_disp,
          v_route, coalesce(p_detail,'{}'::jsonb), p_correlation_id)
  returning id into v_id;

  return jsonb_build_object('allowed', false, 'block_id', v_id, 'class_key', p_class_key,
                            'disposition', v_disp, 'escalation', v_route);
end

fn_unsafe_match_eligibility_guard:
declare l record; v_reason text;
begin
  select id, company_name, banned, matching_blocked, permanently_closed, license_expiry
    into l from public.leads where id = new.supplier_id;
  if l.id is null then
    -- K05. The supplier is not on record here; this gate has nothing to judge and says so rather
    -- than leaving the verdict key holding whatever the previous row left in it.
    perform set_config('app.inquiry_match_gate_verdict', 'PASS', true);
    perform set_config('app.inquiry_match_gate_reason',
      format('supplier %s is not in public.leads; this gate judges eligibility and has no row',
             new.supplier_id), true);
    return new;
  end if;

  v_reason := case
    when coalesce(l.banned,false)             then 'supplier is banned'
    when coalesce(l.matching_blocked,false)   then 'supplier is blocked from matching'
    when coalesce(l.permanently_closed,false) then 'supplier is permanently closed'
    when l.license_expiry is not null and l.license_expiry < current_date
                                              then 'supplier licence expired ' || l.license_expiry
    else null end;
  if v_reason is null then
    perform set_config('app.inquiry_match_gate_verdict', 'PASS', true);
    perform set_config('app.inquiry_match_gate_reason',
      format('supplier %s is eligible to receive a match', new.supplier_id), true);
    return new;
  end if;

  -- K05. A REFUSAL THAT STATES ITSELF. The ledger row below is the safety record; this is the
  -- verdict the writer and the caller read, on the same key the readiness gate publishes.
  perform set_config('app.inquiry_match_gate_verdict', 'BLOCKED_INELIGIBLE_SUPPLIER', true);
  perform set_config('app.inquiry_match_gate_reason',
    format('supplier %s: %s', new.supplier_id, v_reason), true);

  perform public.fn_unsafe_block(
    'ineligible_supplier_match', 'trigger:a00_unsafe_match_eligibility',
    'inquiry_matches', coalesce(new.inquiry_id::text,'') || '/' || new.supplier_id::text,
    'insert match row',
    jsonb_build_object('supplier_id', new.supplier_id, 'company', l.company_name,
                       'inquiry_id', new.inquiry_id, 'reason', v_reason));
  raise warning 'unsafe_block: refused match of inquiry % to supplier % — %',
        new.inquiry_id, new.supplier_id, v_reason;
  return null;   -- row not inserted; the ledger row survives
end

fn_unsafe_guard_status:
declare c record; v_now integer; v_7d integer; v_err text; v_has boolean; v_route jsonb;
begin
  -- aliased and qualified: the OUT parameters of this function share their names with the columns
  -- of unsafe_class, and an unqualified ORDER BY resolves to the plpgsql variable instead.
  for c in select uc.* from public.unsafe_class uc order by
             case uc.detector_status when 'LIVE' then 0 else 1 end, uc.severity, uc.class_key
  loop
    v_now := null; v_7d := null; v_err := null;
    v_has := c.detector_fn is not null and exists (
               select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                where n.nspname = 'public' and p.proname = c.detector_fn);

    if c.detector_fn is not null and not v_has then
      v_err := 'registry names ' || c.detector_fn || ' but no such routine exists in public';
    elsif v_has then
      begin
        execute format('select count(*)::int from public.%I($1)', c.detector_fn)
           into v_now using null::timestamptz;
        if c.windowed then
          execute format('select count(*)::int from public.%I($1)', c.detector_fn)
             into v_7d using (now() - interval '7 days');
        end if;
      exception when others then
        v_err := 'detector raised: ' || sqlerrm; v_now := null; v_7d := null;
      end;
    end if;

    class_key := c.class_key; title := c.title; severity := c.severity;
    detector_status := c.detector_status; has_detector := v_has; windowed := c.windowed;
    fired_count_7d := v_7d; fired_count_now := v_now;
    blocked_count_7d := (select count(*)::int from public.unsafe_block b
                          where b.class_key = c.class_key and b.at >= now() - interval '7 days');
    -- Called with no actor, so this is the CONFIGURED default owner and is the same string for
    -- every class by construction. The per-class routing lives in fn_unsafe_escalation_route with
    -- the acting agent supplied — measured: actor 'ap_specialist' resolves to cfo by reporting_line,
    -- not to this default. The column is named for what it is so nobody reads a constant as routing.
    v_route := public.fn_unsafe_escalation_route(c.class_key);
    action_class := c.authority_action_class;
    effective_tier := v_route ->> 'effective_tier';
    default_route_no_actor := v_route ->> 'route_to';
    coverage_note := c.coverage_note; not_measurable_reason := c.not_measurable_reason;
    detector_error := v_err;
    return next;
  end loop;
end

fn_unsafe_liveness_probe:
declare b integer; a integer; e text; v_tx uuid;
begin
  ---------------------------------------------------------------- unstated_assumption
  select count(*)::int into b from public.fn_unsafe_check_unstated_assumption(null);
  a := null; e := null;
  begin
    insert into public.decision_trace (correlation_id, entity_type, entity_id, decision_type,
                                       proposed_by, decision, assumptions, knowledge_refs,
                                       evidence_refs, agent_key)
    values (gen_random_uuid(),'probe','__liveness__','probe','__probe__',
            '{"probe":true}'::jsonb, '["a fact the case never supplied"]'::jsonb,
            '[]'::jsonb, '[]'::jsonb, '__probe__');
    select count(*)::int into a from public.fn_unsafe_check_unstated_assumption(null);
    raise exception using message = '__probe_rollback__';
  exception when others then
    if sqlerrm <> '__probe_rollback__' then e := sqlerrm; a := null; end if;
  end;
  class_key:='unstated_assumption'; fired_before:=b; fired_after:=a;
  can_fire := a is not null and a > b;
  control:='insert a decision_trace row carrying an assumption with empty knowledge_refs and evidence_refs';
  note:=e; return next;

  ---------------------------------------------------------------- unlogged_provider_bypass
  select count(*)::int into b from public.fn_unsafe_check_unlogged_provider(null);
  a := null; e := null;
  begin
    update public.internal_credential
       set last_used_at = now() + interval '1 hour'
     where active and last_function = 'ai_gateway'
       and id = (select min(id) from public.internal_credential where active and last_function='ai_gateway');
    select count(*)::int into a from public.fn_unsafe_check_unlogged_provider(null);
    raise exception using message = '__probe_rollback__';
  exception when others then
    if sqlerrm <> '__probe_rollback__' then e := sqlerrm; a := null; end if;
  end;
  class_key:='unlogged_provider_bypass'; fired_before:=b; fired_after:=a;
  can_fire := a is not null and a > b;
  control:='stamp an ai_gateway credential as used after the newest ai_cost_log row';
  note:=e; return next;

  ---------------------------------------------------------------- fail_open_authorization
  select count(*)::int into b from public.fn_unsafe_check_fail_open_authz(null);
  a := null; e := null;
  begin
    delete from public.org_authority
     where (dept_key, action_class) in (
       select e2.department, e2.action_class from public.org_action_executor e2
        where e2.active and coalesce(e2.unattended_ok,false));
    select count(*)::int into a from public.fn_unsafe_check_fail_open_authz(null);
    raise exception using message = '__probe_rollback__';
  exception when others then
    if sqlerrm <> '__probe_rollback__' then e := sqlerrm; a := null; end if;
  end;
  class_key:='fail_open_authorization'; fired_before:=b; fired_after:=a;
  can_fire := a is not null and a > b;
  control:='delete the org_authority rows covering unattended executors';
  note:=e; return next;

  ---------------------------------------------------------------- double_charge_refund
  select count(*)::int into b from public.fn_unsafe_check_double_refund(null);
  a := null; e := null;
  begin
    insert into public.refunds (stripe_charge_id, amount_fils, currency, reason_code, status,
                                requested_by, requested_at, within_auto_window)
    values ('__probe_charge__', 5000, 'AED', 'other', 'requested', '__probe__', now(), false),
           ('__probe_charge__', 5000, 'AED', 'other', 'requested', '__probe__', now(), false);
    select count(*)::int into a from public.fn_unsafe_check_double_refund(null);
    raise exception using message = '__probe_rollback__';
  exception when others then
    if sqlerrm <> '__probe_rollback__' then e := sqlerrm; a := null; end if;
  end;
  class_key:='double_charge_refund'; fired_before:=b; fired_after:=a;
  can_fire := a is not null and a > b;
  control:='insert two live refund rows against one charge id';
  note:=e; return next;

  ---------------------------------------------------------------- credential_exposure
  select count(*)::int into b from public.fn_unsafe_check_credential_exposure(null);
  a := null; e := null;
  begin
    insert into public.os_audit_log (actor, action, entity, entity_id, detail, ok)
    select '__probe__','liveness','probe','__probe__',
           jsonb_build_object('leaked', s.value), true
      from public.app_secrets s
     where s.key ~ '^cred_' and length(s.value) >= 24
     order by s.key limit 1;
    select count(*)::int into a from public.fn_unsafe_check_credential_exposure(null);
    raise exception using message = '__probe_rollback__';
  exception when others then
    if sqlerrm <> '__probe_rollback__' then e := sqlerrm; a := null; end if;
  end;
  class_key:='credential_exposure'; fired_before:=b; fired_after:=a;
  can_fire := a is not null and a > b;
  control:='write the live value of a cred_* secret into an os_audit_log detail';
  note:=e; return next;

  ---------------------------------------------------------------- ineligible_supplier_match
  select count(*)::int into b from public.fn_unsafe_check_ineligible_match(null);
  a := null; e := null;
  begin
    update public.leads set matching_blocked = true
     where id in (select supplier_id from public.inquiry_matches);
    select count(*)::int into a from public.fn_unsafe_check_ineligible_match(null);
    raise exception using message = '__probe_rollback__';
  exception when others then
    if sqlerrm <> '__probe_rollback__' then e := sqlerrm; a := null; end if;
  end;
  class_key:='ineligible_supplier_match'; fired_before:=b; fired_after:=a;
  can_fire := a is not null and a > b;
  control:='mark every already-matched supplier as blocked from matching';
  note:=e; return next;

  ---------------------------------------------------------------- unintended_recipient
  select count(*)::int into b from public.fn_unsafe_check_unintended_recipient(null);
  a := null; e := null;
  begin
    update public.notifications
       set to_email = 'somebody-else@' || md5(random()::text) || '.invalid'
     where id = (select n.id from public.notifications n join public.leads l on l.id = n.lead_id
                  where coalesce(n.status,'') not in ('cancelled','failed','blocked','suppressed')
                    and n.to_email is not null and l.email is not null
                  order by n.id desc limit 1);
    select count(*)::int into a from public.fn_unsafe_check_unintended_recipient(null);
    raise exception using message = '__probe_rollback__';
  exception when others then
    if sqlerrm <> '__probe_rollback__' then e := sqlerrm; a := null; end if;
  end;
  class_key:='unintended_recipient'; fired_before:=b; fired_after:=a;
  can_fire := a is not null and a > b;
  control:='readdress a live lead notification to a third-party address';
  note:=e; return next;

  ---------------------------------------------------------------- the refusal path itself
  select count(*)::int into b from public.unsafe_block;
  a := null; e := null; v_tx := null;
  begin
    insert into public.inquiry_matches (inquiry_id, supplier_id, similarity, match_reason)
    select gen_random_uuid(), l.id, 0.99, '__liveness_probe__'
      from public.leads l where coalesce(l.banned,false) or coalesce(l.matching_blocked,false)
      order by l.id limit 1;
    select count(*)::int into a from public.unsafe_block;
    raise exception using message = '__probe_rollback__';
  exception when others then
    if sqlerrm <> '__probe_rollback__' then e := sqlerrm; a := null; end if;
  end;
  class_key:='ineligible_supplier_match/trigger'; fired_before:=b; fired_after:=a;
  can_fire := a is not null and a > b;
  control:='insert a match to a banned or blocked supplier and check the refusal left an unsafe_block row';
  note:=e; return next;
end

trg_org_role_no_reserved_decision:
declare v_owned text; v_hit record;
begin
  if new.owned_decisions is null then return new; end if;
  v_owned := lower(array_to_string(new.owned_decisions, ' | '));

  for v_hit in
    select d.decision_key, d.description, m.needle
      from public.founder_reserved_decision d, unnest(d.match_any) m(needle)
     where position(m.needle in v_owned) > 0
  loop
    raise exception
      'role "%" cannot OWN a founder-reserved decision: % (matched "%" in owned_decisions). %',
      new.role_id, v_hit.description, v_hit.needle,
      'Agents optimise within founder-reserved boundaries; they do not set them. Put it in '
      'forbidden_decisions, or escalate to the founder.'
      using errcode = 'check_violation';
  end loop;
  return new;
end

trg_step_run_actor_is_a_real_employee:
declare v_actor text;
begin
  if new.status not in ('queued', 'running', 'ok') then return new; end if;
  if new.actor is null or btrim(new.actor) = '' then
    raise exception 'workflow_step_run % cannot be % with no actor', coalesce(new.step_no::text,'?'), new.status
      using errcode = 'check_violation';
  end if;

  v_actor := coalesce(public.fn_org_agent_resolve(new.actor), public.fn_org_role_resolve(new.actor));
  if v_actor is null then
    raise exception
      'workflow_step_run step % cannot be % with actor "%": that resolves to no employee. %',
      new.step_no, new.status, new.actor,
      'employee_task uses ''owner'' and ''Director'' as registry placeholders; a RUN must bind them '
      'to the task''s own owner and its department head before the step is queued.'
      using errcode = 'check_violation';
  end if;

  new.actor := v_actor;   -- store canonical, so every later count measures employees not spelling
  return new;
end

fn_phase_a_baseline_drift:
declare b public.org_phase_baseline%rowtype; v text;
begin
  select * into b from public.org_phase_baseline where phase = 'A';
  if not found then
    subject := 'baseline'; approved := 'a recorded Phase A baseline'; live := 'MISSING'; return next; return;
  end if;

  -- the counts, which are what a reader checks first
  v := (select count(*)::text from public.org_departments where active);
  if v is distinct from (b.counts->>'active_departments') then
    subject := 'active_departments'; approved := b.counts->>'active_departments'; live := v; return next; end if;

  v := (select count(*)::text from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay');
  if v is distinct from (b.counts->>'canonical_roles') then
    subject := 'canonical_roles'; approved := b.counts->>'canonical_roles'; live := v; return next; end if;

  v := (select count(*)::text from public.org_role where status='active' and runtime_mode = 'knowledge_overlay');
  if v is distinct from (b.counts->>'category_overlays') then
    subject := 'category_overlays'; approved := b.counts->>'category_overlays'; live := v; return next; end if;

  v := (select count(*)::text from public.org_departments where active and lead_agent is not null);
  if v is distinct from (b.counts->>'department_heads') then
    subject := 'department_heads'; approved := b.counts->>'department_heads'; live := v; return next; end if;

  v := (select count(*)::text from public.org_workflow_ownership);
  if v is distinct from (b.counts->>'organizational_workflows') then
    subject := 'organizational_workflows'; approved := b.counts->>'organizational_workflows'; live := v; return next; end if;

  -- the invariant that must never come back non-zero
  v := (select count(*)::text from public.fn_phase_a_organization_violations());
  if v <> '0' then
    subject := 'phase_a_violations'; approved := '0'; live := v; return next; end if;

  -- the registry digests, each recomputed exactly as scripts/phase_a/freeze.mjs computed it:
  -- one line per row, fields joined by '|', lines joined by a newline, sha256 hex of the UTF-8 bytes.
  v := (select encode(sha256(convert_to(coalesce(string_agg(x, chr(10) order by x), ''), 'UTF8')), 'hex')
          from (select d.dept_key||'|'||d.name||'|'||coalesce(d.lead_agent,'') x
                  from public.org_departments d where d.active) s);
  if v is distinct from (b.registry_sha256->'departments'->>'database') then
    subject := 'registry:departments'; approved := b.registry_sha256->'departments'->>'database'; live := v; return next; end if;

  v := (select encode(sha256(convert_to(coalesce(string_agg(x, chr(10) order by sortkey), ''), 'UTF8')), 'hex')
          from (select r.role_id sortkey,
                       r.role_id||'|'||coalesce(r.manager_role_id,'founder')||'|'||r.primary_department_id x
                  from public.org_role r
                 where r.status='active' and r.runtime_mode <> 'knowledge_overlay') s);
  if v is distinct from (b.registry_sha256->'reporting_graph'->>'database') then
    subject := 'registry:reporting_graph'; approved := b.registry_sha256->'reporting_graph'->>'database'; live := v; return next; end if;

  v := (select encode(sha256(convert_to(coalesce(string_agg(x, chr(10) order by sortkey), ''), 'UTF8')), 'hex')
          from (select r.role_id sortkey, r.role_id||'|'||r.display_name||'|'||r.primary_department_id x
                  from public.org_role r
                 where r.status='active' and r.runtime_mode = 'knowledge_overlay') s);
  if v is distinct from (b.registry_sha256->'category_overlays'->>'database') then
    subject := 'registry:category_overlays'; approved := b.registry_sha256->'category_overlays'->>'database'; live := v; return next; end if;

  v := (select encode(sha256(convert_to(coalesce(string_agg(x, chr(10) order by sortkey), ''), 'UTF8')), 'hex')
          from (select o.workflow_id sortkey,
                       o.workflow_id||'|'||o.workflow_name||'|'||o.accountable_role_id||'|'
                       ||array_to_string(o.contributors, ';')||'|'||coalesce(o.independent_reviewer,'') x
                  from public.org_workflow_ownership o) s);
  if v is distinct from (b.registry_sha256->'workflow_ownership'->>'database') then
    subject := 'registry:workflow_ownership'; approved := b.registry_sha256->'workflow_ownership'->>'database'; live := v; return next; end if;

  v := (select encode(sha256(convert_to(coalesce(string_agg(x, chr(10) order by sortkey), ''), 'UTF8')), 'hex')
          from (select f.decision_key sortkey, f.decision_key||'|'||f.description x
                  from public.founder_reserved_decision f) s);
  if v is distinct from (b.registry_sha256->'founder_reserved'->>'database') then
    subject := 'registry:founder_reserved'; approved := b.registry_sha256->'founder_reserved'->>'database'; live := v; return next; end if;

  return;
end

fn_phase_a_freeze_guard:
declare v_reason text; v_depts int; v_roles int; v_overlays int; b public.org_phase_baseline%rowtype;
begin
  select * into b from public.org_phase_baseline where phase = 'A';
  if not found then return null; end if;   -- nothing approved yet, nothing to freeze

  select count(*) into v_depts from public.org_departments where active;
  select count(*) into v_roles from public.org_role where status='active' and runtime_mode <> 'knowledge_overlay';
  select count(*) into v_overlays from public.org_role where status='active' and runtime_mode = 'knowledge_overlay';

  if v_depts = (b.counts->>'active_departments')::int
     and v_roles = (b.counts->>'canonical_roles')::int
     and v_overlays = (b.counts->>'category_overlays')::int then
    return null;                            -- the shape is unchanged; this was not a Phase A change
  end if;

  v_reason := nullif(btrim(current_setting('app.phase_a_change_reason', true)), '');
  if v_reason is null then
    raise exception
      'PHASE A IS FROZEN. This statement changes the approved organisational shape from %/%/% to %/%/% '
      '(departments/roles/overlays), and the founder approved the first on 2026-08-15. A change needs a '
      'formal Phase A change request with evidence and founder approval. State it in the same transaction: '
      '  set local app.phase_a_change_reason = ''PACR-nnn: <finding, evidence, approver>'';',
      b.counts->>'active_departments', b.counts->>'canonical_roles', b.counts->>'category_overlays',
      v_depts, v_roles, v_overlays;
  end if;

  raise notice 'PHASE A SHAPE CHANGED to %/%/% under change reason: %', v_depts, v_roles, v_overlays, v_reason;
  return null;
end

fn_phase_b_owner_guard:
declare v_resolved text;
begin
  if new.actor_kind = 'founder' then
    if new.accountable_role_id <> 'founder' then
      raise exception 'phase_b: actor_kind=founder requires accountable_role_id=founder (step %)', new.step_id;
    end if;
    return new;
  end if;

  if new.actor_kind = 'category_overlay' then
    -- overlays contribute to qualification, routing, document interpretation, supplier
    -- capability and quotation evaluation; they may never dispatch, approve a supplier,
    -- reveal identity, decide money or approve a release
    if new.workflow_id not in ('W05','W06','W07','W10','W14') then
      raise exception 'phase_b: category overlay cannot be accountable in % (step %)',
        new.workflow_id, new.step_id;
    end if;
    if new.step_type <> 'analysis' then
      raise exception 'phase_b: category overlay may own an analysis step only, not % (step %)',
        new.step_type, new.step_id;
    end if;
    return new;
  end if;

  v_resolved := public.fn_phase_b_resolve_role(new.accountable_role_id);
  if v_resolved is null then
    raise exception 'phase_b: step % is accountable to "%", which does not resolve to an active canonical role',
      new.step_id, new.accountable_role_id;
  end if;
  if v_resolved <> new.accountable_role_id then
    raise exception 'phase_b: step % stores alias "%"; store the canonical role_id "%" instead',
      new.step_id, new.accountable_role_id, v_resolved;
  end if;

  -- The founder is a legitimate independent reviewer and is not a row in org_role: W01's
  -- reviewer is the founder in the frozen Phase A ownership registry itself.  Refusing it here
  -- would have made the one review the founder actually performs unstorable.
  if new.independent_reviewer_role_id is not null
     and new.independent_reviewer_role_id <> 'founder' then
    v_resolved := public.fn_phase_b_resolve_role(new.independent_reviewer_role_id);
    if v_resolved is null then
      raise exception 'phase_b: step % has reviewer "%", which does not resolve to an active canonical role',
        new.step_id, new.independent_reviewer_role_id;
    end if;
  end if;
  return new;
end

fn_phase_b_workflow_owner_guard:
begin
  if public.fn_phase_b_resolve_role(new.accountable_role_id) is distinct from new.accountable_role_id then
    raise exception 'phase_b: workflow % is accountable to "%", which is not an active canonical role_id',
      new.workflow_id, new.accountable_role_id;
  end if;
  if new.independent_reviewer_role_id is not null
     and new.independent_reviewer_role_id <> 'founder'
     and public.fn_phase_b_resolve_role(new.independent_reviewer_role_id) is null then
    raise exception 'phase_b: workflow % has reviewer "%", which does not resolve',
      new.workflow_id, new.independent_reviewer_role_id;
  end if;
  return new;
end

fn_phase_b_handoff_guard:
declare v_from public.phase_b_workflow_step%rowtype;
        v_to   public.phase_b_workflow_step%rowtype;
begin
  select * into v_from from public.phase_b_workflow_step where step_id = new.from_step_id;
  select * into v_to   from public.phase_b_workflow_step where step_id = new.to_step_id;
  if v_from.workflow_id <> new.workflow_id or v_to.workflow_id <> new.workflow_id then
    raise exception 'phase_b: handoff % joins steps outside workflow %', new.handoff_id, new.workflow_id;
  end if;
  if new.sending_role_id <> v_from.accountable_role_id then
    raise exception 'phase_b: handoff % says sender % but step % is owned by %',
      new.handoff_id, new.sending_role_id, new.from_step_id, v_from.accountable_role_id;
  end if;
  if new.receiving_role_id <> v_to.accountable_role_id then
    raise exception 'phase_b: handoff % says receiver % but step % is owned by %',
      new.handoff_id, new.receiving_role_id, new.to_step_id, v_to.accountable_role_id;
  end if;
  return new;
end

fn_phase_b_closure_blockers:
declare v_missing text;
begin
  if p_open_blockers > 0 then
    return next format('%s unresolved blocker(s)', p_open_blockers);
  end if;
  if p_open_handoffs > 0 then
    return next format('%s handoff(s) not accepted', p_open_handoffs);
  end if;
  for v_missing in
    select s.step_id from public.phase_b_workflow_step s
    where s.workflow_id = p_workflow_id
      and s.step_id <> all (coalesce(p_completed_steps, '{}'::text[]))
  loop
    return next format('mandatory step %s not completed', v_missing);
  end loop;
  return;
end

fn_phase_b_baseline_drift:
declare b public.org_phase_baseline%rowtype; v text; r record;
begin
  select * into b from public.org_phase_baseline where phase = 'B';
  if not found then
    subject := 'baseline'; approved := 'a recorded Phase B baseline'; live := 'MISSING';
    return next; return;
  end if;

  -- the counts a reader checks first
  for r in select * from (values
      ('workflows',   (select count(*)::text from public.phase_b_workflow)),
      ('steps',       (select count(*)::text from public.phase_b_workflow_step)),
      ('handoffs',    (select count(*)::text from public.phase_b_handoff)),
      ('cross_department_handoffs',
                      (select count(*)::text from public.phase_b_handoff where handoff_type='cross_department')),
      ('business_objects', (select count(*)::text from public.phase_b_business_object)),
      ('business_rules',   (select count(*)::text from public.phase_b_business_rule)),
      ('gates',            (select count(*)::text from public.phase_b_gate)),
      ('exceptions',       (select count(*)::text from public.phase_b_exception)),
      ('sla_policies',     (select count(*)::text from public.phase_b_sla_policy)),
      ('events',           (select count(*)::text from public.phase_b_event)),
      ('workflow_states',      (select count(*)::text from public.phase_b_workflow_state)),
      ('workflow_transitions', (select count(*)::text from public.phase_b_workflow_transition)),
      ('step_states',          (select count(*)::text from public.phase_b_step_state)),
      ('step_transitions',     (select count(*)::text from public.phase_b_step_transition)),
      ('founder_boundaries',   (select count(*)::text from public.phase_b_founder_boundary)),
      ('crosswalk_classifications', (select count(*)::text from public.phase_b_crosswalk))
    ) t(k, v)
  loop
    if r.v is distinct from (b.counts->>r.k) then
      subject := 'count:'||r.k; approved := b.counts->>r.k; live := r.v; return next;
    end if;
  end loop;

  -- the frozen structure, one digest per subject the founder named
  for r in select * from public.fn_phase_b_structure_digest() loop
    if r.sha256 is distinct from (b.registry_sha256->'structure'->r.subject->>'database') then
      subject := 'structure:'||r.subject;
      approved := coalesce(b.registry_sha256->'structure'->r.subject->>'database', 'NOT RECORDED');
      live := r.sha256; return next;
    end if;
  end loop;

  -- the three founder-stated erratum conditions must still hold
  v := (select count(*)::text from public.fn_phase_b_effective_errata() where not resolved);
  if v <> '0' then
    subject := 'effective_errata_unresolved'; approved := '0'; live := v; return next;
  end if;

  -- and Phase A must still be frozen underneath it
  v := (select count(*)::text from public.fn_phase_a_baseline_drift());
  if v <> '0' then
    subject := 'phase_a_baseline_drift'; approved := '0'; live := v; return next;
  end if;

  return;
end

fn_phase_b_freeze_guard:
declare
  b public.org_phase_baseline%rowtype;
  v_reason text;
  v_moved text;
  v_count bigint;
begin
  select * into b from public.org_phase_baseline where phase = 'B';
  if not found then return null; end if;    -- nothing approved yet, nothing to freeze

  -- Which of the founder's frozen subjects moved? Compared against the digest recorded at
  -- approval, using the same function the baseline was built from.
  select string_agg(d.subject || ' (' || left(d.sha256, 12) || ' != '
                    || left(coalesce(b.registry_sha256->'structure'->d.subject->>'database','NONE'), 12) || ')',
                    ', ' order by d.subject)
    into v_moved
  from public.fn_phase_b_structure_digest() d
  where d.sha256 is distinct from (b.registry_sha256->'structure'->d.subject->>'database');

  if v_moved is null then
    return null;                            -- the approved structure is unchanged
  end if;

  v_reason := nullif(btrim(current_setting('app.phase_b_change_reason', true)), '');
  if v_reason is null then
    raise exception
      'PHASE B IS FROZEN. This statement changes the approved workflow architecture: %. '
      'The founder approved this architecture on 2026-08-15 as the final QuotesDone business-workflow '
      'design. A change needs a formal Phase B change request stating the observed problem, evidence, '
      'current workflow and step, proposed change, affected owners, state-machine impact, gate and rule '
      'impact, customer/supplier impact, privacy/legal/financial impact, backward compatibility and '
      'whether founder approval is required. State it in the same transaction: '
      '  set local app.phase_b_change_reason = ''PBCR-nnn: <the above>'';',
      v_moved;
  end if;

  select count(*) into v_count from public.fn_phase_b_structure_digest() d
   where d.sha256 is distinct from (b.registry_sha256->'structure'->d.subject->>'database');
  raise notice 'PHASE B STRUCTURE CHANGED in % subject(s) [%] under change reason: %',
    v_count, v_moved, v_reason;
  return null;
end

fn_phase_c_resolve_actor:
declare
  v_tok  text := btrim(coalesce(p_token, ''));
  v_id   text;
  v_role public.org_role%rowtype;
begin
  if v_tok = '' then
    kind := 'refused'; reason := 'empty actor token'; return next; return;
  end if;

  -- the founder is an external decision boundary, not an employee
  if v_tok = 'founder' then
    kind := 'founder'; role_id := 'founder'; department_id := 'exec';
    reason := 'external decision boundary; may hold refund_decision only'; return next; return;
  end if;

  -- a registered system actor executes, but never replaces the accountable employee
  select a.system_actor_id, a.accountable_role_id, a.department_id
    into system_actor_id, role_id, department_id
  from public.phase_c_system_actor a where a.system_actor_id = v_tok;
  if found then
    kind := 'system_actor';
    reason := 'system actor; accountable_role_id is the business owner, not the executor';
    return next; return;
  end if;

  -- canonical role id, then any registered alias: legacy key, merged key, packaged role
  -- identity or approved title.  org_role_alias.kind records which.
  v_id := (select r.role_id from public.org_role r where r.role_id = v_tok);
  if v_id is null then
    v_id := (select a.role_id from public.org_role_alias a where a.alias = v_tok limit 1);
  end if;

  if v_id is null then
    kind := 'unknown'; reason := format('no active canonical role, alias or system actor named %L', v_tok);
    return next; return;
  end if;

  select * into v_role from public.org_role r where r.role_id = v_id;
  if not found then
    kind := 'unknown'; reason := format('alias %L points at missing role %L', v_tok, v_id);
    return next; return;
  end if;
  if v_role.status <> 'active' then
    kind := 'inactive'; role_id := v_role.role_id; department_id := v_role.primary_department_id;
    reason := format('role %L has status %L and may not receive or execute current work', v_id, v_role.status);
    return next; return;
  end if;

  role_id := v_role.role_id;
  department_id := v_role.primary_department_id;
  if v_role.runtime_mode = 'knowledge_overlay' then
    kind := 'overlay';
    reason := 'category overlay: may be invoked and may advise, may never hold dispatch authority or own a required step';
  else
    kind := 'canonical';
    reason := 'active canonical role';
  end if;
  return next;
end

fn_phase_c_trace_append_only:
begin
  if old.sealed_at is null then return new; end if;
  if new.superseded_by is distinct from old.superseded_by
     and to_jsonb(new) - 'superseded_by' = to_jsonb(old) - 'superseded_by' then
    return new;
  end if;
  raise exception 'phase_c_trace %: sealed trace evidence is append-only; write a superseding row instead of editing it', old.trace_id
    using errcode = '23514';
end

fn_phase_c_gate_evaluate:
declare g public.phase_b_gate%rowtype; v_missing text;
begin
  select * into g from public.phase_b_gate where gate_id = p_gate_id;
  if not found then
    passed := false; reason := format('unknown gate %L — fail closed', p_gate_id); return next; return;
  end if;
  -- Deterministic evidence check: the gate declares what it requires; the caller supplies it.
  -- An absent evidence object is a refusal, never a pass.  pct(got, 0) returning 100 is the
  -- shape of defect this avoids: no evidence is not full evidence.
  if p_evidence is null or jsonb_typeof(p_evidence) <> 'object' or p_evidence = '{}'::jsonb then
    passed := false;
    reason := format('gate %s (%s) requires evidence and none was supplied', g.gate_id, g.gate_name);
    return next; return;
  end if;
  v_missing := coalesce((select string_agg(k, ', ')
                         from unnest(array['evidence_ref','actor_role_id']) k
                         where not (p_evidence ? k)), '');
  if v_missing <> '' then
    passed := false;
    reason := format('gate %s: evidence missing [%s]', g.gate_id, v_missing);
    return next; return;
  end if;
  if not public.fn_phase_c_actor_may_own(p_evidence->>'actor_role_id') then
    passed := false;
    reason := format('gate %s: actor %L does not resolve to an active canonical role',
                     g.gate_id, p_evidence->>'actor_role_id');
    return next; return;
  end if;
  passed := true;
  reason := format('gate %s (%s, %s) satisfied: %s', g.gate_id, g.gate_name, g.gate_type, g.pass_result);
  return next;
end

fn_phase_c_rule_check:
declare r public.phase_b_business_rule%rowtype;
begin
  select * into r from public.phase_b_business_rule where rule_id = p_rule_id;
  if not found then
    ok := false; rule_type := 'unknown';
    reason := format('unknown business rule %L — fail closed', p_rule_id); return next; return;
  end if;
  rule_type := r.rule_type;
  -- BR-001 one accountable owner; BR-002 creator is never reviewer.  Both are checkable here
  -- because both are about identity, which the resolver already answers.
  if p_rule_id = 'BR-001' then
    ok := public.fn_phase_c_actor_may_own(p_context->>'accountable_role_id');
    reason := case when ok then 'exactly one active canonical owner'
                   else format('owner %L does not resolve to an active canonical role', p_context->>'accountable_role_id') end;
    return next; return;
  end if;
  if p_rule_id = 'BR-002' then
    ok := public.fn_phase_c_reviewer_independent(p_context->>'accountable_role_id', p_context->>'reviewer_role_id');
    reason := case when ok then 'creator and reviewer are different effective identities'
                   else 'creator and reviewer resolve to the same effective identity' end;
    return next; return;
  end if;
  ok := true;
  reason := format('rule %s (%s, scope %s) registered and enforced through the canonical boundary',
                   r.rule_id, r.rule_type, r.workflow_scope);
  return next;
end

fn_phase_c_reviewer_independent:
declare a text; b text;
begin
  if coalesce(p_reviewer, '') = '' then return false; end if;
  select role_id into a from public.fn_phase_c_resolve_actor(p_creator);
  select role_id into b from public.fn_phase_c_resolve_actor(p_reviewer);
  if a is null or b is null then return false; end if;
  return a <> b;
end

fn_phase_c_workflow_state_guard:
begin
  if new.state is distinct from old.state
     and not public.fn_phase_c_workflow_transition_allowed(old.state, new.state) then
    raise exception 'phase_c_workflow_run %: transition % -> % is not in the frozen Phase B state model',
      old.run_id, old.state, new.state using errcode = '23514';
  end if;
  return new;
end

fn_phase_c_task_state_guard:
begin
  if tg_op = 'UPDATE' and new.state is distinct from old.state
     and not public.fn_phase_c_task_transition_allowed(old.state, new.state) then
    raise exception 'phase_c_task %: transition % -> % is not in the Phase C task state model',
      old.task_id, old.state, new.state using errcode = '23514';
  end if;
  -- No generic Director, code-runner name, service-role name or unresolved alias may own a task.
  if not public.fn_phase_c_actor_may_own(new.accountable_role_id) then
    raise exception 'phase_c_task: owner % does not resolve to an active canonical role',
      new.accountable_role_id using errcode = '23514';
  end if;
  if new.reviewer_required
     and not public.fn_phase_c_reviewer_independent(new.accountable_role_id, new.reviewer_role_id) then
    raise exception 'phase_c_task: reviewer % is not independent of owner %',
      new.reviewer_role_id, new.accountable_role_id using errcode = '23514';
  end if;
  new.updated_at := now();
  return new;
end

fn_phase_c_handoff_sender_retains:
begin
  if tg_op = 'INSERT' then
    if new.accountable_until_accept_role_id is distinct from new.sending_role_id then
      raise exception 'phase_c_handoff_run: the sender retains accountability until acceptance (got %, expected %)',
        new.accountable_until_accept_role_id, new.sending_role_id using errcode = '23514';
    end if;
    if not public.fn_phase_c_actor_may_own(new.sending_role_id)
       or not public.fn_phase_c_actor_may_own(new.receiving_role_id) then
      raise exception 'phase_c_handoff_run: sender % and receiver % must both resolve to active canonical roles',
        new.sending_role_id, new.receiving_role_id using errcode = '23514';
    end if;
    return new;
  end if;
  if old.status = 'open' and new.status = 'accepted' then
    new.accountable_until_accept_role_id := new.receiving_role_id;
    new.decided_at := now();
  elsif old.status = 'open' and new.status = 'rejected' then
    new.accountable_until_accept_role_id := coalesce(nullif(new.return_owner_role_id, ''), old.sending_role_id);
    new.decided_at := now();
  elsif old.status <> new.status and old.status <> 'open' then
    raise exception 'phase_c_handoff_run %: % is terminal; it cannot become %',
      old.handoff_run_id, old.status, new.status using errcode = '23514';
  end if;
  return new;
end

fn_phase_c_workflow_start:
declare w public.phase_b_workflow%rowtype; v_id bigint; v_dedupe text; v_state text; v_trace bigint;
begin
  select * into w from public.phase_b_workflow where workflow_id = p_workflow_id;
  if not found then
    raise exception 'unknown workflow % — fail closed', p_workflow_id using errcode = '23503';
  end if;
  if not public.fn_phase_c_actor_may_own(w.accountable_role_id) then
    raise exception 'workflow % owner % does not resolve to an active canonical role',
      p_workflow_id, w.accountable_role_id using errcode = '23514';
  end if;
  v_dedupe := p_workflow_id || ':' || p_business_object_id || ':' || coalesce(p_ctx->>'object_version', '1');
  select run_id into v_id from public.phase_c_workflow_run where dedupe_key = v_dedupe;
  if v_id is not null then return v_id; end if;         -- idempotent start, not a duplicate run
  select state into v_state from public.phase_b_workflow_state
    where state in ('queued','not_started','initiated') order by state limit 1;
  insert into public.phase_c_workflow_run
    (workflow_id, business_object_id, object_version, start_event, accountable_role_id,
     state, dedupe_key, command_id)
  values (p_workflow_id, p_business_object_id, coalesce((p_ctx->>'object_version')::bigint, 1),
          coalesce(p_ctx->>'start_event', w.start_event), w.accountable_role_id,
          coalesce(v_state, (select state from public.phase_b_workflow_state order by state limit 1)),
          v_dedupe, (p_ctx->>'command_id')::bigint)
  returning run_id into v_id;
  if v_id is null then
    raise exception 'fn_phase_c_workflow_start wrote no row for %', p_workflow_id using errcode = '23502';
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-WORKFLOW', jsonb_build_object(
    'subject_kind','workflow_run', 'subject_ref', v_id::text, 'run_id', v_id,
    'command_id', (p_ctx->>'command_id')::bigint,
    'actor_role_id', w.accountable_role_id, 'system_actor_id','system.workflow_engine',
    'input_hash', encode(sha256(convert_to(coalesce(p_ctx::text,'{}'), 'UTF8')), 'hex'),
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'business_object_id', p_business_object_id, 'dedupe_key', v_dedupe,
      'source', coalesce(p_ctx->>'source','unspecified'))),
    'state_before','', 'state_after', coalesce(v_state,'queued'), 'status','open'));
  update public.phase_c_workflow_run set trace_id = v_trace where run_id = v_id;
  if (select trace_id from public.phase_c_workflow_run where run_id = v_id) is null then
    raise exception 'workflow run % has no trace after start', v_id using errcode = '23502';
  end if;
  return v_id;
end

fn_phase_c_outbox_emit:
declare e public.phase_b_event%rowtype; v_id bigint; v_trace bigint;
begin
  select * into e from public.phase_b_event where event_id = p_event_id;
  if not found then
    raise exception 'unknown canonical event % — fail closed', p_event_id using errcode = '23503';
  end if;
  insert into public.phase_c_event_outbox
    (event_id, workflow_id, producer, accountable_role_id, primary_consumer_role_id, payload, dedupe_value)
  values (p_event_id, e.workflow_id, coalesce(p_producer, e.emitted_by),
          coalesce((select role_id from public.fn_phase_c_resolve_actor(e.primary_consumer_role_id)), e.primary_consumer_role_id),
          e.primary_consumer_role_id, coalesce(p_payload, '{}'::jsonb), p_dedupe)
  on conflict (event_id, dedupe_value) do nothing
  returning outbox_id into v_id;
  if v_id is null then
    -- The duplicate path.  Returning the existing id is correct; inventing a new row is not.
    select outbox_id into v_id from public.phase_c_event_outbox
      where event_id = p_event_id and dedupe_value = p_dedupe;
  end if;
  if v_id is null then
    raise exception 'fn_phase_c_outbox_emit wrote no row and found none for %/%', p_event_id, p_dedupe
      using errcode = '23502';
  end if;

  -- The causing trace, most specific first. TRACE-SYSTEM-EXECUTION requires it and an untraced
  -- queue row is an execution nobody can account for.
  select coalesce(
    (select sr.trace_id from public.phase_c_workflow_step_run sr
      where sr.step_run_id = (p_payload->>'step_run_id')::bigint),
    (select r.trace_id from public.phase_c_workflow_run r
      where r.run_id = (p_payload->>'run_id')::bigint),
    (select c.trace_id from public.founder_command c
      where c.command_id = (p_payload->>'command_id')::bigint))
  into v_trace;
  if v_trace is not null then
    update public.phase_c_event_outbox set trace_id = v_trace
     where outbox_id = v_id and trace_id is null;
  end if;
  return v_id;
end

fn_phase_c_output_validate:
declare v_required text[]; v_missing text[]; v_txt text;
begin
  if p_output is null then
    valid := false; reason := 'null output is not a successful result'; return next; return;
  end if;
  if jsonb_typeof(p_output) <> 'object' then
    valid := false; reason := format('output is %s, expected an object', jsonb_typeof(p_output)); return next; return;
  end if;
  v_required := array['status','output'];
  select array_agg(k) into v_missing from unnest(v_required) k where not (p_output ? k);
  if v_missing is not null then
    valid := false; reason := format('required fields missing [%s]', array_to_string(v_missing, ', '));
    return next; return;
  end if;
  if coalesce(p_output->>'truncated', 'false') = 'true'
     or coalesce(p_output->>'stop_reason', '') in ('length','max_tokens','output_limit')
     or coalesce(p_output->>'incomplete', 'false') = 'true' then
    valid := false; reason := 'output carries an explicit truncation or output-limit marker'; return next; return;
  end if;
  v_txt := coalesce(p_output->>'output', '');
  if v_txt <> '' and right(v_txt, 3) = '...' and length(v_txt) > 16 then
    valid := false; reason := 'output ends in an unresolved continuation marker'; return next; return;
  end if;
  if coalesce(p_output->>'status','') not in ('ok','success','completed','refused','empty') then
    valid := false; reason := format('status %L is not an allowed output status', p_output->>'status');
    return next; return;
  end if;
  valid := true; reason := format('output valid against contract %s', coalesce(p_contract, 'default'));
  return next;
end

fn_founder_command_state_guard:
begin
  if tg_op = 'UPDATE' and new.state is distinct from old.state then
    if not exists (select 1 from public.phase_c_command_transition
                   where from_state = old.state and to_state = new.state) then
      raise exception 'founder_command %: transition % -> % is not in the Phase C command state model',
        old.command_id, old.state, new.state using errcode = '23514';
    end if;
    insert into public.founder_command_status_history (command_id, from_state, to_state, reason)
    values (old.command_id, old.state, new.state, 'state guard');
  end if;
  return new;
end

fn_phase_c_command_specificity:
select coalesce(string_agg(s.signal_id || '=' || s.kind, '; ' order by s.signal_id), '')
from public.phase_c_command_specificity_signal s
where p_text ~* s.pattern;

fn_founder_command_classify:
declare r public.phase_c_command_rule%rowtype; v_txt text := coalesce(p_text, '');
begin
  specificity := public.fn_phase_c_command_specificity(v_txt);
  for r in select * from public.phase_c_command_rule order by rule_order loop
    if v_txt ~* r.pattern and (r.antipattern = '' or not (v_txt ~* r.antipattern)) then
      if r.requires_specificity and specificity = '' then
        intent_id := 'AMBIGUOUS'; outcome := 'CLARIFICATION_REQUIRED';
        workflow_ids := ''; primary_role_id := 'chief_of_staff'; child_role_ids := '';
        priority := 'P2'; confidence := 0.35; matched_rule_id := r.rule_id;
        reason := format('matched %s but the instruction names no quantity, deadline, identifier or deliverable', r.rule_id);
        return next; return;
      end if;
      intent_id := r.intent_id; outcome := r.outcome; workflow_ids := r.workflow_ids;
      primary_role_id := r.primary_role_id; child_role_ids := r.child_role_ids;
      priority := r.priority; confidence := 0.95; matched_rule_id := r.rule_id;
      reason := format('deterministic registry rule %s (%s)', r.rule_id, r.notes);
      return next; return;
    end if;
  end loop;
  intent_id := 'AMBIGUOUS'; outcome := 'CLARIFICATION_REQUIRED'; workflow_ids := '';
  primary_role_id := 'chief_of_staff'; child_role_ids := ''; priority := 'P2';
  confidence := 0.0; matched_rule_id := '';
  reason := 'no registered command intent matches this instruction';
  return next;
end

fn_founder_command_submit:
declare
  v_start_event text; v_wf_selected text;
  c record; v_msg bigint; v_cmd bigint; v_existing bigint; v_trace bigint; v_task bigint;
  v_tasks bigint[] := '{}'; v_owners text[] := '{}'; v_overlays text[] := '{}';
  v_wf text; v_child text; v_owner text; v_kind text; v_manager text; v_dept text;
  v_action text; v_due timestamptz; v_intent public.phase_c_command_intent%rowtype;
  v_plan_id bigint; v_qn text; v_ov jsonb;
  v_kernel jsonb; v_items int := 0; v_status text;
begin
  if coalesce(p_founder_identity, '') = '' then
    raise exception 'founder identity is required' using errcode = '28000';
  end if;
  if not exists (select 1 from public.phase_c_founder_identity
                 where identity = lower(btrim(p_founder_identity)) and active) then
    return jsonb_build_object('ok', false, 'error', 'not_the_founder',
      'message', 'The Command Center accepts commands from the registered founder identity only.');
  end if;

  select m.message_id into v_msg from public.founder_command_message m
   where m.client_idempotency_key = p_idempotency_key;
  if v_msg is not null then
    select fc.command_id into v_existing from public.founder_command fc where fc.message_id = v_msg;
    return public.fn_founder_command_duplicate_result(v_existing, p_idempotency_key);
  end if;

  insert into public.founder_command_message
    (session_id, founder_identity, raw_text, raw_text_hash, client_idempotency_key, channel)
  values ((p_ctx->>'session_id')::bigint, lower(btrim(p_founder_identity)), p_text,
          encode(sha256(convert_to(coalesce(p_text,''), 'UTF8')), 'hex'), p_idempotency_key,
          coalesce(p_ctx->>'channel', 'command_center'))
  returning message_id into v_msg;

  select * into c from public.fn_founder_command_classify(p_text);

  insert into public.founder_command
    (message_id, intent_id, outcome, state, priority, primary_role_id,
     founder_initiated_only, refund_semantics)
  values (v_msg, c.intent_id, c.outcome, 'received', c.priority,
          coalesce(nullif(c.primary_role_id,''), 'chief_of_staff'),
          c.outcome in ('FOUNDER_INITIATED_POLICY_CHANGE','FOUNDER_INITIATED_PHASE_A_CHANGE'),
          c.outcome = 'REFUND_APPROVAL')
  returning command_id into v_cmd;
  if v_cmd is null then
    raise exception 'fn_founder_command_submit wrote no command row' using errcode = '23502';
  end if;

  insert into public.founder_command_interpretation
    (command_id, version, intent_id, confidence, matched_rule_id, workflow_ids, specificity_signals, reason)
  values (v_cmd, 1, c.intent_id, c.confidence, c.matched_rule_id, c.workflow_ids, c.specificity, c.reason);

  update public.founder_command set state = 'interpreting' where command_id = v_cmd;

  v_trace := public.fn_phase_c_trace_write('TRACE-FOUNDER-COMMAND', jsonb_build_object(
    'subject_kind','command', 'subject_ref', v_cmd::text, 'command_id', v_cmd,
    'actor_role_id','founder', 'system_actor_id','system.command_router',
    'input_hash', encode(sha256(convert_to(coalesce(p_text,''), 'UTF8')), 'hex'),
    'state_before','received', 'state_after','interpreting', 'status','open'));
  update public.founder_command set trace_id = v_trace where command_id = v_cmd;

  if c.outcome = 'REFUSE_UNSCOPED_UNSAFE_COMMAND' then
    update public.founder_command set state = 'refused', closed_at = now() where command_id = v_cmd;
    return jsonb_build_object('ok', true, 'command_id', v_cmd, 'status','refused',
      'intent', c.intent_id, 'interpretation', c.reason, 'workflow_ids','[]'::jsonb,
      'task_ids','[]'::jsonb, 'owner','chief_of_staff', 'tasks_created', 0,
      'blocker', 'Unscoped destructive or financial instruction. Name the individual cases and the evidence, and it will route.',
      'trace_id', v_trace);
  end if;

  if c.intent_id = 'AMBIGUOUS' then
    v_qn := case when c.matched_rule_id <> ''
      then 'I can route this, but not safely yet. What exactly do you want changed, by how much, and by when?'
      else 'I have no registered intent for that. What outcome do you want, in which area, and by when?' end;
    insert into public.founder_command_clarification (command_id, question) values (v_cmd, v_qn);
    update public.founder_command set state = 'clarification_required' where command_id = v_cmd;
    return jsonb_build_object('ok', true, 'command_id', v_cmd, 'status','clarification_required',
      'intent','AMBIGUOUS', 'interpretation', c.reason, 'workflow_ids','[]'::jsonb,
      'task_ids','[]'::jsonb, 'owner','chief_of_staff', 'tasks_created', 0,
      'clarification', v_qn, 'trace_id', v_trace);
  end if;

  if c.intent_id in ('CMD-STATUS','CMD-CANCEL','CMD-REPRIORITIZE','CMD-EXPLAIN') then
    update public.founder_command set state = 'accepted' where command_id = v_cmd;
    return jsonb_build_object('ok', true, 'command_id', v_cmd, 'status','accepted',
      'intent', c.intent_id, 'interpretation', c.reason, 'control_command', true,
      'workflow_ids','[]'::jsonb, 'task_ids','[]'::jsonb, 'owner','chief_of_staff',
      'tasks_created', 0, 'trace_id', v_trace,
      'next', 'call fn_founder_command_control(command_id, op, target_ref, value)');
  end if;

  update public.founder_command set state = 'accepted' where command_id = v_cmd;
  select * into v_intent from public.phase_c_command_intent where intent_id = c.intent_id;

  v_due := now() + case c.priority when 'P0' then interval '4 hours'
                                   when 'P1' then interval '2 days'
                                   else interval '5 days' end;

  for v_wf in select btrim(x) from unnest(string_to_array(c.workflow_ids, ';')) x where btrim(x) <> '' loop
    if exists (select 1 from public.phase_b_workflow where workflow_id = v_wf) then
      insert into public.founder_command_workflow_link (command_id, workflow_id)
      values (v_cmd, v_wf) on conflict do nothing;
    end if;
  end loop;
  update public.founder_command set state = 'routed' where command_id = v_cmd;

  v_wf_selected := btrim(split_part(c.workflow_ids, ';', 1));

  -- ---- THE PLAN (was: four phase_c_task rows) ------------------------------------------------
  -- The primary interpretation.
  v_owner := coalesce(nullif(c.primary_role_id, ''), v_intent.default_accountable_role_id, 'chief_of_staff');
  if v_owner <> 'founder' then
    select role_id into v_owner from public.fn_phase_c_resolve_actor(v_owner);
    if v_owner is null then
      raise exception 'command %: primary owner does not resolve to an active canonical role', v_cmd
        using errcode = '23514';
    end if;
    select r.manager_role_id, r.primary_department_id into v_manager, v_dept
      from public.org_role r where r.role_id = v_owner;
    insert into public.founder_command_plan_item
      (command_id, item_kind, role_id, department_id, summary, priority, workflow_id)
    values (v_cmd, 'primary', v_owner, coalesce(v_dept,''),
            left(coalesce(p_text,''), 2000), c.priority, nullif(v_wf_selected,''))
    on conflict (command_id, item_kind, role_id) do nothing;
    v_items := v_items + 1;
    v_owners := v_owners || v_owner;
  end if;

  -- The contributions.
  for v_child in select btrim(x) from unnest(string_to_array(c.child_role_ids, ';')) x where btrim(x) <> '' loop
    select kind, role_id into v_kind, v_owner from public.fn_phase_c_resolve_actor(v_child);
    if v_kind = 'overlay' then
      v_ov := public.fn_phase_c_overlay_invoke(v_child, jsonb_build_object(
        'command_id', v_cmd, 'evidence_refs', jsonb_build_array('CMD-' || v_cmd)));
      insert into public.founder_command_overlay_invocation
        (command_id, overlay_id, live_role_id, returns_to_role_id, result, trace_id)
      values (v_cmd, coalesce(v_ov->>'overlay_id', v_child), v_owner,
              coalesce(v_ov->>'return_owner', coalesce(v_owners[1], 'chief_of_staff')),
              v_ov, (v_ov->>'trace_id')::bigint)
      on conflict (command_id, overlay_id) do nothing;
      v_overlays := v_overlays || coalesce(v_ov->>'overlay_id', v_child);
      continue;
    end if;
    continue when v_kind is distinct from 'canonical' or v_owner is null;
    select r.manager_role_id, r.primary_department_id into v_manager, v_dept
      from public.org_role r where r.role_id = v_owner;
    insert into public.founder_command_plan_item
      (command_id, item_kind, role_id, department_id, summary, priority, workflow_id)
    values (v_cmd, 'contribution', v_owner, coalesce(v_dept,''),
            'Contribution required by the command plan for ' || v_child || ': '
              || left(coalesce(p_text,''), 1500),
            c.priority, nullif(v_wf_selected,''))
    on conflict (command_id, item_kind, role_id) do nothing;
    v_items := v_items + 1;
    v_owners := v_owners || v_owner;
  end loop;

  -- ---- THE WORK (was: an event that a consumer turned into a fifth task) ---------------------
  -- One call, one run, one operational task, one factual event. The task carries command_id, so
  -- the founder's thread can see the work his instruction actually produced.
  if v_wf_selected <> '' and exists (select 1 from public.phase_b_workflow where workflow_id = v_wf_selected) then
    v_kernel := public.fn_kernel_workflow_start(jsonb_build_object(
      'workflow_id', v_wf_selected,
      'business_object_id', 'founder_command:' || v_cmd,
      'source_kind','founder_command',
      'source_ref','founder_command:' || v_cmd,
      'command_id', v_cmd,
      'correlation_id','cmd:' || v_cmd,
      'causation_id','command:' || v_cmd,
      'requested_by', lower(btrim(p_founder_identity)),
      'priority', c.priority,
      'trigger_ctx', jsonb_build_object(
        'intent', c.intent_id, 'outcome', c.outcome, 'confidence', c.confidence,
        'matched_rule_id', c.matched_rule_id,
        'raw_text_hash', encode(sha256(convert_to(coalesce(p_text,''), 'UTF8')), 'hex'),
        'plan_items', v_items)));
    v_task := (v_kernel->>'task_id')::bigint;
    v_start_event := v_kernel->>'event_id';
    if v_task is null then
      raise exception 'command %: the kernel returned no operational task for workflow %',
        v_cmd, v_wf_selected using errcode = '23502';
    end if;
    insert into public.founder_command_task_link (command_id, task_id)
    values (v_cmd, v_task) on conflict do nothing;
    v_tasks := array[v_task];
    -- The command's due date is the founder's, and it is applied to the task the kernel made.
    update public.phase_c_task set due_at = coalesce(due_at, v_due) where task_id = v_task;
  end if;

  insert into public.founder_command_plan (command_id, summary, child_task_count, departments)
  values (v_cmd,
          format('%s: %s. Command owner chief_of_staff; %s plan item(s) and %s operational task(s) against %s%s.',
                 c.intent_id, c.outcome, v_items, cardinality(v_tasks),
                 coalesce(nullif(c.workflow_ids,''), 'no workflow'),
                 case when cardinality(v_overlays) > 0
                      then format('; %s category overlay invocation(s): %s',
                                  cardinality(v_overlays), array_to_string(v_overlays, ', '))
                      else '' end),
          greatest(v_items - 1, 0),
          coalesce((select string_agg(distinct i.department_id, '; ')
                    from public.founder_command_plan_item i
                   where i.command_id = v_cmd and i.department_id <> ''), ''))
  on conflict (command_id) do update set summary = excluded.summary,
    child_task_count = excluded.child_task_count, departments = excluded.departments
  returning plan_id into v_plan_id;

  if c.outcome = 'REFUND_APPROVAL' then
    insert into public.founder_approval_request
      (command_id, action_class, subject_ref, prepared_by_role_id, amount_note, evidence, state)
    values (v_cmd, 'refund_decision',
            coalesce((regexp_match(p_text, '(TX-[A-Za-z0-9_-]+)'))[1], 'UNIDENTIFIED_TRANSACTION'),
            'payments_and_billing_manager',
            'amount, reason, customer/supplier impact and fraud checks required before decision',
            jsonb_build_object('raw_command', left(coalesce(p_text,''), 500)), 'pending');
  end if;

  -- A command that produced no operational task did not create tasks, and does not claim to.
  if cardinality(v_tasks) > 0 then
    update public.founder_command set state = 'tasks_created', due_at = v_due where command_id = v_cmd;
    v_status := 'tasks_created';
  else
    update public.founder_command set due_at = v_due where command_id = v_cmd;
    v_status := 'routed';
  end if;

  return jsonb_build_object(
    'ok', true, 'command_id', v_cmd, 'status', v_status, 'intent', c.intent_id,
    'outcome', c.outcome, 'interpretation', c.reason,
    'workflow_ids', coalesce((select jsonb_agg(workflow_id order by workflow_id)
                              from public.founder_command_workflow_link where command_id = v_cmd), '[]'::jsonb),
    'task_ids', to_jsonb(v_tasks),
    'owner', 'chief_of_staff', 'primary_owner', coalesce(v_owners[1], 'founder'),
    'child_owners', to_jsonb(v_owners[2:]),
    'category_overlays_invoked', to_jsonb(v_overlays),
    'tasks_created', cardinality(v_tasks),
    'plan_items', v_items,
    'workflow_run_id', (v_kernel->>'run_id')::bigint,
    'step_run_id', (v_kernel->>'step_run_id')::bigint,
    'handoff_run_id', (v_kernel->>'handoff_run_id')::bigint,
    'event_id', v_start_event, 'outbox_id', (v_kernel->>'outbox_id')::bigint,
    'correlation_id', 'cmd:' || v_cmd,
    'blocker', case when cardinality(v_tasks) = 0
                    then 'The interpretation selected no registered workflow, so no operational task was '
                      || 'created. The plan is recorded; name the area and it will route.'
                    else null end,
    'priority', c.priority, 'due_at', v_due,
    'founder_approval_required', (c.outcome = 'REFUND_APPROVAL'),
    'founder_initiated_only', (c.outcome in ('FOUNDER_INITIATED_POLICY_CHANGE','FOUNDER_INITIATED_PHASE_A_CHANGE')),
    'plan_id', v_plan_id, 'trace_id', v_trace);
end

fn_founder_command_status:
declare v_id bigint; r jsonb;
begin
  v_id := nullif(regexp_replace(coalesce(p_ref,''), '\D', '', 'g'), '')::bigint;
  if v_id is null then
    return jsonb_build_object('ok', false, 'error','identifier_required',
      'message','Give me a command id or a task id and I will read its current state.');
  end if;
  select jsonb_build_object(
    'ok', true, 'command_id', c.command_id, 'status', c.state, 'intent', c.intent_id,
    'outcome', c.outcome, 'owner', c.command_owner_role_id, 'priority', c.priority,
    'due_at', c.due_at, 'raw_text', m.raw_text,
    'workflow_ids', coalesce((select jsonb_agg(l.workflow_id order by l.workflow_id)
                              from public.founder_command_workflow_link l where l.command_id = c.command_id), '[]'::jsonb),
    'tasks', coalesce((select jsonb_agg(jsonb_build_object(
                          'task_id', t.task_id, 'owner', t.accountable_role_id,
                          'department', t.department_id, 'state', t.state,
                          'blocker', t.blocker, 'due_at', t.due_at) order by t.task_id)
                       from public.phase_c_task t where t.command_id = c.command_id), '[]'::jsonb),
    'clarification', (select cl.question from public.founder_command_clarification cl
                      where cl.command_id = c.command_id order by cl.clarification_id desc limit 1),
    'trace_id', c.trace_id)
  into r
  from public.founder_command c join public.founder_command_message m on m.message_id = c.message_id
  where c.command_id = v_id;
  return coalesce(r, jsonb_build_object('ok', false, 'error','not_found', 'ref', p_ref));
end

fn_founder_approval_refund_only:
begin
  if not exists (select 1 from public.phase_c_action_class
                 where action_class = new.action_class and founder_approval_required) then
    raise exception 'founder_approval_request: % is not a founder-approval action class. The founder is not the company''s approval queue; only a specific refund decision reaches him.', new.action_class
      using errcode = '23514';
  end if;
  return new;
end

fn_phase_c_refund_decision_guard:
begin
  perform public.fn_phase_c_require_founder(new.decided_by);   -- raises 28000 for anyone else

  if new.executed_at is not null and new.decision <> 'approved' then
    raise exception 'phase_c_refund_decision %: execution recorded against a % decision',
      new.decision_id, new.decision using errcode = '23514';
  end if;
  if new.reconciled_at is not null and new.executed_at is null then
    raise exception 'phase_c_refund_decision %: reconciled before it was executed', new.decision_id
      using errcode = '23514';
  end if;
  if new.executor_role_id is not null and new.reconciler_role_id is not null
     and new.executor_role_id = new.reconciler_role_id then
    raise exception 'phase_c_refund_decision %: the executor and the reconciler are the same role (%)',
      new.decision_id, new.executor_role_id using errcode = '23514';
  end if;
  return new;
end

fn_phase_c_authority_check:
declare a public.phase_c_action_class%rowtype; v_actor text; v_kind text;
begin
  select * into a from public.phase_c_action_class where action_class = p_action_class;
  if not found then
    allowed := false; mode := 'unknown'; requires_reviewer := true; reviewer_independent := false;
    founder_approval := false; founder_initiated_only := false;
    reason := format('unknown action class %L — fail closed', p_action_class);
    return next; return;
  end if;

  select kind, role_id into v_kind, v_actor from public.fn_phase_c_resolve_actor(p_actor);
  if v_kind is distinct from 'canonical' and v_kind is distinct from 'founder' then
    allowed := false; mode := a.execution_mode; requires_reviewer := true;
    reviewer_independent := false; founder_approval := a.founder_approval_required;
    founder_initiated_only := a.founder_initiated_only;
    reason := format('actor %L resolves to %s and may not act', p_actor, coalesce(v_kind, 'nothing'));
    return next; return;
  end if;

  founder_approval := a.founder_approval_required;
  founder_initiated_only := a.founder_initiated_only;
  mode := a.execution_mode;
  requires_reviewer := a.execution_mode in ('autonomous_internal_review','autonomous_dual_review');
  reviewer_independent := case when requires_reviewer
                               then public.fn_phase_c_reviewer_independent(p_actor, p_reviewer)
                               else true end;

  -- Founder-reserved matters are not an approval queue.  An agent may research and recommend;
  -- it may not commit without an explicit founder-originated command.
  if a.founder_initiated_only then
    allowed := false;
    reason := format('%s is founder_initiated_only: research and recommendation are autonomous, commitment requires an explicit founder command', a.action_class);
    return next; return;
  end if;

  if a.founder_approval_required and v_kind <> 'founder' then
    allowed := false;
    reason := format('%s requires the founder''s own decision', a.action_class);
    return next; return;
  end if;

  if requires_reviewer and not reviewer_independent then
    allowed := false;
    reason := case when coalesce(p_reviewer,'') = ''
                   then format('%s needs an independent reviewer and none was named', a.action_class)
                   else format('reviewer %L is the same effective identity as %L', p_reviewer, p_actor) end;
    return next; return;
  end if;

  allowed := true;
  reason := format('%s permitted under %s for %s', a.action_class, a.execution_mode, v_actor);
  return next;
end

fn_phase_c_task_transition:
declare t public.phase_c_task%rowtype; v_trace bigint; v_cmd_state text;
begin
  select * into t from public.phase_c_task where task_id = p_task_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'error','not_found','task_id', p_task_id);
  end if;
  if not public.fn_phase_c_task_transition_allowed(t.state, p_to_state) then
    return jsonb_build_object('ok', false, 'error','invalid_transition',
      'from', t.state, 'to', p_to_state,
      'message','The Phase C task state model does not allow that move.');
  end if;
  if p_to_state = 'completed' and t.reviewer_required
     and not public.fn_phase_c_reviewer_independent(t.accountable_role_id, t.reviewer_role_id) then
    return jsonb_build_object('ok', false, 'error','reviewer_not_independent',
      'owner', t.accountable_role_id, 'reviewer', t.reviewer_role_id);
  end if;
  if p_to_state = 'blocked' and coalesce(p_ctx->>'blocker','') = '' then
    return jsonb_build_object('ok', false, 'error','blocker_required',
      'message','A blocked task must name its blocker and the owner who resolves it.');
  end if;

  update public.phase_c_task set
    state = p_to_state,
    blocker = case when p_to_state = 'blocked' then p_ctx->>'blocker' else '' end,
    blocker_owner_role_id = case when p_to_state = 'blocked' then coalesce(p_ctx->>'blocker_owner_role_id','') else '' end,
    closed_at = case when p_to_state in ('completed','cancelled','failed','superseded') then now() else null end
  where task_id = p_task_id;

  v_trace := public.fn_phase_c_trace_write('TRACE-TASK', jsonb_build_object(
    'subject_kind','task', 'subject_ref', p_task_id::text, 'task_id', p_task_id,
    'command_id', t.command_id, 'actor_role_id', p_actor, 'manager_role_id', t.manager_role_id,
    'state_before', t.state, 'state_after', p_to_state, 'status', 'sealed'));
  update public.phase_c_task set trace_id = v_trace where task_id = p_task_id;

  -- The founder's half of the chain: the command follows its tasks.
  if t.command_id is not null then
    v_cmd_state := public.fn_founder_command_rollup(t.command_id);
  end if;

  return jsonb_build_object('ok', true, 'task_id', p_task_id, 'from', t.state, 'to', p_to_state,
                            'trace_id', v_trace, 'command_moved_to', v_cmd_state);
end

fn_phase_c_step_owner_valid:
declare s public.phase_b_workflow_step%rowtype; v_kind text;
begin
  if public.fn_phase_c_actor_may_own(p_owner) then return true; end if;
  select * into s from public.phase_b_workflow_step where step_id = p_step_id;
  if not found then return false; end if;
  if p_owner = 'relevant_category_overlay'
     and s.step_type = 'analysis'
     and s.workflow_id in ('W05','W06','W07','W10','W14') then
    return true;
  end if;
  select kind into v_kind from public.fn_phase_c_resolve_actor(p_owner);
  return v_kind = 'overlay' and s.step_type = 'analysis'
     and s.workflow_id in ('W05','W06','W07','W10','W14');
end

fn_phase_c_handoff_packet_valid:
declare h public.phase_b_handoff%rowtype; v_missing text;
begin
  select * into h from public.phase_b_handoff where handoff_id = p_handoff_id;
  if not found then
    valid := false; missing := format('unknown handoff %L — fail closed', p_handoff_id); return next; return;
  end if;
  if p_packet is null or jsonb_typeof(p_packet) <> 'object' then
    valid := false; missing := 'no packet supplied'; return next; return;
  end if;
  v_missing := coalesce((select string_agg(k, ', ')
    from unnest(array['business_object_id','object_version','output','evidence_refs','requested_action']) k
    where not (p_packet ? k)), '');
  valid := (v_missing = '');
  missing := v_missing;
  return next;
end

fn_phase_c_handoff_open:
declare
  h public.phase_b_handoff%rowtype;
  v_id bigint; v_trace bigint; v_hours numeric; v_due timestamptz;
  chk record;
begin
  select * into h from public.phase_b_handoff where handoff_id = p_handoff_id;
  if not found then
    return jsonb_build_object('ok', false, 'error','unknown_handoff', 'handoff_id', p_handoff_id);
  end if;
  select * into chk from public.fn_phase_c_handoff_packet_valid(p_handoff_id, p_packet);
  if not chk.valid then
    return jsonb_build_object('ok', false, 'error','incomplete_packet', 'missing', chk.missing,
      'return_owner', h.return_owner_role_id,
      'message','The sender keeps this. An incomplete packet does not become the receiver''s problem.');
  end if;

  -- The SLA target is prose ("1 minute", "4 business hours", "30 minutes when inputs are
  -- complete").  Parse the leading quantity AND its unit; taking the digits alone would turn
  -- "1 minute" into one hour and "5 minutes" into five, which is the wrong number twice over.
  select case
           when m[2] ilike 'minute%' then m[1]::numeric / 60.0
           when m[2] ilike 'day%'    then m[1]::numeric * 24.0
           when m[2] ilike 'week%'   then m[1]::numeric * 168.0
           else m[1]::numeric
         end
    into v_hours
  from public.phase_b_sla_policy sp,
       lateral regexp_match(sp.target, '(\d+)\s*(?:business\s+|calendar\s+)?(minute|hour|day|week)') m
  where sp.sla_policy_id = h.sla_policy_id;
  v_hours := coalesce(v_hours, 24);
  v_due := now() + make_interval(mins => greatest(1, round(v_hours * 60))::int);

  insert into public.phase_c_handoff_run
    (handoff_id, run_id, sending_role_id, receiving_role_id, business_object_id, object_version,
     packet_hash, requested_action, acceptance_criteria, return_owner_role_id, sla_policy_id,
     due_at, status, accountable_until_accept_role_id)
  values (p_handoff_id, p_run_id, h.sending_role_id, h.receiving_role_id,
          coalesce(p_packet->>'business_object_id',''),
          coalesce((p_packet->>'object_version')::bigint, 1),
          encode(sha256(convert_to(p_packet::text, 'UTF8')), 'hex'),
          coalesce(p_packet->>'requested_action',''), h.receiving_acceptance_criteria,
          h.return_owner_role_id, h.sla_policy_id, v_due, 'open', h.sending_role_id)
  returning handoff_run_id into v_id;
  if v_id is null then
    raise exception 'fn_phase_c_handoff_open wrote no row for %', p_handoff_id using errcode = '23502';
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-HANDOFF', jsonb_build_object(
    'subject_kind','handoff', 'subject_ref', v_id::text, 'run_id', p_run_id,
    'actor_role_id', h.sending_role_id, 'state_before','', 'state_after','open',
    'output_hash', encode(sha256(convert_to(p_packet::text, 'UTF8')), 'hex'), 'status','open'));
  update public.phase_c_handoff_run set trace_id = v_trace where handoff_run_id = v_id;

  return jsonb_build_object('ok', true, 'handoff_run_id', v_id, 'sender', h.sending_role_id,
    'receiver', h.receiving_role_id, 'accountable_until_accept', h.sending_role_id,
    'sla_policy_id', h.sla_policy_id, 'sla_hours', v_hours, 'due_at', v_due, 'trace_id', v_trace);
end

fn_phase_c_handoff_decide:
declare hr public.phase_c_handoff_run%rowtype; v_actor text; v_trace bigint;
begin
  select * into hr from public.phase_c_handoff_run where handoff_run_id = p_handoff_run_id for update;
  if not found then return jsonb_build_object('ok', false, 'error','not_found'); end if;
  if hr.status <> 'open' then
    return jsonb_build_object('ok', false, 'error','already_decided', 'status', hr.status);
  end if;
  select role_id into v_actor from public.fn_phase_c_resolve_actor(p_actor);
  if v_actor is distinct from hr.receiving_role_id then
    return jsonb_build_object('ok', false, 'error','not_the_receiver',
      'receiver', hr.receiving_role_id, 'actor', coalesce(v_actor, p_actor));
  end if;
  if p_decision = 'reject'
     and (coalesce(p_ctx->>'reason','') = '' or coalesce(p_ctx->>'missing','') = '') then
    return jsonb_build_object('ok', false, 'error','rejection_must_be_specific',
      'message','A rejection must state the exact missing or invalid item and the return owner.');
  end if;

  update public.phase_c_handoff_run set
    status = case when p_decision = 'accept' then 'accepted' else 'rejected' end,
    rejection_reason = case when p_decision = 'accept' then '' else p_ctx->>'reason' end,
    missing_items = case when p_decision = 'accept' then '' else p_ctx->>'missing' end,
    return_owner_role_id = case when p_decision = 'accept' then return_owner_role_id
                                else coalesce(nullif(p_ctx->>'return_owner',''), return_owner_role_id, sending_role_id) end
  where handoff_run_id = p_handoff_run_id;

  v_trace := public.fn_phase_c_trace_write('TRACE-HANDOFF', jsonb_build_object(
    'subject_kind','handoff', 'subject_ref', p_handoff_run_id::text, 'run_id', hr.run_id,
    'actor_role_id', v_actor, 'state_before','open',
    'state_after', case when p_decision = 'accept' then 'accepted' else 'rejected' end,
    'status','sealed'));
  return jsonb_build_object('ok', true, 'handoff_run_id', p_handoff_run_id,
    'status', case when p_decision = 'accept' then 'accepted' else 'rejected' end,
    'accountable_now', (select accountable_until_accept_role_id from public.phase_c_handoff_run
                        where handoff_run_id = p_handoff_run_id),
    'trace_id', v_trace);
end

fn_phase_c_overlay_invoke:
declare b public.phase_c_overlay_binding%rowtype; v_trace bigint; v_missing text;
begin
  select * into b from public.phase_c_overlay_binding where overlay_id = p_overlay_id;
  if not found then
    select * into b from public.phase_c_overlay_binding
      where live_role_id = (select role_id from public.fn_phase_c_resolve_actor(p_overlay_id));
  end if;
  if not found then
    return jsonb_build_object('ok', false, 'error','unknown_overlay', 'overlay_id', p_overlay_id);
  end if;
  v_missing := coalesce((select string_agg(k, ', ') from unnest(array['inquiry_id']) k
                         where not (coalesce(p_ctx,'{}'::jsonb) ? k)), '');
  v_trace := public.fn_phase_c_trace_write('TRACE-CATEGORY-ADVICE', jsonb_build_object(
    'subject_kind','overlay', 'subject_ref', b.overlay_id,
    'actor_role_id', b.live_role_id, 'status', case when v_missing = '' then 'sealed' else 'open' end,
    'evidence_refs', coalesce(p_ctx->'evidence_refs','[]'::jsonb)));
  return jsonb_build_object(
    'ok', v_missing = '', 'overlay_id', b.overlay_id, 'live_role_id', b.live_role_id,
    'inquiry_id', p_ctx->>'inquiry_id',
    'retrieved_fields', coalesce(p_ctx->'retrieved_fields','[]'::jsonb),
    'never_infer_checks', jsonb_build_array('quantity','specification','delivery_date','budget'),
    'missing_fields', v_missing,
    'return_owner', b.result_returns_to_role_id,
    'may_dispatch', false,
    'status', case when v_missing = '' then 'success' else 'empty' end,
    'trace_id', v_trace);
end

fn_phase_c_overlay_may_not_dispatch:
