fn_founder_command_rollup:
declare
  c public.founder_command%rowtype;
  n_total bigint; n_open bigint; n_blocked bigint; n_started bigint; n_failed bigint; n_done bigint;
  v_want text; v_summary text;
begin
  select * into c from public.founder_command where command_id = p_command_id for update;
  if not found then return null; end if;
  -- a terminal command is not re-opened by a late task movement
  if c.state in ('completed','cancelled','refused','superseded','failed') then return null; end if;

  select count(*),
         count(*) filter (where closed_at is null),
         count(*) filter (where state = 'blocked'),
         count(*) filter (where state in ('in_progress','accepted','review_required','revision_required')),
         count(*) filter (where state = 'failed'),
         count(*) filter (where state = 'completed')
    into n_total, n_open, n_blocked, n_started, n_failed, n_done
  from public.phase_c_task where command_id = p_command_id;

  if n_total = 0 then return null; end if;

  v_want := case
    when n_open = 0 and n_failed > 0 then 'failed'
    when n_open = 0                  then 'completed'
    when n_blocked > 0               then 'partially_blocked'
    when n_started > 0               then 'in_progress'
    else c.state
  end;
  if v_want = c.state then return null; end if;

  -- The frozen command state model still decides. A move it does not allow is not forced; the
  -- command stays where it is and the task movement is unaffected.
  if not exists (select 1 from public.phase_c_command_transition
                 where from_state = c.state and to_state = v_want) then
    return null;
  end if;

  update public.founder_command set
    state = v_want,
    closed_at = case when v_want in ('completed','failed') then now() else closed_at end
  where command_id = p_command_id;

  if v_want in ('completed','failed') then
    v_summary := format(
      '%s of %s task(s) completed, %s failed. Owners: %s.',
      n_done, n_total, n_failed,
      coalesce((select string_agg(distinct accountable_role_id, ', ' order by accountable_role_id)
                from public.phase_c_task where command_id = p_command_id), 'none'));
    insert into public.founder_command_completion (command_id, summary, evidence)
    values (p_command_id, v_summary, jsonb_build_object(
      'tasks_total', n_total, 'tasks_completed', n_done, 'tasks_failed', n_failed,
      'task_ids', coalesce((select jsonb_agg(task_id order by task_id)
                            from public.phase_c_task where command_id = p_command_id), '[]'::jsonb),
      'traces', coalesce((select jsonb_agg(trace_id) from public.phase_c_task
                          where command_id = p_command_id and trace_id is not null), '[]'::jsonb)))
    on conflict (command_id) do update set summary = excluded.summary,
      evidence = excluded.evidence, closed_at = now();

    perform public.fn_phase_c_trace_write('TRACE-FOUNDER-COMMAND', jsonb_build_object(
      'subject_kind','command', 'subject_ref', p_command_id::text, 'command_id', p_command_id,
      'actor_role_id','chief_of_staff', 'system_actor_id','system.task_engine',
      'state_before', c.state, 'state_after', v_want, 'status','sealed',
      'evidence_refs', jsonb_build_array(jsonb_build_object('completion_summary', v_summary))));
  end if;

  return v_want;
end

fn_founder_command_progress_add:
declare v_author text; v_id bigint; v_trace bigint;
begin
  if coalesce(btrim(p_note), '') = '' then
    return jsonb_build_object('ok', false, 'error','note_required');
  end if;
  select role_id into v_author from public.fn_phase_c_resolve_actor(p_author);
  if v_author is null or not public.fn_phase_c_actor_may_own(v_author) then
    return jsonb_build_object('ok', false, 'error','author_not_canonical', 'author', p_author);
  end if;
  if not exists (select 1 from public.founder_command where command_id = p_command_id) then
    return jsonb_build_object('ok', false, 'error','unknown_command', 'command_id', p_command_id);
  end if;
  -- a note against a task must come from that task's own owner or its manager
  if p_task_id is not null and not exists (
       select 1 from public.phase_c_task t
       where t.task_id = p_task_id and t.command_id = p_command_id
         and (t.accountable_role_id = v_author or t.manager_role_id = v_author)) then
    return jsonb_build_object('ok', false, 'error','not_the_task_owner_or_manager',
      'author', v_author, 'task_id', p_task_id);
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-ROLE-ACTION', jsonb_build_object(
    'subject_kind','progress_note', 'subject_ref', p_command_id::text,
    'command_id', p_command_id, 'task_id', p_task_id, 'actor_role_id', v_author,
    'output_hash', encode(sha256(convert_to(p_note, 'UTF8')), 'hex'), 'status','sealed'));

  insert into public.founder_command_progress_note
    (command_id, task_id, author_role_id, note, evidence, trace_id)
  values (p_command_id, p_task_id, v_author, p_note, coalesce(p_evidence, '{}'::jsonb), v_trace)
  returning note_id into v_id;
  if v_id is null then
    raise exception 'fn_founder_command_progress_add wrote no row' using errcode = '23502';
  end if;
  return jsonb_build_object('ok', true, 'note_id', v_id, 'author', v_author, 'trace_id', v_trace);
end

fn_os_fresh_start_at:
select coalesce((select f.effective_from from public.os_fresh_start f
                  order by f.effective_from desc, f.id desc limit 1),
                '-infinity'::timestamptz);

fn_phase_c_trace_advance:
declare t public.phase_c_trace%rowtype; v_new bigint;
begin
  if p_trace_id is null then return null; end if;
  select * into t from public.phase_c_trace where trace_id = p_trace_id;
  if not found then
    raise exception 'fn_phase_c_trace_advance: no trace %', p_trace_id using errcode = '23503';
  end if;

  -- A sealed trace is evidence. It is superseded, never rewritten.
  if t.sealed_at is not null then
    v_new := public.fn_phase_c_trace_write(t.trace_policy_id, jsonb_build_object(
      'subject_kind', t.subject_kind, 'subject_ref', t.subject_ref,
      'command_id', t.command_id, 'run_id', t.run_id, 'step_run_id', t.step_run_id,
      'task_id', t.task_id, 'actor_role_id', t.actor_role_id,
      'manager_role_id', t.manager_role_id, 'system_actor_id', t.system_actor_id,
      'state_before', t.state_after, 'state_after', p_state_after,
      'evidence_refs', coalesce(p_body->'evidence_refs', '[]'::jsonb),
      'parent_trace_id', coalesce(t.parent_trace_id, t.trace_id),
      'status', case when p_seal then 'sealed' else 'open' end));
    update public.phase_c_trace set superseded_by = v_new where trace_id = p_trace_id;
    return v_new;
  end if;

  update public.phase_c_trace set
    state_before  = coalesce(nullif(t.state_before,''), t.state_after),
    state_after   = p_state_after,
    status        = case when p_seal then 'sealed' else 'open' end,
    sealed_at     = case when p_seal then now() else null end,
    output_hash   = coalesce(nullif(p_body->>'output_hash',''), t.output_hash),
    evidence_refs = case when p_body ? 'evidence_refs'
                         then coalesce(t.evidence_refs,'[]'::jsonb) || (p_body->'evidence_refs')
                         else t.evidence_refs end
  where trace_id = p_trace_id;
  return p_trace_id;
end

fn_founder_command_trace_guard:
declare t public.phase_c_trace%rowtype;
begin
  if tg_op = 'INSERT' then
    -- A command is BORN at 'received'. That is the only state a row may be created in with no
    -- trace, because the trace is opened by the router on the next statement. Creating one at a
    -- LATER state with a null trace was how a command became invisible to both command trace
    -- checks: commands_ahead_of_their_trace uses an INNER JOIN, which drops a null trace_id.
    if new.trace_id is null then
      if new.state <> 'received' then
        raise exception
          'founder_command: cannot be created at state % with no trace; only received is trace-less at birth',
          new.state using errcode = '23514',
          hint = 'Insert the command at received and transition it, or supply the root trace on '
              || 'the insert. TRACE-FOUNDER-COMMAND declares trace_required=YES.';
      end if;
      return new;
    end if;
    select * into t from public.phase_c_trace where trace_id = new.trace_id;
    if not found then
      raise exception 'founder_command: root trace % does not exist', new.trace_id
        using errcode = '23503';
    end if;
    return new;
  end if;

  if new.state is not distinct from old.state then return new; end if;
  if new.state = 'received' then return new; end if;

  -- received -> interpreting is the one move that legitimately precedes the trace: it is the
  -- transition the router makes in order to open the trace, in the same transaction, on the very
  -- next statement. Requiring the trace here would make it impossible to ever write one. Every
  -- state after that must have it, which is what the assertion below enforces.
  if old.state = 'received' and new.state = 'interpreting' and new.trace_id is null then
    return new;
  end if;

  if new.trace_id is null then
    raise exception 'founder_command %: cannot leave % without a root trace', new.command_id, old.state
      using errcode = '23514';
  end if;
  select * into t from public.phase_c_trace where trace_id = new.trace_id;
  if not found then
    raise exception 'founder_command %: root trace % does not exist', new.command_id, new.trace_id
      using errcode = '23503';
  end if;

  -- Advance the root so the two can never disagree, then assert it. The assertion is not
  -- decoration: if a future path sets state without going through this trigger, it fails here
  -- rather than shipping a command whose evidence describes a different moment.
  perform public.fn_phase_c_trace_advance(
    new.trace_id, new.state,
    new.state in ('completed','failed','cancelled','refused','superseded'),
    jsonb_build_object('evidence_refs', jsonb_build_array(
      jsonb_build_object('command_transition', old.state || ' -> ' || new.state, 'at', now()))));

  select * into t from public.phase_c_trace where trace_id = new.trace_id;
  if t.state_after is distinct from new.state then
    raise exception 'founder_command %: state % but root trace % still says %',
      new.command_id, new.state, new.trace_id, t.state_after using errcode = '23514';
  end if;
  return new;
end

fn_phase_c_event_binding_status:
declare
  e public.phase_b_event%rowtype;
  v_has_producer boolean; v_has_consumer boolean; v_step text; v_consumer_ok boolean;
begin
  select * into e from public.phase_b_event where event_id = p_event_id;
  if not found then
    return query select 'BROKEN'::text,
      'no row in the frozen Phase B event registry for this binding'::text; return;
  end if;

  -- the consumer role must resolve, or nothing downstream can own the result
  select (select kind from public.fn_phase_c_resolve_actor(e.primary_consumer_role_id)) is not null
    into v_consumer_ok;
  if not coalesce(v_consumer_ok, false) then
    return query select 'BROKEN'::text,
      format('primary consumer %L does not resolve to a canonical actor', e.primary_consumer_role_id);
    return;
  end if;

  -- the emitting leg
  if e.event_name like '%.started' then
    v_has_producer := true; v_has_consumer := true;
    return query select 'CONNECTED'::text, format(
      'producer fn_phase_c_event_ingress / fn_founder_command_submit via fn_phase_c_lifecycle_event(%L,''started''); '
      'durable row phase_c_event_outbox; claim fn_phase_c_outbox_claim (FOR UPDATE SKIP LOCKED); '
      'worker fn_phase_c_outbox_deliver (cron phase_c_outbox_deliver_1min); '
      'consumer fn_phase_c_event_consume -> fn_phase_c_event_ingress creates run, step run and task; '
      'evidence phase_c_event_delivery_attempt', e.workflow_id);
    return;
  end if;

  select s.step_id into v_step
    from public.phase_b_workflow_step s
   where s.workflow_id = e.workflow_id
     and public.fn_phase_c_step_event(s.step_id, 'completed') = p_event_id
   limit 1;
  if v_step is not null then
    return query select 'CONNECTED'::text, format(
      'producer fn_phase_c_step_advance via fn_phase_c_step_event(%L,''completed''); '
      'durable row phase_c_event_outbox; claim fn_phase_c_outbox_claim; '
      'worker fn_phase_c_outbox_deliver; consumer fn_phase_c_event_consume hands the successor '
      'step to its accountable owner through phase_b_handoff; evidence phase_c_event_delivery_attempt',
      v_step);
    return;
  end if;

  -- everything else: the registry describes it, nothing emits it, nothing consumes it
  return query select 'DEFERRED_RUNTIME_IMPLEMENTATION'::text, format(
    'no deployed producer emits %L and fn_phase_c_event_consume has no branch for it; '
    'Phase D must add the emitter at the state change this event names and a consumer branch',
    p_event_id);
end

fn_phase_c_event_binding_status_guard:
declare v_status text;
begin
  select status into v_status from public.fn_phase_c_event_binding_status(new.event_id);
  if new.connection_status is distinct from v_status then
    raise exception 'phase_c_event_binding %: status %L is not what the legs support (%L). '
                    'Wire the missing leg; do not relabel the row.',
      new.event_id, new.connection_status, v_status using errcode = '23514';
  end if;
  return new;
end

fn_phase_c_task_trace_subject:
declare v_parent bigint; v_trace bigint;
begin
  if new.trace_id is not null then
    -- A caller supplied the trace. Stamp the subject on it if it does not already carry one.
    update public.phase_c_trace
       set task_id = new.task_id, subject_ref = new.task_id::text
     where trace_id = new.trace_id and task_id is null and sealed_at is null;
    return null;
  end if;

  -- The root this task hangs from: its command's trace, or its workflow run's trace.
  select c.trace_id into v_parent from public.founder_command c where c.command_id = new.command_id;
  if v_parent is null then
    select r.trace_id into v_parent from public.phase_c_workflow_run r where r.run_id = new.run_id;
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-TASK', jsonb_build_object(
    'subject_kind','task', 'subject_ref', new.task_id::text, 'task_id', new.task_id,
    'command_id', new.command_id, 'run_id', new.run_id,
    'actor_role_id', new.accountable_role_id, 'manager_role_id', new.manager_role_id,
    'system_actor_id', case when new.command_id is not null
                            then 'system.command_router' else 'system.workflow_engine' end,
    'authority_result', coalesce(new.authority_class,''),
    'reviewer_role_id', coalesce(new.reviewer_role_id,''),
    'input_hash', encode(sha256(convert_to(coalesce(new.objective,''), 'UTF8')), 'hex'),
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'idempotency_key', new.idempotency_key, 'source_kind', new.source_kind,
      'source_ref', new.source_ref)),
    'parent_trace_id', v_parent,
    'state_before','', 'state_after', coalesce(new.state,'queued'), 'status','open'));

  update public.phase_c_task set trace_id = v_trace where task_id = new.task_id;
  return null;
end

fn_phase_c_require_founder:
declare
  v_sub    uuid;
  v_id     text;
  v_ev     bigint;
  v_route  text;
begin
  -- ---- ROUTE A: a bearer token PostgREST already verified -------------------------------------
  -- auth.uid() is null for a service_role connection and for anything that did not arrive with a
  -- user JWT. It cannot be set by a caller.
  begin
    v_sub := auth.uid();
  exception when others then
    v_sub := null;
  end;
  if v_sub is not null then
    select f.identity into v_id
      from public.phase_c_founder_identity f
     where f.auth_user_id = v_sub and f.active and f.kind = 'email';
    v_route := 'auth.uid()';
  end if;

  -- ---- ROUTE B: the server path bound a subject it verified ------------------------------------
  if v_id is null then
    v_ev := nullif(btrim(current_setting('app.phase_c_founder_auth_event', true)),'')::bigint;
    if v_ev is not null then
      select e.identity, e.auth_subject into v_id, v_sub
        from public.phase_c_founder_auth_event e
        join public.phase_c_founder_identity f on f.identity = e.identity
       where e.event_id = v_ev
         -- BOUND TO THIS TRANSACTION. A GUC pointing at an event from another transaction is not a
         -- session: it is a value a caller typed.
         and e.txid = txid_current()
         and f.active and f.kind = 'email';
      v_route := 'fn_phase_c_founder_subject_bind';
    end if;
  end if;

  if v_id is null then
    -- E39's vector, refused: knowing the email is no longer being the founder.
    raise exception 'not the founder: no verified auth subject on this call. The founder is resolved from auth.uid() or from a subject os_api verified and bound with fn_phase_c_founder_subject_bind; a caller-supplied identity is not authentication. (PCCR-003)'
      using errcode = '28000',
            hint = 'Call with the founder''s bearer token so auth.uid() resolves, or verify the JWT in os_api and bind the verified subject first.';
  end if;

  -- p_actor is now an ASSERTION, not a source. Supplying one that disagrees with the verified
  -- identity is a caller claiming to be someone else and is refused; supplying none is fine.
  if coalesce(btrim(p_actor),'') <> '' and lower(btrim(p_actor)) <> lower(v_id) then
    raise exception 'not the founder: the call asserts identity % and the verified auth subject resolves to %',
      lower(btrim(p_actor)), v_id using errcode = '28000';
  end if;

  return v_id;
end

fn_phase_c_founder_identity_human_only:
begin
  if new.active and new.kind <> 'email' then
    raise exception
      'phase_c_founder_identity: only an email identity may be active; % is kind %',
      new.identity, new.kind
      using errcode = '23514',
            hint = 'A build-mode or service identity must never be enabled as the founder. '
                || 'This is the defect the 16 Aug audit found (FAIL 1).';
  end if;
  return new;
end

fn_founder_command_clarify:
declare
  cmd public.founder_command%rowtype;
  msg public.founder_command_message%rowtype;
  c record; v_combined text; v_qn text; v_owner text; v_child text;
  v_tasks bigint[] := '{}'; v_owners text[] := '{}'; v_task bigint;
  v_due timestamptz; v_wf text; v_start_event text; v_plan bigint; v_clar bigint;
  v_kernel jsonb; v_items int := 0; v_manager text; v_dept text;
  v_founder text;
begin
  v_founder := public.fn_phase_c_require_founder(p_actor);   -- raises 28000 for anyone else

  if coalesce(btrim(p_answer),'') = '' then
    return jsonb_build_object('ok', false, 'error','answer_required',
      'message','Say what you want and I will route it. An empty reply cannot resolve a clarification.');
  end if;
  select * into cmd from public.founder_command where command_id = p_command_id;
  if not found then return jsonb_build_object('ok', false, 'error','not_found'); end if;
  if cmd.state <> 'clarification_required' then
    return jsonb_build_object('ok', false, 'error','not_awaiting_clarification',
      'state', cmd.state,
      'message','This command is not waiting for a clarification.');
  end if;
  select * into msg from public.founder_command_message where message_id = cmd.message_id;

  -- The original instruction is never edited. The reply is APPENDED, on its own row, with its own
  -- timestamp, and the exact words the founder used.
  update public.founder_command_clarification
     set answer_text = p_answer, answered_at = now()
   where clarification_id = (select max(cl.clarification_id) from public.founder_command_clarification cl
                             where cl.command_id = p_command_id)
  returning clarification_id into v_clar;

  update public.founder_command set state = 'interpreting' where command_id = p_command_id;

  -- Re-interpret the instruction AND its clarification together, through the same deterministic
  -- classifier the first attempt used. No model is consulted; nothing is guessed.
  v_combined := coalesce(msg.raw_text,'') || E'\n' || p_answer;
  select * into c from public.fn_founder_command_classify(v_combined);

  insert into public.founder_command_interpretation
    (command_id, version, intent_id, confidence, matched_rule_id, workflow_ids,
     specificity_signals, reason)
  values (p_command_id,
          1 + coalesce((select max(i.version) from public.founder_command_interpretation i
                         where i.command_id = p_command_id), 0),
          c.intent_id, c.confidence, c.matched_rule_id, c.workflow_ids, c.specificity,
          'after clarification: ' || c.reason);

  -- Still not routable. Ask once more; still create nothing.
  if c.outcome not in ('ROUTE_AND_CREATE_TASKS','FOUNDER_INITIATED_POLICY_CHANGE',
                       'FOUNDER_INITIATED_PHASE_A_CHANGE','REFUND_APPROVAL') then
    v_qn := coalesce(nullif(c.reason,''), 'I still cannot route this safely.')
            || ' What exactly do you want changed, by how much, and by when?';
    insert into public.founder_command_clarification (command_id, question)
    values (p_command_id, v_qn);
    update public.founder_command set state = 'clarification_required' where command_id = p_command_id;
    return jsonb_build_object('ok', true, 'command_id', p_command_id,
      'status','clarification_required', 'tasks_created', 0, 'task_ids','[]'::jsonb,
      'owner','chief_of_staff', 'clarification', v_qn,
      'answer_recorded', true, 'clarification_id', v_clar, 'actor', v_founder);
  end if;

  -- Routable now. One command id, the plan and the tasks, in this transaction.
  update public.founder_command
     set intent_id = c.intent_id, outcome = c.outcome, priority = c.priority,
         primary_role_id = coalesce(nullif(c.primary_role_id,''), 'chief_of_staff'),
         state = 'accepted'
   where command_id = p_command_id;
  update public.founder_command set state = 'routed' where command_id = p_command_id;

  v_due := now() + case c.priority when 'P0' then interval '4 hours' when 'P1' then interval '2 days'
                                   when 'P2' then interval '5 days' else interval '10 days' end;
  v_wf := btrim(split_part(c.workflow_ids, ';', 1));

  insert into public.founder_command_workflow_link (command_id, workflow_id)
  select p_command_id, btrim(x) from unnest(string_to_array(c.workflow_ids, ';')) x
   where btrim(x) <> '' on conflict do nothing;

  select role_id into v_owner from public.fn_phase_c_resolve_actor(
    coalesce(nullif(c.primary_role_id,''), 'chief_of_staff'));
  -- ---- THE PLAN (not operational tasks) --------------------------------------------------
  -- K2 moved this for fn_founder_command_submit and left the clarify path behind, so answering a
  -- clarification still created four phase_c_task rows and no workflow run at all. Measured on
  -- command 270 through the real authenticated path on 17 Aug: tasks 4, runs 0, outbox 0.
  -- Plan items record who the command plan names. They are not work anybody is accountable for.
  if v_owner is not null then
    select r.manager_role_id, r.primary_department_id into v_manager, v_dept
      from public.org_role r where r.role_id = v_owner;
    insert into public.founder_command_plan_item
      (command_id, item_kind, role_id, department_id, summary, priority, workflow_id)
    values (p_command_id, 'primary', v_owner, coalesce(v_dept,''),
            left(v_combined, 1500), c.priority, nullif(v_wf,''))
    on conflict (command_id, item_kind, role_id) do nothing;
    v_items := v_items + 1; v_owners := v_owners || v_owner;
  end if;

  for v_child in select btrim(x) from unnest(string_to_array(c.child_role_ids, ';')) x where btrim(x) <> '' loop
    select role_id into v_owner from public.fn_phase_c_resolve_actor(v_child);
    continue when v_owner is null;
    select r.manager_role_id, r.primary_department_id into v_manager, v_dept
      from public.org_role r where r.role_id = v_owner;
    insert into public.founder_command_plan_item
      (command_id, item_kind, role_id, department_id, summary, priority, workflow_id)
    values (p_command_id, 'contribution', v_owner, coalesce(v_dept,''),
            'Contribution required by the command plan for ' || v_child || ': ' || left(v_combined, 1500),
            c.priority, nullif(v_wf,''))
    on conflict (command_id, item_kind, role_id) do nothing;
    v_items := v_items + 1; v_owners := v_owners || v_owner;
  end loop;

  -- ---- THE WORK --------------------------------------------------------------------------------
  -- One call, one run, one operational task, one factual event — the same kernel entry point the
  -- submit path uses, so the two can no longer drift apart.
  if coalesce(v_wf,'') <> '' and exists (select 1 from public.phase_b_workflow where workflow_id = v_wf) then
    v_kernel := public.fn_kernel_workflow_start(jsonb_build_object(
      'workflow_id', v_wf,
      'business_object_id', 'founder_command:' || p_command_id,
      'source_kind','founder_command',
      'source_ref','founder_command:' || p_command_id,
      'command_id', p_command_id,
      'correlation_id','cmd:' || p_command_id,
      'causation_id','command:' || p_command_id,
      'requested_by', v_founder,
      'priority', c.priority,
      'trigger_ctx', jsonb_build_object(
        'intent', c.intent_id, 'outcome', c.outcome, 'confidence', c.confidence,
        'matched_rule_id', c.matched_rule_id, 'after_clarification', true,
        'clarification_id', v_clar, 'plan_items', v_items)));
    v_task := (v_kernel->>'task_id')::bigint;
    v_start_event := v_kernel->>'event_id';
    if v_task is null then
      raise exception 'command %: the kernel returned no operational task for workflow %',
        p_command_id, v_wf using errcode = '23502';
    end if;
    insert into public.founder_command_task_link (command_id, task_id)
    values (p_command_id, v_task) on conflict do nothing;
    v_tasks := array[v_task];
    update public.phase_c_task set due_at = coalesce(due_at, v_due) where task_id = v_task;
  end if;

  insert into public.founder_command_plan (command_id, summary, child_task_count, departments)
  values (p_command_id,
          format('%s: %s after clarification. Command owner chief_of_staff; %s plan item(s), %s operational task against %s.',
                 c.intent_id, c.outcome, v_items, cardinality(v_tasks),
                 coalesce(nullif(c.workflow_ids,''),'no workflow')),
          v_items,
          coalesce((select string_agg(distinct t.department_id, '; ') from public.phase_c_task t
                     where t.command_id = p_command_id and t.department_id <> ''), ''))
  returning plan_id into v_plan;

  update public.founder_command set state = 'tasks_created', due_at = v_due
   where command_id = p_command_id;

  return jsonb_build_object('ok', true, 'command_id', p_command_id, 'status','tasks_created',
    'intent', c.intent_id, 'outcome', c.outcome, 'owner','chief_of_staff',
    'primary_owner', coalesce(v_owners[1],'founder'), 'task_ids', to_jsonb(v_tasks),
    'tasks_created', cardinality(v_tasks), 'workflow_id', v_wf,
    'event_emitted', v_start_event, 'plan_id', v_plan, 'clarification_id', v_clar,
    'answer_recorded', true, 'trace_id', cmd.trace_id, 'actor', v_founder,
    'interpretation','after clarification: ' || c.reason);
end

fn_founder_command_control:
declare v_target bigint; v_state text; v_n bigint := 0; t record; v_trace bigint; v_founder text;
        v_out jsonb;
begin
  v_founder := public.fn_phase_c_require_founder(p_actor);   -- raises 28000 for anyone else

  v_target := nullif(regexp_replace(coalesce(p_target,''), '\D', '', 'g'), '')::bigint;
  if v_target is null then
    return jsonb_build_object('ok', false, 'error','identifier_required');
  end if;
  select state into v_state from public.founder_command where command_id = v_target;
  if v_state is null then return jsonb_build_object('ok', false, 'error','not_found'); end if;

  if p_op in ('cancel','supersede') then
    -- ROOT CAUSE 2. THIS BRANCH USED TO BE A SECOND CANCELLER. It set founder_command.state itself
    -- and closed the child tasks one by one, and it stopped there: the workflow run, its open step
    -- runs, its handoffs, its queued outbox rows and its open traces were left live beneath a
    -- command the founder had cancelled. The final Phase C acceptance cancelled command 338 through
    -- this exact path and left run 538 and step run 531 active.
    --
    -- It now delegates. fn_kernel_cancel is the canonical canceller and the only one: it walks the
    -- command, its plan, its runs, their step runs, tasks, handoffs, undelivered outbox rows and
    -- open traces, refuses a transition the state model does not declare, and counts what it left
    -- behind before returning. The founder identity is verified twice on purpose — once above, and
    -- again inside the kernel for the founder_command subject — because the kernel may not trust a
    -- caller's word about who is asking.
    v_out := public.fn_kernel_cancel(jsonb_build_object(
      'subject_kind', 'founder_command',
      'subject_ref',  v_target::text,
      'op',           p_op,
      'actor',        p_actor,
      'reason',       coalesce(nullif(btrim(p_value),''),
                               'founder ' || p_op || ' of command ' || v_target
                               || ' through the Command Center control')));

    -- IDEMPOTENT. A command already in its terminal state is not an error and must not become one:
    -- the second click of Cancel returns the same answer as the first and changes nothing.
    if coalesce((v_out->>'ok')::boolean, false) is not true
       and v_state in ('cancelled','superseded') then
      return jsonb_build_object('ok', true, 'command_id', v_target, 'status', v_state,
        'already_terminal', true, 'child_tasks_closed', 0, 'actor', v_founder,
        'kernel', v_out);
    end if;
    if coalesce((v_out->>'ok')::boolean, false) is not true then
      return jsonb_build_object('ok', false, 'command_id', v_target,
        'error', coalesce(v_out->>'error', 'cancellation_refused'), 'kernel', v_out);
    end if;

    return jsonb_build_object('ok', true, 'command_id', v_target,
      'status', case when p_op = 'cancel' then 'cancelled' else 'superseded' end,
      'superseded_by', case when p_op = 'supersede' then p_command_id else null end,
      'child_tasks_closed', coalesce((v_out->'closed'->>'tasks')::int, 0),
      'closed', v_out->'closed', 'actor', v_founder);

  elsif p_op = 'reprioritize' then
    if coalesce(p_value,'') !~ '^P[0-3]$' then
      return jsonb_build_object('ok', false, 'error','priority_required', 'allowed','P0..P3');
    end if;
    update public.founder_command set priority = p_value where command_id = v_target;
    update public.phase_c_task set priority = p_value where command_id = v_target and closed_at is null;
    get diagnostics v_n = row_count;
    return jsonb_build_object('ok', true, 'command_id', v_target, 'priority', p_value,
      'tasks_updated', v_n, 'actor', v_founder);

  elsif p_op = 'explain' then
    return jsonb_build_object('ok', true, 'command_id', v_target,
      'explanation', coalesce((select i.reason from public.founder_command_interpretation i
                               where i.command_id = v_target order by i.version desc limit 1),
                              'no interpretation recorded'),
      'traces', coalesce((select jsonb_agg(jsonb_build_object(
                              'trace_id', tr.trace_id, 'policy', tr.trace_policy_id,
                              'subject', tr.subject_kind, 'state_after', tr.state_after,
                              'status', tr.status) order by tr.trace_id)
                          from public.phase_c_trace tr where tr.command_id = v_target), '[]'::jsonb),
      'plan', (select p.summary from public.founder_command_plan p where p.command_id = v_target),
      'actor', v_founder);
  end if;
  return jsonb_build_object('ok', false, 'error','unknown_control_operation', 'op', p_op);
end

fn_kernel_cancel:
declare
  v_kind     text := coalesce(p_input->>'subject_kind', '');
  v_ref      text := coalesce(p_input->>'subject_ref', '');
  v_op       text := coalesce(nullif(p_input->>'op',''), 'cancel');
  v_reason   text := coalesce(nullif(btrim(p_input->>'reason'),''), '');
  v_actor    text := coalesce(p_input->>'actor', '');
  v_terminal text;
  v_command  bigint;
  v_runs     bigint[] := '{}';
  v_founder  text;
  r          record;
  v_trace    bigint;
  n_cmd int := 0; n_plan int := 0; n_run int := 0; n_step int := 0;
  n_task int := 0; n_handoff int := 0; n_outbox int := 0; n_trace int := 0;
  v_left_tasks int; v_left_runs int; v_left_steps int; v_left_handoffs int; v_left_outbox int;
begin
  if v_op not in ('cancel','supersede') then
    raise exception 'fn_kernel_cancel: op must be cancel or supersede, got %', v_op using errcode = '22023';
  end if;
  v_terminal := case when v_op = 'cancel' then 'cancelled' else 'superseded' end;

  -- A cancellation with no stated reason is an unexplained disappearance in the audit trail.
  if v_reason = '' then
    raise exception 'fn_kernel_cancel: a reason is required' using errcode = '23514';
  end if;

  -- ---- resolve the subject ------------------------------------------------------------------
  if v_kind = 'founder_command' then
    -- Only the founder may cancel his own instruction. K0 put the one verifier in the estate;
    -- this is the second caller of it, not a second copy of it.
    v_founder := public.fn_phase_c_require_founder(v_actor);
    v_command := nullif(regexp_replace(v_ref, '\D', '', 'g'), '')::bigint;
    if v_command is null or not exists (select 1 from public.founder_command where command_id = v_command) then
      return jsonb_build_object('ok', false, 'error', 'not_found', 'subject_ref', v_ref);
    end if;
    select coalesce(array_agg(run_id), '{}') into v_runs
      from public.phase_c_workflow_run where command_id = v_command;

  elsif v_kind = 'workflow_run' then
    -- An autonomous run has no founder in the loop; the actor is recorded, not authenticated as
    -- the founder, because requiring a founder here would make autonomous cleanup impossible.
    v_runs := array[nullif(regexp_replace(v_ref, '\D', '', 'g'), '')::bigint];
    if v_runs[1] is null or not exists (select 1 from public.phase_c_workflow_run where run_id = v_runs[1]) then
      return jsonb_build_object('ok', false, 'error', 'not_found', 'subject_ref', v_ref);
    end if;
    select command_id into v_command from public.phase_c_workflow_run where run_id = v_runs[1];

  else
    raise exception 'fn_kernel_cancel: subject_kind must be founder_command or workflow_run, got %',
      v_kind using errcode = '22023';
  end if;

  -- ---- (a) the command --------------------------------------------------------------------
  if v_command is not null then
    if exists (select 1 from public.founder_command
                where command_id = v_command and state not in ('cancelled','superseded','completed')) then
      if not exists (select 1 from public.phase_c_command_transition t
                      join public.founder_command c on c.command_id = v_command
                     where t.from_state = c.state and t.to_state = v_terminal) then
        return jsonb_build_object('ok', false, 'error', 'transition_not_permitted',
          'from', (select state from public.founder_command where command_id = v_command),
          'to', v_terminal,
          'message', 'The command state model does not allow this move. Nothing was cancelled.');
      end if;
      update public.founder_command
         set state = v_terminal,
             superseded_by = case when v_op = 'supersede'
                                  then nullif(regexp_replace(coalesce(p_input->>'superseded_by',''), '\D','','g'),'')::bigint
                                  else superseded_by end,
             closed_at = now()
       where command_id = v_command;
      n_cmd := 1;
    end if;

    -- ---- (b) the command plan --------------------------------------------------------------
    update public.founder_command_plan
       set state = v_terminal, closed_at = now()
     where command_id = v_command and state = 'active';
    get diagnostics n_plan = row_count;
  end if;

  -- ---- (c) the workflow runs --------------------------------------------------------------
  for r in select * from public.phase_c_workflow_run
            where run_id = any(v_runs)
              and state not in ('cancelled','superseded','completed','failed') loop
    v_trace := public.fn_phase_c_trace_write('TRACE-WORKFLOW', jsonb_build_object(
      'subject_kind','workflow_run', 'subject_ref', r.run_id::text, 'run_id', r.run_id,
      'command_id', r.command_id, 'actor_role_id', coalesce(nullif(v_founder,''),'system'),
      'system_actor_id','system.workflow_engine',
      'state_before', r.state, 'state_after', v_terminal,
      'evidence_refs', jsonb_build_array(jsonb_build_object('reason', v_reason, 'actor', v_actor)),
      'status','sealed'));
    update public.phase_c_workflow_run
       set state = v_terminal, closed_at = now(),
           closure_evidence = coalesce(closure_evidence,'{}'::jsonb)
             || jsonb_build_object('cancelled_reason', v_reason, 'cancelled_by', v_actor,
                                   'cancelled_at', now(), 'trace_id', v_trace)
     where run_id = r.run_id;
    n_run := n_run + 1;
  end loop;

  -- ---- (d) the open step runs -------------------------------------------------------------
  for r in select * from public.phase_c_workflow_step_run
            where run_id = any(v_runs)
              and state not in ('cancelled','completed','failed','superseded') loop
    v_trace := public.fn_phase_c_trace_write('TRACE-STEP', jsonb_build_object(
      'subject_kind','step_run', 'subject_ref', r.step_run_id::text,
      'run_id', r.run_id, 'step_run_id', r.step_run_id,
      'actor_role_id', r.accountable_role_id, 'system_actor_id','system.workflow_engine',
      'state_before', r.state, 'state_after', v_terminal,
      'evidence_refs', jsonb_build_array(jsonb_build_object('reason', v_reason, 'actor', v_actor)),
      'status','sealed'));
    update public.phase_c_workflow_step_run
       set state = v_terminal, finished_at = now(), trace_id = coalesce(trace_id, v_trace),
           failure_reason = case when failure_reason = '' then 'cancelled: ' || v_reason else failure_reason end
     where step_run_id = r.step_run_id;
    n_step := n_step + 1;
  end loop;

  -- ---- (e) the tasks, BY COMMAND AND BY RUN ------------------------------------------------
  -- The old sweep matched on command_id alone. Task 794 carries command_id NULL and run_id 96, which
  -- is exactly how it survived its own command's cancellation.
  for r in select * from public.phase_c_task
            where ((v_command is not null and command_id = v_command) or run_id = any(v_runs))
              and state in ('queued','assigned','accepted','in_progress','blocked') loop
    v_trace := public.fn_phase_c_trace_write('TRACE-TASK', jsonb_build_object(
      'subject_kind','task', 'subject_ref', r.task_id::text, 'task_id', r.task_id,
      'command_id', r.command_id, 'run_id', r.run_id,
      'actor_role_id', coalesce(nullif(v_founder,''),'system'),
      'manager_role_id', r.manager_role_id, 'system_actor_id','system.command_router',
      'state_before', r.state, 'state_after', v_terminal,
      'evidence_refs', jsonb_build_array(jsonb_build_object('reason', v_reason, 'actor', v_actor)),
      'status','sealed'));
    update public.phase_c_task
       set state = v_terminal, closed_at = now(), trace_id = v_trace
     where task_id = r.task_id;
    n_task := n_task + 1;
  end loop;

  -- ---- (f) the pending handoffs ------------------------------------------------------------
  for r in select * from public.phase_c_handoff_run
            where run_id = any(v_runs) and status = 'open' loop
    v_trace := public.fn_phase_c_trace_write('TRACE-HANDOFF', jsonb_build_object(
      'subject_kind','handoff_run', 'subject_ref', r.handoff_run_id::text, 'run_id', r.run_id,
      'actor_role_id', r.sending_role_id, 'system_actor_id','system.workflow_engine',
      'state_before', r.status, 'state_after','cancelled',
      'evidence_refs', jsonb_build_array(jsonb_build_object('reason', v_reason, 'actor', v_actor)),
      'status','sealed'));
    update public.phase_c_handoff_run
       set status = 'cancelled', decided_at = now(), trace_id = coalesce(trace_id, v_trace)
     where handoff_run_id = r.handoff_run_id;
    n_handoff := n_handoff + 1;
  end loop;

  -- ---- (g) the undelivered outbox rows -----------------------------------------------------
  -- Delivered rows are NOT touched: a delivered event is a fact that happened, and rewriting it
  -- would be falsifying history. Only what has not yet left the queue is stopped.
  -- ROOT CAUSE 2. This matched on payload->>'run_id'. Only ONE producer writes that key: the
  -- step-complete event. The workflow-START event writes 'workflow_run_id', so every start event
  -- survived cancellation as 'pending' and was delivered afterwards. The leftover check below used
  -- the SAME predicate as this write, so it counted nothing left behind and the function reported
  -- success. Relationships are columns now, and the check reads the same columns this writes.
  update public.phase_c_event_outbox o
     set status = 'superseded',
         last_error = 'CANCELLED ' || to_char(now(),'YYYY-MM-DD') || ': ' || v_reason
                   || ' (fn_kernel_cancel, subject ' || v_kind || ':' || v_ref || ')'
   where o.status in ('pending','claimed','retry_wait')
     and ( (v_command is not null and o.command_id = v_command)
        or o.workflow_run_id = any(v_runs)
        or o.step_run_id in (select sr.step_run_id from public.phase_c_workflow_step_run sr
                              where sr.run_id = any(v_runs))
        or o.task_id in (select t.task_id from public.phase_c_task t
                          where (v_command is not null and t.command_id = v_command)
                             or t.run_id = any(v_runs)) );
  get diagnostics n_outbox = row_count;

  -- ---- (h) seal every open trace whose subject was just closed -----------------------------
  update public.phase_c_trace
     set status = 'sealed', sealed_at = now()
   where sealed_at is null
     and ( (v_command is not null and command_id = v_command)
        or run_id = any(v_runs)
        or task_id in (select task_id from public.phase_c_task
                        where (v_command is not null and command_id = v_command)
                           or run_id = any(v_runs)) );
  get diagnostics n_trace = row_count;

  -- ---- (i) THE POSTCONDITION ---------------------------------------------------------------
  -- "A cancelled command may leave no queued derived work." Asserted, not asserted about.
  select count(*) into v_left_tasks from public.phase_c_task
   where ((v_command is not null and command_id = v_command) or run_id = any(v_runs))
     and state in ('queued','assigned','accepted','in_progress','blocked');
  select count(*) into v_left_runs from public.phase_c_workflow_run
   where run_id = any(v_runs) and state not in ('cancelled','superseded','completed','failed');
  select count(*) into v_left_steps from public.phase_c_workflow_step_run
   where run_id = any(v_runs) and state not in ('cancelled','completed','failed','superseded');
  select count(*) into v_left_handoffs from public.phase_c_handoff_run
   where run_id = any(v_runs) and status = 'open';
  select count(*) into v_left_outbox from public.phase_c_event_outbox o
   where o.status in ('pending','claimed','retry_wait')
     and ( (v_command is not null and o.command_id = v_command)
        or o.workflow_run_id = any(v_runs)
        or o.step_run_id in (select sr.step_run_id from public.phase_c_workflow_step_run sr
                              where sr.run_id = any(v_runs))
        or o.task_id in (select t.task_id from public.phase_c_task t
                          where (v_command is not null and t.command_id = v_command)
                             or t.run_id = any(v_runs)) );

  if v_left_tasks + v_left_runs + v_left_steps + v_left_handoffs + v_left_outbox > 0 then
    raise exception
      'fn_kernel_cancel left derived work behind: tasks=% runs=% steps=% handoffs=% outbox=%',
      v_left_tasks, v_left_runs, v_left_steps, v_left_handoffs, v_left_outbox
      using errcode = '23514',
            hint = 'The propagation missed a table. Nothing was cancelled — the transaction is rolled back.';
  end if;

  return jsonb_build_object('ok', true, 'op', v_op, 'subject_kind', v_kind, 'subject_ref', v_ref,
    'command_id', v_command, 'run_ids', to_jsonb(v_runs), 'actor', v_actor, 'reason', v_reason,
    'closed', jsonb_build_object('command', n_cmd, 'plan', n_plan, 'workflow_runs', n_run,
      'step_runs', n_step, 'tasks', n_task, 'handoffs', n_handoff, 'outbox_superseded', n_outbox,
      'traces_sealed', n_trace),
    'queued_derived_work_remaining', 0);
end

fn_kernel_paid_provider_gate:
declare
  v_switch  boolean;
  v_routes  bigint;
  v_held    bigint;
  v_model   text := nullif(btrim(coalesce(p_model, '')), '');
  v_reg     boolean;
  v_open    timestamptz;
begin
  -- An EMPTY STRING is not a deterministic path, it is a caller that did not say. Denied, with its
  -- own rule name, because "I passed you nothing" and "I am not calling a provider" are different
  -- statements and a gate that conflates them has a hole shaped like a typo.
  if p_model is not null and v_model is null then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'model_unspecified',
      'reason', 'an empty model string is not a deterministic path; pass NULL or ''none'' to declare '
             || 'that no provider call is being made', 'model', p_model);
  end if;

  -- A deterministic path is not a provider call and never was. It is named explicitly rather than
  -- reached by falling off the end of the checks.
  if v_model is null or v_model in ('none', 'none/deterministic') then
    return jsonb_build_object('allowed', true, 'gate', 'kernel_k12',
      'rule', 'deterministic_path', 'reason', 'no provider call is being made', 'model', p_model);
  end if;

  -- 1. the explicit switch
  select exists (select 1 from public.app_secrets
                  where key = 'no_paid_ai' and lower(coalesce(value,'')) in ('1','true','yes','on'))
    into v_switch;
  if v_switch then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'no_paid_ai_switch', 'reason', 'app_secrets.no_paid_ai is set; paid inference is off',
      'model', v_model);
  end if;

  -- 2. empty route state is DENIED, not permitted. An absent hold is not a permission — this is the
  --    "what does it print when its input is absent?" case, answered on purpose.
  select count(*) into v_routes from public.llm_route_health;
  if v_routes = 0 then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'empty_route_state',
      'reason', 'llm_route_health holds no rows; with no route state there is no evidence that any '
             || 'route is permitted', 'model', v_model);
  end if;

  -- 3. the founder's hold, on ANY route. He held the whole estate on 15 Aug 2026; holding one route
  --    and leaving the others open would not be what he asked for.
  select count(*) into v_held from public.llm_route_health where open_until is not null and open_until > now();
  if v_held > 0 then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'founder_hold',
      'reason', v_held || ' of ' || v_routes || ' routes are held open-circuit until '
             || (select max(open_until)::text from public.llm_route_health where open_until > now()),
      'held', v_held, 'routes', v_routes, 'model', v_model);
  end if;

  -- 4. the route must be registered and active
  select exists (select 1 from public.model_registry r where r.model_id = v_model and r.active) into v_reg;
  if not v_reg then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'route_not_registered',
      'reason', 'model ' || v_model || ' is not an active row in model_registry', 'model', v_model);
  end if;

  -- 5. this route's own breaker
  select open_until into v_open from public.llm_route_health where model_id = v_model;
  if v_open is not null and v_open > now() then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'route_open', 'reason', 'circuit open until ' || v_open::text, 'model', v_model);
  end if;

  return jsonb_build_object('allowed', true, 'gate', 'kernel_k12',
    'rule', 'registered_breaker_closed', 'reason', 'switch off, no hold, route registered, breaker closed',
    'model', v_model);
exception
  -- The gate itself failing is the most dangerous case, because it is the one a try/catch upstream
  -- used to swallow. It answers DENIED, in its own voice, rather than throwing into a caller that
  -- might interpret an exception as "carry on".
  when others then
    return jsonb_build_object('allowed', false, 'gate', 'kernel_k12',
      'rule', 'gate_unreadable',
      'reason', 'the paid-provider gate could not be evaluated: ' || sqlstate || ' ' || sqlerrm,
      'model', p_model);
end

fn_phase_c_refund_decision_immutable:
begin
  if tg_op = 'DELETE' then
    raise exception
      'phase_c_refund_decision %: a founder refund decision cannot be deleted', old.decision_id
      using errcode = '23514',
            hint = 'A decision that changed is a NEW row citing the old one in '
                || 'supersedes_decision_id, with supersession_reason. The record of what was '
                || 'decided, by whom and when is the point of the table.';
  end if;

  -- The decision itself is frozen. Only the post-decision execution record may be filled in, and
  -- only once, and only from NULL: an executor cannot rewrite who approved, or why, or when.
  if new.decided_by  is distinct from old.decided_by
     or new.decision is distinct from old.decision
     or new.reason   is distinct from old.reason
     or new.decided_at is distinct from old.decided_at
     or new.request_id is distinct from old.request_id then
    raise exception
      'phase_c_refund_decision %: the decision is append-only; supersede it, do not edit it',
      old.decision_id
      using errcode = '23514',
            hint = 'Insert a NEW decision whose supersedes_decision_id points at this one.';
  end if;

  if old.executed_at   is not null and new.executed_at   is distinct from old.executed_at   then
    raise exception 'phase_c_refund_decision %: executed_at is written once', old.decision_id using errcode = '23514';
  end if;
  if old.reconciled_at is not null and new.reconciled_at is distinct from old.reconciled_at then
    raise exception 'phase_c_refund_decision %: reconciled_at is written once', old.decision_id using errcode = '23514';
  end if;

  return new;
end

fn_kernel_reviewer_independent:
declare
  a_pc text; b_pc text;   -- the Phase C canonical resolver
  a_or text; b_or text;   -- the org-layer alias resolver
begin
  -- An absent reviewer is not an independent reviewer. Absence is never a pass.
  if coalesce(btrim(p_reviewer), '') = '' or coalesce(btrim(p_creator), '') = '' then
    return false;
  end if;

  select role_id into a_pc from public.fn_phase_c_resolve_actor(p_creator);
  select role_id into b_pc from public.fn_phase_c_resolve_actor(p_reviewer);
  -- An identity that does not resolve is refused, not waved through. A null here used to mean
  -- "cannot tell", and "cannot tell" must not be spendable as "yes".
  if a_pc is null or b_pc is null then return false; end if;
  if a_pc = b_pc then return false; end if;

  a_or := coalesce(public.fn_org_agent_resolve(p_creator), a_pc);
  b_or := coalesce(public.fn_org_agent_resolve(p_reviewer), b_pc);
  if a_or = b_or then return false; end if;

  -- Cross-vocabulary collapse: the creator under one resolver and the reviewer under the other.
  if a_pc = b_or or a_or = b_pc then return false; end if;

  return true;
end

fn_kernel_review_decide:
declare
  v_task     bigint := nullif(regexp_replace(coalesce(p_input->>'task_id',''), '\D', '', 'g'), '')::bigint;
  v_reviewer text   := coalesce(btrim(p_input->>'reviewer_role_id'), '');
  v_decision text   := lower(coalesce(btrim(p_input->>'decision'), ''));
  v_reason   text   := coalesce(btrim(p_input->>'reason'), '');
  t          public.phase_c_task%rowtype;
  v_declared text;
  v_trace    bigint;
begin
  if v_decision not in ('approved','rejected','changes_requested') then
    raise exception 'fn_kernel_review_decide: decision must be approved, rejected or changes_requested, got %',
      v_decision using errcode = '22023';
  end if;
  if v_reason = '' then
    raise exception 'fn_kernel_review_decide: a review with no stated reason is not a review'
      using errcode = '23514';
  end if;

  select * into t from public.phase_c_task where task_id = v_task;
  if not found then
    return jsonb_build_object('ok', false, 'error','task_not_found', 'task_id', v_task);
  end if;

  -- The declared reviewer comes from the FROZEN Phase B registry, read never written.
  select nullif(btrim(s.independent_reviewer_role_id), '') into v_declared
    from public.phase_b_workflow_step s where s.step_id = t.step_id;

  -- Compare RESOLVED, not literal: the registry may name a role and the caller an alias of it.
  -- fn_phase_c_resolve_actor is set-returning, so each side is pulled out in its own scalar
  -- subquery — calling it directly inside a boolean expression raises 42804.
  if v_declared is not null
     and (select role_id from public.fn_phase_c_resolve_actor(v_reviewer))
         is distinct from (select role_id from public.fn_phase_c_resolve_actor(v_declared)) then
    return jsonb_build_object('ok', false, 'error','not_the_declared_reviewer',
      'declared', v_declared, 'offered', v_reviewer, 'step_id', t.step_id,
      'message','Phase B names the independent reviewer for this step. It is frozen, and this is '
             || 'not that role.');
  end if;

  if not public.fn_kernel_reviewer_independent(t.accountable_role_id, v_reviewer) then
    return jsonb_build_object('ok', false, 'error','reviewer_not_independent',
      'creator', t.accountable_role_id, 'reviewer', v_reviewer,
      'message','The reviewer resolves to the same employee as the creator under at least one of '
             || 'the two identity vocabularies. A self-review is not a review.');
  end if;

  v_trace := public.fn_phase_c_trace_write('TRACE-ROLE-ACTION', jsonb_build_object(
    'subject_kind','task', 'subject_ref', t.task_id::text, 'task_id', t.task_id,
    'command_id', t.command_id, 'run_id', t.run_id,
    'actor_role_id', v_reviewer, 'reviewer_role_id', v_reviewer, 'reviewer_independent', true,
    'manager_role_id', t.manager_role_id, 'system_actor_id','system.workflow_engine',
    'state_before', t.state, 'state_after', t.state,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'review_decision', v_decision, 'reason', v_reason,
      'declared_reviewer', coalesce(v_declared,'(none declared for this step)'))),
    'status','sealed'));

  update public.phase_c_task
     set reviewer_role_id = v_reviewer
   where task_id = v_task;

  return jsonb_build_object('ok', true, 'task_id', v_task, 'reviewer_role_id', v_reviewer,
    'decision', v_decision, 'declared_reviewer', v_declared, 'trace_id', v_trace,
    'independent', true);
end

fn_kernel_assert_not_in_delivery:
begin
  if public.fn_kernel_in_delivery() then
    raise exception
      're-entry refused: % is a kernel writer and was called from event delivery', p_writer
      using errcode = '23514',
            hint = 'A domain event records a state change that already happened. A consumer may '
                || 'notify, project or fan out; it may not call the producer.';
  end if;
end

fn_kernel_outbox_emit:
declare
  e public.phase_b_event%rowtype;
  v_id bigint;
  v_event  text := nullif(btrim(coalesce(p_input->>'event_id','')), '');
  v_dedupe text := nullif(btrim(coalesce(p_input->>'dedupe_value','')), '');
  v_prod   text := coalesce(nullif(btrim(p_input->>'producer'),''), 'kernel:unnamed');
  v_corr   text := nullif(btrim(coalesce(p_input->>'correlation_id','')), '');
  v_caus   text := nullif(btrim(coalesce(p_input->>'causation_id','')), '');
  v_src    text := nullif(btrim(coalesce(p_input->>'source_id','')), '');
  v_consumer text;
begin
  select * into e from public.phase_b_event where event_id = v_event;
  if not found then
    raise exception 'fn_kernel_outbox_emit: % is not in the frozen Phase B event registry — fail closed',
      coalesce(v_event,'(null)') using errcode = '23503';
  end if;
  if v_dedupe is null then
    raise exception 'fn_kernel_outbox_emit: dedupe_value is required for %', v_event using errcode = '23502';
  end if;
  if v_corr is null or v_caus is null or v_src is null then
    raise exception 'fn_kernel_outbox_emit: % is missing identity (correlation_id=%, causation_id=%, source_id=%)',
      v_event, coalesce(v_corr,'(null)'), coalesce(v_caus,'(null)'), coalesce(v_src,'(null)')
      using errcode = '23514';
  end if;

  select role_id into v_consumer from public.fn_phase_c_resolve_actor(e.primary_consumer_role_id);
  v_consumer := coalesce(v_consumer, e.primary_consumer_role_id);

  insert into public.phase_c_event_outbox
    (event_id, workflow_id, object_version, producer, accountable_role_id, primary_consumer_role_id,
     payload, dedupe_value, status, correlation_id, causation_id, source_id,
     command_id, workflow_run_id, step_run_id, task_id, trace_id)
  values (e.event_id, e.workflow_id, coalesce((p_input->>'object_version')::bigint, 1),
          v_prod, v_consumer, coalesce(e.primary_consumer_role_id,''),
          coalesce(p_input->'payload', '{}'::jsonb), v_dedupe, 'pending',
          v_corr, v_caus, v_src,
          nullif(p_input->>'command_id','')::bigint,
          nullif(p_input->>'workflow_run_id','')::bigint,
          nullif(p_input->>'step_run_id','')::bigint,
          -- ROOT CAUSE 2. The relationship a cancellation follows must be a COLUMN. task_id was the
          -- one missing normalised link: every producer already carries it in the payload it emits,
          -- so it is read from the explicit input first and from the payload second, and never
          -- looked up from JSON again after this point.
          coalesce(nullif(p_input->>'task_id','')::bigint,
                   nullif(p_input->'payload'->>'task_id','')::bigint),
          nullif(p_input->>'trace_id','')::bigint)
  on conflict (event_id, dedupe_value) do nothing
  returning outbox_id into v_id;

  -- A duplicate is not a new row and it is not an error: re-read the one that already exists.
  if v_id is null then
    select outbox_id into v_id from public.phase_c_event_outbox
     where event_id = e.event_id and dedupe_value = v_dedupe;
  end if;
  -- Error and empty must not return the same value.
  if v_id is null then
    raise exception 'fn_kernel_outbox_emit wrote no row and found none for %/%', v_event, v_dedupe
      using errcode = '23502';
  end if;
  return v_id;
end

fn_kernel_event_consume:
declare
  o public.phase_c_event_outbox%rowtype;
  e public.phase_b_event%rowtype;
  v_run bigint; v_step text; v_prior text;
  v_sk text; v_next text; v_next_owner text; v_ho text; v_sk_reason text;
  v_handled boolean := false; v_ref text; v_result jsonb; v_reason text;
begin
  v_prior := coalesce(nullif(current_setting('kernel.in_delivery', true),''), '0');
  perform set_config('kernel.in_delivery', '1', true);

  select * into o from public.phase_c_event_outbox where outbox_id = p_outbox_id;
  if not found then
    v_reason := 'unknown_outbox_row';
  else
    select * into e from public.phase_b_event where event_id = o.event_id;
    if not found then
      v_reason := format('%s is not in the frozen Phase B event registry', o.event_id);

    -- A row naming a command must be for a workflow that command actually selected.
    elsif coalesce(o.command_id::text, o.payload->>'command_id') is not null
      and not exists (select 1 from public.founder_command_workflow_link l
                       where l.command_id = coalesce(o.command_id, (o.payload->>'command_id')::bigint)
                         and l.workflow_id = o.workflow_id) then
      v_reason := format('event %s names workflow %s but command %s selected a different workflow',
                         o.event_id, o.workflow_id, coalesce(o.command_id::text, o.payload->>'command_id'));

    elsif e.event_name like '%.started' then
      -- workflow.started is a RECORD of a run fn_kernel_workflow_start already created.
      v_run := coalesce(o.workflow_run_id, nullif(o.payload->>'run_id','')::bigint);
      if v_run is null then
        v_reason := format('%s carries no workflow_run_id: it was produced as a command, not as a '
                        || 'record of a run. The kernel creates the run and then emits.', o.event_id);
      elsif not exists (select 1 from public.phase_c_workflow_run where run_id = v_run) then
        v_reason := format('%s names workflow run %s, which does not exist', o.event_id, v_run);
      else
        v_handled := true;
        v_ref     := 'run:' || v_run;
        v_result  := jsonb_build_object('projected','workflow_run', 'run_id', v_run,
                       'workflow_id', o.workflow_id, 'correlation_id', o.correlation_id,
                       'step_run_id', o.step_run_id, 'created_by', o.producer);
      end if;

    -- WORKFLOW-level lifecycle first. EV-Wnn-COMPLETED is named 'phase_b.wnn.completed', so it
    -- matches '%.completed' too, and K3 stamps a step_run_id on it. Without this branch the run
    -- closure would be read as a step completion and reported against the closure step.
    elsif o.event_id in (public.fn_phase_c_lifecycle_event(o.workflow_id, 'completed'),
                         public.fn_phase_c_lifecycle_event(o.workflow_id, 'blocked')) then
      v_run := coalesce(o.workflow_run_id, nullif(o.payload->>'run_id','')::bigint);
      if v_run is null then
        v_reason := format('%s carries no workflow_run_id', o.event_id);
      elsif not exists (select 1 from public.phase_c_workflow_run where run_id = v_run) then
        v_reason := format('%s names workflow run %s, which does not exist', o.event_id, v_run);
      else
        v_handled := true;
        v_ref := 'run_' || (select state from public.phase_c_workflow_run where run_id = v_run)
                 || ':' || v_run;
        v_result := jsonb_build_object('projected','workflow_lifecycle', 'created', 0,
          'run_id', v_run, 'workflow_id', o.workflow_id,
          'state', (select state from public.phase_c_workflow_run where run_id = v_run),
          'closed_at', (select closed_at from public.phase_c_workflow_run where run_id = v_run),
          'fact', o.payload->>'fact');
      end if;

    elsif e.event_name like '%.completed' and (o.step_run_id is not null or o.payload ? 'step_id') then
      v_run  := coalesce(o.workflow_run_id, nullif(o.payload->>'run_id','')::bigint);
      v_step := coalesce(o.payload->>'step_id',
                         (select step_id from public.phase_c_workflow_step_run
                           where step_run_id = o.step_run_id));
      if v_run is null or v_step is null then
        v_reason := format('completed event %s carries no run (%s) or no step (%s)',
                           o.event_id, coalesce(v_run::text,'null'), coalesce(v_step,'null'));
      else
        -- PROJECTION ONLY. fn_kernel_step_complete is the single authoritative progression path
        -- and has already created whatever comes next, inside the transaction that closed the
        -- step. Creating a task here would be a second creator racing the first, and it would
        -- hand a receiving owner work they never accepted.
        -- aliased: this function's OUT parameter `reason` would otherwise shadow the
        -- classifier's column of the same name and raise 42702.
        select c.kind, c.next_step_id, c.next_owner_role_id, c.handoff_id, c.reason
          into v_sk, v_next, v_next_owner, v_ho, v_sk_reason
          from public.fn_kernel_step_successor(v_step) c;
        v_handled := true;
        v_ref := case v_sk
                   when 'closure'    then 'closure_step:' || v_step
                   when 'same_owner' then 'kernel_opened:' || coalesce(v_next,'?')
                   when 'cross_owner' then 'kernel_handoff:' || coalesce(v_ho,'?')
                   else 'registry_defect:' || v_sk || ':' || v_step end;
        v_result := jsonb_build_object(
          'projected','step_completed', 'created', 0,
          'run_id', v_run, 'step_id', v_step, 'successor_kind', v_sk,
          'next_step_id', v_next, 'next_owner_role_id', v_next_owner, 'handoff_id', v_ho,
          'successor_reason', v_sk_reason,
          'note','fn_kernel_step_complete is the only creator of business work; delivery projects.');
      end if;

    else
      v_reason := format('no canonical consumer for %s (%s)', o.event_id, e.event_name);
    end if;
  end if;

  perform set_config('kernel.in_delivery', v_prior, true);
  return query select v_handled, v_ref, v_result, v_reason;
end

fn_kernel_workflow_start:
declare
  v_pd_dispatch jsonb := '{}'::jsonb;  -- D36
  w  public.phase_b_workflow%rowtype;
  s  public.phase_b_workflow_step%rowtype;
  v_wf        text   := nullif(btrim(coalesce(p_input->>'workflow_id','')), '');
  v_object    text   := nullif(btrim(coalesce(p_input->>'business_object_id','')), '');
  v_source_k  text   := nullif(btrim(coalesce(p_input->>'source_kind','')), '');
  v_source_r  text   := nullif(btrim(coalesce(p_input->>'source_ref','')), '');
  v_by        text   := nullif(btrim(coalesce(p_input->>'requested_by','')), '');
  v_command   bigint := nullif(p_input->>'command_id','')::bigint;
  v_version   bigint := coalesce(nullif(p_input->>'object_version','')::bigint, 1);
  v_priority  text   := coalesce(nullif(p_input->>'priority',''), 'P2');
  v_ctx       jsonb  := coalesce(p_input->'trigger_ctx', '{}'::jsonb);
  v_corr      text;
  v_caus      text;
  v_dedupe    text;
  v_run       bigint;
  v_step_run  bigint;
  v_task      bigint;
  v_outbox    bigint;
  v_run_trace bigint;
  v_step_trace bigint;
  v_task_trace bigint;
  v_task_parent bigint;
  v_owner     text;
  v_step_owner text;
  v_kind      text;
  v_start_event text;
  v_input_hash text;
  -- Scalars, not a RECORD: a plpgsql record read after a SELECT INTO that matched nothing is a
  -- trap this estate has already paid for once.
  v_prior_run   bigint;
  v_prior_state text;
  v_prior_trace bigint;
  v_prior_step  bigint;
  v_prior_task  bigint;
begin
  -- ---- 0. a consumer may not re-enter the producer ----------------------------------------
  perform public.fn_kernel_assert_not_in_delivery('fn_kernel_workflow_start');

  if v_wf is null or v_object is null or v_source_r is null or v_by is null then
    raise exception 'fn_kernel_workflow_start: workflow_id, business_object_id, source_ref and requested_by are all required (got %, %, %, %)',
      coalesce(v_wf,'(null)'), coalesce(v_object,'(null)'), coalesce(v_source_r,'(null)'), coalesce(v_by,'(null)')
      using errcode = '22023';
  end if;
  if v_source_k not in ('founder_command','autonomous') then
    raise exception 'fn_kernel_workflow_start: source_kind must be founder_command or autonomous, got %',
      coalesce(v_source_k,'(null)') using errcode = '22023';
  end if;
  if v_source_k = 'founder_command' and v_command is null then
    raise exception 'fn_kernel_workflow_start: source_kind founder_command requires a command_id'
      using errcode = '22023';
  end if;
  v_corr := coalesce(nullif(btrim(p_input->>'correlation_id'),''), v_source_r);
  v_caus := coalesce(nullif(btrim(p_input->>'causation_id'),''), v_source_r);

  -- ---- (a) the workflow run ---------------------------------------------------------------
  select * into w from public.phase_b_workflow where workflow_id = v_wf;
  if not found then
    raise exception 'fn_kernel_workflow_start (a): % is not in the frozen Phase B workflow registry — fail closed',
      v_wf using errcode = '23503';
  end if;

  -- The accountable role comes from the registry and must RESOLVE. Never defaulted; there is no
  -- chief_of_staff fallback here and there will not be one.
  select kind, role_id into v_kind, v_owner from public.fn_phase_c_resolve_actor(w.accountable_role_id);
  if v_owner is null or v_kind is distinct from 'canonical' then
    raise exception 'fn_kernel_workflow_start (a): workflow % names accountable role %, which resolves to % — no run created',
      v_wf, w.accountable_role_id, coalesce(v_kind,'nothing') using errcode = '23514';
  end if;

  -- The start event is read from the frozen registry, never concatenated. A literal
  -- 'EV-W01-STARTED' once announced W01 for every command the company had ever received.
  v_start_event := public.fn_phase_c_lifecycle_event(v_wf, 'started');
  if v_start_event is null then
    raise exception 'fn_kernel_workflow_start (f): workflow % declares no .started event in phase_b_event',
      v_wf using errcode = '23503';
  end if;

  -- Idempotency, unchanged in shape from fn_phase_c_workflow_start so existing runs still match.
  v_dedupe := v_wf || ':' || v_object || ':' || v_version::text;
  select r.run_id, r.state, r.trace_id
    into v_prior_run, v_prior_state, v_prior_trace
    from public.phase_c_workflow_run r where r.dedupe_key = v_dedupe;
  if v_prior_run is not null then
    select sr.step_run_id into v_prior_step from public.phase_c_workflow_step_run sr
     where sr.run_id = v_prior_run order by sr.step_run_id limit 1;
    select t.task_id into v_prior_task from public.phase_c_task t
     where t.run_id = v_prior_run order by t.task_id limit 1;
    -- A second call creates NOTHING. Not a new run, not a second task, not a second event.
    return jsonb_build_object('ok', true, 'duplicate', true, 'run_id', v_prior_run,
      'workflow_id', v_wf, 'business_object_id', v_object, 'object_version', v_version,
      'state', v_prior_state, 'step_run_id', v_prior_step,
      'task_id', v_prior_task, 'trace_id', v_prior_trace,
      'dedupe_key', v_dedupe, 'created', '{}'::jsonb);
  end if;

  v_input_hash := encode(sha256(convert_to(
    v_wf || '|' || v_object || '|' || v_version::text || '|' || v_ctx::text, 'UTF8')), 'hex');

  insert into public.phase_c_workflow_run
    (workflow_id, business_object_id, object_version, start_event, accountable_role_id,
     state, dedupe_key, command_id)
  values (v_wf, v_object, v_version, v_start_event, v_owner, 'queued', v_dedupe, v_command)
  returning run_id into v_run;
  if v_run is null then
    raise exception 'fn_kernel_workflow_start (a): the workflow run insert produced no row for %', v_wf
      using errcode = '23502';
  end if;

  -- ---- (d.1) the ROOT trace, before anything hangs from it ---------------------------------
  v_run_trace := public.fn_phase_c_trace_write('TRACE-WORKFLOW', jsonb_build_object(
    'subject_kind','workflow_run', 'subject_ref', v_run::text, 'run_id', v_run,
    'command_id', v_command,
    'actor_role_id', v_owner, 'system_actor_id','system.workflow_engine',
    'input_hash', v_input_hash,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'business_object_id', v_object, 'dedupe_key', v_dedupe, 'source_kind', v_source_k,
      'source_ref', v_source_r, 'requested_by', v_by, 'trigger_ctx', v_ctx)),
    'event_ids', jsonb_build_array(v_start_event),
    'state_before','', 'state_after','queued', 'status','open'));
  update public.phase_c_workflow_run set trace_id = v_run_trace where run_id = v_run;
  if v_run_trace is null then
    raise exception 'fn_kernel_workflow_start (d): the run has no root trace' using errcode = '23502';
  end if;

  -- The run is ACTIVE because its first step run is opened in this same transaction. The move is
  -- made as a declared transition (queued -> active) so z20_phase_c_workflow_state_guard and
  -- phase_b_workflow_transition are load-bearing rather than decorative.
  update public.phase_c_workflow_run set state = 'active' where run_id = v_run;

  -- ---- (b) the initial step run, at the REGISTRY entry step --------------------------------
  select * into s from public.phase_b_workflow_step
   where workflow_id = v_wf and step_no = 1;               -- UNIQUE (workflow_id, step_no)
  if not found then
    raise exception 'fn_kernel_workflow_start (b): workflow % declares no step_no = 1', v_wf
      using errcode = '23502';
  end if;

  select kind, role_id into v_kind, v_step_owner from public.fn_phase_c_resolve_actor(s.accountable_role_id);
  if v_step_owner is null or v_kind is distinct from 'canonical' then
    raise exception 'fn_kernel_workflow_start (c): step % names owner %, which resolves to % — no task created',
      s.step_id, s.accountable_role_id, coalesce(v_kind,'nothing') using errcode = '23514';
  end if;

  insert into public.phase_c_workflow_step_run
    (run_id, step_id, accountable_role_id, reviewer_role_id, state, attempt_no,
     input_hash, output_hash, gates_evaluated, authority_result, idempotency_key)
  values (v_run, s.step_id, v_step_owner, coalesce(s.independent_reviewer_role_id,''), 'active', 1,
          v_input_hash, '', '[]'::jsonb, 'pending: the step has not been executed yet',
          s.idempotency_scope || '|' || v_run || '|' || s.step_id || '|kernel')
  returning step_run_id into v_step_run;
  if v_step_run is null then
    raise exception 'fn_kernel_workflow_start (b): the step run insert produced no row for %', s.step_id
      using errcode = '23502';
  end if;

  -- The step run gets its own TRACE-STEP, parented to the run's root. phase_c_workflow_step_run
  -- has no trace guard trigger (only phase_c_task does), so an active step run with trace_id NULL
  -- is exactly what nobody notices — the first rehearsal of this file measured 6 of 11 step runs
  -- in that state, two of them created by this function.
  v_step_trace := public.fn_phase_c_trace_write('TRACE-STEP', jsonb_build_object(
    'subject_kind','step_run', 'subject_ref', v_step_run::text,
    'run_id', v_run, 'step_run_id', v_step_run, 'command_id', v_command,
    'actor_role_id', v_step_owner, 'system_actor_id','system.workflow_engine',
    'reviewer_role_id', coalesce(s.independent_reviewer_role_id,''),
    'authority_result','pending: the step has not been executed yet',
    'input_hash', v_input_hash,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'step_id', s.step_id, 'step_name', s.step_name, 'entry_condition', s.entry_condition)),
    'state_before','', 'state_after','active', 'status','open'));
  update public.phase_c_workflow_step_run set trace_id = v_step_trace where step_run_id = v_step_run;
  update public.phase_c_trace set parent_trace_id = v_run_trace where trace_id = v_step_trace;
  if v_step_trace is null then
    raise exception 'fn_kernel_workflow_start (d): step run % has no trace', v_step_run
      using errcode = '23502';
  end if;

  -- ---- (c) EXACTLY ONE operational task -----------------------------------------------------
  -- Deterministic key. It is also the key the invariant check looks for: a founder command may
  -- have run:N:step:* work or cmd:N:* plan rows, never both.
  v_task := public.fn_phase_c_task_create(jsonb_build_object(
    'source_kind', v_source_k, 'source_ref', v_source_r,
    'command_id', v_command, 'run_id', v_run, 'workflow_id', v_wf, 'step_id', s.step_id,
    'accountable_role_id', v_step_owner,
    'objective', format('%s — %s: perform %s (%s) for %s.',
                        w.workflow_name, v_start_event, s.step_id, s.step_name, v_object),
    'required_inputs', s.required_inputs,
    'requested_output', s.required_output,
    'acceptance_criteria', s.acceptance_criteria,
    'closure_criteria', s.closure_criteria,
    'priority', v_priority,
    'reviewer_required', (coalesce(s.independent_reviewer_role_id,'') <> ''),
    'reviewer_role_id', coalesce(s.independent_reviewer_role_id,''),
    'idempotency_key', 'run:' || v_run || ':step:' || s.step_id));
  if v_task is null then
    raise exception 'fn_kernel_workflow_start (c): no operational task was created for run % step %',
      v_run, s.step_id using errcode = '23502';
  end if;

  -- ---- (d.2) the CHILD trace for the task, parented -----------------------------------------
  -- a00_phase_c_task_trace_guard mints it on INSERT and parents it to the command trace when the
  -- task carries a command_id, otherwise to the run trace. Both are roots; what is refused here is
  -- a task hanging from nothing.
  select trace_id into v_task_trace from public.phase_c_task where task_id = v_task;
  select parent_trace_id into v_task_parent from public.phase_c_trace where trace_id = v_task_trace;
  if v_task_trace is null or v_task_parent is null then
    raise exception 'fn_kernel_workflow_start (d): task % has trace % with parent % — a task without its parented trace is refused',
      v_task, coalesce(v_task_trace::text,'null'), coalesce(v_task_parent::text,'null')
      using errcode = '23502';
  end if;

  -- ---- (e) NO HANDOFF AT START -- K14 -------------------------------------------------------
  -- Deliberately empty, and named so a reader looking for the block that used to be here finds the
  -- reason rather than a gap. The entry step's outgoing handoff run is created by
  -- fn_kernel_step_complete when that step completes, from its accepted output. Creating it here
  -- as well produced TWO open handoff runs on one registry edge the moment the entry step
  -- completed, and the successor step could then never be opened.

  -- ---- (f) ONE factual event ----------------------------------------------------------------
  -- Emitted LAST, after the state it describes exists. Its consumer may not create any of it.
  v_outbox := public.fn_kernel_outbox_emit(jsonb_build_object(
    'event_id', v_start_event, 'producer', 'kernel:workflow_start',
    'object_version', v_version,
    'correlation_id', v_corr, 'causation_id', v_caus, 'source_id', v_source_r,
    'command_id', v_command, 'workflow_run_id', v_run, 'step_run_id', v_step_run,
    'trace_id', v_run_trace,
    'dedupe_value', 'kernel:started:' || v_dedupe,
    'payload', jsonb_build_object(
      'fact','workflow.started',
      'workflow_id', v_wf, 'workflow_run_id', v_run, 'step_id', s.step_id,
      'step_run_id', v_step_run, 'task_id', v_task, 'handoff_run_id', null,
      'business_object_id', v_object, 'object_version', v_version,
      'accountable_role_id', v_owner, 'step_accountable_role_id', v_step_owner,
      'source_kind', v_source_k, 'source_ref', v_source_r, 'requested_by', v_by,
      'trace_id', v_run_trace, 'input_hash', v_input_hash)));
  if v_outbox is null then
    raise exception 'fn_kernel_workflow_start (f): no event row was written for run %', v_run
      using errcode = '23502';
  end if;

  -- ---- all or nothing -----------------------------------------------------------------------
  if v_run is null or v_step_run is null or v_task is null or v_outbox is null
     or v_run_trace is null or v_step_trace is null or v_task_trace is null then
    raise exception 'fn_kernel_workflow_start incomplete: run=% step_run=% task=% outbox=% run_trace=% step_trace=% task_trace=%',
      v_run, v_step_run, v_task, v_outbox, v_run_trace, v_step_trace, v_task_trace
      using errcode = '23502';
  end if;

  -- ---- (g) PHASE D DISPATCH (D36) --------------------------------------------------------------
  -- THE FIRST STEP OF A RUN IS OPENED HERE, INLINE — this routine does not call fn_kernel_open_step.
  -- Wiring the dispatch only into fn_kernel_open_step therefore reached successors and handoffs and
  -- missed every run's first step, which is the step an autonomous arrival actually causes. Both
  -- openers call the same routine so the two paths cannot drift apart.
  v_pd_dispatch := public.fn_phase_d_dispatch_step(jsonb_build_object(
    'step_run_id', v_step_run, 'actor_role_id', v_step_owner,
    'opened_by_kind', v_source_k, 'opened_by_ref', v_source_r,
    'idempotency_key', s.idempotency_scope || '|' || v_run || '|' || s.step_id || '|kernel',
    'correlation_id', v_corr));

  return jsonb_build_object(
    'ok', true, 'duplicate', false,
    'run_id', v_run, 'workflow_id', v_wf, 'workflow_name', w.workflow_name,
    'business_object_id', v_object, 'object_version', v_version, 'dedupe_key', v_dedupe,
    'state','active', 'accountable_role_id', v_owner,
    'step_id', s.step_id, 'step_run_id', v_step_run, 'step_accountable_role_id', v_step_owner,
    'task_id', v_task, 'task_idempotency_key', 'run:' || v_run || ':step:' || s.step_id,
    'handoff_run_id', null, 'handoff_id', null,
    'run_trace_id', v_run_trace, 'step_trace_id', v_step_trace,
    'task_trace_id', v_task_trace, 'handoff_trace_id', null,
    'event_id', v_start_event, 'outbox_id', v_outbox,
    'correlation_id', v_corr, 'causation_id', v_caus, 'source_id', v_source_r,
    'command_id', v_command, 'source_kind', v_source_k, 'requested_by', v_by,
    'created', jsonb_build_object('run',1, 'step_run',1, 'task',1, 'traces',
      3,
      'handoff', 0, 'event',1));
end

fn_phase_c_task_trace_committed:
declare v_trace bigint; v_state text; t public.phase_c_trace%rowtype;
begin
  select state, trace_id into v_state, v_trace
    from public.phase_c_task where task_id = new.task_id;
  if not found then return null; end if;          -- deleted in this transaction; nothing to assert

  if v_trace is null then
    raise exception 'phase_c_task %: committed in state % with no trace', new.task_id, v_state
      using errcode = '23514',
            hint = 'TRACE-TASK declares trace_required=YES and completed_without_trace_allowed=NO. '
                || 'The trace is written by z90_phase_c_task_trace_subject on AFTER INSERT; if it '
                || 'is missing at commit, something cleared trace_id after the row was created.';
  end if;

  select * into t from public.phase_c_trace where trace_id = v_trace;
  if not found then
    raise exception 'phase_c_task %: trace % does not exist at commit', new.task_id, v_trace
      using errcode = '23503',
            hint = 'The task points at a trace that was deleted in this transaction. Evidence is '
                || 'superseded, never removed.';
  end if;
  if t.task_id is distinct from new.task_id then
    raise exception 'phase_c_task %: trace % names task % — the ledger and the task disagree',
      new.task_id, v_trace, coalesce(t.task_id::text,'NULL')
      using errcode = '23514',
            hint = 'A trace whose task_id does not resolve is exactly the orphan class K6 exists '
                || 'to make impossible.';
  end if;
  return null;
end

fn_phase_c_step_run_trace_subject:
declare v_parent bigint; v_trace bigint;
begin
  if new.trace_id is not null then
    update public.phase_c_trace
       set step_run_id = new.step_run_id, subject_ref = new.step_run_id::text
     where trace_id = new.trace_id and step_run_id is null and sealed_at is null;
    return null;
  end if;

  select r.trace_id into v_parent from public.phase_c_workflow_run r where r.run_id = new.run_id;

  v_trace := public.fn_phase_c_trace_write('TRACE-STEP', jsonb_build_object(
    'subject_kind','step_run', 'subject_ref', new.step_run_id::text,
    'run_id', new.run_id, 'step_run_id', new.step_run_id,
    'actor_role_id', new.accountable_role_id, 'reviewer_role_id', new.reviewer_role_id,
    'system_actor_id','system.workflow_engine',
    'authority_result', new.authority_result, 'gates', new.gates_evaluated,
    'input_hash', new.input_hash, 'output_hash', new.output_hash,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'step_id', new.step_id, 'attempt_no', new.attempt_no,
      'idempotency_key', new.idempotency_key)),
    'parent_trace_id', v_parent,
    'state_before','', 'state_after', new.state, 'status','open'));

  update public.phase_c_workflow_step_run set trace_id = v_trace where step_run_id = new.step_run_id;
  return null;
end

fn_phase_c_step_run_trace_committed:
declare v_trace bigint; v_state text;
begin
  select state, trace_id into v_state, v_trace
    from public.phase_c_workflow_step_run where step_run_id = new.step_run_id;
  if not found then return null; end if;

  if v_state not in ('active','waiting_review','waiting_input','blocked',
                     'completed','failed','cancelled','superseded','skipped') then
    return null;                          -- not_ready / ready: the step has not started
  end if;

  if v_trace is null then
    raise exception 'phase_c_workflow_step_run %: committed in state % with no trace',
      new.step_run_id, v_state using errcode = '23514',
      hint = 'TRACE-STEP declares trace_required=YES and completed_without_trace_allowed=NO. The '
          || 'trace is written by z90_phase_c_step_run_trace_subject on AFTER INSERT.';
  end if;
  if not exists (select 1 from public.phase_c_trace where trace_id = v_trace) then
    raise exception 'phase_c_workflow_step_run %: trace % does not exist at commit',
      new.step_run_id, v_trace using errcode = '23503',
      hint = 'Evidence is superseded, never removed.';
  end if;
  return null;
end

fn_kernel_component_reachability:
declare
  c              public.phase_c_component%rowtype;
  v_oid          oid;
  v_slug         text;
  v_jobid        bigint;
  v_ext          boolean := false;
  v_vec          jsonb   := '{}'::jsonb;
  v_names        text[]  := '{}';
  v_txt          text;
  v_bool         boolean;
  v_class        text;
  v_state        text;
  v_decided      text;
  v_reachable    boolean := false;
  v_unauth       boolean := false;
  v_unexpected   boolean := false;
  v_external     text;
  -- a deployed 410 responder: it answers HTTP and executes nothing
  v_retired_stub boolean := false;
begin
  select * into c from public.phase_c_component where component_id = p_component_id;
  if not found then
    return jsonb_build_object('component_id', p_component_id, 'derived_classification','UNDERIVABLE',
      'why','no row in phase_c_component with this id');
  end if;

  -- ---- resolve the physical object -------------------------------------------------------
  if c.component_type = 'database_function' then
    select p.oid into v_oid
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = split_part(c.source_path_or_db_object,'.',1)
       and p.proname = split_part(c.source_path_or_db_object,'.',2)
       -- the registry writes the signature without DEFAULT clauses; strip them to compare
       and c.component_id = 'dbfn:' || p.proname || '(' ||
             regexp_replace(pg_get_function_arguments(p.oid),
                            ' DEFAULT .*?(?=(, [a-zA-Z_"]+ )|$)', '', 'g') || ')'
     limit 1;
  elsif c.component_type = 'edge_function' then
    v_slug := regexp_replace(c.component_id, '^edge:', '');
  elsif c.component_type = 'cron_job' then
    begin
      v_jobid := (regexp_replace(c.source_path_or_db_object, '^cron\.job/', ''))::bigint;
    exception when others then v_jobid := null; end;
  end if;

  if c.component_type not in ('database_function','edge_function','cron_job')
     or (c.component_type = 'database_function' and v_oid is null)
     or (c.component_type = 'cron_job' and v_jobid is null) then
    return jsonb_build_object(
      'component_id', c.component_id, 'component_type', c.component_type,
      'extension_owned', false, 'vectors', '{}'::jsonb,
      'reachable', null, 'reachable_unauthenticated', null, 'unexpectedly_active', null,
      'derived_classification','UNDERIVABLE', 'derived_activation_state', null,
      'decided_by','no measurable object: this component type carries no catalogue, platform or '
                 ||'repository vector that this derivation can read');
  end if;

  -- ---- extension-owned objects are not QuotesDone components ------------------------------
  if v_oid is not null then
    select true into v_ext from pg_depend d
     where d.classid = 'pg_proc'::regclass and d.objid = v_oid and d.deptype = 'e' limit 1;
    v_ext := coalesce(v_ext, false);
  end if;
  if v_ext then
    select e.extname into v_txt
      from pg_depend d join pg_extension e on e.oid = d.refobjid
     where d.classid = 'pg_proc'::regclass and d.objid = v_oid and d.deptype = 'e' limit 1;
    return jsonb_build_object(
      'component_id', c.component_id, 'component_type', c.component_type,
      'extension_owned', true, 'vectors', '{}'::jsonb,
      'reachable', null, 'reachable_unauthenticated', null, 'unexpectedly_active', false,
      'derived_classification','EXTENSION_OWNED_EXCLUDED', 'derived_activation_state', null,
      'decided_by', format('pg_depend deptype ''e'' on extension %L — an extension internal, never '
                        || 'a QuotesDone component; excluded from the deferred population', v_txt));
  end if;

  -- ---- vector: HTTP deployment + verify_jwt (probe) ---------------------------------------
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'http_deployed';
  if v_bool is not null then
    v_vec := v_vec || jsonb_build_object('http_deployed', jsonb_build_object('present', v_bool, 'evidence', v_txt));
    if v_bool then v_names := v_names || 'http_deployed'::text; end if;
  end if;
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'http_verify_jwt';
  if v_bool is not null then
    v_vec := v_vec || jsonb_build_object('http_verify_jwt', jsonb_build_object('present', v_bool, 'evidence', v_txt));
  end if;

  -- ---- vector: in-function authorisation, and the retired 410 stub (probe) ----------------
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'in_function_auth';
  if v_bool is not null then
    v_vec := v_vec || jsonb_build_object('in_function_auth', jsonb_build_object('present', v_bool, 'evidence', v_txt));
  end if;
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'retired_stub';
  v_retired_stub := coalesce(v_bool, false);
  if v_bool is not null then
    v_vec := v_vec || jsonb_build_object('retired_stub', jsonb_build_object('present', v_bool, 'evidence', v_txt));
  end if;

  -- ---- vector: RPC grants. has_function_privilege, NOT the grant statement -----------------
  -- A `revoke execute from anon` is a silent no-op while the grant is held through PUBLIC, so the
  -- privilege check is the only answer that means anything. The PUBLIC leg is reported separately
  -- because it changes what the repair has to be.
  if v_oid is not null then
    v_bool := has_function_privilege('anon', v_oid, 'EXECUTE');
    v_vec := v_vec || jsonb_build_object('rpc_anon', jsonb_build_object('present', v_bool,
      'evidence', format('has_function_privilege(''anon'', %s, ''EXECUTE'') = %s; proacl = %s',
        v_oid::regprocedure, v_bool, coalesce((select proacl::text from pg_proc where oid = v_oid),'null (owner default: PUBLIC holds EXECUTE)'))));
    if v_bool then v_names := v_names || 'rpc_anon'::text; end if;

    v_bool := has_function_privilege('authenticated', v_oid, 'EXECUTE');
    v_vec := v_vec || jsonb_build_object('rpc_authenticated', jsonb_build_object('present', v_bool,
      'evidence', format('has_function_privilege(''authenticated'', %s, ''EXECUTE'') = %s', v_oid::regprocedure, v_bool)));
    if v_bool then v_names := v_names || 'rpc_authenticated'::text; end if;

    select coalesce(bool_or(a.grantee = 0 and a.privilege_type = 'EXECUTE'), false)
      into v_bool
      from pg_proc p,
           lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
     where p.oid = v_oid;
    v_bool := coalesce(v_bool, false);
    v_vec := v_vec || jsonb_build_object('rpc_public', jsonb_build_object('present', v_bool,
      'evidence', case when v_bool
        then 'PUBLIC holds EXECUTE (aclitem grantee 0): a REVOKE FROM anon on this function is a silent no-op'
        else 'PUBLIC does not hold EXECUTE' end));
    if v_bool then v_names := v_names || 'rpc_public'::text; end if;

    -- ---- vector: auth hook. An EXPLICIT grant to supabase_auth_admin, not one inherited -----
    -- through PUBLIC, which every PUBLIC-executable function would otherwise register as a hook.
    select coalesce(bool_or(a.grantee = (select r.oid from pg_roles r where r.rolname = 'supabase_auth_admin')
                            and a.privilege_type = 'EXECUTE'), false)
      into v_bool
      from pg_proc p, lateral aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
     where p.oid = v_oid;
    v_bool := coalesce(v_bool, false);
    v_vec := v_vec || jsonb_build_object('auth_hook', jsonb_build_object('present', v_bool,
      'evidence', case when v_bool
        then 'explicit GRANT EXECUTE to supabase_auth_admin in proacl (not inherited through PUBLIC) '
             || '— the GoTrue auth service can call this'
        else 'no explicit grant to supabase_auth_admin' end));
    if v_bool then v_names := v_names || 'auth_hook'::text; end if;

    -- ---- vector: internal callers in pg_proc.prosrc -----------------------------------------
    select string_agg(cn.nspname||'.'||cp.proname, ', ' order by cp.proname)
      into v_txt
      from pg_proc cp join pg_namespace cn on cn.oid = cp.pronamespace
     where cp.oid <> v_oid
       and cn.nspname not in ('pg_catalog','information_schema')
       and not exists (select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=cp.oid and d.deptype='e')
       -- cheap substring test first; the anchored regex only runs on the handful that survive it
       and strpos(cp.prosrc, (select proname from pg_proc where oid = v_oid)) > 0
       and cp.prosrc ~ ('\y' || (select proname from pg_proc where oid = v_oid) || '\s*\(');
    v_bool := v_txt is not null;
    v_vec := v_vec || jsonb_build_object('internal_caller', jsonb_build_object('present', v_bool,
      'evidence', coalesce('pg_proc.prosrc references it in: '||left(v_txt, 400),
                           'no other non-extension routine names it in pg_proc.prosrc')));
    if v_bool then v_names := v_names || 'internal_caller'::text; end if;

    -- ---- vector: row triggers ---------------------------------------------------------------
    select string_agg(t.tgname, ', ' order by t.tgname) into v_txt
      from pg_trigger t where t.tgfoid = v_oid and not t.tgisinternal;
    v_bool := v_txt is not null;
    v_vec := v_vec || jsonb_build_object('row_trigger', jsonb_build_object('present', v_bool,
      'evidence', coalesce('pg_trigger: '||v_txt, 'no row trigger executes this function')));
    if v_bool then v_names := v_names || 'row_trigger'::text; end if;

    -- ---- vector: EVENT triggers. The vector that missed fn_enforce_rls_on_new_tables --------
    select string_agg(format('%s on %s (evtenabled=%s)', t.evtname, t.evtevent, t.evtenabled), ', ' order by t.evtname)
      into v_txt
      from pg_event_trigger t where t.evtfoid = v_oid and t.evtenabled <> 'D';
    v_bool := v_txt is not null;
    v_vec := v_vec || jsonb_build_object('event_trigger', jsonb_build_object('present', v_bool,
      'evidence', coalesce('pg_event_trigger, ENABLED: '||v_txt,
                           'no enabled event trigger executes this function')));
    if v_bool then v_names := v_names || 'event_trigger'::text; end if;

    -- ---- vector: views and matviews that compile the function in ----------------------------
    -- Through pg_depend on the view's rewrite rule, not a regex over pg_get_viewdef: the dependency
    -- is what the planner itself recorded, so it cannot miss a call and cannot invent one from a
    -- name that merely appears in a comment or a column alias. It is also ~100x cheaper, which
    -- matters when the invariant calls this function once per component.
    select string_agg(distinct cn.nspname||'.'||cl.relname||
                      ' ('||case cl.relkind when 'm' then 'matview' else 'view' end||')', ', ')
      into v_txt
      from pg_depend d
      join pg_rewrite rw on rw.oid = d.objid
      join pg_class cl   on cl.oid = rw.ev_class
      join pg_namespace cn on cn.oid = cl.relnamespace
     where d.refclassid = 'pg_proc'::regclass and d.refobjid = v_oid
       and d.classid = 'pg_rewrite'::regclass
       and cl.relkind in ('v','m');
    v_bool := v_txt is not null;
    v_vec := v_vec || jsonb_build_object('compiled_into_view', jsonb_build_object('present', v_bool,
      'evidence', coalesce('runs on every SELECT of: '||v_txt, 'no view or matview compiles it in')));
    if v_bool then v_names := v_names || 'compiled_into_view'::text; end if;

    -- ---- vector: queue consumers -------------------------------------------------------------
    select string_agg(qn.nspname||'.'||q.proname, ', ' order by q.proname) into v_txt
      from pg_proc q join pg_namespace qn on qn.oid = q.pronamespace
     where qn.nspname in ('pgmq','net')
       and q.prosrc ~ ('\y' || (select proname from pg_proc where oid = v_oid) || '\s*\(');
    v_bool := v_txt is not null;
    v_vec := v_vec || jsonb_build_object('queue_consumer', jsonb_build_object('present', v_bool,
      'evidence', coalesce('named by queue machinery: '||v_txt, 'no pgmq/net routine names it')));
    if v_bool then v_names := v_names || 'queue_consumer'::text; end if;
  end if;

  -- ---- vector: cron, ACTIVE and INACTIVE reported separately -------------------------------
  -- An inactive job is a disabled component; an active one is a running component that a label
  -- calling it inactive cannot stop.
  if v_jobid is not null then
    select format('cron.job %s %L schedule %L active=%s; %s runs, last %s',
                  j.jobid, j.jobname, j.schedule, j.active,
                  (select count(*) from cron.job_run_details r where r.jobid = j.jobid),
                  coalesce((select max(r.start_time)::text from cron.job_run_details r where r.jobid = j.jobid),'never')),
           j.active
      into v_txt, v_bool
      from cron.job j where j.jobid = v_jobid;
    v_vec := v_vec || jsonb_build_object('cron_active', jsonb_build_object('present', coalesce(v_bool,false), 'evidence', coalesce(v_txt,'no cron.job row with this jobid')));
    v_vec := v_vec || jsonb_build_object('cron_registered', jsonb_build_object('present', v_txt is not null, 'evidence', coalesce(v_txt,'no cron.job row with this jobid')));
    if coalesce(v_bool,false) then v_names := v_names || 'cron_active'::text; end if;
  end if;

  -- ---- vector: webhook / net.http_post targeting this component ----------------------------
  if v_slug is not null then
    select string_agg(x.src, ', ') into v_txt from (
      select 'db routine '||n.nspname||'.'||p.proname src
        from pg_proc p join pg_namespace n on n.oid = p.pronamespace
       where n.nspname not in ('pg_catalog','information_schema')
         and strpos(p.prosrc, 'functions/v1/'||v_slug) > 0
         and p.prosrc ~ ('functions/v1/'||v_slug||'\y')
      union all
      select 'cron.job '||j.jobid||' ('||coalesce(j.jobname,'')||', active='||j.active||')'
        from cron.job j where j.command ~ ('functions/v1/'||v_slug||'\y')
    ) x;
  elsif v_oid is not null then
    select string_agg('trigger '||t.tgname||' -> '||tp.proname, ', ') into v_txt
      from pg_trigger t join pg_proc tp on tp.oid = t.tgfoid
     where not t.tgisinternal and tp.prosrc ~ 'net\.http_post'
       and tp.prosrc ~ ('\y' || (select proname from pg_proc where oid = v_oid) || '\y');
  else
    v_txt := null;
  end if;
  v_bool := v_txt is not null;
  v_vec := v_vec || jsonb_build_object('webhook_caller', jsonb_build_object('present', v_bool,
    'evidence', coalesce('net.http_post / cron HTTP caller: '||v_txt,
                         'no database routine, trigger or cron command posts to this component')));
  if v_bool then v_names := v_names || 'webhook_caller'::text; end if;

  -- ---- vector: frontend callers in src/** (probe) ------------------------------------------
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'frontend_caller';
  v_vec := v_vec || jsonb_build_object('frontend_caller', jsonb_build_object('present', coalesce(v_bool,false),
    'evidence', coalesce(v_txt, 'not swept: no src/** measurement recorded for this component')));
  if coalesce(v_bool,false) then v_names := v_names || 'frontend_caller'::text; end if;

  -- ---- vector: SCRIPT callers in scripts/** (probe) — the omitted one -----------------------
  select p.present, p.evidence into v_bool, v_txt
    from public.phase_c_component_probe p
   where p.component_id = c.component_id and p.vector = 'script_caller';
  v_vec := v_vec || jsonb_build_object('script_caller', jsonb_build_object('present', coalesce(v_bool,false),
    'evidence', coalesce(v_txt, 'no invocation of this component found in scripts/**')));
  if coalesce(v_bool,false) then v_names := v_names || 'script_caller'::text; end if;

  -- ---- conclusions -------------------------------------------------------------------------
  -- REACHABLE: some caller, some grant or some schedule can put control into this component.
  -- A retired 410 stub answers HTTP but executes nothing, so it is deployed-and-disabled, not
  -- reachable.
  -- A deployed HTTP endpoint that answers is reachable even when it demands a credential first:
  -- "access-controlled" is a description of HOW it is reached, not a claim that it is not. Only the
  -- 410 stubs are genuinely not reachable, because there is nothing behind the door.
  v_reachable := (not v_retired_stub) and (
       'http_deployed'      = any(v_names)
    or 'rpc_anon'           = any(v_names)
    or 'rpc_authenticated'  = any(v_names)
    or 'auth_hook'          = any(v_names)
    or 'internal_caller'    = any(v_names)
    or 'row_trigger'        = any(v_names)
    or 'event_trigger'      = any(v_names)
    or 'compiled_into_view' = any(v_names)
    or 'queue_consumer'     = any(v_names)
    or 'cron_active'        = any(v_names)
    or 'webhook_caller'     = any(v_names)
    or 'frontend_caller'    = any(v_names)
    or 'script_caller'      = any(v_names));

  -- REACHABLE UNAUTHENTICATED: a caller holding no credential at all gets in.
  v_unauth := (
       'rpc_anon' = any(v_names)
    or ('http_deployed' = any(v_names)
        and not coalesce((v_vec->'http_verify_jwt'->>'present')::boolean, true)
        and not coalesce((v_vec->'in_function_auth'->>'present')::boolean, false)));

  -- UNEXPECTEDLY ACTIVE: something is executing it now, without anyone deciding to call it.
  v_unexpected := 'event_trigger' = any(v_names)
               or 'row_trigger'   = any(v_names)
               or 'cron_active'   = any(v_names)
               or 'compiled_into_view' = any(v_names);

  -- The recorded vocabulary is 'no' / 'unauthenticated_only' / 'yes'. A deployed HTTP surface is an
  -- external entry even when every caller must present a credential — 'yes' means "an outside
  -- caller can address this", not "an outside caller can do as they like".
  v_external := case
    when v_unauth then 'unauthenticated_only'
    when 'http_deployed' = any(v_names) or 'rpc_authenticated' = any(v_names) then 'yes'
    else 'no' end;

  -- ---- the classification the evidence supports, most consequential vector first ------------
  -- The 410 stub is tested first. Five of the six answer an anonymous caller and would otherwise be
  -- filed ACTIVE_PUBLIC_ENTRY on the strength of a verify_jwt setting, which would be the same
  -- mistake in the opposite direction: the deployment is reachable, the component is not.
  if v_retired_stub then
    v_class := 'INTENTIONALLY_RETIRED'; v_state := 'inactive';
    v_decided := 'retired_stub: ' || (v_vec->'retired_stub'->>'evidence')
              || ' — deployed and addressable, executes nothing';
  elsif 'event_trigger' = any(v_names) then
    v_class := 'ACTIVE_EVENT_TRIGGER'; v_state := 'active';
    v_decided := 'event_trigger: ' || (v_vec->'event_trigger'->>'evidence');
  elsif 'cron_active' = any(v_names) then
    v_class := 'ACTIVE_CRON'; v_state := 'active';
    v_decided := 'cron_active: ' || (v_vec->'cron_active'->>'evidence');
  elsif v_unauth then
    v_class := 'ACTIVE_PUBLIC_ENTRY'; v_state := 'active';
    v_decided := case when 'rpc_anon' = any(v_names)
                      then 'rpc_anon: ' || (v_vec->'rpc_anon'->>'evidence')
                      else 'http_deployed with verify_jwt=false and no in-function authorisation: '
                           || (v_vec->'in_function_auth'->>'evidence') end;
  elsif 'auth_hook' = any(v_names) then
    v_class := 'ACTIVE_AUTH_HOOK'; v_state := 'active';
    v_decided := 'auth_hook: ' || (v_vec->'auth_hook'->>'evidence');
  elsif 'webhook_caller' = any(v_names) then
    v_class := 'ACTIVE_WEBHOOK_ENTRY'; v_state := 'active';
    v_decided := 'webhook_caller: ' || (v_vec->'webhook_caller'->>'evidence');
  elsif 'frontend_caller' = any(v_names) then
    v_class := 'ACTIVE_FRONTEND_ENTRY'; v_state := 'active';
    v_decided := 'frontend_caller: ' || (v_vec->'frontend_caller'->>'evidence');
  elsif 'compiled_into_view' = any(v_names) or 'internal_caller' = any(v_names)
     or 'row_trigger' = any(v_names) or 'queue_consumer' = any(v_names) then
    v_class := 'ACTIVE_INTERNAL_CALLER'; v_state := 'active';
    v_decided := coalesce('compiled_into_view: '||(v_vec->'compiled_into_view'->>'evidence'),'')
              || case when 'internal_caller' = any(v_names) then ' | internal_caller: '||(v_vec->'internal_caller'->>'evidence') else '' end
              || case when 'row_trigger' = any(v_names) then ' | row_trigger: '||(v_vec->'row_trigger'->>'evidence') else '' end
              || case when 'queue_consumer' = any(v_names) then ' | queue_consumer: '||(v_vec->'queue_consumer'->>'evidence') else '' end;
  elsif 'script_caller' = any(v_names) then
    v_class := 'ACTIVE_SCRIPT_ENTRY'; v_state := 'active';
    v_decided := 'script_caller: ' || (v_vec->'script_caller'->>'evidence');
  elsif 'http_deployed' = any(v_names)
        and (coalesce((v_vec->'http_verify_jwt'->>'present')::boolean,false)
             or coalesce((v_vec->'in_function_auth'->>'present')::boolean,false)) then
    v_class := 'ACCESS_CONTROLLED_NO_CALLER'; v_state := 'deployed';
    v_decided := 'deployed and callable, but every caller must present a credential: '
              || coalesce((v_vec->'in_function_auth'->>'evidence'), (v_vec->'http_verify_jwt'->>'evidence'))
              || ' | no frontend, script, cron or webhook caller found';
  elsif 'rpc_authenticated' = any(v_names) then
    v_class := 'ACCESS_CONTROLLED_NO_CALLER'; v_state := 'deployed';
    v_decided := 'rpc_authenticated: ' || (v_vec->'rpc_authenticated'->>'evidence') || ' | anon cannot execute it';
  else
    -- No vector at all. This is the absence of a finding, not a finding: it says the derivation
    -- could not get in, never that the component was never built. A registered-but-switched-off
    -- cron job says so in its own words rather than being described as "no cron job".
    v_class := 'DEFERRED_RUNTIME_IMPLEMENTATION'; v_state := 'inactive';
    v_decided := 'no reachability vector: no grant to anon or authenticated, no internal caller, no '
              || 'row or event trigger, no active schedule, no view, no queue consumer, no webhook, '
              || 'no caller in src/** or scripts/**'
              || case when coalesce((v_vec->'cron_registered'->>'present')::boolean,false)
                      then ' | schedule is registered and SWITCHED OFF: '
                           || (v_vec->'cron_active'->>'evidence')
                      else '' end;
  end if;

  return jsonb_build_object(
    'component_id',              c.component_id,
    'component_type',            c.component_type,
    'object',                    c.source_path_or_db_object,
    'mutates_state',             c.mutates_state,
    'extension_owned',           false,
    'vectors',                   v_vec,
    'vectors_present',           to_jsonb(v_names),
    'reachable',                 v_reachable,
    'reachable_unauthenticated', v_unauth,
    'unexpectedly_active',       v_unexpected,
    'derived_classification',    v_class,
    'derived_activation_state',  v_state,
    'derived_external_entry',    v_external,
    'decided_by',                v_decided);
end

fn_phase_c_component_classification_guar:
declare
  d           jsonb;
  v_derived   text;
  v_reachable boolean;
  v_unexpect  boolean;
begin
  d := public.fn_kernel_component_reachability(new.component_id);
  v_derived := d->>'derived_classification';

  if v_derived in ('UNDERIVABLE','EXTENSION_OWNED_EXCLUDED') then
    return new;
  end if;

  v_reachable := (d->>'reachable')::boolean;
  v_unexpect  := (d->>'unexpectedly_active')::boolean;

  if new.classification in ('DEFERRED_RUNTIME_IMPLEMENTATION','INACTIVE_HISTORICAL',
                            'INTENTIONALLY_INACTIVE','HISTORICAL_ONLY','NO_CALLER_UNCLASSIFIED')
     and v_reachable then
    -- RAISE has no %L. It is % and a stray literal L, which is how the sibling event-binding guard
    -- ends up printing "CONNECTEDL". Quotes are written into the format string instead.
    raise exception
      'phase_c_component %: classification "%" says this component has no way in, and it has one. '
      'The derivation reaches it via %. Derived classification is "%". '
      'Wire the missing leg, or record what is true; do not relabel the row.',
      new.component_id, new.classification, d->>'decided_by', v_derived
      using errcode = '23514';
  end if;

  if new.classification like 'ACTIVE\_%' and not v_reachable then
    raise exception
      'phase_c_component %: classification "%" claims a live entry point and the derivation finds '
      'none — %. Derived classification is "%". '
      'Wire the missing leg, or record what is true; do not relabel the row.',
      new.component_id, new.classification, d->>'decided_by', v_derived
      using errcode = '23514';
  end if;

  if new.activation_state = 'inactive' and v_unexpect then
    raise exception
      'phase_c_component %: activation_state ''inactive'' cannot stop it — %. Derived state is "%". '
      'Wire the missing leg, or record what is true; do not relabel the row.',
      new.component_id, d->>'decided_by', d->>'derived_activation_state'
      using errcode = '23514';
  end if;

  return new;
end

fn_kernel_routine_ownership:
declare
  v_want_sch  text;
  v_want_name text;
  v_args      text := coalesce(p_identity_args, '');
  v_matches   int;
  v_sch       text;
  v_owner     text;
  v_ext       text;
  v_lang      text;
  v_src       text;
  v_file      text;
  v_class     text;
  v_rule      text;
  v_evidence  text;
  -- The platform's own roles. Membership is read from pg_proc.proowner, which is a catalogue fact,
  -- not from the routine's name.
  c_platform_roles constant text[] := array[
    'supabase_admin', 'supabase_auth_admin', 'supabase_storage_admin', 'supabase_functions_admin',
    'supabase_realtime_admin', 'authenticator', 'pgbouncer', 'pgsodium_keyholder'];
  -- The managed product schemas. `extensions` is deliberately NOT here — see R3.
  c_platform_schemas constant text[] := array[
    'auth', 'storage', 'realtime', 'vault', 'graphql', 'graphql_public', 'pgbouncer', 'net',
    'cron', 'pgsodium', 'supabase_functions', 'supabase_migrations', '_realtime', '_analytics',
    '_supavisor'];
begin
  if position('.' in coalesce(p_proname, '')) > 0 then
    v_want_sch  := split_part(p_proname, '.', 1);
    v_want_name := split_part(p_proname, '.', 2);
  else
    v_want_sch  := null;
    v_want_name := p_proname;
  end if;

  select count(*) into v_matches
    from pg_proc p
    join pg_namespace ns on ns.oid = p.pronamespace
   where p.proname = v_want_name
     and pg_get_function_identity_arguments(p.oid) = v_args
     and ns.nspname not in ('pg_catalog', 'information_schema', 'pg_toast')
     and (v_want_sch is null or ns.nspname = v_want_sch);

  if v_matches = 0 then
    -- Not a verdict in the allowed class list, so the guard refuses any row claiming ownership of
    -- a routine that is not there. A ledger of code that does not exist is not a ledger.
    return jsonb_build_object(
      'ownership_class', 'ABSENT_FROM_CATALOG',
      'rule', 'R0_NOT_IN_PG_PROC',
      'evidence', format('no pg_proc entry for %s(%s) in any non-system schema', p_proname, v_args),
      'schema_name', null, 'identity_args', v_args);
  end if;
  if v_matches > 1 then
    return jsonb_build_object(
      'ownership_class', 'AMBIGUOUS_WITHOUT_SCHEMA',
      'rule', 'R0B_MORE_THAN_ONE_SCHEMA_MATCHES',
      'evidence', format('%s routines named %s(%s) — qualify the name with its schema',
                         v_matches, p_proname, v_args),
      'schema_name', null, 'identity_args', v_args);
  end if;

  -- Exactly one match. SELECT INTO here cannot leave the targets null-by-accident: the count above
  -- proved the row exists, and every column selected is NOT NULL in the catalogue except v_ext.
  select ns.nspname,
         pg_get_userbyid(p.proowner),
         (select e.extname
            from pg_depend d
            join pg_extension e on e.oid = d.refobjid
           where d.objid = p.oid and d.deptype = 'e'
           limit 1),
         l.lanname
    into v_sch, v_owner, v_ext, v_lang
    from pg_proc p
    join pg_namespace ns on ns.oid = p.pronamespace
    join pg_language l on l.oid = p.prolang
   where p.proname = v_want_name
     and pg_get_function_identity_arguments(p.oid) = v_args
     and ns.nspname not in ('pg_catalog', 'information_schema', 'pg_toast')
     and (v_want_sch is null or ns.nspname = v_want_sch);

  v_src := p_source_kind;
  if v_src is null then
    select k.source_kind, k.source_file
      into v_src, v_file
      from public.kernel_routine_ownership k
     where k.schema_name = v_sch
       and k.routine_name = v_want_name
       and k.identity_args = v_args;
    -- No row: SELECT INTO leaves both null, which is the correct reading — nothing has been
    -- recorded about this routine's repository provenance.
  end if;

  if v_ext is not null then
    v_class := 'EXTENSION_MANAGED';
    v_rule  := 'R1_PG_DEPEND_EXTENSION';
    v_evidence := format('pg_depend deptype=e binds %s.%s to extension %s', v_sch, v_want_name, v_ext);
  elsif v_owner = any (c_platform_roles) and v_sch = any (c_platform_schemas) then
    v_class := 'SUPABASE_MANAGED';
    v_rule  := 'R2_PLATFORM_ROLE_IN_PLATFORM_SCHEMA';
    v_evidence := format('proowner=%s in managed schema %s', v_owner, v_sch);
  elsif v_owner = any (c_platform_roles) and v_sch = 'extensions' then
    v_class := 'PLATFORM_INTERNAL';
    v_rule  := 'R3_PLATFORM_ROLE_IN_EXTENSIONS_SCHEMA';
    v_evidence := format('proowner=%s in schema extensions and NO extension owns it '
                         '(no pg_depend deptype=e) — platform bootstrap glue', v_owner);
  elsif v_owner = any (c_platform_roles) then
    v_class := 'SUPABASE_MANAGED';
    v_rule  := 'R2B_PLATFORM_ROLE';
    v_evidence := format('proowner=%s (a platform role) in schema %s', v_owner, v_sch);
  elsif v_src = 'MANIFEST' then
    v_class := 'QUOTESDONE_APPLICATION';
    v_rule  := 'R4_MANIFEST_DEFINES_IT';
    v_evidence := format('owner=%s, no extension, and a scripts/sql/MANIFEST.txt file defines it%s',
                         v_owner, coalesce(': ' || v_file, ''));
  elsif v_src = 'TRACKED_SQL_OUTSIDE_MANIFEST' then
    v_class := 'HISTORICAL_APPLICATION';
    v_rule  := 'R5_TRACKED_SQL_OUTSIDE_MANIFEST';
    v_evidence := format('owner=%s, no MANIFEST file defines it, tracked SQL elsewhere does%s',
                         v_owner, coalesce(': ' || v_file, ''));
  elsif v_src = 'NONE' then
    v_class := 'INTENTIONALLY_UNTRACKED_WITH_JUSTIFICATION';
    v_rule  := 'R6_NO_SOURCE_ANYWHERE_JUSTIFIED';
    v_evidence := format('owner=%s, lang=%s, and no tracked *.sql in the repository creates it',
                         v_owner, v_lang);
  else
    -- Application-owned and nothing said where it came from. Not a class; the guard refuses it.
    v_class := 'NO_PROVENANCE_RECORDED';
    v_rule  := 'R6_NO_PROVENANCE_RECORDED';
    v_evidence := format('owner=%s in schema %s is not platform-owned, and source_kind is %s — '
                         'the repository has not been asked where this came from',
                         v_owner, v_sch, coalesce(v_src, 'unrecorded'));
  end if;

  return jsonb_build_object(
    'ownership_class', v_class,
    'rule', v_rule,
    'evidence', v_evidence,
    'schema_name', v_sch,
    'identity_args', v_args,
    'owner', v_owner,
    'extension', v_ext);
end

a00_kernel_routine_ownership_guard:
declare
  v_d       jsonb;
  v_derived text;
begin
  v_d := public.fn_kernel_routine_ownership(
           NEW.schema_name || '.' || NEW.routine_name, NEW.identity_args, NEW.source_kind);
  v_derived := v_d->>'ownership_class';

  if v_derived is distinct from NEW.ownership_class then
    raise exception
      'kernel_routine_ownership refuses %.%(%): recorded class %, but the facts support %. Rule %. %',
      NEW.schema_name, NEW.routine_name, NEW.identity_args, NEW.ownership_class, v_derived,
      v_d->>'rule', v_d->>'evidence'
      using errcode = '23514';
  end if;

  if NEW.classified_by_rule is distinct from (v_d->>'rule') then
    raise exception
      'kernel_routine_ownership refuses %.%(%): recorded rule % is not the rule that fired (%). %',
      NEW.schema_name, NEW.routine_name, NEW.identity_args, NEW.classified_by_rule,
      v_d->>'rule', v_d->>'evidence'
      using errcode = '23514';
  end if;

  return null;
end

fn_kernel_workflow_run_trace_guard:
declare v_state text;
begin
  if new.state is not distinct from old.state then return new; end if;

  -- No trace yet is only legal while the run is still being built inside fn_kernel_workflow_start,
  -- which writes the run row and its trace in the same statement sequence. Any later state change
  -- without a trace is the defect this guard exists for.
  if new.trace_id is null then
    raise exception
      'phase_c_workflow_run %: state % -> % with no trace', new.run_id, old.state, new.state
      using errcode = '23514',
            hint = 'fn_kernel_workflow_start writes the run trace. Nothing else may move a run.';
  end if;

  -- A SEALED trace is never edited in place; fn_phase_c_trace_advance supersedes it with a new row
  -- and links the two. The append-only guard refuses an edit and it is right to.
  new.trace_id := public.fn_phase_c_trace_advance(
    new.trace_id, new.state,
    new.state in ('completed','cancelled','superseded','failed'),
    jsonb_build_object(
      'state_before', old.state,
      'subject_kind','workflow_run', 'subject_ref', new.run_id::text, 'run_id', new.run_id,
      'command_id', new.command_id));

  select t.state_after into v_state from public.phase_c_trace t where t.trace_id = new.trace_id;
  if v_state is distinct from new.state then
    raise exception
      'phase_c_workflow_run %: the run says % and its trace says %', new.run_id, new.state, v_state
      using errcode = '23514',
            hint = 'The trace must be advanced in the same transaction as the state it records.';
  end if;
  return new;
end

fn_kernel_step_successor:
declare
  s public.phase_b_workflow_step%rowtype;
  n public.phase_b_workflow_step%rowtype;
  v_this text;
  v_next text;
  v_edge text;
begin
  select * into s from public.phase_b_workflow_step where step_id = p_step_id;
  if not found then
    kind := 'unknown_step';
    reason := format('%L is not a step in the frozen Phase B registry — fail closed', p_step_id);
    return next; return;
  end if;

  success_state := s.success_workflow_state;
  failure_state := s.failure_workflow_state;
  select role_id into v_this from public.fn_phase_c_resolve_actor(s.accountable_role_id);
  this_owner_role_id := v_this;

  -- Terminality: the sentinel AND the flag. Never an empty join against phase_b_handoff.
  if s.next_step_if_pass = 'WORKFLOW_COMPLETE' or s.is_closure_step then
    if not (s.next_step_if_pass = 'WORKFLOW_COMPLETE' and s.is_closure_step) then
      kind := 'closure_flag_disagrees';
      reason := format('step %s: next_step_if_pass=%L but is_closure_step=%s — the two statements '
                    || 'of terminality disagree and neither may be preferred silently',
                       s.step_id, s.next_step_if_pass, s.is_closure_step);
      return next; return;
    end if;
    kind := 'closure';
    reason := format('step %s is the declared closure step of %s', s.step_id, s.workflow_id);
    return next; return;
  end if;

  select * into n from public.phase_b_workflow_step where step_id = s.next_step_if_pass;
  if not found then
    kind := 'successor_not_a_step'; next_step_id := s.next_step_if_pass;
    reason := format('step %s declares successor %L, which is not a step in the registry',
                     s.step_id, s.next_step_if_pass);
    return next; return;
  end if;
  next_step_id := n.step_id;

  select role_id into v_next from public.fn_phase_c_resolve_actor(n.accountable_role_id);
  next_owner_role_id := v_next;
  if v_next is null or not public.fn_phase_c_actor_may_own(v_next) then
    kind := 'successor_owner_unresolved';
    reason := format('step %s declares successor %s, whose accountable_role_id %L does not resolve '
                  || 'to an active canonical role (%s). A category overlay advises and may never '
                  || 'own a task, so no step run and no task may be opened for it.',
                     s.step_id, n.step_id, n.accountable_role_id,
                     coalesce((select r.reason from public.fn_phase_c_resolve_actor(n.accountable_role_id) r),
                              'no reason returned'));
    return next; return;
  end if;

  select h.handoff_id into v_edge from public.phase_b_handoff h
   where h.from_step_id = s.step_id and h.to_step_id = n.step_id;
  handoff_id := v_edge;

  if v_this is not null and v_next = v_this then
    if v_edge is not null then
      -- Both owners resolve to one identity yet a formal handoff is declared. 0 of 227 today.
      kind := 'cross_owner';
      reason := format('step %s -> %s: the registry declares handoff %s; it is honoured even '
                    || 'though both owners resolve to %L', s.step_id, n.step_id, v_edge, v_this);
      return next; return;
    end if;
    kind := 'same_owner';
    reason := format('step %s -> %s: owner stays %L, so no handoff is owed and none is invented',
                     s.step_id, n.step_id, v_this);
    return next; return;
  end if;

  if v_edge is null then
    kind := 'registry_gap_no_handoff';
    reason := format('step %s declares successor %s and accountability moves from %L to %L, but '
                  || 'phase_b_handoff declares no edge for it. A handoff nobody owes will not be '
                  || 'invented; this is a Phase B registry gap and is refused visibly.',
                     s.step_id, n.step_id, coalesce(v_this,'(unresolved)'), v_next);
    return next; return;
  end if;

  kind := 'cross_owner';
  reason := format('step %s -> %s via handoff %s: accountability moves from %L to %L',
                   s.step_id, n.step_id, v_edge, coalesce(v_this,'(unresolved)'), v_next);
  return next;
end

fn_kernel_open_step:
declare
  v_pd_dispatch jsonb := '{}'::jsonb;  -- D36
  s public.phase_b_workflow_step%rowtype;
  v_run       bigint := nullif(p_input->>'run_id','')::bigint;
  v_step      text   := nullif(btrim(coalesce(p_input->>'step_id','')), '');
  v_owner     text   := nullif(btrim(coalesce(p_input->>'owner_role_id','')), '');
  v_src_kind  text   := coalesce(nullif(p_input->>'source_kind',''), 'workflow_progression');
  v_src_ref   text   := coalesce(nullif(p_input->>'source_ref',''), 'kernel:step_engine');
  v_command   bigint := nullif(p_input->>'command_id','')::bigint;
  v_priority  text   := coalesce(nullif(p_input->>'priority',''), 'P2');
  v_object    text   := coalesce(nullif(p_input->>'business_object_id',''), '');
  v_in_hash   text   := coalesce(nullif(p_input->>'input_hash',''), '');
  v_reason    text   := coalesce(nullif(p_input->>'opened_because',''), '(no reason stated)');
  v_step_run  bigint;
  v_task      bigint;
  v_st_trace  bigint;
  v_tk_trace  bigint;
  v_tk_parent bigint;
  v_wf        text;
  v_idem      text;
begin
  if v_run is null or v_step is null or v_owner is null then
    raise exception 'fn_kernel_open_step: run_id, step_id and owner_role_id are all required (got %, %, %)',
      coalesce(v_run::text,'(null)'), coalesce(v_step,'(null)'), coalesce(v_owner,'(null)')
      using errcode = '22023';
  end if;

  select * into s from public.phase_b_workflow_step where step_id = v_step;
  if not found then
    raise exception 'fn_kernel_open_step: % is not in the frozen Phase B step registry — fail closed',
      v_step using errcode = '23503';
  end if;
  select workflow_id into v_wf from public.phase_c_workflow_run where run_id = v_run;
  if v_wf is null then
    raise exception 'fn_kernel_open_step: no workflow run %', v_run using errcode = '23503';
  end if;
  if v_wf is distinct from s.workflow_id then
    raise exception 'fn_kernel_open_step: run % is workflow % and step % belongs to % — refused',
      v_run, v_wf, v_step, s.workflow_id using errcode = '23514';
  end if;
  -- Owners are never defaulted. A step whose owner does not resolve is not opened.
  if not public.fn_phase_c_actor_may_own(v_owner) then
    raise exception 'fn_kernel_open_step: % does not resolve to an active canonical role, so step % is not opened',
      v_owner, v_step using errcode = '23514';
  end if;

  -- phase_c_step_run_live_uk is UNIQUE (run_id, step_id) WHERE state is not terminal, so a second
  -- live step run for the same step is refused by the index. Report it as the specific thing it is.
  if exists (select 1 from public.phase_c_workflow_step_run r
              where r.run_id = v_run and r.step_id = v_step
                and r.state not in ('completed','cancelled','failed','superseded','skipped')) then
    raise exception 'fn_kernel_open_step: run % already has a live step run for % — a second one would be a duplicate of work in flight',
      v_run, v_step using errcode = '23505';
  end if;

  v_idem := s.idempotency_scope || '|' || v_run || '|' || v_step || '|kernel';

  -- No trace_id on the insert: z90_phase_c_step_run_trace_subject mints TRACE-STEP AFTER INSERT
  -- and parents it to the run's root trace.
  insert into public.phase_c_workflow_step_run
    (run_id, step_id, accountable_role_id, reviewer_role_id, state, attempt_no,
     input_hash, output_hash, gates_evaluated, authority_result, idempotency_key)
  values (v_run, v_step, v_owner, coalesce(s.independent_reviewer_role_id,''), 'active', 1,
          v_in_hash, '', '[]'::jsonb, 'pending: the step has not been executed yet', v_idem)
  returning step_run_id into v_step_run;
  if v_step_run is null then
    raise exception 'fn_kernel_open_step: the step run insert produced no row for %', v_step
      using errcode = '23502';
  end if;

  select trace_id into v_st_trace from public.phase_c_workflow_step_run where step_run_id = v_step_run;
  if v_st_trace is null then
    raise exception 'fn_kernel_open_step: step run % has no trace', v_step_run using errcode = '23502';
  end if;

  -- EXACTLY ONE task, on the same deterministic key fn_kernel_workflow_start uses. That key is
  -- also what makes the legacy delivery fan-out a no-op rather than a duplicate.
  v_task := public.fn_phase_c_task_create(jsonb_build_object(
    'source_kind', v_src_kind, 'source_ref', v_src_ref,
    'command_id', v_command, 'run_id', v_run, 'workflow_id', s.workflow_id, 'step_id', v_step,
    'accountable_role_id', v_owner,
    'objective', format('%s (%s) for %s — opened because %s',
                        s.step_id, s.step_name, coalesce(nullif(v_object,''),'this run'), v_reason),
    'required_inputs', s.required_inputs,
    'requested_output', s.required_output,
    'acceptance_criteria', s.acceptance_criteria,
    'closure_criteria', s.closure_criteria,
    'priority', v_priority,
    'reviewer_required', (coalesce(s.independent_reviewer_role_id,'') <> ''),
    'reviewer_role_id', coalesce(s.independent_reviewer_role_id,''),
    'idempotency_key', 'run:' || v_run || ':step:' || v_step));
  if v_task is null then
    raise exception 'fn_kernel_open_step: no task was created for run % step %', v_run, v_step
      using errcode = '23502';
  end if;

  select trace_id into v_tk_trace from public.phase_c_task where task_id = v_task;
  select parent_trace_id into v_tk_parent from public.phase_c_trace where trace_id = v_tk_trace;
  if v_tk_trace is null or v_tk_parent is null then
    raise exception 'fn_kernel_open_step: task % has trace % with parent % — a task without its parented trace is refused',
      v_task, coalesce(v_tk_trace::text,'null'), coalesce(v_tk_parent::text,'null')
      using errcode = '23502';
  end if;

  -- ---- PHASE D DISPATCH (D36) ------------------------------------------------------------------
  -- The step is open, owned, tasked and traced. If the frozen registry binds a deterministic Phase D
  -- handler to it, this is where that handler runs — not in a harness, and not behind an endpoint
  -- nothing calls. fn_phase_d_dispatch_step never raises: a refusal is recorded in
  -- public.phase_d_dispatch, because a handler refusing five frames down must not roll back the
  -- business write that caused the step to open.
  v_pd_dispatch := public.fn_phase_d_dispatch_step(jsonb_build_object(
    'step_run_id', v_step_run, 'actor_role_id', v_owner,
    'opened_by_kind', v_src_kind, 'opened_by_ref', v_src_ref,
    'idempotency_key', v_idem, 'correlation_id', p_input->>'correlation_id'));

  return jsonb_build_object('step_run_id', v_step_run, 'task_id', v_task, 'step_id', v_step,
    'owner_role_id', v_owner, 'step_trace_id', v_st_trace, 'task_trace_id', v_tk_trace,
    'reviewer_required', (coalesce(s.independent_reviewer_role_id,'') <> ''),
    'reviewer_role_id', coalesce(s.independent_reviewer_role_id,''),
    'idempotency_key', v_idem);
end

fn_kernel_step_complete:
declare
  sr  public.phase_c_workflow_step_run%rowtype;
  r   public.phase_c_workflow_run%rowtype;
  s   public.phase_b_workflow_step%rowtype;
  t   public.phase_c_task%rowtype;
  h   public.phase_b_handoff%rowtype;
  v_step_run  bigint := nullif(p_input->>'step_run_id','')::bigint;
  v_actor_in  text   := nullif(btrim(coalesce(p_input->>'actor_role_id','')), '');
  v_outcome   text   := lower(nullif(btrim(coalesce(p_input->>'outcome','')), ''));
  v_idem      text   := nullif(btrim(coalesce(p_input->>'idempotency_key','')), '');
  v_reason    text   := coalesce(btrim(p_input->>'reason'), '');
  v_output    jsonb  := p_input->'output';
  v_priority  text   := coalesce(nullif(p_input->>'priority',''), 'P2');
  v_actor     text;
  v_kind      text;
  v_owner     text;
  v_authority text;
  v_delegated boolean := false;
  v_target_st text;                       -- the step run's target state
  v_run_state text;                       -- the run's target state
  v_out_hash  text := '';
  v_ev_ref    text;
  v_gates     jsonb := '[]'::jsonb;
  v_gate      record;
  -- Separate scalars per callee. One shared RECORD would carry the shape of whichever
  -- set-returning function last filled it, and reading a field the new shape does not have
  -- RAISES rather than returning null.
  v_out_ok    boolean; v_out_reason text;
  v_gate_ok   boolean; v_gate_reason text;
  v_hop       text;
  v_from      text;
  v_now       text;
  v_hops      text[];
  v_tr        jsonb;
  v_completion bigint;
  v_prior     jsonb;
  -- progression
  v_sk        text; v_next_step text; v_next_owner text; v_handoff_id text;
  v_succ_state text; v_fail_state text; v_this_owner text; v_sk_reason text;
  v_opened    jsonb;
  v_handoff_run bigint;
  v_ho_trace  bigint;
  v_blockers  jsonb := '[]'::jsonb;
  v_n         bigint;
  v_rules     jsonb;
  v_step_ev   text;
  v_wf_ev     text;
  v_outbox_step bigint;
  v_outbox_wf   bigint;
  v_corr      text; v_caus text; v_src text;
  v_created_steps int := 0; v_created_tasks int := 0; v_created_handoffs int := 0;
  v_created_events int := 0;
  v_result    jsonb;
begin
  -- ---- 0. a consumer may not re-enter the producer ----------------------------------------
  perform public.fn_kernel_assert_not_in_delivery('fn_kernel_step_complete');

  if v_step_run is null or v_actor_in is null or v_idem is null then
    raise exception 'fn_kernel_step_complete: step_run_id, actor_role_id and idempotency_key are all required (got %, %, %)',
      coalesce(v_step_run::text,'(null)'), coalesce(v_actor_in,'(null)'), coalesce(v_idem,'(null)')
      using errcode = '22023';
  end if;
  if v_outcome is null or v_outcome not in ('pass','fail','block') then
    raise exception 'fn_kernel_step_complete: outcome must be pass, fail or block, got %',
      coalesce(v_outcome,'(null)') using errcode = '22023';
  end if;
  if v_outcome in ('fail','block') and v_reason = '' then
    raise exception 'fn_kernel_step_complete: outcome % requires a stated reason. An unexplained failure is not a record of anything.',
      v_outcome using errcode = '23514';
  end if;

  -- ---- 1. IDEMPOTENCY, claimed before any work --------------------------------------------
  select c.result into v_prior from public.phase_c_step_completion c where c.idempotency_key = v_idem;
  if v_prior is not null then
    return v_prior || jsonb_build_object('replay', true);
  end if;

  -- ---- 2. LOCK: run, then step run, then task. Always this order. --------------------------
  select run_id into v_n from public.phase_c_workflow_step_run where step_run_id = v_step_run;
  if v_n is null then
    raise exception 'fn_kernel_step_complete: no step run % (k3_step_run_not_found)', v_step_run
      using errcode = '23503';
  end if;
  select * into r from public.phase_c_workflow_run where run_id = v_n for update;
  if not found then
    raise exception 'fn_kernel_step_complete: step run % names workflow run %, which does not exist',
      v_step_run, v_n using errcode = '23503';
  end if;
  select * into sr from public.phase_c_workflow_step_run where step_run_id = v_step_run for update;
  if not found then
    raise exception 'fn_kernel_step_complete: no step run % (k3_step_run_not_found)', v_step_run
      using errcode = '23503';
  end if;
  select * into t from public.phase_c_task
   where run_id = r.run_id and step_id = sr.step_id order by task_id limit 1 for update;
  if not found then
    raise exception 'fn_kernel_step_complete: run % step % has no task. The kernel creates exactly one task per step run; completing a step with no task would close work nobody was ever asked to do. (k3_task_missing)',
      r.run_id, sr.step_id using errcode = '23503';
  end if;

  select * into s from public.phase_b_workflow_step where step_id = sr.step_id;
  if not found then
    raise exception 'fn_kernel_step_complete: step % is not in the frozen Phase B registry — fail closed',
      sr.step_id using errcode = '23503';
  end if;

  -- ---- 3. VERIFY -----------------------------------------------------------------------------
  -- 3a. the run must be running. Every path in this engine leaves the run at 'active' before the
  --     next step is executed, so anything else means this call is out of order.
  if r.state <> 'active' then
    raise exception 'fn_kernel_step_complete: workflow run % is in state %, not active — a step cannot be completed against a run that is not running (k3_run_not_active)',
      r.run_id, r.state using errcode = '23514';
  end if;

  -- 3b. the step run must be in a state the FROZEN step model allows to reach the target.
  v_target_st := case v_outcome when 'pass' then 'completed'
                                when 'fail' then 'failed' else 'blocked' end;
  if not exists (select 1 from public.phase_b_step_transition x
                  where x.from_state = sr.state and x.to_state = v_target_st) then
    raise exception 'fn_kernel_step_complete: step run % is in state % and the frozen Phase B step model declares no transition % -> % (k3_step_state_invalid)',
      v_step_run, sr.state, sr.state, v_target_st using errcode = '23514';
  end if;

  -- 3c. the ACTOR resolves, is active and canonical.
  select kind, role_id into v_kind, v_actor from public.fn_phase_c_resolve_actor(v_actor_in);
  if v_actor is null or v_kind is distinct from 'canonical' then
    raise exception 'fn_kernel_step_complete: actor % resolves to % — only an active canonical role may complete a step (k3_actor_unresolved)',
      v_actor_in, coalesce(v_kind,'nothing') using errcode = '23514';
  end if;

  -- 3d. the actor is the step run's accountable owner, or holds EXPLICIT delegated authority.
  --     Resolved on both sides, never string-matched: the registry may name a role and the caller
  --     an alias of it.
  v_owner := sr.accountable_role_id;
  if v_actor is distinct from (select role_id from public.fn_phase_c_resolve_actor(v_owner)) then
    select true into v_delegated
      from public.delegation_rule d
     where d.active
       and (select role_id from public.fn_phase_c_resolve_actor(d.when_agent)) = v_owner
       and (select role_id from public.fn_phase_c_resolve_actor(d.delegate_to)) = v_actor
     limit 1;
    if not coalesce(v_delegated, false) then
      raise exception 'fn_kernel_step_complete: step % is accountable to % and % holds no active delegation for it. Phase B froze step ownership; Phase C does not reassign it at runtime. (k3_not_the_accountable_owner)',
        sr.step_id, v_owner, v_actor using errcode = '23514';
    end if;
    v_authority := format('delegated: %s acted for %s under an active delegation_rule', v_actor, v_owner);
  else
    v_delegated := false;
    v_authority := format('accountable owner: %s', v_actor);
  end if;

  -- 3e. REQUIRED INPUTS. The registry states them as prose; K3 requires the caller to name what
  --     it actually used. An absent object is a refusal, never an empty pass.
  if coalesce(btrim(s.required_inputs),'') <> ''
     and coalesce(p_input->'inputs', 'null'::jsonb) in ('null'::jsonb, '{}'::jsonb) then
    raise exception 'fn_kernel_step_complete: step % declares required inputs (%) and the call names none. Send inputs as a non-empty object. (k3_required_inputs_missing)',
      sr.step_id, left(s.required_inputs, 120) using errcode = '22023';
  end if;

  -- 3f. OUTPUT. Three different absences are three different refusals, not one.
  if v_outcome = 'pass' then
    if not (p_input ? 'output') then
      raise exception 'fn_kernel_step_complete: step % passed with no output key at all. The step contract asks for %. (k3_output_key_absent)',
        sr.step_id, left(coalesce(s.required_output,'a structured output'), 120) using errcode = '22023';
    end if;
    if jsonb_typeof(v_output) = 'null' then
      raise exception 'fn_kernel_step_complete: step % sent output as a JSON null. A null is a stated absence of a result, not a result. (k3_output_is_json_null)',
        sr.step_id using errcode = '22023';
    end if;
    if jsonb_typeof(v_output) <> 'object' then
      raise exception 'fn_kernel_step_complete: step % sent output of type %, expected an object. (k3_output_not_an_object)',
        sr.step_id, jsonb_typeof(v_output) using errcode = '22023';
    end if;
    if v_output = '{}'::jsonb then
      raise exception 'fn_kernel_step_complete: step % sent an empty output object. An empty object is not evidence that anything was produced. (k3_output_empty)',
        sr.step_id using errcode = '22023';
    end if;
    select valid, reason into v_out_ok, v_out_reason
      from public.fn_phase_c_output_validate(s.required_output, v_output);
    if not coalesce(v_out_ok, false) then
      raise exception 'fn_kernel_step_complete: step % output is invalid: %. (k3_output_invalid)',
        sr.step_id, coalesce(v_out_reason,'(no reason returned)') using errcode = '22023';
    end if;
    -- The hash is over the OUTPUT. A constant is not evidence.
    v_out_hash := encode(sha256(convert_to(v_output::text, 'UTF8')), 'hex');
  end if;

  -- 3g. REVIEWER. Where Phase B names an independent reviewer for this step, a verdict from that
  --     reviewer must already exist. Independence is decided by fn_kernel_reviewer_independent —
  --     it is not re-implemented here.
  if v_outcome = 'pass' and coalesce(btrim(s.independent_reviewer_role_id),'') <> '' then
    if not exists (
      select 1 from public.phase_c_trace tr
       where tr.task_id = t.task_id
         and tr.trace_policy_id = 'TRACE-ROLE-ACTION'
         and tr.evidence_refs @> '[{"review_decision":"approved"}]'::jsonb
         and public.fn_kernel_reviewer_independent(sr.accountable_role_id, tr.reviewer_role_id)
         and (select role_id from public.fn_phase_c_resolve_actor(tr.reviewer_role_id))
             = (select role_id from public.fn_phase_c_resolve_actor(s.independent_reviewer_role_id))
    ) then
      raise exception 'fn_kernel_step_complete: step % names % as its independent reviewer and no approved, independent verdict from that role exists on task %. Record it with fn_kernel_review_decide first. (k3_reviewer_verdict_missing)',
        sr.step_id, s.independent_reviewer_role_id, t.task_id using errcode = '23514';
    end if;
  end if;

  -- 3h. GATES in scope. Hard gates block; phase_boundary gates are recorded, because they assert a
  --     property of the PHASE and not of this step's evidence.
  v_ev_ref := coalesce(nullif(p_input->>'evidence_ref',''),
                       'run:' || r.run_id || ':step:' || sr.step_id);
  for v_gate in select * from public.fn_phase_c_gates_for_step(sr.step_id) loop
    select passed, reason into v_gate_ok, v_gate_reason
      from public.fn_phase_c_gate_evaluate(v_gate.gate_id,
        jsonb_build_object('evidence_ref', v_ev_ref, 'actor_role_id', v_actor,
                           'step_id', sr.step_id, 'run_id', r.run_id, 'outcome', v_outcome));
    if v_gate.gate_type = 'hard' and not coalesce(v_gate_ok, false) and v_outcome = 'pass' then
      raise exception 'fn_kernel_step_complete: hard gate % refused step %: % (k3_gate_failed)',
        v_gate.gate_id, sr.step_id, coalesce(v_gate_reason,'(no reason returned)')
        using errcode = '23514';
    end if;
    v_gates := v_gates || jsonb_build_array(jsonb_build_object(
      'gate_id', v_gate.gate_id, 'gate_name', v_gate.gate_name, 'type', v_gate.gate_type,
      'passed', coalesce(v_gate_ok,false), 'reason', v_gate_reason,
      'blocking', (v_gate.gate_type = 'hard')));
  end loop;

  -- ---- 4. CLAIM THE IDEMPOTENCY KEY --------------------------------------------------------
  insert into public.phase_c_step_completion
    (idempotency_key, step_run_id, run_id, step_id, actor_role_id, outcome)
  values (v_idem, v_step_run, r.run_id, sr.step_id, v_actor, v_outcome)
  on conflict (idempotency_key) do nothing
  returning completion_id into v_completion;
  if v_completion is null then
    -- A concurrent caller committed the same key while we were verifying. Return THEIR result.
    select c.result into v_prior from public.phase_c_step_completion c where c.idempotency_key = v_idem;
    if v_prior is null then
      raise exception 'fn_kernel_step_complete: idempotency key % is claimed and carries no result — refusing to guess what the other caller did',
        v_idem using errcode = '23505';
    end if;
    return v_prior || jsonb_build_object('replay', true);
  end if;

  -- ---- 5. CLOSE THE TASK, then the STEP RUN, with their traces ------------------------------
  -- The task walks the Phase C task state model one declared hop at a time through
  -- fn_phase_c_task_transition, so every hop is guarded and traced. Hops that are not legal from
  -- the current state are skipped, and the ARRIVAL is asserted: an unreached terminal state raises
  -- rather than being reported as a close.
  v_hops := case v_outcome
              when 'pass'  then array['assigned','accepted','in_progress','completed']
              when 'fail'  then array['assigned','accepted','in_progress','failed']
              else              array['assigned','accepted','in_progress','blocked'] end;
  foreach v_hop in array v_hops loop
    select state into v_now from public.phase_c_task where task_id = t.task_id;
    continue when v_now = v_hop;
    continue when not public.fn_phase_c_task_transition_allowed(v_now, v_hop);
    v_tr := public.fn_phase_c_task_transition(t.task_id, v_hop, v_actor,
      jsonb_build_object('evidence', format('step %s %s by %s', sr.step_id, v_outcome, v_actor),
                         'output_hash', v_out_hash,
                         'blocker', case when v_hop = 'blocked' then v_reason else null end,
                         'blocker_owner_role_id', case when v_hop = 'blocked' then v_owner else null end));
    if not coalesce((v_tr->>'ok')::boolean, false) then
      raise exception 'fn_kernel_step_complete: task % refused the hop % -> %: %',
        t.task_id, v_now, v_hop, coalesce(v_tr->>'error','(no error given)') using errcode = '23514';
    end if;
  end loop;
  select state into v_now from public.phase_c_task where task_id = t.task_id;
  if v_now is distinct from v_hops[array_length(v_hops,1)] then
    raise exception 'fn_kernel_step_complete: task % stopped at % and never reached %. The Phase C task state model declares no path from there, so the step is NOT recorded as closed. (k3_task_close_failed)',
      t.task_id, v_now, v_hops[array_length(v_hops,1)] using errcode = '23514';
  end if;

  -- The output and the gates go on the trace while it is still OPEN; the state update below seals
  -- it through a00_phase_c_step_run_trace_guard.
  perform public.fn_phase_c_trace_advance(sr.trace_id, sr.state, false, jsonb_build_object(
    'output_hash', v_out_hash,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'step_id', sr.step_id, 'outcome', v_outcome, 'actor_role_id', v_actor,
      'authority', v_authority, 'delegated', coalesce(v_delegated,false),
      'gates', v_gates, 'evidence_ref', v_ev_ref,
      'inputs_named', coalesce(p_input->'inputs', '{}'::jsonb),
      'reason', v_reason, 'idempotency_key', v_idem))));

  update public.phase_c_workflow_step_run
     set state = v_target_st, output_hash = v_out_hash, gates_evaluated = v_gates,
         authority_result = v_authority, finished_at = now(),
         failure_reason = case when v_outcome = 'pass' then '' else v_reason end
   where step_run_id = v_step_run;
  if not exists (select 1 from public.phase_c_workflow_step_run
                  where step_run_id = v_step_run and state = v_target_st) then
    raise exception 'fn_kernel_step_complete: step run % did not reach %', v_step_run, v_target_st
      using errcode = '23514';
  end if;

  -- ---- 6. PROGRESSION ------------------------------------------------------------------------
  select c.kind, c.next_step_id, c.next_owner_role_id, c.handoff_id, c.success_state,
         c.failure_state, c.this_owner_role_id, c.reason
    into v_sk, v_next_step, v_next_owner, v_handoff_id, v_succ_state, v_fail_state,
         v_this_owner, v_sk_reason
    from public.fn_kernel_step_successor(sr.step_id) c;

  if v_outcome in ('fail','block') then
    -- The FROZEN registry's failure target, never next_step_if_fail, which is prose in all 257.
    v_run_state := v_fail_state;

  elsif v_sk = 'closure' then
    v_run_state := v_succ_state;                                   -- 'completed' in all 30

    -- MANDATORY CLOSURE BLOCKERS. Each is measured, each can fire, and the current step and task
    -- are already closed above so they cannot count themselves.
    select count(*) into v_n from public.phase_c_workflow_step_run x
     where x.run_id = r.run_id
       and x.state not in ('completed','cancelled','failed','superseded','skipped');
    if v_n > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','open_step_runs', 'count', v_n,
        'detail',(select string_agg(x.step_id || '=' || x.state, ', ' order by x.step_id)
                    from public.phase_c_workflow_step_run x where x.run_id = r.run_id
                     and x.state not in ('completed','cancelled','failed','superseded','skipped'))));
    end if;

    select count(*) into v_n from public.phase_c_task x
     where x.run_id = r.run_id and x.state not in ('completed','cancelled','failed','superseded');
    if v_n > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','open_tasks', 'count', v_n,
        'detail',(select string_agg(x.task_id || '=' || x.state, ', ' order by x.task_id)
                    from public.phase_c_task x where x.run_id = r.run_id
                     and x.state not in ('completed','cancelled','failed','superseded'))));
    end if;

    select count(*) into v_n from public.phase_c_handoff_run x
     where x.run_id = r.run_id and x.status = 'open';
    if v_n > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','open_handoffs', 'count', v_n,
        'detail',(select string_agg(x.handoff_id, ', ' order by x.handoff_id)
                    from public.phase_c_handoff_run x
                   where x.run_id = r.run_id and x.status = 'open')));
    end if;

    -- Every step the workflow declares before the closure step must have been executed to a
    -- terminal state in THIS run. phase_b_workflow_step.step_no is 1..N with no gaps in all 30
    -- workflows, so this is exact rather than approximate.
    select count(*) into v_n from public.phase_b_workflow_step b
     where b.workflow_id = r.workflow_id and b.step_no < s.step_no
       and not exists (select 1 from public.phase_c_workflow_step_run x
                        where x.run_id = r.run_id and x.step_id = b.step_id
                          and x.state in ('completed','skipped','superseded'));
    if v_n > 0 then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','mandatory_steps_never_executed', 'count', v_n,
        'detail',(select string_agg(b.step_id, ', ' order by b.step_no)
                    from public.phase_b_workflow_step b
                   where b.workflow_id = r.workflow_id and b.step_no < s.step_no
                     and not exists (select 1 from public.phase_c_workflow_step_run x
                                      where x.run_id = r.run_id and x.step_id = b.step_id
                                        and x.state in ('completed','skipped','superseded')))));
    end if;

    -- The hard gates in scope were evaluated above and any failure already raised; they are
    -- restated in the closure evidence so the record names what was checked.
    if exists (select 1 from jsonb_array_elements(v_gates) g
                where (g->>'blocking')::boolean and not (g->>'passed')::boolean) then
      v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
        'blocker','hard_gate_failed', 'count', 1, 'detail', v_gates::text));
    end if;

    if jsonb_array_length(v_blockers) > 0 then
      raise exception 'fn_kernel_step_complete: run % cannot close — % mandatory blocker class(es) are open: %. (k3_closure_blocked)',
        r.run_id, jsonb_array_length(v_blockers), v_blockers::text using errcode = '23514';
    end if;

    -- phase_b_business_rule holds 47 hard rules as PROSE with no machine predicate. They are
    -- RECORDED as the obligations in scope; they are not scored, because a scorer that always
    -- returns pass is worse than no scorer. This is a stated Phase C gap, not a silent one.
    select coalesce(jsonb_agg(jsonb_build_object('rule_id', b.rule_id, 'rule_name', b.rule_name)
                              order by b.rule_id), '[]'::jsonb)
      into v_rules
      from public.phase_b_business_rule b
     where b.rule_type = 'hard'
       and (lower(b.workflow_scope) = 'all'
            or r.workflow_id = any (string_to_array(replace(b.workflow_scope,' ',''), ';')));

  elsif v_sk = 'same_owner' then
    v_run_state := v_succ_state;

  elsif v_sk = 'cross_owner' then
    v_run_state := v_succ_state;

  else
    -- registry_gap_no_handoff, successor_owner_unresolved, successor_not_a_step,
    -- closure_flag_disagrees, unknown_step. A non-closure step with no valid successor FAILS
    -- VISIBLY. It never returns terminal success and never returns handled with no reason.
    raise exception 'fn_kernel_step_complete: step % passed and has no valid successor [%]: % (k3_no_valid_successor)',
      sr.step_id, v_sk, v_sk_reason using errcode = '23514';
  end if;

  -- ---- 7. WRITE THE NEXT THING ---------------------------------------------------------------
  if v_outcome = 'pass' and v_sk = 'same_owner' then
    -- No handoff is required and none is invented.
    v_opened := public.fn_kernel_open_step(jsonb_build_object(
      'run_id', r.run_id, 'step_id', v_next_step, 'owner_role_id', v_next_owner,
      'source_kind','workflow_progression',
      'source_ref', 'step_run:' || v_step_run, 'command_id', r.command_id,
      'business_object_id', r.business_object_id, 'priority', v_priority,
      'input_hash', v_out_hash,
      'opened_because', format('%s completed and %s keeps the same accountable owner', sr.step_id, v_next_step)));
    v_created_steps := 1; v_created_tasks := 1;

  elsif v_outcome = 'pass' and v_sk = 'cross_owner' then
    select * into h from public.phase_b_handoff where handoff_id = v_handoff_id;
    if not found then
      raise exception 'fn_kernel_step_complete: the classifier named handoff % and it is not in the registry',
        v_handoff_id using errcode = '23503';
    end if;
    -- The receiving step run and task are NOT created here. Accountability transfers on
    -- ACCEPTANCE, and fn_kernel_handoff_accept is where that happens.
    insert into public.phase_c_handoff_run
      (handoff_id, run_id, from_step_run_id, sending_role_id, receiving_role_id,
       business_object_id, object_version, packet_hash, requested_action, acceptance_criteria,
       return_owner_role_id, sla_policy_id, due_at, status, accountable_until_accept_role_id)
    values (h.handoff_id, r.run_id, v_step_run, h.sending_role_id, h.receiving_role_id,
            r.business_object_id, r.object_version,
            -- over the ACTUAL output that is being handed over
            encode(sha256(convert_to(jsonb_build_object(
              'from_step_id', sr.step_id, 'from_step_run_id', v_step_run,
              'business_object_id', r.business_object_id, 'object_version', r.object_version,
              'output', v_output)::text, 'UTF8')), 'hex'),
            h.required_packet, h.receiving_acceptance_criteria,
            h.return_owner_role_id, h.sla_policy_id,
            public.fn_kernel_sla_due(h.sla_policy_id), 'open', h.sending_role_id)
    returning handoff_run_id into v_handoff_run;
    if v_handoff_run is null then
      raise exception 'fn_kernel_step_complete: the registry declares handoff % for % and no handoff run was created',
        h.handoff_id, sr.step_id using errcode = '23502';
    end if;
    v_ho_trace := public.fn_phase_c_trace_write('TRACE-HANDOFF', jsonb_build_object(
      'subject_kind','handoff_run', 'subject_ref', v_handoff_run::text, 'run_id', r.run_id,
      'command_id', r.command_id, 'actor_role_id', h.sending_role_id,
      'system_actor_id','system.workflow_engine',
      'evidence_refs', jsonb_build_array(jsonb_build_object(
        'handoff_id', h.handoff_id, 'from_step_id', sr.step_id, 'to_step_id', v_next_step,
        'required_packet', h.required_packet, 'sla_policy_id', h.sla_policy_id,
        'output_hash', v_out_hash)),
      'output_hash', v_out_hash,
      'state_before','', 'state_after','open', 'status','open'));
    update public.phase_c_handoff_run set trace_id = v_ho_trace where handoff_run_id = v_handoff_run;
    update public.phase_c_trace set parent_trace_id = r.trace_id where trace_id = v_ho_trace;
    v_created_handoffs := 1;
  end if;

  -- ---- 8. MOVE THE RUN, as a declared and guarded transition ----------------------------------
  -- The closure evidence goes onto the run's root trace while it is still OPEN. The state update
  -- below then seals it through a00_kernel_workflow_run_trace_guard. Writing the evidence after
  -- the seal would create a superseding row instead of the record of this closure.
  if v_outcome = 'pass' and v_sk = 'closure' then
    perform public.fn_phase_c_trace_advance(r.trace_id, r.state, false, jsonb_build_object(
      'output_hash', v_out_hash,
      'evidence_refs', jsonb_build_array(jsonb_build_object(
        'closure_step_id', sr.step_id, 'closed_by', v_actor,
        'blockers_open_at_closure', v_blockers,
        'hard_business_rules_in_scope', coalesce(v_rules,'[]'::jsonb)))));
  end if;

  if v_run_state is distinct from r.state then
    update public.phase_c_workflow_run set state = v_run_state where run_id = r.run_id;
  end if;
  if v_outcome = 'pass' and v_sk = 'closure' then
    update public.phase_c_workflow_run
       set closed_at = now(),
           closure_evidence = jsonb_build_object(
             'closed_by', v_actor, 'closure_step_id', sr.step_id, 'step_run_id', v_step_run,
             'task_id', t.task_id, 'output_hash', v_out_hash, 'idempotency_key', v_idem,
             'gates_evaluated', v_gates,
             'hard_business_rules_in_scope', coalesce(v_rules,'[]'::jsonb),
             'blockers_open_at_closure', v_blockers, 'closed_at', now())
     where run_id = r.run_id;
  elsif v_outcome = 'pass' and v_sk = 'same_owner' then
    -- The successor step run is ACTIVE in this same transaction, so the run is running again.
    -- Both hops are declared in phase_b_workflow_transition; the guard enforces them.
    if v_run_state is distinct from 'active' then
      update public.phase_c_workflow_run set state = 'active' where run_id = r.run_id;
      v_run_state := 'active';
    end if;
  end if;

  -- ---- 9. EMIT, LAST, AND ONLY AFTER THE STATE CHANGE SUCCEEDED --------------------------------
  v_corr := coalesce(nullif(btrim(p_input->>'correlation_id'),''),
                     'run:' || r.run_id);
  v_caus := coalesce(nullif(btrim(p_input->>'causation_id'),''),
                     'step_run:' || v_step_run);
  v_src  := coalesce(nullif(btrim(p_input->>'source_id'),''),
                     'step_run:' || v_step_run);

  if v_outcome = 'pass' then
    v_step_ev := public.fn_phase_c_step_event(sr.step_id, 'completed');
    if v_step_ev is not null then
      v_outbox_step := public.fn_kernel_outbox_emit(jsonb_build_object(
        'event_id', v_step_ev, 'producer','kernel:step_complete',
        'object_version', r.object_version,
        'correlation_id', v_corr, 'causation_id', v_caus, 'source_id', v_src,
        'command_id', r.command_id, 'workflow_run_id', r.run_id, 'step_run_id', v_step_run,
        'trace_id', sr.trace_id,
        'dedupe_value', 'kernel:step_completed:' || v_step_run,
        'payload', jsonb_build_object(
          'fact','step.completed', 'workflow_id', r.workflow_id, 'run_id', r.run_id,
          'step_id', sr.step_id, 'step_run_id', v_step_run, 'task_id', t.task_id,
          'business_object_id', r.business_object_id, 'object_version', r.object_version,
          'actor_role_id', v_actor, 'accountable_role_id', v_owner,
          'delegated', coalesce(v_delegated,false),
          'output_hash', v_out_hash, 'successor_kind', v_sk, 'next_step_id', v_next_step,
          'handoff_run_id', v_handoff_run, 'run_state', v_run_state)));
      v_created_events := v_created_events + 1;
    end if;
  end if;

  if (v_outcome = 'pass' and v_sk = 'closure') then
    v_wf_ev := public.fn_phase_c_lifecycle_event(r.workflow_id, 'completed');
  elsif v_outcome in ('fail','block') then
    -- phase_b_event declares no .failed and no .cancelled event for any workflow. The factual
    -- record of a failed or blocked step is that the workflow is BLOCKED, which is exactly what
    -- failure_workflow_state says. Nothing is invented.
    v_wf_ev := public.fn_phase_c_lifecycle_event(r.workflow_id, 'blocked');
  end if;
  if v_wf_ev is not null then
    v_outbox_wf := public.fn_kernel_outbox_emit(jsonb_build_object(
      'event_id', v_wf_ev, 'producer','kernel:step_complete',
      'object_version', r.object_version,
      'correlation_id', v_corr, 'causation_id', v_caus, 'source_id', v_src,
      'command_id', r.command_id, 'workflow_run_id', r.run_id, 'step_run_id', v_step_run,
      'trace_id', r.trace_id,
      'dedupe_value', 'kernel:run_' || v_run_state || ':' || r.run_id || ':' || v_step_run,
      'payload', jsonb_build_object(
        'fact', 'workflow.' || v_run_state, 'workflow_id', r.workflow_id, 'run_id', r.run_id,
        'step_id', sr.step_id, 'step_run_id', v_step_run,
        'business_object_id', r.business_object_id, 'object_version', r.object_version,
        'accountable_role_id', r.accountable_role_id, 'closed_by', v_actor,
        'outcome', v_outcome, 'reason', v_reason,
        'closure_evidence', (select closure_evidence from public.phase_c_workflow_run
                              where run_id = r.run_id))));
    v_created_events := v_created_events + 1;
  end if;

  -- ---- 10. RESULT, stored on the claim so a replay returns THIS, not a recomputation ----------
  v_result := jsonb_build_object(
    'ok', true, 'replay', false,
    'run_id', r.run_id, 'workflow_id', r.workflow_id,
    'business_object_id', r.business_object_id, 'object_version', r.object_version,
    'step_id', sr.step_id, 'step_run_id', v_step_run, 'task_id', t.task_id,
    'outcome', v_outcome, 'step_run_state', v_target_st, 'run_state', v_run_state,
    'terminal_run', (v_run_state in (select state from public.phase_b_workflow_state where terminal)),
    'actor_role_id', v_actor, 'accountable_role_id', v_owner,
    'delegated', coalesce(v_delegated,false), 'authority', v_authority,
    'successor_kind', v_sk, 'successor_reason', v_sk_reason,
    'next_step_id', v_next_step, 'next_owner_role_id', v_next_owner,
    'handoff_id', v_handoff_id, 'handoff_run_id', v_handoff_run,
    'next_step_run_id', v_opened->'step_run_id', 'next_task_id', v_opened->'task_id',
    'output_hash', v_out_hash, 'gates_evaluated', v_gates,
    'closure_blockers', v_blockers,
    'hard_business_rules_in_scope', coalesce(v_rules,'[]'::jsonb),
    'run_trace_id', r.trace_id, 'step_trace_id', sr.trace_id, 'handoff_trace_id', v_ho_trace,
    'command_id', r.command_id, 'correlation_id', v_corr, 'causation_id', v_caus,
    'source_id', v_src, 'idempotency_key', v_idem,
    'event_step', v_step_ev, 'event_workflow', v_wf_ev,
    'outbox_step_id', v_outbox_step, 'outbox_workflow_id', v_outbox_wf,
    'created', jsonb_build_object('step_runs', v_created_steps, 'tasks', v_created_tasks,
                                  'handoffs', v_created_handoffs, 'events', v_created_events));

  update public.phase_c_step_completion set result = v_result where completion_id = v_completion;
  return v_result;
end

fn_kernel_handoff_accept:
declare
  hr public.phase_c_handoff_run%rowtype;
  r  public.phase_c_workflow_run%rowtype;
  h  public.phase_b_handoff%rowtype;
  v_id     bigint := nullif(p_input->>'handoff_run_id','')::bigint;
  v_actor_in text := nullif(btrim(coalesce(p_input->>'actor_role_id','')), '');
  v_packet jsonb  := p_input->'packet';
  v_actor  text;
  v_kind   text;
  v_n      bigint;
  v_valid  record;
  v_dec    jsonb;
  v_opened jsonb;
  v_target text;
begin
  perform public.fn_kernel_assert_not_in_delivery('fn_kernel_handoff_accept');

  if v_id is null or v_actor_in is null then
    raise exception 'fn_kernel_handoff_accept: handoff_run_id and actor_role_id are both required'
      using errcode = '22023';
  end if;

  -- Same lock order as the engine: run, then handoff run.
  select run_id into v_n from public.phase_c_handoff_run where handoff_run_id = v_id;
  if v_n is null then
    raise exception 'fn_kernel_handoff_accept: no handoff run % (k3_handoff_not_found)', v_id
      using errcode = '23503';
  end if;
  select * into r from public.phase_c_workflow_run where run_id = v_n for update;
  if not found then
    raise exception 'fn_kernel_handoff_accept: handoff run % names workflow run %, which does not exist',
      v_id, v_n using errcode = '23503';
  end if;
  select * into hr from public.phase_c_handoff_run where handoff_run_id = v_id for update;
  if hr.status <> 'open' then
    raise exception 'fn_kernel_handoff_accept: handoff run % is % and cannot be accepted again (k3_handoff_not_open)',
      v_id, hr.status using errcode = '23514';
  end if;
  select * into h from public.phase_b_handoff where handoff_id = hr.handoff_id;
  if not found then
    raise exception 'fn_kernel_handoff_accept: handoff % is not in the frozen registry', hr.handoff_id
      using errcode = '23503';
  end if;

  select kind, role_id into v_kind, v_actor from public.fn_phase_c_resolve_actor(v_actor_in);
  if v_actor is null or v_kind is distinct from 'canonical' then
    raise exception 'fn_kernel_handoff_accept: actor % resolves to % (k3_actor_unresolved)',
      v_actor_in, coalesce(v_kind,'nothing') using errcode = '23514';
  end if;
  if v_actor is distinct from (select role_id from public.fn_phase_c_resolve_actor(hr.receiving_role_id)) then
    raise exception 'fn_kernel_handoff_accept: handoff run % is addressed to % and % may not accept it (k3_not_the_receiver)',
      v_id, hr.receiving_role_id, v_actor using errcode = '23514';
  end if;

  -- GATE-007 in substance: a packet that does not carry what the registry requires is not a
  -- complete handoff, and accepting it would transfer accountability for work nobody can do.
  select * into v_valid from public.fn_phase_c_handoff_packet_valid(hr.handoff_id, v_packet);
  if not v_valid.valid then
    raise exception 'fn_kernel_handoff_accept: handoff run % packet is incomplete [%]. Required packet: %. (k3_handoff_packet_incomplete)',
      v_id, v_valid.missing, left(h.required_packet, 160) using errcode = '23514';
  end if;

  v_dec := public.fn_phase_c_handoff_decide(v_id, 'accept', v_actor,
    jsonb_build_object('packet_hash', encode(sha256(convert_to(v_packet::text,'UTF8')),'hex')));
  if not coalesce((v_dec->>'ok')::boolean, false) then
    raise exception 'fn_kernel_handoff_accept: handoff run % refused acceptance: %',
      v_id, coalesce(v_dec->>'error','(no error given)') using errcode = '23514';
  end if;

  -- The receiving step run and its ONE task, from the accepted contract.
  select role_id into v_target from public.fn_phase_c_resolve_actor(
    (select b.accountable_role_id from public.phase_b_workflow_step b where b.step_id = h.to_step_id));
  if v_target is null or not public.fn_phase_c_actor_may_own(v_target) then
    raise exception 'fn_kernel_handoff_accept: step % names an owner that does not resolve to an active canonical role — no step run and no task are opened (k3_successor_owner_unresolved)',
      h.to_step_id using errcode = '23514';
  end if;

  -- The run is running again. waiting_handoff -> active and waiting_review -> active are both
  -- declared in phase_b_workflow_transition; the guard on phase_c_workflow_run enforces it.
  --
  -- E14 / PCCR-002. THIS STATEMENT USED TO SIT BELOW THE CALL BELOW IT, AND THAT ORDERING MEANT NO
  -- STEP IN THE ESTATE COULD EVER EXECUTE. Since D36, fn_kernel_open_step dispatches the Phase D
  -- handler for the step it opens. A KERNEL_ONLY_TRANSITION handler's declared effect is to complete
  -- that step through fn_kernel_step_complete -- which refuses, correctly, with
  -- k3_run_not_active, because at that instant this function had not yet moved the run out of
  -- waiting_handoff. The kernel opened the step, told Phase D to run it, and refused the only thing
  -- Phase D could do with it. Measured 2026-08-20: 207 dispatches across all thirty workflows, 0
  -- EXECUTED; with the run already active, the same W01-S05 step run returns EXECUTED, hdl_w01_s05,
  -- effect_id 7351.
  --
  -- Nothing else changes. Same condition, same statement, same target row; r is read at the top of
  -- the function and is unaffected by the move. If fn_kernel_open_step raises, the transaction rolls
  -- back exactly as before.
  if r.state is distinct from 'active' then
    update public.phase_c_workflow_run set state = 'active' where run_id = r.run_id;
  end if;

  v_opened := public.fn_kernel_open_step(jsonb_build_object(
    'run_id', r.run_id, 'step_id', h.to_step_id, 'owner_role_id', v_target,
    'source_kind','handoff_accepted', 'source_ref','handoff_run:' || v_id,
    'command_id', r.command_id, 'business_object_id', r.business_object_id,
    'priority', coalesce(nullif(p_input->>'priority',''), 'P2'),
    'input_hash', encode(sha256(convert_to(v_packet::text,'UTF8')),'hex'),
    'opened_because', format('handoff %s was accepted by %s', hr.handoff_id, v_actor)));

  return jsonb_build_object('ok', true, 'handoff_run_id', v_id, 'handoff_id', hr.handoff_id,
    'run_id', r.run_id, 'workflow_id', r.workflow_id,
    'accepted_by', v_actor, 'accountable_now', v_dec->>'accountable_now',
    'to_step_id', h.to_step_id,
    'step_run_id', v_opened->'step_run_id', 'task_id', v_opened->'task_id',
    'step_trace_id', v_opened->'step_trace_id', 'task_trace_id', v_opened->'task_trace_id',
    'handoff_trace_id', v_dec->'trace_id', 'run_state','active',
    'created', jsonb_build_object('step_runs',1,'tasks',1,'handoffs',0,'events',0));
end

fn_kernel_trigger_type_routing_guard:
declare
  v_wf_owner   text;
  v_step_owner text;
  v_step_id    text;
begin
  if new.workflow_id is null then
    return new;                     -- a DEFERRED_HANDLER routes to nothing and owns nothing
  end if;

  select w.accountable_role_id into v_wf_owner
    from public.phase_b_workflow w where w.workflow_id = new.workflow_id;

  select s.step_id, s.accountable_role_id into v_step_id, v_step_owner
    from public.phase_b_workflow_step s
   where s.workflow_id = new.workflow_id and s.step_no = 1;

  -- SELECT INTO that matched nothing leaves NULLs, so the absence is tested rather than assumed.
  if v_step_id is null then
    raise exception
      'kernel_trigger_type %: workflow % declares no step_no = 1, so this trigger type has no entry '
      'step to own the work it would create.', new.trigger_type, new.workflow_id
      using errcode = '23502';
  end if;

  if v_wf_owner in ('founder','chief_of_staff') or v_step_owner in ('founder','chief_of_staff') then
    raise exception
      'kernel_trigger_type %: workflow % is owned by "%" and its entry step % is owned by "%". '
      'Normal autonomous work bypasses both the founder and the Chief of Staff — that is a frozen '
      'boundary, not a preference. Register this route only if it is a founder command, and founder '
      'commands do not come through the trigger inbox.',
      new.trigger_type, new.workflow_id, v_wf_owner, v_step_id, v_step_owner
      using errcode = '23514';
  end if;

  return new;
end

fn_kernel_trigger_submit:
declare
  v_class     text  := nullif(btrim(coalesce(p_input->>'source_class','')), '');
  v_system    text  := nullif(btrim(coalesce(p_input->>'source_system','')), '');
  v_ref       text  := nullif(btrim(coalesce(p_input->>'source_ref','')), '');
  v_ext       text  := nullif(btrim(coalesce(p_input->>'external_ref','')), '');
  v_type_in   text  := nullif(btrim(coalesce(p_input->>'trigger_type','')), '');
  v_by        text  := nullif(btrim(coalesce(p_input->>'requested_by','')), '');
  v_payload   jsonb := coalesce(p_input->'raw_payload', '{}'::jsonb);
  v_version   bigint := coalesce(nullif(p_input->>'object_version','')::bigint, 1);
  v_priority  text  := coalesce(nullif(p_input->>'priority',''), 'P2');
  v_idem      text;
  v_corr      text;
  v_caus      text;
  v_inbox     bigint;
  v_trace     bigint;
  v_obj       text;
  v_key       text;
  v_val       text;
  v_missing   text;
  v_start     jsonb;
  v_run       bigint;
  v_status    text;
  v_reason    text;
  v_actor     text;
  v_kind      text;
  v_owner     text;
  v_step_owner text;
  v_step_id   text;
  -- Scalars, never a RECORD: a plpgsql RECORD assigned only inside an if-branch raises when it is
  -- read, and a SELECT INTO that matched nothing NULLs every target rather than leaving the
  -- initialiser. Both traps have already been paid for in this estate.
  t_workflow  text;
  t_rule      text;
  t_sources   text[];
  t_actor     text;
  t_activation text;
  t_impl      text;
  t_class     text;
  t_note      text;
  p_inbox     bigint;
  p_status    text;
  p_run       bigint;
  p_trace     bigint;
  p_type      text;
  p_wf        text;
  p_obj       text;
  p_reason    text;
begin
  -- ---- 0. a consumer may never drive the request side --------------------------------------
  perform public.fn_kernel_assert_not_in_delivery('fn_kernel_trigger_submit');

  -- ---- 1. envelope. A malformed envelope has nothing recordable in it ----------------------
  --
  -- These raise rather than record: source_class is CHECK-constrained and requested_by is NOT NULL,
  -- so a row cannot be written to hold the refusal. Everything that CAN be recorded is recorded
  -- below instead of raised.
  if v_class is null or v_system is null or v_ref is null or v_type_in is null or v_by is null then
    raise exception
      'fn_kernel_trigger_submit: source_class, source_system, source_ref, trigger_type and '
      'requested_by are all required (got %, %, %, %, %)',
      coalesce(v_class,'(null)'), coalesce(v_system,'(null)'), coalesce(v_ref,'(null)'),
      coalesce(v_type_in,'(null)'), coalesce(v_by,'(null)')
      using errcode = '22023';
  end if;
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception 'fn_kernel_trigger_submit: raw_payload must be a json object, got %',
      jsonb_typeof(v_payload) using errcode = '22023';
  end if;
  if v_class not in ('customer_event','supplier_event','scheduled_event','deadline_sla_event',
                     'kpi_deviation_event','system_health_event','webhook_provider_event',
                     'workflow_followup_event') then
    raise exception 'fn_kernel_trigger_submit: % is not one of the eight registered source classes',
      v_class using errcode = '22023';
  end if;

  -- The idempotency key is the external identity of the request. Defaulted from the source's own
  -- reference, never from now() or from a sequence: a key that is different every time is not a key.
  v_idem := coalesce(nullif(btrim(p_input->>'idempotency_key'),''),
                     v_system || ':' || coalesce(v_ext, v_ref));
  v_corr := coalesce(nullif(btrim(p_input->>'correlation_id'),''), 'trigger:' || v_idem);
  v_caus := coalesce(nullif(btrim(p_input->>'causation_id'),''), v_system || ':' || v_ref);

  -- ---- 2. idempotency, before anything is resolved and before anything is created ----------
  insert into public.kernel_trigger_inbox
    (source_class, source_system, source_ref, external_ref, raw_payload,
     correlation_id, causation_id, idempotency_key, status, requested_by)
  values (v_class, v_system, v_ref, v_ext, v_payload, v_corr, v_caus, v_idem, 'pending', v_by)
  on conflict (idempotency_key) do nothing
  returning inbox_id into v_inbox;

  if v_inbox is null then
    -- Seen before. Return the FIRST result and create nothing: no run, no task, no event, and no
    -- second inbox row. The first row's decision is the answer, whatever it was.
    select i.inbox_id, i.status, i.run_id, i.trace_id, i.trigger_type, i.workflow_id,
           i.business_object_id, i.refusal_reason
      into p_inbox, p_status, p_run, p_trace, p_type, p_wf, p_obj, p_reason
      from public.kernel_trigger_inbox i where i.idempotency_key = v_idem;
    -- An empty read here would mean the conflicting row belongs to a transaction that has not
    -- committed. Returning a jsonb full of nulls would make "someone else is mid-flight" look
    -- exactly like "refused with no reason", so it raises instead.
    if p_inbox is null then
      raise exception
        'fn_kernel_trigger_submit: idempotency key % conflicted but no committed row holds it — a '
        'concurrent submission of the same key is still open. Retry.', v_idem
        using errcode = '40001';
    end if;
    return jsonb_build_object(
      'ok', p_status in ('accepted','duplicate'), 'duplicate', true, 'status', p_status,
      'inbox_id', p_inbox, 'idempotency_key', v_idem, 'trigger_type', p_type,
      'workflow_id', p_wf, 'business_object_id', p_obj, 'run_id', p_run, 'trace_id', p_trace,
      'refusal_reason', p_reason,
      'created', jsonb_build_object('inbox_row',0,'run',0,'step_run',0,'task',0,'event',0),
      'note','idempotency_key already recorded; the first result is returned and nothing was created');
  end if;

  -- ---- 3. normalize to a REGISTERED trigger type -------------------------------------------
  select t.workflow_id, t.business_object_rule, t.allowed_source_systems, t.system_actor_id,
         t.activation_state, t.implementation_state, t.source_class, t.accountable_note
    into t_workflow, t_rule, t_sources, t_actor, t_activation, t_impl, t_class, t_note
    from public.kernel_trigger_type t where t.trigger_type = v_type_in;

  v_status := null; v_reason := null;

  if t_class is null then
    v_status := 'refused';
    v_reason := format('no registered trigger type named %s. An unmapped trigger is recorded and '
                    || 'refused; it is never resolved to the nearest workflow.', v_type_in);
  elsif t_class is distinct from v_class then
    v_status := 'refused';
    v_reason := format('trigger type %s is registered under source class %s and was submitted as %s',
                       v_type_in, t_class, v_class);
  elsif not (v_system = any (t_sources)) then
    v_status := 'refused';
    v_reason := format('source system %s is not permitted to submit %s. Permitted: %s',
                       v_system, v_type_in, array_to_string(t_sources, ', '));
  elsif t_impl = 'DEFERRED_HANDLER' then
    v_status := 'deferred';
    v_reason := format('trigger type %s is a DEFERRED_HANDLER: the frozen Phase B registry declares '
                    || 'no workflow that starts from this signal. %s', v_type_in, t_note);
  elsif t_activation <> 'active' then
    v_status := 'refused';
    v_reason := format('trigger type %s is registered with activation_state %s and does not accept '
                    || 'submissions', v_type_in, t_activation);
  end if;

  -- ---- 4. resolve the business object BY THE RECORDED RULE ---------------------------------
  if v_status is null then
    v_obj := t_rule;
    -- regexp_matches is set-returning, so it is driven by a FOR loop and never placed inside a
    -- boolean expression: a set-returning function in a boolean expression raises 42804.
    for v_key in select rr.mk[1] from regexp_matches(t_rule, '\{([a-zA-Z0-9_]+)\}', 'g') as rr(mk) loop
      v_val := nullif(btrim(coalesce(v_payload->>v_key,'')), '');
      if v_val is null then
        v_missing := coalesce(v_missing || ', ', '') || v_key;
      else
        v_obj := replace(v_obj, '{' || v_key || '}', v_val);
      end if;
    end loop;

    if v_missing is not null then
      v_status := 'refused';
      v_reason := format('business object rule %s needs payload key(s) %s and the payload does not '
                      || 'carry them. The object is refused, not guessed.', t_rule, v_missing);
    elsif v_obj ~ '[{}]' then
      v_status := 'refused';
      v_reason := format('business object rule %s did not fully resolve: %s', t_rule, v_obj);
    end if;
  end if;

  -- ---- 5. the founder boundary, checked again at call time ---------------------------------
  --
  -- The registry guard in §1 refuses such a row at write time. This is the second check, because a
  -- row could predate the guard, and because "normal autonomous work never routes through the
  -- founder or the Chief of Staff" is the kind of rule that must hold even when the table is wrong.
  if v_status is null then
    select kind, role_id into v_kind, v_owner
      from public.fn_phase_c_resolve_actor(
        (select w.accountable_role_id from public.phase_b_workflow w where w.workflow_id = t_workflow));
    select s.step_id, r.role_id into v_step_id, v_step_owner
      from public.phase_b_workflow_step s,
           lateral public.fn_phase_c_resolve_actor(s.accountable_role_id) r
     where s.workflow_id = t_workflow and s.step_no = 1;

    if v_owner is null or v_kind is distinct from 'canonical' then
      v_status := 'refused';
      v_reason := format('workflow %s names accountable role that resolves to %s — no run created',
                         t_workflow, coalesce(v_kind,'nothing'));
    elsif v_owner in ('founder','chief_of_staff') or coalesce(v_step_owner,'') in ('founder','chief_of_staff') then
      v_status := 'refused';
      v_reason := format('workflow %s would put autonomous work on %s / %s (step %s). Normal '
                      || 'autonomous work bypasses both the founder and the Chief of Staff.',
                         t_workflow, v_owner, coalesce(v_step_owner,'(none)'), coalesce(v_step_id,'(none)'));
    end if;
  end if;

  -- ---- 6. refusals and deferrals are RECORDED, with their own trace ------------------------
  if v_status is not null then
    v_actor := coalesce(t_actor, 'system.webhook_receiver');
    v_trace := public.fn_kernel_intake_execution('dbfn:fn_kernel_trigger_submit(jsonb)', jsonb_build_object(
      'subject_kind','trigger_inbox', 'subject_ref', v_inbox::text,
      'system_actor_id', v_actor,
      'actor_role_id', coalesce(nullif(v_owner,''), ''),
      'component_id','dbfn:fn_kernel_trigger_submit(jsonb)',
      'authority_result', v_status || ': ' || v_reason,
      'input_hash', encode(sha256(convert_to(v_idem || '|' || v_payload::text, 'UTF8')), 'hex'),
      'evidence_refs', jsonb_build_array(jsonb_build_object(
        'source_class', v_class, 'source_system', v_system, 'source_ref', v_ref,
        'external_ref', v_ext, 'submitted_trigger_type', v_type_in,
        'idempotency_key', v_idem, 'raw_payload', v_payload)),
      'state_before','pending', 'state_after', v_status, 'status','sealed'));

    update public.kernel_trigger_inbox
       set status = v_status, refusal_reason = v_reason, trace_id = v_trace,
           trigger_type = (case when t_class is null then null else v_type_in end),
           processed_at = now()
     where inbox_id = v_inbox;

    return jsonb_build_object(
      'ok', false, 'duplicate', false, 'status', v_status, 'inbox_id', v_inbox,
      'idempotency_key', v_idem, 'trigger_type', v_type_in, 'workflow_id', t_workflow,
      'business_object_id', null, 'run_id', null, 'trace_id', v_trace,
      'refusal_reason', v_reason, 'correlation_id', v_corr, 'causation_id', v_caus,
      'created', jsonb_build_object('inbox_row',1,'run',0,'step_run',0,'task',0,'event',0));
  end if;

  -- ---- 7. THE ONLY creator of business work is called ---------------------------------------
  --
  -- No insert into phase_c_task, phase_c_workflow_run, phase_c_workflow_step_run,
  -- phase_c_handoff_run or phase_c_event_outbox appears anywhere in this function. All six objects
  -- come from fn_kernel_workflow_start, atomically, or none of them does.
  v_start := public.fn_kernel_workflow_start(jsonb_build_object(
    'workflow_id',        t_workflow,
    'business_object_id', v_obj,
    'object_version',     v_version,
    'source_kind',        'autonomous',
    'source_ref',         'trigger_inbox:' || v_inbox,
    'correlation_id',     v_corr,
    'causation_id',       v_caus,
    'requested_by',       v_by,
    'priority',           v_priority,
    'trigger_ctx',        jsonb_build_object(
        'inbox_id', v_inbox, 'trigger_type', v_type_in, 'source_class', v_class,
        'source_system', v_system, 'source_ref', v_ref, 'external_ref', v_ext,
        'idempotency_key', v_idem, 'business_object_rule', t_rule, 'raw_payload', v_payload)));

  v_run    := (v_start->>'run_id')::bigint;
  v_status := case when coalesce((v_start->>'duplicate')::boolean, false)
                   then 'duplicate' else 'accepted' end;

  if v_run is null then
    raise exception 'fn_kernel_trigger_submit: fn_kernel_workflow_start returned no run_id for % / %',
      t_workflow, v_obj using errcode = '23502';
  end if;

  -- ---- 8. the adapter's own execution trace, parented to the run's root --------------------
  v_trace := public.fn_kernel_intake_execution('dbfn:fn_kernel_trigger_submit(jsonb)', jsonb_build_object(
    'subject_kind','trigger_inbox', 'subject_ref', v_inbox::text,
    'run_id', v_run, 'step_run_id', (v_start->>'step_run_id')::bigint,
    'task_id', (v_start->>'task_id')::bigint,
    'system_actor_id', t_actor,
    'actor_role_id', v_start->>'step_accountable_role_id',
    'manager_role_id', v_start->>'accountable_role_id',
    'component_id','dbfn:fn_kernel_trigger_submit(jsonb)',
    'authority_result', v_status || ': trigger type ' || v_type_in || ' -> ' || t_workflow
                     || ' by registry, business object by rule ' || t_rule,
    'input_hash', encode(sha256(convert_to(v_idem || '|' || v_payload::text, 'UTF8')), 'hex'),
    'output_hash', encode(sha256(convert_to(v_start::text, 'UTF8')), 'hex'),
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'source_class', v_class, 'source_system', v_system, 'source_ref', v_ref,
      'external_ref', v_ext, 'idempotency_key', v_idem,
      'business_object_rule', t_rule, 'business_object_id', v_obj, 'raw_payload', v_payload)),
    'event_ids', jsonb_build_array(v_start->>'event_id'),
    'state_before','pending', 'state_after', v_status, 'status','sealed',
    'parent_trace_id', (v_start->>'run_trace_id')::bigint));

  update public.kernel_trigger_inbox
     set status = v_status, trigger_type = v_type_in, workflow_id = t_workflow,
         business_object_id = v_obj, run_id = v_run, trace_id = v_trace, processed_at = now()
   where inbox_id = v_inbox;

  return jsonb_build_object(
    'ok', true, 'duplicate', (v_status = 'duplicate'), 'status', v_status,
    'inbox_id', v_inbox, 'idempotency_key', v_idem,
    'source_class', v_class, 'trigger_type', v_type_in, 'workflow_id', t_workflow,
    'business_object_id', v_obj, 'object_version', v_version,
    'run_id', v_run, 'step_run_id', (v_start->>'step_run_id')::bigint,
    'task_id', (v_start->>'task_id')::bigint,
    'accountable_role_id', v_start->>'accountable_role_id',
    'step_accountable_role_id', v_start->>'step_accountable_role_id',
    'handoff_run_id', (v_start->>'handoff_run_id')::bigint,
    'event_id', v_start->>'event_id', 'outbox_id', (v_start->>'outbox_id')::bigint,
    'trace_id', v_trace, 'run_trace_id', (v_start->>'run_trace_id')::bigint,
    'correlation_id', v_corr, 'causation_id', v_caus, 'system_actor_id', t_actor,
    'created', jsonb_build_object(
      'inbox_row', 1,
      'run',      (case when v_status = 'duplicate' then 0 else 1 end),
      'step_run', (case when v_status = 'duplicate' then 0 else 1 end),
      'task',     (case when v_status = 'duplicate' then 0 else 1 end),
      'event',    (case when v_status = 'duplicate' then 0 else 1 end),
      'adapter_trace', 1));
end

fn_kernel_cron_exec:
declare
  w          public.phase_c_system_execution_wrapper%rowtype;
  c          public.phase_c_component%rowtype;
  a          public.phase_c_action_class%rowtype;
  v_sched    text;
  v_started  timestamptz := clock_timestamp();
  v_finished timestamptz;
  v_result   text := 'succeeded';
  v_failure  text := null;
  v_scope    text := null;
begin
  select * into w from public.phase_c_system_execution_wrapper where jobid = p_jobid;
  if not found then
    raise exception
      'fn_kernel_cron_exec: no wrapper row for cron job %. The job command was rewritten to call '
      'this wrapper and the row holding its original command is gone, so there is nothing to run. '
      'Restore the row or restore the command; do not leave the job pointing at nothing.', p_jobid
      using errcode = '23503';
  end if;

  select * into c from public.phase_c_component where component_id = w.component_id;
  if not found then
    raise exception 'fn_kernel_cron_exec: component % has no registry row', w.component_id
      using errcode = '23503';
  end if;

  select schedule into v_sched from cron.job where jobid = p_jobid;
  select * into a from public.phase_c_action_class where action_class = c.authority_class;

  -- Run the original work. The sub-transaction means a failure rolls the work back and still
  -- leaves the trace writable, which is the whole point of recording the failure.
  --
  -- ponytail: the failure is recorded and NOT re-raised, so cron.job_run_details will read
  -- "succeeded" for a run whose work failed. Re-raising would roll back the trace as well and we
  -- would be back to an untraced failure, which is worse. The trace carries result='failed' with
  -- the sqlstate and message, and fn_kernel_system_trace_state reports failures on their own line.
  -- Upgrade path if cron-level failure signalling is ever needed: write the trace through a
  -- dblink/pg_background autonomous connection, then re-raise.
  begin
    execute w.original_command;
  exception when others then
    v_result  := 'failed';
    v_failure := sqlstate || ' ' || sqlerrm;
  end;
  v_finished := clock_timestamp();

  -- A cron component with no Phase B workflow says so, in words, rather than borrowing the
  -- authority of a workflow id it does not have.
  if coalesce(c.workflow_id,'') = ''
     or not exists (select 1 from public.phase_b_workflow where workflow_id = c.workflow_id) then
    v_scope := format('technical scope: scheduled infrastructure execution registered as %L in '
                   || 'phase_c_component.workflow_id, which is not one of the thirty Phase B '
                   || 'workflows. Accountability is carried by the role, not by a workflow.',
                      coalesce(nullif(c.workflow_id,''), '(none)'));
  end if;

  return public.fn_kernel_system_execution_trace(jsonb_build_object(
    'component_id',       c.component_id,
    'system_actor',       c.canonical_system_actor,
    'accountable_role_id',c.accountable_role_id,
    'workflow_id',        case when v_scope is null then c.workflow_id else null end,
    'step_id',            case when v_scope is null then nullif(c.step_id,'') else null end,
    'technical_scope',    v_scope,
    'trigger_source',     format('cron.job/%s %L schedule %L', p_jobid, c.component_id,
                                 coalesce(v_sched,'(unreadable)')),
    -- Derived from the action class, not asserted. If a class ever requires founder approval this
    -- string says so and fn_kernel_system_trace_state counts it on its own line.
    'authority_result',   case
                            when a.action_class is null then 'unknown_action_class:' || coalesce(c.authority_class,'(none)')
                            when a.founder_approval_required then 'requires_founder_approval:' || a.action_class
                            else 'allowed_autonomous:' || a.action_class || ':' || a.execution_mode
                          end,
    -- For a scheduled execution the honest state pair is the execution's own lifecycle: the
    -- wrapper cannot know which business object the payload touched. Where the payload routes
    -- through the kernel, the business transition is traced separately under TRACE-WORKFLOW and
    -- TRACE-STEP; this trace records that the scheduled execution happened and how it ended.
    'state_before',       'scheduled_due',
    'state_after',        v_result,
    'result',             v_result,
    'failure',            to_jsonb(v_failure),
    'correlation_id',     gen_random_uuid()::text,
    'causation_id',       format('cron.job/%s@%s', p_jobid,
                                 to_char(v_started at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MSZ')),
    'input_hash',         md5(w.original_command),
    'started_at',         v_started,
    'finished_at',        v_finished));
end

fn_kernel_assert_in_kernel:
begin
  if coalesce(current_setting('kernel.in_kernel', true), '') <> 'on' then
    raise exception
      '% is a kernel-internal primitive and was called from outside the kernel', p_who
      using errcode = '23514',
            hint = 'Call the canonical service instead. public.kernel_retired_path names the '
                || 'replacement for every retired path.';
  end if;
end

fn_kernel_signal_submit:
declare
  v_src_type  text   := nullif(btrim(coalesce(p_input->>'source_type','')), '');
  v_src_id    text   := nullif(btrim(coalesce(p_input->>'source_id','')), '');
  v_run       bigint := nullif(p_input->>'workflow_run_id','')::bigint;
  v_sig       text   := nullif(btrim(coalesce(p_input->>'signal_type','')), '');
  v_payload   jsonb  := coalesce(p_input->'payload', '{}'::jsonb);
  v_by        text   := nullif(btrim(coalesce(p_input->>'requested_by','')), '');
  v_idem      text;
  v_corr      text;
  v_caus      text;
  v_id        bigint;
  -- Scalars, never a RECORD read outside the branch that filled it.
  v_prior_id     bigint;
  v_prior_status text;
  v_prior_result jsonb;
  v_disp      text;
  v_sig_wf    text;
  v_sig_act   text;
  v_sig_sys   text;
  v_run_wf    text;
  v_run_state text;
  v_run_obj   text;
  v_run_trace bigint;
  v_step_run  bigint;
  v_step_id   text;
  v_step_owner text;
  v_task      bigint;
  v_trace     bigint;
  v_out       jsonb;
  v_refuse    text;
begin
  -- ---- 0. a delivery worker may never drive the request side -------------------------------
  perform public.fn_kernel_assert_not_in_delivery('fn_kernel_signal_submit');

  -- ---- 1. envelope. Nothing recordable in a malformed one -----------------------------------
  if v_src_type is null or v_src_id is null or v_sig is null or v_by is null then
    raise exception 'fn_kernel_signal_submit: source_type, source_id, signal_type and requested_by are all required (got %, %, %, %)',
      coalesce(v_src_type,'(null)'), coalesce(v_src_id,'(null)'), coalesce(v_sig,'(null)'),
      coalesce(v_by,'(null)') using errcode = '22023';
  end if;
  if jsonb_typeof(v_payload) <> 'object' then
    raise exception 'fn_kernel_signal_submit: payload must be a json object, got %',
      jsonb_typeof(v_payload) using errcode = '22023';
  end if;

  -- The key is the external identity of the signal. Defaulted from the source's own reference and
  -- the run it is about — never from now() or a sequence, because a key that differs every time
  -- is not a key and would let one webhook retry apply twice.
  v_idem := coalesce(nullif(btrim(p_input->>'idempotency_key'),''),
                     v_src_type || ':' || v_src_id || ':' || v_sig || ':' || coalesce(v_run::text,'-'));
  v_corr := coalesce(nullif(btrim(p_input->>'correlation_id'),''), 'signal:' || v_idem);
  v_caus := coalesce(nullif(btrim(p_input->>'causation_id'),''), v_src_type || ':' || v_src_id);

  -- ---- 2. idempotency, before anything is resolved and before anything happens --------------
  select s.signal_id, s.status, s.result into v_prior_id, v_prior_status, v_prior_result
    from public.kernel_signal_inbox s where s.idempotency_key = v_idem;
  if v_prior_id is not null then
    return jsonb_build_object('ok', v_prior_status <> 'refused', 'duplicate', true,
      'signal_id', v_prior_id, 'status', v_prior_status, 'result', v_prior_result,
      'reason', 'this signal has already been delivered; the first decision is the answer');
  end if;

  insert into public.kernel_signal_inbox
    (source_type, source_id, workflow_run_id, signal_type, payload, idempotency_key,
     correlation_id, causation_id, requested_by)
  values (v_src_type, v_src_id, v_run, v_sig, v_payload, v_idem, v_corr, v_caus, v_by)
  returning signal_id into v_id;

  -- ---- 3. the signal type must be registered and active ------------------------------------
  select t.disposition, t.workflow_id, t.activation_state, t.system_actor_id
    into v_disp, v_sig_wf, v_sig_act, v_sig_sys
    from public.kernel_signal_type t where t.signal_type = v_sig;
  if v_disp is null then
    v_refuse := format('signal type %L is not registered. A signal the kernel has never heard of '
                    || 'is not routed on a guess.', v_sig);
  elsif v_sig_act <> 'active' then
    v_refuse := format('signal type %L is registered with activation_state %L and does not accept '
                    || 'submissions.', v_sig, v_sig_act);
  end if;

  -- ---- 4. the run must exist, and must still be running -------------------------------------
  if v_refuse is null then
    if v_run is null then
      v_refuse := 'a signal about an existing workflow must name workflow_run_id. There is no '
               || 'lookup by business object here on purpose: guessing which run a signal belongs '
               || 'to is how one arrival lands on two runs.';
    else
      select r.workflow_id, r.state, r.business_object_id, r.trace_id
        into v_run_wf, v_run_state, v_run_obj, v_run_trace
        from public.phase_c_workflow_run r where r.run_id = v_run for update;
      if v_run_wf is null then
        v_refuse := format('workflow run %s does not exist.', v_run);
      elsif exists (select 1 from public.phase_b_workflow_state ws
                     where ws.state = v_run_state and ws.terminal) then
        v_refuse := format('workflow run %s is in terminal state %L. A closed run does not accept '
                        || 'signals; if this is new work it must come through '
                        || 'fn_kernel_trigger_submit and be judged on its own.', v_run, v_run_state);
      elsif v_sig_wf is not null and v_sig_wf is distinct from v_run_wf then
        v_refuse := format('signal type %L is declared for workflow %L and run %s is %L.',
                           v_sig, v_sig_wf, v_run, v_run_wf);
      end if;
    end if;
  end if;

  if v_refuse is not null then
    update public.kernel_signal_inbox
       set status = 'refused', refusal_reason = v_refuse, processed_at = now()
     where signal_id = v_id;
    return jsonb_build_object('ok', false, 'duplicate', false, 'signal_id', v_id,
      'status','refused', 'reason', v_refuse);
  end if;

  -- ---- 5. the signal is attached to the run it names, always --------------------------------
  -- Even a signal whose disposition changes nothing leaves a trace parented to the run's trace, so
  -- "we were told and did nothing" and "we were never told" can never be confused later.
  v_trace := public.fn_kernel_intake_execution('dbfn:fn_kernel_signal_submit(jsonb)', jsonb_build_object(
    'subject_kind','system_execution', 'subject_ref', 'signal:' || v_id::text, 'run_id', v_run,
    'actor_role_id', null, 'system_actor_id', v_sig_sys,
    'evidence_refs', jsonb_build_array(jsonb_build_object(
      'signal_id', v_id, 'signal_type', v_sig, 'disposition', v_disp,
      'source_type', v_src_type, 'source_id', v_src_id, 'idempotency_key', v_idem)),
    'state_before', v_run_state, 'state_after', v_run_state, 'status','complete'));
  update public.kernel_signal_inbox set trace_id = v_trace where signal_id = v_id;
  if v_run_trace is not null then
    -- parent_trace_id is set by fn_kernel_intake_execution BEFORE the trace is sealed (rc4).
  -- Setting it here would edit a sealed trace, which fn_phase_c_trace_append_only refuses.
  perform 1;
  end if;

  -- The run's currently active step, if it has one. Read once, used by three dispositions.
  select sr.step_run_id, sr.step_id, sr.accountable_role_id
    into v_step_run, v_step_id, v_step_owner
    from public.phase_c_workflow_step_run sr
   where sr.run_id = v_run and sr.state = 'active'
   order by sr.step_run_id limit 1;

  -- ---- 6. the declared disposition, and only that -------------------------------------------
  if v_disp = 'ATTACH_ONLY' then
    update public.kernel_signal_inbox
       set status = 'attached', step_run_id = v_step_run, processed_at = now(),
           result = jsonb_build_object('attached_to_run', v_run, 'active_step', v_step_id)
     where signal_id = v_id;
    return jsonb_build_object('ok', true, 'duplicate', false, 'signal_id', v_id,
      'status','attached', 'workflow_run_id', v_run, 'workflow_id', v_run_wf,
      'active_step_id', v_step_id, 'trace_id', v_trace, 'created_workflow_runs', 0);

  elsif v_disp = 'COMPLETE_STEP' then
    if v_step_run is null then
      v_refuse := format('run %s has no active step, so there is nothing for a COMPLETE_STEP '
                      || 'signal to complete.', v_run);
    elsif coalesce(jsonb_typeof(v_payload->'output'),'') <> 'object'
       or v_payload->'output' = '{}'::jsonb then
      v_refuse := format('signal type %L completes step %s and the payload carries no output '
                      || 'object. An output is what the step contract asks for; it is not '
                      || 'defaulted here, because a fabricated output certifies work nobody did.',
                         v_sig, v_step_id);
    end if;
    if v_refuse is not null then
      update public.kernel_signal_inbox
         set status = 'refused', refusal_reason = v_refuse, step_run_id = v_step_run,
             processed_at = now()
       where signal_id = v_id;
      return jsonb_build_object('ok', false, 'duplicate', false, 'signal_id', v_id,
        'status','refused', 'reason', v_refuse);
    end if;
    v_out := public.fn_kernel_step_complete(jsonb_build_object(
      'step_run_id',     v_step_run,
      'actor_role_id',   v_step_owner,
      'outcome',         coalesce(nullif(btrim(v_payload->>'outcome'),''), 'pass'),
      'idempotency_key', 'signal:' || v_idem,
      'reason',          coalesce(nullif(btrim(v_payload->>'reason'),''),
                                  'signal ' || v_sig || ' from ' || v_src_type || ':' || v_src_id),
      'inputs',          coalesce(v_payload->'inputs',
                                  jsonb_build_object('signal_id', v_id, 'signal_type', v_sig,
                                                     'source', v_src_type || ':' || v_src_id)),
      'output',          v_payload->'output',
      'evidence_ref',    'signal:' || v_id::text,
      'correlation_id',  v_corr, 'causation_id', v_caus));

  elsif v_disp = 'REVIEW_VERDICT' then
    select t.task_id into v_task from public.phase_c_task t
     where t.run_id = v_run and t.step_id = v_step_id order by t.task_id desc limit 1;
    if v_task is null or coalesce(btrim(v_payload->>'decision'),'') = '' then
      v_refuse := format('a REVIEW_VERDICT signal needs a task on the active step and a decision '
                      || 'in the payload (task %s, decision %L).',
                         coalesce(v_task::text,'none'), coalesce(v_payload->>'decision','(none)'));
      update public.kernel_signal_inbox
         set status = 'refused', refusal_reason = v_refuse, step_run_id = v_step_run,
             processed_at = now()
       where signal_id = v_id;
      return jsonb_build_object('ok', false, 'duplicate', false, 'signal_id', v_id,
        'status','refused', 'reason', v_refuse);
    end if;
    v_out := public.fn_kernel_review_decide(jsonb_build_object(
      'task_id',          v_task,
      'reviewer_role_id', v_payload->>'reviewer_role_id',
      'decision',         v_payload->>'decision',
      'reason',           coalesce(nullif(btrim(v_payload->>'reason'),''),
                                   'recorded from signal ' || v_id::text)));

  elsif v_disp = 'CANCEL' then
    v_out := public.fn_kernel_cancel(jsonb_build_object(
      'subject_kind', 'workflow_run',
      'subject_ref',  v_run::text,
      'op',           'cancel',
      'reason',       coalesce(nullif(btrim(v_payload->>'reason'),''),
                               'cancelled by signal ' || v_sig || ' from ' || v_src_type || ':' || v_src_id),
      'actor',        v_by));
  end if;

  update public.kernel_signal_inbox
     set status = 'applied', step_run_id = v_step_run, processed_at = now(), result = v_out
   where signal_id = v_id;

  return jsonb_build_object('ok', coalesce((v_out->>'ok')::boolean, true), 'duplicate', false,
    'signal_id', v_id, 'status','applied', 'disposition', v_disp,
    'workflow_run_id', v_run, 'workflow_id', v_run_wf, 'step_id', v_step_id,
    'trace_id', v_trace, 'created_workflow_runs', 0, 'result', v_out);
end

fn_kernel_write_guard:
declare
  v_ctx    text;
  v_reason text;
  v_owner  text;
  v_ok     boolean;
begin
  get diagnostics v_ctx = pg_context;

  -- Door 1: an authorised routine is on the stack. The stack cannot be forged.
  select exists (
    select 1 from public.kernel_write_authority a
     where a.table_name = tg_table_name
       and v_ctx ~ ('PL/pgSQL function (public\.)?' || a.routine_name || '\(')
  ) into v_ok;
  if v_ok then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  -- Door 2: an explicit, audited maintenance operation BY THE TABLE OWNER. Under SECURITY INVOKER
  -- current_user is the caller's own role — service_role stays service_role, and the comparison
  -- means what it says.
  v_reason := nullif(btrim(current_setting('kernel.maintenance_reason', true)), '');
  select tableowner into v_owner from pg_tables
   where schemaname = tg_table_schema and tablename = tg_table_name;
  if v_reason is not null and current_user = v_owner then
    perform public.fn_kernel_record_maintenance_write(
      current_user, session_user, tg_table_name, tg_op, v_reason, v_ctx);
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  raise exception
    '% on %.% is refused: no routine with write authority for this table is on the call stack.',
    tg_op, tg_table_schema, tg_table_name
    using errcode = '42501',
          detail = 'Call stack was:' || chr(10) || v_ctx,
          hint = 'Business work is created by the kernel and only by the kernel. New work goes '
              || 'through fn_kernel_trigger_submit; a signal about a run that already exists goes '
              || 'through fn_kernel_signal_submit; a step is completed with fn_kernel_step_complete. '
              || 'public.kernel_write_authority lists every routine permitted to write this table '
              || 'and why. Historical maintenance needs BOTH a stated reason — set local '
              || 'kernel.maintenance_reason — AND the table owner; stating a reason alone is not '
              || 'enough, and since K37 it never was.';
end

fn_kernel_source_emit:
declare
  v_class   text;
  v_vocab   text;
  v_wf      text;
  v_actor   text;
  v_active  text;
  v_ref     text := nullif(btrim(coalesce(p_input->>'source_ref','')), '');
  v_run     bigint := nullif(p_input->>'workflow_run_id','')::bigint;
  v_out     jsonb;
  v_ctx     text;
begin
  select c.source_class, c.target_step_or_signal, c.target_workflow, c.system_actor,
         c.current_activation
    into v_class, v_vocab, v_wf, v_actor, v_active
    from public.phase_c_source_cutover c where c.source_component_id = p_source_key;

  if v_class is null then
    raise exception 'fn_kernel_source_emit: % is not in the source cutover register', p_source_key
      using errcode = '23503',
            hint = 'Every autonomous source is classified in public.phase_c_source_cutover. A '
                || 'source with no row has no route, and routing it on a guess is how one arrival '
                || 'lands on two workflows. Classify it in scripts/phase_c/source_classification.mjs '
                || 'and regenerate.';
  end if;

  if v_class = 'C READ_ONLY_MONITOR' then
    raise exception 'fn_kernel_source_emit: % is a READ_ONLY_MONITOR and may not create business work',
      p_source_key using errcode = '42501',
        hint = 'A monitor collects status and may update approved operational state. When a '
            || 'threshold is crossed it raises a SEPARATE class-A request under its own source '
            || 'key, with its own dedupe key and its own evidence — a different call, which looks '
            || 'like one.';
  end if;

  if v_class = 'D RETIRE_OR_HISTORICAL' then
    raise exception 'fn_kernel_source_emit: % is retired', p_source_key
      using errcode = '42501',
            hint = 'Retired means retired. If this source must live again it needs a row saying so, '
                || 'not a call.';
  end if;

  if v_ref is null then
    raise exception 'fn_kernel_source_emit: % supplied no source_ref', p_source_key
      using errcode = '22023',
            hint = 'source_ref is the external identity of the thing this is about — the inquiry '
                || 'id, the quote id, the transaction id. The idempotency key is built from it, '
                || 'and a key that is different every time is not a key.';
  end if;

  begin
    if v_class = 'A NEW_WORK_REQUEST' then
      v_out := public.fn_kernel_trigger_submit(jsonb_build_object(
        'source_class',    (select source_class from public.kernel_trigger_type
                             where trigger_type = v_vocab),
        'source_system',   p_source_key,
        'source_ref',      v_ref,
        'external_ref',    p_input->>'external_ref',
        'trigger_type',    v_vocab,
        'raw_payload',     coalesce(p_input->'raw_payload', '{}'::jsonb),
        'requested_by',    coalesce(nullif(btrim(p_input->>'requested_by'),''), v_actor),
        'object_version',  p_input->>'object_version',
        'priority',        p_input->>'priority',
        'idempotency_key', p_input->>'idempotency_key',
        'correlation_id',  p_input->>'correlation_id',
        'causation_id',    p_input->>'causation_id'));
    else
      -- K22b. There WAS a raise here for a NULL workflow_run_id, and it was wrong. A class-B
      -- source is a database trigger that fires on every row change; "this object has no live run
      -- right now" is the ordinary case, not a developer error, and raising turned it into a
      -- failed insert on quote_items and transactions. It is also not a silence to swallow:
      -- fn_kernel_signal_submit inserts the ledger row BEFORE it validates, so a signal with no
      -- run is recorded as a refused row carrying its reason — which is exactly what that table
      -- exists for. The check is deleted rather than moved: the door below already does it, and
      -- does it better.
      v_out := public.fn_kernel_signal_submit(jsonb_build_object(
        'source_type',     p_source_key,
        'source_id',       v_ref,
        'workflow_run_id', v_run,
        'signal_type',     v_vocab,
        'payload',         coalesce(p_input->'raw_payload', '{}'::jsonb),
        'requested_by',    coalesce(nullif(btrim(p_input->>'requested_by'),''), v_actor),
        'idempotency_key', p_input->>'idempotency_key',
        'correlation_id',  p_input->>'correlation_id',
        'causation_id',    p_input->>'causation_id'));
    end if;
  exception
    -- Deliberately narrow: the four raises above are the wrapper's own contract violations and
    -- must reach the developer, not be filed as a runtime fault. Everything else is a kernel
    -- fault, and a kernel fault must not stop a customer inserting an inquiry.
    when sqlstate '23503' or sqlstate '42501' or sqlstate '22023' then
      raise;
    when others then
      get diagnostics v_ctx = pg_context;
      insert into public.kernel_adapter_failure (source_key, input, sqlstate, message, call_stack)
      values (p_source_key, p_input, sqlstate, sqlerrm, v_ctx);
      return jsonb_build_object('ok', false, 'recorded_failure', true, 'source_key', p_source_key,
        'sqlstate', sqlstate, 'error', sqlerrm,
        'note', 'the kernel raised; the business row was not blocked and the fault is recorded in '
             || 'kernel_adapter_failure, where fn_kernel_source_emit_state fails while it is unresolved');
  end;

  return coalesce(v_out, '{}'::jsonb) || jsonb_build_object('source_key', p_source_key,
    'source_class', v_class, 'vocabulary', v_vocab, 'activation', v_active);
end

fn_kernel_outbox_refuse_cancelled_subjec:
declare v_why text;
begin
  -- Only the transition INTO delivered is guarded. Claiming, retrying and superseding are allowed.
  if new.status is distinct from 'delivered' or old.status = 'delivered' then
    return new;
  end if;

  select string_agg(x, '; ') into v_why from (
    select 'founder command ' || c.command_id || ' is ' || c.state as x
      from public.founder_command c
     where c.command_id = new.command_id and c.state in ('cancelled','superseded')
    union all
    select 'workflow run ' || r.run_id || ' is ' || r.state
      from public.phase_c_workflow_run r
     where r.run_id = new.workflow_run_id and r.state in ('cancelled','superseded')
    union all
    select 'step run ' || sr.step_run_id || ' is ' || sr.state
      from public.phase_c_workflow_step_run sr
     where sr.step_run_id = new.step_run_id and sr.state in ('cancelled','superseded')
    union all
    select 'task ' || t.task_id || ' is ' || t.state
      from public.phase_c_task t
     where t.task_id = new.task_id and t.state in ('cancelled','superseded')
  ) s;

  if v_why is null then
    return new;
  end if;

  new.status       := 'superseded';
  new.delivered_at := null;
  new.last_error   := 'DELIVERY REFUSED ' || to_char(now(),'YYYY-MM-DD HH24:MI') || ': '
                   || v_why || ' (fn_kernel_outbox_refuse_cancelled_subject). The event is kept as '
                   || 'the record that it was produced; it is not delivered, because the work it '
                   || 'describes has been cancelled.';
  return new;
end

fn_kernel_signal_type_activation_guard:
declare v_srcs text;
begin
  if new.activation_state = 'active' or new.activation_state = old.activation_state then
    return new;
  end if;
  select string_agg(c.source_component_id, ', ' order by c.source_component_id) into v_srcs
    from public.phase_c_source_cutover c
   where c.current_activation = 'ACTIVE' and c.target_step_or_signal = new.signal_type;
  if v_srcs is not null then
    raise exception
      'signal type %L cannot be moved to %L: % ACTIVE source(s) still point at it (%). Deactivate '
      'or repoint the source first — an active source pointing at an inactive type is refused at '
      'submission and reported as cut over, which is the defect root cause 3 closed.',
      new.signal_type, new.activation_state,
      (select count(*) from public.phase_c_source_cutover c
        where c.current_activation='ACTIVE' and c.target_step_or_signal = new.signal_type),
      v_srcs
      using errcode = '23514';
  end if;
  return new;
end

fn_kernel_source_signal_guard:
declare v_state text;
begin
  if new.current_activation <> 'ACTIVE' or new.source_class not like 'B %' then
    return new;
  end if;
  select t.activation_state into v_state
    from public.kernel_signal_type t where t.signal_type = new.target_step_or_signal;
  if v_state is null then
    raise exception
      'source % is ACTIVE and names signal type %L, which is not registered in kernel_signal_type. '
      'A signal the kernel has never heard of is refused at submission, so the source would be '
      'recorded as cut over while every delivery from it failed.',
      new.source_component_id, coalesce(new.target_step_or_signal,'(null)') using errcode = '23503';
  end if;
  if v_state <> 'active' then
    raise exception
      'source % is ACTIVE and names signal type %L, whose activation_state is %L. '
      'fn_kernel_signal_submit refuses every submission of an inactive type, so this source would '
      'be reported CUT_OVER while nothing it emits is ever accepted. Activate the type with a '
      'recorded reason, or set the source to DISABLED.',
      new.source_component_id, new.target_step_or_signal, v_state using errcode = '23514';
  end if;
  return new;
end

fn_kernel_system_execution_close:
declare
  t public.phase_c_trace%rowtype; v_comp public.phase_c_component%rowtype;
  v_result text := p_input->>'result';
  v_failure text := nullif(btrim(coalesce(p_input->>'failure','')), '');
  v_started timestamptz; v_finished timestamptz := coalesce(nullif(p_input->>'finished_at','')::timestamptz, now());
begin
  select * into t from public.phase_c_trace where trace_id = p_trace;
  if not found then
    raise exception 'fn_kernel_system_execution_close: trace % does not exist', p_trace using errcode = '23503';
  end if;
  if t.trace_policy_id <> 'TRACE-SYSTEM-EXECUTION' then
    raise exception 'fn_kernel_system_execution_close: trace % is on policy %, not TRACE-SYSTEM-EXECUTION',
      p_trace, t.trace_policy_id using errcode = '23514';
  end if;
  if exists (select 1 from public.phase_c_system_execution where trace_id = p_trace) then
    return p_trace;   -- already closed; closing twice is not a second execution
  end if;
  select * into v_comp from public.phase_c_component where component_id = t.component_id;

  if v_result <> all (array['succeeded','failed','refused','no_op']) then
    raise exception 'fn_kernel_system_execution_close: result % is not one of succeeded, failed, refused, no_op',
      coalesce(v_result,'(null)') using errcode = '23514';
  end if;
  if v_result = 'failed' and v_failure is null then
    raise exception 'fn_kernel_system_execution_close: result is failed and no failure was stated. '
      'A failure with no cause is the shape that lets an outage read as a quiet success.'
      using errcode = '23514';
  end if;
  if v_result <> 'failed' and v_failure is not null then
    raise exception 'fn_kernel_system_execution_close: result is % and a failure string was supplied. '
      'One of the two is wrong and the record may not carry both.', v_result using errcode = '23514';
  end if;

  v_started := coalesce(
    nullif(p_input->>'started_at','')::timestamptz,
    (t.evidence_refs->0->>'started_at')::timestamptz,
    t.created_at);

  update public.phase_c_trace set
    status       = 'sealed',
    sealed_at    = now(),
    state_after  = case when v_result = 'failed' then 'failed' else coalesce(nullif(p_input->>'state_after',''), v_result) end,
    output_hash  = coalesce(nullif(p_input->>'output_hash',''), md5(v_result || coalesce(v_failure,''))),
    authority_result = coalesce(nullif(p_input->>'authority_result',''), t.authority_result),
    evidence_refs = coalesce(t.evidence_refs,'[]'::jsonb) || jsonb_build_array(jsonb_build_object(
      'lifecycle', case when v_result = 'failed' then 'fail' else 'finish' end,
      'result', v_result, 'failure', v_failure,
      'sqlstate', p_input->>'sqlstate',
      'retry_eligible', coalesce((p_input->>'retry_eligible')::boolean, false),
      'finished_at', v_finished))
  where trace_id = p_trace;

  insert into public.phase_c_system_execution (
    trace_id, component_id, system_actor, accountable_role_id, workflow_id, step_id,
    technical_scope, trigger_source, authority_result, state_before, state_after, result,
    failure, correlation_id, causation_id, started_at, finished_at)
  values (
    p_trace, t.component_id, t.system_actor_id, t.actor_role_id,
    nullif(coalesce(p_input->>'workflow_id', coalesce(v_comp.workflow_id,'')),''),
    nullif(coalesce(p_input->>'step_id', coalesce(v_comp.step_id,'')),''),
    coalesce(nullif(p_input->>'technical_scope',''),
      case when coalesce(v_comp.workflow_id,'') = '' then
        'technical scope: kernel-owned execution registered as ' || t.component_id
        || ', which belongs to no one of the thirty Phase B workflows. Accountability is carried by '
        || 'the role, not by a workflow id it does not have.' end),
    coalesce(nullif(p_input->>'trigger_source',''), t.evidence_refs->0->>'trigger_source', 'unstated'),
    coalesce(nullif(p_input->>'authority_result',''), t.authority_result),
    coalesce(t.state_before, 'not_started'),
    case when v_result = 'failed' then 'failed' else coalesce(nullif(p_input->>'state_after',''), v_result) end,
    v_result, v_failure, coalesce(t.evidence_refs->0->>'correlation_id','unstated'),
    coalesce(t.evidence_refs->0->>'causation_id','unstated'), v_started, v_finished);

  return p_trace;
end

fn_kernel_system_execution_pair_guard:
declare t public.phase_c_trace%rowtype; e public.phase_c_system_execution%rowtype;
begin
  if tg_table_name = 'phase_c_trace' then
    select * into t from public.phase_c_trace where trace_id = new.trace_id;
    if not found then return null; end if;                      -- rolled back with its transaction
    if t.trace_policy_id <> 'TRACE-SYSTEM-EXECUTION' then return null; end if;

    -- RULE 6: the subject must identify the real execution, not an idempotency string.
    if t.subject_kind <> 'system_execution' then
      raise exception
        'trace % is on TRACE-SYSTEM-EXECUTION with subject_kind %L. The policy''s subject is a '
        'system execution; trace 3730 was written with subject_kind ''trigger_inbox'' and had no '
        'execution to point at. Use fn_kernel_intake_execution, or write the trace under the policy '
        'the subject actually has.', t.trace_id, t.subject_kind using errcode = '23514';
    end if;
    if t.subject_ref is distinct from t.component_id then
      raise exception
        'trace % names subject_ref %L and component %L. For a system execution the subject IS the '
        'component that ran; fn_kernel_signal_submit used to write ''signal:<id>'' here, which '
        'identifies a signal and not any execution.', t.trace_id, t.subject_ref, t.component_id
        using errcode = '23514';
    end if;

    -- RULE 4: sealed requires sealed_at.
    if t.status = 'sealed' and t.sealed_at is null then
      raise exception 'trace % is sealed with no sealed_at', t.trace_id using errcode = '23514';
    end if;

    -- RULE 1: a SEALED system-execution trace must have its execution row. An OPEN one must not —
    -- that is an execution in flight, and phase_c_system_execution is append-only so its row is
    -- written when the execution is over.
    if t.status = 'sealed'
       and not exists (select 1 from public.phase_c_system_execution se where se.trace_id = t.trace_id) then
      raise exception
        'trace % is a SEALED TRACE-SYSTEM-EXECUTION trace with no row in phase_c_system_execution. '
        'This is the exact shape of trace 3730. Close the execution with '
        'fn_kernel_system_execution_finish or _fail, which write the pair together.', t.trace_id
        using errcode = '23514';
    end if;
    return null;
  end if;

  -- phase_c_system_execution
  select * into e from public.phase_c_system_execution where trace_id = new.trace_id;
  if not found then return null; end if;
  select * into t from public.phase_c_trace where trace_id = e.trace_id;
  -- RULE 2: an execution cannot exist without a trace.
  if not found then
    raise exception
      'system execution on trace % has no trace row. An execution nobody can account for is the '
      'thing this policy exists to make impossible.', e.trace_id using errcode = '23503';
  end if;
  -- RULE 3: a terminal execution cannot have an open or incomplete trace.
  if e.result is not null and e.finished_at is not null
     and (t.status <> 'sealed' or t.sealed_at is null) then
    raise exception
      'system execution on trace % is terminal (result %L, finished) while its trace is %L with '
      'sealed_at %L. A finished execution whose trace is still open is a record that can still be '
      'rewritten after the fact.', e.trace_id, e.result, t.status, t.sealed_at using errcode = '23514';
  end if;
  return null;
end

fn_kernel_truncate_guard:
declare
  v_ctx    text;
  v_reason text;
  v_owner  text;
begin
  get diagnostics v_ctx = pg_context;

  -- There is no Door 1 here on purpose. No kernel routine truncates a protected table; a TRUNCATE
  -- is always maintenance, so the only door is the audited one the row guard already uses.
  v_reason := nullif(btrim(current_setting('kernel.maintenance_reason', true)), '');
  select tableowner into v_owner from pg_tables
   where schemaname = tg_table_schema and tablename = tg_table_name;
  if v_reason is not null and current_user = v_owner then
    perform public.fn_kernel_record_maintenance_write(
      current_user, session_user, tg_table_name, 'TRUNCATE', v_reason, v_ctx);
    return null;
  end if;

  raise exception
    'TRUNCATE on %.% is refused: a truncate is not a kernel write and fires no row-level guard.',
    tg_table_schema, tg_table_name
    using errcode = '42501',
          detail = 'Call stack was:' || chr(10) || v_ctx,
          hint = 'TRUNCATE removes every row without firing fn_kernel_write_guard, so it is '
              || 'refused outright. Historical maintenance needs BOTH a stated reason — set local '
              || 'kernel.maintenance_reason — AND the table owner, exactly as it does for an '
              || 'ordinary write, and it is recorded in kernel_maintenance_write either way.';
end

fn_kernel_all_boards:
declare
  b record;
begin
  for b in
    select p.proname as fn
      from pg_proc p
      join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.pronargs = 0
       and p.proargnames @> array['check_name','expected','actual','ok']
       -- IT DISCOVERED ITSELF. Written and applied without this line, and the first call recursed
       -- until the statement timeout killed it: this function returns exactly the shape it searches
       -- for, so it found itself, called itself, found itself again. Left as the reason the
       -- exclusion is by name rather than by a comment saying "don't add recursive boards".
       and p.proname <> 'fn_kernel_all_boards'
     order by p.proname
  loop
    board := b.fn;
    begin
      return query execute format(
        'select %L::text, x.check_name, x.expected, x.actual, x.ok from public.%I() x', b.fn, b.fn);
    exception when others then
      -- A BOARD THAT RAISES IS A FAILURE, NOT AN ABSENCE. fn_phase_c_invariants once raised 22007
      -- on every call after a column retype, which also took out fn_phase_c_baseline_drift. If that
      -- happens again it must read as red here rather than as a board that quietly returned nothing.
      check_name := 'BOARD_RAISED';
      expected   := 'the board returns rows';
      actual     := sqlstate || ' ' || sqlerrm;
      ok         := false;
      return next;
    end;
  end loop;
end

fn_phase_d_schema_validate:
declare
  sc public.phase_d_handler_schema%rowtype;
  v_missing text[];
  v_empty   text[];
  v_untyped text[];
  v_wrong   text[];
  v_badenum text[];
  v_unknown text[];
  v_known   text[];
begin
  select * into sc from public.phase_d_handler_schema where schema_id = p_schema_id;
  if not found then
    valid := false;
    reason := format('unknown schema %L — fail closed', p_schema_id);
    missing := '{}'; return next; return;
  end if;

  -- An absent payload is a refusal, never an empty pass. pct(got, 0) returning 100 is the shape
  -- of defect this avoids: no evidence is not full evidence.
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    valid := false;
    reason := format('schema %s expects an object, got %s',
                     p_schema_id, coalesce(jsonb_typeof(p_payload),'null'));
    missing := sc.required_keys; return next; return;
  end if;

  select array_agg(k order by k) into v_missing
    from unnest(sc.required_keys) k where not (p_payload ? k);
  if v_missing is not null then
    valid := false;
    reason := format('schema %s: required keys missing [%s]',
                     p_schema_id, array_to_string(v_missing, ', '));
    missing := v_missing; return next; return;
  end if;

  -- A key present and empty is the same absence wearing a different hat.
  select array_agg(k order by k) into v_empty
    from unnest(sc.required_keys) k
   where jsonb_typeof(p_payload->k) = 'null'
      or (jsonb_typeof(p_payload->k) = 'string' and btrim(p_payload->>k) = '')
      or (jsonb_typeof(p_payload->k) = 'array'  and jsonb_array_length(p_payload->k) = 0)
      or (jsonb_typeof(p_payload->k) = 'object' and p_payload->k = '{}'::jsonb);
  if v_empty is not null then
    valid := false;
    reason := format('schema %s: required keys present but empty [%s]',
                     p_schema_id, array_to_string(v_empty, ', '));
    missing := v_empty; return next; return;
  end if;

  -- ---- D46 (a) A KEY WITH NO RECORDED TYPE IS A BROKEN SCHEMA, NOT A PERMITTED ONE --------------
  -- If field_types does not mention a key the schema requires, the schema itself is refused. The
  -- alternative — treating an unstated type as "anything goes" — is how a missing declaration reads
  -- as a satisfied one.
  select array_agg(k order by k) into v_untyped
    from unnest(sc.required_keys) k where not (sc.field_types ? k);
  if v_untyped is not null then
    valid := false;
    reason := format('schema %s is incomplete: no declared type for [%s]. An unstated type is not an unconstrained one.',
                     p_schema_id, array_to_string(v_untyped, ', '));
    missing := v_untyped; return next; return;
  end if;

  -- ---- D46 (b) DECLARED TYPES ------------------------------------------------------------------
  select array_agg(format('%s expected %s got %s', k, sc.field_types->>k, jsonb_typeof(p_payload->k))
                   order by k)
    into v_wrong
    from unnest(sc.required_keys || coalesce(sc.optional_keys,'{}')) k
   where p_payload ? k
     and coalesce(sc.field_types->>k,'unconstrained') <> 'unconstrained'
     and jsonb_typeof(p_payload->k) is distinct from (sc.field_types->>k);
  if v_wrong is not null then
    valid := false;
    reason := format('schema %s: wrong types [%s]', p_schema_id, array_to_string(v_wrong, '; '));
    missing := '{}'; return next; return;
  end if;

  -- ---- D46 (c) DECLARED DOMAINS ----------------------------------------------------------------
  select array_agg(format('%s=%L is not one of [%s]', k, p_payload->>k,
                          (select string_agg(d, ', ')
                             from jsonb_array_elements_text(sc.enum_domains->k) d))
                   order by k)
    into v_badenum
    from jsonb_object_keys(sc.enum_domains) k
   where p_payload ? k
     and not (sc.enum_domains->k @> to_jsonb(p_payload->>k));
  if v_badenum is not null then
    valid := false;
    reason := format('schema %s: outside the declared domain [%s]',
                     p_schema_id, array_to_string(v_badenum, '; '));
    missing := '{}'; return next; return;
  end if;

  -- ---- D46 (d) UNKNOWN KEYS, WHERE THE CONTRACT IS CLOSED --------------------------------------
  if not coalesce(sc.additional_properties, true) then
    v_known := sc.required_keys || coalesce(sc.optional_keys, '{}');
    select array_agg(k order by k) into v_unknown
      from jsonb_object_keys(p_payload) k where not (k = any (v_known));
    if v_unknown is not null then
      valid := false;
      reason := format('schema %s declares a closed contract and the payload carries [%s]',
                       p_schema_id, array_to_string(v_unknown, ', '));
      missing := '{}'; return next; return;
    end if;
  end if;

  valid := true;
  reason := format('payload satisfies %s v%s (%s keys, %s typed, %s domain(s), %s, source digest %s)',
                   p_schema_id, sc.schema_version, cardinality(sc.required_keys),
                   (select count(*) from jsonb_each_text(sc.field_types) t
                     where t.value <> 'unconstrained'),
                   (select count(*) from jsonb_object_keys(sc.enum_domains)),
                   case when coalesce(sc.additional_properties,true)
                        then 'open to further keys' else 'closed' end,
                   left(sc.source_digest,12));
  missing := '{}'; return next;
end

fn_phase_d_handler_state:
declare n_steps int; n_bound int; n_amb int; n_sch int; n_drift int; n_blocked int; n_def int;
        n_produced int;
        n_wired int; n_needwrite int;
begin
  select count(*) into n_steps from public.phase_b_workflow_step;
  select count(*) into n_bound from public.phase_d_handler_binding;

  check_name := 'every_frozen_step_has_a_handler_binding';
  expected := n_steps::text; actual := n_bound::text; ok := (n_bound = n_steps); return next;

  select count(*) into n_amb from public.phase_d_handler_binding b
   where not exists (select 1 from public.phase_b_workflow_step s where s.step_id = b.step_id);
  check_name := 'no_binding_for_an_unfrozen_step';
  expected := '0'; actual := n_amb::text; ok := (n_amb = 0); return next;

  select count(*) into n_sch from public.phase_d_handler_schema;
  check_name := 'two_schemas_per_step';
  expected := (n_steps * 2)::text; actual := n_sch::text; ok := (n_sch = n_steps * 2); return next;

  select count(*) into n_drift from public.phase_d_handler_schema sc
    join public.phase_b_workflow_step s on s.step_id = sc.step_id
   where sc.source_digest <> encode(sha256(convert_to(
           case sc.schema_kind
             when 'input' then coalesce(s.required_inputs,'')
             else coalesce(s.required_output,'') || ' || ' || coalesce(s.acceptance_criteria,'')
           end, 'UTF8')), 'hex');
  check_name := 'no_schema_drift_against_frozen_phase_b';
  expected := '0'; actual := n_drift::text; ok := (n_drift = 0); return next;

  select count(*) into n_blocked from public.phase_d_handler_binding
   where phase_d_status = 'BLOCKED_DEFECT';
  check_name := 'blocked_defects';
  expected := '0'; actual := n_blocked::text; ok := (n_blocked = 0); return next;

  select count(*) into n_def
    from public.phase_d_handler_binding b
    join public.kernel_retired_path rp
      on b.handler_routine like '%' || rp.path_name || '%'
   where rp.disposition = 'DISABLED';
  check_name := 'no_binding_names_a_retired_routine';
  expected := '0'; actual := n_def::text; ok := (n_def = 0); return next;

  -- THE HONEST ONE. Red until a handler actually writes its business object. This check exists
  -- so the 236 NEW_DETERMINISTIC_HANDLER rows cannot be read as 236 steps with a business effect.
  --
  -- Counted as the GAP, not as the coverage, so the number FALLS as the work lands and the
  -- kernel-boards ratchet can cap it. A check reading "0 of 257 wired" would have to be ratcheted
  -- at a number that must grow, which the ratchet cannot express and which would invert its
  -- meaning: it asserts disclosed debt does not get worse.
  select count(*) into n_wired from public.phase_d_handler_binding where business_write_wired;
  select count(*) into n_needwrite from public.phase_d_handler_binding;
  -- E20 / finding 10. RENAMED TO WHAT IT COMPUTES. It reads business_write_wired, a stored boolean
  -- that records a binding DECLARING a business write. A declaration is not a write, and a check
  -- whose name says "not writing" while its body counts a column asserts something untrue about
  -- itself. E10 added a comment saying so; the name still said the other thing.
  check_name := 'handler_bindings_that_declare_no_business_write';
  expected := '0'; actual := (n_needwrite - n_wired)::text
           || ' of ' || n_needwrite::text || ' (source: phase_d_handler_binding.business_write_wired, '
           || 'a declaration; see handlers_that_have_actually_produced_an_effect below for writes)';
  ok := (n_needwrite - n_wired = 0); return next;

  -- E10. WHAT THAT ZERO IS, AND WHAT IT IS NOT. It is derived from the handler's declared call to
  -- fn_phase_d_effect_produce plus a stored boolean — a statement that the PATH EXISTS. It is not a
  -- statement that any handler has ever written a business object, and the two read identically at
  -- a glance because both are the number 0 beside a green tick.
  -- The question it does not answer is on fn_phase_d_effect_state as
  -- steps_with_no_effect_ever_produced, which reads 257 and is this phase's only red. Both numbers
  -- are quoted here so a reader of this board cannot take the green one for the other.
  select count(distinct step_id) into n_produced from public.phase_d_effect_ledger;

  check_name := 'handlers_that_have_actually_produced_an_effect';
  expected := 'informational — the green above says the path EXISTS, this says whether it has RUN';
  actual := n_produced::text || ' of ' || n_steps::text
         || ' steps have ever produced an effect; see fn_phase_d_effect_state.'
         || 'steps_with_no_effect_ever_produced for what holds the remainder';
  ok := true; return next;
end

fn_phase_d_rule_applies:
declare
  r public.phase_b_business_rule%rowtype;
  s public.phase_b_workflow_step%rowtype;
  e public.phase_d_rule_enforcement%rowtype;
  v_in_scope boolean;
  v_governs text;
  v_primary text;
  v_producer text;   -- K06
begin
  select * into r from public.phase_b_business_rule where rule_id = p_rule_id;
  if not found then
    applies := false; why := format('unknown rule %L', p_rule_id); return next; return;
  end if;
  select * into s from public.phase_b_workflow_step where step_id = p_step_id;
  if not found then
    applies := false; why := format('unknown step %L', p_step_id); return next; return;
  end if;
  select * into e from public.phase_d_rule_enforcement where rule_id = p_rule_id;

  -- 1. WORKFLOW SCOPE, from the frozen registry.
  v_in_scope := (lower(r.workflow_scope) = 'all'
                 or s.workflow_id = any (string_to_array(replace(r.workflow_scope,' ',''), ';')));
  if not v_in_scope then
    applies := false;
    why := format('%s is scoped to %s and %s is in %s', r.rule_id, r.workflow_scope, p_step_id, s.workflow_id);
    return next; return;
  end if;

  -- 2. STEP-LEVEL APPLICABILITY. Scope is not applicability, and conflating the two is what made
  --    the first executor refuse an intake step for a creator/reviewer collision.
  if p_rule_id in ('BR-002','BR-030','BR-031','BR-037','BR-038') then
    if coalesce(btrim(s.independent_reviewer_role_id),'') = '' then
      applies := false;
      why := format('%s governs the independence of a named reviewer and %s names none', r.rule_id, p_step_id);
      return next; return;
    end if;
  end if;

  if p_rule_id = 'BR-003' then
    if lower(coalesce(btrim(s.founder_gate),'none')) = 'none' then
      applies := false;
      why := format('BR-003 governs founder-reserved decisions and %s declares founder_gate none', p_step_id);
      return next; return;
    end if;
  end if;

  if p_rule_id = 'BR-009' and not coalesce(s.is_closure_step,false) then
    applies := false;
    why := format('BR-009 is a closure rule and %s is not the closure step', p_step_id);
    return next; return;
  end if;

  if p_rule_id = 'BR-042' and s.step_type <> 'analysis' then
    applies := false;
    why := format('BR-042 governs analysis output and %s is a %s step', p_step_id, s.step_type);
    return next; return;
  end if;

  if p_rule_id = 'BR-040' and s.step_type <> 'measurement' then
    applies := false;
    why := format('BR-040 governs metric definition and %s is a %s step', p_step_id, s.step_type);
    return next; return;
  end if;

  if p_rule_id = 'BR-044'
     and not exists (select 1 from public.phase_b_handoff h where h.from_step_id = p_step_id) then
    applies := false;
    why := format('BR-044 governs a step that opens a handoff and %s opens none', p_step_id);
    return next; return;
  end if;

  -- D50. BR-008 governs the CONTENTS OF A HANDOFF PACKET, so it can only apply to a step that opens
  -- one. Until D47 it fell through to ENFORCED_PASS and could not fail; giving it a real predicate
  -- without giving it this applicability rule turned it into the opposite defect — it refused 29 of
  -- the 30 workflows' first steps for not carrying a packet no handoff had asked for. The condition
  -- is the same one BR-044 already uses, and it is used here for the same reason.
  if p_rule_id = 'BR-008'
     and not exists (select 1 from public.phase_b_handoff h where h.from_step_id = p_step_id) then
    applies := false;
    why := format('BR-008 governs the packet a handoff carries and %s opens no handoff', p_step_id);
    return next; return;
  end if;

  -- 3. A RULE DOES NOT GOVERN THE WORKFLOW THAT PRODUCES ITS SUBJECT.
  if e.required_context is not null and cardinality(e.required_context) > 0 then
    select st.object_id into v_governs
      from public.phase_d_fixture_stage st
     where st.contributes_ref = any(e.required_context)
     limit 1;
    if v_governs is not null then
      -- K06. A WORKFLOW PRODUCES MORE THAN ITS PRIMARY OBJECT. This compared the rule's subject
      -- with phase_b_workflow.primary_object alone, so BR-018 asked W14 to already hold the
      -- quotation revision W14 exists to produce, and BR-032 asked W16 to already hold the provider
      -- event W16-S03 receives. The producing step is read from the frozen effect registry; the
      -- primary object is still reported in the reason when it is the one that matched.
      select w.primary_object into v_primary
        from public.phase_b_workflow w where w.workflow_id = s.workflow_id;
      select min(x.step_id) into v_producer
        from public.phase_d_step_effect x
       where x.workflow_id = s.workflow_id and x.effect_object_id = v_governs;
      if (v_primary is not null and v_primary = v_governs) or v_producer is not null then
        applies := false;
        why := format('%s governs %s and %s is the workflow that produces it (%s); the rule guards its use downstream, not its creation',
                      r.rule_id, v_governs, s.workflow_id,
                      coalesce('first produced at ' || v_producer, 'primary_object ' || v_primary));
        return next; return;
      end if;
    end if;
  end if;

  applies := true;
  why := format('%s (%s, %s) applies to %s: in scope %s%s', r.rule_id, r.rule_type,
                coalesce(e.enforcement_kind,'UNREGISTERED'), p_step_id, r.workflow_scope,
                case when e.status = 'OUTSTANDING'
                     then ' — enforcement OUTSTANDING, pending the D2 object map' else '' end);
  return next;
end

fn_phase_d_rule_state:
declare n_rules int; n_reg int; n_out int; n_unres int; n_alwaystrue int;
        n_can int; n_deleg int; n_held int; n_exec int;
begin
  select count(*) into n_rules from public.phase_b_business_rule;
  select count(*) into n_reg   from public.phase_d_rule_enforcement;

  check_name := 'every_frozen_rule_has_an_enforcement_row';
  expected := n_rules::text; actual := n_reg::text; ok := (n_reg = n_rules); return next;

  -- A named mechanism that does not exist is prose. Every enforcement_point naming a public
  -- routine is resolved in pg_proc; the two naming a table are resolved in pg_class.
  select count(*) into n_unres from public.phase_d_rule_enforcement e
   where e.enforcement_point like 'public.fn_%'
     and not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
                      where n.nspname = 'public'
                        and p.proname = split_part(split_part(e.enforcement_point,'.',2),'(',1));
  check_name := 'every_named_enforcement_routine_resolves';
  expected := '0'; actual := n_unres::text; ok := (n_unres = 0); return next;

  select count(*) into n_out from public.phase_d_rule_enforcement where status = 'OUTSTANDING';
  check_name := 'rules_with_outstanding_enforcement';
  expected := '0'; actual := n_out::text; ok := (n_out = 0); return next;

  -- The regression guard: the routine this replaced ended with an unconditional ok := true.
  select count(*) into n_alwaystrue
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
   where n.nspname = 'public' and p.proname = 'fn_phase_d_rule_check'
     and pg_get_functiondef(p.oid) !~ 'rule_unregistered';
  check_name := 'rule_check_refuses_an_unregistered_rule';
  expected := '0'; actual := n_alwaystrue::text; ok := (n_alwaystrue = 0); return next;

  -- ---- E10. WHAT "ENFORCED" MEANS ON THIS BOARD, SAID BESIDE THE NUMBER ----------------------
  -- rules_with_outstanding_enforcement counts phase_d_rule_enforcement.status, which is ENFORCED on
  -- all 54. That is a statement about a declared MECHANISM. It is not a statement about whether the
  -- predicate can produce a refusal, and the two were being read as one.
  -- fn_phase_d_rule_can_refuse() already answers the harder question by driving each rule against
  -- three probe contexts. Its answer has never been on this board. It is now, as disclosure rows:
  -- the mechanism count does not move, and a reader can no longer take 54/54 for 54 that refuse.
  select count(*) into n_can from public.fn_phase_d_rule_can_refuse() where can_refuse;
  check_name := 'rules_whose_predicate_can_actually_refuse';
  expected := 'informational — 54/54 ENFORCED is a mechanism count, not this';
  actual := n_can::text || ' of ' || n_reg::text
         || ' produce ENFORCED_FAIL on at least one of the three probe contexts';
  ok := true; return next;

  select count(*) into n_deleg from public.fn_phase_d_rule_can_refuse()
   where not can_refuse and note like 'delegated%';
  check_name := 'rules_the_kernel_guard_decides_not_the_predicate';
  expected := 'informational — enforced, and not by anything this predicate can invoke';
  actual := n_deleg::text || ' rule(s) delegated to a kernel guard';
  ok := true; return next;

  select count(*) into n_held from public.fn_phase_d_rule_can_refuse()
   where not can_refuse and note like 'constant%';
  check_name := 'rules_constant_while_a_founder_hold_stands';
  expected := 'informational — the founder''s to lift, not a defect';
  actual := n_held::text || ' rule(s) cannot vary while the provider hold stands';
  ok := true; return next;

  select count(*) into n_exec from public.fn_phase_d_rule_can_refuse()
   where not can_refuse and note not like 'delegated%' and note not like 'constant%';
  check_name := 'rules_enforced_somewhere_other_than_the_predicate';
  expected := 'informational';
  actual := n_exec::text || ' rule(s) enforced at the executor''s capability boundary';
  ok := true; return next;

  -- The four groups must still account for every registered rule. A decomposition that stops
  -- covering its subject is worse than none: the parts would sum to fewer than the whole and
  -- nothing would say so.
  check_name := 'every_registered_rule_carries_a_refusal_class';
  expected := n_reg::text; actual := (n_can + n_deleg + n_held + n_exec)::text;
  ok := (n_can + n_deleg + n_held + n_exec = n_reg); return next;
end

fn_phase_d_object_policy_guard:
declare v_family text;
begin
  -- Pinned lookup. A trigger runs with the WRITER's search_path, so an unqualified read here
  -- could be answered by a table the caller shadowed.
  select b.policy_family into v_family
    from public.phase_d_business_object_binding b
   where b.object_id = coalesce(new.object_id, old.object_id);

  if v_family is null then
    raise exception 'phase_d_object_record: object % has no Phase D binding — fail closed rather than store a record under a policy nobody declared',
      coalesce(new.object_id, old.object_id) using errcode = '23503';
  end if;

  if tg_op = 'DELETE' then
    raise exception 'phase_d_object_record: % is a % object and business records are never deleted. Cancellation preserves the record, its reason and its authority (BR-046). (pd_object_delete_refused)',
      old.object_id, v_family using errcode = '23514';
  end if;

  if tg_op = 'UPDATE' then
    -- The ONLY update any family permits is the supersession pointer being set once, plus the
    -- state moving. Everything that carries the business fact is frozen on write.
    if new.object_id  is distinct from old.object_id
       or new.business_key is distinct from old.business_key
       or new.version   is distinct from old.version
       or new.payload   is distinct from old.payload
       or new.owner_scope is distinct from old.owner_scope
       or new.owner_ref is distinct from old.owner_ref
       or new.created_by is distinct from old.created_by
       or new.created_at is distinct from old.created_at then
      raise exception 'phase_d_object_record: record % belongs to % (%). Its identity, owner and payload are frozen on write; a change creates a NEW version and supersedes this one. (pd_object_overwrite_refused)',
        old.record_id, old.object_id, v_family using errcode = '23514';
    end if;
    if old.superseded_by is not null and new.superseded_by is distinct from old.superseded_by then
      raise exception 'phase_d_object_record: record % is already superseded by % and a supersession pointer is written once. (pd_object_resupersede_refused)',
        old.record_id, old.superseded_by using errcode = '23514';
    end if;
    if v_family = 'APPEND_ONLY' and new.state is distinct from old.state then
      raise exception 'phase_d_object_record: % is APPEND_ONLY (%); even its state does not move after write. A correction is a new record. (pd_object_append_only)',
        old.object_id, (select record_policy from public.phase_d_business_object_binding
                         where object_id = old.object_id) using errcode = '23514';
    end if;
  end if;

  return new;
end

fn_phase_d_object_write:
declare
  b            public.phase_d_business_object_binding%rowtype;
  wm           public.phase_d_object_write_map%rowtype;
  v_object     text  := nullif(btrim(coalesce(p_input->>'object_id','')),'');
  v_key        text  := nullif(btrim(coalesce(p_input->>'business_key','')),'');
  v_owner_ref  text  := nullif(btrim(coalesce(p_input->>'owner_ref','')),'');
  v_payload    jsonb := p_input->'payload';
  v_actor      text  := nullif(btrim(coalesce(p_input->>'created_by','')),'');
  v_state      text  := coalesce(nullif(btrim(p_input->>'state'),''), 'open');
  v_state_given text := nullif(btrim(p_input->>'state'),'');   -- H02: what the caller actually said
  v_unchanged  boolean := false;                               -- H02: a confirmation, not a write
  v_prior      public.phase_d_object_record%rowtype;
  v_version    integer := 1;
  v_id         bigint;
  v_readback   public.phase_d_object_record%rowtype;
  v_cols       text[] := '{}';
  v_vals       text[] := '{}';
  v_sets       text[] := '{}';
  v_col        record;
  v_expr       text;
  v_existing   text;
  v_result_ref text;
  v_sql        text;
  v_supplied   jsonb;
  -- D17: the outbound door.
  v_testctx    boolean := public.fn_phase_d_fixture_context() is not null;
  v_door       record;
  v_door_val   jsonb;
  v_net_max    bigint;
  v_net_new    bigint;
  v_net_urls   text;
  -- K02: the parent the object declares.
  v_parent_src text;
  -- D18: identity resolution for UPSERT_STATE.
  v_ident_val  text;
  v_uq         record;
  v_where      text;
begin
  if v_object is null or v_key is null or v_actor is null then
    raise exception 'fn_phase_d_object_write: object_id, business_key and created_by are all required (got %, %, %) (pd_object_input_invalid)',
      coalesce(v_object,'(null)'), coalesce(v_key,'(null)'), coalesce(v_actor,'(null)')
      using errcode = '22023';
  end if;

  select * into b from public.phase_d_business_object_binding where object_id = v_object;
  if not found then
    raise exception 'fn_phase_d_object_write: % is not a bound Phase D business object — fail closed rather than store a record under a policy nobody declared (pd_object_unbound)',
      v_object using errcode = '23503';
  end if;

  if v_payload is null or jsonb_typeof(v_payload) <> 'object' or v_payload = '{}'::jsonb then
    raise exception 'fn_phase_d_object_write: % sent payload of type %. An empty object is not evidence that anything was recorded. (pd_object_payload_empty)',
      v_object, coalesce(jsonb_typeof(v_payload),'null') using errcode = '22023';
  end if;

  if v_owner_ref is null then
    raise exception 'fn_phase_d_object_write: % is %-scoped and the call names no owner_ref. An unowned business record is the accountability gap this map exists to close. (pd_object_owner_missing)',
      v_object, b.ownership_scope using errcode = '22023';
  end if;

  -- ================= EXISTING TABLE: a real write, through the declared map =================
  if b.relation_kind = 'EXISTING_TABLE' then
    -- THE KERNEL'S OWN TABLES ARE NOT WRITABLE FROM HERE, AND THIS IS THE POINT OF THE BRANCH.
    -- workflow_run, workflow_step_run and handoff_record are created and moved by
    -- fn_kernel_step_complete. Two creators for one object is what deadlocked 16 of 30 workflows
    -- when workflow_start and step_complete both made the same handoff run; it is not repeated
    -- here because a handler asked politely.
    if b.governing_workflow_id = 'ALL' and v_object <> 'review_record' then
      raise exception 'fn_phase_d_object_write: % is written by the frozen kernel (%). A Phase D handler that wrote it would be a second creator for one object. Use fn_kernel_step_complete. (pd_object_kernel_owned)',
        v_object, b.canonical_relation using errcode = '23514';
    end if;

    select * into wm from public.phase_d_object_write_map where object_id = v_object;
    if not found then
      raise exception 'fn_phase_d_object_write: % is bound to existing relation % and no write map is declared for it. Refusing to guess a column layout. (pd_object_no_write_map)',
        v_object, b.canonical_relation using errcode = '23503';
    end if;

    -- The payload the caller actually sent, plus the four facts every write carries. state and
    -- owner_ref are named here so a map can point a column at either without the caller repeating
    -- them; nothing else is defaulted.
    -- H02 (1). NO STATE THE CALLER DID NOT STATE. An insert takes the relation's default and an
    -- update leaves the column alone; a stated state for a relation whose map carries no state
    -- column is refused rather than dropped on the floor.
    -- H09. A stated state the map cannot carry is reported on the return, not refused: review_record
    -- carries its verdict as content and has never had a state column.
    v_supplied := v_payload
                  || jsonb_build_object('owner_ref', v_owner_ref, 'business_key', v_key)
                  || case when v_state_given is null then '{}'::jsonb
                          else jsonb_build_object('state', v_state_given) end;

    -- D17. OUTBOUND SUPPRESSION, IN TEST CONTEXT ONLY, THROUGH EACH TRIGGER'S OWN GUARD.
    -- In production this loop does not run: a real Phase D handler dispatching a real inquiry is
    -- the intended behaviour and must not be suppressed. Under the Phase D hold the writer sets
    -- the product's own already-done marker, and a caller that supplied one keeps it.
    if v_testctx then
      for v_door in
        select d.guard_column, d.suppression_sql
          from public.phase_d_outbound_door d
         where d.relation = wm.target_relation
           and d.disposition = 'SUPPRESSED_BY_ITS_OWN_GUARD'
      loop
        -- D19. THE SUPPRESSION IS NOT DEFEASIBLE BY THE CALLER.
        --
        -- This was `if not (v_supplied ? guard_column)` — respect a value the caller supplied.
        -- Adding `routing` to the inquiry write map in D17 made the DRIVER's payload builder start
        -- generating a value for it, because it invents a typed value for every declared column.
        -- The generated jsonb carried no dispatched_at, the injection stood aside for it, and
        -- W05-S01 POSTed dispatch_inquiry again. A harness that generates a value for the key the
        -- guard reads is the same defect D9 recorded as "a generated fixture beat the real
        -- reference", and here it silently re-armed a door the writer had just closed.
        --
        -- Under the Phase D hold a caller does not get to opt out, so the writer overwrites. Both
        -- registered guard columns were measured as read by nothing: 0 rules, 0 gate contracts,
        -- 0 references in fn_rfq_score / fn_rfq_required_check. Overwriting them changes no
        -- decision any workflow makes; leaving them writable changes whether a POST leaves the
        -- database.
        execute format('select %s', v_door.suppression_sql) into v_door_val;
        v_supplied := v_supplied || jsonb_build_object(v_door.guard_column, v_door_val);
      end loop;
    end if;

    -- K02. AN ORPHAN IS REFUSED BY NAME. Where the object's binding declares a parent identity,
    -- the write map maps a column of that name, and this call supplies no value for it, the row
    -- about to be written belongs to nothing. Issuing it can only end in a silent BEFORE-trigger
    -- skip -- which is exactly how W12-S06 lost its effect -- or a foreign-key error two layers
    -- down. A NOT NULL column is left to the relation's own 23502; this covers the nullable ones,
    -- which is where the hole was.
    select wm.column_map->>b.parent_identity into v_parent_src
      from pg_attribute a
     where a.attrelid = wm.target_relation::regclass
       and a.attname = b.parent_identity and a.attnum > 0 and not a.attnotnull
       and coalesce(btrim(b.parent_identity),'') <> ''
       and wm.column_map ? b.parent_identity;
    if v_parent_src is not null
       and v_parent_src not in ('business_key','owner_ref','state')
       and (not (v_supplied ? v_parent_src) or v_supplied->v_parent_src = 'null'::jsonb) then
      raise exception 'fn_phase_d_object_write: % declares parent identity %, the write map reads it from payload key %, and this call supplies none. A % row that belongs to no % is not a business record. (pd_object_parent_missing)',
        v_object, b.parent_identity, v_parent_src, wm.target_relation, b.parent_identity
        using errcode = '23502';
    end if;

    for v_col in
      select k.key as col, wm.column_map->>k.key as src,
             format_type(a.atttypid, a.atttypmod) as ftype,
             (select typcategory from pg_type ty where ty.oid = a.atttypid) as tcat,
             a.attidentity, a.attgenerated
        from jsonb_each(wm.column_map) k
        join pg_attribute a
          on a.attrelid = wm.target_relation::regclass and a.attname = k.key and a.attnum > 0
       order by k.key
    loop
      -- A GENERATED ALWAYS identity or generated column cannot be written. The map validator
      -- excludes them from "required"; this excludes them from the statement.
      if v_col.attidentity = 'a' or v_col.attgenerated <> '' then continue; end if;
      if not (v_supplied ? v_col.src) then continue; end if;

      v_expr := case
        when v_col.ftype = 'jsonb' or v_col.ftype = 'json' then
          format('($1->%L)', v_col.src)
        when v_col.tcat = 'A' then
          format('(select coalesce(array_agg(x::text),''{}'')::%s from jsonb_array_elements_text($1->%L) x)',
                 v_col.ftype, v_col.src)
        else
          format('($1->>%L)::%s', v_col.src, v_col.ftype)
      end;
      v_cols := v_cols || quote_ident(v_col.col);
      v_vals := v_vals || v_expr;
      if v_col.col <> wm.key_column then
        v_sets := v_sets || format('%I = %s', v_col.col, v_expr);
      end if;
    end loop;

    if cardinality(v_cols) = 0 then
      raise exception 'fn_phase_d_object_write: % supplied no column the write map for % can use. Payload keys were %. (pd_object_payload_unmapped)',
        v_object, wm.target_relation,
        coalesce((select string_agg(k,', ' order by k) from jsonb_object_keys(v_supplied) k),'(none)')
        using errcode = '22023';
    end if;

    -- D17. The high-water mark, taken immediately before the write. Counting rows with a HIGHER id
    -- afterwards rather than differencing two counts is deliberate: pg_net's worker DELETES rows it
    -- has processed, so a plain count delta can be masked to zero by a concurrent drain and report
    -- silence over two real POSTs.
    if v_testctx then
      select coalesce(max(id),0) into v_net_max from net.http_request_queue;
    end if;

    -- K04. THE IDENTITY PROBE RUNS FOR AN INSERT TOO. An INSERT that would violate a unique
    -- index on values this call supplies is not a new record: it is the record that already exists.
    -- W16-S05 collided on reveal_invoices_pkey because operation INSERT skipped the probe entirely
    -- and the scenario had already issued the invoice for that transaction. For an INSERT the
    -- existing reference is returned and NOTHING is updated -- see the branch below -- so an
    -- immutable_revision object is never rewritten by a replay.
    if wm.operation in ('UPSERT_STATE', 'INSERT') then
      -- D18. AN UPSERT MUST LOOK FOR THE ROW IT WOULD WRITE, NOT FOR A DIFFERENT ONE.
      --
      -- This probe used to be `where key_column::text = business_key` unconditionally, which is
      -- only correct when the map points key_column at business_key. Two shapes broke on it:
      --
      --   supplier_capability  key_column = supplier_id, column_map.supplier_id = 'owner_ref'
      --                        -> probed supplier_id = <business key>, INSERTED supplier_id =
      --                           <owner ref>. It read one value and wrote another, so it could
      --                           never find its own row and the second write died on the pkey.
      --
      --   quotation / payment_transaction   key_column = id, a generated bigint
      --                        -> probed a bigint id against a uuid business key, never matched,
      --                           always inserted, and collided on the relation's NATURAL key
      --                           (quotes(inquiry_id,supplier_id), transactions(quote_id)).
      --
      -- Identity is now resolved in two derived passes and nothing is hand-listed:
      --   1. key_column, using THE VALUE THAT WILL BE WRITTEN INTO IT.
      --   2. failing that, any other unique index on the relation whose columns are ALL declared
      --      in the map and ALL supplied by this call — the row's natural key. The index's own
      --      predicate is carried through verbatim from pg_get_expr, so a PARTIAL unique index
      --      such as transactions(quote_id) WHERE quote_id IS NOT NULL is matched on exactly the
      --      rows it actually constrains rather than on a guess about what the predicate means.
      --
      -- Where neither pass resolves an identity the write stays an INSERT and a unique violation
      -- remains a real business duplicate. That is reported by fn_phase_d_object_identity_state()
      -- rather than papered over.
      v_existing := null;

      if wm.column_map ? wm.key_column then
        v_ident_val := v_supplied->>(wm.column_map->>wm.key_column);
        if v_ident_val is not null then
          v_sql := format('select %I::text from %s where %I::text = $1 limit 1',
                          wm.key_column, wm.target_relation, wm.key_column);
          execute v_sql into v_existing using v_ident_val;
        end if;
      end if;

      -- H02 (2). THE CALLER'S KEY IS THE RELATION'S KEY when the map writes no key column: probe it
      -- as text, which matches nothing when the shapes differ and the row when they do not.
      if v_existing is null and not (wm.column_map ? wm.key_column) then
        begin
          v_sql := format('select %I::text from %s where %I::text = $1 limit 1',
                          wm.key_column, wm.target_relation, wm.key_column);
          execute v_sql into v_existing using v_key;
        exception when others then
          v_existing := null;
        end;
      end if;

      if v_existing is null then
        for v_uq in
          select ic.relname as idx_name,
                 array_agg(a.attname::text order by a.attnum) as cols,
                 min(pg_get_expr(i.indpred, i.indrelid)) as pred
            from pg_index i
            join pg_class ic on ic.oid = i.indexrelid
            join pg_attribute a on a.attrelid = i.indrelid and a.attnum = any(i.indkey)
           where i.indrelid = wm.target_relation::regclass
             and i.indisunique
           group by ic.relname, i.indexrelid
           order by ic.relname
        loop
          -- an index on exactly the key column is pass 1's job, and it already ran
          continue when v_uq.cols = array[wm.key_column];
          continue when not (select bool_and(wm.column_map ? c) from unnest(v_uq.cols) c);
          continue when not (select bool_and(v_supplied ? (wm.column_map->>c)) from unnest(v_uq.cols) c);
          continue when exists (select 1 from unnest(v_uq.cols) c
                                 where v_supplied->>(wm.column_map->>c) is null);

          select string_agg(format('%I::text = ($1->>%L)', c, wm.column_map->>c), ' and ')
            into v_where from unnest(v_uq.cols) c;
          if v_uq.pred is not null then
            v_where := v_where || ' and (' || v_uq.pred || ')';
          end if;

          v_sql := format('select %I::text from %s where %s limit 1',
                          wm.key_column, wm.target_relation, v_where);
          execute v_sql into v_existing using v_supplied;
          exit when v_existing is not null;
        end loop;
      end if;
      if v_existing is not null then
        -- K04. AN INSERT NEVER UPDATES WHAT IT FOUND. The row already exists under the identity
        -- this call carries; that is the declared completion condition met, not a second record and
        -- not a rewrite of the first.
        if wm.operation = 'INSERT' or cardinality(v_sets) = 0 then
          -- H02 (3). The row already carries everything this call asked for. That is the declared
          -- completion condition of an OBJECT_STATE_WRITE met, not a transition refused: the
          -- existing reference is returned, nothing is written, and unchanged = true says so.
          v_unchanged := true;
          v_result_ref := v_existing;
        end if;
        -- D18. Update the row the probe actually FOUND. Re-deriving the target from business_key
        -- here would reintroduce the same mismatch one statement later: the natural-key probe can
        -- resolve a row whose key_column value equals neither the business key nor anything in the
        -- payload.
        if not v_unchanged then
          v_sql := format('update %s set %s where %I::text = $2 returning %I::text',
                          wm.target_relation, array_to_string(v_sets, ', '),
                          wm.key_column, wm.key_column);
          execute v_sql into v_result_ref using v_supplied, v_existing;
        end if;
      else
        v_sql := format('insert into %s (%s) values (%s) returning %I::text',
                        wm.target_relation, array_to_string(v_cols, ', '),
                        array_to_string(v_vals, ', '), wm.key_column);
        execute v_sql into v_result_ref using v_supplied;
      end if;
    else
      v_sql := format('insert into %s (%s) values (%s) returning %I::text',
                      wm.target_relation, array_to_string(v_cols, ', '),
                      array_to_string(v_vals, ', '), wm.key_column);
      execute v_sql into v_result_ref using v_supplied;
    end if;

    -- A NULL RETURN IS NOT A WRITE. A BEFORE trigger returning NULL gives a statement that
    -- "succeeded" with no row; the returned key is what separates the two.
    if v_result_ref is null then
      -- K05. NAME THE GATE THAT REFUSED. A BEFORE trigger returning null gives a statement that
      -- "succeeded" with no row, and this message used to report only the silence -- which is how
      -- W12-S06's cause was recorded wrongly in the 23 Aug hand-over. Where the refusing gate
      -- published a verdict, it is quoted here.
      raise exception 'fn_phase_d_object_write: the write to % for % returned no key. Refusing to report a write that produced nothing. Gate verdict: % — %. (pd_object_write_produced_nothing)',
        wm.target_relation, v_object,
        coalesce(nullif(current_setting('app.inquiry_match_gate_verdict', true),''), '(no gate published a verdict)'),
        coalesce(nullif(current_setting('app.inquiry_match_gate_reason', true),''), 'no reason was published')
        using errcode = '23502';
    end if;

    -- D17. THE ASSERTION. A Phase D test write may not leave an outbound request behind it.
    if v_testctx then
      -- WHOSE REQUEST IS IT. This counted every row above an id watermark, so a request enqueued
      -- by ANY concurrent transaction was attributed to this write. Measured 23 Aug 2026: the
      -- step-coverage drive failed with "writing inquiry to public.inquiries enqueued 2 outbound
      -- HTTP request(s): POST .../dropbox_backup, POST .../uptime_check" -- and neither came from
      -- the write. cron.job 88 (dropbox_backup_scan) and 35 (uptime_check_15min) both run
      -- */15 * * * *, they commit while a Phase D transaction is open, and READ COMMITTED then
      -- shows their rows to the next statement here. A drive that fails four times an hour, on the
      -- quarter hour, because a scheduled job ran is an instrument reporting on the wrong subject.
      -- The requests are attributed to this transaction now; see the helper for how.
      select r.n, r.urls into v_net_new, v_net_urls
        from public.fn_phase_d_outbound_requests_by_this_transaction(v_net_max) r;
      if coalesce(v_net_new,0) > 0 then
        raise exception 'fn_phase_d_object_write: writing % to % enqueued % outbound HTTP request(s): %. A Phase D test write may not leave an outbound request behind it. (pd_object_outbound_request_produced)',
          v_object, wm.target_relation, v_net_new, v_net_urls using errcode = '23514',
          hint = 'A trigger on this relation calls net.http_post. Register it in public.phase_d_outbound_door with the product''s own already-done guard column, or explain why the request is legitimate under the hold.';
      end if;
    end if;

    return jsonb_build_object(
      'ok', true, 'object_id', v_object, 'relation_kind', 'EXISTING_TABLE',
      'canonical_relation', wm.target_relation, 'operation', wm.operation,
      'result_reference', format('%s:%s=%s', wm.target_relation, wm.key_column, v_result_ref),
      -- F44. THE CANONICAL REFERENCE, RETURNED BY THE WRITER ITSELF.
      -- Which identity is canonical for this object is a property of the object, recorded once in
      -- public.phase_d_object_reference_strategy and derived from the frozen 56-object map. For an
      -- EXISTING_TABLE object it is the relation's own primary key -- the value this write just
      -- produced -- and every caller downstream now takes it from here rather than choosing.
      'canonical_ref', public.fn_phase_d_ref(jsonb_build_object(
                         'object_id', v_object, 'identity', v_result_ref,
                         'owner_ref', v_owner_ref)),
      'business_key', v_key, 'state', v_state_given,
      'policy_family', b.policy_family, 'record_policy', b.record_policy,
      'owner_scope', b.ownership_scope, 'owner_ref', v_owner_ref,
      'columns_written', case when v_unchanged then '[]'::jsonb else to_jsonb(v_cols) end,
      'unchanged', v_unchanged,
      'state_carried_by_relation', (v_state_given is null
         or exists (select 1 from jsonb_each_text(wm.column_map) k where k.value = 'state')),
      'outbound_requests_enqueued', coalesce(v_net_new, 0),
      'quarantine_note', wm.quarantine_note,
      'payload_digest', encode(sha256(convert_to(v_payload::text,'UTF8')),'hex'));
  end if;

  -- ================= PHASE D STORE: unchanged behaviour from D2 =================
  select * into v_prior from public.phase_d_object_record
   where object_id = v_object and business_key = v_key and superseded_by is null
   order by version desc limit 1;

  if found then
    if b.policy_family = 'APPEND_ONLY' then
      raise exception 'fn_phase_d_object_write: % is APPEND_ONLY (%) and business key % already holds record %. A correction is a NEW key, never a second version of this one. (pd_object_append_only)',
        v_object, b.record_policy, v_key, v_prior.record_id using errcode = '23514';
    end if;
    -- D27. "MOVE ITS STATE" — AND THE WRITER OFFERED NO WAY TO MOVE IT.
    --
    -- This refusal told the caller to move the record's state instead of writing a second, and then
    -- returned before anything could. In the store branch it governs exactly ONE object:
    --
    --     dispatch_batch   PHASE_D_OBJECT_VIEW   TRANSACTION_RECORD
    --
    -- payment_transaction, reveal_transaction and supplier_assignment are the other three
    -- TRANSACTION_RECORDs and all three are EXISTING_TABLE, so they never reach this branch — their
    -- second write is an UPSERT_STATE that moves the row, which is exactly what this text asks for.
    --
    -- And the frozen registry writes dispatch_batch at FIVE successive steps of W12:
    --     S01 Accept dispatch-ready package        INTAKE_HANDLER
    --     S02 Build eligible supplier pool         ANALYSIS_HANDLER
    --     S03 Apply fairness and capacity policy   ANALYSIS_HANDLER
    --     S04 Review policy exception if needed    REVIEW_HANDLER
    --     S08 Record selection and exclusion evidence  EXECUTION_HANDLER
    --
    -- A batch that is accepted, then built, then policy-applied, then reviewed, then evidenced. Five
    -- writes to one identity is the DESIGN, so a rule refusing the second could never be satisfied
    -- by the workflow that owns the object. That is a misclassification meeting a missing mechanism,
    -- not a business constraint doing its job.
    --
    -- ONE RECORD PER IDENTITY IS PRESERVED, and that is the part that must not be lost. The move is
    -- a superseding version, the same mechanism VERSIONED, IMMUTABLE_REVISION, CASE_RECORD and
    -- MUTABLE_CONTROLLED already use: the prior row is retained and marked superseded, so after five
    -- writes there is exactly ONE current record and four retained predecessors. Nothing is
    -- overwritten in place, which matters because Phase B's frozen mutation_rule for this object is
    -- "immutable selection evidence" — history is evidence.
    --
    -- THE REFUSAL IS KEPT, NARROWED TO WHAT IT CAN ACTUALLY MEAN: a repeat that moves nothing. The
    -- EXISTING_TABLE branch already refuses on exactly that ground — "a write that changes nothing
    -- is not a state transition" — so the two branches now agree about one family instead of giving
    -- it opposite answers. record_policy is FROZEN Phase B and is untouched; policy_family is Phase
    -- D's own fold and is also untouched. Only the writer's behaviour changes.
    if b.policy_family = 'TRANSACTION_RECORD'
       and v_prior.state is not distinct from v_state
       and v_prior.payload = v_payload then
      raise exception 'fn_phase_d_object_write: % is a %-family record and business key % already exists as record % with the same state and payload. One record per identity; move its state, do not write a second. (pd_object_duplicate_identity)',
        v_object, b.policy_family, v_key, v_prior.record_id using errcode = '23505';
    end if;
    v_version := v_prior.version + 1;
  end if;

  insert into public.phase_d_object_record
    (object_id, business_key, version, state, owner_scope, owner_ref, payload,
     run_id, step_run_id, trace_id, created_by)
  values (v_object, v_key, v_version, v_state, b.ownership_scope, v_owner_ref, v_payload,
          nullif(p_input->>'run_id','')::bigint, nullif(p_input->>'step_run_id','')::bigint,
          nullif(p_input->>'trace_id','')::bigint, v_actor)
  returning record_id into v_id;

  if v_id is null then
    raise exception 'fn_phase_d_object_write: the insert for % / % returned no record_id. Refusing to report a write that produced nothing. (pd_object_write_produced_nothing)',
      v_object, v_key using errcode = '23502';
  end if;
  select * into v_readback from public.phase_d_object_record where record_id = v_id;
  if not found then
    raise exception 'fn_phase_d_object_write: record % is not readable back in the same transaction. (pd_object_write_not_readable)',
      v_id using errcode = '23502';
  end if;

  if v_prior.record_id is not null
     -- D27. TRANSACTION_RECORD joins the supersede list so that "one record per identity" stays
     -- literally true: the prior version is retained and marked superseded, never left as a second
     -- live record alongside the new one.
     and b.policy_family in ('VERSIONED','IMMUTABLE_REVISION','CASE_RECORD','MUTABLE_CONTROLLED','TRANSACTION_RECORD') then
    update public.phase_d_object_record
       set superseded_by = v_id, superseded_at = now()
     where record_id = v_prior.record_id;
  end if;

  return jsonb_build_object(
    'ok', true, 'object_id', v_object, 'relation_kind', 'PHASE_D_OBJECT_VIEW',
    'record_id', v_id, 'business_key', v_key,
    'result_reference', format('public.phase_d_object_record:record_id=%s', v_id),
    -- F44. For a PHASE_D_STORE object the canonical identity is object_id + business_key + version.
    -- record_id stays in the envelope as the physical detail it is, never as the identity.
    'canonical_ref', public.fn_phase_d_ref(jsonb_build_object(
                       'object_id', v_object, 'identity', v_key,
                       'version', v_version::text, 'owner_ref', v_owner_ref)),
    'version', v_version, 'state', v_readback.state,
    'policy_family', b.policy_family, 'record_policy', b.record_policy,
    'owner_scope', b.ownership_scope, 'owner_ref', v_owner_ref,
    'canonical_relation', b.canonical_relation,
    'superseded_record_id', v_prior.record_id,
    'payload_digest', encode(sha256(convert_to(v_payload::text,'UTF8')),'hex'));
end

fn_phase_d_object_read:
declare
  b            public.phase_d_business_object_binding%rowtype;
  v_object     text := nullif(btrim(coalesce(p_input->>'object_id','')),'');
  v_key        text := nullif(btrim(coalesce(p_input->>'business_key','')),'');
  v_scope      text := nullif(btrim(coalesce(p_input->>'caller_scope','')),'');
  v_asked      text := nullif(btrim(coalesce(p_input->>'caller_ref','')),'');
  v_ref        text;
  v_identity   text;
  v_derived    boolean := false;
  v_rows       jsonb;
begin
  if v_object is null then
    raise exception 'fn_phase_d_object_read: object_id is required (pd_object_input_invalid)'
      using errcode = '22023';
  end if;
  select * into b from public.phase_d_business_object_binding where object_id = v_object;
  if not found then
    raise exception 'fn_phase_d_object_read: % is not a bound Phase D business object (pd_object_unbound)',
      v_object using errcode = '23503';
  end if;
  if b.relation_kind <> 'PHASE_D_OBJECT_VIEW' then
    raise exception 'fn_phase_d_object_read: % lives in the existing relation % and is read there. (pd_object_wrong_reader)',
      v_object, b.canonical_relation using errcode = '23514';
  end if;

  -- E20 / finding 16. WHO THE CALLER IS COMES FROM THE TOKEN, NOT FROM THE CALL.
  -- This routine is SECURITY DEFINER, so it reads with the owner's rights and its owner scoping was
  -- the only thing standing between one customer's records and another's — and it took caller_ref
  -- straight out of the input. E4 revoked it from anon and authenticated, which bounds WHO can
  -- reach it; it does nothing about WHOSE records they then ask for.
  --
  -- Derived exactly as fn_customer_document_refs derives it, against the same table. A supplied
  -- caller_ref is accepted only when the call carries no end-user identity at all, which is the
  -- service_role case; when it does carry one, a caller_ref naming somebody else is refused rather
  -- than honoured.
  v_identity := nullif(coalesce(auth.email(), ''), '');
  if v_identity is not null or auth.uid() is not null then
    select c.id::text into v_ref
      from public.customers c
     where lower(c.email) = lower(coalesce(v_identity,''))
        or c.id = auth.uid()
     order by (lower(c.email) = lower(coalesce(v_identity,''))) desc nulls last
     limit 1;
    if v_ref is null and v_identity is not null then
      select l.id::text into v_ref from public.leads l
       where lower(coalesce(l.email,'')) = lower(v_identity) limit 1;
    end if;
    if v_ref is null then
      raise exception 'fn_phase_d_object_read: the call carries an end-user identity that resolves to no customer or supplier, so there is no owner to scope this read to. (pd_object_caller_unresolved)'
        using errcode = '42501';
    end if;
    v_derived := true;
    if v_asked is not null and v_asked <> v_ref then
      raise exception 'fn_phase_d_object_read: the call presents caller_ref % and the verified identity resolves to %. A caller does not get to name whose records these are. (pd_object_caller_ref_mismatch)',
        v_asked, v_ref using errcode = '42501';
    end if;
  else
    v_ref := v_asked;
  end if;

  -- CROSS-OWNER ACCESS IS REFUSED HERE, not filtered by the caller. A COMPANY-scoped object is
  -- readable by an internal caller; a CUSTOMER- or SUPPLIER-scoped one requires the caller to
  -- name whose record it is asking for, and gets nothing back for anybody else.
  if b.ownership_scope in ('CUSTOMER','SUPPLIER') then
    if v_scope is null or v_ref is null then
      raise exception 'fn_phase_d_object_read: % is %-scoped and the call names no caller_scope/caller_ref. Refusing to answer for an unnamed owner. (pd_object_owner_unstated)',
        v_object, b.ownership_scope using errcode = '22023';
    end if;
    if v_scope <> b.ownership_scope then
      raise exception 'fn_phase_d_object_read: % is %-scoped and the caller presents scope %. (pd_object_cross_scope)',
        v_object, b.ownership_scope, v_scope using errcode = '23514';
    end if;
  end if;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.version desc), '[]'::jsonb) into v_rows
    from public.phase_d_object_record r
   where r.object_id = v_object
     and (v_key is null or r.business_key = v_key)
     and (b.ownership_scope = 'COMPANY' or r.owner_ref = v_ref);

  return jsonb_build_object(
    'ok', true, 'object_id', v_object, 'canonical_relation', b.canonical_relation,
    'owner_scope', b.ownership_scope, 'caller_ref', v_ref,
    -- Said out loud in the answer, so a consumer can tell a verified read from an internal one.
    'caller_ref_source', case when v_derived then 'derived from the verified auth identity'
                              else 'supplied by the caller; no end-user identity was present' end,
    'count', jsonb_array_length(v_rows), 'records', v_rows);
end

fn_phase_d_object_state:
declare n_obj int; n_bound int; n_unres int; n_noread int; n_nowrite int; n_noowner int;
        n_views int; n_needviews int;
begin
  select count(*) into n_obj   from public.phase_b_business_object;
  select count(*) into n_bound from public.phase_d_business_object_binding;

  check_name := 'every_frozen_object_has_a_binding';
  expected := n_obj::text; actual := n_bound::text; ok := (n_bound = n_obj); return next;

  -- A named relation that does not exist is prose. Tables and views are both resolved.
  select count(*) into n_unres
    from public.phase_d_business_object_binding b
   where not exists (
     select 1 from pg_class c join pg_namespace n on n.oid = c.relnamespace
      where n.nspname = 'public' and c.relkind in ('r','v','m','p')
        and c.relname = replace(b.canonical_relation, 'public.', ''));
  check_name := 'every_canonical_relation_resolves';
  expected := '0'; actual := n_unres::text; ok := (n_unres = 0); return next;

  select count(*) into n_noread  from public.phase_d_business_object_binding
   where coalesce(btrim(canonical_read_service),'') = '';
  check_name := 'objects_with_no_canonical_read_service';
  expected := '0'; actual := n_noread::text; ok := (n_noread = 0); return next;

  select count(*) into n_nowrite from public.phase_d_business_object_binding
   where coalesce(btrim(canonical_write_service),'') = '';
  check_name := 'mutable_objects_with_no_canonical_write_service';
  expected := '0'; actual := n_nowrite::text; ok := (n_nowrite = 0); return next;

  select count(*) into n_noowner from public.phase_d_business_object_binding
   where ownership_scope is null or coalesce(btrim(ownership_scope),'') = '';
  check_name := 'objects_with_no_ownership_scope';
  expected := '0'; actual := n_noowner::text; ok := (n_noowner = 0); return next;

  select count(*) into n_needviews from public.phase_d_business_object_binding
   where relation_kind = 'PHASE_D_OBJECT_VIEW';
  select count(*) into n_views from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'v' and c.relname like 'v_obj_%';
  check_name := 'one_view_per_stored_object';
  expected := n_needviews::text; actual := n_views::text; ok := (n_views = n_needviews); return next;

  -- The store's guard must be attached, or the record policy is a column value and nothing else.
  check_name := 'record_policy_guard_is_attached';
  expected := '1'; ok := exists (
    select 1 from pg_trigger t join pg_class c on c.oid = t.tgrelid
     where c.relname = 'phase_d_object_record' and t.tgname = 'a00_phase_d_object_policy_guard'
       and not t.tgisinternal);
  actual := case when ok then '1' else '0' end; return next;
end

fn_phase_d_reveal_permitted:
declare t public.transactions%rowtype; s public.phase_d_payment_state%rowtype; v_raw text;
begin
  select * into t from public.transactions where id::text = p_transaction_id;
  if not found then
    permitted := false; state_key := 'no_transaction'; rung := 0;
    reason := format('BR-020: no transaction %s. A reveal with no transaction is not an edge case, it is the whole defect.', coalesce(p_transaction_id,'(null)'));
    return next; return;
  end if;

  v_raw := lower(btrim(coalesce(t.fee_status, '')));
  if v_raw = '' then
    permitted := false; state_key := 'unstated'; rung := 0;
    reason := 'BR-020: transaction carries no fee_status. An absent payment state is not a paid one.';
    return next; return;
  end if;

  -- The table is ALIASED and the column QUALIFIED. This function's OUT parameter is also named
  -- state_key, and an unqualified reference resolves to the plpgsql variable rather than the
  -- column. Postgres refuses that as ambiguous instead of silently choosing, which is the good
  -- outcome — but only once it is written correctly.
  select * into s from public.phase_d_payment_state ps where ps.state_key = v_raw;
  if not found then
    -- FAIL CLOSED. An unrecognised value is not mapped to the nearest rung and not assumed paid.
    permitted := false; state_key := v_raw; rung := 0;
    reason := format('BR-020: fee_status %s is not a declared payment state. Refusing rather than guessing which rung it means.', v_raw);
    return next; return;
  end if;

  if not s.authorizes_reveal then
    permitted := false; state_key := s.state_key; rung := s.rung;
    reason := format('BR-020: transaction is at rung %s (%s) and reveal requires payment_reconciled at rung 5. %s',
                     s.rung, s.state_key, s.why);
    return next; return;
  end if;

  -- Reconciled is claimed. The claim must carry the two facts that make it one.
  if coalesce(btrim(t.payment_ref),'') = '' then
    permitted := false; state_key := s.state_key; rung := s.rung;
    reason := 'BR-020: the transaction claims a reconciled state with no payment_ref. A reconciliation with nothing to reconcile against is a label.';
    return next; return;
  end if;
  if t.reveal_fee is null then
    permitted := false; state_key := s.state_key; rung := s.rung;
    reason := 'BR-020: the transaction claims a reconciled state with a null reveal_fee. A null amount is an unmeasured amount, not a settled one.';
    return next; return;
  end if;

  permitted := true; state_key := s.state_key; rung := s.rung;
  reason := format('BR-020: transaction %s is at rung %s (%s) with payment_ref and a stated reveal_fee.',
                   t.id, s.rung, s.state_key);
  return next;
end

fn_phase_d_gate_state:
declare n_gates int; n_contract int; n_notimpl int; n_generic int; n_blank int;
begin
  select count(*) into n_gates    from public.phase_b_gate;
  select count(*) into n_contract from public.phase_d_gate_contract;

  check_name := 'every_frozen_gate_has_an_evidence_contract';
  expected := n_gates::text; actual := n_contract::text; ok := (n_contract = n_gates); return next;

  -- Every gate must reach a predicate. Asked with EMPTY evidence, none may report NOT_IMPLEMENTED.
  select count(*) into n_notimpl from public.phase_b_gate g
   where (select ge.state from public.fn_phase_d_gate_evaluate(g.gate_id, '{}'::jsonb) ge)
         = 'NOT_IMPLEMENTED';
  check_name := 'gates_with_no_predicate';
  expected := '0'; actual := n_notimpl::text; ok := (n_notimpl = 0); return next;

  -- An unknown gate must be blocked, never waved through.
  check_name := 'unknown_gate_is_blocked';
  expected := 'NOT_IMPLEMENTED/false';
  actual := (select ge.state || '/' || ge.passed::text
               from public.fn_phase_d_gate_evaluate('GATE-999','{}'::jsonb) ge);
  ok := (actual = 'NOT_IMPLEMENTED/false'); return next;

  -- A gate declaring evidence must BLOCK when given none. This is the check that would have
  -- caught the generic predicate this file replaces.
  select count(*) into n_generic from public.phase_d_gate_contract c
   where cardinality(c.evidence_keys) > 0
     and (select ge.passed from public.fn_phase_d_gate_evaluate(c.gate_id, '{}'::jsonb) ge);
  check_name := 'evidence_declaring_gates_that_pass_on_no_evidence';
  expected := '0'; actual := n_generic::text; ok := (n_generic = 0); return next;

  select count(*) into n_blank from public.phase_d_gate_contract
   where coalesce(btrim(correction_owner),'') = '' or coalesce(btrim(evidence_source),'') = '';
  check_name := 'gates_with_no_correction_owner_or_source';
  expected := '0'; actual := n_blank::text; ok := (n_blank = 0); return next;
end

fn_phase_d_effect_produce:
declare
  e            public.phase_d_step_effect%rowtype;
  sr           public.phase_c_workflow_step_run%rowtype;
  prior        public.phase_d_effect_ledger%rowtype;
  v_step_run   bigint := nullif(p_input->>'step_run_id','')::bigint;
  v_idem       text   := nullif(btrim(coalesce(p_input->>'idempotency_key','')),'');
  v_actor      text   := nullif(btrim(coalesce(p_input->>'actor_role_id','')),'');
  v_payload    jsonb  := coalesce(p_input->'payload','{}'::jsonb);
  v_key        text   := nullif(btrim(coalesce(p_input->>'business_key','')),'');
  v_owner      text   := nullif(btrim(coalesce(p_input->>'owner_ref','')),'');
  v_state      text   := nullif(btrim(coalesce(p_input->>'state','')),'');
  v_ctx        text   := lower(coalesce(nullif(btrim(p_input->>'execution_context'),''),'production'));
  v_write      jsonb;
  v_result_ref text;
  v_relation   text;
  v_mode       text := 'none';
  v_eid        bigint;
  v_num        numeric; v_den numeric;
  v_cap        jsonb;   -- F05: the accepted capability result for this step run, or null
  v_parent_col text;    -- K02: the parent identity the object's binding declares
  v_parent_src text;    -- K02: the payload key the write map reads it from
  v_parent_val jsonb;   -- K02: what the step context resolves for it
begin
  if v_step_run is null or v_idem is null or v_actor is null then
    raise exception 'fn_phase_d_effect_produce: step_run_id, idempotency_key and actor_role_id are all required (pd_effect_input_invalid)'
      using errcode = '22023';
  end if;

  select * into sr from public.phase_c_workflow_step_run where step_run_id = v_step_run;
  if not found then
    raise exception 'fn_phase_d_effect_produce: no step run % (pd_step_state_invalid)', v_step_run
      using errcode = '23503';
  end if;

  select * into e from public.phase_d_step_effect where step_id = sr.step_id;
  if not found then
    raise exception 'fn_phase_d_effect_produce: step % has no declared effect contract — fail closed. All 257 frozen steps carry one. (pd_effect_undeclared)',
      sr.step_id using errcode = '23503';
  end if;

  -- ---- IDEMPOTENCY IS A READ, NOT A HOPE -------------------------------------------------
  -- A replayed handler must produce NO second effect. The assertion a duplicate-effect test makes
  -- is the ledger ROW COUNT, not the returned payload, so the check is done here and the prior
  -- row is returned verbatim.
  select * into prior from public.phase_d_effect_ledger
   where step_run_id = v_step_run and effect_type = e.expected_effect_type;
  if found then
    return jsonb_build_object(
      'ok', true, 'replay', true, 'effect_id', prior.effect_id,
      'effect_type', prior.effect_type, 'effect_object_id', prior.effect_object_id,
      'result_reference', prior.result_reference, 'provider_mode', prior.provider_mode,
      'note', 'the effect for this step run already exists; no second effect was produced');
  end if;

  -- ---- K02. THE PARENT THE OBJECT DECLARES -------------------------------------------------
  -- public.phase_d_object_write skips a mapped column whose source key the payload does not carry,
  -- and fn_phase_d_fixture_effect_payload only fills columns the RELATION demands. A parent column
  -- that is nullable demands nothing, so supplier_assignment was written with no inquiry_id and a
  -- BEFORE trigger dropped the row. The object's own binding already names its parent; that is read
  -- here, and the value comes from the step context, which resolves an identity from the row it
  -- names. Nothing is invented and no constant is used: an identity is never a fixture.
  select bb.parent_identity, wm.column_map->>bb.parent_identity
    into v_parent_col, v_parent_src
    from public.phase_d_business_object_binding bb
    join public.phase_d_object_write_map wm on wm.object_id = bb.object_id
   where bb.object_id = e.effect_object_id
     and coalesce(btrim(bb.parent_identity),'') <> ''
     and wm.column_map ? bb.parent_identity;
  if v_parent_src is not null
     and v_parent_src not in ('business_key','owner_ref','state')
     and (not (v_payload ? v_parent_src) or v_payload->v_parent_src = 'null'::jsonb) then
    v_parent_val := (public.fn_phase_d_step_context(v_step_run))->'context'->v_parent_src;
    if v_parent_val is not null and v_parent_val <> 'null'::jsonb then
      v_payload := v_payload || jsonb_build_object(v_parent_src, v_parent_val);
    end if;
  end if;

  -- ---- the seven types -------------------------------------------------------------------
  if e.expected_effect_type = 'KERNEL_ONLY_TRANSITION' then
    -- Nothing is written here beyond the ledger entry. The effect IS the kernel's step run and
    -- run-state move, which is persistent and kernel-verifiable; a domain row invented to make a
    -- count look better would be a fabricated effect.
    v_result_ref := format('public.phase_c_workflow_step_run:step_run_id=%s', v_step_run);
    v_relation   := 'public.phase_c_workflow_step_run';

  elsif e.expected_effect_type = 'CAPABILITY_REQUEST' then
    -- Fail closed in production, and record the refusal as the effect. A capability step whose
    -- effect was a success record would be a mock completing a business step.
    -- F05. This read `if v_ctx <> 'test' then raise`, which is the bypass the founder prohibited
    -- seen from the effect side: the string 'test' turned the refusal into a record. The subject
    -- is now the same one the handler asks about -- is there an ACCEPTED capability result for
    -- this step run? The declared effect of a capability step IS the request; what the result
    -- adds is the answer it can point at, and its provider_mode is recorded rather than assumed.
    v_cap := public.fn_phase_d_capability_answer(v_step_run);
    if v_cap is null then
      raise exception 'fn_phase_d_effect_produce: step % is capability-dependent and its capability request carries no accepted result. The declared effect is a refusal, not a record. No execution context lifts this. (pd_capability_unavailable)',
        sr.step_id using errcode = '23514';
    end if;
    v_result_ref := format('capability_request:%s:result=%s:mode=%s:digest=%s',
                           v_cap->>'request_id', v_cap->>'result_id', v_cap->>'provider_mode',
                           left(coalesce(v_cap->>'payload_digest',''), 12));
    v_relation   := 'public.phase_d_capability_result';
    v_mode       := v_cap->>'provider_mode';

  elsif e.expected_effect_type = 'EXTERNAL_EFFECT_INTENT' then
    -- MOCK, ALWAYS. provider_mode has no 'live' value, so this cannot be turned into a send by
    -- changing a parameter. A recipient and a consent basis are REQUIRED and are not defaulted:
    -- an intent that cannot say who it is for is not an intent.
    if not (v_payload ? 'recipient') or not (v_payload ? 'consent_basis') then
      raise exception 'fn_phase_d_effect_produce: step % declares an external effect and the payload names no %. An intent with no recipient or no consent basis must not be recorded as one. (pd_effect_intent_incomplete)',
        sr.step_id,
        case when not (v_payload ? 'recipient') then 'recipient' else 'consent_basis' end
        using errcode = '22023';
    end if;
    if coalesce(v_payload->>'suppressed','false') = 'true' then
      v_result_ref := format('external_intent:SUPPRESSED:%s', v_payload->>'recipient');
    else
      v_result_ref := format('external_intent:MOCK:%s', v_payload->>'recipient');
    end if;
    v_relation := 'public.phase_d_effect_ledger';
    v_mode     := 'mock';

  elsif e.expected_effect_type = 'MEASUREMENT_RECORD' then
    -- least(100, NULL) returns 100 and put 97.7% attainment in the founder's email on a
    -- zero-revenue day. Nothing is defaulted, and a zero denominator raises.
    if not (v_payload ? 'numerator') or not (v_payload ? 'denominator') then
      raise exception 'fn_phase_d_effect_produce: step % is a measurement step and the payload names no %. An absent input must not score as satisfied. (pd_effect_measurement_incomplete)',
        sr.step_id,
        case when not (v_payload ? 'numerator') then 'numerator' else 'denominator' end
        using errcode = '22023';
    end if;
    v_num := (v_payload->>'numerator')::numeric;
    v_den := (v_payload->>'denominator')::numeric;
    if v_den = 0 then
      raise exception 'fn_phase_d_effect_produce: step % reported a denominator of 0. A ratio over nothing is not a measurement. (pd_effect_zero_denominator)',
        sr.step_id using errcode = '22023';
    end if;
    v_result_ref := format('measurement:%s/%s', v_num, v_den);
    v_relation   := 'public.phase_d_effect_ledger';

  elsif e.expected_effect_type = 'REVIEW_VERDICT' then
    -- The verdict is the caller's. An absent one is a refusal, not an approval: a review handler
    -- that supplied its own verdict would make all 47 review steps a rubber stamp.
    if not (v_payload ? 'verdict') or nullif(btrim(v_payload->>'verdict'),'') is null then
      raise exception 'fn_phase_d_effect_produce: step % is a review step and the payload names no verdict. This routine does not have one to give. (pd_effect_verdict_absent)',
        sr.step_id using errcode = '22023';
    end if;
    if not public.fn_kernel_reviewer_independent(
             sr.accountable_role_id, nullif(btrim(v_payload->>'reviewer_role_id'),'')) then
      raise exception 'fn_phase_d_effect_produce: step % is accountable to % and names % as reviewer; those resolve to one effective identity (BR-002). (pd_rule_refused)',
        sr.step_id, sr.accountable_role_id, coalesce(v_payload->>'reviewer_role_id','(none)')
        using errcode = '23514';
    end if;
    -- H10. review_chain demands subject_type, subject_id, author_agent and stage. The caller's
    -- payload wins where it names them; otherwise each is the fact the run already holds -- what is
    -- under review, its identity, and who reviewed it -- never invented. dept_key comes from the
    -- owner_ref derivation, which resolves a real department for a COMPANY-scoped write.
    v_write := public.fn_phase_d_object_write(jsonb_build_object(
      'object_id','review_record',
      'business_key', coalesce(v_key, format('%s:%s', sr.step_id, v_step_run)),
      'owner_ref', coalesce(v_owner, sr.accountable_role_id),
      'created_by', v_actor,
      'state', coalesce(v_state, v_payload->>'verdict'),
      'payload', jsonb_build_object(
        'subject_type', e.effect_object_id,
        'subject_id',   coalesce(v_key, format('%s:%s', sr.step_id, v_step_run)),
        'author_agent', v_actor,
        'stage',        sr.step_id,
        'notes',        coalesce(v_payload->>'notes', 'phase_d review verdict'))
        || v_payload));
    v_result_ref := v_write->>'result_reference';
    v_relation   := v_write->>'canonical_relation';

  else
    -- DOMAIN_MUTATION and VERSIONED_ARTIFACT: the object's own canonical service.
    if v_key is null or v_owner is null then
      raise exception 'fn_phase_d_effect_produce: step % writes business object % and the call names no %. (pd_effect_owner_or_key_missing)',
        sr.step_id, e.effect_object_id,
        case when v_key is null then 'business_key' else 'owner_ref' end
        using errcode = '22023';
    end if;
    v_write := public.fn_phase_d_object_write(jsonb_build_object(
      'object_id', e.effect_object_id, 'business_key', v_key, 'owner_ref', v_owner,
      'created_by', v_actor, 'state', v_state, 'payload', v_payload,
      'run_id', sr.run_id, 'step_run_id', v_step_run, 'trace_id', p_input->>'trace_id'));
    v_result_ref := v_write->>'result_reference';
    v_relation   := coalesce(v_write->>'canonical_relation', e.effect_relation);
  end if;

  insert into public.phase_d_effect_ledger
    (step_run_id, step_id, workflow_id, run_id, effect_type, effect_object_id, effect_relation,
     effect_operation, result_reference, state_before, state_after, provider_mode,
     payload_digest, idempotency_key, produced_by, trace_id)
  values (v_step_run, sr.step_id, e.workflow_id, sr.run_id, e.expected_effect_type,
          e.effect_object_id, v_relation, e.effect_operation, v_result_ref,
          nullif(p_input->>'state_before',''), v_state, v_mode,
          encode(sha256(convert_to(v_payload::text,'UTF8')),'hex'), v_idem, v_actor,
          nullif(p_input->>'trace_id','')::bigint)
  returning effect_id into v_eid;

  if v_eid is null then
    raise exception 'fn_phase_d_effect_produce: the ledger insert for step run % returned no effect_id. (pd_effect_produced_nothing)',
      v_step_run using errcode = '23502';
  end if;

  return jsonb_build_object(
    'ok', true, 'replay', false, 'effect_id', v_eid,
    'effect_type', e.expected_effect_type, 'effect_object_id', e.effect_object_id,
    'effect_relation', v_relation, 'effect_operation', e.effect_operation,
    'result_reference', v_result_ref, 'provider_mode', v_mode,
    'completion_condition', e.completion_condition,
    'object_write', v_write);
end

fn_phase_d_effect_state:
declare n int; m int; v text;
begin
  select count(*) into m from public.phase_b_workflow_step;

  select count(*) into n from public.phase_d_step_effect;
  check_name := 'every_frozen_step_declares_an_effect';
  expected := m::text; actual := n::text; ok := (n = m); return next;

  select count(*) into n from public.phase_d_step_effect where expected_effect_type is null;
  check_name := 'steps_with_no_expected_effect_type';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_step_effect
   where expected_effect_type not in ('KERNEL_ONLY_TRANSITION','CAPABILITY_REQUEST')
     and effect_object_id is null;
  check_name := 'domain_effects_with_no_object';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  -- Built from the catalogue, not rendered by a cast whose output depends on search_path.
  select count(*) into n from public.phase_d_step_effect e
   where not exists (
     select 1 from pg_proc p join pg_namespace nn on nn.oid = p.pronamespace
      where nn.nspname = 'public'
        and nn.nspname || '.' || p.proname || '('
            || coalesce((select string_agg(format_type(t.o, null), ', ' order by t.ord)
                           from unnest(p.proargtypes) with ordinality t(o, ord)), '')
            || ')' = e.effect_service);
  check_name := 'effect_services_that_do_not_resolve';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_step_effect e
    join public.phase_d_business_object_binding ob on ob.object_id = e.effect_object_id
   where e.expected_effect_type in ('DOMAIN_MUTATION','VERSIONED_ARTIFACT')
     and ob.relation_kind = 'EXISTING_TABLE'
     and not exists (select 1 from public.phase_d_object_write_map w where w.object_id = ob.object_id);
  check_name := 'existing_table_effects_with_no_write_map';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n
    from public.phase_d_object_write_map w
    cross join lateral jsonb_object_keys(w.column_map) k
   where not exists (select 1 from information_schema.columns c
                      where c.table_schema = split_part(w.target_relation,'.',1)
                        and c.table_name   = split_part(w.target_relation,'.',2)
                        and c.column_name  = k);
  check_name := 'write_map_columns_absent_from_the_target';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_object_write_map w
    join public.phase_d_business_object_binding ob on ob.object_id = w.object_id
   where ob.governing_workflow_id = 'ALL' and ob.canonical_relation like 'public.phase_c_%';
  check_name := 'kernel_owned_objects_with_a_phase_d_writer';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_object_write_map
   where target_relation = 'public.notifications';
  check_name := 'phase_d_write_maps_into_the_outbound_notification_table';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_step_effect
   where effect_object_id in ('notification','notification_attempt')
     and expected_effect_type <> 'EXTERNAL_EFFECT_INTENT';
  check_name := 'notification_effects_not_classified_as_intent';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.phase_d_effect_ledger
   where provider_mode not in ('none','mock','disabled');
  check_name := 'ledger_rows_claiming_a_live_external_effect';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from (
    select step_run_id, effect_type from public.phase_d_effect_ledger
     group by 1,2 having count(*) > 1) d;
  check_name := 'duplicate_effects_for_one_step_run';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  -- DISCLOSURE, NOT A PASS. Counts steps whose effect has actually been produced at least once,
  -- which is a different question from whether the path exists.
  --
  -- NAME, DERIVATION AND VALUE UNCHANGED SINCE IT WAS WRITTEN. scripts/checks/kernel-boards.json
  -- keys its ratchet on this exact string, and a ratchet whose subject is renamed goes on silencing
  -- whatever later takes the name. The rows that follow say what is holding it; they neither replace
  -- it nor lower it, and E7 did not touch it either.
  select count(distinct step_id) into n from public.phase_d_effect_ledger;
  check_name := 'steps_with_no_effect_ever_produced';
  expected := '0'; actual := (m - n)::text; ok := (n = m); return next;

  -- ---- THE RED, DECOMPOSED BY THE BRANCH EACH EFFECT ACTUALLY EXECUTES ------------------------
  -- E5 wrote three rows here and derived them from the DECLARED effect object. E7 replaces them
  -- with five derived from the branch, because fn_phase_d_effect_produce hardcodes 'review_record'
  -- for all 41 REVIEW_VERDICT steps and writes only the ledger for EXTERNAL_EFFECT_INTENT and
  -- MEASUREMENT_RECORD. The E5 rows are gone rather than kept beside these: two of them carried a
  -- number this file proves wrong, and a board showing both readings makes the reader choose.
  select count(*) into n from public.fn_phase_d_effect_reachability()
   where reachability = 'REFUSAL_IS_THE_DECLARED_EFFECT' and not has_produced_an_effect;
  check_name := 'no_effect_because_the_refusal_is_the_effect';
  expected := 'informational — the provider hold, and it is the founder''s to lift';
  actual := n::text || ' CAPABILITY_REQUEST step(s): the branch raises pd_capability_unavailable in '
         || 'production rather than recording. A ledger row needs execution_context=test, which is '
         || 'not a result.';
  ok := true; return next;

  select count(*) into n from public.fn_phase_d_effect_reachability()
   where reachability = 'WRITES_A_ZERO_RESIDUE_TABLE' and not has_produced_an_effect;
  check_name := 'no_effect_because_the_effect_writes_a_zero_residue_table';
  expected := 'informational — the zero-residue rule, and it is the founder''s to lift';
  actual := n::text || ' step(s) whose effect writes customers, inquiries, quotes or transactions. '
         || 'The estate holds 0 of each since the 16 Aug purge and may not be given one.';
  ok := true; return next;

  select count(*) into n from public.fn_phase_d_effect_reachability()
   where reachability = 'WRITES_AN_EXISTING_TABLE_NOT_UNDER_THE_RULE' and not has_produced_an_effect;
  check_name := 'no_effect_and_the_effect_writes_a_real_table_the_rule_does_not_name';
  expected := 'informational — the fixture rule, plus a row in a table the company uses';
  actual := n::text || ' step(s) writing review_chain, refunds, company_goals, opportunity, '
         || 'os_incidents, legal_reviews, documents, quote_comparisons, supplier_capabilities, '
         || 'leads, stripe_events, inquiry_matches, department_objective, content_drafts, '
         || 'reveal_invoices or org_tasks. Permitted by the letter of the zero-residue rule and '
         || 'still not Phase D''s own storage — 41 of them are the REVIEW_VERDICT steps, which write '
         || 'review_chain through a hardcoded object_id their own effect row does not name.';
  ok := true; return next;

  select count(*) into n from public.fn_phase_d_effect_reachability()
   where reachability in ('WRITES_ONLY_THE_PHASE_D_LEDGER','WRITES_ONLY_THE_PHASE_D_OBJECT_STORE')
     and not has_produced_an_effect;
  check_name := 'no_effect_although_the_effect_leaves_phase_d_tables_only';
  expected := 'informational — NEITHER hold touches these; the fixture rule does';
  actual := n::text || ' step(s) writing only phase_d_effect_ledger or phase_d_object_record. '
         || 'They are not waiting on a business arrival. The only driver, fn_phase_d_drive_workflow, '
         || 'opens every run with source_ref zz-phase-d-… and trigger_ctx.fixture=true, so '
         || 'committing one leaves residue that fn_phase_d_fixture_residue() must report as 0.';
  ok := true; return next;

  -- A decomposition that stops covering the thing it decomposes is worse than no decomposition, and
  -- UNRESOLVED is its own failure: a branch whose written relation cannot be resolved is a step
  -- nobody can say anything about.
  select count(*) into n from public.fn_phase_d_effect_reachability()
   where reachability = 'UNRESOLVED';
  check_name := 'steps_whose_written_relation_does_not_resolve';
  expected := '0'; actual := n::text; ok := (n = 0); return next;

  select count(*) into n from public.fn_phase_d_effect_reachability();
  check_name := 'every_step_carries_a_reachability_class';
  expected := m::text; actual := n::text; ok := (n = m); return next;

  select string_agg(x.t || '=' || x.c, ' ' order by x.t) into v
    from (select reachability t, count(*)::text c
            from public.fn_phase_d_effect_reachability() group by 1) x;
  check_name := 'reachability_class_distribution';
  expected := 'informational'; actual := coalesce(v,'(none)'); ok := true; return next;

  select string_agg(x.t || '=' || x.c, ' ' order by x.t) into v
    from (select expected_effect_type t, count(*)::text c
            from public.phase_d_step_effect group by 1) x;
  check_name := 'effect_type_distribution';
  expected := 'informational'; actual := coalesce(v,'(none)'); ok := true; return next;

  select string_agg(x.t || '=' || x.c, ' ' order by x.t) into v
    from (select implementation_depth t, count(*)::text c
            from public.phase_d_step_effect group by 1) x;
  check_name := 'implementation_depth_distribution';
  expected := 'informational'; actual := coalesce(v,'(none)'); ok := true; return next;

  select string_agg(x.t || '=' || x.c, ' ' order by x.t) into v
    from (select object_resolution t, count(*)::text c
            from public.phase_d_step_effect group by 1) x;
  check_name := 'object_resolution_distribution';
  expected := 'informational'; actual := coalesce(v,'(none)'); ok := true; return next;
end

fn_phase_d_drive_workflow:
declare
  w         public.phase_b_workflow%rowtype;
  sr        public.phase_c_workflow_step_run%rowtype;
  hr        public.phase_c_handoff_run%rowtype;
  hc        public.phase_d_handoff_contract%rowtype;
  d         public.phase_d_dispatch%rowtype;
  v_prev    public.phase_c_workflow_step_run%rowtype;
  v_wf      text := nullif(btrim(coalesce(p_input->>'workflow_id','')),'');
  v_label   text := coalesce(nullif(btrim(p_input->>'label'),''), 'phase-d-drive');
  v_ctx     text := lower(coalesce(nullif(btrim(p_input->>'execution_context'),''),'production'));
  v_max     int  := coalesce(nullif(p_input->>'max_steps','')::int, 40);
  -- HOLD AT AN OPEN STEP. A caller that means to drive a step's FAILURE branch needs that step
  -- open and owned, and cannot get there by asking the kernel to stop: since PCCR-001 the dispatch
  -- fires when the step OPENS, so a handler that can execute closes its step and the kernel opens
  -- the next one before any caller is consulted. max_steps 0 therefore does not leave a step open
  -- -- measured 23 Aug 2026 on all 30 workflows, 19 of them came back with the run in
  -- waiting_handoff or waiting_review and NO open step run at all, because the successor is not
  -- opened until the receiving owner accepts the handoff. The failure and cancellation probes then
  -- had nothing to act on and were refused 22023 for a null step_run_id, which is a fact about the
  -- probe and not about the estate.
  --
  -- These two inputs let the caller drive the canonical path -- the same handoff acceptances, the
  -- same capability results, the same recorded reviews, the same fn_kernel_step_complete for every
  -- earlier step -- and STOP with one named step open, having completed nothing on it. Nothing is
  -- skipped and no state is written by hand: the run is exactly where a real actor would find it.
  v_hold_step text := nullif(btrim(coalesce(p_input->>'hold_at_step_id','')),'');
  v_hold_any  boolean := coalesce((p_input->>'hold_at_first_open_step')::boolean, false);
  v_held_srid bigint := null;
  v_held_step text := null;
  v_boid    text := nullif(btrim(coalesce(p_input->>'business_object_id','')),'');
  v_caller_reviewer text := nullif(btrim(coalesce(p_input->>'reviewer_role_id','')),'');
  v_cands   text[] := coalesce((select array_agg(x)
                                  from jsonb_array_elements_text(p_input->'reviewer_candidates') x),
                               '{}'::text[]);
  v_run     bigint;
  v_start   jsonb;
  v_steps   jsonb := '[]'::jsonb;
  v_handoffs jsonb := '[]'::jsonb;
  v_i       int := 0;
  v_driven  int := 0;
  v_haccept int := 0;
  v_dispatched int := 0;
  v_executed   int := 0;
  v_before  bigint;
  v_declared text;
  v_rev     text;
  v_task    bigint;
  v_decide  jsonb;
  v_hoff    jsonb;
  v_hpk     jsonb;
  v_err     text; v_sqlstate text; v_code text;
  v_run_state text;
  v_cap_fixture text;      -- F17: the committed CAPABILITY_RESULT row for this step
  v_cap_req   jsonb;       -- F17
  v_cap_res   jsonb;       -- F17
  v_caps      jsonb := '[]'::jsonb;   -- F17: what the capability path did, per step
  v_capn      int := 0;    -- F17: capability results accepted
  v_redisp    jsonb;
  sr2         public.phase_c_workflow_step_run%rowtype;  -- F38: the step run, re-read after dispatch
  v_handler_closed int := 0;          -- F38: steps the handler closed through the kernel itself
  v_seen           bigint[] := '{}';  -- G07: every step run this loop actually observed
  v_unseen         int := 0;          -- G07: handler closures that happened before the loop began
  v_rtask     bigint;                 -- F35: the task the internal review decides
  v_rrev      text;                   -- F35: the reviewer, frozen-declared or independence-tested
  v_rdec      jsonb;                  -- F35: what fn_kernel_review_decide returned
  v_revs      jsonb := '[]'::jsonb;   -- F35: what the review path did, per step
  v_revn      int := 0;               -- F35: internal reviews recorded
  v_stopped jsonb := null;        -- where the DRIVE could go no further, and why
  v_first_refusal jsonb := null;  -- where the deterministic HANDLER first declined, and why
  v_founder_cmd   bigint := null; -- G05: the fixture founder command this run arises from, where one applies
  v_premature     boolean := false;   -- H06: the kernel reported the run already existed
  v_redispatched  int := 0;           -- H06: open steps dispatched again once the scenario was complete
begin
  if v_wf is null then
    raise exception 'fn_phase_d_drive_workflow: workflow_id is required' using errcode = '22023';
  end if;
  -- The kernel dispatch hard-codes 'execution_context','production'. Accepting any other value
  -- here would be this routine promising a mode it has no way to pass on.
  if v_ctx <> 'production' then
    raise exception 'fn_phase_d_drive_workflow: execution_context % is not available. This driver goes through fn_kernel_step_complete, and fn_phase_d_dispatch_step executes the handler in production context with no other mode. (pd_drive_context_unavailable)',
      v_ctx using errcode = '22023';
  end if;

  select * into w from public.phase_b_workflow where workflow_id = v_wf;
  if not found then
    raise exception 'fn_phase_d_drive_workflow: % is not a frozen workflow', v_wf using errcode = '23503';
  end if;

  select count(*) into v_before from public.phase_d_effect_ledger;

  -- THE ARRIVAL NAMES THE OBJECT IT IS ABOUT. E25 derives business_key from the run's
  -- business_object_id and only when it carries the '<object>:' prefix of the object the step
  -- writes - 'inquiry:<uuid>' is an identity, a bare object name is not. The previous driver
  -- passed w.primary_object, which is the object's NAME, so the prefix test was false on every
  -- run it started and the derivation E25 built could never fire through this path.
  v_boid := coalesce(v_boid, w.primary_object || ':' || v_label);

  -- G05. EVERY RUN AROSE BY ITSELF, SO NO RUN COULD REST ON FOUNDER AUTHORITY.
  --
  -- This started every one of the 30 workflows with source_kind 'autonomous' and no command_id.
  -- fn_phase_d_step_context resolves founder_authority_ref from founder_command_workflow_link for
  -- the run, or failing that from phase_c_workflow_run.command_id -- and an autonomous start
  -- leaves both empty by construction. So the key was unresolvable on every run of every workflow,
  -- and the six rules that read it refused every founder-gated step in the estate. Measured:
  -- W03-S01 and W18-S05 refused with "BR-003 requires [founder_authority_ref] and the call names
  -- none of it", and the scenario factory had created a founder command four statements earlier
  -- and handed back founder_authority_ref in its parent_refs, where nothing read it.
  --
  -- The correction is an ARRIVAL, not an injection. fn_kernel_workflow_start already accepts
  -- source_kind 'founder_command' with a command_id, and that is how a founder-instructed run is
  -- really started in production; F12's fixture command is a real row in public.founder_command
  -- created through its own canonical service inside this aborted transaction. Starting the run
  -- from it makes the run's origin TRUE rather than absent. Handing the rule a reference for a run
  -- that arose autonomously would have been the forgery; a run that has no origin at all is simply
  -- a run nothing instructed.
  --
  -- THE FOUNDER COMMAND IS ONLY USED WHERE THE FROZEN REGISTRY SAYS THE WORKFLOW IS FOUNDER-GATED,
  -- and which workflows those are is read from phase_b_business_rule.workflow_scope and
  -- phase_b_workflow_step.founder_gate, never listed here. A workflow with no founder-reserved
  -- step still starts autonomously, and BR-003 stays unresolvable there -- as it should, since
  -- BR-003 does not govern it.
  --
  -- IT AUTHORISES NOTHING BEYOND ITS OWN SENTENCE. The fixture command carries
  -- founder_initiated_only false and refund_semantics false, its founder_identity resolves to
  -- nobody, and founder AUTHENTICATION is fn_phase_c_require_founder, which reads a verified auth
  -- subject and never this table. z00_refund_founder_decision_only on public.refunds is untouched
  -- and still refuses a refund without a founder decision -- measured after this change, not
  -- assumed.
  if exists (select 1 from public.phase_b_workflow_step fs
              where fs.workflow_id = v_wf
                and lower(coalesce(btrim(fs.founder_gate),'none')) <> 'none')
     or exists (select 1 from public.phase_b_business_rule br
                 where br.rule_id in (select re.rule_id from public.phase_d_rule_enforcement re
                                       where 'founder_authority_ref' = any(re.required_context))
                   and (upper(br.workflow_scope) = 'ALL'
                        or v_wf = any(string_to_array(replace(br.workflow_scope,' ',''),';'))))
  then
    -- The command the factory recorded, read from the evidence manifest it wrote — the same row
    -- fn_phase_d_founder_authority_fixture returned, not a second lookup that might find another.
    select nullif(split_part(l.contributed_value, ':', 2),'')::bigint into v_founder_cmd
      from public.phase_d_scenario_record l
     where l.fixture_run_id = public.fn_phase_d_fixture_context()
       and l.contributes_ref = 'founder_authority_ref'
     order by l.scenario_record_id desc limit 1;
  end if;

  v_start := public.fn_kernel_workflow_start(jsonb_build_object(
    'workflow_id',        v_wf,
    'business_object_id', v_boid,
    'source_kind',        case when v_founder_cmd is null then 'autonomous' else 'founder_command' end,
    'source_ref',         format('zz-phase-d-%s-%s', v_label, v_wf),
    'requested_by',       w.accountable_role_id,
    'trigger_ctx',        jsonb_build_object('driver','fn_phase_d_drive_workflow',
                                             'path','kernel doors only'))
    || case when v_founder_cmd is null then '{}'::jsonb
            else jsonb_build_object('command_id', v_founder_cmd) end);
  if v_founder_cmd is not null then
    -- fn_kernel_event_consume refuses an event naming a workflow the command did not select, so the
    -- selection is recorded here rather than left implied by the run alone.
    -- K01. THE run_id WAS NEVER WRITTEN. fn_phase_d_step_context reads this table by run_id
    -- first, and all 15 rows carried run_id null, so that read had never matched a row in the
    -- estate's history. It is stamped here -- and ONLY where the kernel's own row says this command
    -- started this run. Where the arrival started the run first (H06) the command did not instruct
    -- it, and claiming otherwise would put founder authority under a customer's inquiry.
    insert into public.founder_command_workflow_link (command_id, workflow_id, run_id)
    values (v_founder_cmd, v_wf,
            (select r2.run_id from public.phase_c_workflow_run r2
              where r2.run_id = v_run and r2.command_id = v_founder_cmd))
    on conflict (command_id, workflow_id) do update
      set run_id = excluded.run_id
      where public.founder_command_workflow_link.run_id is null
        and excluded.run_id is not null;
  end if;
  v_run := (v_start->>'run_id')::bigint;
  if v_run is null then
    return jsonb_build_object('ok', false, 'workflow_id', v_wf,
      'stopped_because', 'the kernel returned no run_id', 'kernel_result', v_start);
  end if;

  -- H06. THE RUN ALREADY EXISTED: the scenario's own arrival started it before the scenario was
  -- complete, and its first dispatch judged half a world. Each open step run whose latest dispatch
  -- was a refusal is dispatched once more, through the same door, under the kernel's own key.
  if coalesce((v_start->>'duplicate')::boolean, false) then
    v_premature := true;
    for sr in select * from public.phase_c_workflow_step_run
               where run_id = v_run
                 and state in ('ready','active','not_ready','waiting_input','waiting_review','blocked')
               order by step_run_id
    loop
      select * into d from public.phase_d_dispatch
       where step_run_id = sr.step_run_id order by dispatch_id desc limit 1;
      if found and d.outcome <> 'EXECUTED' then
        begin
          perform public.fn_phase_d_dispatch_step(jsonb_build_object(
            'step_run_id',     sr.step_run_id,
            'actor_role_id',   sr.accountable_role_id,
            'opened_by_kind',  'scenario_complete',
            'opened_by_ref',   format('the scenario finished after the arrival opened %s', sr.step_id),
            'idempotency_key', (select ws.idempotency_scope from public.phase_b_workflow_step ws
                                 where ws.step_id = sr.step_id) || '|' || v_run || '|' || sr.step_id || '|kernel'));
          v_redispatched := v_redispatched + 1;
        exception when others then null;
        end;
      end if;
    end loop;
  end if;

  loop
    v_i := v_i + 1;
    exit when v_i > v_max;

    select * into sr from public.phase_c_workflow_step_run
     where run_id = v_run
       and state in ('ready','active','not_ready','waiting_input','waiting_review','blocked')
     order by step_run_id
     limit 1;

    -- ---- NO OPEN STEP RUN IS NOT NECESSARILY A STOPPED RUN -----------------------------------
    -- The kernel opens no successor until the receiving owner accepts the handoff.
    if not found then
      select * into hr from public.phase_c_handoff_run
       where run_id = v_run and status = 'open'
       order by handoff_run_id limit 1;
      -- A DRIVER THAT STOPS WITHOUT SAYING WHY IS THE INSTRUMENT GAP THIS ESTATE KEEPS FINDING.
      -- Both of these were a bare `exit when not found` in my first draft, so a run that ended in
      -- waiting_handoff with no D9 contract reported a stop with an empty reason, and a reader
      -- would have taken the blank for "nothing went wrong".
      if not found then
        if v_stopped is null then
          v_stopped := jsonb_build_object(
            'at', (select state from public.phase_c_workflow_run where run_id = v_run),
            'refused_with','pd_drive_no_open_work',
            -- NO run_id IN A REPRODUCIBLE DELIVERABLE. This read "...on run 25384", and a run_id is
            -- different every drive, so the committed CSV could never reproduce byte-for-byte and
            -- phase_d_deliverables_match_production.test.mjs failed on thirty lines that differed
            -- only in that number. The run_id is on the row already, as run_id; a reason is a
            -- reason.
            'reason', 'no step run is open and no handoff run is open; the run is as far as the kernel will take it');
        end if;
        exit;
      end if;

      select * into hc from public.phase_d_handoff_contract where handoff_id = hr.handoff_id;
      if not found then
        if v_stopped is null then
          v_stopped := jsonb_build_object('at', hr.handoff_id, 'refused_with','pd_handoff_contract_absent',
            'reason', format('handoff %s is open and public.phase_d_handoff_contract holds no row for it, so this driver has no packet contract to satisfy', hr.handoff_id));
        end if;
        v_handoffs := v_handoffs || jsonb_build_array(jsonb_build_object(
          'handoff_id', hr.handoff_id, 'handoff_run_id', hr.handoff_run_id,
          'ok', false, 'refused_with', 'pd_handoff_contract_absent'));
        exit;
      end if;

      select * into v_prev from public.phase_c_workflow_step_run
       where step_run_id = hr.from_step_run_id;

      -- Derived where the estate can derive it; a labelled caller assertion for the work-product
      -- keys, which are what the sending PERSON hands over and no business rule ever reads.
      v_hpk := coalesce((select jsonb_object_agg(k, format('ZZ DEMO - %s declared by the driver standing in for %s', k, hc.sending_role_id))
                           from unnest(hc.packet_keys) k), '{}'::jsonb)
             || jsonb_build_object(
                  'business_object_id',
                    coalesce((select business_object_id from public.phase_c_workflow_run
                               where run_id = v_run), v_boid),
                  'object_version', coalesce(hr.object_version, 1),
                  'output', coalesce(v_prev.output_hash,
                                     'no output hash recorded on the sending step run'),
                  'evidence_refs',
                    coalesce((select string_agg(result_reference, '; ' order by effect_id)
                                from public.phase_d_effect_ledger
                               where step_run_id = hr.from_step_run_id),
                             'no Phase D effect recorded for the sending step run'),
                  'requested_action',
                    coalesce((select required_action from public.phase_b_workflow_step
                               where step_id = hc.to_step_id),
                             'the frozen receiving step names no required action'));

      begin
        v_hoff := public.fn_phase_d_handoff_accept(jsonb_build_object(
          'handoff_run_id',  hr.handoff_run_id,
          'actor_role_id',   hc.receiving_role_id,
          'packet',          v_hpk,
          'idempotency_key', format('%s:%s:%s', v_label, hr.handoff_id, hr.handoff_run_id)));
        v_haccept := v_haccept + 1;
        v_handoffs := v_handoffs || jsonb_build_array(jsonb_build_object(
          'handoff_id', hr.handoff_id, 'handoff_run_id', hr.handoff_run_id,
          'ok', v_hoff->'ok', 'to_step_id', v_hoff->>'to_step_id',
          'accountable_after', v_hoff->>'accountable_after'));
        continue;
      exception when others then
        v_sqlstate := SQLSTATE; v_err := SQLERRM;
        v_code := coalesce((regexp_match(v_err, '\((pd_[a-z0-9_]+|k[0-9]+_[a-z0-9_]+)\)'))[1], '(none)');
        v_handoffs := v_handoffs || jsonb_build_array(jsonb_build_object(
          'handoff_id', hr.handoff_id, 'handoff_run_id', hr.handoff_run_id,
          'ok', false, 'refused_with', v_code, 'sqlstate', v_sqlstate,
          'reason', left(v_err, 400)));
        if v_stopped is null then
          v_stopped := jsonb_build_object('at', hr.handoff_id, 'refused_with', v_code,
                                          'reason', left(v_err, 400));
        end if;
        -- A driver that skipped a refused handoff would report a closure the workflow never reached.
        exit;
      end;
    end if;

    -- ---- THE HOLD ----------------------------------------------------------------------------
    -- Reached only through the doors above: every earlier step was completed through
    -- fn_kernel_step_complete and every earlier handoff through fn_phase_d_handoff_accept. This
    -- step run is open because the kernel opened it and nothing has closed it.
    if v_hold_any or (v_hold_step is not null and sr.step_id = v_hold_step) then
      v_held_srid := sr.step_run_id;
      v_held_step := sr.step_id;
      v_seen := v_seen || sr.step_run_id;
      if v_stopped is null then
        v_stopped := jsonb_build_object('at', sr.step_id, 'refused_with', 'pd_drive_held_open',
          'reason', 'the caller asked this drive to stop with this step open; nothing was completed on it');
      end if;
      exit;
    end if;

    -- ---- WHAT THE DETERMINISTIC HANDLER DID WITH THIS STEP ------------------------------------
    -- It has already happened. The dispatch fires when the kernel OPENS the step, so by the time
    -- this loop sees an open step run the row is on the table. Reading it is the whole of what this
    -- driver has to do to measure Phase D; it never calls the handler itself.
    select * into d from public.phase_d_dispatch
     where step_run_id = sr.step_run_id order by dispatch_id desc limit 1;

    -- ---- F17. THE CAPABILITY RESULT ARRIVES, AND THE STEP IS DISPATCHED AGAIN ------------------
    -- The founder's section C sequence is: capability request -> capability result -> output
    -- validation -> evidence/provenance -> handler continuation. F05 built the first four and left
    -- the fifth to the caller, because the request is opened INSIDE fn_kernel_open_step and there is
    -- no moment between the open and the refusal for anyone to answer it. This is that moment: the
    -- kernel opened the step, the handler asked and was refused for want of an answer, and the
    -- driver -- standing in for whoever supplies the capability -- submits the pre-authored fixture
    -- result through the canonical acceptance service and asks the estate to dispatch the step
    -- again.
    --
    -- Nothing here bypasses anything. fn_phase_d_capability_result_accept still requires a verified
    -- Phase D fixture context, still validates the payload against the step's own output contract,
    -- still records the fixture id, version and hash, and still refuses provider_mode = provider
    -- while the hold stands. If any of that refuses, the step stays refused and the refusal is
    -- recorded below rather than swallowed.
    if found and d.refusal_code = 'pd_capability_unavailable'
       and public.fn_phase_d_fixture_context() is not null then
      select c.fixture_id into v_cap_fixture
        from public.phase_d_fixture_catalogue c
       where c.scope = 'CAPABILITY_RESULT' and c.step_id = sr.step_id
       order by c.fixture_id limit 1;
      begin
        if v_cap_fixture is null then
          raise exception 'no committed CAPABILITY_RESULT fixture for step % (pd_capability_fixture_unknown)', sr.step_id
            using errcode = '23503';
        end if;
        v_cap_req := public.fn_phase_d_capability_request_open(jsonb_build_object(
          'step_run_id', sr.step_run_id, 'requested_by', sr.accountable_role_id));
        v_cap_res := public.fn_phase_d_capability_result_accept(jsonb_build_object(
          'request_id',    v_cap_req->'request_id',
          'provider_mode', 'fixture',
          'fixture_id',    v_cap_fixture,
          'accepted_by',   sr.accountable_role_id));
        v_capn := v_capn + 1;
        -- HANDLER CONTINUATION: the same door the kernel used, on the same step run.
        v_redisp := public.fn_phase_d_dispatch_step(jsonb_build_object(
          'step_run_id',     sr.step_run_id,
          'actor_role_id',   sr.accountable_role_id,
          'opened_by_kind',  'capability_result',
          'opened_by_ref',   format('%s:result=%s', v_cap_fixture, v_cap_res->>'result_id'),
          'idempotency_key', format('%s:%s:%s:cap', v_label, sr.step_id, sr.step_run_id)));
        v_caps := v_caps || jsonb_build_array(jsonb_build_object(
          'step_id', sr.step_id, 'request_id', v_cap_req->'request_id',
          'result_id', v_cap_res->'result_id', 'provider_mode', v_cap_res->>'provider_mode',
          'fixture_id', v_cap_res->>'fixture_id', 'fixture_version', v_cap_res->'fixture_version',
          'fixture_hash', v_cap_res->>'fixture_hash',
          'redispatch_outcome', v_redisp->>'outcome',
          'redispatch_refusal', v_redisp->>'refusal_code'));
        select * into d from public.phase_d_dispatch
         where step_run_id = sr.step_run_id order by dispatch_id desc limit 1;
      exception when others then
        v_caps := v_caps || jsonb_build_array(jsonb_build_object(
          'step_id', sr.step_id, 'fixture_id', v_cap_fixture, 'ok', false,
          'refused_with', coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
          'reason', left(SQLERRM, 300)));
      end;
      v_cap_fixture := null;
    end if;

    -- ---- THE INTERNAL REVIEW, THROUGH THE KERNEL'S OWN DOOR, THEN ASK AGAIN (F35) -----------
    -- The mirror of the capability block above, for the other input class the handler cannot
    -- invent. F34 made fn_phase_d_handler_execute read the verdict and the reviewer from the review
    -- the estate RECORDED -- phase_c_task.reviewer_role_id and the sealed TRACE-ROLE-ACTION -- and
    -- refuse with pd_review_not_recorded when there is none. There is none at step-open time,
    -- because the kernel dispatches the handler the instant the step opens and no review has
    -- happened yet. This is the moment one can: the step is open and owned, the handler has said
    -- what it is missing, and the driver -- standing in for the reviewer -- records the decision
    -- through fn_kernel_review_decide and asks the estate to dispatch the step again.
    --
    -- NOTHING IS BYPASSED. fn_kernel_review_decide refuses a reviewer the frozen registry did not
    -- name where it names one, refuses a reviewer who resolves to the creator, refuses a review
    -- with no stated reason, and seals its own trace. The reviewer is never chosen by preference
    -- here: it is the frozen independent_reviewer_role_id, or a candidate the kernel's own
    -- independence test allows. If it refuses, the step stays refused and the refusal is recorded.
    -- H11. Also record a review when a gate refused for want of the reviewer, not only when the
    -- REVIEW_HANDLER raised pd_review_not_recorded. Same review, same door, same independence check.
    if found and (d.refusal_code = 'pd_review_not_recorded'
                  or (d.refusal_code in ('pd_evidence_absent','pd_gate_refused')
                      and coalesce(d.reason,'') ilike '%reviewer_role_id%')) then
      begin
        select t.task_id into v_rtask from public.phase_c_task t
         where t.run_id = sr.run_id and t.step_id = sr.step_id
         order by t.task_id desc limit 1;

        select s2.independent_reviewer_role_id into v_rrev
          from public.phase_b_workflow_step s2 where s2.step_id = sr.step_id;
        v_rrev := nullif(btrim(coalesce(v_rrev,'')),'');
        if v_rrev is null then
          v_rrev := (select c from unnest(v_cands) c
                      where public.fn_kernel_reviewer_independent(sr.accountable_role_id, c)
                      limit 1);
        end if;
        if v_rrev is null and v_caller_reviewer is not null
           and public.fn_kernel_reviewer_independent(sr.accountable_role_id, v_caller_reviewer) then
          v_rrev := v_caller_reviewer;
        end if;

        if v_rtask is null then
          raise exception 'step % has no task to review (pd_review_no_task)', sr.step_id
            using errcode = '23503';
        end if;
        if v_rrev is null then
          raise exception 'step % is owned by % and no candidate role passes the kernel independence test against it (pd_review_no_independent_reviewer)',
            sr.step_id, sr.accountable_role_id using errcode = '23503';
        end if;

        -- The stated reason is the committed rationale fixture, not a sentence written here.
        v_rdec := public.fn_kernel_review_decide(jsonb_build_object(
          'task_id',          v_rtask,
          'reviewer_role_id', v_rrev,
          'decision',         'approved',
          'reason',           coalesce(
                                public.fn_phase_d_fixture_output(sr.step_id,'rationale') #>> '{}',
                                'PHASE_D_FIXTURE_DO_NOT_PUBLISH - no committed rationale fixture')));

        if coalesce((v_rdec->>'ok')::boolean, false) then
          v_redisp := public.fn_phase_d_dispatch_step(jsonb_build_object(
            'step_run_id',     sr.step_run_id,
            'actor_role_id',   sr.accountable_role_id,
            'opened_by_kind',  'internal_review',
            'opened_by_ref',   format('task=%s;reviewer=%s', v_rtask, v_rrev),
            'idempotency_key', format('%s:%s:%s:rev', v_label, sr.step_id, sr.step_run_id)));
          select * into d from public.phase_d_dispatch
           where step_run_id = sr.step_run_id order by dispatch_id desc limit 1;
        end if;

        v_revn := v_revn + 1;
        v_revs := v_revs || jsonb_build_array(jsonb_build_object(
          'step_id', sr.step_id, 'task_id', v_rtask, 'reviewer_role_id', v_rrev,
          'review_ok', v_rdec->'ok', 'review_error', v_rdec->>'error',
          'redispatch_outcome', v_redisp->>'outcome',
          'redispatch_refusal', v_redisp->>'refusal_code'));
      exception when others then
        v_revs := v_revs || jsonb_build_array(jsonb_build_object(
          'step_id', sr.step_id, 'ok', false,
          'refused_with', coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
          'reason', left(SQLERRM, 300)));
      end;
    end if;

    if found then
      v_dispatched := v_dispatched + 1;
      if d.outcome = 'EXECUTED' then v_executed := v_executed + 1; end if;
      v_steps := v_steps || jsonb_build_array(jsonb_build_object(
        'step_id', sr.step_id, 'step_run_id', sr.step_run_id,
        'ok', (d.outcome = 'EXECUTED'), 'dispatch_outcome', d.outcome,
        'refused_with', nullif(d.refusal_code,''), 'reason', left(coalesce(d.reason,''), 400),
        'unresolved_keys', to_jsonb(coalesce(d.unresolved_keys,'{}'::text[])),
        'effect_id', d.effect_id));
      -- TWO SUBJECTS, TWO FIELDS. My first draft folded both into one 'stopped' object, and the
      -- deliverable then reported W21 as stopping at W21-S01 when the drive had in fact reached
      -- W21-S07 -- because step 1's dispatch refused, as nearly every dispatch does, and that was
      -- the first thing to claim the field. Where the HANDLER first declined is a Phase D fact;
      -- where the DRIVE could go no further is a fact about this harness and the kernel.
      if d.outcome <> 'EXECUTED' and v_first_refusal is null then
        v_first_refusal := jsonb_build_object('at', sr.step_id,
                                              'refused_with', nullif(d.refusal_code,''),
                                              'reason', left(coalesce(d.reason,''), 400));
      end if;
    else
      v_steps := v_steps || jsonb_build_array(jsonb_build_object(
        'step_id', sr.step_id, 'step_run_id', sr.step_run_id,
        'ok', false, 'dispatch_outcome', 'NOT_DISPATCHED',
        'refused_with', 'pd_no_dispatch_row',
        'reason', 'the kernel opened this step and no phase_d_dispatch row exists for it'));
      if v_first_refusal is null then
        v_first_refusal := jsonb_build_object('at', sr.step_id, 'refused_with','pd_no_dispatch_row',
          'reason','the kernel opened this step and no phase_d_dispatch row exists for it');
      end if;
    end if;

    -- ---- F38. THE HANDLER MAY HAVE ALREADY COMPLETED THIS STEP -----------------------------
    -- fn_phase_d_handler_execute section 7 hands the completed step to the FROZEN KERNEL itself.
    -- When it succeeds, the kernel closes the step run, opens the successor, and -- where the step
    -- ends in a handoff -- moves the whole run to waiting_handoff. The driver then arrived at its
    -- own fn_kernel_step_complete for a step that was already closed, against a run that was no
    -- longer active, and was refused:
    --
    --   k3_run_not_active: workflow run N is in state waiting_handoff, not active
    --
    -- and the drive stopped there. MEASURED, and it is the reason a fix made the headline fall:
    -- after F36 let the five capability steps execute, total EXECUTED across the estate went from
    -- 45 to 36, because every workflow whose handler succeeded early now died at the next
    -- iteration. Success in one place was being converted into an earlier stop.
    --
    -- The kernel is right on both counts and neither is touched. What was wrong is that this
    -- driver assumed every step needs an actor to close it. A step the HANDLER closed is closed;
    -- the driver re-reads the step run and, if the kernel has moved it out of every open state,
    -- takes the next piece of work instead of trying to close it twice.
    --
    -- This is also the §4 distinction the founder asked for: a step closed here is
    -- CANONICAL_HANDLER_EFFECT, and a step closed below is CANONICAL_ACTOR_INPUT. They are counted
    -- apart because they are different claims.
    v_seen := v_seen || sr.step_run_id;   -- G07: what this loop saw, so what it did not see is derivable
    select * into sr2 from public.phase_c_workflow_step_run where step_run_id = sr.step_run_id;
    if found and sr2.state not in
       ('ready','active','not_ready','waiting_input','waiting_review','blocked') then
      v_handler_closed := v_handler_closed + 1;
      v_steps := v_steps || jsonb_build_array(jsonb_build_object(
        'step_id', sr.step_id, 'step_run_id', sr.step_run_id,
        'closed_by', 'CANONICAL_HANDLER_EFFECT', 'step_run_state', sr2.state));
      continue;
    end if;

    -- ---- A STEP THAT NEEDS AN INDEPENDENT VERDICT GETS ONE, THROUGH THE KERNEL'S OWN DOOR ------
    -- The reviewer is never chosen here: it is the one the frozen registry declares, or one the
    -- CALLER offered, and fn_kernel_review_decide decides independence either way. A driver that
    -- picked a reviewer would be fn_pick_reviewer returning the department head, one layer up.
    select s.independent_reviewer_role_id into v_declared
      from public.phase_b_workflow_step s where s.step_id = sr.step_id;
    v_rev := nullif(btrim(coalesce(v_declared,'')),'');
    if v_rev is null then
      v_rev := (select c from unnest(v_cands) c
                 where public.fn_kernel_reviewer_independent(sr.accountable_role_id, c) limit 1);
    end if;
    if v_rev is null and v_caller_reviewer is not null
       and public.fn_kernel_reviewer_independent(sr.accountable_role_id, v_caller_reviewer) then
      v_rev := v_caller_reviewer;
    end if;
    if v_rev is not null then
      select t.task_id into v_task from public.phase_c_task t
       where t.run_id = v_run and t.step_id = sr.step_id order by t.task_id desc limit 1;
      if v_task is not null then
        begin
          v_decide := public.fn_kernel_review_decide(jsonb_build_object(
            'task_id', v_task, 'reviewer_role_id', v_rev, 'decision', 'approved',
            'reason', format('%s: an independent reviewer approves %s', v_label, sr.step_id)));
        exception when others then
          -- Recorded, never swallowed: a verdict that could not be written is why the step may
          -- refuse a moment later, and a driver that hid it would make that refusal unexplainable.
          v_decide := jsonb_build_object('ok', false, 'error', left(SQLERRM, 240));
        end;
      end if;
    end if;

    -- ---- THE DOOR PRODUCTION USES ------------------------------------------------------------
    -- fn_kernel_step_complete, with what an ACTOR supplies and nothing else. No context, no gate
    -- evidence, no business_key, no owner_ref, no effect payload: the kernel dispatch resolves all
    -- of those from fn_phase_d_step_inputs and fn_phase_d_step_context, and will not accept them
    -- from a caller. That is the property this file exists to restore.
    begin
      perform public.fn_kernel_step_complete(jsonb_build_object(
        'step_run_id',      sr.step_run_id,
        'actor_role_id',    sr.accountable_role_id,
        'outcome',          'pass',
        'idempotency_key',  format('%s:%s:%s', v_label, sr.step_id, sr.step_run_id),
        'inputs',           jsonb_build_object('driver','fn_phase_d_drive_workflow',
                                               'note','no business content is supplied by this driver'),
        'output',           jsonb_build_object('status','completed',
                                               'output', format('%s completed %s', v_label, sr.step_id)),
        'evidence_refs',    jsonb_build_array(jsonb_build_object('driver_run', v_label)),
        'requested_action', 'proceed',
        'acceptance_criteria', format('%s drove %s through the kernel', v_label, sr.step_id),
        'object_version',   1));
      v_driven := v_driven + 1;
    exception when others then
      v_sqlstate := SQLSTATE; v_err := SQLERRM;
      v_code := coalesce((regexp_match(v_err, '\((pd_[a-z0-9_]+|k[0-9]+_[a-z0-9_]+)\)'))[1], '(none)');
      v_steps := v_steps || jsonb_build_array(jsonb_build_object(
        'step_id', sr.step_id, 'step_run_id', sr.step_run_id,
        'ok', false, 'kernel_refused', true, 'refused_with', v_code,
        'sqlstate', v_sqlstate, 'reason', left(v_err, 400)));
      v_stopped := jsonb_build_object('at', sr.step_id, 'refused_with', v_code,
                                      'reason', left(v_err, 400),
                                      'refused_by', 'fn_kernel_step_complete');
      exit;
    end;
  end loop;

  select state into v_run_state from public.phase_c_workflow_run where run_id = v_run;

  -- G07. THE CLOSURES THIS LOOP NEVER SAW, read from the ledger that already recorded them.
  -- A step run carrying an EXECUTED dispatch and sitting in no open state was closed by the
  -- handler's own call into fn_kernel_step_complete. Excluding the step runs the loop handled makes
  -- the two counts disjoint by construction rather than by argument.
  -- ALIASED disp, NOT d: this routine declares a RECORD named d, and a plpgsql variable shadows a
  -- table alias of the same name rather than losing to it.
  select count(distinct disp.step_run_id) into v_unseen
    from public.phase_d_dispatch disp
    join public.phase_c_workflow_step_run x on x.step_run_id = disp.step_run_id
   where disp.run_id = v_run
     and disp.outcome = 'EXECUTED'
     and x.state not in ('ready','active','not_ready','waiting_input','waiting_review','blocked')
     and not (disp.step_run_id = any(v_seen));

  return jsonb_build_object(
    'ok', true,
    'workflow_id', v_wf,
    'run_id', v_run,
    'label', v_label,
    -- Named for what it measures, not for what a reader might hope it measures.
    'path', 'fn_kernel_workflow_start -> fn_kernel_review_decide -> fn_kernel_step_complete -> fn_phase_d_handoff_accept',
    'steps_in_workflow', (select count(*) from public.phase_b_workflow_step where workflow_id = v_wf),
    'held_step_id', v_held_step,
    'held_step_run_id', v_held_srid,
    'steps_driven', v_driven,
    'handoffs_accepted', v_haccept,
    'open_handoffs_left', (select count(*) from public.phase_c_handoff_run
                            where run_id = v_run and status = 'open'),
    -- What Phase D actually did: how many step-openings the kernel dispatched to the
    -- deterministic handler, and how many of those the handler completed unaided.
    -- COUNTED FROM THE TABLE, NOT FROM THIS LOOP. The first version incremented these as the loop
    -- walked the open steps, and it reported dispatches_executed = 0 on a run that had produced
    -- three effect-ledger rows. The reason is the whole of E33: a step whose handler EXECUTES has
    -- its task closed in the same statement that opened it, so it is never an open step and this
    -- loop never sees it. An instrument that counts only what it walks past cannot count the thing
    -- that finishes before the walk reaches it. The population is every dispatch the kernel
    -- produced for this run.
    'dispatches_seen', (select count(*) from public.phase_d_dispatch where run_id = v_run),
    'dispatches_executed', (select count(*) from public.phase_d_dispatch
                             where run_id = v_run and outcome = 'EXECUTED'),
    'dispatch_outcomes', (select coalesce(jsonb_object_agg(o, n), '{}'::jsonb) from (
        select coalesce(nullif(refusal_code,''), outcome) o, count(*) n
          from public.phase_d_dispatch where run_id = v_run group by 1) z),
    'steps_loop_walked', v_dispatched,
    'effects_for_this_run', (select count(*) from public.phase_d_effect_ledger where run_id = v_run),
    'effects_total_delta', (select count(*) from public.phase_d_effect_ledger) - v_before,
    'run_state', v_run_state,
    -- phase_b_workflow.allowed_terminal_states is TEXT, not an array: 'completed; cancelled;
    -- superseded'. My first draft wrote `v_run_state = any((select allowed_terminal_states ...))`,
    -- which Postgres parses as the SUBQUERY form of ANY — so it compared the run state against the
    -- whole semicolon-separated string as one value and was false for every run ever driven.
    -- closure_verdict could therefore only ever read STOPPED, and this deliverable reported 0 of 30
    -- closing while runs were reaching 'completed'. Caught by the deliverable's own reproduction
    -- test, not by reading the code.
    'terminal', exists (
       select 1 from public.phase_b_workflow w2,
            lateral unnest(string_to_array(coalesce(w2.allowed_terminal_states,''), ';')) s
        where w2.workflow_id = v_wf and btrim(s) = v_run_state),
    -- Where the DRIVE could go no further. Null only when the run reached a terminal state with
    -- nothing open, which is the one case where "it stopped" needs no explanation.
    'stopped', coalesce(v_stopped, case when v_i > v_max
      then jsonb_build_object('at','(step budget)','refused_with','pd_drive_max_steps',
             'reason', format('the drive ran %s steps and max_steps is %s', v_i - 1, v_max))
      else null end),
    -- Where the deterministic HANDLER first declined. This is the Phase D subject, and it is a
    -- different question from the one above. Read from the dispatch table in dispatch order for
    -- the same reason the counts are: the loop does not see every dispatched step.
    'first_handler_refusal', coalesce(
      (select jsonb_build_object('at', step_id, 'refused_with', nullif(refusal_code,''),
                                 'reason', left(coalesce(reason,''), 400))
         from public.phase_d_dispatch
        where run_id = v_run and outcome <> 'EXECUTED'
        order by dispatch_id limit 1), v_first_refusal),
    'capability_results_accepted', v_capn,
    'premature_arrival_run', v_premature,
    'steps_redispatched_after_scenario', v_redispatched,
    'capability_path', v_caps,
    'steps_closed_by_the_handler', v_handler_closed + v_unseen,
    'steps_closed_by_the_handler_before_the_loop_began', v_unseen,
    'internal_reviews_recorded', v_revn,
    'review_path', v_revs,
    'steps', v_steps,
    'handoffs', v_handoffs);
end

fn_phase_d_fixture_for_column:
declare
  v_oid    oid := p_relation::regclass;
  v_ftype  text;
  v_tcat   text;
  v_attnum smallint;
  v_def    text;
  v_lits   text[];
begin
  select a.attnum, format_type(a.atttypid, a.atttypmod),
         (select ty.typcategory from pg_type ty where ty.oid = a.atttypid)
    into v_attnum, v_ftype, v_tcat
    from pg_attribute a
   where a.attrelid = v_oid and a.attname = p_column and a.attnum > 0;
  if v_attnum is null then
    raise exception 'fn_phase_d_fixture_for_column: % has no column %', p_relation, p_column
      using errcode = '42703';
  end if;

  -- conkey = ARRAY[attnum] restricts this to checks over THIS column alone. A multi-column check
  -- that merely mentions the column enumerates a relationship, not a value set, and reading its
  -- literals would produce a value that satisfies nothing.
  select pg_get_constraintdef(c.oid) into v_def
    from pg_constraint c
   where c.conrelid = v_oid and c.contype = 'c' and c.conkey = array[v_attnum]
   order by c.conname
   limit 1;

  if v_def is not null then
    select array_agg(m[1] order by ord) into v_lits
      from regexp_matches(v_def, '''([^'']+)''', 'g') with ordinality t(m, ord);
    if v_lits is not null and cardinality(v_lits) > 0 then
      -- An enumerated column takes a DECLARED value. It is no longer visibly a fixture, and that is
      -- the constraint's decision, not a shortcut: the row is still identifiable as a fixture by
      -- every unconstrained column on it.
      if v_tcat = 'A' then
        return jsonb_build_array(v_lits[1]);
      end if;
      return to_jsonb(v_lits[1]);
    end if;
  end if;

  return public.fn_phase_d_fixture_value(v_ftype, v_tcat, p_label);
end

fn_phase_d_handoff_packet_valid:
declare
  c public.phase_d_handoff_contract%rowtype;
  v_all text[];
begin
  select * into c from public.phase_d_handoff_contract where handoff_id = p_handoff_id;
  if not found then
    -- Fail closed. An uncontracted handoff is not a permissive one.
    valid := false;
    missing := array['(no Phase D contract for ' || coalesce(p_handoff_id,'(null)') || ')'];
    required := '{}'; present := '{}';
    return next; return;
  end if;

  if p_packet is null or jsonb_typeof(p_packet) <> 'object' then
    valid := false; missing := c.packet_keys || c.kernel_packet_keys;
    required := c.packet_keys || c.kernel_packet_keys; present := '{}';
    return next; return;
  end if;

  -- BOTH sets. The contract keys come from the frozen prose; the kernel keys come from the kernel.
  -- Dropping either would mean a packet that satisfies this routine and is then refused downstream,
  -- or the reverse — a check that disagrees with the thing it guards.
  v_all := c.packet_keys || c.kernel_packet_keys;

  select array_agg(k order by k) into missing
    from unnest(v_all) k
   where not (p_packet ? k)
      or jsonb_typeof(p_packet->k) = 'null'
      or (jsonb_typeof(p_packet->k) = 'string' and btrim(p_packet->>k) = '');

  select array_agg(k order by k) into present
    from unnest(v_all) k where p_packet ? k;

  required := v_all;
  present  := coalesce(present, '{}');
  valid    := (missing is null);
  return next;
end

fn_phase_d_handoff_accept:
declare
  c        public.phase_d_handoff_contract%rowtype;
  hr       public.phase_c_handoff_run%rowtype;
  r        public.phase_c_workflow_run%rowtype;
  prior    public.phase_d_handoff_acceptance%rowtype;
  v_id     bigint := nullif(p_input->>'handoff_run_id','')::bigint;
  v_actor  text   := nullif(btrim(coalesce(p_input->>'actor_role_id','')),'');
  v_packet jsonb  := p_input->'packet';
  v_idem   text   := nullif(btrim(coalesce(p_input->>'idempotency_key','')),'');
  v_valid  record;
  v_res    jsonb;
  v_resolved text;
  v_due    timestamptz;
  v_tasks  int;
  v_aid    bigint;
  v_pd_executed boolean;   -- E33: did the Phase D handler execute the receiving step at open?
begin
  if v_id is null or v_actor is null then
    raise exception 'fn_phase_d_handoff_accept: handoff_run_id and actor_role_id are both required (pd_handoff_input_invalid)'
      using errcode = '22023';
  end if;
  v_idem := coalesce(v_idem, format('pd-handoff-accept:%s', v_id));

  select * into hr from public.phase_c_handoff_run where handoff_run_id = v_id;
  if not found then
    raise exception 'fn_phase_d_handoff_accept: no handoff run % (pd_handoff_not_found)', v_id
      using errcode = '23503';
  end if;

  -- IDEMPOTENCY IS A READ. The kernel would raise k3_handoff_not_open on a second call, which is
  -- correct but tells a replaying caller nothing about what happened the first time. The stored
  -- decision is returned verbatim and NOTHING is created.
  select * into prior from public.phase_d_handoff_acceptance where handoff_run_id = v_id;
  if found then
    return jsonb_build_object(
      'ok', prior.outcome = 'accepted', 'replay', true,
      'handoff_run_id', v_id, 'handoff_id', prior.handoff_id, 'outcome', prior.outcome,
      'run_id', prior.run_id, 'to_step_id', prior.to_step_id,
      'step_run_id', prior.opened_step_run_id, 'task_id', prior.opened_task_id,
      'accountable_now', prior.accountable_after,
      'note', 'this handoff run already carries a Phase D decision; no second task was opened');
  end if;

  select * into c from public.phase_d_handoff_contract where handoff_id = hr.handoff_id;
  if not found then
    raise exception 'fn_phase_d_handoff_accept: handoff % carries no Phase D contract — refusing to accept under a contract nobody declared (pd_handoff_uncontracted)',
      hr.handoff_id using errcode = '23503';
  end if;

  if hr.status <> 'open' then
    raise exception 'fn_phase_d_handoff_accept: handoff run % is % and only an open handoff may be accepted (pd_handoff_not_open)',
      v_id, hr.status using errcode = '23514';
  end if;

  select * into r from public.phase_c_workflow_run where run_id = hr.run_id;
  if not found then
    raise exception 'fn_phase_d_handoff_accept: handoff run % names workflow run %, which does not exist (pd_handoff_run_missing)',
      v_id, hr.run_id using errcode = '23503';
  end if;
  -- A run that has reached a terminal state, or is blocked, cannot take work back. The kernel
  -- would move it to active regardless, because its transition guard permits waiting_* -> active
  -- and says nothing about cancelled -> active being reached from here.
  if r.state not in ('waiting_handoff','waiting_review','active','waiting_input') then
    raise exception 'fn_phase_d_handoff_accept: run % is in state % and no handoff may be accepted into it (pd_handoff_run_state_invalid)',
      r.run_id, r.state using errcode = '23514';
  end if;

  -- THE RECEIVER, DECIDED FROM THE CONTRACT AND NOT FROM THE RUN ROW. The kernel checks the same
  -- thing against phase_c_handoff_run.receiving_role_id; checking the frozen contract as well means
  -- a handoff run whose receiver was written wrong cannot be accepted by the wrong role and then
  -- have the kernel agree with it.
  select role_id into v_resolved from public.fn_phase_c_resolve_actor(v_actor);
  if v_resolved is null
     or v_resolved is distinct from (select role_id from public.fn_phase_c_resolve_actor(c.receiving_role_id)) then
    raise exception 'fn_phase_d_handoff_accept: handoff % is addressed to % and % may not accept it (pd_handoff_wrong_receiver)',
      c.handoff_id, c.receiving_role_id, v_actor using errcode = '23514';
  end if;

  select * into v_valid from public.fn_phase_d_handoff_packet_valid(hr.handoff_id, v_packet);
  if not v_valid.valid then
    raise exception 'fn_phase_d_handoff_accept: handoff % packet is missing [%]. Its frozen required_packet is: % (pd_handoff_packet_incomplete)',
      c.handoff_id, array_to_string(v_valid.missing, ', '),
      left((select required_packet from public.phase_b_handoff where handoff_id = c.handoff_id), 180)
      using errcode = '23514';
  end if;

  -- SLA is a measurement, not a second gate. A late acceptance is still an acceptance; recording it
  -- as a breach is the contract element, and refusing it would invent a rule Phase B does not state.
  v_due := coalesce(hr.due_at, hr.opened_at + c.sla_target);

  -- ---- the frozen kernel does the state move ---------------------------------------------------
  v_res := public.fn_kernel_handoff_accept(jsonb_build_object(
    'handoff_run_id', v_id, 'actor_role_id', v_actor, 'packet', v_packet,
    'priority', coalesce(nullif(p_input->>'priority',''), 'P2')));

  if not coalesce((v_res->>'ok')::boolean, false) then
    raise exception 'fn_phase_d_handoff_accept: the kernel refused handoff run %: % (pd_handoff_kernel_refused)',
      v_id, coalesce(v_res::text, '(no result)') using errcode = '23514';
  end if;

  -- AT MOST ONE OPEN TASK ON THE RECEIVING STEP, AND ZERO HAS TWO DIFFERENT CAUSES. Asserted on
  -- the row count, not inferred from the kernel's own summary. `phase_c_task` carries
  -- (run_id, step_id) and no step_run_id, so the population is the receiving step of this run; a
  -- duplicate acceptance that opened a second task makes this 2, which is precisely the failure
  -- "duplicate acceptance creating duplicate task = 0" names.
  --
  -- E33. THIS WAS WRITTEN AS <> 1 AND SO IT ALSO REFUSED ZERO, WHICH SINCE D36 IS WHAT PHASE D
  -- WORKING LOOKS LIKE. The dispatch runs in the kernel's OPENER, so this very acceptance opens the
  -- receiving step and the deterministic handler attempts it in the same statement. If the handler
  -- EXECUTES, the step's work is done and the kernel closes its task - and this count is 0. W01-S05
  -- and W21-S08 are the only two steps in the estate whose handler executes, and they were the only
  -- two whose incoming handoff was refused. A guard that fires exactly when the system works.
  --
  -- Measured before changing it: two drives of W01 differing only in app.phase_d_dispatch. With the
  -- dispatch ON the run stops after W01-S05, whose dispatch reads EXECUTED and whose task is
  -- closed. With it OFF the run reaches W01-S06 with an OPEN task. One variable, opposite outcomes.
  select count(*) into v_tasks from public.phase_c_task t
   where t.run_id = r.run_id and t.step_id = c.to_step_id and t.closed_at is null;

  v_pd_executed := exists (
    select 1 from public.phase_d_dispatch d
     where d.run_id = r.run_id and d.step_id = c.to_step_id and d.outcome = 'EXECUTED');

  if v_tasks > 1 then
    raise exception 'fn_phase_d_handoff_accept: accepting handoff run % left % open task(s) on %; a second open task is a duplicate acceptance (pd_handoff_task_count_wrong)',
      v_id, v_tasks, c.to_step_id using errcode = '23514';
  end if;
  if v_tasks = 0 and not v_pd_executed then
    raise exception 'fn_phase_d_handoff_accept: accepting handoff run % left no open task on % and no Phase D dispatch executed that step, so nothing is carrying the work (pd_handoff_task_count_wrong)',
      v_id, c.to_step_id using errcode = '23514';
  end if;

  insert into public.phase_d_handoff_acceptance
    (handoff_run_id, handoff_id, run_id, workflow_id, outcome, actor_role_id,
     accountable_before, accountable_after, to_step_id, opened_step_run_id, opened_task_id,
     packet_digest, packet_keys_present, packet_keys_missing, sla_policy_id, due_at, sla_breached,
     idempotency_key, trace_id)
  values (v_id, c.handoff_id, r.run_id, r.workflow_id, 'accepted', v_resolved,
          c.accountable_before_accept, c.accountable_after_accept, c.to_step_id,
          (v_res->>'step_run_id')::bigint, (v_res->>'task_id')::bigint,
          encode(sha256(convert_to(coalesce(v_packet,'{}'::jsonb)::text,'UTF8')),'hex'),
          v_valid.present, null, c.sla_policy_id, v_due,
          case when v_due is null then null else now() > v_due end,
          v_idem, (v_res->>'handoff_trace_id')::bigint)
  returning acceptance_id into v_aid;

  if v_aid is null then
    raise exception 'fn_phase_d_handoff_accept: the acceptance ledger insert for handoff run % returned no id (pd_handoff_ledger_produced_nothing)',
      v_id using errcode = '23502';
  end if;

  return jsonb_build_object(
    'ok', true, 'replay', false, 'acceptance_id', v_aid,
    'handoff_run_id', v_id, 'handoff_id', c.handoff_id,
    'run_id', r.run_id, 'workflow_id', r.workflow_id,
    'accepted_by', v_resolved,
    'accountable_before', c.accountable_before_accept,
    'accountable_after', c.accountable_after_accept,
    'to_step_id', c.to_step_id,
    'step_run_id', (v_res->>'step_run_id')::bigint,
    'task_id', (v_res->>'task_id')::bigint,
    -- E33. WHO IS CARRYING THE RECEIVING STEP, on the row rather than only in a comment. An
    -- acceptance that opened a task for a person and one whose step the deterministic handler had
    -- already completed are different events, and a reader must not have to infer which from a
    -- null.
    'open_tasks_on_receiving_step', v_tasks,
    'receiving_step_handled_by',
      case when v_tasks = 1 then 'actor'
           when v_pd_executed then 'phase_d_handler'
           else 'nobody' end,
    'tasks_opened', v_tasks,
    'packet_keys_checked', v_valid.required,
    'sla_policy_id', c.sla_policy_id, 'due_at', v_due,
    'sla_breached', case when v_due is null then null else now() > v_due end,
    'run_state', v_res->>'run_state',
    'closure_condition', c.closure_condition);
end

fn_phase_d_handoff_reject:
declare
  c       public.phase_d_handoff_contract%rowtype;
  hr      public.phase_c_handoff_run%rowtype;
  prior   public.phase_d_handoff_acceptance%rowtype;
  v_id    bigint := nullif(p_input->>'handoff_run_id','')::bigint;
  v_actor text   := nullif(btrim(coalesce(p_input->>'actor_role_id','')),'');
  v_reason text  := nullif(btrim(coalesce(p_input->>'reason','')),'');
  v_missing text := nullif(btrim(coalesce(p_input->>'missing','')),'');
  v_return text  := nullif(btrim(coalesce(p_input->>'return_owner','')),'');
  v_code  text   := nullif(btrim(coalesce(p_input->>'rejection_code','')),'');
  v_idem  text   := nullif(btrim(coalesce(p_input->>'idempotency_key','')),'');
  v_resolved text;
  v_before int; v_after int;
  v_state_before text; v_state_after text;
  v_hstatus_before text; v_hstatus_after text;
  v_aid   bigint;
begin
  if v_id is null or v_actor is null then
    raise exception 'fn_phase_d_handoff_reject: handoff_run_id and actor_role_id are both required (pd_handoff_input_invalid)'
      using errcode = '22023';
  end if;
  v_idem := coalesce(v_idem, format('pd-handoff-reject:%s', v_id));

  select * into hr from public.phase_c_handoff_run where handoff_run_id = v_id;
  if not found then
    raise exception 'fn_phase_d_handoff_reject: no handoff run % (pd_handoff_not_found)', v_id
      using errcode = '23503';
  end if;

  select * into prior from public.phase_d_handoff_acceptance where handoff_run_id = v_id;
  if found then
    return jsonb_build_object('ok', false, 'replay', true, 'handoff_run_id', v_id,
      'outcome', prior.outcome, 'rejection_code', prior.rejection_code,
      'note', 'this handoff run already carries a Phase D decision');
  end if;

  select * into c from public.phase_d_handoff_contract where handoff_id = hr.handoff_id;
  if not found then
    raise exception 'fn_phase_d_handoff_reject: handoff % carries no Phase D contract (pd_handoff_uncontracted)',
      hr.handoff_id using errcode = '23503';
  end if;

  if hr.status <> 'open' then
    raise exception 'fn_phase_d_handoff_reject: handoff run % is % and only an open handoff may be decided (pd_handoff_not_open)',
      v_id, hr.status using errcode = '23514';
  end if;

  -- A REJECTION MUST BE ACTIONABLE. "Rejected" with no missing item leaves the work nowhere, which
  -- is the accountability gap the frozen closure_condition is written against.
  if v_reason is null or v_missing is null then
    raise exception 'fn_phase_d_handoff_reject: handoff % must be rejected with BOTH a reason and the exact missing item. Its frozen rejection_condition is: % (pd_handoff_rejection_unspecific)',
      c.handoff_id, left(c.rejection_condition, 160) using errcode = '22023';
  end if;

  select role_id into v_resolved from public.fn_phase_c_resolve_actor(v_actor);
  if v_resolved is null
     or v_resolved is distinct from (select role_id from public.fn_phase_c_resolve_actor(c.receiving_role_id)) then
    raise exception 'fn_phase_d_handoff_reject: handoff % is addressed to % and % may not decide it (pd_handoff_wrong_receiver)',
      c.handoff_id, c.receiving_role_id, v_actor using errcode = '23514';
  end if;

  -- The return owner defaults to the frozen contract's, never to whoever happens to be calling.
  v_return := coalesce(v_return, c.return_owner_role_id);

  select count(*) into v_before from public.phase_c_workflow_step_run where run_id = hr.run_id;
  select state into v_state_before from public.phase_c_workflow_run where run_id = hr.run_id;
  v_hstatus_before := hr.status;

  -- NO KERNEL PRIMITIVE IS CALLED. See the header: there is no fn_kernel_handoff_reject, Phase C is
  -- frozen, and fn_phase_c_handoff_decide is kernel-internal. The decision is recorded on the Phase D
  -- side and the kernel's handoff run is left exactly as it was.

  select count(*) into v_after from public.phase_c_workflow_step_run where run_id = hr.run_id;
  select state into v_state_after from public.phase_c_workflow_run where run_id = hr.run_id;
  select status into v_hstatus_after from public.phase_c_handoff_run where handoff_run_id = v_id;

  -- Asserted, not assumed. A rejection that advanced the workflow would be the defect §4 names.
  if v_after <> v_before then
    raise exception 'fn_phase_d_handoff_reject: rejecting handoff run % opened % new step run(s). A rejected handoff advances nothing. (pd_handoff_rejection_advanced_workflow)',
      v_id, v_after - v_before using errcode = '23514';
  end if;
  if v_state_after is distinct from v_state_before then
    raise exception 'fn_phase_d_handoff_reject: rejecting handoff run % moved run % from % to %. (pd_handoff_rejection_moved_run)',
      v_id, hr.run_id, v_state_before, v_state_after using errcode = '23514';
  end if;

  insert into public.phase_d_handoff_acceptance
    (handoff_run_id, handoff_id, run_id, workflow_id, outcome, actor_role_id,
     accountable_before, accountable_after, to_step_id,
     packet_digest, packet_keys_present, rejection_code, rejection_reason, missing_items,
     return_owner_role_id, sla_policy_id, due_at, idempotency_key)
  values (v_id, c.handoff_id, hr.run_id, c.workflow_id, 'rejected', v_resolved,
          c.accountable_before_accept,
          -- ACCOUNTABILITY DOES NOT TRANSFER ON A REJECTION. It returns to the named return owner,
          -- which is the whole point of the field; recording the receiver here would lose it.
          v_return, c.to_step_id,
          encode(sha256(convert_to(coalesce(p_input->'packet','{}'::jsonb)::text,'UTF8')),'hex'),
          '{}', coalesce(v_code, c.rejection_code), v_reason, v_missing, v_return,
          c.sla_policy_id, hr.due_at, v_idem)
  returning acceptance_id into v_aid;

  return jsonb_build_object(
    'ok', true, 'outcome', 'rejected', 'acceptance_id', v_aid,
    'handoff_run_id', v_id, 'handoff_id', c.handoff_id, 'run_id', hr.run_id,
    'rejection_code', coalesce(v_code, c.rejection_code),
    'reason', v_reason, 'missing', v_missing,
    'return_owner_role_id', v_return, 'accountable_now', v_return,
    'step_runs_before', v_before, 'step_runs_after', v_after,
    'run_state_before', v_state_before, 'run_state_after', v_state_after,
    'workflow_advanced', false,
    'kernel_handoff_status', v_hstatus_after,
    'kernel_handoff_still_open', (v_hstatus_after = 'open'),
    'disclosure', 'the frozen kernel exposes no handoff rejection routine, so the kernel-side handoff run is left open; closing it needs a Phase C change request, not a Phase D increment');
end

fn_phase_d_handoff_cancel:
declare
  v_run    bigint := nullif(p_input->>'run_id','')::bigint;
  v_reason text   := nullif(btrim(coalesce(p_input->>'reason','')),'');
  v_actor  text   := nullif(btrim(coalesce(p_input->>'actor_role_id','')),'');
  v_open_before int; v_open_after int; v_state text;
  v_res    jsonb;
begin
  if v_run is null or v_reason is null or v_actor is null then
    raise exception 'fn_phase_d_handoff_cancel: run_id, reason and actor_role_id are all required. A cancellation with no reason is not auditable. (pd_cancel_input_invalid)'
      using errcode = '22023';
  end if;

  select count(*) into v_open_before from public.phase_c_handoff_run
   where run_id = v_run and status = 'open';

  -- The kernel's own argument names, taken from its body rather than guessed.
  v_res := public.fn_kernel_cancel(jsonb_build_object(
    'subject_kind', 'workflow_run',
    'subject_ref',  v_run::text,
    'op',           'cancel',
    'reason',       v_reason,
    'actor',        v_actor));

  if not coalesce((v_res->>'ok')::boolean, false) then
    raise exception 'fn_phase_d_handoff_cancel: the kernel refused to cancel run %: % (pd_cancel_kernel_refused)',
      v_run, coalesce(v_res::text,'(no result)') using errcode = '23514';
  end if;

  select count(*) into v_open_after from public.phase_c_handoff_run
   where run_id = v_run and status = 'open';
  select state into v_state from public.phase_c_workflow_run where run_id = v_run;

  -- The postcondition is a row count, not an intention.
  if v_open_after <> 0 then
    raise exception 'fn_phase_d_handoff_cancel: run % was cancelled and % handoff run(s) are still open. (pd_cancel_left_open_handoff)',
      v_run, v_open_after using errcode = '23514';
  end if;
  if v_state is distinct from 'cancelled' then
    raise exception 'fn_phase_d_handoff_cancel: run % is % after a cancellation. (pd_cancel_run_not_cancelled)',
      v_run, coalesce(v_state,'(missing)') using errcode = '23514';
  end if;

  return jsonb_build_object(
    'ok', true, 'run_id', v_run, 'run_state', v_state,
    'open_handoffs_before', v_open_before, 'open_handoffs_after', v_open_after,
    'kernel_result', v_res);
end

fn_phase_d_fixture_scenario:
declare
  st       public.phase_d_fixture_stage%rowtype;
  v_label  text := nullif(btrim(coalesce(p_input->>'label','')),'');
  v_ctx    text := lower(coalesce(nullif(btrim(p_input->>'execution_context'),''),''));
  v_upto   int  := coalesce(nullif(p_input->>'up_to_stage','')::int, 9999);
  v_actor  text := coalesce(nullif(btrim(p_input->>'created_by'),''), 'phase_d_fixture_factory');
  v_refs   jsonb := '{}'::jsonb;
  v_man    jsonb := '[]'::jsonb;
  v_w      jsonb;
  v_pay    jsonb;
  v_key    text;
  v_owner  text;
  v_state  text;
  v_name   text;
  v_missing text[];
  v_ref_n  bigint;
  v_err    text;
  v_ok     int := 0; v_blocked int := 0; v_owned int := 0;
  v_for_wf text := nullif(btrim(coalesce(p_input->>'for_workflow','')),'');
  v_notif_before bigint; v_notif_after bigint;
  v_notif_id_before bigint;              -- G11: the high-water mark, so new rows are identifiable
  v_notif_id_start  bigint;              -- G13: the same, for the whole scenario rather than one stage
  v_inbox_before bigint; v_inbox_after bigint;
  v_notif_start  bigint; v_inbox_start  bigint;
  v_net_start    bigint;
  v_fixture_run  bigint;                     -- F01: the audited fixture run this build belongs to
  v_terms_ver    text;   v_terms_hash text;  -- F08: a REAL published document, not an invented one
  v_sup_ver      text;   v_sup_hash   text;
  v_art_sha      text;                       -- F08: the digest BR-036 resolves
  v_cat          jsonb;                      -- F08: a committed catalogue value
  v_scenario_id  bigint;
  v_state_col    text;    -- F15: the column the write map points at the state
  v_actual       text;    -- F15: what the product left in it
begin
  if v_label is null then
    raise exception 'fn_phase_d_fixture_scenario: label is required; it is what makes the ids deterministic and the residue findable (pd_fixture_label_missing)'
      using errcode = '22023';
  end if;
  if v_ctx <> 'test' then
    raise exception 'fn_phase_d_fixture_scenario: execution_context is %; this factory runs only in test (pd_fixture_not_test_context)',
      coalesce(nullif(v_ctx,''),'(unset)') using errcode = '23514';
  end if;
  -- F01. THIS READ A GUC ANY CALLER COULD SET. `set local app.phase_d_test_context = 'on'` was
  -- accepted from service_role, so the "protected test context" was a string the caller supplied
  -- about itself -- the same shape as a guard authenticating an email. The context is now an hmac
  -- over the current txid, keyed by a secret no role can SELECT, minted only by
  -- fn_phase_d_test_context_open against an approved audited operation.
  v_fixture_run := public.fn_phase_d_fixture_context();
  if v_fixture_run is null then
    raise exception 'fn_phase_d_fixture_scenario: no verified Phase D fixture context in this transaction (pd_fixture_no_test_context)'
      using errcode = '23514',
            hint = 'select public.fn_phase_d_test_context_open(''{"operation_key":"pdop_scenario_factory","label":"..."}''); and abort the transaction when finished.';
  end if;
  if current_user in ('anon','authenticated') then
    raise exception 'fn_phase_d_fixture_scenario: % may not build fixtures (pd_fixture_untrusted_caller)',
      current_user using errcode = '42501';
  end if;

  -- F08. BR-025 REQUIRES THE EXACT DISPLAYED VERSION AND ITS DIGEST, and this factory was writing
  -- 'zz-terms-v1' with sha256('zz-terms-v1') -- a hash OF THE VERSION STRING, not of any terms.
  -- The rule resolves the pair against public.legal_documents where the displayed body hashes to
  -- exactly that digest, so the acceptance the factory created could never be an acceptance of
  -- anything, and BR-025 refused every terms step for the right reason. The pair is now READ from
  -- the published document, so the fixture accepts terms that actually exist.
  select d.version, encode(sha256(convert_to(coalesce(d.body_html,''),'UTF8')),'hex')
    into v_terms_ver, v_terms_hash
    from public.legal_documents d where d.slug = 'customer-terms' order by d.version desc limit 1;
  select d.version, encode(sha256(convert_to(coalesce(d.body_html,''),'UTF8')),'hex')
    into v_sup_ver, v_sup_hash
    from public.legal_documents d where d.slug = 'supplier-agreement' order by d.version desc limit 1;
  -- The artifact digest is the digest of the committed artifact fixture's own text, so BR-036
  -- resolves it against a record this scenario writes rather than against a string.
  select encode(sha256(convert_to(c.value #>> '{}','UTF8')),'hex') into v_art_sha
    from public.phase_d_fixture_catalogue c
   where c.scope = 'CONTEXT_KEY' and c.field_key = 'artifact_ref';

  select coalesce(max(id),0) into v_net_start from net.http_request_queue;
  select count(*) into v_notif_start from public.notifications;
  select coalesce(max(id),0) into v_notif_id_start from public.notifications;  -- G13
  select count(*) into v_inbox_start from public.kernel_trigger_inbox;

  for st in select * from public.phase_d_fixture_stage where stage_no <= v_upto order by stage_no
  loop
    -- A SCENARIO MUST NOT PRE-CREATE THE OBJECT THE WORKFLOW UNDER TEST PRODUCES. W09 writes
    -- supplier_capability, W14 writes quotation, W16 writes payment_transaction; building those
    -- first made the workflow collide with its own output on a unique constraint, and a harness
    -- that seeds the row the step is supposed to create is answering its own question. The set is
    -- read from phase_d_step_effect for that workflow, never listed by hand.
    -- D22. THE EXCLUSION SKIPS LEAVES ONLY, SO A CASCADE IS IMPOSSIBLE BY CONSTRUCTION.
    --
    -- Measured with the old rule: for_workflow on W09 skipped 3 stages and the requires_stages
    -- cascade then blocked 13 MORE, because supplier_account is a parent of half the lineage. The
    -- D9 closure recorded the same shape as closure falling 14 -> 3, which is why the exclusion was
    -- left available and unused. Removing a parent to avoid a collision costs more than it saves.
    --
    -- A stage no other stage requires cannot cascade. supplier_assignment and provider_event are
    -- both leaves, and they are exactly the two collisions left: W12 writes supplier_assignment and
    -- GATE-015 correctly refused the fixture's as a duplicate dispatch. The skip is still recorded
    -- in the manifest as SKIPPED_PRODUCED_BY_THE_WORKFLOW_UNDER_TEST, never silently.
    if v_for_wf is not null
       and not exists (select 1 from public.phase_d_fixture_stage t
                        where st.stage_key = any(t.requires_stages))
       and exists (
         select 1 from public.phase_d_step_effect x
          where x.workflow_id = v_for_wf and x.effect_object_id = st.object_id) then
      v_man := v_man || jsonb_build_array(jsonb_build_object(
        'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
        'status', 'SKIPPED_PRODUCED_BY_THE_WORKFLOW_UNDER_TEST', 'detail', v_for_wf));
      v_owned := v_owned + 1;
      continue;
    end if;

    select array_agg(r) into v_missing
      from unnest(st.requires_stages) r
     where not exists (select 1 from jsonb_array_elements(v_man) m
                        where m->>'stage_key' = r and m->>'status' = 'CREATED');
    if v_missing is not null then
      v_man := v_man || jsonb_build_array(jsonb_build_object(
        'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
        'status', 'SKIPPED_PARENT_NOT_CREATED', 'detail', array_to_string(v_missing, ', ')));
      v_blocked := v_blocked + 1;
      continue;
    end if;

    if st.reference_relation is not null then
      execute format('select count(*) from %s', st.reference_relation) into v_ref_n;
      if v_ref_n = 0 then
        v_man := v_man || jsonb_build_array(jsonb_build_object(
          'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
          'status', 'BLOCKED_NO_REFERENCE_DATA', 'detail',
          format('%s holds 0 rows and this factory does not create business reference data',
                 st.reference_relation)));
        v_blocked := v_blocked + 1;
        continue;
      end if;
    end if;

    v_name  := format('ZZ DEMO — %s %s', v_label, st.stage_key);
    v_key   := md5(format('%s:%s', v_label, st.stage_key))::uuid::text;
    v_owner := v_key;
    -- F10. THE STATE IS THE STAGE'S OWN DECLARATION. This line used to read v_state := 'open' and
    -- every branch below then assigned a literal over it, so public.phase_d_fixture_stage.working_state
    -- -- the column whose sibling working_state_evidence explains, per stage, WHY that state -- was
    -- read by nothing at all. Five stages carried a state their object's contract does not declare
    -- and refused on every build since they were written; correcting the table changed nothing,
    -- because the table was not the source. It is now.
    v_state := coalesce(nullif(btrim(st.working_state),''), 'open');
    v_pay   := jsonb_build_object('fixture_label', v_label, 'stage', st.stage_key,
                                  'phase_d_test_context', true);

    -- D22. company_objective HAS NEVER ONCE CREATED ITS OBJECT.
    --
    -- D16 added this stage to fix W01-S03 dying on department_objective_goal_key_fkey, and it has
    -- refused on every build since with
    --     null value in column "goal" of relation "company_goals" violates not-null
    -- because the chain below has no branch for it, so the payload carried only the three
    -- bookkeeping keys every stage gets. The write map declares goal and metric; both are NOT NULL
    -- with no default.
    --
    -- Nothing failed loudly. stages_created read 23 of 25 and the missing one was recorded as
    -- REFUSED inside the manifest, where no caller was looking. A stage added to fix a foreign key
    -- and never observed creating anything is the "finished capability with no entry point" shape,
    -- and the only reason it surfaced is that a control started counting stages_not_created.
    if st.stage_key = 'company_objective' then
      v_pay := v_pay || jsonb_build_object(
        'goal', 1, 'metric', format('zz_demo_%s', v_label), 'active', true, 'direction', 'at_least');

    elsif st.stage_key = 'customer_account' then
      -- NO EMAIL AND NO PHONE. trg_inquiry_received_a queues a customer email for any inquiry whose
      -- customer has an address, and trg_new_quote_sms / trg_reveal_receipt_a do the same on a
      -- phone. The fixture identity carries neither, and the per-stage assertion below is what
      -- proves it rather than this comment.
      v_pay := v_pay || jsonb_build_object('full_name', v_name, 'locale', 'en');

    elsif st.stage_key = 'customer_terms_acceptance' then
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object(
        'terms_version', v_terms_ver,
        'terms_hash',    v_terms_hash,
        'accepted_by',   v_refs->>'customer_id');

    elsif st.stage_key = 'inquiry' then
      -- The FACTS fn_rfq_score reads, never a readiness flag. rfq_ready is derived by
      -- trg_rfq_complete and the verdict stays the product's own.
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || public.fn_phase_d_fixture_inquiry_payload(v_label);

    elsif st.stage_key = 'inquiry_answer' then
      v_owner := v_refs->>'inquiry_id';
      -- G11. THE GROUP IS A CHILD OF THIS SCENARIO'S OWN INQUIRY, so this stage creates it.
      -- public.inquiry_workstream_group holds 0 rows on production and this stage reported
      -- BLOCKED_NO_REFERENCE_DATA on every build since D9c. A group carries an inquiry_id foreign
      -- key and a defaulted rfq_mode and nothing else -- it is structure belonging to one inquiry,
      -- not a supplier or a field definition the estate shares. It is created for the inquiry this
      -- scenario created and rolled back with it.
      insert into public.inquiry_workstream_group (inquiry_id)
      values ((v_refs->>'inquiry_id')::uuid)
      on conflict do nothing;
      v_pay := v_pay || jsonb_build_object(
        'answer_scope','inquiry_shared', 'source_kind','customer', 'precedence','customer_confirmed',
        'value', to_jsonb('PHASE_D_FIXTURE_DO_NOT_PUBLISH — fixture answer'::text),
        'field_id', (select fd.field_id from public.field_definition fd order by fd.field_id limit 1),
        'group_id', (select g.id from public.inquiry_workstream_group g
                      where g.inquiry_id = (v_refs->>'inquiry_id')::uuid
                      order by g.id desc limit 1));

    elsif st.stage_key = 'notification' then
      -- G11. The recipient is the committed catalogue's reserved .invalid address and the channel
      -- is none. status is NOT set here: fn_phase_d_object_write's outbound-door loop overwrites it
      -- with the declared suppression in verified fixture context and does not let a caller opt out,
      -- which is exactly the D19 property -- a generated payload must not be able to re-arm a door.
      v_owner := 'phase_d_fixture';
      v_pay := v_pay || jsonb_build_object(
        'type', 'phase_d_fixture',
        'channel', 'none',
        'to_email', public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'recipient'),
        'subject', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — Phase D fixture notification record',
        'body', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture notification. It is written at the suppression the outbound door declares, no sender selects it, and it is created inside a transaction that is aborted.');

    elsif st.stage_key = 'inquiry_version' then
      v_owner := v_refs->>'inquiry_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id', 'version', 1);

    elsif st.stage_key = 'inquiry_route_set' then
      v_owner := v_refs->>'inquiry_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id',
                                           'route_state','confirmed', 'routes', '["general"]'::jsonb,
                                           'evidence','ZZ DEMO — fixture route evidence');

    elsif st.stage_key = 'inquiry_document' then
      v_owner := v_refs->>'inquiry_id';
      v_pay := v_pay || jsonb_build_object('kind','boq', 'mime','application/pdf',
                                           'bucket','zz-phase-d-fixtures',
                                           'path', format('zz/%s/%s.pdf', v_label, st.stage_key),
                                           'file_name', format('zz-%s.pdf', v_label));

    elsif st.stage_key = 'document_extraction' then
      v_owner := v_refs->>'document_id';
      v_pay := v_pay || jsonb_build_object('document_id', v_refs->>'document_id',
                                           'method','deterministic', 'paid_model_used', false);

    elsif st.stage_key = 'supplier_safe_package' then
      v_owner := v_refs->>'inquiry_id';
      v_pay := v_pay || jsonb_build_object(
        'inquiry_id', v_refs->>'inquiry_id',
        'safe_package_ref', v_key,
        'safe_package_approved_by', 'compliance_and_privacy_officer',
        'contents','ZZ DEMO — scope and quantities only; no customer identity');

    elsif st.stage_key = 'supplier_account' then
      v_pay := v_pay || jsonb_build_object('company_name', v_name, 'verified', true);

    elsif st.stage_key = 'supplier_terms_acceptance' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('terms_version', v_sup_ver,
        'terms_hash',  v_sup_hash,
        'supplier_id', v_refs->>'supplier_id');

    elsif st.stage_key = 'supplier_capability' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('trades', '["general"]'::jsonb);

    elsif st.stage_key = 'supplier_verification_case' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('supplier_id', v_refs->>'supplier_id',
                                           'evidence','ZZ DEMO — fixture verification evidence',
                                           'verified_by','supplier_verification');

    elsif st.stage_key = 'supplier_assignment' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id',
                                           'similarity', 0.9,
                                           'match_reason','ZZ DEMO — fixture assignment');

    elsif st.stage_key = 'quotation' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id', 'quote_amount', 1000);

    elsif st.stage_key = 'quotation_revision' then
      v_owner := v_refs->>'supplier_id';
      v_pay := v_pay || jsonb_build_object('quote_id', v_refs->>'quote_id',
                                           'quote_revision_ref', v_key, 'platform_edited', false);

    elsif st.stage_key = 'quotation_comparison' then
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id',
                                           'analysis', jsonb_build_object('note','ZZ DEMO — fixture comparison'),
                                           'quote_count', 1,
                                           'signature', encode(sha256(convert_to(v_key,'UTF8')),'hex'));

    elsif st.stage_key = 'customer_selection' then
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object('comparison_id', v_refs->>'comparison_id',
                                           'selected_quote_id', v_refs->>'quote_id');

    elsif st.stage_key = 'payment_transaction' then
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object('inquiry_id', v_refs->>'inquiry_id',
                                           'quote_id', v_refs->>'quote_id',
                                           'quote_amount', 1000, 'reveal_fee', 100,
                                           'payment_ref', format('zz-pay-%s', v_label));

    elsif st.stage_key = 'provider_event' then
      v_owner := v_refs->>'transaction_id';
      v_key := format('evt_zz_%s', v_label);
      v_pay := v_pay || jsonb_build_object('event_type','checkout.session.completed');

    elsif st.stage_key = 'reconciliation_case' then
      v_owner := v_refs->>'transaction_id';
      v_pay := v_pay || jsonb_build_object('transaction_id', v_refs->>'transaction_id',
                                           'monetary_state','reconciled');

    elsif st.stage_key = 'reveal_transaction' then
      v_key := v_refs->>'transaction_id';
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object('reveal_fee', 100,
                                           'payment_ref', format('zz-pay-%s', v_label),
                                           'revealed_at', now(),
                                           'supplier_id', (v_refs->>'supplier_id')::bigint);

    elsif st.stage_key = 'refund_dispute_case' then
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object('transaction_id', v_refs->>'transaction_id',
                                           'amount_fils', 10000, 'reason_code','other',
                                           'reason_note','ZZ DEMO — fixture refund case; no refund is executed',
                                           'requested_by', v_refs->>'customer_id');

    elsif st.stage_key = 'artifact_revision' then
      -- F08. BR-036 resolves artifact_sha256 against an artifact_review row or a business object
      -- record CARRYING that digest. public.artifact_review holds 0 rows, so the record is the
      -- only honest route: this stage writes one whose payload carries the digest of the committed
      -- artifact fixture's own text. The digest is computed, never typed.
      -- F48. v_art_sha WAS DECLARED AND NEVER ASSIGNED, SO THIS PAYLOAD CARRIED A NULL.
      --
      -- F08 added the variable with the comment "the digest BR-036 resolves" and the stage below
      -- writes it into the artifact record's payload. Nothing ever assigned it. Measured: BR-036
      -- refuses W08, W20, W22 and W24 with "review names artifact <id> at digest 5be99093ba73,
      -- which resolves to 0 artifact_review row(s) and 0 business object record(s) carrying exactly
      -- that digest" -- and the reason no record carries it is that this line wrote null.
      --
      -- The digest is the committed one F39 computed over the committed artifact body, read here
      -- rather than recomputed, so the value in the record is the same value the context resolver
      -- hands the rule and anyone can recompute both from the catalogue.
      v_art_sha := public.fn_phase_d_stage_content(st.object_id, 'CONTEXT_KEY', 'artifact_sha256');
      if v_art_sha is null then
        raise exception 'fn_phase_d_fixture_scenario: no committed artifact_sha256 fixture, so the artifact record would carry no digest and BR-036 could never pass or fail for a real reason (pd_fixture_artifact_digest_missing)'
          using errcode = '23502';
      end if;

      v_pay := v_pay || jsonb_build_object(
        'artifact_ref', public.fn_phase_d_stage_content(st.object_id, 'CONTEXT_KEY', 'artifact_ref'),
        'artifact_sha256', v_art_sha,
        'revision', 1);

    elsif st.stage_key = 'system_incident' then
      v_pay := v_pay || jsonb_build_object(
        'title',    public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'title'),
        'severity', 'low');

    elsif st.stage_key = 'marketing_content' then
      v_pay := v_pay || jsonb_build_object(
        'title', public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'title'),
        'body',  public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'body'),
        'channel','none', 'published', false);

    elsif st.stage_key = 'knowledge_capability_request' then
      v_pay := v_pay || jsonb_build_object(
        'requested_capability','REASONING',
        'note', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a knowledge/capability request record; no provider is called by Phase D');

    elsif st.stage_key = 'workforce_performance_case' then
      v_pay := v_pay || jsonb_build_object(
        'subject_role','phase_d_fixture_role',
        'note', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a workforce performance case about no real person and no real agent');

    elsif st.stage_key = 'notification_intent' then
      v_pay := v_pay || jsonb_build_object(
        'recipient',     public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'recipient'),
        'consent_basis', public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'consent_basis'),
        'provider_mode','mock', 'suppressed', true);

    elsif st.stage_key = 'department_mandate' then
      v_pay := v_pay || jsonb_build_object(
        'objective', public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'objective'),
        'goal_key',  v_refs->>'goal_key',
        'dept_key',  (select dept_key from public.org_departments where active order by dept_key limit 1));
      v_owner := (select dept_key from public.org_departments where active order by dept_key limit 1);

    elsif st.stage_key = 'review_record' then
      v_pay := v_pay || jsonb_build_object('verdict','approved',
                                           'subject_type','phase_d_fixture', 'subject_id', v_label,
                                           'author_agent','customer_onboarding',
                                           'reviewer_role_id','customer_success_director',
                                           'stage', st.stage_key, 'notes','ZZ DEMO — fixture review');

    -- G10. THE FOUR EXISTING RELATIONS WHOSE COLUMNS A HANDLER MUST NOT INVENT.
    elsif st.stage_key = 'initiative' then
      -- public.org_tasks.dept_key is a foreign key into public.org_departments and title is NOT
      -- NULL. The department is read from the estate and the title from the committed catalogue.
      v_owner := (select dept_key from public.org_departments where active order by dept_key limit 1);
      v_pay := v_pay || jsonb_build_object(
        'title',  public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'title'),
        'detail', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture initiative. It assigns no real work to any department and is created inside a transaction that is aborted.',
        'dept_key', (select dept_key from public.org_departments where active order by dept_key limit 1));

    elsif st.stage_key = 'legal_risk_review' then
      v_pay := v_pay || jsonb_build_object(
        'title',      public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'title'),
        'summary',    'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture legal risk review. No document was reviewed, no legal opinion is expressed, and it is created inside a transaction that is aborted.',
        'doc_kind',   'phase_d_fixture',
        'risk_level', 'low');

    elsif st.stage_key = 'partnership_opportunity' then
      v_pay := v_pay || jsonb_build_object(
        'kind',   public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'kind'),
        'title',  public.fn_phase_d_stage_content(st.object_id, 'EFFECT_PAYLOAD', 'title'),
        'detail', 'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture partnership opportunity. No partner is named, no approach is made, and it is created inside a transaction that is aborted.');

    elsif st.stage_key = 'invoice_receipt' then
      -- transaction_id is NOT NULL and a foreign key, so this stage depends on payment_transaction
      -- and takes the transaction the scenario created rather than choosing one.
      v_owner := v_refs->>'customer_id';
      v_pay := v_pay || jsonb_build_object(
        'transaction_id', v_refs->>'transaction_id',
        'bucket', 'zz-phase-d-fixtures',
        'path',   format('zz/%s/invoice-%s.pdf', v_label, st.stage_key));

    else
      -- G10. EVERY STAGE THE CHAIN ABOVE DOES NOT NAME, WHICH IS SIXTEEN PHASE D STORE OBJECTS AND
      -- ANY ADDED LATER. The object store writes from the payload every stage already carries, so
      -- the only thing these need is the one fact the store checks and a bookkeeping payload cannot
      -- supply: WHO OWNS THE RECORD. That is derived from the object's own declared ownership_scope
      -- rather than repeated sixteen times, so a CUSTOMER-scoped case is owned by the scenario's
      -- customer and a SUPPLIER-scoped one by its supplier. D9h found the opposite of this once --
      -- a customer-scoped object owned by something that was not a customer -- and a derivation
      -- cannot drift back into it one object at a time.
      v_owner := case (select ob.ownership_scope from public.phase_d_business_object_binding ob
                        where ob.object_id = st.object_id)
                   when 'CUSTOMER' then coalesce(nullif(v_refs->>'customer_id',''), v_key)
                   when 'SUPPLIER' then coalesce(nullif(v_refs->>'supplier_id',''), v_key)
                   else v_key end;
      v_pay := v_pay || jsonb_build_object('note', format(
        'PHASE_D_FIXTURE_DO_NOT_PUBLISH — a Phase D fixture %s, created through fn_phase_d_object_write inside a transaction that is aborted. It states nothing about the business and is never published.',
        st.object_id));
    end if;

    select count(*) into v_notif_before from public.notifications;
    select coalesce(max(id),0) into v_notif_id_before from public.notifications;  -- G11
    select count(*) into v_inbox_before from public.kernel_trigger_inbox;

    begin
      v_w := public.fn_phase_d_object_write(jsonb_build_object(
        'object_id', st.object_id, 'business_key', v_key, 'owner_ref', v_owner,
        'created_by', v_actor, 'state', v_state, 'payload', v_pay));

      select count(*) into v_notif_after from public.notifications;
      if v_notif_after <> v_notif_before then
        -- G11. A STAGE MAY WRITE INTO ITS OWN OBJECT'S CANONICAL RELATION, AND ONLY SUPPRESSED.
        -- The assertion exists because a canonical write to some OTHER object queued a message as a
        -- side effect, and that property is what the Phase D hold rests on. It could not tell that
        -- apart from the one stage whose DECLARED object is the notification. Narrowed by
        -- derivation, never by naming a stage: the relation must be this object's own canonical
        -- relation, and every row written must carry the suppression the outbound door declares for
        -- it. A stage writing here for any other object still aborts the build, and so does this one
        -- if the row it wrote is deliverable.
        if not exists (select 1 from public.phase_d_object_write_map wm2
                        where wm2.object_id = st.object_id
                          and wm2.target_relation = 'public.notifications')
           -- and every row this stage wrote must carry the state the stage declares, which is the
           -- value the outbound door forces and no sender selects. A row at any other status is a
           -- deliverable message and aborts the build exactly as before.
           or exists (select 1 from public.notifications n
                       where n.id > v_notif_id_before
                         and n.status is distinct from st.working_state)
        then
          raise exception 'fn_phase_d_fixture_scenario: stage % wrote % row(s) into public.notifications. A fixture may not queue an outbound message. (pd_fixture_external_effect_produced)',
            st.stage_key, v_notif_after - v_notif_before using errcode = '23514';
        end if;
      end if;

      -- F15. THE PRODUCT'S OWN TRIGGERS GET THE LAST WORD ON AN INSERT, SO SETTLE THE STATE.
      -- public.trg_inquiry_enrich is a BEFORE INSERT trigger that sets the status a NEW inquiry
      -- has, so the inquiry stage asked for quote_ready and the row came out open, and GATE-011
      -- and BR-013 refused it -- correctly, because it was not quote-ready. A real inquiry is
      -- created open and BECOMES quote-ready, so the factory now does that: create, read back the
      -- column the write map points at the state, and if the product moved it, write again through
      -- the same canonical service. Skipped entirely when the readback already agrees.
      select c.k into v_state_col
        from public.phase_d_object_write_map wm,
             lateral (select k from jsonb_object_keys(wm.column_map) k where wm.column_map->>k = 'state') c
       where wm.object_id = st.object_id limit 1;
      if v_state_col is not null then
        begin
          execute format('select %I::text from %s where %I::text = $1',
                         v_state_col,
                         (select wm.target_relation from public.phase_d_object_write_map wm
                           where wm.object_id = st.object_id),
                         (select wm.key_column from public.phase_d_object_write_map wm
                           where wm.object_id = st.object_id))
            into v_actual using coalesce(split_part(v_w->>'result_reference','=',2), v_key);
          if v_actual is distinct from v_state then
            -- H08. ADDRESS THE ROW THE FIRST WRITE RETURNED. v_key is the stage's own uuid and names
            -- nothing on a generated-key relation; the returned identity is the row.
            v_w := public.fn_phase_d_object_write(jsonb_build_object(
              'object_id', st.object_id,
              'business_key', coalesce(split_part(v_w->>'result_reference','=',2), v_key),
              'owner_ref', v_owner,
              'created_by', v_actor, 'state', v_state, 'payload', v_pay));
            v_man := v_man || jsonb_build_array(jsonb_build_object(
              'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
              'status','SETTLED',
              'detail', format('%s.%s was %s after the create and the stage declares %s; a second write through the same canonical service settled it',
                               v_state_col, st.object_id, coalesce(v_actual,'(null)'), v_state)));
          end if;
        exception when others then
          v_man := v_man || jsonb_build_array(jsonb_build_object(
            'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
            'status','SETTLE_REFUSED',
            'refused_with', coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
            'reason', left(SQLERRM, 300)));
        end;
        v_state_col := null; v_actual := null;
      end if;

      -- F02. THE EVIDENCE MANIFEST THE FOUNDER ASKED FOR. Written from what the canonical write
      -- RETURNED, in the same statement block, so a manifest entry cannot exist for an object the
      -- service did not create -- and so an object the service created cannot be missing from it.
      v_scenario_id := public.fn_phase_d_scenario_record_write(jsonb_build_object(
        'fixture_id',        format('PDS-%s', st.stage_key),
        'fixture_version',   1,
        'source_checksum',   encode(sha256(convert_to(v_pay::text,'UTF8')),'hex'),
        'object_id',         st.object_id,
        'business_key',      coalesce(split_part(v_w->>'result_reference','=',2), v_key),
        'owner_ref',         v_owner,
        'ownership_scope',   coalesce((select ob.ownership_scope
                                         from public.phase_d_business_object_binding ob
                                        where ob.object_id = st.object_id), 'COMPANY'),
        'state',             v_w->>'state',
        'canonical_relation',v_w->>'canonical_relation',
        'canonical_service', 'fn_phase_d_object_write',
        'result_reference',  v_w->>'result_reference',
        'contributes_ref',   st.contributes_ref,
        'contributes_kind',  st.contributes_kind,
        'canonical_ref',     v_w->'canonical_ref',
        'contributed_value', case when st.stage_key = 'inquiry_route_set' then 'confirmed'
                                  -- F41. A PAYLOAD_VALUE STAGE CONTRIBUTES A VALUE, NOT ITS ROW ID.
                                  -- artifact_revision declares it contributes artifact_sha256, and
                                  -- this expression handed over split_part(result_reference,'=',2)
                                  -- -- the primary key of the row it had just written. BR-036 read
                                  -- 44208 and refused it as "not a SHA-256 digest", correctly.
                                  -- The digest is in the record's own payload, written by F08 over
                                  -- the committed artifact body, so it is read from there.
                                  -- F42. AN OBJECT_KEY STAGE CONTRIBUTES THE KEY THE PHASE D
                                  -- OBJECT STORE USES, WHICH IS NOT THE RELATION'S ROW ID.
                                  -- F45. OBJECT_KEY AND RESULT_KEY WERE THE SAME QUESTION ASKED TWICE.
                                  -- Which identity an object is known by is a property of the
                                  -- object, recorded once in phase_d_object_reference_strategy and
                                  -- derived from the frozen map -- not something a stage decides.
                                  -- Both arms are now the canonical reference the writer returned.
                                  when st.contributes_kind in ('OBJECT_KEY','RESULT_KEY')
                                    then v_w->'canonical_ref'->>'canonical_identity'
                                  when st.contributes_kind = 'PAYLOAD_VALUE' then
                                    (select o.payload #>> array[st.contributes_ref]
                                       from public.phase_d_object_record o
                                      where o.object_id = st.object_id
                                        and o.business_key = split_part(v_w->>'result_reference', '=', 2)
                                      limit 1)
                                  else split_part(v_w->>'result_reference', '=', 2) end,
        'expected_effect',   coalesce(st.note,'(none recorded on the stage)')));

      if st.contributes_ref is not null then
        v_refs := v_refs || jsonb_build_object(st.contributes_ref,
          case when st.stage_key = 'inquiry_route_set' then 'confirmed'
               when st.contributes_kind in ('OBJECT_KEY','RESULT_KEY')
                 then v_w->'canonical_ref'->>'canonical_identity'
               when st.contributes_kind = 'PAYLOAD_VALUE' then
                 (select o.payload #>> array[st.contributes_ref]
                    from public.phase_d_object_record o
                   where o.object_id = st.object_id
                     and o.business_key = split_part(v_w->>'result_reference', '=', 2)
                   limit 1)
               else split_part(v_w->>'result_reference', '=', 2) end);
      end if;

      select count(*) into v_inbox_after from public.kernel_trigger_inbox;
      v_man := v_man || jsonb_build_array(jsonb_build_object(
        'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
        'status','CREATED', 'relation', v_w->>'canonical_relation',
        'result_reference', v_w->>'result_reference', 'state', v_w->>'state',
        'policy_family', v_w->>'policy_family',
        'notifications_written', v_notif_after - v_notif_before,
        'kernel_trigger_rows_written', v_inbox_after - v_inbox_before,
        'contributes', st.contributes_ref));
      v_ok := v_ok + 1;

    exception when others then
      v_err := SQLERRM;
      if position('pd_fixture_external_effect_produced' in v_err) > 0 then raise; end if;
      -- D17. An outbound HTTP request is not a stage that failed; it is the whole scenario losing
      -- its zero-external-effect property. It aborts the build exactly as a notification does.
      if position('pd_object_outbound_request_produced' in v_err) > 0 then raise; end if;
      v_man := v_man || jsonb_build_array(jsonb_build_object(
        'stage_no', st.stage_no, 'stage_key', st.stage_key, 'object_id', st.object_id,
        'status','REFUSED',
        'refused_with', coalesce((regexp_match(v_err,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
        'reason', left(v_err, 300)));
      v_blocked := v_blocked + 1;
    end;
  end loop;

  -- G12. THE THREE OBJECTS ONLY THE KERNEL MAY CREATE, asked for through the kernel's own doors.
  -- fn_phase_d_object_write refuses workflow_run, workflow_step_run and handoff_record by name --
  -- "a Phase D handler that wrote it would be a second creator for one object" -- so no stage of
  -- the chain above can create them and the round-trip proof reported all three as
  -- NOT_CREATED_BY_ANY_STAGE, counted as neither pass nor fail. This does not write them either: it
  -- calls fn_kernel_workflow_start and fn_kernel_step_complete and records what the kernel made.
  begin
    v_w := public.fn_phase_d_kernel_object_fixture(jsonb_build_object('label', v_label));
    v_man := v_man || jsonb_build_array(jsonb_build_object(
      'stage_no', 998, 'stage_key','kernel_objects', 'object_id','workflow_run/workflow_step_run/handoff_record',
      'status', case when coalesce((v_w->>'objects_recorded')::int,0) > 0 then 'CREATED' else 'REFUSED' end,
      'relation','public.phase_c_workflow_run + _step_run + _handoff_run',
      'result_reference', format('run_id=%s step_run_id=%s handoff_run_id=%s',
        coalesce(v_w->>'run_id','(none)'), coalesce(v_w->>'step_run_id','(none)'),
        coalesce(v_w->>'handoff_run_id','(none)')),
      'state','open', 'contributes', null, 'detail', v_w->>'note'));
    if coalesce((v_w->>'objects_recorded')::int,0) > 0 then v_ok := v_ok + 1;
    else v_blocked := v_blocked + 1; end if;
  exception when others then
    v_man := v_man || jsonb_build_array(jsonb_build_object(
      'stage_no', 998, 'stage_key','kernel_objects', 'object_id','workflow_run/workflow_step_run/handoff_record',
      'status','REFUSED',
      'refused_with', coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
      'reason', left(SQLERRM, 300)));
    v_blocked := v_blocked + 1;
  end;

  -- F12. THE FOUNDER AUTHORITY FIXTURE, LAST, BECAUSE NOTHING DEPENDS ON IT. Six rules resolve
  -- founder_authority_ref against public.founder_command; a Phase D run has no founder command
  -- behind it, so all six refuse on every founder-gated step. This creates one, marked, at state
  -- received, founder_initiated_only false and refund_semantics false, inside the same aborted
  -- transaction -- and it authenticates nobody: see the header of F12.
  begin
    v_w := public.fn_phase_d_founder_authority_fixture(jsonb_build_object('label', v_label));
    v_refs := v_refs || jsonb_build_object('founder_authority_ref', v_w->>'founder_authority_ref');
    v_man := v_man || jsonb_build_array(jsonb_build_object(
      'stage_no', 999, 'stage_key','founder_authority', 'object_id','founder_command_fixture',
      'status','CREATED', 'relation','public.founder_command',
      'result_reference', v_w->>'founder_authority_ref', 'state','received',
      'contributes','founder_authority_ref'));
    v_ok := v_ok + 1;
  exception when others then
    v_man := v_man || jsonb_build_array(jsonb_build_object(
      'stage_no', 999, 'stage_key','founder_authority', 'object_id','founder_command_fixture',
      'status','REFUSED',
      'refused_with', coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+)\)'))[1],'(none)'),
      'reason', left(SQLERRM, 300)));
    v_blocked := v_blocked + 1;
  end;

  select count(*) into v_notif_after from public.notifications;
  select count(*) into v_inbox_after from public.kernel_trigger_inbox;

  select coalesce(max(id),0) into v_notif_id_before from public.notifications;  -- reused as a bound

  return jsonb_build_object(
    'ok', v_blocked = 0, 'label', v_label, 'fixture_run_id', v_fixture_run,
    'evidence_manifest', (select coalesce(jsonb_agg(to_jsonb(x) order by x.scenario_record_id),'[]'::jsonb)
                            from public.phase_d_scenario_record x
                           where x.fixture_run_id = v_fixture_run),
    'stages_created', v_ok, 'stages_not_created', v_blocked,
    'stages_left_to_the_workflow_under_test', v_owned, 'for_workflow', v_for_wf,
    'stages_declared', (select count(*) from public.phase_d_fixture_stage where stage_no <= v_upto),
    'parent_refs', v_refs,
    -- THE RULE CONTEXT IS WHAT THIS SCENARIO ACTUALLY PERSISTED, not a set of plausible strings.
    -- Every value below is either a key returned by a write above or the exact value that write
    -- recorded on the row. A rule reading one of these is reading the scenario, and a rule whose
    -- key is absent still gets the driver's generated fixture and still refuses.
    -- F08. `rule_context` used to be returned here as a set of plausible strings for a caller to
    -- hand the rules. E32 removed the caller's ability to hand the kernel anything, so nothing has
    -- read it since; and two of its values were false -- terms_hash was the digest of the VERSION
    -- STRING, and safe_package_approved_by and assignment_result were literals with no record
    -- behind them. It is replaced by evidence_manifest above, which is what this scenario actually
    -- persisted, and by the committed catalogue for the values that are content rather than record.
    'parent_ref_keys', (select coalesce(jsonb_agg(k order by k),'[]'::jsonb)
                          from jsonb_object_keys(v_refs) k),
    'manifest', v_man,
    'notifications_written_by_this_scenario', v_notif_after - v_notif_start,
    -- G13. THE ONE THAT MUST BE ZERO. A row a sender would select is a queued outbound message; a
    -- row at the suppression the outbound door forces is a record. The suppression is read from the
    -- stage that declares it rather than written here, so there is no second copy of the word.
    'deliverable_notifications_written_by_this_scenario',
      (select count(*) from public.notifications n
        where n.id > coalesce(v_notif_id_start, 0)
          and n.status is distinct from (
            select st2.working_state from public.phase_d_fixture_stage st2
             where st2.object_id in (select wm3.object_id from public.phase_d_object_write_map wm3
                                      where wm3.target_relation = 'public.notifications')
             limit 1)),
    'kernel_trigger_rows_written_by_this_scenario', v_inbox_after - v_inbox_start,
    -- D17. MEASURED, NOT ASSERTED. Before D17 this object said 'external_effects', 0 while every
    -- build enqueued two POSTs to production edge functions, because the only thing counted was
    -- public.notifications. Both doors are now counted and the writer refuses on either.
    'outbound_http_requests_written_by_this_scenario',
      (select r.n from public.fn_phase_d_outbound_requests_by_this_transaction(v_net_start) r),
    'external_effects', 0, 'paid_calls', 0,
    'note', 'every row here was written through fn_phase_d_object_write; abort the transaction to leave nothing behind');
end

fn_phase_d_fixture_residue:
declare r record; v_n bigint; v_pred text;
begin
  for r in
    select distinct wm.target_relation as rel from public.phase_d_object_write_map wm
     union select 'public.phase_d_object_record'
  loop
    v_pred := (select string_agg(format(
                 '(coalesce(%I::text,'''') like ''ZZ DEMO — %%'' or coalesce(%I::text,'''') like ''%%@example.invalid'' or coalesce(%I::text,'''') like ''zz-phase-d-%%'')',
                 a.attname, a.attname, a.attname), ' or ')
               from pg_attribute a
              where a.attrelid = r.rel::regclass and a.attnum > 0 and not a.attisdropped
                and format_type(a.atttypid, a.atttypmod) in ('text','character varying','jsonb'));
    if v_pred is null then continue; end if;
    execute format('select count(*) from %s where %s', r.rel, v_pred) into v_n;
    if v_n > 0 then
      relation := r.rel; surviving_rows := v_n; return next;
    end if;
  end loop;
end

fn_phase_d_step_cases:
declare
  s   public.phase_b_workflow_step%rowtype;
  b   public.phase_d_handler_binding%rowtype;
  ins public.phase_d_handler_schema%rowtype;
  outs public.phase_d_handler_schema%rowtype;
  v_full jsonb; v_short jsonb; v record; v_k text;
  v_rule text; v_gate text; v_n int;
begin
  select * into s from public.phase_b_workflow_step where step_id = p_step_id;
  if not found then
    case_kind := 'positive'; decided_at := 'step_contract'; expectation := 'the step exists';
    passed := false; refused_with := 'step_unknown';
    detail := format('%s is not a frozen step', p_step_id); return next; return;
  end if;
  select * into b from public.phase_d_handler_binding where step_id = p_step_id;
  select * into ins  from public.phase_d_handler_schema where step_id = p_step_id and schema_kind='input';
  select * into outs from public.phase_d_handler_schema where step_id = p_step_id and schema_kind='output';

  -- a complete input payload, built from the step's OWN declared keys
  select coalesce(jsonb_object_agg(k, 'evidence for ' || k), '{}'::jsonb) into v_full
    from unnest(coalesce(ins.required_keys, '{}'::text[])) k;

  -- ---- 1. POSITIVE: the step's own contract accepts a complete payload ---------------------------
  select * into v from public.fn_phase_d_schema_validate(ins.schema_id, v_full);
  case_kind := 'positive'; decided_at := 'step_contract';
  expectation := 'a payload carrying every declared input key validates';
  passed := coalesce(v.valid, false); refused_with := null;
  detail := format('%s key(s) declared; %s', cardinality(coalesce(ins.required_keys,'{}')),
                   coalesce(v.reason, '(no reason)'));
  return next;

  -- ---- 2. MISSING INPUT: one declared key removed ------------------------------------------------
  if cardinality(coalesce(ins.required_keys,'{}')) = 0 then
    -- A step that declares no input cannot have one taken away. Recorded honestly rather than
    -- scored as a pass on a case that did not run.
    case_kind := 'missing_input'; decided_at := 'step_contract';
    expectation := 'removing a declared input key is refused';
    passed := false; refused_with := 'no_declared_input';
    detail := 'the frozen step declares no required input, so this case has no subject';
    return next;
  else
    v_k := ins.required_keys[1];
    v_short := v_full - v_k;
    select * into v from public.fn_phase_d_schema_validate(ins.schema_id, v_short);
    case_kind := 'missing_input'; decided_at := 'step_contract';
    expectation := format('removing %L is refused and the refusal names it', v_k);
    passed := (not coalesce(v.valid, true)) and (v.missing @> array[v_k]);
    refused_with := case when coalesce(v.valid,true) then null else 'pd_input_schema_invalid' end;
    detail := coalesce(v.reason, '(no reason)');
    return next;
  end if;

  -- ---- 3. WRONG ACTOR ---------------------------------------------------------------------------
  -- BR-004 is the rule that decides whether an acting identity is canonical, and the executor
  -- consults it for every step. An identity nobody models must not resolve.
  select * into v from public.fn_phase_d_rule_check('BR-004',
    jsonb_build_object('actor_role_id', 'zz_not_a_canonical_role_' || p_step_id));
  case_kind := 'wrong_actor'; decided_at := 'executor_boundary';
  expectation := 'an identity nobody models does not resolve to a canonical role';
  passed := (v.state = 'ENFORCED_FAIL') and not coalesce(v.ok, true);
  refused_with := v.refusal_code; detail := v.reason;
  return next;

  -- ---- 4. INVALID STATE -------------------------------------------------------------------------
  -- A step run that does not exist. The executor refuses before it reaches any write.
  begin
    perform public.fn_phase_d_handler_execute(jsonb_build_object(
      'step_run_id', -1, 'actor_role_id', s.accountable_role_id,
      'idempotency_key', 'pd-case-invalid-state:' || p_step_id,
      'inputs', v_full, 'execution_context', 'test'));
    case_kind := 'invalid_state'; decided_at := 'executor_boundary';
    expectation := 'a step run that does not exist is refused';
    passed := false; refused_with := null; detail := 'ACCEPTED — the executor ran against no step run';
  exception when others then
    case_kind := 'invalid_state'; decided_at := 'executor_boundary';
    expectation := 'a step run that does not exist is refused';
    refused_with := coalesce((regexp_match(SQLERRM,'\((pd_[a-z0-9_]+|k[0-9]+_[a-z0-9_]+)\)'))[1], '(none)');
    passed := refused_with = 'pd_step_state_invalid';
    detail := left(SQLERRM, 200);
  end;
  return next;

  -- ---- 5. DUPLICATE -----------------------------------------------------------------------------
  -- The guarantee is a UNIQUE constraint, not a convention, so the case reads the catalogue for the
  -- constraint itself. A test that trusted a constraint it never looked at is a test nobody ran.
  select count(*) into v_n from pg_constraint c
   where c.conrelid = 'public.phase_d_effect_ledger'::regclass and c.contype = 'u'
     -- attname is `name`, not `text`; the array comparison needs the cast or Postgres refuses the
     -- operator outright — which it did, and correctly.
     and (select array_agg(a.attname::text order by a.attname::text) from unnest(c.conkey) k
           join pg_attribute a on a.attrelid = c.conrelid and a.attnum = k)
         = array['effect_type','step_run_id']::text[];
  case_kind := 'duplicate'; decided_at := 'structural_constraint';
  expectation := 'a replayed handler cannot produce a second effect for one step run';
  passed := (v_n = 1);
  refused_with := case when v_n = 1 then 'pd_effect_replay' else null end;
  detail := format('%s UNIQUE(step_run_id, effect_type) constraint(s) on phase_d_effect_ledger', v_n);
  return next;

  -- ---- 6. FAILED RULE OR GATE -------------------------------------------------------------------
  -- Asked with an EMPTY context, at least one rule or gate in the step's own scope must refuse.
  -- A step whose whole scope passes on no evidence is a step nothing is enforcing.
  v_n := 0; v_rule := null; v_gate := null;
  if b.rule_ids is not null then
    for v_k in select unnest(b.rule_ids) loop
      select * into v from public.fn_phase_d_rule_check(v_k, '{}'::jsonb);
      if v.state in ('ENFORCED_FAIL','NOT_IMPLEMENTED') then
        v_n := v_n + 1; v_rule := coalesce(v_rule, v_k);
      end if;
    end loop;
  end if;
  if b.gate_ids is not null then
    for v_k in select unnest(b.gate_ids) loop
      select * into v from public.fn_phase_d_gate_evaluate(v_k, '{}'::jsonb);
      if not coalesce(v.passed, true) then v_n := v_n + 1; v_gate := coalesce(v_gate, v_k); end if;
    end loop;
  end if;
  case_kind := 'failed_rule_or_gate'; decided_at := 'executor_boundary';
  expectation := 'with no evidence at all, at least one rule or gate in scope refuses';
  passed := (v_n > 0);
  refused_with := case when v_n > 0 then coalesce('pd_rule_refused', 'pd_gate_refused') else null end;
  detail := format('%s of %s rule(s) and %s gate(s) in scope refuse an empty context; first %s',
                   v_n, cardinality(coalesce(b.rule_ids,'{}')), cardinality(coalesce(b.gate_ids,'{}')),
                   coalesce(v_rule, v_gate, '(none)'));
  return next;

  -- ---- 7. MALFORMED OUTPUT ----------------------------------------------------------------------
  select * into v from public.fn_phase_d_schema_validate(outs.schema_id, '{}'::jsonb);
  case_kind := 'malformed_output'; decided_at := 'step_contract';
  expectation := 'an empty output is refused by the step''s own output contract';
  passed := not coalesce(v.valid, true);
  refused_with := case when coalesce(v.valid,true) then null else 'pd_output_schema_invalid' end;
  detail := coalesce(v.reason, '(no reason)');
  return next;
end

fn_phase_d_run_step_cases:
declare
  st record; c record;
  v_steps int := 0; v_cases int := 0; v_passed int := 0;
  v_eff_before bigint; v_eff_after bigint; v_run_before bigint; v_run_after bigint;
begin
  -- NO CASE MAY WRITE. Counted around the whole matrix rather than promised in a comment.
  select count(*) into v_eff_before from public.phase_d_effect_ledger;
  select count(*) into v_run_before from public.phase_c_workflow_step_run;

  delete from public.phase_d_step_case_result;

  for st in select step_id from public.phase_b_workflow_step order by step_id loop
    v_steps := v_steps + 1;
    for c in select * from public.fn_phase_d_step_cases(st.step_id) loop
      insert into public.phase_d_step_case_result
        (step_id, case_kind, decided_at, expectation, passed, refused_with, detail)
      values (st.step_id, c.case_kind, c.decided_at, c.expectation, c.passed,
              c.refused_with, left(c.detail, 400))
      on conflict (step_id, case_kind) do update
        set decided_at = excluded.decided_at, expectation = excluded.expectation,
            passed = excluded.passed, refused_with = excluded.refused_with,
            detail = excluded.detail, run_at = now();
      v_cases := v_cases + 1;
      if c.passed then v_passed := v_passed + 1; end if;
    end loop;
  end loop;

  select count(*) into v_eff_after from public.phase_d_effect_ledger;
  select count(*) into v_run_after from public.phase_c_workflow_step_run;
  if v_eff_after <> v_eff_before or v_run_after <> v_run_before then
    raise exception 'fn_phase_d_run_step_cases: the matrix produced % effect(s) and % step run(s). A contract test may not write. (pd_case_matrix_had_a_side_effect)',
      v_eff_after - v_eff_before, v_run_after - v_run_before using errcode = '23514';
  end if;

  return jsonb_build_object(
    'ok', v_cases = v_steps * 7,
    'steps', v_steps, 'cases', v_cases, 'expected_cases', v_steps * 7,
    'passed', v_passed, 'failed', v_cases - v_passed,
    'effects_written', v_eff_after - v_eff_before,
    'step_runs_written', v_run_after - v_run_before);
end

fn_phase_d_stage_payment_state_declared:
begin
  if NEW.object_id in ('payment_transaction','reveal_transaction')
     and not exists (select 1 from public.phase_d_payment_state s
                      where s.state_key = NEW.working_state) then
    raise exception 'phase_d_fixture_stage: % declares working_state %, which is not a rung of public.phase_d_payment_state. BR-020 reads that ladder; a money state outside it is not a state. (pd_stage_payment_state_undeclared)',
      NEW.stage_key, NEW.working_state using errcode = '23514';
  end if;
  return NEW;
end

fn_phase_d_external_deliver:
declare
  v_step    text  := nullif(btrim(coalesce(p_input->>'step_id','')),'');
  v_idem    text  := nullif(btrim(coalesce(p_input->>'idempotency_key','')),'');
  v_case    text  := lower(nullif(btrim(coalesce(p_input->>'mock_case','')),''));
  v_mode    text  := lower(coalesce(nullif(btrim(p_input->>'provider_mode'),''),'mock'));
  v_payload jsonb := p_input->'approved_payload';
  v_ref     text  := nullif(btrim(coalesce(p_input->>'approved_payload_ref','')),'');
  v_effect  bigint := nullif(p_input->>'effect_id','')::bigint;
  v_kind    text  := lower(coalesce(nullif(btrim(p_input->>'effect_kind'),''),'generic'));
  v_prior   public.phase_d_external_attempt%rowtype;
  v_no      int;
  v_sha     text;
  v_reqid   text;
  v_resid   text;
  v_retry   text;
  v_delivered boolean := false;
  v_recon   text;
  v_dead    timestamptz;
  v_deadwhy text;
  v_cancel  timestamptz;
  v_cancelwhy text;
  v_id      bigint;
  v_missing text;
  v_cap     int := 3;
begin
  if v_step is null or v_idem is null or v_case is null or v_ref is null then
    raise exception 'fn_phase_d_external_deliver: step_id, idempotency_key, mock_case and approved_payload_ref are all required (pd_external_input_invalid)'
      using errcode = '22023';
  end if;
  if v_mode <> 'mock' then
    raise exception 'fn_phase_d_external_deliver: provider_mode is %; this adapter has no live mode and never sends (pd_external_live_mode_refused)', v_mode
      using errcode = '42501';
  end if;
  if public.fn_phase_d_fixture_context() is null then
    raise exception 'fn_phase_d_external_deliver: no verified Phase D fixture context in this transaction (pd_external_no_test_context)'
      using errcode = '23514';
  end if;
  -- FIELD 2. An intent with no approved payload is not deliverable. This is the field that was
  -- absent, and it is a refusal rather than a column: nothing may be delivered that nobody approved.
  if v_payload is null or jsonb_typeof(v_payload) <> 'object' or v_payload = '{}'::jsonb then
    raise exception 'fn_phase_d_external_deliver: % carries no approved payload. An intent nobody approved is not deliverable. (pd_external_payload_not_approved)', v_step
      using errcode = '22023';
  end if;

  -- THE FOUNDER'S FOUR-MESSAGE REVEAL CONTRACT, enforced on the payload rather than assumed.
  if v_kind = 'reveal' then
    select string_agg(c.contract_key, ', ' order by c.contract_key) into v_missing
      from public.phase_d_external_message_contract c
     where c.effect_kind = 'reveal' and c.required
       and not (coalesce(v_payload->'messages','[]'::jsonb) @> to_jsonb(array[c.contract_key]));
    if v_missing is not null then
      raise exception 'fn_phase_d_external_deliver: a reveal must carry all four messages the founder specified — an email and a WhatsApp to BOTH parties. Missing: %. (pd_external_reveal_contract_incomplete)', v_missing
        using errcode = '23514';
    end if;
  end if;

  v_sha := encode(sha256(convert_to(v_payload::text,'UTF8')),'hex');

  -- FIELD 12. A cancelled intent may not be delivered afterwards.
  select * into v_prior from public.phase_d_external_attempt
   where idempotency_key = v_idem and cancelled_at is not null
   order by attempt_no desc limit 1;
  if found and v_case <> 'cancellation' then
    raise exception 'fn_phase_d_external_deliver: % was cancelled at % and may not be delivered (pd_external_cancelled)',
      v_idem, v_prior.cancelled_at using errcode = '23514';
  end if;

  -- FIELD 9 + duplicate replay. The FIRST delivered attempt owns the result id.
  select * into v_prior from public.phase_d_external_attempt
   where idempotency_key = v_idem and delivered
   order by attempt_no asc limit 1;
  if found then
    -- A duplicate replay adds an attempt row for the audit trail and delivers NOTHING new.
    select coalesce(max(attempt_no),0) + 1 into v_no from public.phase_d_external_attempt where idempotency_key = v_idem;
    insert into public.phase_d_external_attempt
      (effect_id, step_id, idempotency_key, attempt_no, provider_mode, approved_payload_ref,
       approved_payload_sha256, provider_request_id, provider_result_id, provider_outcome,
       provider_detail, retry_class, delivered, reconciled_at, reconciliation_state)
    values (v_effect, v_step, v_idem, v_no, 'mock', v_ref, v_sha,
            format('req_mock_%s_%s', v_idem, v_no), v_prior.provider_result_id, 'duplicate_replay',
            format('replay of attempt %s; no second delivery', v_prior.attempt_no),
            'NOT_APPLICABLE', false, now(), 'MATCHED')
    returning attempt_id into v_id;
    return jsonb_build_object(
      'ok', true, 'replay', true, 'attempt_id', v_id, 'attempt_no', v_no,
      'provider_result_id', v_prior.provider_result_id,
      'delivered_now', false, 'first_delivery_attempt_no', v_prior.attempt_no,
      'provider_mode', 'mock', 'sent', false);
  end if;

  select coalesce(max(attempt_no),0) + 1 into v_no from public.phase_d_external_attempt where idempotency_key = v_idem;
  v_reqid := format('req_mock_%s_%s', v_idem, v_no);

  -- FIELDS 8 + 10 + 11 + 14: what the adapter DOES with each provider answer.
  if v_case = 'success' then
    v_resid := format('res_mock_%s_%s', v_idem, v_no); v_retry := 'NOT_APPLICABLE';
    v_delivered := true; v_recon := 'MATCHED';
  elsif v_case = 'suppression' then
    v_retry := 'NOT_APPLICABLE'; v_recon := 'SUPPRESSED';
  elsif v_case = 'null_result' then
    -- NOT A SUCCESS. quote_compare returned {ok:false} at HTTP 200 for weeks; a provider that
    -- answers with nothing has not delivered, and calling it delivered is that defect again.
    v_retry := 'RETRYABLE'; v_recon := 'NOT_DELIVERED';
  elsif v_case = 'retryable_failure' then
    v_retry := 'RETRYABLE'; v_recon := 'NOT_DELIVERED';
    if v_no >= v_cap then
      v_dead := now();
      v_deadwhy := format('%s retryable attempt(s) reached the cap of %s', v_no, v_cap);
      v_recon := 'DEAD_LETTERED';
    end if;
  elsif v_case = 'terminal_failure' then
    v_retry := 'TERMINAL'; v_dead := now();
    v_deadwhy := 'terminal provider failure; no further attempt is permitted';
    v_recon := 'DEAD_LETTERED';
  elsif v_case = 'cancellation' then
    v_retry := 'NOT_APPLICABLE'; v_cancel := now();
    v_cancelwhy := coalesce(nullif(btrim(p_input->>'cancel_reason'),''), 'cancelled before delivery');
    v_recon := 'CANCELLED';
  elsif v_case = 'duplicate_replay' then
    raise exception 'fn_phase_d_external_deliver: duplicate_replay is not a first attempt. Deliver once, then replay the same idempotency key. (pd_external_replay_without_delivery)'
      using errcode = '22023';
  else
    raise exception 'fn_phase_d_external_deliver: % is not a declared mock case (pd_external_unknown_case)', v_case
      using errcode = '22023';
  end if;

  insert into public.phase_d_external_attempt
    (effect_id, step_id, idempotency_key, attempt_no, provider_mode, approved_payload_ref,
     approved_payload_sha256, provider_request_id, provider_result_id, provider_outcome,
     provider_detail, retry_class, dead_lettered_at, dead_letter_reason,
     cancelled_at, cancel_reason, delivered, reconciled_at, reconciliation_state,
     trace_id)
  values (v_effect, v_step, v_idem, v_no, 'mock', v_ref, v_sha, v_reqid, v_resid, v_case,
          p_input->>'provider_detail', v_retry, v_dead, v_deadwhy, v_cancel, v_cancelwhy,
          v_delivered, now(), v_recon, nullif(p_input->>'trace_id','')::bigint)
  returning attempt_id into v_id;

  return jsonb_build_object(
    'ok', v_case in ('success','suppression','cancellation'),
    'attempt_id', v_id, 'attempt_no', v_no, 'provider_mode', 'mock', 'sent', false,
    'provider_request_id', v_reqid, 'provider_result_id', v_resid,
    'provider_outcome', v_case, 'retry_class', v_retry,
    'retry_permitted', (v_retry = 'RETRYABLE' and v_dead is null),
    'dead_lettered', v_dead is not null, 'dead_letter_reason', v_deadwhy,
    'cancelled', v_cancel is not null,
    'delivered', v_delivered, 'reconciliation_state', v_recon,
    'approved_payload_sha256', v_sha);
end

fn_phase_d_run_external_cases:
declare
  st record; c text; v jsonb; v_idem text; v_pass boolean; v_detail text;
  v_pay jsonb;
  CASES text[] := array['success','suppression','null_result','retryable_failure',
                        'terminal_failure','duplicate_replay','cancellation'];
begin
  if public.fn_phase_d_fixture_context() is null then
    -- F01. THIS READ A GUC ANY CALLER COULD SET. app.phase_d_test_context = 'on' was a string the
    -- caller supplied about itself; the context is now an hmac over txid_current(), keyed by a
    -- secret no role can SELECT, minted only against an approved audited operation. Leaving the old
    -- door open here would have left the whole control reachable through the value F01 removed.
    raise exception 'no verified Phase D fixture context in this transaction (pd_fixture_no_test_context)'
      using errcode = '23514',
            hint = 'select public.fn_phase_d_test_context_open(''{"operation_key":"pdop_deliverable_build","label":"..."}''); and abort the transaction when finished.';
  end if;

  for st in select e.step_id as sid from public.phase_d_step_effect e
             where e.expected_effect_type = 'EXTERNAL_EFFECT_INTENT' order by e.step_id
  loop
    foreach c in array CASES loop
      v_idem := format('zz-ext-%s-%s', st.sid, c);
      v_pay  := jsonb_build_object('subject', 'ZZ DEMO — ' || st.sid, 'body', 'ZZ DEMO — mock only');
      v_pass := false; v_detail := '';
      begin
        if c = 'duplicate_replay' then
          v := public.fn_phase_d_external_deliver(jsonb_build_object(
                 'step_id', st.sid, 'idempotency_key', v_idem, 'mock_case', 'success',
                 'approved_payload_ref', 'zz-approved-v1', 'approved_payload', v_pay));
          v := public.fn_phase_d_external_deliver(jsonb_build_object(
                 'step_id', st.sid, 'idempotency_key', v_idem, 'mock_case', 'success',
                 'approved_payload_ref', 'zz-approved-v1', 'approved_payload', v_pay));
          v_pass := coalesce((v->>'replay')::boolean,false)
                    and coalesce((v->>'delivered_now')::boolean,true) = false
                    and (select count(*) from public.phase_d_external_attempt
                          where idempotency_key = v_idem and delivered) = 1;
          v_detail := format('replay=%s deliveries=%s', v->>'replay',
                        (select count(*) from public.phase_d_external_attempt
                          where idempotency_key = v_idem and delivered));
        elsif c = 'cancellation' then
          v := public.fn_phase_d_external_deliver(jsonb_build_object(
                 'step_id', st.sid, 'idempotency_key', v_idem, 'mock_case', 'cancellation',
                 'approved_payload_ref', 'zz-approved-v1', 'approved_payload', v_pay));
          -- a later delivery on a cancelled intent must be REFUSED
          begin
            perform public.fn_phase_d_external_deliver(jsonb_build_object(
              'step_id', st.sid, 'idempotency_key', v_idem, 'mock_case', 'success',
              'approved_payload_ref', 'zz-approved-v1', 'approved_payload', v_pay));
            v_detail := 'a cancelled intent was delivered afterwards';
          exception when others then
            v_pass := position('pd_external_cancelled' in SQLERRM) > 0;
            v_detail := 'later delivery refused: ' || left(SQLERRM, 60);
          end;
        else
          v := public.fn_phase_d_external_deliver(jsonb_build_object(
                 'step_id', st.sid, 'idempotency_key', v_idem, 'mock_case', c,
                 'approved_payload_ref', 'zz-approved-v1', 'approved_payload', v_pay));
          v_pass := case c
            when 'success'           then coalesce((v->>'delivered')::boolean,false)
                                          and (v->>'provider_result_id') is not null
                                          and (v->>'reconciliation_state') = 'MATCHED'
            when 'suppression'       then coalesce((v->>'delivered')::boolean,true) = false
                                          and (v->>'reconciliation_state') = 'SUPPRESSED'
            when 'null_result'       then coalesce((v->>'delivered')::boolean,true) = false
                                          and (v->>'reconciliation_state') = 'NOT_DELIVERED'
            when 'retryable_failure' then (v->>'retry_class') = 'RETRYABLE'
                                          and coalesce((v->>'delivered')::boolean,true) = false
            when 'terminal_failure'  then (v->>'retry_class') = 'TERMINAL'
                                          and coalesce((v->>'dead_lettered')::boolean,false)
            else false end;
          v_detail := format('outcome=%s retry=%s delivered=%s recon=%s',
                             v->>'provider_outcome', v->>'retry_class', v->>'delivered',
                             v->>'reconciliation_state');
        end if;
      exception when others then
        v_pass := false; v_detail := 'raised: ' || left(SQLERRM, 90);
      end;
      step_id := st.sid; mock_case := c; passed := v_pass; detail := v_detail;
      return next;
    end loop;
  end loop;
end

fn_phase_d_run_injected_defects:
declare
  v_ok boolean; v_msg text; v_n int; v_a jsonb; v_b jsonb; v_key text; v_pay jsonb;
  v_sup text; v_id bigint;
begin
  if public.fn_phase_d_fixture_context() is null then
    -- F01. THIS READ A GUC ANY CALLER COULD SET. app.phase_d_test_context = 'on' was a string the
    -- caller supplied about itself; the context is now an hmac over txid_current(), keyed by a
    -- secret no role can SELECT, minted only against an approved audited operation. Leaving the old
    -- door open here would have left the whole control reachable through the value F01 removed.
    raise exception 'no verified Phase D fixture context in this transaction (pd_fixture_no_test_context)'
      using errcode = '23514',
            hint = 'select public.fn_phase_d_test_context_open(''{"operation_key":"pdop_deliverable_build","label":"..."}''); and abort the transaction when finished.';
  end if;

  -- ============ helper shape: each probe INJECTS, then reports what the machine did ============

  -- ---- IDEMPOTENCY ----------------------------------------------------------------------------
  -- PD-IDEM-001 duplicate registration: one identity, two canonical writes, no second row.
  v_key := 'zz-idem-001-' || md5('reg');
  v_a := public.fn_phase_d_object_write(jsonb_build_object(
    'object_id','customer_account','business_key', md5(v_key)::uuid::text,'owner_ref', md5(v_key)::uuid::text,
    'created_by','defect_probe','state','active','payload', jsonb_build_object('full_name','ZZ DEMO — idem001')));
  begin
    v_b := public.fn_phase_d_object_write(jsonb_build_object(
      'object_id','customer_account','business_key', md5(v_key)::uuid::text,'owner_ref', md5(v_key)::uuid::text,
      'created_by','defect_probe','state','active','payload', jsonb_build_object('full_name','ZZ DEMO — idem001')));
    v_ok := (v_a->>'result_reference') = (v_b->>'result_reference');
    v_msg := format('both writes resolved to %s', v_b->>'result_reference');
  exception when others then
    v_ok := true; v_msg := 'second write refused: ' || left(SQLERRM,70);
  end;
  defect_id:='PD-IDEM-001'; category:='IDEMPOTENCY';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  -- PD-IDEM-003 duplicate supplier assignment: the unique index is the machine's answer.
  select count(*) into v_n from pg_index i join pg_class ic on ic.oid=i.indexrelid
   where i.indrelid='public.inquiry_matches'::regclass and i.indisunique
     and ic.relname='inquiry_matches_inquiry_id_supplier_id_key';
  defect_id:='PD-IDEM-003'; category:='IDEMPOTENCY';
  status := case when v_n=1 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := format('UNIQUE (inquiry_id, supplier_id) present=%s; GATE-015 refuses a duplicate dispatch before it', v_n);
  blocker := null; return next;

  -- PD-IDEM-004 duplicate notification request -> one effect. The effect ledger's unique key.
  select count(*) into v_n from pg_constraint
   where conrelid='public.phase_d_effect_ledger'::regclass and contype='u';
  defect_id:='PD-IDEM-004'; category:='IDEMPOTENCY';
  status := case when v_n>0 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := format('phase_d_effect_ledger carries %s unique constraint(s) on (step_run_id, effect_type)', v_n);
  blocker := null; return next;

  -- PD-IDEM-005 duplicate payment webhook -> one monetary transition.
  v_key := 'zz-idem-005-' || md5('pay');
  begin
    perform public.fn_phase_d_external_deliver(jsonb_build_object(
      'step_id','W16-S02','idempotency_key',v_key,'mock_case','success',
      'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
    v_b := public.fn_phase_d_external_deliver(jsonb_build_object(
      'step_id','W16-S02','idempotency_key',v_key,'mock_case','success',
      'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
    select count(*) into v_n from public.phase_d_external_attempt where idempotency_key=v_key and delivered;
    v_ok := coalesce((v_b->>'replay')::boolean,false) and v_n=1;
    v_msg := format('replay=%s deliveries=%s', v_b->>'replay', v_n);
  exception when others then v_ok:=false; v_msg:='raised: '||left(SQLERRM,70); end;
  defect_id:='PD-IDEM-005'; category:='IDEMPOTENCY';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  -- PD-IDEM-002 duplicate workflow step completion -> the frozen kernel decides.
  defect_id:='PD-IDEM-002'; category:='IDEMPOTENCY'; status:='NOT_RUN';
  observed := null;
  blocker := 'needs a live step run to complete twice; the driver aborts its transaction so a second '
          || 'fn_kernel_step_complete on the SAME committed step run cannot be staged here. Executing it '
          || 'requires the section 8 API path that completes a step from outside a single transaction.';
  return next;

  -- ---- CONCURRENCY ----------------------------------------------------------------------------
  -- PD-CONC-002 two suppliers submit the same revision number -> revision uniqueness.
  select count(*) into v_n from public.phase_d_business_object_binding
   where object_id='quotation_revision' and policy_family='IMMUTABLE_REVISION';
  defect_id:='PD-CONC-002'; category:='CONCURRENCY';
  status := case when v_n=1 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := 'quotation_revision is IMMUTABLE_REVISION: a second write supersedes as a new revision and never overwrites';
  blocker := null; return next;

  -- PD-CONC-003 two admins publish the same quotation set -> idempotent result.
  v_key := 'zz-conc-003-' || md5('pub');
  begin
    perform public.fn_phase_d_external_deliver(jsonb_build_object(
      'step_id','W15-S04','idempotency_key',v_key,'mock_case','success',
      'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
    v_b := public.fn_phase_d_external_deliver(jsonb_build_object(
      'step_id','W15-S04','idempotency_key',v_key,'mock_case','success',
      'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
    v_ok := coalesce((v_b->>'replay')::boolean,false);
    v_msg := format('second publish returned the first result id %s and delivered nothing new', v_b->>'provider_result_id');
  exception when others then v_ok:=false; v_msg:='raised: '||left(SQLERRM,70); end;
  defect_id:='PD-CONC-003'; category:='CONCURRENCY';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  -- PD-CONC-004 cancellation races with delivery -> a cancelled subject cannot deliver.
  v_key := 'zz-conc-004-' || md5('cancel');
  begin
    perform public.fn_phase_d_external_deliver(jsonb_build_object(
      'step_id','W13-S01','idempotency_key',v_key,'mock_case','cancellation',
      'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
    begin
      perform public.fn_phase_d_external_deliver(jsonb_build_object(
        'step_id','W13-S01','idempotency_key',v_key,'mock_case','success',
        'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
      v_ok := false; v_msg := 'a cancelled subject was delivered';
    exception when others then
      v_ok := position('pd_external_cancelled' in SQLERRM)>0;
      v_msg := 'delivery after cancellation refused: pd_external_cancelled';
    end;
  exception when others then v_ok:=false; v_msg:='raised: '||left(SQLERRM,70); end;
  defect_id:='PD-CONC-004'; category:='CONCURRENCY';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  -- PD-CONC-005 refund decision races with execution -> one immutable decision.
  defect_id:='PD-CONC-005'; category:='CONCURRENCY';
  select count(*) into v_n from pg_trigger t join pg_proc p on p.oid=t.tgfoid
   where t.tgrelid='public.refunds'::regclass and p.proname='fn_refund_founder_decision_only';
  status := case when v_n=1 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := 'z00_refund_founder_decision_only is a row trigger on public.refunds: every approval path, '
           || 'racing or not, must present an active founder identity or the row is refused';
  blocker := null; return next;

  -- PD-CONC-001 two workers claim the same task -> needs two sessions.
  defect_id:='PD-CONC-001'; category:='CONCURRENCY'; status:='NOT_RUN'; observed:=null;
  blocker := 'a true race needs TWO concurrent database sessions. Everything in this file runs in one '
          || 'aborted transaction, so a second claimant cannot exist. Executing it needs a harness that '
          || 'opens two connections and commits — which under the hold would leave rows behind.';
  return next;

  -- ---- FINANCE --------------------------------------------------------------------------------
  -- PD-FIN-003 refund without founder decision -> refused.
  begin
    insert into public.refunds (transaction_id, customer_id, amount_fils, reason_code, status, decided_by, decided_at)
    values (null, null, 100, 'other', 'approved', 'trust_and_safety_manager', now());
    v_ok := false; v_msg := 'an approved refund by a non-founder was ACCEPTED';
  exception when sqlstate '42501' then
    v_ok := true; v_msg := 'refused 42501: approved by a role that is not an active founder identity';
  when others then
    v_ok := false; v_msg := 'refused for another reason before the guard: ' || left(SQLERRM,60);
  end;
  defect_id:='PD-FIN-003'; category:='FINANCE';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  -- PD-FIN-005 unknown monetary state silently accepted -> visible exception.
  begin
    update public.phase_d_fixture_stage set working_state = 'zz_not_a_rung'
     where object_id = 'payment_transaction';
    v_ok := false; v_msg := 'an undeclared payment state was ACCEPTED';
  exception when others then
    v_ok := position('pd_stage_payment_state_undeclared' in SQLERRM)>0;
    v_msg := 'refused: the state is not a rung of public.phase_d_payment_state';
  end;
  defect_id:='PD-FIN-005'; category:='FINANCE';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  -- PD-FIN-002 reveal before confirmed reconciliation -> refused.
  select count(*) into v_n from public.phase_d_payment_state where authorizes_reveal;
  defect_id:='PD-FIN-002'; category:='FINANCE';
  status := case when v_n=2 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := format('%s of 6 payment rungs authorise a reveal (payment_reconciled, reveal_authorized); '
                     'BR-020 names rung 5 as the founder-approved bar and no rung below it authorises', v_n);
  blocker := null; return next;

  -- PD-FIN-001 executor also reconciles -> separation of duties.
  defect_id:='PD-FIN-001'; category:='FINANCE'; status:='NOT_RUN'; observed:=null;
  blocker := 'phase_c_refund_decision carries executor_role_id and reconciler_role_id, but no Phase D '
          || 'path writes that table — GATE-020 reads public.refunds instead. Injecting one identity into '
          || 'both columns needs the refund execution path of section 9 wired to phase_c_refund_decision, '
          || 'which is not built.';
  return next;

  -- PD-FIN-004 founder decision updated or deleted -> append-only refusal.
  defect_id:='PD-FIN-004'; category:='FINANCE'; status:='NOT_RUN'; observed:=null;
  blocker := 'needs a committed founder decision row to attempt to rewrite. A fixture may never forge '
          || 'one (his standing rule), and no test-context founder identity exists, so the append-only '
          || 'refusal cannot be provoked without a real decision.';
  return next;

  -- ---- REVIEW ---------------------------------------------------------------------------------
  -- PD-REV-001 creator alias equals reviewer alias -> self-review refusal.
  v_ok := not public.fn_kernel_reviewer_independent('trust_and_safety_manager','trust_and_safety_manager');
  defect_id:='PD-REV-001'; category:='REVIEW';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := 'fn_kernel_reviewer_independent(x, x) is false: one identity cannot review its own output';
  blocker := null; return next;

  -- PD-REV-003 reviewer outside authority -> refused.
  v_ok := not public.fn_kernel_reviewer_independent('trust_and_safety_manager', null);
  defect_id:='PD-REV-003'; category:='REVIEW';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := 'a null reviewer is not independent; BR-002 refuses the step rather than proceeding unreviewed';
  blocker := null; return next;

  -- PD-REV-002/004/005 need a committed task and a sealed verdict.
  defect_id:='PD-REV-002'; category:='REVIEW'; status:='NOT_RUN'; observed:=null;
  blocker := 'the driver records a verdict and completes the step inside one aborted transaction; leaving a '
          || 'step in waiting_review to observe it requires a committed run, which the hold forbids.';
  return next;
  defect_id:='PD-REV-004'; category:='REVIEW'; status:='NOT_RUN'; observed:=null;
  blocker := 'requires driving a REJECTED verdict through a committed run to observe that no successor task '
          || 'is created; the handoff rejection path is proved separately in D9k but not as this injection.';
  return next;
  defect_id:='PD-REV-005'; category:='REVIEW'; status:='NOT_RUN'; observed:=null;
  blocker := 'needs a sealed verdict row to attempt to edit; sealing happens on commit and this file aborts.';
  return next;

  -- ---- OUTBOX (the D29 adapter is the machine under test) --------------------------------------
  -- PD-OUTBOX-001 consumer returns null -> delivery failure, attempt recorded.
  v_key := 'zz-out-001-' || md5('null');
  v_b := public.fn_phase_d_external_deliver(jsonb_build_object(
    'step_id','W13-S02','idempotency_key',v_key,'mock_case','null_result',
    'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
  select count(*) into v_n from public.phase_d_external_attempt where idempotency_key=v_key;
  defect_id:='PD-OUTBOX-001'; category:='OUTBOX';
  status := case when coalesce((v_b->>'delivered')::boolean,true)=false and v_n=1
                 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := format('null result: delivered=%s, reconciliation=%s, attempts recorded=%s',
                     v_b->>'delivered', v_b->>'reconciliation_state', v_n);
  blocker := null; return next;

  -- PD-OUTBOX-002 retryable failure then success -> first failure preserved.
  v_key := 'zz-out-002-' || md5('retry');
  perform public.fn_phase_d_external_deliver(jsonb_build_object(
    'step_id','W13-S03','idempotency_key',v_key,'mock_case','retryable_failure',
    'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
  v_b := public.fn_phase_d_external_deliver(jsonb_build_object(
    'step_id','W13-S03','idempotency_key',v_key,'mock_case','success',
    'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
  select count(*) into v_n from public.phase_d_external_attempt
   where idempotency_key=v_key and provider_outcome='retryable_failure';
  defect_id:='PD-OUTBOX-002'; category:='OUTBOX';
  status := case when coalesce((v_b->>'delivered')::boolean,false) and v_n=1
                 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := format('attempt 1 retryable preserved (%s row), attempt 2 delivered=%s', v_n, v_b->>'delivered');
  blocker := null; return next;

  -- PD-OUTBOX-003 terminal failure -> dead_letter, no business success.
  v_key := 'zz-out-003-' || md5('term');
  v_b := public.fn_phase_d_external_deliver(jsonb_build_object(
    'step_id','W13-S04','idempotency_key',v_key,'mock_case','terminal_failure',
    'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
  defect_id:='PD-OUTBOX-003'; category:='OUTBOX';
  status := case when coalesce((v_b->>'dead_lettered')::boolean,false)
                  and coalesce((v_b->>'delivered')::boolean,true)=false
                 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := format('terminal: retry_class=%s dead_lettered=%s delivered=%s',
                     v_b->>'retry_class', v_b->>'dead_lettered', v_b->>'delivered');
  blocker := null; return next;

  -- PD-OUTBOX-005 cancelled subject pending delivery -> non-deliverable.
  v_key := 'zz-out-005-' || md5('cx');
  perform public.fn_phase_d_external_deliver(jsonb_build_object(
    'step_id','W13-S05','idempotency_key',v_key,'mock_case','cancellation',
    'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
  begin
    perform public.fn_phase_d_external_deliver(jsonb_build_object(
      'step_id','W13-S05','idempotency_key',v_key,'mock_case','success',
      'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
    v_ok := false; v_msg := 'a cancelled subject was delivered';
  exception when others then
    v_ok := position('pd_external_cancelled' in SQLERRM)>0; v_msg := 'refused: pd_external_cancelled';
  end;
  defect_id:='PD-OUTBOX-005'; category:='OUTBOX';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  -- PD-OUTBOX-004 consumer re-emits the same event -> self-loop.
  defect_id:='PD-OUTBOX-004'; category:='OUTBOX'; status:='NOT_RUN'; observed:=null;
  blocker := 'the 54 event self-loops are a FROZEN Phase B property (emitted_by = primary_consumer_role_id) '
          || 'recorded RED and ratcheted by D11. Injecting a re-emission needs a live consumer, and no '
          || 'consumer is running under the automation hold.';
  return next;

  -- ---- NOTIFY ---------------------------------------------------------------------------------
  -- PD-NOTIFY-001 external send attempted in Phase D -> provider-disabled refusal.
  begin
    perform public.fn_phase_d_external_deliver(jsonb_build_object(
      'step_id','W13-S06','idempotency_key','zz-notify-001','mock_case','success','provider_mode','live',
      'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
    v_ok := false; v_msg := 'a LIVE provider mode was accepted';
  exception when others then
    v_ok := position('pd_external_live_mode_refused' in SQLERRM)>0;
    v_msg := 'refused: pd_external_live_mode_refused — this adapter has no live mode';
  end;
  defect_id:='PD-NOTIFY-001'; category:='NOTIFY';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  -- PD-NOTIFY-002 opted-out recipient queued -> suppressed.
  v_key := 'zz-notify-002-' || md5('supp');
  v_b := public.fn_phase_d_external_deliver(jsonb_build_object(
    'step_id','W13-S07','idempotency_key',v_key,'mock_case','suppression',
    'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
  defect_id:='PD-NOTIFY-002'; category:='NOTIFY';
  status := case when (v_b->>'reconciliation_state')='SUPPRESSED'
                  and coalesce((v_b->>'delivered')::boolean,true)=false
                 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := format('suppressed: delivered=%s reconciliation=%s', v_b->>'delivered', v_b->>'reconciliation_state');
  blocker := null; return next;

  -- PD-NOTIFY-003 duplicate message from retry -> one send ledger row.
  v_key := 'zz-notify-003-' || md5('dup');
  perform public.fn_phase_d_external_deliver(jsonb_build_object(
    'step_id','W13-S01','idempotency_key',v_key,'mock_case','success',
    'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
  perform public.fn_phase_d_external_deliver(jsonb_build_object(
    'step_id','W13-S01','idempotency_key',v_key,'mock_case','success',
    'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
  select count(*) into v_n from public.phase_d_external_attempt where idempotency_key=v_key and delivered;
  defect_id:='PD-NOTIFY-003'; category:='NOTIFY';
  status := case when v_n=1 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := format('two identical sends produced %s delivered row(s)', v_n);
  blocker := null; return next;

  -- PD-NOTIFY-004 success claimed on a null provider result -> failure.
  v_key := 'zz-notify-004-' || md5('nullclaim');
  v_b := public.fn_phase_d_external_deliver(jsonb_build_object(
    'step_id','W13-S02','idempotency_key',v_key,'mock_case','null_result',
    'approved_payload_ref','zz-approved-v1','approved_payload', jsonb_build_object('x',1)));
  defect_id:='PD-NOTIFY-004'; category:='NOTIFY';
  status := case when coalesce((v_b->>'ok')::boolean,true)=false
                  and coalesce((v_b->>'delivered')::boolean,true)=false
                 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := 'a null provider result returns ok=false and delivered=false — it is never a success';
  blocker := null; return next;

  -- PD-NOTIFY-005 supplier receives raw customer identity -> approval/send refused.
  defect_id:='PD-NOTIFY-005'; category:='NOTIFY'; status:='NOT_RUN'; observed:=null;
  blocker := 'needs a rendered supplier-facing message body to scan for customer identity. Section 9 '
          || 'records an approved payload and its sha256 but does not render a body, and the PII detector '
          || 'runs in the edge functions that section 8 would exercise.';
  return next;

  -- ---- PROVIDER -------------------------------------------------------------------------------
  -- PD-PROV-005 provider reports success with no request ID -> failure.
  begin
    insert into public.phase_d_external_attempt
      (step_id, idempotency_key, attempt_no, provider_mode, approved_payload_ref, approved_payload_sha256,
       provider_request_id, provider_result_id, provider_outcome, retry_class, delivered)
    values ('W13-S01','zz-prov-005',1,'mock','zz','zz','req_zz', null, 'success','NOT_APPLICABLE', true);
    v_ok := false; v_msg := 'a DELIVERED attempt with no result id was accepted';
  exception when others then
    v_ok := true; v_msg := 'refused by phase_d_external_attempt_delivered_has_result: delivered requires a result id';
  end;
  defect_id:='PD-PROV-005'; category:='PROVIDER';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  -- PD-PROV-001 OpenRouter request in zero-cost mode -> network denied.
  select count(*) into v_n from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname='public' and p.proname in ('fn_phase_d_external_deliver','fn_phase_d_run_external_cases',
                                              'fn_phase_d_object_write','fn_phase_d_drive_workflow')
     -- READING the queue is the D17 GUARD; POSTING to it is a request. The first draft matched
     -- net.http_ and counted fn_phase_d_object_write, which references net.http_request_queue
     -- precisely in order to REFUSE one. The control refused the file rather than scoring it.
     -- MATCH A CALL, NOT A MENTION. Two drafts of this probe were wrong and both are worth keeping
     -- in the record. The first matched net.http_ and counted fn_phase_d_object_write, which names
     -- net.http_request_queue in order to REFUSE a request. The second narrowed to net.http_post and
     -- STILL counted it, because the D17 refusal's own hint text reads "A trigger on this relation
     -- calls net.http_post" — a keyword scanner matching a sentence ABOUT the thing it forbids.
     -- Quoted literals are stripped before judging, exactly as qd_guard does for the same reason:
     -- check the skeleton, not the payload.
     and regexp_replace(p.prosrc, '''(''''|[^''])*''', '''''', 'g') ~* 'openrouter|net[.]http_(post|get)[[:space:]]*[(]';
  defect_id:='PD-PROV-001'; category:='PROVIDER';
  status := case when v_n=0 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := format('%s Phase D routine(s) make an openrouter or net.http_post/get call; the D17 guard additionally '
                     'refuses any Phase D write that leaves a request in net.http_request_queue', v_n);
  blocker := null; return next;

  -- PD-PROV-004 direct provider client bypass -> repo/network scan.
  defect_id:='PD-PROV-004'; category:='PROVIDER'; status:='NOT_RUN'; observed:=null;
  blocker := 'a repository scan for a direct provider client lives in the CI credential test over '
          || 'supabase/functions, not in the database. Executing it as an INJECTION means adding a bypass '
          || 'to an edge function and observing CI refuse it, which needs the section 8 deploy path.';
  return next;

  -- PD-PROV-002/003 gate read failure and malformed route state.
  begin
    perform public.fn_phase_d_gate_evaluate('GATE-010', jsonb_build_object('route_state',''));
    select count(*) into v_n from public.fn_phase_d_gate_evaluate('GATE-010', jsonb_build_object('route_state','')) where ok;
    v_ok := (v_n = 0);
    v_msg := 'an empty route_state does not pass GATE-010; the gate denies rather than falling back';
  exception when others then v_ok := true; v_msg := 'gate raised on malformed evidence: ' || left(SQLERRM,60); end;
  defect_id:='PD-PROV-003'; category:='PROVIDER';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  defect_id:='PD-PROV-002'; category:='PROVIDER'; status:='NOT_RUN'; observed:=null;
  blocker := 'requires making a gate READ fail (not evaluate false) — a permission or relation error mid-gate. '
          || 'Provoking it means revoking a grant on production, which the hold forbids outside an aborted '
          || 'transaction that the gate would not observe.';
  return next;

  -- ---- STATE ----------------------------------------------------------------------------------
  -- PD-STATE-001 step completed from an invalid state.
  begin
    perform public.fn_phase_d_effect_produce(jsonb_build_object(
      'step_run_id', -1, 'idempotency_key','zz-state-001','actor_role_id','defect_probe',
      'payload', jsonb_build_object('x',1)));
    v_ok := false; v_msg := 'a nonexistent step run was accepted';
  exception when others then
    v_ok := position('pd_step_state_invalid' in SQLERRM)>0;
    v_msg := 'refused: pd_step_state_invalid — no such step run';
  end;
  defect_id:='PD-STATE-001'; category:='STATE';
  status := case when v_ok then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := v_msg; blocker := null; return next;

  -- PD-STATE-005 failure outcome interpreted as a step id -> no invented step.
  select count(*) into v_n from public.fn_phase_d_step_cases('NOT-A-STEP') where passed;
  defect_id:='PD-STATE-005'; category:='STATE';
  status := case when v_n=0 then 'REFUSED_AS_REQUIRED' else 'NOT_REFUSED' end;
  observed := 'fn_phase_d_step_cases on an unknown step returns passed=false with step_unknown; no step is invented';
  blocker := null; return next;

  -- PD-STATE-002/003/004 need a committed run to observe closure and successor behaviour.
  defect_id:='PD-STATE-002'; category:='STATE'; status:='NOT_RUN'; observed:=null;
  blocker := 'closing a workflow with a mandatory blocker open needs a committed run whose closed_at can be '
          || 'read afterwards; every Phase D drive aborts.';
  return next;
  defect_id:='PD-STATE-003'; category:='STATE'; status:='NOT_RUN'; observed:=null;
  blocker := 'requires a committed run to show the successor was not skipped.';
  return next;
  defect_id:='PD-STATE-004'; category:='STATE'; status:='NOT_RUN'; observed:=null;
  blocker := 'a missing successor owner is a FROZEN Phase B property; injecting one means editing '
           || 'phase_b_workflow_step, which z90_phase_b_freeze refuses without a change request.';
  return next;

  -- ---- TRACE ----------------------------------------------------------------------------------
  defect_id:='PD-TRACE-001'; category:='TRACE'; status:='NOT_RUN'; observed:=null;
  blocker := 'inserting an active step run without a trace means writing phase_c_workflow_step_run directly; '
          || 'fn_phase_d_object_write refuses kernel-owned tables (pd_object_kernel_owned), so the injection '
          || 'cannot be staged through a Phase D path and doing it raw would test the kernel, not Phase D.';
  return next;
  defect_id:='PD-TRACE-002'; category:='TRACE'; status:='NOT_RUN'; observed:=null;
  blocker := 'as PD-TRACE-001: the subject is a frozen kernel table.';
  return next;
  defect_id:='PD-TRACE-003'; category:='TRACE'; status:='NOT_RUN'; observed:=null;
  blocker := 'as PD-TRACE-001: sealing is a kernel operation and sealed_at is a kernel column.';
  return next;
  defect_id:='PD-TRACE-004'; category:='TRACE'; status:='NOT_RUN'; observed:=null;
  blocker := 'observing an ORPHAN trace after a failed insert needs the failed insert to commit its trace, '
          || 'which cannot happen inside one aborted transaction.';
  return next;
  defect_id:='PD-TRACE-005'; category:='TRACE'; status:='NOT_RUN'; observed:=null;
  blocker := 'the read-only trace exemption is decided in the kernel; Phase D has no path that requests it.';
  return next;

  -- ---- The categories that need section 8 -------------------------------------------------------
  -- Each names the specific missing capability. None is mapped onto a nearby guard.
  for v_key, v_msg in
    select * from (values
      ('PD-AUTH-001','AUTH: needs an unauthenticated HTTP request against a deployed customer endpoint and the response status. No Phase D path issues an HTTP request.'),
      ('PD-AUTH-002','AUTH: needs supplier A''s bearer token against supplier B''s document URL. Requires the section 8 API + storage path.'),
      ('PD-AUTH-003','AUTH: needs a non-admin identity attempting an admin mutation over HTTP; the RLS/route decision is made in the edge function, not in SQL.'),
      ('PD-AUTH-004','AUTH: needs an inactive canonical role to attempt a step through the API; in SQL the driver supplies the role directly and never authenticates it.'),
      ('PD-AUTH-005','AUTH: needs a category overlay presented as a task owner through the API path; the SQL path resolves the actor before any authority check.'),
      ('PD-FILE-001','FILES: needs a real upload whose magic bytes disagree with its extension. The attachment classifier lives in supabase/functions/_shared/attachment.ts and is exercised by its own deno test, not by any SQL path.'),
      ('PD-FILE-002','FILES: needs an oversized upload against the storage endpoint and a 413.'),
      ('PD-FILE-003','FILES: needs executable content posted as a document and the quarantine result.'),
      ('PD-FILE-004','FILES: needs an EXPIRED signed URL to be reused and the 403 observed; signed URLs are minted by storage, not by the database.'),
      ('PD-FILE-005','FILES: needs an insert into storage.objects under a path the caller does not own, judged by a storage RLS policy.'),
      ('PD-PRIV-003','PRIVACY: needs a signed URL whose path belongs to another supplier; storage authorization is the subject.'),
      ('PD-PRIV-004','PRIVACY: needs a supplier bearer token calling the raw inquiry endpoint and the response body.'),
      ('PD-PRIV-005','PRIVACY: needs a rendered artifact to scan for hidden metadata; no Phase D path renders one.'),
      ('PD-PRIV-001','PRIVACY: needs the supplier-safe approval path to receive a payload containing a customer email and refuse it. The safe package is recorded as an object but its CONTENTS are not rendered or scanned in Phase D.'),
      ('PD-PRIV-002','PRIVACY: needs a drawing revision with an unapproved redaction; file revision state is a storage + document-pipeline fact.'),
      ('PD-DISP-005','DISPATCH: needs a category overlay to attempt a dispatch through an authenticated path.'),
      ('PD-QUOTE-001','QUOTE: needs supplier A''s token editing supplier B''s quote over the API.'),
      ('PD-QUOTE-004','QUOTE: needs a customer read of an unpublished quote through the portal read path.'),
      ('PD-LEGAL-001','LEGAL: needs the certificate rendering path, which is outside Phase D.'),
      ('PD-LEGAL-004','LEGAL: needs the tax/legal static file freshness check, which is a content-pipeline fact.')
    ) as t(a,b)
  loop
    defect_id := v_key; category := split_part(v_msg, ':', 1); status := 'NOT_RUN';
    observed := null; blocker := 'SECTION 8 NOT BUILT — ' || v_msg;
    return next;
  end loop;

  -- ---- Remaining rows whose subject exists but whose injection needs a committed run ------------
  for v_key, v_msg in
    select * from (values
      ('PD-DISP-001','DISPATCH: GATE-011 refuses a not-quote-ready inquiry and is proved by the W05 drive, but injecting it as a DEFECT needs a dispatch attempted against a deliberately unready inquiry in a committed run.'),
      ('PD-DISP-002','DISPATCH: needs a supplier in pending/rejected/expired presented to the assignment path; the fixture writes approved suppliers only and BR-015 refuses the rest before dispatch.'),
      ('PD-DISP-003','DISPATCH: GATE-013 tests who approved the safe package; injecting an UNAPPROVED one needs the approval column to be writable to a non-approver, which the write map does not permit.'),
      ('PD-DISP-004','DISPATCH: needs assignment and outbox counts reconciled across a committed run.'),
      ('PD-QUOTE-002','QUOTE: GATE-017 refuses a quote with no amount and is exercised by the W14 drive; as an INJECTION it needs a publish attempted on the incomplete quote.'),
      ('PD-QUOTE-003','QUOTE: needs a technical claim with no evidence presented to the evaluation path; quotation_evaluation is bound but no Phase D step writes an evidence-bearing claim.'),
      ('PD-QUOTE-005','QUOTE: needs normalization to attempt an overwrite of an original supplier value; the normalization path is not built.'),
      ('PD-LEGAL-002','LEGAL: customer_terms_acceptance is APPEND_ONLY and the writer refuses a second version by name, but injecting a REWRITE needs a committed acceptance row.'),
      ('PD-LEGAL-003','LEGAL: needs a non-refund subject submitted to the founder approval path; that path is phase_c_refund_decision and no Phase D route writes it.'),
      ('PD-LEGAL-005','LEGAL: the independence refusal is proved for reviewers (PD-REV-001); injecting it for a COMPLIANCE review needs the compliance review path, which is not a Phase D step.')
    ) as t(a,b)
  loop
    defect_id := v_key; category := split_part(v_msg, ':', 1); status := 'NOT_RUN';
    observed := null; blocker := v_msg;
    return next;
  end loop;
end

fn_phase_d_step_context:
declare
  sr public.phase_c_workflow_step_run%rowtype;
  v_val_txt text;  -- G02: the acceptance value read back before it becomes jsonb
  v_key_obj text;  -- G08: the object a context key names, from phase_d_context_key_object
  v_link    text;  -- G08: the column on this run's relation that reaches that object
  v_link_v  text;  -- G08: what that column holds
  v_scn_ref jsonb; -- G08: the canonical reference the scenario recorded for that object
  r  public.phase_c_workflow_run%rowtype;
  s  public.phase_b_workflow_step%rowtype;
  b  public.phase_d_handler_binding%rowtype;
  ec public.phase_d_step_effect%rowtype;
  v_keys   text[];
  v_k      text;
  v_val    jsonb;
  v_src    text;
  v_ctx    jsonb := '{}'::jsonb;
  v_prov   jsonb := '{}'::jsonb;
  v_unres  text[] := '{}';
  v_obj    text;
  v_boid   text;
  v_run_key text;
  v_rel    text;
  v_keycol text;
  v_owncol text;
  v_row_id text;
  v_row_own text;
  v_found  boolean := false;
  v_key_prefixed boolean := false;   -- E25
  v_sql    text;
  v_from   text;
  v_to     text;
  v_route  text;
  v_cmd    bigint;
  v_auth   jsonb;   -- K01
  v_src_ref   text;
  v_src_kind  text;
  v_src_class text;
  v_src_actor text;
  v_src_act   text;
  v_email     text;
  v_fx_val    jsonb;   -- F11
  v_fx_src    text;    -- F11
begin
  select * into sr from public.phase_c_workflow_step_run where step_run_id = p_step_run_id;
  if not found then
    raise exception 'fn_phase_d_step_context: no step run %', p_step_run_id using errcode = '23503';
  end if;
  select * into r  from public.phase_c_workflow_run    where run_id  = sr.run_id;
  select * into s  from public.phase_b_workflow_step   where step_id = sr.step_id;
  select * into b  from public.phase_d_handler_binding where step_id = sr.step_id;
  select * into ec from public.phase_d_step_effect     where step_id = sr.step_id;

  select coalesce(array_agg(distinct k), '{}') into v_keys from (
    select unnest(re.required_context) k from public.phase_d_rule_enforcement re
     where re.rule_id = any (coalesce(b.rule_ids,'{}'))
    union
    select unnest(gc.evidence_keys) k from public.phase_d_gate_contract gc
     where gc.gate_id = any (coalesce(b.gate_ids,'{}'))
    -- K03. THE PARENT OF THE RECORD THIS STEP WRITES. The list was the union of what the step's
    -- rules and gates ask for, and nothing else, so a key no rule happens to name was never
    -- resolved even where the estate could answer it. W16-S01 wrote a reveal payment that belonged
    -- to no quote for exactly that reason. The object's own frozen binding names its parent and the
    -- write map names the payload key that carries it; both are read here. A step that writes no
    -- business object adds nothing, and a key a rule already asks for is unchanged -- this is a
    -- distinct union.
    union
    select wm.column_map->>bb.parent_identity k
      from public.phase_d_business_object_binding bb
      join public.phase_d_object_write_map wm on wm.object_id = bb.object_id
     where bb.object_id = ec.effect_object_id
       and coalesce(btrim(bb.parent_identity),'') <> ''
       and wm.column_map ? bb.parent_identity
       and wm.column_map->>bb.parent_identity not in ('business_key','owner_ref','state')
    ) q(k);

  -- ---- the frozen state model ------------------------------------------------------------------
  v_from  := r.state;
  -- E12. THE RESOLVER NULLED A FACT THE GATE EXISTS TO JUDGE.
  --
  -- to_state is the step's own frozen declaration: phase_b_workflow_step.success_workflow_state.
  -- Until now this line also re-ran GATE-006's test on it, and blanked the value when the test
  -- failed. That is a different act from resolving, and it had two consequences.
  --
  -- First, it made the answer depend on WHEN the resolver was called rather than on what the
  -- registry says. fn_phase_d_dispatch_step runs inside fn_kernel_open_step, and a step opened out
  -- of a handoff is dispatched while its run is still in waiting_handoff -- the state it is
  -- leaving. The old guard therefore asked whether the run could go waiting_handoff ->
  -- waiting_handoff, which the frozen model rightly says it cannot, and nulled the key. Called a
  -- moment later, against the same step run, the same function resolved it. Measured 2026-08-20:
  -- W01-S04/S05/S06 record to_state in phase_d_dispatch.unresolved_keys, and a direct call for the
  -- same step runs resolves it to waiting_handoff.
  --
  -- Second, and worse, it turned a judgeable fact into an absent one. GATE-006 already tests the
  -- transition against public.phase_b_workflow_transition, and already holds the reasoned branch
  -- for the case where a step declares the state it is already in (55 of 257 steps do). With the
  -- key blanked, the gate could not reach either branch and reported "requires [to_state] and the
  -- call names none of it" -- an evidence-absence message standing in for a judgement the
  -- instrument was built to make.
  --
  -- The resolution is therefore the declaration, and the judgement stays with the gate. This is a
  -- REMOVAL: nothing new is asserted, and a transition the frozen model does not declare is still
  -- refused -- by GATE-006, which is the check that owns it.
  v_to    := nullif(btrim(coalesce(s.success_workflow_state,'')),'');
  -- D42. route_state IS NOT "the first declared transition, alphabetically". That is what this
  -- resolver did, and GATE-010 duly reported "route state approved; only a confirmed route carries
  -- dispatch authority" for an inquiry that had never been routed. Picking a plausible value out of
  -- the declared set is the placeholder defect wearing a schema. A route state exists when a route
  -- has been confirmed; until then the key is unresolved and GATE-010 refuses, which is the gate
  -- doing its job.
  v_route := null;

  -- ---- the arrival that caused this run, and how the register classifies it ---------------------
  select ti.source_system, 'trigger' into v_src_ref, v_src_kind
    from public.kernel_trigger_inbox ti where ti.run_id = sr.run_id order by ti.inbox_id desc limit 1;
  if v_src_ref is null and coalesce(btrim(coalesce(r.business_object_id,'')),'') <> '' then
    -- D39(2). The first step of a run dispatches INSIDE fn_kernel_workflow_start, before the inbox
    -- row is stamped with run_id. business_object_id is on both sides already, derived from the same
    -- object rule, so it is what links them at the only moment that matters.
    select ti.source_system, 'trigger' into v_src_ref, v_src_kind
      from public.kernel_trigger_inbox ti
     where ti.business_object_id = r.business_object_id
     order by ti.inbox_id desc limit 1;
  end if;
  if v_src_ref is null then
    select si.source_type, 'signal' into v_src_ref, v_src_kind
      from public.kernel_signal_inbox si
     where si.workflow_run_id = sr.run_id order by si.signal_id desc limit 1;
  end if;
  if v_src_ref is null then
    select tk.source_ref, tk.source_kind into v_src_ref, v_src_kind
      from public.phase_c_task tk where tk.run_id = sr.run_id order by tk.task_id limit 1;
  end if;
  -- D40. THE INBOX ROW IS NOT READABLE BY run_id OR business_object_id AT FIRST-STEP DISPATCH TIME.
  -- fn_kernel_trigger_submit inserts the inbox row, then calls fn_kernel_workflow_start passing
  -- source_ref = 'trigger_inbox:<inbox_id>', and stamps run_id and business_object_id onto that row
  -- only AFTER the call returns. The dispatch happens inside it, so both earlier matches were looking
  -- for columns the row does not carry yet. The inbox id IS in the source_ref the kernel already
  -- passes, and fn_kernel_workflow_start writes it onto the task before it opens the step — the one
  -- identifier available at the only moment that matters.
  if v_src_ref like 'trigger_inbox:%' then
    select ti.source_system, 'trigger' into v_src_ref, v_src_kind
      from public.kernel_trigger_inbox ti
     where ti.inbox_id = nullif(substr(v_src_ref, 15), '')::bigint;
  end if;
  if coalesce(btrim(coalesce(v_src_ref,'')),'') <> '' then
    select c.source_class, c.system_actor, c.current_activation
      into v_src_class, v_src_actor, v_src_act
      from public.phase_c_source_cutover c
     where c.source_component_id = v_src_ref limit 1;
  end if;

  -- ---- the run's own business object -----------------------------------------------------------
  v_obj := coalesce(nullif(btrim(coalesce(ec.effect_object_id,'')),''),
                    (select bo.object_id from public.phase_d_business_object_binding bo
                      where bo.governing_workflow_id = r.workflow_id limit 1));
  v_boid := nullif(btrim(coalesce(r.business_object_id,'')),'');
  -- THE RUN'S OWN PARTY, KEPT SEPARATELY. v_boid below is consumed by the STEP's object: where the
  -- step writes something other than what the run is about, the prefix does not match, the lookup
  -- fails and v_found is false. That is correct for the step's own subject and wrong for anything
  -- that belongs to the run as a whole. Measured 23 Aug 2026 on W09-S03: the run's
  -- business_object_id is 'supplier_account:37085' and the step's business object is
  -- supplier_capability on public.supplier_capabilities with row_found false, so the terms branch
  -- below had no anchor and fell through to the catalogue.
  v_run_key := case when v_boid like '%:%' then substr(v_boid, position(':' in v_boid) + 1) else null end;
  -- D39(1). The kernel writes the object rule out in full: 'inquiry:<uuid>'. Strip ONLY that
  -- object's own prefix; a blind split on ':' would corrupt an identifier that contains one.
  -- E25. WHETHER THE PREFIX MATCHED IS ITSELF A FACT, and the caller needs it. A run whose
  -- business_object_id is 'inquiry:<uuid>' names the object this step writes; one that reads
  -- 'outbox:195' or a probe label does not, and using the raw string as a business key would invent
  -- an identity for a record. Only a stripped key is a key.
  v_key_prefixed := (v_obj is not null and v_boid is not null and v_boid like (v_obj || ':%'));
  if v_key_prefixed then
    v_boid := substr(v_boid, length(v_obj) + 2);
  end if;
  if v_obj is not null and coalesce(v_boid,'') <> '' then
    select wm.target_relation, wm.key_column, wm.owner_column
      into v_rel, v_keycol, v_owncol
      from public.phase_d_object_write_map wm where wm.object_id = v_obj limit 1;
    if v_rel is not null and coalesce(btrim(v_keycol),'') <> ''
       and to_regclass(v_rel) is not null then
      begin
        v_sql := format('select %I::text, %s from %s where %I::text = $1 limit 1',
                        v_keycol,
                        case when coalesce(btrim(v_owncol),'') = '' then 'null::text'
                             else quote_ident(v_owncol) || '::text' end,
                        to_regclass(v_rel)::text, v_keycol);
        execute v_sql into v_row_id, v_row_own using v_boid;
        v_found := v_row_id is not null;
      exception when others then
        v_found := false;
      end;
    end if;
  end if;

  foreach v_k in array v_keys loop
    v_val := null; v_src := null;

    if v_k = 'from_state' then
      v_val := to_jsonb(v_from); v_src := 'phase_c_workflow_run.state';
    elsif v_k = 'to_state' then
      if v_to is not null then
        v_val := to_jsonb(v_to);
        v_src := 'phase_b_workflow_step.success_workflow_state, confirmed against phase_b_workflow_transition';
      end if;
    elsif v_k = 'route_state' then
      -- Resolved only from a route that actually exists. See the note above v_route.
      if v_route is not null then
        v_val := to_jsonb(v_route); v_src := 'the confirmed route for this inquiry';
      end if;

    elsif v_k in ('inquiry_id','supplier_id','quote_id','transaction_id','document_id',
                  'comparison_id','refund_id') then
      -- G08. THIS ANSWERED ALL SEVEN WITH THE RUN'S OWN ROW ID. See the file header: BR-015 was told
      -- a quote was a supplier, BR-020 that a comparison was a transaction, BR-013 that a document
      -- was an inquiry. Each key names an object, that object is recorded, and the answer must come
      -- from the object it names or not at all.
      select cko.object_id into v_key_obj
        from public.phase_d_context_key_object cko where cko.context_key = v_k;

      if v_found and v_key_obj is not null and v_key_obj = v_obj then
        -- The key names the object this run is about. The row id is the answer.
        v_val := to_jsonb(v_row_id);
        v_src := format('%s.%s, looked up by the run''s business_object_id', v_rel, v_keycol);

      elsif v_found and v_key_obj is not null then
        -- The key names a DIFFERENT object. Reach it from this run's own row, through a declared
        -- foreign key to that object's canonical relation where one exists, and otherwise through a
        -- column named exactly like the key. Both are read from the catalog; neither is listed here.
        select a.attname into v_link
          from pg_constraint con
          join lateral unnest(con.conkey) k(attnum) on true
          join pg_attribute a on a.attrelid = con.conrelid and a.attnum = k.attnum
         where con.contype = 'f'
           and con.conrelid = to_regclass(v_rel)
           and con.confrelid = (select to_regclass(bb.canonical_relation)
                                  from public.phase_d_business_object_binding bb
                                 where bb.object_id = v_key_obj)
         order by a.attname limit 1;
        if v_link is null then
          select a.attname into v_link from pg_attribute a
           where a.attrelid = to_regclass(v_rel) and a.attnum > 0 and not a.attisdropped
             and a.attname = v_k;
        end if;
        if v_link is not null then
          begin
            execute format('select %I::text from %s where %I::text = $1',
                           v_link, to_regclass(v_rel)::text, v_keycol)
              into v_link_v using v_row_id;
          exception when others then v_link_v := null; end;
          if coalesce(btrim(v_link_v),'') <> '' then
            v_val := to_jsonb(v_link_v);
            v_src := format('%s.%s of the run''s own row, which reaches %s', v_rel, v_link, v_key_obj);
          end if;
          v_link := null; v_link_v := null;
        end if;
      end if;
    elsif v_k = 'caller_customer_id' then
      -- G18. THE OWNER IS THE ANSWER ONLY WHEN THE OWNER IS A CUSTOMER.
      -- On a W14 run the business object is a quotation and its owner column is
      -- public.quotes.supplier_id, so this branch handed BR-019 a supplier and BR-019 refused,
      -- correctly, about the wrong party. Whether the owner column reaches the customer relation is
      -- read from the catalog, not assumed from the column's name.
      if v_found and v_row_own is not null and v_owncol is not null
         and exists (select 1
                       from pg_constraint con
                       join lateral unnest(con.conkey) k(attnum) on true
                       join pg_attribute a on a.attrelid = con.conrelid and a.attnum = k.attnum
                      where con.contype = 'f'
                        and con.conrelid = to_regclass(v_rel)
                        and a.attname = v_owncol
                        and con.confrelid = (select to_regclass(bb.canonical_relation)
                                               from public.phase_d_business_object_binding bb
                                              where bb.object_id = 'customer_account')) then
        v_val := to_jsonb(v_row_own);
        v_src := format('%s.%s of the run''s own object, which is a declared foreign key into the customer relation', v_rel, v_owncol);
      end if;

    elsif v_k = 'inquiry_owner' then
      -- D41. inquiry_owner IS A ROLE, NOT A CUSTOMER. BR-049 is the only consumer of this key —
      -- no gate declares it — and its predicate compares it to the literal role
      -- 'rfq_qualification_manager'. Resolving it from inquiries.customer_id handed a rule about
      -- ACCOUNTABILITY a customer UUID, so it refused every inquiry the moment the owner started
      -- resolving at all. The frozen rule text is unambiguous: "Specialist and document handoffs do
      -- not transfer overall inquiry accountability away from RFQ Qualification Manager unless an
      -- explicit approved workflow says so."
      --
      -- The subject is therefore the role accountable for the INQUIRY, which is
      -- phase_c_workflow_run.accountable_role_id of the run that owns it. For a W05 run that is this
      -- run; for W06 and W07, which are the specialist workflows the rule is about, it is the W05
      -- run for the same inquiry, and where no such run exists the key stays unresolved rather than
      -- being answered with this run''s own role.
      --
      -- This is what makes the rule able to FAIL: it fails exactly when a run''s accountable role
      -- has drifted from the frozen registry''s, which is the drift BR-049 exists to catch.
      if r.workflow_id = 'W05' then
        v_val := to_jsonb(r.accountable_role_id);
        v_src := 'phase_c_workflow_run.accountable_role_id of this inquiry''s own run';
      elsif v_found then
        select to_jsonb(r2.accountable_role_id) into v_val
          from public.phase_c_workflow_run r2
         where r2.workflow_id = 'W05'
           and r2.business_object_id = ('inquiry:' || v_row_id)
         order by r2.run_id desc limit 1;
        v_src := 'phase_c_workflow_run.accountable_role_id of the W05 run that owns this inquiry';
        -- G09. AN INQUIRY NO RUN HAS CLAIMED HAS NOT DRIFTED FROM ANYTHING.
        -- Measured: W06-S01 and W07-S01 refused with "inquiry owner is (unstated)" because the
        -- inquiry exists and no W05 run does. The branch above still comes first, so an inquiry a
        -- run HAS claimed is answered by that run's actual role and BR-049 still refuses when it
        -- has drifted. Only the unclaimed case changes, and there the frozen registry's own
        -- accountable role for the workflow that owns the inquiry object is the answer -- read from
        -- public.phase_b_workflow, never named here.
      end if;
      -- G14. THE FALLBACK WAS INSIDE THE BRANCH THAT NEEDS THE RUN'S OWN ROW, AND W06 HAS NONE.
      -- W06's primary object is inquiry_route_set, whose fixture stage contributes a STATE rather
      -- than a key, so the run's business object never resolves and the branch above never ran.
      -- W06-S01 kept refusing with "inquiry owner is (unstated)" after G09 had supposedly answered
      -- it. The fallback belongs wherever nothing else has answered, which is here.
      if v_val is null then
        select to_jsonb(w2.accountable_role_id) into v_val
          from public.phase_b_workflow w2
         where w2.primary_object = 'inquiry' order by w2.workflow_id limit 1;
        v_src := 'phase_b_workflow.accountable_role_id of the workflow whose primary object is '
              || 'the inquiry -- no workflow run has claimed this inquiry, so accountability is '
              || 'where the frozen registry puts it and has not moved';
      end if;
    elsif v_k = 'monetary_state' then
      if v_found and v_rel like '%transactions' then
        select to_jsonb(t.fee_status) into v_val from public.transactions t
          where t.id::text = v_row_id limit 1;
        v_src := 'public.transactions.fee_status of the run''s own transaction';
      end if;

    elsif v_k = 'evidence_authority' then
      -- F13. THIS RESOLVED, AND RESOLVED TO SOMETHING THE RULE CANNOT RANK.
      --
      -- BR-029 is about RANK: lower-authority evidence may not silently overwrite higher, and the
      -- estate's ranking is public.mep_evidence_weight (alias, customer_text, document_extraction,
      -- scope_rule, structured_answer). This branch answered with the arrival CLASSIFICATION --
      -- "A NEW_WORK_REQUEST (system.task_engine) via dbtrigger:public.inquiries:trg_inquiry_received_a,
      -- activation ACTIVE" -- which is a true fact about how the run started and is not an evidence
      -- authority at all. Measured on every drive: 0 rows matched, so BR-029 refused for the whole
      -- estate, and it refused with a reason that read as though the authority were unranked rather
      -- than as though the resolver had answered a different question.
      --
      -- The correction is a REMOVAL plus a test: the classification is offered only if it actually
      -- appears in the ranking. When it does not, the key is UNRESOLVED, which is the honest state
      -- -- and which is what lets the Phase D fixture door supply a ranked authority, and what
      -- keeps BR-029 refusing in production where no such authority is named.
      if v_src_class is not null
         and exists (select 1 from public.mep_evidence_weight w
                      where w.weight_key = v_src_class or w.evidence_source = v_src_class
                         or w.source_authority = v_src_class) then
        v_val := to_jsonb(v_src_class);
        v_src := 'phase_c_source_cutover classification of the arrival that caused this run, confirmed present in the public.mep_evidence_weight ranking';
      elsif exists (select 1 from public.phase_d_object_record o
                     where o.object_id = 'document_extraction'
                       and o.payload->>'document_id' = coalesce(v_row_id,'')) then
        -- The run's own object carries a document extraction, and document_extraction IS a ranked
        -- evidence source. This is a read of what the run rests on, not a choice.
        v_val := to_jsonb('document_extraction'::text);
        v_src := 'public.mep_evidence_weight: the run''s own object carries a document extraction, which is a ranked evidence source';
      end if;

    elsif v_k = 'notify_email' then
      if v_found and v_row_own is not null then
        v_email := null;
        if v_owncol = 'customer_id' then
          select c.email into v_email from public.customers c where c.id::text = v_row_own limit 1;
        elsif v_owncol in ('supplier_id','lead_id') then
          select l.email into v_email from public.leads l where l.id::text = v_row_own limit 1;
        end if;
        if coalesce(btrim(coalesce(v_email,'')),'') <> '' then
          v_val := to_jsonb(v_email);
          v_src := format('the email of %s.%s, the owner of the run''s own object', v_rel, v_owncol);
        end if;
      end if;

    elsif v_k = 'evidence_refs' then
      -- E22. A CONDITION THE FIRST STEP OF A RUN COULD NEVER MEET.
      --
      -- This resolved evidence_refs from public.phase_d_effect_ledger for the run and nothing else.
      -- The FIRST step of a run has no predecessor, so it has no prior effect, so the key was
      -- unresolvable for it by construction — not sometimes, ever. BR-027 is bound to 59 steps and
      -- applies to 7 of the estate's first steps; six of those seven (the seventh is held by the
      -- capability boundary) were refused by a rule they had no way to satisfy. Measured 2026-08-20.
      --
      -- The fix is not to hand the key a placeholder. It is to notice that a first step DOES have
      -- evidence, and that the resolver was reading the wrong subject for it: what a first step
      -- rests on is THE ARRIVAL THAT OPENED THE RUN. That is a row — phase_c_workflow_run carries
      -- start_event, command_id and opened_at, and phase_c_source_cutover classifies the source
      -- component — so naming it is a read, not an invention.
      --
      -- THE ARRIVAL COUNTS ONLY FOR A STEP WITH NO PREDECESSOR, and that restriction is what keeps
      -- BR-027 able to fail. A later step must still show what the run has PRODUCED; if its
      -- predecessors produced nothing, it still gets nothing and BR-027 still refuses. Handing every
      -- call an automatic arrival reference would have turned a rule that refuses into a rule that
      -- cannot, which is the defect this file is fixing, in the other direction.
      select case when count(*) = 0 then null
                  else jsonb_agg(jsonb_build_object(
                         'effect_id', el.effect_id, 'step_id', el.step_id,
                         'effect_type', el.effect_type,
                         'result_reference', el.result_reference) order by el.effect_id) end
        into v_val
        from public.phase_d_effect_ledger el where el.run_id = sr.run_id;
      v_src := 'phase_d_effect_ledger for this run';

      if v_val is null
         and not exists (select 1 from public.phase_c_workflow_step_run pr
                          where pr.run_id = sr.run_id and pr.step_run_id < sr.step_run_id) then
        v_val := jsonb_build_array(jsonb_build_object(
          'kind',          'arrival',
          'run_id',        sr.run_id,
          'workflow_id',   r.workflow_id,
          'start_event',   nullif(btrim(coalesce(r.start_event,'')),''),
          'command_id',    r.command_id,
          'source_ref',    nullif(btrim(coalesce(v_src_ref,'')),''),
          'source_class',  v_src_class,
          'system_actor',  v_src_actor,
          'opened_at',     r.opened_at));
        v_src := 'the arrival that opened this run (phase_c_workflow_run.start_event/command_id '
              || 'plus its phase_c_source_cutover classification) — this step has no predecessor, '
              || 'so the arrival is the evidence it rests on';
      end if;

    elsif v_k = 'handoff_id' then
      -- D50. The handoff this step opens is a row of the frozen registry, not something a caller has
      -- to remember to pass. BR-008 was refusing for want of an identifier sitting in a table.
      select to_jsonb(hc.handoff_id) into v_val
        from public.phase_d_handoff_contract hc where hc.from_step_id = sr.step_id
       order by hc.handoff_id limit 1;
      v_src := 'phase_d_handoff_contract.handoff_id for the handoff this step opens';

    elsif v_k = 'sla_policy_id' then
      -- Likewise: the SLA policy of that handoff is recorded against it in the frozen registry.
      select to_jsonb(nullif(btrim(coalesce(h.sla_policy_id,'')),'')) into v_val
        from public.phase_b_handoff h where h.from_step_id = sr.step_id
       order by h.handoff_id limit 1;
      v_src := 'phase_b_handoff.sla_policy_id of the handoff this step opens';

    elsif v_k in ('packet','requested_action','source_version') then
      select case v_k
               when 'packet' then case when hc.packet_keys is null or cardinality(hc.packet_keys) = 0
                                       then null else to_jsonb(hc.packet_keys) end
               when 'requested_action' then to_jsonb(nullif(btrim(coalesce(hc.acceptance_criteria,'')),''))
               else to_jsonb(nullif(btrim(coalesce(hc.source_object_version_key,'')),'')) end
        into v_val
        from public.phase_d_handoff_contract hc where hc.from_step_id = sr.step_id limit 1;
      v_src := 'phase_d_handoff_contract for this step';

    elsif v_k = 'founder_authority_ref' then
      -- K01. GATE-005's frozen evidence is "Decision is within delegated authority OR founder
      -- approval exists", and this resolved only the second half, so a step whose run no founder
      -- instructed could never answer it. One resolver now answers both, from the founder's own
      -- frozen boundary register where no command instructed the run, and it reports the reference
      -- only when that reference is valid -- exists, current, and covering this workflow.
      v_auth := public.fn_phase_d_founder_authority(sr.run_id, sr.step_id);
      if coalesce((v_auth->>'valid')::boolean, false) then
        v_val := to_jsonb(v_auth->>'ref');
        v_src := v_auth->>'source';
      end if;

    elsif v_k = 'run_id' then
      -- E11. This function loads sr and r in its first ten lines and then declared run_id
      -- unresolved, which refused GATE-008 on every step in the estate for want of a number the
      -- same function was already holding.
      v_val := to_jsonb(sr.run_id);
      v_src := 'phase_c_workflow_step_run.run_id of this step run';

    elsif v_k = 'actor_role_id' then
      -- The role ACCOUNTABLE for this step run, read from the kernel's own row. Not the caller's
      -- claim about who they are: this function is given a step_run_id and nothing else, and a
      -- context resolver that took an identity from its caller would be answering the question it
      -- was asked to check.
      v_val := to_jsonb(nullif(btrim(coalesce(sr.accountable_role_id,'')),''));
      v_src := 'phase_c_workflow_step_run.accountable_role_id';

    elsif v_k = 'reviewer_role_id' then
      -- The INDEPENDENT reviewer the frozen binding declares, and only that. 45 of the 47 review
      -- steps name none, and for those this stays unresolved so GATE-004 and GATE-021 refuse —
      -- which is the gate working. Choosing a reviewer here would be fn_pick_reviewer returning the
      -- department head 182 times, one layer up.
      -- G02. THE REVIEWER WHO ACTUALLY REVIEWED, BEFORE THE ONE THE REGISTRY DECLARES.
      --
      -- This read only phase_d_handler_binding.independent_reviewer_role_id, which 229 of the 257
      -- steps leave blank, so every gate asking who reviewed something was answered "nobody" even
      -- after fn_kernel_review_decide had sealed a verdict and STAMPED THE REVIEWER on the task.
      -- fn_phase_d_recorded_review already reads that stamp and nothing consulted it here.
      --
      -- Order matters and this order is deliberate: the reviewer who actually reviewed outranks the
      -- reviewer a registry column names, because the gate's question is about the review that
      -- happened. Where no review has been recorded the declared reviewer still answers, and where
      -- neither exists the key stays unresolved and the gate refuses -- which is the gate working,
      -- and is what the previous comment here was protecting. Nothing chooses a reviewer: this
      -- resolver reports one or reports none, exactly as fn_pick_reviewer should have.
      v_val := to_jsonb(nullif(btrim(coalesce(
                 (public.fn_phase_d_recorded_review(p_step_run_id))->>'reviewer_role_id','')),''));
      if v_val is not null then
        v_src := 'phase_c_task.reviewer_role_id, stamped by fn_kernel_review_decide on the review '
              || 'actually recorded for this step run';
      else
        v_val := to_jsonb(nullif(btrim(coalesce(b.independent_reviewer_role_id,'')),''));
        v_src := 'phase_d_handler_binding.independent_reviewer_role_id, declared not chosen';
      end if;
      -- H03. A STEP THAT IS NOT A REVIEW IS ASKED ABOUT THE REVIEW THE RUN RECORDED. GATE-021 and
      -- GATE-026 apply from the first review step to the last step; at a publish step the reviewer
      -- is whoever reviewed earlier in this run. Read from the same task stamp, on an earlier step
      -- run of the same run, only where this step reviews nothing itself.
      if (v_val is null or v_val = 'null'::jsonb)
         and b.handler_class is distinct from 'REVIEW_HANDLER'
         and coalesce(btrim((select s3.independent_reviewer_role_id
                              from public.phase_b_workflow_step s3 where s3.step_id = sr.step_id)),'') = '' then
        select to_jsonb(nullif(btrim(coalesce(t2.reviewer_role_id,'')),'')) into v_val
          from public.phase_c_task t2
          join public.phase_c_workflow_step_run sr2
            on sr2.run_id = t2.run_id and sr2.step_id = t2.step_id
         where t2.run_id = sr.run_id
           and sr2.step_run_id < p_step_run_id
           and coalesce(btrim(t2.reviewer_role_id),'') <> ''
         order by sr2.step_run_id desc, t2.task_id desc
         limit 1;
        if v_val is not null then
          v_src := 'phase_c_task.reviewer_role_id of the most recent review fn_kernel_review_decide '
                || 'recorded on an earlier step run of this same run -- this step reviews nothing '
                || 'itself, and the gate asks about the review that happened';
        end if;
      end if;

    elsif v_k = 'step_id' then
      -- MENTIONED IN THIS FUNCTION AND NOT BRANCHED, which is why the first measurement of this
      -- defect missed it. sr.step_id appears in the return object at the bottom, so a grep for
      -- 'step_id' finds it and a reader concludes the key resolves. It did not. A mention is not a
      -- branch — the same lens that cost the 19 Aug audit its central premise, applied here to the
      -- very file that was measuring it.
      v_val := to_jsonb(sr.step_id);
      v_src := 'phase_c_workflow_step_run.step_id';

    elsif v_k = 'step_run_id' then
      v_val := to_jsonb(p_step_run_id);
      v_src := 'the step_run_id this function was called with';

    elsif v_k in ('terms_version','terms_hash') then
      -- G02. A KEY THAT NAMES A RECORD WAS ANSWERED FROM A CONSTANT, AND THE CONSTANT WON.
      --
      -- BR-025 asks whether an acceptance references the exact displayed version AND hash, and it
      -- resolves the pair against public.legal_documents. Measured on W04 and W09: it refused with
      --
      --   "acceptance names version phase-d-fixture-terms-v1 at digest 5d31c13d1f0f, which matches
      --    0 row(s) in public.legal_documents whose displayed body hashes to exactly that digest"
      --
      -- Those two values are the COMMITTED CATALOGUE FIXTURES PDF-3104 and PDF-3105. Nothing was
      -- wrong with them; they are a real pair over a real fixture body. What was wrong is that they
      -- were the answer at all. The scenario factory reads the version and digest of the ACTUALLY
      -- PUBLISHED documents -- public.legal_documents customer-terms v3 and supplier-agreement v5 --
      -- and writes them onto the acceptance record it creates. Both keys then fell through every
      -- branch of this resolver to the fixture door, which answered from the catalogue, and the
      -- catalogue value shadowed the record the scenario had just written. That is D9g's "a
      -- generated fixture beat the real reference", one layer up, and F47's "a key that names an
      -- object is answered from that object's reference" stated for a third time.
      --
      -- THE ACCEPTANCE RECORD IS FOUND BY WHAT IT CARRIES, NOT BY WHAT IT IS CALLED. The record
      -- sought is the live object record owned by this run's own business object that carries both
      -- terms keys -- no object name, no naming convention, no workflow list. A run whose object
      -- row was not found, or that owns no acceptance, resolves nothing here and falls through to
      -- the catalogue exactly as before, where BR-025 still matches 0 rows and still refuses. The
      -- rule keeps its ability to fail, and it now also has a way to pass for a true reason.
      -- J05. AND THE ACCEPTANCE BELONGS TO THE RUN'S PARTY, NOT TO THE STEP'S SUBJECT. The block
      -- above anchored on v_row_id, which is the row the STEP is about. Measured on W09-S03, S05
      -- and S06: the run is about supplier_account 37085 and the step is about a
      -- supplier_capability that does not exist yet, so v_found was false, this branch never ran,
      -- and BR-025 was answered from catalogue fixtures PDF-3104/PDF-3105 --
      -- "acceptance names version phase-d-fixture-terms-v1 at digest 5d31c13d1f0f, which matches 0
      -- row(s) in public.legal_documents". The acceptance the scenario actually wrote names
      -- supplier-agreement v5, owned by 37085, and it was one join away the whole time.
      --
      -- A terms acceptance is a fact about the PARTY the run concerns; no step in a workflow makes
      -- it a fact about that step's own subject. So the step's subject is tried first, and the
      -- run's own party second. A run whose party owns no acceptance still resolves nothing and
      -- BR-025 still matches 0 rows and still refuses: the rule keeps its ability to fail.
      if coalesce(v_row_id, v_run_key) is not null then
        select o.payload ->> v_k into v_val_txt
          from public.phase_d_object_record o
         where o.superseded_by is null
           and o.payload ? 'terms_version' and o.payload ? 'terms_hash'
           and o.owner_ref in (v_row_id, v_run_key)
         order by (o.owner_ref = v_row_id) desc, o.record_id desc limit 1;
        if coalesce(btrim(v_val_txt),'') <> '' then
          v_val := to_jsonb(v_val_txt);
          v_src := 'the terms-acceptance record this run''s own business object owns, in '
                || 'public.phase_d_object_record -- the pair the acceptance actually names';
        end if;
        v_val_txt := null;
      end if;

    elsif v_k = 'source_ref' then
      -- The arrival that caused this run, already computed into v_src_ref from kernel_trigger_inbox
      -- at the top of this function. Unresolved when no arrival is recorded, which is a fact about
      -- the run rather than a gap in this resolver.
      v_val := to_jsonb(nullif(btrim(coalesce(v_src_ref,'')),''));
      v_src := 'kernel_trigger_inbox.source_system for this run';

    else
      -- 40 of the 71 declared context keys still land here, and that is correct: artifact_sha256,
      -- terms_hash, legal_review_ref, denominator, formula, outcome_metric and the rest are facts a
      -- CALLER produces at runtime, not facts this estate holds. They stay unresolved and their
      -- rules and gates refuse, which is the contract working.
      -- exception_authority_ref is here on purpose too: BR-043 applies only when the call names a
      -- policy exception, and inventing an authority reference would be the placeholder defect the
      -- D42 comment above already refused once for route_state.
      v_val := null; v_src := null;
    end if;


    -- G08. THE SCENARIO-REFERENCE DOOR, in front of the catalogue and behind every real source.
    --
    -- public.quote_comparisons carries no transaction column and public.documents relates to its
    -- inquiry through a polymorphic (ref_table, ref_id) pair, so no derivation from the schema can
    -- reach W15's transaction_id or W07's inquiry_id from the run's own row. The scenario created
    -- both objects and recorded the canonical reference of each. This answers from THAT -- a row the
    -- scenario actually wrote through fn_phase_d_object_write -- rather than from the committed
    -- constant the fixture door below would otherwise supply.
    --
    -- It returns nothing unless fn_phase_d_fixture_context() verifies an hmac over the current txid
    -- keyed by a secret no role can SELECT. In production this block resolves nothing at all.
    -- K07. THE OBJECT THIS RUN ALREADY CREATED, before any fixture is consulted.
    --
    -- A key that names an object was answered from the run's own row, from a declared foreign key
    -- on it, or -- fixture context only -- from the canonical reference the SCENARIO recorded.
    -- Nothing answered "the object THIS RUN produced at an earlier step", so W17-S07 asked for the
    -- refund_id of a refund_dispute_case that W17-S01 had created six steps earlier and was told
    -- there was none. public.phase_d_effect_ledger holds it: run_id, effect_object_id and the
    -- canonical result_reference fn_phase_d_object_write returned. This is not a fixture and it runs
    -- in production; it is asked after every source that reads the run's own row, and before the
    -- scenario record, because a fact this run produced outranks one a scenario planted.
    if (v_val is null or v_val = 'null'::jsonb
        or (jsonb_typeof(v_val) = 'string' and btrim(coalesce(v_val #>> '{}','')) = '')) then
      select cko.object_id into v_key_obj
        from public.phase_d_context_key_object cko where cko.context_key = v_k;
      if v_key_obj is not null then
        select nullif(btrim(substring(el.result_reference from position('=' in el.result_reference) + 1)),'')
          into v_link_v
          from public.phase_d_effect_ledger el
          join public.phase_d_business_object_binding bb on bb.object_id = el.effect_object_id
         where el.run_id = sr.run_id
           and el.effect_object_id = v_key_obj
           -- AN EFFECT NAMED FOR AN OBJECT IS NOT ALWAYS A REFERENCE TO ONE. phase_d_effect_ledger
           -- records effect_object_id from the step's DECLARED object, so a REVIEW_VERDICT step of
           -- W15 carries effect_object_id quotation_comparison and result_reference
           -- public.review_chain:id=15748 -- the identity of the review, not of the comparison.
           -- Taking it made GATE-018 judge a review row as a comparison and refuse W15-S05 for
           -- 'comparison 15748 does NOT belong to the calling customer', which was true and was
           -- about the wrong row. Only a reference into the object's OWN canonical relation is an
           -- identity of that object.
           and el.effect_relation = bb.canonical_relation
           and coalesce(btrim(el.result_reference),'') <> ''
           and position('=' in el.result_reference) > 0
         order by el.effect_id desc limit 1;
        if v_link_v is not null then
          v_ctx  := v_ctx  || jsonb_build_object(v_k, to_jsonb(v_link_v));
          v_prov := v_prov || jsonb_build_object(v_k,
            format('the canonical reference of the %s this run itself created, read from '
                || 'public.phase_d_effect_ledger.result_reference', v_key_obj));
          v_link_v := null; v_key_obj := null;
          continue;
        end if;
      end if;
      v_key_obj := null;
    end if;

    if (v_val is null or v_val = 'null'::jsonb
        or (jsonb_typeof(v_val) = 'string' and btrim(coalesce(v_val #>> '{}','')) = ''))
       and public.fn_phase_d_fixture_context() is not null then
      select cko.object_id into v_key_obj
        from public.phase_d_context_key_object cko where cko.context_key = v_k;
      if v_key_obj is not null then
        select sc.canonical_ref into v_scn_ref
          from public.phase_d_scenario_record sc
         where sc.fixture_run_id = public.fn_phase_d_fixture_context()
           and sc.object_id = v_key_obj
         order by sc.scenario_record_id desc limit 1;
        if v_scn_ref is not null
           and coalesce(btrim(v_scn_ref->>'canonical_identity'),'') <> '' then
          v_ctx  := v_ctx  || jsonb_build_object(v_k, to_jsonb(v_scn_ref->>'canonical_identity'));
          v_prov := v_prov || jsonb_build_object(v_k,
            format('the canonical reference the scenario recorded for %s in '
                || 'public.phase_d_scenario_record -- a row this scenario created through '
                || 'fn_phase_d_object_write, not a committed constant', v_key_obj));
          v_scn_ref := null; v_key_obj := null;
          continue;
        end if;
        v_scn_ref := null;
      end if;
      v_key_obj := null;
    end if;

    -- F11. THE FIXTURE DOOR, AND ONLY AFTER EVERY REAL SOURCE HAS BEEN TRIED.
    --
    -- The founder's section B: "A deterministic handler must not invent business content. The
    -- scenario catalogue supplies explicit test values... The handler receives the fixture as
    -- input. The handler must not generate the fixture itself."
    --
    -- This is where the fixture becomes an input. It runs in the RESOLVER, which is called by
    -- fn_phase_d_dispatch_step before fn_phase_d_handler_execute is entered, so the handler is
    -- handed a value and never reaches for one. And it runs LAST: a key a real row can answer is
    -- answered by that row, and the fixture never shadows a fact.
    --
    -- fn_phase_d_fixture_input returns NO ROW unless fn_phase_d_fixture_context() verifies an hmac
    -- over the current txid keyed by a secret no role can read. In production there is no such
    -- context, so this block resolves nothing, the key stays unresolved, and its rule or gate
    -- refuses exactly as it did before this file existed.
    if v_val is null or v_val = 'null'::jsonb
       or (jsonb_typeof(v_val) = 'string' and btrim(coalesce(v_val #>> '{}','')) = '') then
      select fi.value, fi.provenance || format(' [fixture %s v%s %s]', fi.fixture_id,
                                               fi.fixture_version, left(fi.checksum, 12))
        into v_fx_val, v_fx_src
        from public.fn_phase_d_fixture_input(p_step_run_id, 'CONTEXT_KEY', v_k) fi;
      if v_fx_val is not null then
        v_ctx := v_ctx || jsonb_build_object(v_k, v_fx_val);
        v_prov := v_prov || jsonb_build_object(v_k, v_fx_src);
        v_fx_val := null; v_fx_src := null;
        continue;
      end if;
    end if;
    if v_val is null or v_val = 'null'::jsonb
       or (jsonb_typeof(v_val) = 'string' and btrim(coalesce(v_val #>> '{}','')) = '') then
      v_unres := v_unres || v_k;
    else
      v_ctx  := v_ctx  || jsonb_build_object(v_k, v_val);
      v_prov := v_prov || jsonb_build_object(v_k, v_src);
    end if;
  end loop;

  return jsonb_build_object(
    'step_run_id', p_step_run_id, 'step_id', sr.step_id,
    'declared_keys', to_jsonb(v_keys),
    'context', v_ctx, 'provenance', v_prov, 'unresolved', to_jsonb(v_unres),
    'arrival', jsonb_build_object('source_ref', v_src_ref, 'source_kind', v_src_kind,
                                  'source_class', v_src_class, 'activation', v_src_act),
    'business_object', jsonb_build_object(
      'object_id', v_obj, 'object_key', v_boid, 'relation', v_rel, 'key_column', v_keycol,
      'owner_column', v_owncol, 'row_found', v_found,
      -- E25. The two facts fn_phase_d_effect_produce demands of its caller, reported here because
      -- this is the routine that already resolved them and the dispatch had no way to know them.
      'key_is_prefixed', v_key_prefixed,
      'row_owner_ref', v_row_own,
      'ownership_scope', (select ob.ownership_scope
                            from public.phase_d_business_object_binding ob
                           where ob.object_id = v_obj)));
end

fn_phase_d_rule_can_refuse:
declare
  v_full jsonb; v_held jsonb; v_overlay text;
  r record; e public.phase_d_rule_enforcement%rowtype; s1 text; s2 text; s3 text;
begin
  select ob.overlay_id into v_overlay from public.phase_c_overlay_binding ob order by 1 limit 1;

  -- (2) everything named, including the authority that permits it
  v_full := jsonb_build_object(
    'accountable_role_id','rfq_qualification_manager','actor_role_id','rfq_qualification_manager',
    'reviewer_role_id','inquiry_quality_analyst','step_id','W05-S01','workflow_id','W05',
    'run_id', 1, 'founder_gate','NONE','execution_context','production',
    'evidence_refs', jsonb_build_array('e1'), 'assumptions', jsonb_build_array('a real assumption'),
    'formula','numerator/denominator','denominator', 2, 'numerator', 1,
    'inquiry_owner','rfq_qualification_manager','evidence_authority','A NEW_WORK_REQUEST',
    'commercial_policy_change','raise reveal fee','founder_authority_ref','founder_command:1',
    'policy_exception','waive fee','exception_authority_ref','founder_command:1',
    'sla_policy_id', (select sp.sla_policy_id from public.phase_b_sla_policy sp order by 1 limit 1),
    'handoff_id', (select hc.handoff_id from public.phase_d_handoff_contract hc order by 1 limit 1),
    'packet', '{}'::jsonb);

  -- (3) the same subjects with the AUTHORITY WITHHELD, and an actor that resolves to an overlay.
  -- This is the context the first two could not express, and it is where six of the seven refuse.
  v_held := (v_full - 'founder_authority_ref' - 'exception_authority_ref')
            || jsonb_build_object('actor_role_id', coalesce(v_overlay,'rfq_qualification_manager'));

  for r in select br.rule_id from public.phase_b_business_rule br order by br.rule_id loop
    select rc.state into s1 from public.fn_phase_d_rule_check(r.rule_id, '{}'::jsonb) rc limit 1;
    select rc.state into s2 from public.fn_phase_d_rule_check(r.rule_id, v_full)      rc limit 1;
    select rc.state into s3 from public.fn_phase_d_rule_check(r.rule_id, v_held)      rc limit 1;
    select * into e from public.phase_d_rule_enforcement en where en.rule_id = r.rule_id;

    rule_id := r.rule_id;
    states  := format('empty=%s full=%s authority_withheld=%s', s1, s2, s3);
    can_refuse := 'ENFORCED_FAIL' in (s1, s2, s3);
    refusing_context := case
      when s1 = 'ENFORCED_FAIL' then 'empty'
      when s3 = 'ENFORCED_FAIL' then 'authority_withheld'
      when s2 = 'ENFORCED_FAIL' then 'full'
      else '(none)' end;
    -- E20. DERIVED FROM THE ENFORCEMENT ROW, NEVER FROM A RULE ID. The prior body matched
    -- 'BR-028' and 'BR-053'/'BR-054' as literals, so the excuse would have printed unchanged if any
    -- of them had started or stopped refusing. Every branch below reads a column.
    note := case
      when can_refuse then 'a context producing ENFORCED_FAIL exists'
      when s1 = 'DELEGATED_TO_KERNEL_GUARD' then 'delegated: the kernel guard decides, this predicate cannot invoke it'
      when e.rule_id is null then 'this rule has no row in phase_d_rule_enforcement, so nothing here can explain it'
      when e.enforcement_kind = 'EXECUTOR_ENFORCED'
        then format('enforced at %s, which is not this predicate; the predicate is not where this rule refuses',
                    coalesce(e.enforcement_point,'(unstated)'))
      when s1 = s2 and s2 = s3 and coalesce(cardinality(e.required_context),0) = 0
        then format('constant under every context tried, and it must be: this rule declares no required_context, so its verdict comes from %s — estate state, not the call. It will vary when that does.',
                    coalesce(e.enforcement_point,'(unstated)'))
      else 'NO CONTEXT PRODUCED A REFUSAL — this rule cannot fail' end;
    return next;
  end loop;
end

fn_phase_d_rule_check:
declare
  r public.phase_b_business_rule%rowtype;
  e public.phase_d_rule_enforcement%rowtype;
  v_missing text[]; v_n bigint; v_txt text; v_ok boolean; v_reason text;
  -- E30. A second count and a second string. A reference that must RESOLVE is two questions --
  -- is it shaped like the thing it claims to be, and does it name something that exists -- and
  -- more than once the answer lives in two relations.
  v_n2 bigint; v_txt2 text;
begin
  -- E19. FALSE UNLESS A BRANCH SAYS OTHERWISE. An OUT parameter left unset is NULL, and a null
  -- read as "not evidence-absent" by one caller and as "unknown" by another is how one column
  -- ends up meaning two things.
  evidence_absent := false;
  select * into r from public.phase_b_business_rule where rule_id = p_rule_id;
  if not found then
    state := 'NOT_IMPLEMENTED'; ok := false; rule_type := 'unknown'; enforced := false;
    reason := format('unknown business rule %s — fail closed', p_rule_id);
    refusal_code := 'unknown_rule'; return next; return;
  end if;
  rule_type := r.rule_type;

  select * into e from public.phase_d_rule_enforcement where rule_id = p_rule_id;
  if not found then
    state := 'NOT_IMPLEMENTED'; ok := false; enforced := false;
    reason := format('rule %s has no row in phase_d_rule_enforcement — fail closed rather than assume it is satisfied', p_rule_id);
    refusal_code := 'rule_unregistered'; return next; return;
  end if;
  refusal_code := e.refusal_code;
  enforced := (e.status = 'ENFORCED');

  -- ============================ the predicates ============================================
  -- Each reads the relation D2 bound for the object it governs. A rule whose evidence is absent
  -- REFUSES; it never passes for want of data.

  if p_rule_id in ('BR-001','BR-005') then
    v_ok := public.fn_phase_c_actor_may_own(p_context->>'accountable_role_id');
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('%s: owner %s %s', p_rule_id, coalesce(p_context->>'accountable_role_id','(none)'),
                     case when v_ok then 'resolves to one active canonical role'
                          else 'does not resolve to an active canonical role' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-004' then
    v_ok := coalesce((select kind from public.fn_phase_c_resolve_actor(p_context->>'actor_role_id')),'') = 'canonical';
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-004: actor %s %s', coalesce(p_context->>'actor_role_id','(none)'),
                     case when v_ok then 'is canonical' else 'is not canonical; aliases are input compatibility only' end);
    return next; return;
  end if;

  if p_rule_id in ('BR-002','BR-030','BR-031','BR-037','BR-038') then
    v_ok := public.fn_kernel_reviewer_independent(p_context->>'accountable_role_id', p_context->>'reviewer_role_id');
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('%s: %s and %s %s', p_rule_id, coalesce(p_context->>'accountable_role_id','(none)'),
                     coalesce(p_context->>'reviewer_role_id','(none)'),
                     case when v_ok then 'are different effective identities'
                          else 'resolve to the same effective identity' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-048' then
    v_ok := not exists (select 1 from public.phase_c_overlay_binding ob
                         where ob.live_role_id = (select role_id from public.fn_phase_c_resolve_actor(p_context->>'actor_role_id')));
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then 'BR-048: the acting identity is not a category overlay'
                   else format('BR-048: %s is a category overlay and may not dispatch, approve suppliers, reveal identity or change policy',
                               p_context->>'actor_role_id') end;
    return next; return;
  end if;

  if p_rule_id in ('BR-053','BR-054') then
    v_ok := not coalesce((public.fn_kernel_paid_provider_gate('openai/gpt-4o-mini')->>'allowed')::boolean, true);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('%s: the paid-provider gate %s', p_rule_id,
                     case when v_ok then 'refuses a paid route' else 'ALLOWED a paid route' end);
    return next; return;
  end if;

  -- E28. BR-003 CHECKED THAT A KEY WAS PRESENT, NEVER THAT IT MEANT ANYTHING.
  -- It fell through to the generic CONTEXT_REQUIRED branch, whose whole test is "is the key present
  -- and non-empty". Measured 2026-08-20: BR-003 returned ENFORCED_PASS for
  -- founder_authority_ref = 'ZZ DEMO — founder_authority_ref for W16-S01', and for the single word
  -- 'banana'. A rule whose name is "founder-reserved decisions require founder authority" was
  -- satisfied by any non-empty string, which means the harness driving the workflow deliverable was
  -- forging founder authority and being told it had it. The founder's standing rule, written into
  -- this estate's own injected-defect catalogue, is that a fixture may never forge one.
  --
  -- The reference must now RESOLVE. 'founder_command:<id>' has to name a row in
  -- public.founder_command; nothing else is accepted, and the refusal says which of the two
  -- failures it is so a caller can tell "you named nothing" from "you named something that is not
  -- a founder decision". Fixing it here rather than in the harness closes it for every caller.
  if p_rule_id = 'BR-003' then
    v_txt := btrim(coalesce(p_context->>'founder_authority_ref',''));
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-003 requires [founder_authority_ref] and the call names none of it.';
      return next; return;
    end if;
    v_ok := exists (select 1 from public.founder_command fc
                     where 'founder_command:' || fc.command_id::text = v_txt);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok
                   then format('BR-003: %s resolves to a founder command on record', v_txt)
                   else format('BR-003: %s does not resolve to any row in public.founder_command. A founder-reserved decision needs the founder''s actual decision, not a string in its shape.', v_txt) end;
    return next; return;
  end if;

  if p_rule_id = 'BR-043' then
    -- E30. BR-043 REFUSED NOTHING, FOR TWO INDEPENDENT REASONS, AND BOTH HAD TO GO.
    -- (1) Applicability keyed on 'policy_exception', which is NOT in its required_context, so the
    --     rule was NOT_APPLICABLE on every call the estate actually makes -- including calls that
    --     named an exception authority.
    -- (2) The authority test was "is the string non-empty", so 'banana' authorised an exception.
    -- Bound, applicable and ACTUALLY REFUSES are three different questions. A brief and two
    -- audits named this rule as a blocker; it had only ever answered the first.
    v_txt  := btrim(coalesce(p_context->>'policy_exception',''));
    v_txt2 := btrim(coalesce(p_context->>'exception_authority_ref',''));
    if v_txt = '' and v_txt2 = '' then
      state := 'NOT_APPLICABLE'; ok := true;
      reason := 'BR-043: the call proposes no policy exception and names no exception authority, so there is no exception to authorise';
      return next; return;
    end if;
    if v_txt2 = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-043: exception %s is proposed with no exception_authority_ref', v_txt);
      return next; return;
    end if;
    -- Does the exception reach founder-reserved subject matter? public.founder_reserved_decision
    -- carries the eleven decision keys and their match terms. That table is the boundary list;
    -- it is not a literal typed into this predicate, so the predicate follows it when it moves.
    select count(*) into v_n from public.founder_reserved_decision d
     where v_txt <> ''
       and (position(lower(replace(d.decision_key,'_',' ')) in lower(replace(v_txt,'_',' '))) > 0
            or exists (select 1 from unnest(d.match_any) t
                        where btrim(t) <> '' and position(lower(btrim(t)) in lower(v_txt)) > 0));
    -- The founder's own authority, resolved exactly as E28 resolved BR-003.
    v_n2 := case when exists (select 1 from public.founder_command fc
                               where 'founder_command:' || fc.command_id::text = v_txt2)
                 then 1 else 0 end;
    if v_n > 0 then
      -- "cannot bypass ... founder boundaries": a delegated authority is not enough here.
      v_ok := (v_n2 = 1);
      reason := format('BR-043: exception %s touches %s founder-reserved decision(s) and names authority %s, which %s',
                       v_txt, v_n, v_txt2,
                       case when v_ok then 'resolves to a founder command on record'
                            else 'does not resolve to any row in public.founder_command -- a delegated authority cannot clear a founder boundary' end);
    else
      v_ok := (v_n2 = 1)
              or exists (select 1 from public.employee_authority ea
                          where 'employee_authority:' || ea.agent_key || ':' || ea.action_class = v_txt2);
      reason := format('BR-043: exception %s names authority %s, which %s',
                       coalesce(nullif(v_txt,''),'(unnamed)'), v_txt2,
                       case when v_ok then 'resolves to a founder command or a granted employee authority'
                            else 'resolves to no row in public.founder_command or public.employee_authority' end);
    end if;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    return next; return;
  end if;

  if p_rule_id in ('BR-021','BR-022','BR-023','BR-024') then
    -- E31. THE SAME DEFECT E30 FOUND IN BR-043, IN THE FOUR RULES E29 HAD JUST FIXED.
    -- E29 made the AUTHORITY resolve, and that half holds. But applicability still keyed on
    -- 'commercial_policy_change', which is NOT in these rules' required_context -- all four
    -- declare only [founder_authority_ref]. So a call that named a founder authority and no
    -- commercial_policy_change was NOT_APPLICABLE, and the authority E29 taught the rule to
    -- resolve was never looked at. Measured after E30: feeding every rule 'banana' for each key
    -- it declares, BR-021..BR-024 were four of the five remaining passes, and all four passed as
    -- NOT_APPLICABLE rather than on the merits.
    --
    -- Bound, applicable and ACTUALLY REFUSES are three questions. E28 and E29 answered the third
    -- for these rules and left the second. A rule is now applicable when EITHER key is named: if
    -- a call in a founder-gated workflow asserts a founder authority, that assertion is judged.
    if coalesce(btrim(p_context->>'commercial_policy_change'),'') = ''
       and coalesce(btrim(p_context->>'founder_authority_ref'),'') = '' then
      state := 'NOT_APPLICABLE'; ok := true;
      reason := format('%s: the call proposes no change to a founder-reserved commercial term and asserts no founder authority', p_rule_id);
      return next; return;
    end if;
    -- E29. THE SAME DEFECT E28 FOUND IN BR-003, IN FOUR MORE RULES.
    -- This tested only that founder_authority_ref was non-empty, so BR-021 through BR-024 --
    -- the rules guarding founder-reserved COMMERCIAL terms -- returned ENFORCED_PASS for the
    -- literal string 'banana'. Measured 2026-08-20: 17 of the 30 rules that declare a
    -- required_context pass on that string. These four are the ones where the consequence is a
    -- forged founder decision on pricing, and they get the same resolution E28 gave BR-003.
    v_txt := btrim(coalesce(p_context->>'founder_authority_ref',''));
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('%s: change %s names no founder authority', p_rule_id,
                       coalesce(nullif(btrim(p_context->>'commercial_policy_change'),''),'(unnamed)'));
      return next; return;
    end if;
    v_ok := exists (select 1 from public.founder_command fc
                     where 'founder_command:' || fc.command_id::text = v_txt);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('%s: change %s %s', p_rule_id,
                     coalesce(nullif(btrim(p_context->>'commercial_policy_change'),''),'(unnamed)'),
                     case when v_ok then format('carries founder authority %s, which resolves to a founder command on record', v_txt)
                          else format('names %s, which does not resolve to any row in public.founder_command', v_txt) end);
    return next; return;
  end if;

  -- ---------------- BR-020: reveal only after reconciliation -------------------------------
  if p_rule_id = 'BR-020' then
    if p_context->>'transaction_id' is null then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-020: no transaction_id in context. A reveal decision with no transaction to reconcile is refused.';
      return next; return;
    end if;
    -- Aliased for the same reason as the lookup inside fn_phase_d_reveal_permitted: this
    -- function's OUT parameter is also called `reason`, so an unqualified reference is ambiguous
    -- between the plpgsql variable and the callee's returned column.
    select rp.permitted, rp.reason into v_ok, v_reason
      from public.fn_phase_d_reveal_permitted(p_context->>'transaction_id') rp;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := v_reason;
    return next; return;
  end if;

  -- ---------------- the object-backed rules D2 unblocked -----------------------------------
  if p_rule_id = 'BR-011' then           -- no customer identity in a supplier-facing payload
    v_txt := coalesce(p_context->>'supplier_payload','');
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-011: no supplier_payload named. A payload nobody showed cannot be certified free of customer identity.';
      return next; return;
    end if;
    select count(*) into v_n from public.customers c
     where (coalesce(c.email,'') <> '' and position(lower(c.email) in lower(v_txt)) > 0)
        or (coalesce(c.phone,'') <> '' and position(c.phone   in v_txt) > 0)
        or (coalesce(c.full_name,'') <> '' and length(c.full_name) > 3
            and position(lower(c.full_name) in lower(v_txt)) > 0);
    -- The test is simply whether any customer identity appears in the payload. An earlier draft
    -- also ORed in a reveal_state check, which collapsed to the same expression under operator
    -- precedence and read as if it were doing something it was not.
    -- E30. I DID NOT CHANGE WHAT THIS RULE MEANS, BECAUSE ITS 'banana' PASS IS A TRUE PASS: the
    -- string 'banana' carries no customer identity, and BR-011 is a content test, not a reference
    -- test. What was wrong is that its only evidence source is a table held at zero. The row-match
    -- arm answers 0 for every payload ever shown to it, and 0 is also what it would answer if it
    -- were broken. So the SHAPE is tested too: a supplier-facing payload carrying an email address
    -- or a dialable UAE mobile is a customer identity leak whether or not that person is a row in
    -- this estate yet.
    v_txt2 := regexp_replace(v_txt, '[^0-9]', '', 'g');
    v_n2 := (case when v_txt ~* '[A-Z0-9._%+-]+@[A-Z0-9.-]+[.][A-Z]{2,}' then 1 else 0 end)
          + (case when v_txt2 ~ '(971|0)5[0-9]{8}' then 1 else 0 end);
    v_ok := (v_n = 0 and v_n2 = 0);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-011: %s customer identity match(es) over %s customer row(s) searched for email, phone and full name, and %s identity-shaped token(s) -- an email address or a UAE mobile -- found in the payload itself',
                     v_n, (select count(*) from public.customers), v_n2);
    return next; return;
  end if;

  if p_rule_id = 'BR-012' then           -- an approved immutable supplier-safe package exists
    -- E30. This asked only whether two strings were non-empty, so 'banana' approved by 'banana'
    -- was an approved immutable supplier-safe package. supplier_safe_package is a REGISTERED
    -- business object of the IMMUTABLE_REVISION family: the ref must name one of those records in
    -- the approved state, and the approver must be someone who may own work here.
    v_txt  := btrim(coalesce(p_context->>'safe_package_ref',''));
    v_txt2 := btrim(coalesce(p_context->>'safe_package_approved_by',''));
    if v_txt = '' or v_txt2 = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-012: no approved supplier-safe package named, or no approver named. No assignment or notification may be created without one.';
      return next; return;
    end if;
    select count(*) into v_n from public.phase_d_object_record o
     where o.object_id = 'supplier_safe_package' and o.state = 'approved' and o.superseded_by is null
       and (o.business_key = v_txt or 'supplier_safe_package:' || o.business_key = v_txt);
    v_ok := (v_n >= 1) and public.fn_phase_c_actor_may_own(v_txt2);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-012: package %s resolves to %s approved supplier_safe_package record(s) in public.phase_d_object_record, and approver %s %s',
                     v_txt, v_n, v_txt2,
                     case when public.fn_phase_c_actor_may_own(v_txt2)
                          then 'resolves to an active canonical role'
                          else 'does not resolve to an active canonical role' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-013' then           -- the inquiry is quote-ready
    if p_context->>'inquiry_id' is null then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-013: no inquiry_id named; readiness cannot be measured against nothing.';
      return next; return;
    end if;
    select count(*) into v_n from public.inquiries i
     where i.id::text = p_context->>'inquiry_id'
       and coalesce(i.status,'') in ('quote_ready','dispatched','quoted','completed');
    v_ok := (v_n = 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-013: inquiry %s %s', p_context->>'inquiry_id',
                     case when v_ok then 'is in a quote-ready state'
                          else 'is not quote-ready; mandatory qualification, route or document blockers remain' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-014' then           -- only a CONFIRMED route authorises dispatch
    v_ok := lower(coalesce(btrim(p_context->>'route_state'),'')) = 'confirmed';
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-014: route state %s. Proposed, ambiguous, rejected and excluded routes cannot authorise dispatch.',
                     coalesce(nullif(btrim(p_context->>'route_state'),''),'(unstated)'));
    return next; return;
  end if;

  if p_rule_id = 'BR-015' then           -- only an approved, eligible supplier is dispatched to
    if p_context->>'supplier_id' is null then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-015: no supplier_id named.'; return next; return;
    end if;
    select count(*) into v_n from public.leads l
     where l.id::text = p_context->>'supplier_id'
       and coalesce(l.approval_status,'') = 'approved' and coalesce(l.verified,false);
    v_ok := (v_n = 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-015: supplier %s %s. public.leads already enforces approved implies verified as a CHECK constraint.',
                     p_context->>'supplier_id',
                     case when v_ok then 'is approved and verified' else 'is not an approved, verified supplier' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-016' then           -- one assignment per supplier per inquiry version
    if p_context->>'inquiry_id' is null or p_context->>'supplier_id' is null then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-016: inquiry_id and supplier_id are both required to decide duplicate assignment.';
      return next; return;
    end if;
    select count(*) into v_n from public.inquiry_matches m
     where m.inquiry_id::text = p_context->>'inquiry_id'
       and m.supplier_id::text = p_context->>'supplier_id';
    v_ok := (v_n <= 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-016: %s existing assignment(s) for that supplier and inquiry. NOTE: public.inquiry_matches carries no version column and no unique constraint, so this is enforced here and NOT structurally — recorded as the D2 REPAIR on supplier_assignment.', v_n);
    return next; return;
  end if;

  if p_rule_id = 'BR-017' then           -- a refused assignment is not a contact
    v_ok := lower(coalesce(btrim(p_context->>'assignment_result'),'')) in ('delivered','accepted','sent');
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-017: assignment result %s. Refused and failed assignments are not counted as contacted and create no success notification.',
                     coalesce(nullif(btrim(p_context->>'assignment_result'),''),'(unstated)'));
    return next; return;
  end if;

  if p_rule_id = 'BR-018' then           -- the supplier's own revision is never platform-edited
    v_ok := coalesce(btrim(p_context->>'quote_revision_ref'),'') <> ''
            and coalesce(p_context->>'platform_edited','true') = 'false';
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('BR-018: revision %s is supplier-authored and unedited; normalisation is separate',
                                         p_context->>'quote_revision_ref')
                   else 'BR-018: no unedited supplier revision named. The platform may normalise for comparison but never alter the original.' end;
    return next; return;
  end if;

  if p_rule_id = 'BR-019' then           -- a customer sees only their own published comparison
    if p_context->>'comparison_id' is null or p_context->>'caller_customer_id' is null then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-019: comparison_id and caller_customer_id are both required.'; return next; return;
    end if;
    select count(*) into v_n from public.quote_comparisons qc
     where qc.id::text = p_context->>'comparison_id'
       and qc.customer_id::text = p_context->>'caller_customer_id';
    v_ok := (v_n = 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-019: comparison %s %s the calling customer', p_context->>'comparison_id',
                     case when v_ok then 'belongs to' else 'does NOT belong to' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-025' then           -- acceptance names the exact version and hash
    -- E30. "the exact displayed version AND hash" was tested as "two non-empty strings", so
    -- 'banana' was an exact hash of version 'banana'. public.legal_documents holds the displayed
    -- documents and their versions. The hash must be a real SHA-256 digest, and it must be the
    -- digest OF THAT DOCUMENT AT THAT VERSION -- a hash that matches nothing is not a reference
    -- to anything specific, which is the whole of what this rule asks for.
    v_txt  := btrim(coalesce(p_context->>'terms_version',''));
    v_txt2 := lower(btrim(coalesce(p_context->>'terms_hash','')));
    if v_txt = '' or v_txt2 = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-025: acceptance must reference the exact displayed version AND hash; one without the other is not an acceptance of anything specific.';
      return next; return;
    end if;
    if v_txt2 !~ '^[0-9a-f]{64}$' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-025: terms_hash %s is not a SHA-256 digest (64 hexadecimal characters), so it was never computed over the displayed terms.',
                       left(v_txt2, 24));
      return next; return;
    end if;
    select count(*) into v_n from public.legal_documents d
     where d.version = v_txt
       and encode(sha256(convert_to(coalesce(d.body_html,''), 'UTF8')), 'hex') = v_txt2;
    v_ok := (v_n >= 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-025: acceptance names version %s at digest %s, which matches %s row(s) in public.legal_documents whose displayed body hashes to exactly that digest',
                     v_txt, left(v_txt2, 12), v_n);
    return next; return;
  end if;

  if p_rule_id = 'BR-026' then           -- no certificate before an acceptance record
    -- E30. The reason string read "acceptance record %s exists" while the predicate had only
    -- checked that a string was non-empty -- evidence stating the premise it never tested.
    -- customer_terms_acceptance and supplier_terms_acceptance are registered APPEND_ONLY business
    -- objects; the ref must name one of those records.
    v_txt := btrim(coalesce(p_context->>'acceptance_ref',''));
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-026: no acceptance record named. A certificate generated before acceptance would assert a fact that has not happened.';
      return next; return;
    end if;
    select count(*) into v_n from public.phase_d_object_record o
     where o.object_id in ('customer_terms_acceptance','supplier_terms_acceptance')
       and (o.business_key = v_txt or o.object_id || ':' || o.business_key = v_txt);
    v_ok := (v_n >= 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-026: acceptance_ref %s resolves to %s terms-acceptance record(s) in public.phase_d_object_record. A certificate may not precede one.',
                     v_txt, v_n);
    return next; return;
  end if;

  if p_rule_id = 'BR-029' then           -- conflicting evidence is preserved, not overwritten
    -- E30. Two arms, both weak. conflict_preserved='true' was the CALLER asserting its own
    -- compliance, which is not evidence of it; and evidence_authority was tested for
    -- non-emptiness, so 'banana' was an authority ranking. This rule is about RANK -- lower
    -- authority may not overwrite higher -- and this estate has a ranking:
    -- public.mep_evidence_weight, with its weight keys, evidence sources and source authorities.
    -- An authority that is not in the ranking cannot be ordered against another, so it cannot be
    -- preserved against one either.
    v_txt := btrim(coalesce(p_context->>'evidence_authority',''));
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-029: no evidence authority named. Lower-authority evidence may not silently overwrite higher, and an unranked authority cannot be ordered against any other.';
      return next; return;
    end if;
    select count(*) into v_n from public.mep_evidence_weight w
     where w.weight_key = v_txt or w.evidence_source = v_txt or w.source_authority = v_txt;
    v_ok := (v_n >= 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-029: evidence authority %s matches %s row(s) in the public.mep_evidence_weight ranking (weight_key, evidence_source or source_authority)%s',
                     v_txt, v_n,
                     case when v_ok then ', so conflicting evidence can be retained in rank order'
                          else ' -- it is not a ranked authority in this estate' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-032' then           -- provider events are unique and replay-safe
    if coalesce(btrim(p_context->>'provider_event_id'),'') = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-032: no provider_event_id named; duplicate delivery cannot be decided without one.';
      return next; return;
    end if;
    -- E30. THE TEST WAS "appears AT MOST once", so an event id appearing ZERO times satisfied a
    -- rule about the safety of REAL provider events -- one never delivered, or the literal
    -- 'banana'. Zero cannot tell an unknown event from a safe one. It must resolve to EXACTLY ONE
    -- recorded delivery, in the provider event log or in the registered provider_event object.
    v_txt := btrim(coalesce(p_context->>'provider_event_id',''));
    select count(*) into v_n  from public.stripe_events se where se.event_id = v_txt;
    select count(*) into v_n2 from public.phase_d_object_record o
     where o.object_id = 'provider_event'
       and (o.business_key = v_txt or 'provider_event:' || o.business_key = v_txt);
    v_ok := (v_n + v_n2) = 1;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-032: provider event %s resolves to %s row(s) in public.stripe_events and %s registered provider_event record(s). Exactly one is replay-safe: zero is an event nobody received, more than one is a duplicate.',
                     v_txt, v_n, v_n2);
    return next; return;
  end if;

  if p_rule_id = 'BR-033' then           -- unknown money is quarantined, never success
    -- E30. A DENY-LIST OF THREE WORDS LEFT EVERY OTHER STRING AS A GOOD MONETARY STATE. The
    -- acceptance audit watched the harness hand this rule 'checkout_created' and get ok=true;
    -- 'banana' did just as well. An unrecognised monetary state IS an unknown one, which is
    -- precisely what this rule exists to quarantine. The permitted set is read from the state
    -- contracts of the TRANSACTION_RECORD family -- the money-carrying objects -- and not typed
    -- in here, so it follows the registry instead of drifting from it.
    -- G04. THE RULE ABOUT MONEY WAS ASKING THE REGISTER THAT DOES NOT MODEL MONEY.
    --
    -- E30 corrected a deny-list of three words by reading the allowed_states of the
    -- TRANSACTION_RECORD family, which was right about the method and wrong about the register.
    -- Two vocabularies describe a transaction in this estate:
    --
    --   public.phase_d_object_state_contract  open, pending, settled, refunded, failed, reconciled
    --       the generic OBJECT-RECORD lifecycle, derived from policy_family and applied identically
    --       to dispatch_batch, payment_transaction, reveal_transaction and supplier_assignment.
    --   public.phase_d_payment_state          checkout_created, payment_initiated, provider_success,
    --       payment_confirmed, payment_reconciled, reveal_authorized -- a SIX-RUNG LADDER, each rung
    --       carrying authorizes_reveal and a stated reason, and it is what public.transactions
    --       .fee_status actually holds and what BR-020 reads.
    --
    -- MEASURED: the intersection of those two sets is EMPTY. Not "different in places" -- no value
    -- appears in both. So BR-033 refused every real monetary state this estate can produce,
    -- including payment_reconciled, the founder-approved bar in BR-020, and would have PASSED
    -- 'settled' or 'refunded' for a payment that never reconciled. Two rules about one transaction,
    -- unable to agree about any transaction, because one of them was reading the wrong register.
    --
    -- THE FROZEN TEXT DECIDES WHICH REGISTER IS RIGHT: "Unknown, conflicting or unreconciled
    -- monetary states are blocked/quarantined and cannot be treated as success." Recognised, and
    -- reconciled. The ladder is the register of recognised monetary states and authorizes_reveal is
    -- the ladder's own mark for the reconciled rungs, so both halves of the frozen sentence are
    -- read from the register that states them.
    --
    -- THIS IS STRICTLY TIGHTER THAN WHAT IT REPLACES, and that is the test of it. Before: five
    -- words passed that say nothing about reconciliation. After: an unrecognised state is refused
    -- as unrecognised, a recognised state below reconciliation is refused as unreconciled, and the
    -- three quarantine words are refused by name as they always were. Only payment_reconciled and
    -- reveal_authorized pass, which is the relationship the founder's section 5 asked BR-020 and
    -- BR-033 to evaluate between them.
    --
    -- public.phase_d_object_state_contract IS NOT AMENDED. The founder's section 5 forbids putting
    -- reveal_authorized into the TRANSACTION_RECORD family to make this rule green, and nothing
    -- here does: the family keeps the generic lifecycle it describes, and this rule stops asking
    -- it a question it was never the register for.
    v_txt := lower(coalesce(btrim(p_context->>'monetary_state'),''));
    select count(*) into v_n
      from public.phase_d_payment_state ps
     where lower(ps.state_key) = v_txt and ps.authorizes_reveal;
    v_ok := v_txt <> '' and v_txt not in ('unknown','conflicting','unreconciled') and v_n >= 1;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-033: monetary state %s matches %s reconciled rung(s) of the payment ladder public.phase_d_payment_state (%s of its %s rungs are reconciled: %s). Unknown, conflicting, unreconciled and unrecognised states are blocked and quarantined, never treated as success.',
                     coalesce(nullif(v_txt,''),'(unstated)'), v_n,
                     (select count(*) from public.phase_d_payment_state where authorizes_reveal),
                     (select count(*) from public.phase_d_payment_state),
                     (select string_agg(ps2.state_key, ', ' order by ps2.rung)
                        from public.phase_d_payment_state ps2 where ps2.authorizes_reveal));
    return next; return;
  end if;

  if p_rule_id = 'BR-034' then           -- consent and suppression are respected
    if coalesce(btrim(p_context->>'notify_email'),'') = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-034: no notify_email named; consent cannot be decided for an unnamed recipient.';
      return next; return;
    end if;
    -- E30. 'banana' is not in the suppression list, so 'banana' was a consenting recipient. A
    -- string that cannot be an email address cannot have been checked for consent: it has to be
    -- an address before the suppression lookup means anything at all.
    v_txt := btrim(coalesce(p_context->>'notify_email',''));
    if v_txt !~* '^[A-Z0-9._%+-]+@[A-Z0-9.-]+[.][A-Z]{2,}$' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-034: %s is not an email address, so no consent or suppression decision about it exists to respect.', v_txt);
      return next; return;
    end if;
    select count(*) into v_n from public.email_suppressions s
     where lower(s.email) = lower(v_txt);
    v_ok := (v_n = 0);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-034: %s is %s in public.email_suppressions (%s matching row(s) over %s suppression(s) on record)',
                     v_txt,
                     case when v_ok then 'not suppressed' else 'SUPPRESSED and must not be contacted' end,
                     v_n, (select count(*) from public.email_suppressions));
    return next; return;
  end if;

  if p_rule_id = 'BR-035' then           -- only the approved revision publishes
    -- E30. Feeding the same junk string to both keys satisfied this rule, because equality of two
    -- unresolved strings is not evidence that either names an approved revision. The approved ref
    -- must resolve to an IMMUTABLE_REVISION business object record in the approved state -- the
    -- estate's own registry of revisions -- and the revision being published must be that one.
    v_txt  := btrim(coalesce(p_context->>'approved_revision_ref',''));
    v_txt2 := btrim(coalesce(p_context->>'publishing_revision_ref',''));
    if v_txt = '' or v_txt2 = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-035: the revision being published is not the independently approved revision, or neither was named.';
      return next; return;
    end if;
    if v_txt <> v_txt2 then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-035: the publishing revision %s is not the approved revision %s', v_txt2, v_txt);
      return next; return;
    end if;
    select count(*) into v_n from public.phase_d_object_record o
      join public.phase_d_object_state_contract c on c.object_id = o.object_id
     where c.policy_family = 'IMMUTABLE_REVISION' and o.state = 'approved'
       and (o.business_key = v_txt or o.object_id || ':' || o.business_key = v_txt);
    v_ok := (v_n >= 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-035: the publishing revision is the approved one (%s), and that reference resolves to %s approved IMMUTABLE_REVISION record(s) in public.phase_d_object_record',
                     v_txt, v_n);
    return next; return;
  end if;

  if p_rule_id = 'BR-036' then           -- review inspects the artifact, not the brief
    -- E30. The acceptance audit caught this one from the other end: it read back
    -- "review names artifact ZZ DEMO - artifact_ref at digest ZZ DEMO - artifact_sha256" and got
    -- ok=true. A SHA-256 is 64 hexadecimal characters; a value that is not one was never computed
    -- over any artifact. And the digest must be OF something -- an artifact_review row, or a
    -- business object record carrying it. In an estate whose vision model once listed eight
    -- identifiers verbatim from a solid black rectangle, the digest is the only part of an
    -- artifact review that cannot be imagined.
    v_txt  := btrim(coalesce(p_context->>'artifact_ref',''));
    v_txt2 := lower(btrim(coalesce(p_context->>'artifact_sha256','')));
    if v_txt = '' or v_txt2 = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-036: the review names no artifact and digest. A verifier that reads the brief instead of the artifact has already produced a false pass in this estate.';
      return next; return;
    end if;
    if v_txt2 !~ '^[0-9a-f]{64}$' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-036: artifact_sha256 %s is not a SHA-256 digest (64 hexadecimal characters), so it was not computed over any artifact.',
                       left(v_txt2, 24));
      return next; return;
    end if;
    select count(*) into v_n  from public.artifact_review ar where lower(ar.artifact_sha256) = v_txt2;
    select count(*) into v_n2 from public.phase_d_object_record o
     where lower(o.payload->>'artifact_sha256') = v_txt2;
    v_ok := (v_n + v_n2) >= 1;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-036: review names artifact %s at digest %s, which resolves to %s artifact_review row(s) and %s business object record(s) carrying exactly that digest',
                     v_txt, left(v_txt2, 12), v_n, v_n2);
    return next; return;
  end if;

  if p_rule_id = 'BR-039' then           -- a release needs an executable rollback
    -- E30. The rule says DEFINED AND EXECUTABLE; the predicate tested only that a string had been
    -- typed, so 'banana' was an executable rollback path. Executable means the estate can name the
    -- thing that would run: a registered action class carrying a compensating action, or a routine
    -- that exists in this database.
    v_txt := btrim(coalesce(p_context->>'rollback_ref',''));
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-039: no rollback or recovery path named. A consequential release without one is not approvable.';
      return next; return;
    end if;
    select count(*) into v_n from public.org_action_executor x
     where x.action_class = v_txt and coalesce(btrim(x.compensation_action_class),'') <> '';
    select count(*) into v_n2 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname = regexp_replace(v_txt, '^public[.]', '');
    v_ok := (v_n + v_n2) >= 1;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-039: rollback path %s resolves to %s registered action class(es) carrying a compensating action and %s routine(s) in this database%s',
                     v_txt, v_n, v_n2,
                     case when v_ok then '' else ' -- nothing that could be executed to undo the release' end);
    return next; return;
  end if;

  if p_rule_id = 'BR-041' then           -- activity is not outcome
    -- E30. "when a business outcome is DEFINED" was tested as "a string was typed that differs
    -- from the activity metric", so 'banana' was a business outcome. public.metric_definition IS
    -- this estate's register of defined metrics. A metric that is not in it has not been defined,
    -- and success declared on it is exactly the vanity claim this rule forbids.
    v_txt  := btrim(coalesce(p_context->>'outcome_metric',''));
    v_txt2 := coalesce(p_context->>'activity_metric','');
    if v_txt = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-041: no business outcome metric named.';
      return next; return;
    end if;
    if v_txt = v_txt2 then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := format('BR-041: the declared outcome metric %s IS the activity metric under another name', v_txt);
      return next; return;
    end if;
    select count(*) into v_n from public.metric_definition m where m.metric_key = v_txt;
    v_ok := (v_n = 1);
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-041: success is declared on outcome metric %s, distinct from the activity metric, and that key resolves to %s row(s) in public.metric_definition (of %s defined metrics)',
                     v_txt, v_n, (select count(*) from public.metric_definition));
    return next; return;
  end if;

  if p_rule_id = 'BR-049' then           -- inquiry accountability does not drift
    v_ok := coalesce(btrim(p_context->>'inquiry_owner'),'') = 'rfq_qualification_manager'
            or coalesce(btrim(p_context->>'accountability_transfer_approved'),'') = 'true';
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := format('BR-049: inquiry owner is %s. Specialist and document handoffs do not move overall inquiry accountability away from rfq_qualification_manager without an approved workflow that says so.',
                     coalesce(nullif(btrim(p_context->>'inquiry_owner'),''),'(unstated)'));
    return next; return;
  end if;

  -- ---------------- D47. FIVE RULES THAT NOW DECIDE FOR THEMSELVES --------------------------
  -- BR-027, BR-040 and BR-042 were SCHEMA_ENFORCED fall-throughs returning ENFORCED_PASS with the
  -- reason "is enforced ... later in this same call". True, and useless: the schema they deferred
  -- to checked presence and emptiness only, so none of the three could refuse anything. D46 gave
  -- the validator declared types and domains; these three read the same facts directly.

  if p_rule_id = 'BR-027' then           -- a finding names the evidence it rests on
    v_ok := jsonb_typeof(p_context->'evidence_refs') = 'array'
            and jsonb_array_length(coalesce(p_context->'evidence_refs','[]'::jsonb)) > 0;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('BR-027: %s evidence reference(s) named',
                                         jsonb_array_length(p_context->'evidence_refs'))
                   else 'BR-027: no evidence_refs array. A finding that names no evidence is an assertion.' end;
    return next; return;
  end if;

  if p_rule_id = 'BR-040' then           -- a ratio states its formula and its denominator
    -- THE DENOMINATOR IS TYPED HERE, not merely present. jsonb_typeof('"0"') is 'string', so a
    -- denominator of "0" as text satisfied every presence check in this estate and still divided
    -- something by nothing. least(100, NULL) = 100 is the same defect in another costume.
    v_ok := coalesce(btrim(p_context->>'formula'),'') <> ''
            and jsonb_typeof(p_context->'denominator') = 'number'
            and (p_context->>'denominator')::numeric > 0;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('BR-040: formula %L over a numeric denominator of %s',
                                         p_context->>'formula', p_context->>'denominator')
                   else format('BR-040: formula %L, denominator %s of type %s. A ratio needs a stated formula and a numeric denominator greater than zero.',
                               coalesce(p_context->>'formula','(none)'),
                               coalesce(p_context->>'denominator','(none)'),
                               coalesce(jsonb_typeof(p_context->'denominator'),'absent')) end;
    return next; return;
  end if;

  if p_rule_id = 'BR-042' then           -- an analysis states its assumptions
    -- AND THEY MAY NOT BE THE ONES THE EXECUTOR WRITES FOR ITSELF. fn_phase_d_handler_execute
    -- writes ANALYSIS_HANDLER's assumptions unconditionally as the fixed one-element literal
    -- 'only the inputs named in this call were used; no external source was consulted'. A rule
    -- satisfied by a constant its own caller supplies is a rule that cannot fail, so that exact
    -- value is refused by name.
    v_ok := jsonb_typeof(p_context->'assumptions') = 'array'
            and jsonb_array_length(coalesce(p_context->'assumptions','[]'::jsonb)) > 0
            and p_context->'assumptions' <> jsonb_build_array(
                  'only the inputs named in this call were used; no external source was consulted');
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('BR-042: %s assumption(s) stated',
                                         jsonb_array_length(p_context->'assumptions'))
                   when p_context->'assumptions' = jsonb_build_array(
                          'only the inputs named in this call were used; no external source was consulted')
                     then 'BR-042: the only assumption stated is the executor''s own boilerplate. A constant the caller writes for itself is not a stated assumption.'
                   else 'BR-042: no assumptions array. An analysis that states no assumptions has hidden them.' end;
    return next; return;
  end if;

  -- D51. BR-008 HAD ITS PREDICATE REMOVED AGAIN, AND THE REGISTRY WAS RIGHT THE FIRST TIME.
  -- D47 gave it one because fn_phase_d_handoff_packet_valid is STABLE and therefore callable.
  -- Callable is not the same as answerable HERE. The packet is what the SENDING STEP PRODUCES;
  -- at the moment fn_phase_d_rule_check runs — the step has just opened and nobody has done it —
  -- the packet does not exist yet. So the predicate refused 29 of 30 first steps, then 15 of 30
  -- once the applicability rule was added, and every one of those refusals was the rule being
  -- asked a question the lifecycle had not reached.
  --
  -- Its enforcement_kind was KERNEL_ENFORCED for exactly that reason: the kernel checks the packet
  -- when the handoff is accepted, which is when there is one to check. It falls through to the
  -- delegated branch below, where it is honestly labelled rather than given a pass or a refusal it
  -- has not earned. BR-044 keeps its predicate: an SLA due time IS computable when the step opens.
  if p_rule_id = 'BR-044' then           -- an SLA has a computable due time
    if coalesce(btrim(p_context->>'sla_policy_id'),'') = '' then
      state := 'ENFORCED_FAIL'; ok := false;
      reason := 'BR-044: no sla_policy_id named, so no due time can be computed.';
      return next; return;
    end if;
    -- D51. THE DELEGATE DEFAULTS, SO "is not null" COULD NEVER FAIL. fn_kernel_sla_due ends in
    -- coalesce(<the policy lookup>, 24), so an sla_policy_id that exists nowhere silently gets a
    -- 24-hour deadline and a non-null answer. Measured: fn_kernel_sla_due('zz-demo-no-such-policy')
    -- returns a timestamp 24 hours out. The predicate therefore asks the question the default hides:
    -- is this policy REGISTERED, and does it then compute a due time. The 24-hour fallback lives in
    -- a frozen kernel routine and is not changed here; it is named so it can be seen.
    v_ok := exists (select 1 from public.phase_b_sla_policy sp
                     where sp.sla_policy_id = p_context->>'sla_policy_id')
            and public.fn_kernel_sla_due(p_context->>'sla_policy_id', now()) is not null;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('BR-044: policy %s resolves to a due time',
                                         p_context->>'sla_policy_id')
                   else format('BR-044: policy %L computes no due time', p_context->>'sla_policy_id') end;
    return next; return;
  end if;
  -- ---------------- structurally enforced elsewhere ----------------------------------------
  if e.enforcement_kind in ('SCHEMA_ENFORCED','EXECUTOR_ENFORCED') then
    state := 'ENFORCED_PASS'; ok := true;
    reason := format('%s is enforced at %s later in this same call, which refuses with %s',
                     p_rule_id, e.enforcement_point, e.refusal_code);
    return next; return;
  end if;
  if e.enforcement_kind in ('KERNEL_ENFORCED','TRIGGER_ENFORCED') then
    -- D47. THIS USED TO SAY ENFORCED_PASS, AND THE PLAN ASKED FOR THE DELEGATE TO BE INVOKED
    -- INSTEAD. Measured, that is possible for two of these and impossible for the other eleven:
    --
    --   BR-006 BR-007 BR-009 BR-045  public.fn_kernel_step_complete(jsonb)  VOLATILE SECDEF, writes
    --   BR-046                       public.fn_kernel_cancel(jsonb)         VOLATILE SECDEF, writes
    --   BR-010                       public.fn_phase_c_trace_append_only()  returns trigger
    --   BR-047                       public.fn_org_authority_guard()        returns trigger
    --   BR-050 BR-051 BR-052         public.fn_kernel_write_guard()         returns trigger
    --
    -- A routine returning trigger cannot be called at all, and a volatile writer cannot be called
    -- from this STABLE predicate without performing the very act it is being asked about. BR-008
    -- and BR-044 CAN be called, and now are, above.
    --
    -- So these get a state of their own rather than a pass they did not earn. Nothing about the
    -- runtime changes: fn_phase_d_handler_execute refuses on ENFORCED_FAIL and NOT_IMPLEMENTED, and
    -- DELEGATED_TO_KERNEL_GUARD is neither. What changes is the count that may be claimed. A rule
    -- enforced by a guard this call never reaches is not a rule this predicate enforces.
    state := 'DELEGATED_TO_KERNEL_GUARD'; ok := true;
    reason := format('%s is enforced at %s, which raises %s. That routine %s, so this predicate cannot invoke it: the guard decides and this call does not.',
                     p_rule_id, e.enforcement_point, e.refusal_code,
                     case when e.enforcement_kind = 'TRIGGER_ENFORCED'
                          then 'returns trigger' else 'is a volatile writer' end);
    return next; return;
  end if;
  if e.enforcement_kind = 'CONTEXT_REQUIRED' then
    select array_agg(k order by k) into v_missing
      from unnest(e.required_context) k
     where not (p_context ? k) or coalesce(btrim(p_context->>k),'') = '';
    v_ok := (v_missing is null);
    -- E19. THE REFUSAL STANDS; ONLY ITS NAME CHANGES. This branch fires when the call names none of
    -- the evidence the rule reads, which is not the same event as the rule reading that evidence and
    -- finding it violates policy. Both refuse. The state stays ENFORCED_FAIL so that every existing
    -- reader -- fn_phase_d_handler_execute, fn_phase_d_rule_can_refuse, fn_phase_d_rule_state --
    -- behaves exactly as before; evidence_absent is the new fact, and it is what lets
    -- fn_phase_d_dispatch_step record REFUSED_EVIDENCE_ABSENT instead of REFUSED. A reader could
    -- previously take an absence of evidence for a business violation, and the 2026-08-20
    -- acceptance audit did exactly that and said so in finding 3.
    evidence_absent := not v_ok;
    state := case when v_ok then 'ENFORCED_PASS' else 'ENFORCED_FAIL' end; ok := v_ok;
    reason := case when v_ok then format('%s: the call names %s', p_rule_id, array_to_string(e.required_context,', '))
                   else format('%s requires [%s] and the call names none of it.', p_rule_id, array_to_string(v_missing,', ')) end;
    return next; return;
  end if;

  -- ---------------- NO PREDICATE. This is the answer that used to be `true`. ----------------
  state := 'NOT_IMPLEMENTED'; ok := false; enforced := false;
  reason := format('%s has no predicate in fn_phase_d_rule_check. NOT_IMPLEMENTED is not a pass.', p_rule_id);
  refusal_code := coalesce(e.refusal_code, 'rule_not_implemented');
  return next;
end

fn_phase_d_gate_evaluate:
declare
  g public.phase_b_gate%rowtype;
  c public.phase_d_gate_contract%rowtype;
  s public.phase_b_workflow_step%rowtype;
  v_missing text[]; v_n bigint; v_ok boolean; v_txt text;
  v_auth jsonb;   -- K01
begin
  evidence_absent := false;   -- E19, see fn_phase_d_rule_check
  select * into g from public.phase_b_gate where gate_id = p_gate_id;
  if not found then
    state := 'NOT_IMPLEMENTED'; passed := false; gate_type := 'unknown';
    reason := format('unknown gate %s — blocked, not defaulted', p_gate_id);
    refusal_code := 'gate_unknown'; return next; return;
  end if;
  gate_type := g.gate_type;

  select * into c from public.phase_d_gate_contract where gate_id = p_gate_id;
  if not found then
    state := 'NOT_IMPLEMENTED'; passed := false;
    reason := format('gate %s has no Phase D evidence contract — blocked', p_gate_id);
    refusal_code := 'gate_uncontracted'; return next; return;
  end if;
  refusal_code := c.refusal_code;

  if cardinality(c.evidence_keys) > 0 then
    select array_agg(k order by k) into v_missing
      from unnest(c.evidence_keys) k
     where p_evidence is null or not (p_evidence ? k)
        or jsonb_typeof(p_evidence->k) = 'null'
        or (jsonb_typeof(p_evidence->k) = 'string' and btrim(p_evidence->>k) = '');
    if v_missing is not null then
      -- E19. Same distinction as the rule side. The gate is BLOCKED either way; this column says
      -- which kind of blocked. Here the gate never saw its evidence -- it did not judge it.
      evidence_absent := true;
      state := 'BLOCKED'; passed := false;
      reason := format('gate %s (%s) requires [%s] and the call names none of it. Declared evidence: %s',
                       g.gate_id, g.gate_name, array_to_string(v_missing, ', '),
                       coalesce(g.required_evidence,'(none stated)'));
      return next; return;
    end if;
  end if;

  if p_gate_id = 'GATE-001' then
    select count(*) into v_n from public.fn_phase_a_baseline_drift();
    v_ok := (v_n = 0) and exists (select 1 from public.org_phase_baseline where phase = 'A');
    reason := format('GATE-001: Phase A drift %s row(s); baseline row %s', v_n,
                     case when exists (select 1 from public.org_phase_baseline where phase='A')
                          then 'present' else 'ABSENT' end);

  elsif p_gate_id = 'GATE-002' then
    v_ok := public.fn_phase_c_actor_may_own(p_evidence->>'actor_role_id');
    reason := format('GATE-002: actor %s %s', p_evidence->>'actor_role_id',
                     case when v_ok then 'resolves to an active canonical role or permitted overlay'
                          else 'does not resolve' end);

  elsif p_gate_id = 'GATE-003' then
    select count(*) into v_n from public.phase_b_workflow_step x
     where x.step_id = p_evidence->>'step_id' and coalesce(btrim(x.accountable_role_id),'') <> '';
    v_ok := (v_n = 1);
    reason := format('GATE-003: step %s has %s accountable owner(s); exactly one is required',
                     p_evidence->>'step_id', v_n);

  elsif p_gate_id = 'GATE-004' then
    select * into s from public.phase_b_workflow_step where step_id = p_evidence->>'step_id';
    v_ok := public.fn_kernel_reviewer_independent(s.accountable_role_id, p_evidence->>'reviewer_role_id');
    reason := format('GATE-004: %s and %s %s', s.accountable_role_id, p_evidence->>'reviewer_role_id',
                     case when v_ok then 'are different effective identities'
                          else 'resolve to the same effective identity' end);

  elsif p_gate_id = 'GATE-005' then
    -- K01. THIS WAS `v_ok := true`. The gate checked that a string was present and never that it
    -- meant anything, so any caller could have handed it any text and passed the founder boundary.
    -- It now resolves the authority for itself, from the founder command that instructed the run or
    -- from the founder-approved frozen boundary register, and requires the reference the call
    -- presents to be the one that resolves.
    select * into s from public.phase_b_workflow_step where step_id = p_evidence->>'step_id';
    v_auth := public.fn_phase_d_founder_authority(
                nullif(p_evidence->>'run_id','')::bigint, p_evidence->>'step_id');
    v_ok := coalesce((v_auth->>'valid')::boolean, false)
            and v_auth->>'ref' is not null
            and (p_evidence->>'founder_authority_ref') = (v_auth->>'ref');
    reason := format('GATE-005: step declares founder_gate %s; the call names authority %s; the '
                  || 'estate resolves %s (%s) -- %s',
                     left(coalesce(s.founder_gate,'none'),60),
                     coalesce(p_evidence->>'founder_authority_ref','(none)'),
                     coalesce(v_auth->>'ref','(none)'), coalesce(v_auth->>'kind','-'),
                     coalesce(v_auth->>'why','(no reason stated)'));

  elsif p_gate_id = 'GATE-006' then
    if p_evidence->>'from_state' = p_evidence->>'to_state' then
      v_ok := true;
      reason := format('GATE-006: the run stays in %s — this step applies no workflow-state '
                    || 'transition, so there is none to declare. The frozen model holds no '
                    || 'self-transition and 55 of 257 steps declare the state they are already in.',
                       p_evidence->>'from_state');
    else
      select count(*) into v_n from public.phase_b_workflow_transition t
       where t.from_state = p_evidence->>'from_state' and t.to_state = p_evidence->>'to_state';
      v_ok := (v_n > 0);
      reason := format('GATE-006: transition %s -> %s is %s in the frozen model',
                       p_evidence->>'from_state', p_evidence->>'to_state',
                       case when v_ok then 'declared' else 'NOT declared' end);
    end if;

  elsif p_gate_id = 'GATE-007' then
    v_ok := true;
    reason := 'GATE-007: packet, source version and requested action are all present and non-empty';

  elsif p_gate_id = 'GATE-008' then
    -- THE CLOSING STEP IS NOT AN OUTSTANDING PIECE OF WORK. It is necessarily open while it asks,
    -- so counting it made this gate unpassable for all 30 closure steps. Every other open step run
    -- still blocks.
    select count(*) into v_n from public.phase_c_workflow_step_run x
     where x.run_id = (p_evidence->>'run_id')::bigint
       and x.step_run_id is distinct from (p_evidence->>'step_run_id')::bigint
       and x.state not in ('completed','cancelled','failed','superseded','skipped');
    v_ok := (v_n = 0);
    reason := format('GATE-008: %s step run(s) still open on run %s, excluding the closing step run %s itself',
                     v_n, p_evidence->>'run_id', p_evidence->>'step_run_id');

  elsif p_gate_id = 'GATE-009' then
    v_ok := true;
    reason := format('GATE-009: acceptance %s names version %s at hash %s',
                     p_evidence->>'acceptance_ref', p_evidence->>'terms_version',
                     left(p_evidence->>'terms_hash',12));

  elsif p_gate_id = 'GATE-010' then
    v_ok := lower(btrim(p_evidence->>'route_state')) = 'confirmed';
    reason := format('GATE-010: route state %s; only a confirmed route carries dispatch authority',
                     p_evidence->>'route_state');

  elsif p_gate_id = 'GATE-011' then
    select count(*) into v_n from public.inquiries i
     where i.id::text = p_evidence->>'inquiry_id'
       and coalesce(i.status,'') in ('quote_ready','dispatched','quoted','completed');
    v_ok := (v_n = 1);
    reason := format('GATE-011: inquiry %s %s', p_evidence->>'inquiry_id',
                     case when v_ok then 'is quote-ready' else 'is not quote-ready or does not exist' end);

  elsif p_gate_id = 'GATE-012' then
    select count(*) into v_n from public.documents d
     where d.id::text = p_evidence->>'document_id'
       and coalesce(d.status,'') not in ('error','quarantined','rejected')
       and coalesce(d.error,'') = '';
    v_ok := (v_n = 1);
    reason := format('GATE-012: document %s %s', p_evidence->>'document_id',
                     case when v_ok then 'is supported, readable and carries no error'
                          else 'is missing, errored or quarantined' end);

  elsif p_gate_id = 'GATE-013' then
    v_ok := public.fn_kernel_reviewer_independent(
              coalesce(p_evidence->>'actor_role_id', 'unknown'),
              p_evidence->>'safe_package_approved_by');
    reason := format('GATE-013: package %s approved by %s; independence %s',
                     p_evidence->>'safe_package_ref', p_evidence->>'safe_package_approved_by',
                     case when v_ok then 'holds' else 'FAILS — the approver is the author' end);

  elsif p_gate_id = 'GATE-014' then
    select count(*) into v_n from public.leads l
     where l.id::text = p_evidence->>'supplier_id'
       and coalesce(l.approval_status,'') = 'approved' and coalesce(l.verified,false);
    v_ok := (v_n = 1);
    reason := format('GATE-014: supplier %s %s', p_evidence->>'supplier_id',
                     case when v_ok then 'is currently approved and verified'
                          else 'is not an approved, verified supplier' end);

  elsif p_gate_id = 'GATE-015' then
    select count(*) into v_n from public.inquiry_matches m
     where m.inquiry_id::text = p_evidence->>'inquiry_id'
       and m.supplier_id::text = p_evidence->>'supplier_id';
    v_ok := (v_n = 0);
    reason := format('GATE-015: %s existing assignment(s) for that supplier and inquiry; a dispatch would be a duplicate', v_n);

  elsif p_gate_id = 'GATE-016' then
    select count(*) into v_n from public.email_suppressions e
     where lower(e.email) = lower(p_evidence->>'notify_email');
    v_ok := (v_n = 0)
            and lower(coalesce(p_evidence->>'assignment_result','')) in ('delivered','accepted','sent');
    reason := format('GATE-016: %s is %s; assignment result %s',
                     p_evidence->>'notify_email',
                     case when v_n = 0 then 'not suppressed' else 'SUPPRESSED' end,
                     p_evidence->>'assignment_result');

  elsif p_gate_id = 'GATE-017' then
    select count(*) into v_n from public.quotes q
     where q.id::text = p_evidence->>'quote_id'
       and q.quote_amount is not null and coalesce(btrim(q.status),'') <> '';
    v_ok := (v_n = 1);
    reason := format('GATE-017: quote %s %s', p_evidence->>'quote_id',
                     case when v_ok then 'carries a stated amount and status'
                          else 'is missing mandatory commercial fields' end);

  elsif p_gate_id = 'GATE-018' then
    select count(*) into v_n from public.quote_comparisons qc
     where qc.id::text = p_evidence->>'comparison_id'
       and qc.customer_id::text = p_evidence->>'caller_customer_id';
    v_ok := (v_n = 1);
    reason := format('GATE-018: comparison %s %s the calling customer', p_evidence->>'comparison_id',
                     case when v_ok then 'belongs to' else 'does NOT belong to' end);

  elsif p_gate_id = 'GATE-019' then
    select rp.permitted, rp.reason into v_ok, v_txt
      from public.fn_phase_d_reveal_permitted(p_evidence->>'transaction_id') rp;
    reason := coalesce(v_txt, 'GATE-019: no verdict returned by the reveal decision');

  elsif p_gate_id = 'GATE-020' then
    select count(*) into v_n from public.refunds rf
     where rf.id::text = p_evidence->>'refund_id'
       and coalesce(btrim(rf.decided_by),'') <> '' and rf.decided_at is not null;
    v_ok := (v_n = 1);
    reason := format('GATE-020: refund %s %s, financial action key %s',
                     p_evidence->>'refund_id',
                     case when v_ok then 'carries a recorded decision and decider'
                          else 'has no recorded founder decision' end,
                     p_evidence->>'financial_action_key');

  elsif p_gate_id = 'GATE-021' then
    v_ok := public.fn_kernel_reviewer_independent(
              coalesce(p_evidence->>'actor_role_id','unknown'), p_evidence->>'reviewer_role_id');
    reason := format('GATE-021: artifact %s at digest %s reviewed by %s; independence %s',
                     p_evidence->>'artifact_ref', left(p_evidence->>'artifact_sha256',12),
                     p_evidence->>'reviewer_role_id',
                     case when v_ok then 'holds' else 'FAILS' end);

  elsif p_gate_id = 'GATE-031' then
    v_ok := not coalesce((public.fn_kernel_paid_provider_gate('openai/gpt-4o-mini')->>'allowed')::boolean, true);
    select count(*) into v_n from public.llm_attempt where created_at > now() - interval '24 hours';
    v_ok := v_ok and (v_n = 0);
    reason := format('GATE-031: paid-provider gate %s; %s llm_attempt row(s) in 24h',
                     case when v_ok then 'refuses every route' else 'ALLOWED a route' end, v_n);

  elsif p_gate_id = 'GATE-032' then
    select count(*) into v_n from cron.job where active;
    v_ok := (v_n <= 25);
    reason := format('GATE-032: %s active cron job(s) against the selective automation hold ceiling of 25', v_n);

  elsif p_gate_id in ('GATE-022','GATE-023','GATE-024','GATE-025','GATE-026','GATE-027',
                      'GATE-028','GATE-029','GATE-030') then
    v_ok := true;
    reason := format('%s (%s): all declared evidence is present and non-empty [%s]. '
                  || 'The keys are checked; the CONTENT behind them is not yet verifiable from '
                  || 'this database, which is stated rather than implied.',
                     g.gate_id, g.gate_name, array_to_string(c.evidence_keys, ', '));

  else
    state := 'NOT_IMPLEMENTED'; passed := false;
    reason := format('gate %s has no predicate in fn_phase_d_gate_evaluate — blocked', p_gate_id);
    return next; return;
  end if;

  state := case when v_ok then 'PASSED' else 'BLOCKED' end;
  passed := coalesce(v_ok, false);
  return next;
end

fn_phase_c_freeze_amendment_approver_gua:
begin
  -- An amendment awaiting approval is the normal state and is not this trigger's business. The
  -- board reports it; refusing it here would make an unapproved amendment unrecordable.
  if new.approved_by is null then
    return new;
  end if;

  if not exists (
        select 1 from public.phase_c_founder_identity fi
         where fi.active
           and lower(btrim(fi.identity)) = lower(btrim(new.approved_by))) then
    raise exception 'phase_c_freeze_amendment: approved_by % does not resolve to an active identity in public.phase_c_founder_identity. An amendment to a FROZEN Phase C contract is approved by the founder or it is not approved; a free-text name here cleared four of them and turned the freeze board green in one statement. (pccr_approver_not_the_founder)',
      coalesce(nullif(btrim(new.approved_by),''), '(empty)')
      using errcode = '23514';
  end if;

  return new;
end

fn_phase_c_founder_approver_guard:
begin
  if new.approved_by is null then
    return new;
  end if;

  if not exists (
        select 1 from public.phase_c_founder_identity fi
         where fi.active
           and lower(btrim(fi.identity)) = lower(btrim(new.approved_by))) then
    raise exception '%: approved_by % does not resolve to an active identity in public.phase_c_founder_identity. A governance record is approved by the founder or it is not approved. (pccr_approver_not_the_founder)',
      TG_TABLE_NAME, coalesce(nullif(btrim(new.approved_by),''), '(empty)')
      using errcode = '23514';
  end if;

  return new;
end

fn_phase_d_test_context_open:
declare
  v_op    text := nullif(btrim(coalesce(p_input->>'operation_key','')),'');
  v_label text := nullif(btrim(coalesce(p_input->>'label','')),'');
  v_id    bigint;
  v_tok   text;
begin
  if v_op is null or v_label is null then
    raise exception 'fn_phase_d_test_context_open: operation_key and label are both required (pd_test_context_input_invalid)'
      using errcode = '22023';
  end if;

  -- The frontend and an ordinary signed-in user are refused before anything else is read. This is
  -- the same refusal fn_phase_d_fixture_scenario already made; it is repeated here because this
  -- routine is now the only door and a door must carry its own lock.
  if current_user in ('anon','authenticated') then
    raise exception 'fn_phase_d_test_context_open: % may not open a Phase D test context (pd_test_context_untrusted_caller)',
      current_user using errcode = '42501';
  end if;

  if not exists (select 1 from public.phase_d_test_operation o
                  where o.operation_key = v_op and o.enabled) then
    raise exception 'fn_phase_d_test_context_open: % is not an enabled approved Phase D test operation. A service-role caller with no approved audit context may not build fixtures. (pd_test_context_operation_unapproved)',
      v_op using errcode = '42501';
  end if;

  insert into public.phase_d_test_context_grant
    (operation_key, label, txid, backend_pid, granted_to, session_user_name)
  values (v_op, v_label, txid_current(), pg_backend_pid(), current_user, session_user)
  returning fixture_run_id into v_id;

  -- BOUND TO THE TRANSACTION. A token minted here does not verify in any other transaction, so it
  -- cannot be lifted out of a log, a query plan or an error message and replayed.
  select encode(extensions.hmac(convert_to(format('%s:%s:%s', txid_current(), v_op, v_id),'UTF8'), s.secret, 'sha256'), 'hex')
    into v_tok from public.phase_d_fixture_secret s where s.singleton;

  perform set_config('app.phase_d_fixture_context', format('%s.%s', v_id, v_tok), true);

  return jsonb_build_object(
    'ok', true, 'fixture_run_id', v_id, 'operation_key', v_op, 'label', v_label,
    'txid', txid_current(),
    'note', 'transaction-local; abort this transaction when finished. The token is bound to this '
         || 'txid and to nothing else.');
end

fn_phase_d_fixture_context:
declare
  v_raw text := nullif(btrim(current_setting('app.phase_d_fixture_context', true)),'');
  v_id  bigint;
  v_tok text;
  v_exp text;
  g     public.phase_d_test_context_grant%rowtype;
begin
  if v_raw is null then return null; end if;
  begin
    v_id := nullif(split_part(v_raw, '.', 1),'')::bigint;
  exception when others then
    return null;
  end;
  v_tok := nullif(split_part(v_raw, '.', 2),'');
  if v_id is null or v_tok is null then return null; end if;

  select * into g from public.phase_d_test_context_grant where fixture_run_id = v_id;
  if not found then return null; end if;
  -- A grant is only a context inside the transaction it was minted in.
  if g.txid <> txid_current() then return null; end if;

  select encode(extensions.hmac(convert_to(format('%s:%s:%s', g.txid, g.operation_key, g.fixture_run_id),'UTF8'), s.secret, 'sha256'), 'hex')
    into v_exp from public.phase_d_fixture_secret s where s.singleton;

  if v_exp is null or v_exp <> v_tok then return null; end if;
  return v_id;
end

fn_phase_d_fixture_catalogue_checksum:
begin
  -- THE CHECKSUM IS COMPUTED, NEVER ACCEPTED. A caller-supplied checksum is a claim about a row.
  new.checksum := public.fn_phase_d_fixture_row_digest(new);
  return new;
end

fn_phase_d_capability_request_open:
declare
  sr  public.phase_c_workflow_step_run%rowtype;
  b   public.phase_d_handler_binding%rowtype;
  q   public.phase_d_capability_request%rowtype;
  v_step_run bigint := nullif(p_input->>'step_run_id','')::bigint;
  v_by       text   := nullif(btrim(coalesce(p_input->>'requested_by','')),'');
  v_id       bigint;
begin
  if v_step_run is null or v_by is null then
    raise exception 'fn_phase_d_capability_request_open: step_run_id and requested_by are required (pd_capability_request_invalid)'
      using errcode = '22023';
  end if;
  select * into sr from public.phase_c_workflow_step_run where step_run_id = v_step_run;
  if not found then
    raise exception 'fn_phase_d_capability_request_open: no step run % (pd_step_state_invalid)', v_step_run
      using errcode = '23503';
  end if;
  select * into b from public.phase_d_handler_binding where step_id = sr.step_id;
  if not found or b.capability_dependency = 'NONE' then
    raise exception 'fn_phase_d_capability_request_open: step % declares no capability dependency, so there is nothing to request (pd_capability_not_declared)',
      sr.step_id using errcode = '22023';
  end if;

  select * into q from public.phase_d_capability_request
   where step_run_id = v_step_run and capability = b.capability_dependency;
  if found then
    return jsonb_build_object('ok', true, 'replay', true, 'request_id', q.request_id,
                              'state', q.state, 'capability', q.capability);
  end if;

  insert into public.phase_d_capability_request
    (step_run_id, run_id, step_id, workflow_id, capability, requested_by, request_digest,
     fixture_run_id)
  values (v_step_run, sr.run_id, sr.step_id, b.workflow_id, b.capability_dependency, v_by,
          encode(sha256(convert_to(format('%s|%s|%s', sr.step_id, v_step_run,
                                          b.capability_dependency),'UTF8')),'hex'),
          public.fn_phase_d_fixture_context())
  returning request_id into v_id;

  return jsonb_build_object('ok', true, 'replay', false, 'request_id', v_id,
                            'state','open', 'capability', b.capability_dependency,
                            'note','a request is open; no provider is available in Phase D, so it '
                                || 'is answered by a Phase D fixture result or not at all');
end

fn_phase_d_capability_result_accept:
declare
  q    public.phase_d_capability_request%rowtype;
  c    public.phase_d_capability_contract%rowtype;
  ex   public.phase_d_capability_result%rowtype;
  v_req   bigint := nullif(p_input->>'request_id','')::bigint;
  v_mode  text   := lower(nullif(btrim(coalesce(p_input->>'provider_mode','')),''));
  v_pay   jsonb  := p_input->'payload';
  v_fid   text   := nullif(btrim(coalesce(p_input->>'fixture_id','')),'');
  v_fver  int    := nullif(p_input->>'fixture_version','')::int;
  v_by    text   := nullif(btrim(coalesce(p_input->>'accepted_by','')),'');
  v_run   bigint := public.fn_phase_d_fixture_context();
  v_cat   public.phase_d_fixture_catalogue%rowtype;
  v_k     text;
  v_want  text;
  v_got   text;
  v_miss  text[] := '{}';
  v_bad   text[] := '{}';
  v_id    bigint;
begin
  if v_req is null or v_mode is null or v_by is null then
    raise exception 'fn_phase_d_capability_result_accept: request_id, provider_mode and accepted_by are all required (pd_capability_result_invalid)'
      using errcode = '22023';
  end if;
  select * into q from public.phase_d_capability_request where request_id = v_req;
  if not found then
    raise exception 'fn_phase_d_capability_result_accept: no capability request % (pd_capability_request_absent)', v_req
      using errcode = '23503';
  end if;

  -- ---- idempotent replay: one result per request, and the first one stands -------------------
  select * into ex from public.phase_d_capability_result where request_id = v_req;
  if found then
    return jsonb_build_object('ok', true, 'replay', true, 'result_id', ex.result_id,
      'provider_mode', ex.provider_mode, 'payload_digest', ex.payload_digest,
      'note','this request already carries a result; no second result and no second effect');
  end if;

  -- ---- THE PROVIDER ARM IS REFUSED WHILE THE HOLD STANDS ------------------------------------
  -- It is written out rather than omitted so that the Phase E path is this path, and so that the
  -- refusal is a measured fact rather than the absence of code.
  if v_mode = 'provider' then
    raise exception 'fn_phase_d_capability_result_accept: a provider result cannot be accepted while the founder''s paid-inference hold stands (NO_PAID_AI=true, OPENROUTER_DISABLED=true, AI_PROVIDER_MODE=mock). No provider was called to produce this refusal. (pd_provider_disabled)'
      using errcode = '23514';
  end if;

  -- ---- THE FIXTURE ARM NEEDS A CONTEXT NO UNTRUSTED CALLER CAN MANUFACTURE --------------------
  if v_mode = 'fixture' then
    if v_run is null then
      raise exception 'fn_phase_d_capability_result_accept: a fixture capability result requires a verified Phase D fixture context. In production there is none, so a fixture result is refused before its payload is read. (pd_capability_fixture_context_absent)'
        using errcode = '42501';
    end if;
    if v_fid is null then
      raise exception 'fn_phase_d_capability_result_accept: a fixture result must name the committed catalogue row it came from (fixture_id) (pd_capability_fixture_unidentified)'
        using errcode = '22023';
    end if;
    select * into v_cat from public.phase_d_fixture_catalogue
     where fixture_id = v_fid and scope = 'CAPABILITY_RESULT';
    if not found then
      raise exception 'fn_phase_d_capability_result_accept: fixture % is not a CAPABILITY_RESULT row in the committed catalogue (pd_capability_fixture_unknown)',
        v_fid using errcode = '23503';
    end if;
    if v_fver is not null and v_fver <> v_cat.fixture_version then
      raise exception 'fn_phase_d_capability_result_accept: fixture % is version % in the committed catalogue and the call names version % (pd_capability_fixture_version_mismatch)',
        v_fid, v_cat.fixture_version, v_fver using errcode = '22023';
    end if;
    v_fver := v_cat.fixture_version;
    -- The payload is the catalogue's, merged over by nothing. A caller may not hand a fixture id
    -- and then a different payload: that would be an unmarked value wearing a marked label.
    v_pay := v_cat.value;
  end if;

  -- ---- OUTPUT VALIDATION, THE SAME FOR BOTH MODES -------------------------------------------
  select * into c from public.phase_d_capability_contract where step_id = q.step_id;
  if not found then
    raise exception 'fn_phase_d_capability_result_accept: step % has no capability contract, so no result can be validated against anything. Fail closed. (pd_capability_contract_absent)',
      q.step_id using errcode = '23503';
  end if;
  if v_pay is null or jsonb_typeof(v_pay) <> 'object' then
    raise exception 'fn_phase_d_capability_result_accept: the result payload for step % is not an object (pd_capability_result_malformed)',
      q.step_id using errcode = '22023';
  end if;
  foreach v_k in array c.required_keys loop
    if not (v_pay ? v_k) then
      v_miss := v_miss || v_k;
    else
      v_want := c.key_types->>v_k;
      v_got  := jsonb_typeof(v_pay->v_k);
      if v_want is not null and v_got <> v_want then
        v_bad := v_bad || format('%s is %s, contract says %s', v_k, v_got, v_want);
      end if;
    end if;
  end loop;
  if cardinality(v_miss) > 0 or cardinality(v_bad) > 0 then
    raise exception 'fn_phase_d_capability_result_accept: the result for step % does not satisfy its capability contract — missing [%], wrongly typed [%] (pd_capability_result_malformed)',
      q.step_id, array_to_string(v_miss, ', '), array_to_string(v_bad, ', ')
      using errcode = '22023';
  end if;
  -- provider_mode travels INSIDE the payload as well as beside it, and the two must agree, so a
  -- result cannot be re-labelled after acceptance by editing one of them.
  if lower(coalesce(v_pay->>'provider_mode','')) <> v_mode then
    raise exception 'fn_phase_d_capability_result_accept: the payload says provider_mode % and the call says %. A result that disagrees with itself about where it came from is refused. (pd_capability_result_malformed)',
      coalesce(v_pay->>'provider_mode','(absent)'), v_mode
      using errcode = '22023';
  end if;

  insert into public.phase_d_capability_result
    (request_id, provider_mode, fixture_id, fixture_version, fixture_hash, provider_event_ref,
     payload, payload_digest, trace_id, evidence, accepted_by, fixture_run_id)
  values (v_req, v_mode, v_fid, v_fver, v_cat.checksum, nullif(p_input->>'provider_event_ref',''),
          v_pay, encode(sha256(convert_to(v_pay::text,'UTF8')),'hex'),
          nullif(p_input->>'trace_id','')::bigint,
          format('capability %s for step %s answered in mode %s from %s; validated against '
              || 'phase_d_capability_contract keys [%s]; 0 paid inference requests were made to '
              || 'produce this result',
                 q.capability, q.step_id, v_mode,
                 coalesce(v_fid || ' v' || v_fver::text, coalesce(p_input->>'provider_event_ref','(unstated)')),
                 array_to_string(c.required_keys, ', ')),
          v_by, v_run)
  returning result_id into v_id;

  update public.phase_d_capability_request set state = 'answered' where request_id = v_req;

  return jsonb_build_object('ok', true, 'replay', false, 'result_id', v_id, 'request_id', v_req,
    'provider_mode', v_mode, 'fixture_id', v_fid, 'fixture_version', v_fver,
    'fixture_hash', v_cat.checksum,
    'payload_digest', encode(sha256(convert_to(v_pay::text,'UTF8')),'hex'));
end

fn_phase_d_fixture_effect_payload:
declare
  v_run bigint := public.fn_phase_d_fixture_context();
  sr    public.phase_c_workflow_step_run%rowtype;
  e     public.phase_d_step_effect%rowtype;
  v_rel text;
  v_out jsonb := '{}'::jsonb;
  r     record;
  fi    record;
  v_ctx_val jsonb;   -- G14: what the step context already resolved for this key
begin
  -- NO VERIFIED FIXTURE CONTEXT, NO CONTENT. In production this returns an empty object, the
  -- effect payload is exactly what it is today, and a NOT NULL column with no value still raises
  -- 23502 and is still classified pd_effect_payload_incomplete.
  if v_run is null then return '{}'::jsonb; end if;

  select * into sr from public.phase_c_workflow_step_run where step_run_id = p_step_run_id;
  if not found then return '{}'::jsonb; end if;
  select * into e from public.phase_d_step_effect where step_id = sr.step_id;
  if not found then return '{}'::jsonb; end if;

  select wm.target_relation into v_rel from public.phase_d_object_write_map wm
   where wm.object_id = e.effect_object_id;

  -- THE POPULATION IS THE COLUMNS THE TARGET RELATION ACTUALLY DEMANDS, read from the catalogue of
  -- the database rather than listed by hand. A column that is NOT NULL, has no default, is not
  -- generated, and is mapped by the object's write map to a payload key -- that is exactly the set
  -- fn_phase_d_effect_produce raises 23502 on today.
  if v_rel is not null and to_regclass(v_rel) is not null then
    for r in
      with m as (
        select k.col, k.key
          from public.phase_d_object_write_map wm,
               lateral jsonb_each_text(wm.column_map) k(col, key)
         where wm.object_id = e.effect_object_id)
      select m.key as src
        from m
        join pg_attribute a on a.attrelid = to_regclass(v_rel) and a.attname = m.col
        left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
       where a.attnum > 0 and a.attidentity = '' and a.attgenerated = ''
         and m.key not in ('business_key','owner_ref','state')
         and (   (a.attnotnull and d.adbin is null)
              -- H04 (3). A mapped column the committed catalogue speaks for, at this step or in
              -- this workflow. Scoped rows only: a global fixture fills nothing here.
              or exists (select 1 from public.phase_d_fixture_catalogue c
                          where c.scope = 'EFFECT_PAYLOAD' and c.field_key = m.key
                            and (c.step_id = sr.step_id
                                 or (c.step_id is null and c.workflow_id = e.workflow_id))))
    loop
      -- G14. A KEY THAT NAMES A ROW IS ANSWERED FROM THE ROW, NOT FROM A CONSTANT.
      -- Five of the sixteen keys in this population name something: inquiry_id, transaction_id,
      -- group_id, field_id, requested_by. fn_phase_d_step_context resolves an object key from the
      -- object it names, from a declared foreign key on the run's own relation, or from the
      -- canonical reference the scenario recorded -- so it is asked first, and the committed
      -- catalogue answers only what it could not. Handing a committed constant to a key that names
      -- a row is the mistake this estate has now corrected four times in one session.
      v_ctx_val := (public.fn_phase_d_step_context(p_step_run_id))->'context'->(r.src);
      if v_ctx_val is not null and v_ctx_val <> 'null'::jsonb then
        v_out := v_out || jsonb_build_object(r.src, v_ctx_val);
        continue;
      end if;
      -- H04 (1). A KEY THAT NAMES AN OBJECT IS ANSWERED FROM THE OBJECT THE SCENARIO CREATED, whether
      -- or not this step's rules declared the key. The register is public.phase_d_context_key_object;
      -- the identity is the canonical reference the scenario recorded for that object.
      select to_jsonb(sc.canonical_ref->>'canonical_identity') into v_ctx_val
        from public.phase_d_context_key_object cko
        join public.phase_d_scenario_record sc
          on sc.object_id = cko.object_id and sc.fixture_run_id = v_run
       where cko.context_key = r.src
         and coalesce(btrim(sc.canonical_ref->>'canonical_identity'),'') <> ''
       order by sc.scenario_record_id desc
       limit 1;
      if v_ctx_val is not null then
        v_out := v_out || jsonb_build_object(r.src, v_ctx_val);
        continue;
      end if;
      select * into fi from public.fn_phase_d_fixture_input(p_step_run_id, 'EFFECT_PAYLOAD', r.src) fi;
      if fi.value is not null then
        -- H04 (2). A CONSTANT CANNOT BE AN IDENTITY. Where this column belongs to a UNIQUE index of
        -- the target relation, the step run id is appended so each versioned row of one run is its
        -- own row and a replay of the same step run lands on the same value.
        if jsonb_typeof(fi.value) = 'string'
           and exists (select 1
                         from pg_index i
                         join pg_attribute a2 on a2.attrelid = i.indrelid and a2.attnum = any(i.indkey)
                        where i.indrelid = to_regclass(v_rel) and i.indisunique
                          and a2.attname = (select m2.col
                                              from public.phase_d_object_write_map wm2,
                                                   lateral jsonb_each_text(wm2.column_map) m2(col, key)
                                             where wm2.object_id = e.effect_object_id and m2.key = r.src
                                             limit 1)) then
          v_out := v_out || jsonb_build_object(r.src,
                     to_jsonb((fi.value #>> '{}') || '/' || sr.step_id || '/' || p_step_run_id::text));
        else
          v_out := v_out || jsonb_build_object(r.src, fi.value);
        end if;
      end if;
    end loop;
  end if;

  -- The three effect types that demand named keys of their own, whatever the relation is.
  if e.expected_effect_type = 'EXTERNAL_EFFECT_INTENT' then
    for r in select unnest(array['recipient','consent_basis']) src loop
      select * into fi from public.fn_phase_d_fixture_input(p_step_run_id, 'EFFECT_PAYLOAD', r.src) fi;
      if fi.value is not null then v_out := v_out || jsonb_build_object(r.src, fi.value); end if;
    end loop;
    v_out := v_out || jsonb_build_object('suppressed', true);
  elsif e.expected_effect_type = 'MEASUREMENT_RECORD' then
    for r in select unnest(array['numerator','denominator']) src loop
      select * into fi from public.fn_phase_d_fixture_input(p_step_run_id, 'CONTEXT_KEY', r.src) fi;
      if fi.value is not null then v_out := v_out || jsonb_build_object(r.src, fi.value); end if;
    end loop;
  elsif e.expected_effect_type = 'REVIEW_VERDICT' then
    select * into fi from public.fn_phase_d_fixture_input(p_step_run_id, 'EFFECT_PAYLOAD', 'verdict') fi;
    if fi.value is not null then v_out := v_out || jsonb_build_object('verdict', fi.value); end if;
  end if;

  return v_out;
end

fn_phase_c_founder_subject_bind:
declare v_id text; v_ev bigint;
begin
  if current_user in ('anon','authenticated') then
    raise exception 'fn_phase_c_founder_subject_bind: % may not bind a founder subject; this is the server path (pd_founder_bind_untrusted_caller)',
      current_user using errcode = '42501';
  end if;
  if p_subject is null then
    raise exception 'fn_phase_c_founder_subject_bind: a verified auth subject is required, and null is not one'
      using errcode = '28000';
  end if;

  select f.identity into v_id
    from public.phase_c_founder_identity f
   where f.auth_user_id = p_subject and f.active and f.kind = 'email';
  if v_id is null then
    raise exception 'not the founder: auth subject % does not resolve to an enabled founder identity', p_subject
      using errcode = '28000';
  end if;

  insert into public.phase_c_founder_auth_event
    (auth_subject, identity, route, txid, bound_by)
  values (p_subject, v_id, 'server_verified_subject', txid_current(), current_user)
  returning event_id into v_ev;

  perform set_config('app.phase_c_founder_auth_event', v_ev::text, true);
  return jsonb_build_object('ok', true, 'identity', v_id, 'event_id', v_ev,
    'note','transaction-local; the verifier requires this event to name the current txid');
end

fn_phase_d_ref_resolve:
declare
  s       public.phase_d_object_reference_strategy%rowtype;
  v_obj   text := nullif(btrim(coalesce(p_ref->>'object_id','')),'');
  -- F46. canonical_identity first: it is the one field that always holds the identity. The other
  -- two are read only for an envelope built before F46, and physical_ref.pk_value is deliberately
  -- LAST because for a PHASE_D_STORE object it is the physical row, not the identity.
  v_key   text := nullif(btrim(coalesce(p_ref->>'canonical_identity',
                                        p_ref->>'business_key',
                                        p_ref->'physical_ref'->>'pk_value','')),'');
  v_ver   int  := nullif(btrim(coalesce(p_ref->>'version','')),'')::int;
  v_n     int;
  v_rec   record;
  v_sql   text;
begin
  if v_obj is null or v_key is null then
    raise exception 'fn_phase_d_ref_resolve: a reference must name an object_id and an identity; got % / % (pd_ref_unresolved)',
      coalesce(v_obj,'(none)'), coalesce(v_key,'(none)') using errcode = '22023';
  end if;

  select * into s from public.phase_d_object_reference_strategy where object_id = v_obj;
  if not found then
    raise exception 'fn_phase_d_ref_resolve: % is not one of the 56 frozen business objects (pd_ref_unknown_object)',
      v_obj using errcode = '23503';
  end if;

  if s.storage_kind = 'PHASE_D_STORE' then
    -- THE VERSION IS PART OF THE IDENTITY. With no version the live one is the record that has not
    -- been superseded; with a version it is that version exactly, superseded or not, because
    -- evidence about what was approved must stay readable after a later revision.
    if v_ver is null then
      select count(*) into v_n from public.phase_d_object_record
       where object_id = v_obj and business_key = v_key and superseded_by is null;
    else
      select count(*) into v_n from public.phase_d_object_record
       where object_id = v_obj and business_key = v_key and version = v_ver;
    end if;

    if v_n = 0 then
      raise exception 'fn_phase_d_ref_resolve: % / % %resolves to no record in public.phase_d_object_record (pd_ref_unresolved)',
        v_obj, v_key, case when v_ver is null then '' else 'version ' || v_ver || ' ' end
        using errcode = '23503';
    elsif v_n > 1 then
      raise exception 'fn_phase_d_ref_resolve: % / % %resolves to % records; a reference must name exactly one (pd_ref_ambiguous)',
        v_obj, v_key, case when v_ver is null then '' else 'version ' || v_ver || ' ' end, v_n
        using errcode = '23505';
    end if;

    if v_ver is null then
      select record_id, business_key, version, state, owner_scope, owner_ref, trace_id
        into v_rec from public.phase_d_object_record
       where object_id = v_obj and business_key = v_key and superseded_by is null;
    else
      select record_id, business_key, version, state, owner_scope, owner_ref, trace_id
        into v_rec from public.phase_d_object_record
       where object_id = v_obj and business_key = v_key and version = v_ver;
    end if;

    return jsonb_build_object(
      'ok', true, 'object_id', v_obj, 'storage_kind', s.storage_kind,
      'canonical_identity', v_rec.business_key,
      'business_key', v_rec.business_key, 'version', v_rec.version, 'state', v_rec.state,
      'owner_scope', v_rec.owner_scope, 'owner_ref', v_rec.owner_ref,
      'trace_id', v_rec.trace_id,
      'physical_ref', jsonb_build_object('schema','public','relation','phase_d_object_record',
                                         'pk_column','record_id','pk_value', v_rec.record_id::text));
  end if;

  -- EXISTING_TABLE and KERNEL_OWNED: the relation's own primary key, compared as text so a uuid, a
  -- bigint and a natural key all work without the caller having to know which it is.
  v_sql := format('select count(*) from %I.%I where %I::text = $1',
                  s.physical_schema, s.physical_relation, s.physical_pk_column);
  execute v_sql into v_n using v_key;

  if v_n = 0 then
    raise exception 'fn_phase_d_ref_resolve: % / % resolves to no row in %.% by % (pd_ref_unresolved)',
      v_obj, v_key, s.physical_schema, s.physical_relation, s.physical_pk_column
      using errcode = '23503';
  elsif v_n > 1 then
    raise exception 'fn_phase_d_ref_resolve: % / % resolves to % rows in %.%; a reference must name exactly one (pd_ref_ambiguous)',
      v_obj, v_key, v_n, s.physical_schema, s.physical_relation
      using errcode = '23505';
  end if;

  return jsonb_build_object(
    'ok', true, 'object_id', v_obj, 'storage_kind', s.storage_kind,
    'canonical_identity', v_key,
    'business_key', v_key, 'version', coalesce(v_ver, 1),
    'physical_ref', jsonb_build_object('schema', s.physical_schema, 'relation', s.physical_relation,
                                       'pk_column', s.physical_pk_column, 'pk_value', v_key));
end

fn_phase_c_freeze_amendment_approve:
declare
  a          public.phase_c_freeze_amendment%rowtype;
  v_identity text;
  v_sub      uuid;
  v_route    text;
  v_ev       bigint;
  v_id       bigint;
  v_prior    text;
begin
  -- THE DOOR. Nothing below runs without a verified founder on this transaction: the resolver
  -- raises 28000 for a service_role connection, for a typed email, and for a bound event that
  -- belongs to some other transaction.
  v_identity := public.fn_phase_c_require_founder(null);

  -- Which route carried it. Re-derived here rather than returned by the resolver, because the row
  -- must record HOW the founder was authenticated and not merely that something said he was.
  begin v_sub := auth.uid(); exception when others then v_sub := null; end;
  if v_sub is not null then
    v_route := 'auth.uid()';
  else
    v_ev := nullif(btrim(current_setting('app.phase_c_founder_auth_event', true)),'')::bigint;
    select e.auth_subject into v_sub from public.phase_c_founder_auth_event e
     where e.event_id = v_ev and e.txid = txid_current();
    v_route := 'fn_phase_c_founder_subject_bind';
  end if;
  if v_sub is null then
    raise exception 'fn_phase_c_freeze_amendment_approve: the founder resolved to % and no auth subject can be named for the call. An approval that cannot say who authenticated is not a session approval. (pccr_approval_subject_unnameable)',
      v_identity using errcode = '28000';
  end if;

  -- ONE AMENDMENT PER CALL. The founder's instruction is that these are approved individually.
  if p_input ?| array['amendment_ids','amendments','change_request_refs'] then
    raise exception 'fn_phase_c_freeze_amendment_approve: this routine approves exactly one amendment per call. Bundling is what the founder refused: "Do not combine or rewrite the amendments." (pccr_approval_bundled)'
      using errcode = '22023';
  end if;
  v_id := nullif(btrim(coalesce(p_input->>'amendment_id','')),'')::bigint;
  if v_id is null then
    raise exception 'fn_phase_c_freeze_amendment_approve: amendment_id is required (pccr_approval_no_amendment)'
      using errcode = '22023';
  end if;

  select * into a from public.phase_c_freeze_amendment where amendment_id = v_id;
  if not found then
    raise exception 'fn_phase_c_freeze_amendment_approve: no amendment % (pccr_approval_unknown_amendment)', v_id
      using errcode = '23503';
  end if;

  -- THE APPROVAL NAMES WHAT IT APPROVES. A mistyped id lands on a different amendment silently
  -- unless the call also restates the change request, the subject and the digest being adopted.
  if coalesce(nullif(btrim(p_input->>'change_request_ref'),''),'') is distinct from a.change_request_ref
     or coalesce(nullif(btrim(p_input->>'subject'),''),'')          is distinct from a.subject
     or coalesce(nullif(btrim(p_input->>'new_digest'),''),'')       is distinct from a.new_digest then
    raise exception 'fn_phase_c_freeze_amendment_approve: amendment % is (%, %, new_digest %) and the call names (%, %, %). An approval must name the exact amendment it approves. (pccr_approval_names_a_different_amendment)',
      v_id, a.change_request_ref, a.subject, a.new_digest,
      coalesce(p_input->>'change_request_ref','(none)'), coalesce(p_input->>'subject','(none)'),
      coalesce(p_input->>'new_digest','(none)') using errcode = '22023';
  end if;

  if coalesce(p_input->>'amendment_table_digest','') !~ '^[0-9a-f]{64}$' then
    raise exception 'fn_phase_c_freeze_amendment_approve: amendment_table_digest must be the sha256 of the amendment tables the approval is based on; got %. (pccr_approval_no_document_digest)',
      coalesce(nullif(p_input->>'amendment_table_digest',''),'(none)') using errcode = '22023';
  end if;

  if (p_input->>'deployed_before_approval') is null then
    raise exception 'fn_phase_c_freeze_amendment_approve: deployed_before_approval must be stated true or false. Whether the code was already live when it was approved is a fact about this approval, not a detail to leave blank. (pccr_approval_deployment_order_unstated)'
      using errcode = '22023';
  end if;
  if (p_input->>'deployed_before_approval')::boolean
     and nullif(btrim(p_input->>'original_deployment_at'),'') is null then
    raise exception 'fn_phase_c_freeze_amendment_approve: amendment % is recorded as deployed before approval and the call names no original_deployment_at. A retrospective ratification that cannot say when the code shipped is not a record of anything. (pccr_approval_deployment_time_missing)',
      v_id using errcode = '22023';
  end if;

  -- ALREADY APPROVED THROUGH THIS DOOR: idempotent, and it does not restamp the time.
  if a.approval_basis = 'AUTHENTICATED_FOUNDER_SESSION' then
    if lower(a.approved_by) is distinct from lower(v_identity) then
      raise exception 'fn_phase_c_freeze_amendment_approve: amendment % is already approved in a verified session by % and % may not overwrite that record. (pccr_approval_would_overwrite_another_founder)',
        v_id, a.approved_by, v_identity using errcode = '23514';
    end if;
    return jsonb_build_object('ok', true, 'amendment_id', v_id, 'outcome','ALREADY_APPROVED',
      'approved_by', a.approved_by, 'approved_at', a.approved_at, 'approval_basis', a.approval_basis,
      'note','this door is idempotent and does not restamp an approval it has already recorded');
  end if;

  v_prior := coalesce(a.approval_basis, '(unapproved)');

  update public.phase_c_freeze_amendment
     set approved_by                      = v_identity,     -- THE VERIFIED IDENTITY, never the input
         approved_at                      = now(),
         approval_basis                   = 'AUTHENTICATED_FOUNDER_SESSION',
         approval_route                   = v_route,
         approval_auth_subject            = v_sub,
         approved_amendment_table_digest  = lower(btrim(p_input->>'amendment_table_digest')),
         deployed_before_approval         = (p_input->>'deployed_before_approval')::boolean,
         original_deployment_at           = nullif(btrim(p_input->>'original_deployment_at'),'')::timestamptz
   where amendment_id = v_id;

  return jsonb_build_object(
    'ok', true, 'amendment_id', v_id,
    'outcome', case when v_prior = 'WRITTEN_INSTRUCTION' then 'REAFFIRMED_IN_VERIFIED_SESSION'
                    else 'APPROVED_IN_VERIFIED_SESSION' end,
    'prior_approval_basis', v_prior,
    'change_request_ref', a.change_request_ref, 'subject', a.subject,
    'approved_by', v_identity, 'approval_route', v_route, 'approval_auth_subject', v_sub,
    'approval_type', case when (p_input->>'deployed_before_approval')::boolean
                          then 'retrospective founder ratification' else 'prospective approval' end,
    'original_deployment_at', nullif(btrim(p_input->>'original_deployment_at'),'')::timestamptz,
    'amendment_table_digest', lower(btrim(p_input->>'amendment_table_digest')));
end

fn_phase_d_catalogue_payment_state_decla:
begin
  -- Only the key that names a monetary state. Every other fixture is untouched.
  if NEW.field_key = 'monetary_state'
     and not exists (select 1 from public.phase_d_payment_state s
                      where s.state_key = (NEW.value #>> '{}')) then
    raise exception 'phase_d_fixture_catalogue: % commits monetary_state %, which is not a rung of public.phase_d_payment_state. BR-020 and BR-033 both read that ladder; a money state outside it is not a state. (pd_catalogue_payment_state_undeclared)',
      NEW.fixture_id, coalesce(NEW.value #>> '{}', '(null)') using errcode = '23514';
  end if;
  return NEW;
end

fn_phase_d_stage_content:
declare
  v_wf  text;
  v_n   int;
  v_val text;
begin
  select b.governing_workflow_id into v_wf
    from public.phase_d_business_object_binding b where b.object_id = p_object_id;

  -- The fixture written FOR this object's workflow, if there is one.
  select count(*), min(c.value #>> '{}') into v_n, v_val
    from public.phase_d_fixture_catalogue c
   where c.scope = p_scope and c.field_key = p_key
     and c.workflow_id is not null
     and (c.workflow_id = v_wf or v_wf like '%' || c.workflow_id || '%');
  if v_n = 1 then return v_val; end if;
  if v_n > 1 then
    raise exception 'fn_phase_d_stage_content: % fixtures at scope % for key % are scoped to the workflow of %. Refusing to choose one. (pd_fixture_ambiguous_content)',
      v_n, p_scope, p_key, p_object_id using errcode = '21000';
  end if;

  -- Otherwise the unscoped one, and there must be exactly one of those too.
  select count(*), min(c.value #>> '{}') into v_n, v_val
    from public.phase_d_fixture_catalogue c
   where c.scope = p_scope and c.field_key = p_key and c.workflow_id is null;
  if v_n > 1 then
    raise exception 'fn_phase_d_stage_content: % unscoped fixtures at scope % for key %. Refusing to choose one; scope them to the workflow they were written for. (pd_fixture_ambiguous_content)',
      v_n, p_scope, p_key using errcode = '21000';
  end if;
  return v_val;   -- null when nothing is committed, which the caller's own NOT NULL will report
end

fn_phase_d_founder_authority:
declare
  v_wf       text;
  v_cmd      bigint;
  v_state    text;
  v_reserved text;
  v_digest   text;
  v_baseline text;
  v_covers   boolean;
  v_exists   boolean;
  v_current  boolean;
begin
  select s.workflow_id into v_wf from public.phase_b_workflow_step s where s.step_id = p_step_id;
  if v_wf is null then
    return jsonb_build_object('ref', null, 'kind', 'UNKNOWN_STEP',
      'exists', false, 'current', false, 'covers', false, 'valid', false,
      'why', format('%s is not a step of the frozen registry', coalesce(p_step_id, '(null)')));
  end if;

  -- WHAT THE FOUNDER RESERVED, read from the register he approved. Never a list in this body.
  select string_agg(b.boundary_id, ';' order by b.boundary_id) into v_reserved
    from public.phase_b_founder_boundary b
   where v_wf = any (string_to_array(replace(b.workflow_scope, ' ', ''), ';'));

  -- 1. A FOUNDER COMMAND, where one instructed this run.
  select l.command_id into v_cmd from public.founder_command_workflow_link l
   where l.run_id = p_run_id limit 1;
  if v_cmd is null then
    select r.command_id into v_cmd from public.phase_c_workflow_run r where r.run_id = p_run_id;
  end if;

  if v_cmd is not null then
    select fc.state into v_state from public.founder_command fc where fc.command_id = v_cmd;
    v_exists  := v_state is not null;
    v_current := v_exists and v_state <> 'cancelled';
    v_covers  := exists (select 1 from public.founder_command_workflow_link l2
                          where l2.command_id = v_cmd and l2.workflow_id = v_wf)
              or exists (select 1 from public.phase_c_workflow_run r2
                          where r2.run_id = p_run_id and r2.command_id = v_cmd);
    return jsonb_build_object(
      'ref',     'founder_command:' || v_cmd::text,
      'kind',    'FOUNDER_COMMAND',
      'source',  'founder_command that started this run',
      'artefact','public.founder_command',
      'reserved_by', v_reserved,
      'exists',  v_exists, 'current', v_current, 'covers', v_covers,
      'valid',   v_exists and v_current and v_covers,
      'why', format('founder command %s is %s and %s workflow %s', v_cmd,
                    case when not v_exists then 'not on record'
                         when v_current then 'live (state ' || v_state || ')'
                         else 'cancelled' end,
                    case when v_covers then 'selected' else 'DID NOT select' end, v_wf));
  end if;

  -- 2. DELEGATED AUTHORITY, read off the founder-approved frozen boundary register.
  select d.sha256 into v_digest
    from public.fn_phase_b_structure_digest() d where d.subject = 'founder_boundaries';
  select bl.registry_sha256->'structure'->'founder_boundaries'->>'database' into v_baseline
    from public.org_phase_baseline bl where bl.phase = 'B';

  v_exists  := v_digest is not null
               and exists (select 1 from public.phase_b_founder_boundary)
               and v_baseline is not null;
  v_current := v_exists and v_digest = v_baseline;
  v_covers  := v_reserved is null;

  if not v_covers then
    return jsonb_build_object(
      'ref', null, 'kind', 'FOUNDER_RESERVED',
      'source', 'public.phase_b_founder_boundary',
      'artefact', 'public.phase_b_founder_boundary@' || coalesce(left(v_digest, 16), '(none)'),
      'reserved_by', v_reserved,
      'exists', v_exists, 'current', v_current, 'covers', false, 'valid', false,
      'why', format('%s is reserved to the founder by %s and no founder command instructed this run',
                    v_wf, v_reserved));
  end if;

  return jsonb_build_object(
    'ref',     'founder_policy:phase_b_founder_boundary@' || coalesce(left(v_digest, 16), 'unknown'),
    'kind',    'DELEGATED_AUTHORITY',
    'source',  'public.phase_b_founder_boundary, the founder-approved frozen register of what he '
            || 'reserves: it names no boundary over ' || v_wf || ', so the decision is delegated '
            || 'to the step''s accountable role',
    'artefact','public.phase_b_founder_boundary@' || coalesce(left(v_digest, 16), 'unknown'),
    'reserved_by', null,
    'exists',  v_exists, 'current', v_current, 'covers', true,
    'valid',   v_exists and v_current,
    'why', format('the founder-approved boundary register (%s rows, digest %s) %s the Phase B '
               || 'baseline and reserves no decision in %s',
                  (select count(*) from public.phase_b_founder_boundary),
                  coalesce(left(v_digest, 16), '(none)'),
                  case when v_current then 'matches' else 'DOES NOT match' end, v_wf));
end
